  INSERT INTO kb_sources (id, title, author, file_name, file_hash)
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, '(ميقلا نبال داعملا داز باتك نم ءزج) يوبنلا بطلا :باتكلا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'توريب - لالهلا راد :رشانلا (ـه157 :ىفوتملا) ةيزوجلا ميق نبا نيدلا سمش دعس نب بويأ نب ركب يبأ نب دمحم :فلؤملا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '- :ةعبطلا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '7 :ءازجألا ددع', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, ']عوبطملل قفاوم باتكلا ميقرت[', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '[مقدمة المحقق]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'بِسْمِ ا هلِلَّ الهرحْنِْ الهرحِيمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الحمد لله الذي فتح أبواب الخير بما فتح على العالمين من أبواب السنة، وهدى الناس إلى الصراط المستقيم بكلام نبيه محمد سيد الأولين والآخرين. اللهم صل على سيدنا محمد وعلى آله وعلى من سار على هديه وأخذ نفسه بسنته والتزم طريقته وعلى أصحابه الأجلة ومن تبعهم بإحسان أما بعد فهذه تعليقات مختصرة تتعلق بتخريج أحاديث شريفة استشهد بها شمس الدين محمد بن أبي بكر أيوب الزرعي الدمشقي ابن قيم الجوزية في كتابه الطب النبوي الذي لا تخفى قيمته، ولا يخفت نوره، ولا تبيده فوائده. والمؤلف يعرفه القاصي والداني، ولا تغيب شمسه عن كل من أخذ قلما وطرسا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'ولد رحهْ الله بدمشق سنة إحدى وتسعين وستمائة 197) هـ( ونشأ على العلم والفهم والصلاح والتقوى والجد والدأب والبحث.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وكتابه الطب النبوي جزء من كتابه «زاد المعاد بهدى خير العباد» غير أن الطب النبوي فيه ذو قيمة مستقلة، وبحوث قيمة، في علم مستقل يتخصص الباحثون فيه اليوم، بل يتخصصون في كل جزء من أجزائه، ففي طب القلب مختصون، وفي جهاز الهضم مختصون وهكذا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'فرأى الكثير من الباحثين إفراد هذا الجزء المتعلق بالطب عن بقية أجزاء الكتاب، وأن يطبع مستقلا فكان في ذلك النفع العظيم، والفوائد الجمة، فطبع طبعات مختلفة كثيرة وكلها راجت وفقدت، مما يدل على أن المسلمين يحبون الاستشفاء بشفاء رسول الله هللا ىلص، ويحبون أن يقرؤا وأن يطلبوا على هذا النموذج العظيم سواء تعلقه بطب علاجي حسي، أو تعلقه بطب معنوي من آيات أو أحاديث أو تعوذات أو تعويذات أو أدعية.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'والشيخ رحهْ الله حجة في كل ما ينقل، وما أخذ إلا ويرى للشيخ الفضل عليه ولكن تخريج الأحاديث شيء درج عليه، وفيه النفع الكثير وبه تطمئن القلوب لصحة الحديث إذا كان صحيحا، ويعرف من هو الذي خرجه ورواه والمؤلف رحهْ الله أراد أن يبين في كتابه هذا أن سيدنا محمد هللا ىلص شفاء لما في الصدور بهذا الإيمان، فهذا الإسلام وهذه السنة، هو شفاء لهذه الجسوم أيضا بما أوتي من معرفة طبية، وأن الله سبحانه قد علمه الطبين الروحي والجسمي، فكان هداية من كل نواحي الهداية، وكان رحةْ للعالمين من وجه، وإن كان إنما بعث للشفاء الروحي بهذا القرآن العظيم وهذه السنة المطهرة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'توفي رحهْ الله سنة إحدى وخمسين وسبعمائة 157) هـ( عن عمر بلغ ستين سنة ولكنه عاش وما زال يعيش طيلة الدهر بهذه المؤلفات التي نشر الله له فيها ذكرا ونرجوا أن يضاعف له فيها أجرا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'دمشق في /7 /2 7993 محمد كريم راجح', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'عفا الله عنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'الطبّ النّبويّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'فصول نافعة فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي الطِّبِّ الهذِي تَطَبهبَ بِهِ وَوَصَفَهُ لِغَيِْرهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَنُـبَـيُِّن مَا فِيهِ مِنَ الِْحكْمَةِ الهتِي تَـعْجِزُ عُقُولُ أَكْثَرِ الَْأطِبهاءِ عَنِ الْوُصُولِ إِلَيْـهَا، وَأَنه نِسْبَةَ طِبِّهِمْ إِلَيْـهَا كَنِسْبَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'طِبِّ الْعَجَائِزِ إِلَى طِبِّهِمْ فَـنَـقُولُ وَبَِالِِّلَّ الْمُسْتَـعَانُ وَمِنْهُ نَسْتَمِدُّ الَْحوْلَ وَالْقُهوةَ: الْمَرَضُ : نَـوْعَانِ مَرَضُ الْقُلُوبِ، وَمَرَضُ الَْأبَدَانِ، وَهُاَُ مَذْكُورَانِ فِي الْقُرْآنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَمَرَضُ الْقُلُوبِ: نَـوْعَانِ: مَرَضُ شُبْـهَةٍ وَشَكٍّ ، وَمَرَضُ شَهْوَةٍ وَغَيٍّ، وَكِلَاهُاَُ فِي الْقُرْآنِ. قَالَ تَـعَالَى فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'مَرَضِ الشُّبْـهَةِ: فِي قُـلُوبِِهمْ مَرَضٌ فَزادَهُمُ ا هللَُّ مَرَضاً »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَقَالَ تَـعَالَى: وَلِيَـقُولَ الهذِينَ فِي قُـلُوبِِهمْ مَرَضٌ وَالْكافِرُونَ ماذا أَرادَ ا هللَُّ بِهذا مَثَلًا »2« وَقَالَ تَـعَالَى فِي حَقِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'مَنْ دُعِيَ إِلَى تَكَِْيمِ الْقُرْآنِ وَالسُّنهةِ، فَأَبََ وَأَعْرَضَ :', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'وَإِذا دُعُوا إِلَى ا هلِلَّ وَرَسُولِهِ لِيَحْكُمَ بَـيْـنَـهُمْ إِذا فَرِيقٌ مِنْـهُمْ مُعْرِضُونَ، وَإِنْ يَكُنْ لَهمُُ الَْحقُّ تََُْوا إِلَيْهِ مُذْعِنِيَن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'أَفِي قُـلُوبِِهمْ مَرَضٌ أَمِ ارْتابُوا، أَمْ يَخافُونَ أَنْ يَِحيفَ ا هللَُّ عَلَيْهِمْ وَرَسُولُهُ بَلْ أُولئِكَ هُمُ ال هظالِمُونَ »3« ، فهذا مرض الشبهات والشكوك.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, '(7) البقرة- -71 والمعنى أن قلوبهم ضعيفة بما فيها من الشك والنفاق فزادها الله ضعيفة بما انزل من القرآن. قَالَ تَـعَالَى وَنُـنَـزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفاءٌ وَرَحْةٌَْ لِلْمُؤْمِنِيَن وَلا يَزِيدُ الظهالِمِيَن إِهلا خَساراً.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, '(2) المدثر- -37 والمعنى أنا جعلنا الموكلين على النار ملائكة وجعلنا عدتهم تسعة عشر ليستيقن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'الذين اوتوا الكتاب ويزداد الذين آمنوا إيمانا ولكي لا تقع الريبة في قلوب الذين أوتوا الكتاب وفي قلوب المؤمنين، وليقول الكفرة والمنافقون من ذوي أمراض القلوب معترضين: ماذا أراد الله بهذا مثلا؟ وسموه مثلا لغرابته.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, '(3) النور- -49 -49 51 والمعنى وإذا دعي المنافقون مرض القلوب إلى كتاب ليحكم هم رسول الله بما فيه من الاحكام بدا ما يخفون في قلوبهم من كذب وشك، وظهر ذلك على وجوههم وألسنتهم، فإذا هم يعرضون عن الحكم لكتاب الله، وعن المجيء إلى رسول الله هللا ىلص، وذلك أنهم يعلمون أن الحكم في الاسلام', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'وأما مرض الشهوات، فقال تعالى يا نِساءَ النهبِِّ لَسْ هُتُ كَأَحَدٍ مِنَ النِّساءِ إِنِ اتهـقَيْـ هُتُ فَلا تَْخضَعْنَ بِالْقَوْلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'فَـيَطْمَعَ اهلذِي فِي قَـلْبِهِ مَرَضٌ »7« . فَـهَذَا مَرَضُ شَهْوَةِ الزِّنََ، وَا هللَُّ أَعْلَمُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَمها مَرَضُ الَْأبَدَانِ، فَـقَالَ تَـعَالَى لَيْسَ عَلَى الَْأعْمى حَرَجٌ وَلا عَلَى الَْأعْرَجِ حَرَجٌ وَلا عَلَى الْمَرِيضِ حَرَجٌ »2« . وَذكََرَ مَرَضَ الْبَدَنِ فِي الَْحجِّ وَالصهوْمِ وَالْوُضُوءِ لِسِرٍّ بَدِيعٍ يُـبَـيُِّن لَكَ عَظَمَةَ الْقُرْآنِ، وَالِاسْتِغْنَاءَ بِهِ لِمَنْ فَهِمَهُ وَعَقَلَهُ عَنْ سِوَاهُ، وَذَلِكَ أَنه قَـوَاعِدَ طِبِّ الَْأبْدَانِ ثَلَاثَةٌ حِفْظُ الصِّحهةِ، وَالِْحمْيَةُ عَنِ الْمُؤْذِي، وَاسْتِفْرَاغُ الْمَوَادِّ الْفَاسِدَةِ، فَذَكَرَ سُبْحَانَهُ هَذِهِ الُْأصُولَ الثهلَاثَةَ فِي هَذِهِ الْمَوَاضِعِ الثهلَاثَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'فَـقَالَ فِي آيَةِ الصهوْمِ: فَمَنْ كانَ مِنْكُمْ مَرِيضاً أَوْ عَلى سَفَرٍ فَعِدهةٌ مِنْ أَهيامٍ أُخَرَ »3« ، فَأَبَاحَ الْفِطْرَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'لِلْمَرِيضِ لِعُذْرِ الْمَرَضِ ، وَلِلْمُسَافِرِ طَلَبًا لِِحفْظِ صِحهتِهِ وَقُـهوتِهِ لِئَهلا يُذْهِبَـهَا الصهوْمُ فِي السهفَرِ لِاجْ تِمَاعِ شِدهةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الَْحرَكَةِ، وَمَا يُوجِبُهُ مِنَ التهحْلِيلِ، وَعَدَمِ الْغِذَاءِ الهذِي يُْخلِفُ مَا تَلََهلَ فَـتَخُورُ الْقُهوةُ، وَتَضْعُفُ ، فَأَبَاحَ لِلْمُسَافِرِ الْفِطْرَ حِفْظًا لِصِحهتِهِ وَقُـهوتِهِ عَمها يُضْعِفُهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَقَالَ فِي آيَةِ الَْحجِّ فَمَنْ كانَ مِنْكُمْ مَرِيضاً أَوْ بِهِ أَذىً مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'لا رشوة فيه ولا تدجيل، وأنه يتبع الحق، لذلك إذا كانوا مبطلين أعرضوا عن كتاب الله، وإذا كانوا ذوي حق رضوا بالتحاكم إليه لأنهم يعرفون حق المعرفة أنه سينصفهم، لأنه لا معدل فيه عن الحق. فهل في قلوبهم مرض أم هم مرتابون في الحكم، أم يخافون ألاينصفهم القرآن؟ لا إنهم يعرفون الحقيقة ولكنهم هم الظالمون.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '(7) الأحزاب- -32 هذا نداء لنساء النب هللا ىلص لما شرفهن الله سبحانه بأنهن أمهات المؤمنين، وبأنهن قدوة النساء الآخريات ولسن كبقية النساء فعليهن أن يكن في غاية التقوى والصلاح وحسن الأسوة والقدوة، فمن التقوى ألايلنّ في الأقوال إذا اضطررن أن يخاطبن الرجال الأجانب، بل عليهن أن يكون كلامهن من غير خضوع ولا لين، فذلك أقرب إلى مركزهن ويتناسب مع قيمتهن وحتى لا يطمع الرجال الذين في قلوبهم أغراض سافلة غير رفيعة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(2) النور- -17 الفتح- -71 هؤلاء ذو والعلل معذورون في ترك الجهاد، فليس عليهم إ م إذا حضر الجهاد أن لا يجاهدوا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, '(3) البقرة- .794', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'صِيامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ »7« ، فَأَبَاحَ لِلْمَرِيضِ ، وَمَنْ بِهِ أَذًى مِنْ رَأْسِهِ، من قمل، أَوْ غَيِْرهِاَُ، أَنْ يَْحلِقَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'رَأْسَهُ فِي الِْإحْ رَامِ اسْتِفْرَاغًا لِمَادهةِ الَْأخِْرَِةِ الهردِيئَةِ الهتِي أَوْجَبَتْ لَهُ الَْأذَى فِي رَأْسِهِ بِاحْ تِقَانَِها تَتََْ الشهعْرِ، فَإِذَا حَلَقَ رَأْسَهُ تَـفَتهحَتِ الْمَسَامُّ، فَخَرَجَتْ تِلْكَ الَْأخِْرَِةُ مِنْـهَا، فَـهَذَا الِاسْتِفْرَاغُ يُـقَاسُ عَلَيْهِ كُلُّ اسْتِفْرَاغٍ يُـؤْذِي انِْبَْاسُهُ، وَالَْأشْيَاءُ الهتِي يُـؤْذِي انِْبَْاسُهَا وَمُدَافَـعَتُـهَا عَشَرَةٌ: الدهمُ إِذَا هَاجَ، وَالْمَنُِِّ إِذَا تَـبَـيهغَ، وَالْبَـوْلُ، وَالْغَائِطُ، وَالرِّيحُ، وَالْقَيْ ءُ، وَالْعُطَاسُ ، وَالنهـوْمُ، وَالُْجوعُ، وَالْعَطَشُ. وَكُلُّ وَاحِدٍ مِنْ هَذِهِ الْعَشَرَةِ يُوجِبُ حَبْسُهُ دَاءً مِنَ الَْأدْوَاءِ بَِحسْبِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَقَدْ نَـبههَ سُبْحَانَهُ بِاسْتِفْرَاغِ أَدْنَاهَا، وَهُوَ الْبُخَارُ الْمُحْ تَـقَنُ فِي الهرأْسِ عَلَى اسْتِفْرَاغِ مَا هُوَ أَصْعَبُ مِنْهُ، كَمَا هِيَ طَرِيقَةُ الْقُرْآنِ التهـنْبِيهُ بِالَْأدْنََ عَلَى الَْأعْلَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَأَمها الِْحمْيَةُ: فَـقَالَ تَـعَالَى فِي آيَةِ الْوُضُوءِ: وَإِنْ كُنْـتُمْ مَرْضى أَوْ عَلى سَفَرٍ أَوْ جاءَ أَحَدٌ مِنْكُمْ مِنَ الْغائِطِ، أَوْ لامَسْتُمُ النِّساءَ فَـلَمْ تَدَُِوا مَاءً فَـتَـيَمهمُوا صَعِيداً طَيِّباً »2« ، فَأَبَاحَ لِلْمَرِيضِ الْعُدُولَ عَنِ الْمَاءِ إِلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'التُّـرَابِ حِيَْْةً لَهُ أَنْ يُصِيبَ جَسَدَهُ مَا يُـؤْذِيهِ، وَهَذَا تَـنْبِيهٌ عَلَى الِْحمْيَةِ عَنْ كُلِّ مُؤْذٍ لَهُ مِنْ دَاخِلٍ أَوْ خَارجٍِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'فَـقَدْ أَرْشَدَ- سُبْحَانَهُ عِبَادَهُ إِلَى أُصُولِ الطِّبِّ وَمَاََمِعِ قَـوَاعِدِهِ، وَنَنُْْ نَذْكُرُ هَدْيَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي ذَلِكَ ، وَنُـبَـيُِّن أَنه هَدْيَهُ فِيهِ أَكْمَلُ هَدْيٍ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'فَأَمها طِبُّ الْقُلُوبِ، فَمُسَلهمٌ إِلَى الرُّسُلِ صَلَوَاتُ ا هلِلَّ وَسَلَامُهُ عَلَيْهِمْ، وَلَا سَبِيلَ إِلَى حُصُولِهِ إِهلا مِنْ جِهَتِهِمْ وَعَلَى أَيْدِيهِمْ، فَإِنه صَلَاحَ الْقُلُوبِ أَنْ تَكُونَ عَارِفَةً بِرَبَِّها، وَفَاطِرِهَا، وَبَِأسَْمائِهِ، وَصِ فَاتِهِ، وَأَفْـعَالِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَأَحْكَامِهِ، وَأَنْ تَكُونَ مُؤْثِرَةً لِمَرْضَاتِهِ وَمُاَُبِّهِ، مُتَجَنِّبَةً لِمَنَاهِيهِ وَمَسَاخِطِهِ، وَلَا صِحهةَ لََها وَلَا حَيَاةَ الْبَـتهةَ إِهلا بِذَلِكَ ، وَلَا سَبِيلَ إِلَى تَـلَقِّيهِ إِهلا مِنْ جِهَةِ الرُّسُلِ وَمَا يُظَنُّ مِنْ حُصُولِ صِحهةِ الْقَلْبِ بِدُونِ اتِّبَاعِهِمْ، فَـغَلَطٌ مِمهنْ يَظُنُّ ذَلِكَ ، وَإِنَِّما ذَلِكَ حَيَاةُ نَـفْسِهِ الْبَهِيمِيهةِ الشههْوَانِيهةِ، وَصِحهتُـهَا وَقُـهوتُـهَا، وَحَ يَاةُ قَـلْبِهِ وَصِحهتُهُ، وَقُـهوتُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'عَنْ ذَلِكَ بَِمعْزِلٍ وَمَنْ لََْ يَُميِّزْ بَـيَْن هَذَا وَهَذَا، فَـلْيَـبْكِ عَلَى حَيَاةِ قَـلْبِهِ، فَإِنههُ مِنَ الَْأمْوَاتِ، وَعَلَى نُورِهِ، فَإِنههُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'مُنْـغَمِسٌ فِي بَِحارِ الظُّلُمَاتِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, '(7) البقرة- 791', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, '(2) النساء- -43 المائدة- -1 والمعنى أنه ليس عليكم حرج إذا كنتم مدُثين وأردتم القيام للصلاة أن تتطهروا بالماء ويعفى من ذلك المرضى مرضا يضر معه الماء والمسافرون الذين لا يجدون الماء بعد طلبه فإنه يكفيهم أن يتيمموا بالتراب فيمسحوا بوجوهم وأيديهم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'الُْجوعِ ،', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَمها طِبُّ الَْأبْدَانِ: فَإِنههُ نَـوْعَانِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'نَـوْعٌ قَدْ فَطَرَ ا هللَُّ عَلَيْهِ الَْحيَـوَانَ نَاطِقَهُ وَبَِهيمَهُ، فَـهَذَا لَا يُْحتَاجُ فِيهِ إِلَى مُعَالََجةِ طَبِيبٍ، كَطِبِّ وَالْعَطَشِ وَالْبَـرْدِ، وَالتهـعَبِ بَِأضْدَادِهَا وَمَا يُزِيلُهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَالثهانِي: مَا يَْحتَاجُ إِلَى فِكْرٍ وَتَمََُّلٍ، كَدَفْعِ الَْأمْرَاضِ الْمُتَشَابَِهةِ الَْحادِثَةِ فِي الْمِزَاجِ، بَِحيْثُ يَْخرُجُ بَِها عَنِ الِاعْتِدَالِ، إِمها إِلَى حَرَارَةٍ، أَوْ بُـرُودَةٍ، أَوْ يُـبُوسَةٍ، أَوْ رُطُوبَةٍ، أَوْ مَا يَـتَـرَكهبُ مِنَ اثْـنَـيِْن مِنْـهَا، وَهِيَ نَـوْعَانِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'إِمها مَادِّيهةٌ، وَإِمها كَيْفِيهةٌ، أَعْنِِ إِمها أَنْ يَكُونَ بِانْصِبَابِ مَادهةٍ، أَوْ بُِحدُوثِ كَيْفِيهةٍ، وَالْفَرْقُ بَـيْـنَـهُمَا أَنه أَمْرَاضَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الْكَيْفِيهةِ تَكُونُ بَـعْدَ زَوَالِ الْمَوَادِّ الهتِي أَوْجَبَـتْـهَا، فَـتَـزُولُ مَوَادُّهَا، وَيَـبْـقَى أَثَـرُهَا كَيْفِيهةً فِي الْمِزَاجِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَأَمْرَاضُ الْمَادهةِ أَسْبَابُـهَا مَعَهَا تَدَُُّهَا، وَإِذَا كَانَ سَبَبُ الْمَرَضِ مَعَهُ، فَالنهظَرُ فِي السهبَبِ يَـنْـبَغِي أَنْ يَـقَعَ أَهولًا، ُ مه فِي الْمَرَضِ ثَنَِيًا، ُ مه فِي الدهوَاءِ ثَلَِثًا. أَوِ الَْأمْرَاضُ الْآلِيهةُ وَهِيَ الهتِي تُْخرِجُ الْعُضْوَ عَنْ هَيْـئَتِهِ، إِمها فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'شَكْلٍ، أَوْ تَوَِْيفٍ، أَوْ مَرًَْى، أَوْ خُشُونَةٍ، أَوْ مَلَاسَةٍ، أَوْ عَدَدٍ، أَوْ عَظْمٍ، أَوْ وَضْعٍ، فَإِنه هَذِهِ الَْأعْضَاءَ إِذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'تَلََهفَتْ وَكَانَ مِنْـهَا الْبَدَنُ سُِّميَ تَلََُّفُهَا اتِّصَالًا، وَالُْخرُوجُ عَنِ الِاعْتِدَالِ فِيهِ يُسَمهى تَـفَهرقَ الِاتِّصَالِ، أَوِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'الَْأمْرَاضُ الْعَامهةُ الهتِي تَـعُمُّ المتشابهة رالآلية.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَالَْأمْرَاضُ الْمُتَشَابَِهةُ: هِيَ الهتِي يَْخرُجُ بَِها الْمِزَاجُ عَنِ الِاعْتِدَالِ، وَهَذَا الُْخرُوجُ يُسَمهى مَرَضًا بَـعْدَ أَنْ يَضُهر بِالْفِعْلِ إِضْرَارًا مَسُُْوسًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَهِيَ عَلَى ثَاََنِيَةِ أَضْرُبٍ: أَرْبَـعَةٌ بَسِيطَةٌ، وَأَرْبَـعَةٌ مُرَكهبَةٌ، فَالْبَسِيطَةُ: الْبَارِدُ، وَالَْحارُّ، وَالهرطْبُ ، وَالْيَابِسُ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَالْمُرَكهبَةُ الَْحارُّ الهرطْبُ ، وَالَْحارُّ الْيَابِسُ ، وَالْبَارِدُ الهرطْبُ ، وَالْبَارِدُ الْيَابِسُ ، وَهِيَ إِمها أَنْ تَكُونَ بِانْصِبَابِ مَادهةٍ، أَوْ بِغَيِْر انْصِبَابِ مَادهةٍ، وَإِنْ لََْ يَضُهر الْمَرَضُ بِالْفِعْلِ يُسَمهى خُرُوجًا عَنِ الِاعْتِدَالِ صِحهةً.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَلِلْبَدَنِ ثَلَاثَةُ أحوال: حال طبيعية، وحار خَارِجَةٌ عَنِ الطهبِيعِيهةِ، وَحَالٌ مُتَـوَسِّطَةٌ بَـيَْن الَْأمْرَيْنِ، فَالُْأولَى: بَِها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'يَكُونُ الْبَدَنُ صَحِيحًا، وَالثهانِيَةُ: بَِها يَكُونُ مَرِيضًا، وَالَْحالُ الثهالِثَةُ هِيَ مُتَـوَسِّطَةٌ بَـيَْن الَْحالَتَـيِْن، فَإِنه الضِّده لَا يَـنْـتَقِلُ إِلَى ضِدِّهِ إِهلا بُِمتَـوَسِّطٍ، وَسَبَبُ خُرُوجِ الْبَدَنِ عَنْ طَبِيعَتِهِ، إِمها مِنْ دَاخِلِهِ، لَِأنههُ مُرَكهبٌ مِنَ الَْحارِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَالْبَارِدِ، وَالهرطْبِ وَالْيَابِسِ ، وَإِمها مِنْ خَارِجٍ، فَلِنَِه مَا يَـلْقَاهُ قَدْ يَكُونُ مُوَافِقًا، وَقَدْ يَكُونُ غَيْـرَ مُوَافِقٍ، وَالضهرَرُ الهذِي يَـلْحَقُ الِْإنْسَانَ قَدْ يَكُونُ مِنْ سُوءِ الْمِزَاجِ خِرُُِوجِهِ عَنِ الِاعْتِدَالِ، وَقَدْ يَكُونُ مِنْ فَسَادٍ فِي الْعُضْوِ، وَقَدْ يَكُونُ مِنْ ضَعْفٍ فِي الْقُوَى، أَوِ الَْأرْوَاحِ الَْحامِلَةِ لََها، وَيَـرْجِعُ ذَلِكَ إِلَى زِيَادَةِ مَا الِاعْتِدَالُ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'عَدَمِ زِيَادَتِهِ، أَوْ نُـقْصَانِ مَا الِاعْتِدَالُ فِي عَدَمِ نُـقْصَانِهِ، أَوْ تَـفَرُّقِ مَا الِاعْتِدَالُ فِي اتِّصَالِهِ، أَوِ اتِّصَالِ مَا الِاعْتِدَالُ في تفرقه، او امتاد مَا الِاعْتِدَالُ فِي انْقِبَاضِهِ، أَوْ خُرُوجِ ذِي وَضْعٍ وَشَكْلٍ عَنْ وَضْعِهِ وَشَكْ لِهِ بَِحيْثُ يُْخرِجُهُ عَنِ اعْتِدَالِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'فَالطهبِيبُ : هُوَ الهذِي يُـفَرِّقُ مَا يَضُرُّ بِالِْإنْسَانِ جَعَُْهُ، أَوْ يَْجمَعُ فِيهِ مَا يضره تفرقه، وينقص مِنْهُ مَا يَضُرُّهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'زِيَادَتُهُ، أَوْ يَزِيدُ فِيهِ مَا يَضُرُّهُ نَـقْصُهُ، فَـيَجْلِبُ الصِّحهةَ الْمَفْقُودَةَ، أَوْ يَْحفَظُهَا بِالشهكْلِ وَالشهبَهِ، وَيَدْفَعُ الْعِلهةَ الْمَ وْجُودَةَ بِالضِّدِّ وَالنهقِيضِ ، وَيُْخرِجُهَا، أَوْ يَدْفَـعُهَا بَِما يَْمنَعُ مِنْ حُصُولَِها بِالِْحمْيَةِ، وَسَتَـرَى هَذَا كُلههُ فِي هَدْيِ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ شَافِيًا كَافِيًا بَِحوَلِ ا هلِلَّ وَقُـهوتِهِ، وَفَضْلِهِ وَمَعُونَتِهِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'فَكَانَ مِنْ هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِعْلُ التهدَاوِي فِي نَـفْسِهِ، وَالَْأمْرُ بِهِ لِمَنْ أَصَابَهُ مَرَضٌ مِنْ أَهْلِهِ وَأَصْحَابِهِ، وَلَكِنْ لََْ يَكُنْ مِنْ هَدْيِهِ وَلَا هَدْيِ أَصْحَابِهِ اسْتِعْمَالُ هَذِهِ الَْأدْوِيَةِ الْمُرَكهبَةِ الهتِي تُسَمهى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'أَقْـرَبَاذِينَ، بَلْ كَانَ غَالِبُ  أَدْوِيَتِهِمْ بِالْمُفْرَدَاتِ، وَرُهبَما أَضَافُوا إِلَى الْمُفْرَدِ مَا يُـعَاوِنُهُ، أَوْ يَكْسِرُ سَوْرَتَهُ، وَهَذَا غَالِبُ طِبِّ الُْأمَمِ عَلَى اخْتِلَافِ أَجْنَاسِهَا مِنَ الْعَرَبِ وَالتُّـرْكِ، وَأَهْلِ الْبَـوَادِي قَاطِبَةً، وَإِهنَما عُنَِِ بِالْمُرَكهبَاتِ الرُّومُ وَالْيُونَانِيُّونَ، وَأَكْ ثَـرُ طِبِّ الِْهنْدِ بِالْمُفْرَدَاتِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَقَدِ اتهـفَقَ الَْأطِبهاءُ عَلَى أَنههُ مَتَى أَمْكَنَ التهدَاوِي بِالْغِذَاءِ لَا يُـعْدَلُ عَنْهُ إِلَى الدهوَاءِ، وَمَتَى أَمْكَنَ بِالْبَسِيطِ لَا يُـعْدَلُ عَنْهُ إِلَى الْمُرَكهبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'قَالُوا وَكُلُّ دَاءٍ قُدِرَ عَلَى دَفْعِهِ بِالَْأغْذِيَةِ وَالِْحمْيَةِ، لََْ يَُحاوَلْ دَفْـعُهُ بِالَْأدْوِيَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'قَالُوا وَلَا يَـنْـبَغِي لِلطهبِيبِ أَنْ يَـوْلَعَ بِسَقْيِ الَْأدْوِيَةِ، فَإِنه الدهوَاءَ إِذَا لََْ يَِجدْ فِي الْبَدَنِ دَاءً يَُحلِّلُهُ، أَوْ وَجَدَ دَاءً', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'لَا يُـوَافِقُهُ، أَوْ وَجَدَ مَا يُـوَافِقُهُ فَـزَادَتْ كَمِّيهـتُهُ عَلَيْهِ، أو كيفيته،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'نشبت؟؟؟ بِالصِّحهةِ، وَعَبَثَ بَِها. وَأَرْبَابُ التهجَارِبِ مِنَ الَْأطِبهاءِ طِبُّـهُمْ بِالْمُفْرَدَاتِ غَالِبًا، وَهُمْ أَحَدُ فِرَقِ الطِّبِّ الثهلَاثِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَالتهحْقِيقُ فِي ذَلِكَ أَنه الَْأدْوِيَةَ مِنْ جِنْسِ الَْأغْذِيَةِ، فَالُْأمهةُ وَالطهائِفَةُ الهتِي غَالِبُ أَغْذِيَتِهَا الْمُفْرَدَاتُ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'أَمْرَاضُهَا قَلِيلَةٌ جِدًّا، وَطِبُّـهَا بِالْمُفْرَدَاتِ، وَأَهْلُ الْمُدُنِ الهذِينَ غَلَبَتْ  عَلَيْهِمُ الَْأغْذِيَةُ الْمُرَكهبَةُ يَْحتَاجُونَ إِلَى الَْأدْوِيَةِ الْمُرَكهبَةِ، وَسَبَبُ ذَلِكَ  أَنه أَمْرَاضَهُمْ فِي الْغَالِبِ مُرَكهبَةٌ، فَالَْأدْوِيَةُ الْمُرَكهبَةُ أَنْـفَعُ لََها، وَأَمْرَاضُ أَهْلِ الْبَـوَادِي وَالصهحَارِي مُفْرَدَةٌ، فَـيَكْفِي فِي مُدَاوَاتَِها الَْأدْوِيَةُ الْمُفْرَدَةُ، فَـهَذَا بُـرْهَانٌ بَِحسْبِ الصِّنَاعَةِ الطبية. وننْ نقول: إن ها هنا أَمْرًا آخَرَ، نِسْبَةُ طِبِّ الَْأطِبهاءِ إِلَيْهِ كَنِسْبَةِ طِبِّ الطهرْقِيهةِ وَالْعَجَائِزِ إِلَى طِبِّهِمْ، وَقَدِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'اعْتَـرَفَ بِهِ حُذهاقُـهُمْ وَأَئِمهتُـهُمْ، فَإِنه مَا عِنْدَهُمْ مِنَ الْعِلْمِ بِالطِّبِّ مِنْـهُمْ مَنْ يَـقُولُ: هُوَ قِيَاسٌ وَمِنْـهُمْ مَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'يَـقُولُ هُوَ تَرَِْبَةٌ. وَمِنْـهُمْ مَنْ يَـقُولُ هُوَ إِلَْهامَاتٌ ، وَمَنَامَاتٌ ، وَحَدْسٌ صَائِبٌ . وَمِنْـهُمْ مَنْ يَـقُولُ: أُخِذَ كَثِيٌر مِنْهُ مِنَ الَْحيَـوَانَاتِ الْبَهِيمِيهةِ، كَمَا نُشَاهِدُ السهنَانِيَر إِذَا أَكَلَتْ ذَوَاتِ السُّمُومِ تَـعْمِدُ إِلَى السِّ رَاجِ، فَـتَـلَغُ فِي الهزيْتِ تتداوى به، وكما رؤيت الَْحيهاتُ إِذَا خَرَجَتْ مِنْ بُطُونِ الَْأرْضِ ، وَقَدْ عَشِيَتْ أَبْصَارُهَا تَتَِْي إِلَى وَرَقِ الهرازِيَانِجِ، فَـتُمِرُّ عُيُونَـهَا عَلَيْـهَا. وَكَمَا عُهِدَ مِنَ الطهيِْر الهذِي يَْحتَقِنُ بَِماءِ الْبَحْرِ عِنْدَ انِْبَْاسِ طَبْعِهِ، وَأَمْثَالُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'ذلك مما ذكر في مبادىء الطِّبِّ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَأَيْنَ يَـقَعُ هَذَا وَأَمْثَالُهُ مِنَ الْوَحْيِ الهذِي يُوحِيهِ ا هللَُّ إِلَى رَسُولِهِ بَِما يَـنْـفَعُهُ وَيَضُرُّهُ، فَنِسْبَةُ مَا عِنْدَهُمْ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'الطِّبِّ إِلَى هَذَا الْوَحْيِ كَنِسْبَةِ مَا عِنْدَهُمْ مِنَ الْعُلُومِ إلى ما جاءت به الأنبياء، بل ها هنا مِنَ الَْأدْوِيَةِ الهتِي تَشْفِي مِنَ الَْأمْرَاضِ مَا لَ يتهد إِلَيْـهَا عُقُولُ أَكَابِرِ الَْأطِبهاءِ، وَلََْ تَصِلْ إِلَيْـهَا علومهم وتاَربهم، و؟؟؟ ن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'الَْأدْوِيَةِ الْقَلْبِيهةِ، وَالرُّوحَانِيهةِ، وَقُـهوةِ الْقَلْبِ، وَاعْتِمَادِهِ عَلَى ا هلِلَّ، وَالتهـوَكُّلِ عَلَيْهِ، وَالِالْتِجَاءِ إلَيْهِ، وَالِانْطِرَاحِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَالِانْكِسَارِ بين يديه، والتذلل له، والصدقئة، وَالدُّعَاءِ، وَالتهـوْبَةِ، وَالِاسْتِغْفَارِ، وَالِْإحْسَانِ إِلَى الَْخلْقِ، وَإِغَاثَةِ الْمَلْهُوفِ، وَالتهـفْرِيجِ عَنِ الْمَكْ رُوبِ، فَإِنه هَذِهِ الَْأدْوِيَةَ قَدْ جَ هربَـتْـهَا الُْأمَمُ عَلَى اخْتِلَافِ أَدْيَانَِها وَمِلَلِهَا، فوجودا لَهاَ مِنَ التهأْثِيِر فِي الشِّ فَاءِ مَا لَا يَصِلُ إِلَيْهِ عِلْمُ أَعْلَمِ الَْأطِبهاءِ، وَلَا تَرَِْبَـتُهُ، وَلَا قِيَاسُهُ. وَقَدْ جَ هربْـنَا نَنُْْ وَغَيْـرُنَا مِنْ هَذَا أُمُورًا كَثِيَرةً، وَرَأَيْـنَاهَا تَـفْعَلُ مَا لَا تفعل الأدوية', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'الِْحسِّ يهةُ، بَلْ تَصِيُر الَْأدْوِيَةُ الِْحسِّ يهةُ عِنْدَهَا بَِمنْزِلَةِ أَدْوِيَةِ الطهرْقِيهةِ عِنْدَ الَْأطِبهاءِ، وَهَذَا جَارٍ عَلَى قَانُونِ الِْحكْمَةِ الِْإلَِهيهةِ لَيْسَ خَارِجًا عَنْـهَا، وَلَكِنه الَْأسْبَابَ مُتَـنَـوِّعَةٌ، فَإِنه الْقَلْبَ مَتَى اتهصَلَ بِرَبِّ الْعَالَمِيَن، وَخَالِقِ الدهاءِ وَالدهوَاءِ، وَمُدَبِّرِ الطهبِيعَةِ وَمُصَرِّفِهَا عَلَى مَا يَشَاءُ كَانَتْ لَهُ أَدْوِيَةٌ أُخْ رَى غَيْـرُ الَْأدْوِيَةِ الهتِي يُـعَانِيهَا الْقَلْبُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'الْبَعِيدُ مِنْهُ الْمُعْرِضُ عَنْهُ، وَقَدْ عُلِمَ أَنه الَْأرْوَاحَ مَتَى قَوِيَتْ ، وَقَوِيَتِ النهـفْسُ وَالطهبِيعَةُ تَـعَاوَنَا عَلَى دَفْعِ الدهاءِ وَقَـهْرِهِ، فَكَيْفَ يُـنْكَرُ لِمَنْ قَوِيَتْ طَبِيعَتُهُ ونفسه، وفرحت بقربها من بارئها، وأنسهابه، وَحُبِّهَا لَهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَتَـنَـعُّمِهَا بِذِكْرِهِ، وَانْصِ رَافِ قُـوَاهَا كُلِّهَا إلَيْهِ، وَجَعَِْهَا عَلَيْهِ، وَاسْتِعَانَتِهَا بِهِ، وَتَـوَكُّلِهَا عَلَيْهِ، أَنْ يَكُونَ ذَلِكَ لََها مِنْ أَكْ بََِ الَْأدْوِيَةِ، وَأَنْ تُوجِبَ لََها هَذِهِ الْقُهوةُ دَفْعَ الَْألََِ بِالْكُلِّيهةِ، وَلَا يُـنْكِرُ هَذَا إِهلا أَجْهَلُ النهاسِ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَأَغْلَظُهُمْ حِجَابًا، وَأَكْ ثَـفُهُمْ نَـفْسًا، وَأَبْـعَدُهُمْ عَنِ ا هلِلَّ وَعَنْ حَقِيقَةِ الِْإنْسَانِيهةِ، وَسَنَذْكُرُ إِنْ شَاءَ ا هللَُّ السهبَبَ الهذِي بِهِ أَزَالَتْ قِرَاءَةُ الْفَاتِةََِ دَاءَ اللهدْغَةِ عَنِ اللهدِيغِ الهتِي رُقِيَ بَِها، فَـقَامَ حَ هتى كَأَنه مَا بِهِ قَـلَبَةٌ »7« . فَـهَذَانِ نَـوْعَانِ مِنَ الطِّبِّ النهـبَوِيِّ نَنُْْ بَِحوْلِ ا هلِلَّ نَـتَكَلهمُ عَلَيْهِمَا بَِحسْبِ الَْجهْدِ وَالطهاقَةِ، وَمَبْـلَغِ عُلُومِنَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'الْقَاصِ رَةِ، وَمَعَارِفِنَا الْمُتَلَاشِيَةِ جِدًّا، وَبِضَاعَتِنَا الْمُزْجَاةِ »2« ، وَلَكِنها نَسْتَـوْهِبُ مَنْ بِيَدِهِ الَْخيْـرُ كُلُّهُ، وَنَسْتَمِدُّ مِنْ فَضْلِهِ، فإنه العزيز الوهّاب.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى مسلم فِي «صَحِيحِهِ» : مِنْ حَدِيثِ أَبِي الزبير، عَنْ جَابِرِ بْنِ عَبْدِ ا هلِلَّ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَسَلهمَ، أَنههُ قَالَ «لِكُلِّ دَاءٍ دَوَاءٌ، فَإِذَا أُصِيبَ دَوَاءُ الدهاءِ، بَـرَأَ بِِإذْنِ ا هلِلَّ عَهز وَجَله» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَفِي «الصهحِيحَيِْن» عَنْ عطاء، عَنْ أَبِي هُرَيْـرَةَ قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَا أَنْـزَلَ ا هللَُّ مِنْ دَاءٍ إِهلا أَنْـزَلَ له شفاء» »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(7) قلبة )بزنة سبلة( الداء أو الألَ الذي يتقلب منه صاحبه (2) بضاعة مزجاة: قليلة أو لَ يتم إصلاحها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(3) أخرجه مسلم في كتاب الطب عن جابر، والإمام أحدْ، ولَ يخرجه البخاري واستدركه الحاكم فوهم (4) أخرجه ابن ماجه. والبخاري في الطب. ورواه مسلم بلفظ «ما أنزل الله داء إلا أنزل له دواء، فإذا أصيب دواء الداء برىء بإذن الله', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَفِي «مُسْنَدِ الِْإمَامِ أَحْدََْ» : مِنْ حَدِيثِ زِيَادِ بْنِ عِلَاقَةَ، عَنْ أسامة بن شريك، قَالَ: كُنْتُ عِنْدَ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَجَاءَتِ الَْأعْرَابُ ، فَـقَالُوا: يَا رَسُولَ ا هلِلَّ! أَنَـتَدَاوَى؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'فَـقَالَ: «نَـعَمْ يَا عِبَادَ ا هلِلَّ تَدَاوَوْا، فَإِنه ا هللََّ عَهز وَجَله لََْ يَضَعْ دَاءً إِهلا وَضَعَ لَهُ شِفَاءً غَيْـرَ دَاءٍ وَاحِدٍ» ، قَالُوا مَا هُوَ؟ قَالَ: «الْهرََمُ» »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَفِي لَفْظٍ: «إِنه الله لَ ينزل داء إلّا أنزل شِفَاءً، عَلِمَهُ مَنْ عَلِمَهُ وَجَهِلَهُ مَنْ جَهِلَهُ» »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَفِي «الْمُسْنَدِ» : مِنْ حَدِيثِ ابْنِ مَسْعُودٍ يَـرْفَـعُهُ: «إِنه ا هللََّ عَهز وَجَله لََْ يُـنْزِلْ دَاءً إِهلا أَنْـزَلَ لَهُ شِفَاءً، عَلِمَهُ مَنْ عَلِمَهُ، وَجَهِلَهُ مَنْ جَهِلَهُ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَفِي «الْمُسْنَدِ» وَ «السُّنَنِ» »3« عَنْ أبي خزامة، قَالَ: قُـلْتُ : يَا رَسُولَ ا هلِلَّ! أَرَأَيْتَ رُقًى نَسْتَـرْقِيهَا، وَدَوَاءً نَـتَدَاوَى بِهِ، وَتُـقَاةً نَـتهقِيهَا، هَلْ تَـرُدُّ مِنْ قَدَرِ ا هلِلَّ شَيْـئًا؟ فَـقَالَ «هِيَ مِنْ قَدَرِ ا هلِلَّ» »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'فَـقَدْ تَضَمهنَتْ هَذِهِ الَْأحَادِيثُ إثْـبَاتَ الَْأسْبَابِ وَالْمُسَبهـبَاتِ. وَإِبْطَالَ قَـوْلِ مَنْ أَنْكَرَهَا، وَيَُجوزُ أَنْ يَكُونَ قَـوْلُهُ: «لِكُلِّ دَاءٍ دَوَاءٌ» ، عَلَى عُمُومِهِ حَ هتى يَـتَـنَاوَلَ الَْأدْوَاءَ الْقَاتِلَةَ، وَالَْأدْوَاءَ الهتِي لَا يُْمكِنُ لِطَبِيبٍ أَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'يُـبِْئََـهَا، وَيَكُونُ ا هللَُّ عَهز وَجَله قَدْ جَعَلَ لََها أَدْوِيَةً تُـبِْئَُـهَا، وَلَكِنْ طَوَى عِلْمَهَا عَنِ الْبَشَرِ، وَلََْ يَْجعَلْ لَهمُْ إِلَيْهِ سَبِيلًا، لَِأنههُ لَا عِلْمَ لِلْخَلْقِ إِهلا مَا عَلهمَهُمُ ا هللَُّ، وَلَِهذَا عَلهقَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وسلم الشّفاء على مصادفة الدواء للداء،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, '(7) أخرجه أبو داود والترمذي والإمام أحدْ وابن ماجه كلهم في كتاب الطب وأخرجه ابن حبان في صحيحه والحاكم من حديث زياد بن علاقة، وقال الترمذي حس صحيح والحاكم صحيح. ومعنى الحديث: أي تداووا ولا تعتمدوا في الشفاء على التداوي بل كونوا عباد الله متوكلين عليه. ومن تداوى عليه أن يعتقد حقا ويؤمن يقينا بأن الدواء لا يحدث شفاء ولا يولده، كما أن الداء لا يحدث سقما ولا يولده، ولكن المولى جلت قدرته يخلق الموجودات واحدا عقب آخر على ترتيب هو أعلم بحكمته و «داء الهرم» أي الكبَ جعل داء تشبيها به لأن الموت يعقبه كالداء', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, '(2) رواه الحاكم. ونوْه للنسائي وابن ماجه، وصحيحه ابن حبان (3) هي سنن الترمذي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, '(4) أخرجه ابن ماجه والحاكم في صحيحه، والترمذي وقال: حسن صحيح', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'فَإِنههُ لَا شَيْ ءَ مِنَ الْمَخْ لُوقَاتِ إِهلا لَهُ ضِدٌّ، وَكُلُّ دَاءٍ لَهُ ضِدٌّ مِنَ الدهوَاءِ يُـعَالََُ بِضِدِّهِ، فَـعَلهقَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ الْبُـرْءَ بُِموَافَـقَةِ الدهاءِ لِلدهوَاءِ، وَهَذَا قَدْرٌ زَائِدٌ عَلَى مُهََردِ وَجُودِهِ، فَإِنه الدهوَاءَ مَتَى جَاوَزَ دَرَجَةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'الدهاءِ فِي الْكَيْفِيهةِ، أَوْ زَادَ فِي الْكَمِّيهةِ عَلَى مَا يَـنْـبَغِي، نَـقَلَهُ إِلَى دَاءٍ آخَرَ، وَمَتَى قَصَرَ عَنْـهَا لََْ يَفِ بُِمقَاوَمَتِهِ، وَكَانَ الْعِلَاجُ قَاصِ رًا، وَمَتَى لََْ يَـقَعِ الْمُدَاوِي عَلَى الدهوَاءِ، أَوْ لََْ يَـقَعِ الدهوَاءُ عَلَى الدهاءِ، لََْ يَْحصُلِ الشِّ فَاءُ، وَمَتَى لََْ يَكُنِ الهزمَانُ صَالًِحا لِذَلِكَ الدهوَاءِ، لََْ يَـنْـفَعْ، وَمَتَى كَانَ الْبَدَنُ غَيْـرَ قَابِلٍ لَهُ، أَوِ الْقُهوةُ عَاجِزَةً عَنْ حَلِْْهِ، أَوْ َ مه مَانِعٌ يَْمنَعُ مِنْ تَثَِْيِرهِ، لََْ يَْحصُلِ الْبُـرْءُ لِعَدَمِ الْمُصَادَفَةِ، وَمَتَى تَهَتِ الْمُصَادَفَةُ حَصَلَ الْبُـرْءُ بِِإذْنِ الله ولابد، وَهَذَا أَحْسَنُ الْمَحْمِلَيِْن فِي الَْحدِيثِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَالثهانِي: أَنْ يَكُونَ مِنَ الْعَامِّ الْمُرَادِ بِهِ الَْخاصُّ، لَا سِيهمَا وَالدهاخِلُ فِي اللهفْظِ أَضْعَافُ أَضْعَافِ الَْخارِجِ مِنْهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَهَذَا يُسْتَـعْمَلُ فِي كُلِّ لِسَانٍ، وَيَكُونُ الْمُرَادُ أَنه ا هللََّ لََْ يَضَعْ دَاءً يَـقْبَلُ الدهوَاءَ إِهلا وَضَعَ لَهُ دَوَاءً، فَلَا يَدْخُلُ فِي هَذَا الَْأدْوَاءُ الهتِي لَا تَـقْبَلُ الدهوَاءَ، وَهَذَا كَقَوْلِهِ تَـعَالَى فِي الرِّيحِ الهتِي سَلهطَهَا عَلَى قَـوْمِ عَادٍ تُدَمِّرُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'كُله شَيْ ءٍ بَِأمْرِ رَبِّها »7« أَيْ كُلُّ شَيْ ءٍ يَـقْبَلُ التهدْمِيَر، وَمِنْ شَأْنِ الرِّيحِ أَنْ تُدَمِّرَهُ، وَنَظَائِرُهُ كَثِيَرةٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَمَنْ تَمََهلَ خَلْقَ الَْأضْدَادِ فِي هَذَا الْعَالََِ، وَمُقَاوَمَةَ بَـعْضِهَا لِبَـعْضٍ ، وَدَفْعَ بَـعْضِهَا بِبَـعْضٍ وَتَسْلِيطَ بَـعْضِهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'عَلَى بَـعْضٍ ، تَـبَـهيَن لَهُ كَمَالُ قُدْرَةِ الهربِّ تَـعَالَى، وَحِكْمَتُهُ، وَإِتْـقَانُهُ مَا صَنَـعَهُ، وَتَـفَرُّدُهُ بِالرُّبُوبِيهةِ، وَالْوَحْدَانِيهةِ، وَالْقَهْرِ، وَأَنه كُله مَا سِوَاهُ فَـلَهُ مَا يُضَادُّهُ وَيَُمانِعُهُ، كَمَا أَنههُ الْغَنُِِّ بِذَاتِهِ، وَكُلُّ مَا سِوَاهُ مُتَُْاجٌ بِذَاتِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'وَفِي الَْأحَادِيثِ الصهحِيحَةِ الَْأمْرُ بِالتهدَاوِي، وَأَنههُ لَا يُـنَافِي التهـوَكُّلَ، كَمَا لَا يُـنَافِيهِ دَفْعُ دَاءِ الَْجوْعِ ، وَالْعَطَشِ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَالَْحرِّ، وَالْبَـرْدِ بَِأضْدَادِهَا، بَلْ لَا تَتِمُّ حَقِيقَةُ التهـوْحِيدِ إِهلا بُِمبَاشَرَةِ الَْأسْبَابِ الهتِي نَصَبَـهَا ا هللَُّ مُقْتَضَيَاتٍ لِمُسَبهـبَاتَِها قَدَرًا وَشَرْعًا، وَأَنه تَـعْطِيلَهَا يَـقْدَحُ فِي نَـفْسِ التهـوَكُّلِ، كَمَا يَـقْدَحُ فِي الَْأمْرِ وَالِْحكْمَةِ، وَيُضْعِفُهُ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'حَيْثُ يَظُنُّ مُعَطِّلُهَا أَنه تَـرْكَهَا أَقْـوَى فِي التهـوَكُّلِ، فَإِنه تَـرْكَهَا عَجْ زًا يُـنَافِي التوكل الذي حقيقته اعتماد', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, '(7) الأحقاف- -25 وهي الريح العاصفة التي دمر الله بها عادا قوم هود، وكان ذلك بإرادة الله سبحانه، فأهلكتهم رجالا ونساء وصغارا وكبارا، وأهلكت أموالهم. وبقي هود ومن آمن معه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'الْقَلْبِ عَلَى ا هلِلَّ فِي حُصُولِ مَا يَـنْـفَعُ الْعَبْدَ فِي دِينِهِ وَدُنْـيَاهُ، وَدَفْعِ مَا يَضُرُّهُ فِي دِينِهِ وَدُنْـيَاهُ، وَلَا بُده مَعَ هَذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'الِاعْتِمَادِ مِنْ مُبَاشَرَةِ الَْأسْبَابِ، وَإِهلا كَانَ مُعَطِّلًا لِلْحِكْمَةِ وَالشهرْعِ ، فَلَا يَْجعَلُ الْعَبْدُ عَجْ زَهُ تَـوَكُّلًا، وَلَا تَـوَكُّلَهُ عَجْ زًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'وَفِيهَا رَدٌّ عَلَى مَنْ أَنْكَرَ التهدَاوِي، وَقَالَ: إِنْ كَانَ الشِّ فَاءُ قَدْ قُدِّرَ، فَالتهدَاوِي لَا يُفِيدُ، وَإِنْ لََْ يَكُنْ قَدْ قُدِّرَ، فَكَذَلِكَ وَأَيْضًا، فَإِنه الْمَرَضَ حَصَلَ بِقَدَرِ ا هلِلَّ، وَقَدَرُ ا هلِلَّ لَا يُدْفَعُ وَلَا يُـرَدُّ، وَهَذَ ا السُّؤَالُ هُوَ الهذِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'أَوْرَدَهُ الَْأعْرَابُ على رسول الله هللا ىلص. وَأَمها أَفَاضِلُ الصِّحَابَةِ، فَأَعْلَمُ بَِا هلِلَّ وَحِكْمَتِهِ وَصِ فَاتِهِ مِنْ أَنْ يُورِدُوا مِثْلَ هَذَا، وَقَدْ أَجَابَـهُمُ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بَِما شَفَى وَكَفَى، فَـقَالَ: هَذِهِ الَْأدْوِيَةُ وَالرُّقَى وَالتُّـقَى هِيَ مِنْ قَدَرِ ا هلِلَّ، فَمَا خَرَجَ شَيْ ءٌ عَنْ قَدَرِهِ، بَلْ يُـرَدُّ قَدَرُهُ بِقَدَرِهِ، وَهَذَا الهردُّ مِنْ قَدَرِهِ، فَلَا سَبِيلَ إِلَى الُْخرُوجِ عَنْ قَدَرِهِ بِوَجْهٍ مَا، وَهَذَا كَرَدِّ قَدَرِ الُْجوعِ ، وَالْعَطَشِ وَالَْحرِّ، وَالْبَـرْدِ بَِأضْدَادِهَا، وَكَرَدِّ قَدَرِ الْعَدُوِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'بِالِْجهَادِ، وَكُلٌّ مِنْ قَدَرِ ا هلِلَّ الدهافِعُ وَالْمَدْفُوعُ وَالدهفْعُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَيُـقَالُ لِمُورِدِ هَذَا السُّؤَالِ «هَذَا يُوجِبُ عليك ألاتباشر سَبَـبًا مِنَ الَْأسْبَابِ الهتِي تَلَِْبُ بَِها مَنْـفَعَةً، أَوْ تَدْفَعُ بَِها مَضَ هرةً، لَِأنه الْمَنْـفَعَةَ وَالْمَضَ هرةَ إِنْ قُدِّرَتَا، لََْ يَكُنْ بُدٌّ مِنْ وُقُوعِهِمَا، وَإِنْ لََْ تُـقَدهرَا لََْ يَكُنْ سَبِيلٌ إِلَى وُقُوعِهِمَا، وَفِي ذَلِكَ خَرَابُ الدِّينِ وَالدُّنْـيَا، وَفَسَادُ الْعَالََِ، وَهَذَا لَا يَـقُولُهُ إِهلا دَافِعٌ لِلْحَقِّ، مُعَانِدٌ لَهُ، فَـيَذْكُرُ الْقَدَرَ لِيَدْفَعَ حُجهةَ الْمُحِقِّ عَلَيْهِ، كَالْمُشْركِِيَن الهذِينَ قَالُوا: لَوْ شاءَ ا هللَُّ ما أَشْرَكْ نا وَلا آباؤُنا »7« ، ولَوْ شاءَ ا هللَُّ مَا عَبَدْنا مِنْ دُونِهِ مِنْ شَيْ ءٍ نَنُْْ وَلا آباؤُنا »2« . فَـهَذَا قَالُوهُ دَفْـعًا لُِحجهةِ ا هلِلَّ عَلَيْهِمْ بِالرُّسُلِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وَجَوَابُ هَذَا السهائِلِ أَنْ يُـقَالَ: بَقِيَ قِسْمٌ ثَلَِثٌ لََْ تَذْكُرْهُ، وَهُوَ أَنه ا هللََّ قَدهرَ كَذَا وَكَذَا بَِهذَا السهبَبِ. فَإِنْ أَتَـيْتَ بِالسهبَبِ حَصَلَ الْمُسَبهبُ ، وَإِهلا فَلَا. فَإِنْ قَالَ: إِنْ كَانَ قَدهرَ لِِ السهبَبَ ، فَـعَلْتُهُ، وَإِنْ لََْ يقدّره لِ لَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'أتكَن من فعله.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, '(7) الانعام- -749 والمعنى أن المشركين يريدون أن يقولوا: إن الله راض بإشراكنا وترَيمنا للبحيرة والسائبة وغيرهاُ. ورد الله عليهم بقوله «قل هل عندكم من علم فتخرجوه لنا»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, '(2) النحل- -35 والمعنى أن قائل هذا القول أهل مكة وأحزابهم في الشرك فرد عليهم بأنهم يتبعون الذين كانوا من قبلهم فهم مقلدون لاحظ لهم من النظر «كذلك قال الذين من قبلهم فهل على الرسل إلا البلاغ المبين»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'قِيلَ: فَـهَلْ تَـقْبَلُ هَذَا الِاحْتِجَاجَ مِنْ عَبْدِكَ، وَوَلَدِكَ، وَأَجِيِركَ إِذَا احْ تَجه بِهِ عَلَيْكَ فِيمَا أَمَرْتَهُ بِهِ، وَنَـهَيْـتَهُ عَنْهُ فَخَالَفَكَ ؟ فَإِنْ قَبِلْتَهُ، فَلَا تَـلُمْ مَنْ عَصَاكَ، وَأَخَذَ مَالَكَ ، وَقَذَفَ عِرْضَكَ ، وَضَيهعَ حُقُوقَكَ . وَإِنْ لََْ تَـقْبَـلْهُ، فَكَيْفَ يَكُونُ مَقْبُولًا مِنْكَ فِي دَفْعِ حُقُوقِ ا هلِلَّ عَلَيْكَ . وَقَدْ رُوِيَ فِي أَثَرٍ إسْرَائِيلِيٍّ: أَنه إبْـرَاهِيمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'الَْخلِيلَ قَالَ؛ يَا رَبِّ مِمهنِ الدهاءُ؟ قَالَ: «مِنِِّ» . قَالَ: «فَمِمهنِ الدهوَاءُ؟» ؟ قَالَ: «مِنِِّ» . قَالَ: فَمَا بَالُ الطهبِيبِ؟، قَالَ: «رَجُلٌ أُرْسِلُ الدهوَاءَ عَلَى يَدَيْهِ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'وَفِي قَـوْلِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ «لِكُلِّ دَاءٍ دَوَاءٌ» ، تَـقْوِيَةٌ لِنَـفْسِ الْمَرِيضِ وَالطهبِيبِ، وَحَثٌّ عَلَى طَلَبِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'ذَلِكَ الدهوَاءِ وَالتهـفْتِيشِ عَلَيْهِ، فَإِنه الْمَرِيضَ إِذَا اسْتَشْعَرَتْ نَـفْسُهُ أَنه لِدَائِهِ دَوَاءً يُزِيلُهُ، تَـعَلهقَ قَـلْبُهُ بِرُوحِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'الرِّجَاءِ، وَبَـرَدَتْ عِنْدَهُ حَرَارَةُ الْيَأْسِ ، وَانْـفَتَحَ لَهُ باب الرجاء، متى قَوِيَتْ نَـفْسُهُ انْـبَـعَثَتْ حَرَارَتُهُ الْغَرِيزِيهةُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'وَكَانَ ذَلِكَ سَبَـبًا لِقُهوةِ الَْأرْوَاحِ الَْحيَـوَانِيهةِ وَالنهـفْسَانِيهةِ وَالطهبِيعِيهةِ، وَمَتَى قَوِيَتْ هَذِهِ الَْأرْوَاحُ، قَوِيَتِ الْقُوَى الهتِي هِيَ حَامِلَةٌ لََها، فَـقَهَرَتِ الْمَرَضَ وَدَفَـعَتْهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'وَكَذَلِكَ الطهبِيبُ إِذَا عَلِمَ أَنه لَِهذَا الدهاءِ دَوَاءً أَمْكَنَهُ طَلَبُهُ وَالتهـفْتِيشُ عَلَيْهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'وَأَمْرَاضُ الَْأبْدَانِ عَلَى وِزَانِ أَمْرَاضِ الْقُلُوبِ، وَمَا جَعَلَ ا هللَُّ لِلْقَلْبِ مَرَضًا إِهلا جَعَلَ لَهُ شِفَاءً بِضَدِّهِ، فَإِنْ عَلِمَهُ صَاحِبُ الدهاءِ وَاسْتَـعْمَلَهُ، وَصَادَفَ دَاءَ قَـلْبِهِ، أَبْـرَأَهُ بإذن الله تعالى.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي الِاحْ تِمَاءِ مِنَ التهخَمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, '، وَالزِّيَادَةِ فِي الَْأكْلِ عَلَى قَدْرِ الَْحاجَةِ، وَالْقَانُونِ الهذِي يَـنْـبَغِي مُرَاعَاتُهُ فِي الَْأكْلِ وَالشُّرْبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'فِي «الْمُسْنَدِ» وَغَيِْرهِ: عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «مَا مَلََِ آدَمِيٌّ وِعَاءً شَرًّا مِنْ بَطْنٍ، بَِحسْبِ ابْنِ آدَمَ لُقَيْمَاتٌ يُقِمْنَ صُلْبَهُ، فَإِنْ كَانَ لَا بُده فَاعِلًا، فَـثُـلُثٌ لِطَعَامِهِ، وَثُـلُثٌ لِشَرَابِهِ، وثلث لنفسه» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(7) أخرجه الإمام أحدْ والنسائي في كتاب الزهد، وابن ماجه في الأطعمة والحاكم في الأطعمة عن المقدام بن معد يكرب. قال الحاكم هو صحيح. وقال ابن حجر في فتح الباري: حديث حسن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الَْأمْرَاضُ نَـوْعَانِ: أَمْرَاضٌ مَادِّيهةٌ تَكُونُ عَنْ زِيَادَةِ مَادهةٍ أَفْـرَطَتْ فِي الْبَدَنِ حَ هتى أَضَ هرتْ بَِأفْـعَالِهِ الطهبِيعِيهةِ، وَهِيَ الَْأمْرَاضُ الَْأكْثَرِيهةُ، وَسَبَـبُـهَا إدْخَالُ الطهعَامِ عَلَى الْبَدَنِ قَـبْلَ هَضْمِ الَْأهولِ، وَالزِّيَادَةُ فِي الْقَدْرِ الهذِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'يَْحتَاجُ إِلَيْهِ الْبَدَنُ وَتَـنَاوُلُ، الَْأغْذِيَةِ الْقَلِيلَةِ النهـفْعِ، الْبَطِيئَةِ الْهضَْمِ، وَالِْإكْ ثَارُ مِنَ الَْأغْذِيَةِ الْمُخْ تَلِفَةِ التهـرَاكِيبِ الْمُتَـنَـوِّعَةِ، فَإِذَا مَلََِ الْآدَمِيُّ بَطْنَهُ مِنْ هَذِهِ الَْأغْذِيَةِ، وَاعْتَادَ ذَلِكَ ، أَوْرَثَـتْهُ أَمْرَاضًا مُتَـنَـوِّعَةً، مِنْـهَا بَطِيءُ الهزوَالِ وَسَرِيعُهُ، فَإِذَا تَـوَسهطَ فِي الْغِذَاءِ، وَتَـنَاوَلَ مِنْهُ قَدْرَ الَْحاجَةِ، وَكَانَ مُعْتَدِلًا فِي كَمِّيهتِهِ وَكَيْفِيهتِهِ، كَانَ انْتِفَاعُ الْبَدَنِ بِهِ أَكْ ثَـرَ مِنَ انْتِفَاعِهِ بِالْغِذَاءِ الْكَثِيِر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَمَرَاتِبُ الْغِذَاءِ ثَلَاثَةٌ: أَحَدُهَا: مَرْتَـبَةُ الَْحاجَةِ. وَالثهانِيَةُ: مَرْتَـبَةُ الْكِفَايَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَالثهالِثَةُ: مَرْتَـبَةُ الْفَضْلَةِ. فَأَخْ بَـرَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: أَنههُ يَكْفِيهِ لُقَيْمَاتٌ يُقِمْنَ صُلْبَهُ، فَلَا تَسْقُطُ قُـهوتُهُ، وَلَا تَضْعُفُ مَعَهَا، فَإِنْ تَاََوَزَهَا، فَـلْيَأْكُلْ فِي ثُـلُثِ بَطْنِهِ، وَيَدَعِ الثُّـلُثَ الْآخَرَ لِلْمَاءِ، وَالثهالِثَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'لِلنهـفَسِ ، وَهَذَا مِنْ أَنْـفَعِ مَا لِلْبَدَنِ وَالْقَلْبِ، فَإِنه الْبَطْنَ إِذَا امْتَلََِ مِنَ الطهعَامِ ضَاقَ عَنِ الشهرَابِ، فَإِذَا وَرَدَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'عَلَيْهِ الشهرَابُ ضَاقَ عَنِ النهـفَسِ ، وَعَرَضَ لَهُ الْكَرْبُ وَالتهـعَبُ بَِحمْلِهِ بَِمنْزِلَةِ حَامِلِ الِْحمْلِ الثهقِيلِ، هَذَا إِلَى مَا يَـلْزَمُ ذَلِكَ مِنْ فساد القلب، وكسل الجوارح عن الئاعات، وَتَرََُّكِهَا فِي الشههَوَاتِ الهتِي يَسْتَـلْزِمُهَا الشِّ بَعُ. فَامْتِلَاءُ الْبَطْنِ مِنَ الطهعَامِ مُضِرٌّ لِلْقَلْبِ وَالْبَدَنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'هَذَا إِذَا كَانَ دَائِمًا أَوْ أَكْثَرِهيا. وَأَمها إِذَا كَانَ فِي الَْأحْيَانِ، فَلَا بَْأسَ بِهِ، فَـقَدْ شَرِبَ أَبُو هُرَيْـرَةَ بَِحضْرَةِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مِنَ اللهبَِن، حَ هتى قَالَ: وَالهذِي بَـعَثَكَ بِالَْحقِّ، لَا أَجِدُ لَهُ مَسْلَكًا »7« وَأَكَلَ الصِّحَابَةُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'بَِحضْرَتِهِ مِرَارًا حَ هتى شَبِعُوا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَالشِّ بَعُ الْمُفْرِطُ يُضْعِفُ الْقُوَى وَالْبَدَنَ، وَإِنْ أَخْصَبَهُ، وَإِنَِّما يَـقْوَى الْبَدَنُ بَِحسْبِ مَا يَـقْبَلُ مِنَ الْغِذَاءِ، لَا بَِحسْبِ كَثْـرَتِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَلَمها كَانَ فِي الِْإنْسَانِ جُزْءٌ أَرْضِ يٌّ، وَجُزْءٌ هَوَائِيٌّ، وَجُزْءٌ مَائِيٌّ، قَسَمَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ طَعَامَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَشَرَابَهُ  وَنَـفَسَهُ  عَلَى  الَْأجْزَاءِ  الثهلَاثَةِ. فَإِنْ قِيلَ «فَأَيْنَ حَظُّ الُْجزْءِ النهارِيِّ ؟.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'قِيلَ: هَذِهِ مَسْأَلَةٌ تَكَلهمَ فِيهَا الأطباء، وقالوا: إن في البدن جزء ناريا بالفعل، وهو أحد أركانه وأسطقساته» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, '(7) أخرجه البخاري في الرقاق: باب كيف كان عيش النب صلّى الله عليه وسلم وأصحابه وتخليهم عن الدنيا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, '(2) لفظ يوناني أي أصوله جعَ «اسطقس» بمعنى الأصل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَنَازَعَهُمْ فِي ذَلِكَ آخَرُونَ مِنَ الْعُقَلَاءِ مِنَ الَْأطِبهاءِ وَغَيِْرهِمْ، وَقَالُوا: لَيْسَ فِي الْبَدَنِ جُزْءٌ نَارِيٌّ بِالْفِعْلِ، وَاسْتَدَلهوا بِوُجُوهٍ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'أَحَدُهَا: أَنه ذَلِكَ الُْجزْءَ النهارِيه إِمها أَنْ يُدهعَى أَنههُ نَـزَلَ عَنِ الَْأثِيِر، وَاخْ تَـلَطَ بَِهذِهِ الَْأجْ زَاءِ الْمَائِيهةِ وَالَْأرْضِ يهةِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'أَوْ يُـقَالُ: إنههُ تَـوَهلدَ فِيهَا وَتَكَ هونَ، وَالَْأهولُ مُسْتَـبْـعَدٌ لِوَجْ هَيِْن، أَحَدُ هَُاُ: أَنه النهارَ بِالطهبْعِ صَاعِدَةٌ، فَـلَوْ نَـزَلَتْ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'لَكَانَتْ بِقَاسِرٍ مِنْ مَرْكَزِهَا إِلَى هَذَا الْعَالََِ. الثهانِي: أَنه تِلْكَ الَْأجْ زَاءَ النهارِيهةَ لابدّ فِي نُـزُولَِها أَنْ تَـعْبُـرَ عَلَى كُرَةِ الهزمْهَرِيرِ الهتِي هِيَ فِي غَايَةِ الْبَـرْدِ، وَنَنُْْ نُشَاهِدُ في هذا العالَ أن النار العظيمة تنطفىء بِالْمَاءِ الْقَلِيلِ، فَتِلْكَ الَْأجْزَاءُ الصهغِيَرةُ عِنْدَ مُرُورِهَا بِكُرَةِ الهزمْهَرِيرِ الهتِي هِيَ فِي غَايَةِ الْبَـرْدِ، وَنَِهايَةِ الْعِظَمِ أَوْلَى بِالِانْطِفَاءِ. وَأَمها الثهانِي- وَهُوَ أن يقال: إنها تكونت ها هنا- فَـهُوَ أَبْـعَدُ وَأَبْـعَدُ، لَِأنه الِْجسْمَ الهذِي صَارَ نَارًا بَـعْدَ أَنْ لََْ يَكُنْ كَذَلِكَ ، قَدْ كَانَ قَـبْلَ صَيْـرُورَتِهِ إِمها أَرْضًا، وَإِمها مَاءً، وَإِمها هَوَاءً لِانِْصَْارِ الَْأرْكَانِ فِي هَذِهِ الَْأرْبَـعَةِ، وَهَذَا الهذِي قَدْ صَارَ نَارًا أَهولًا، كَانَ مُْختَلِطًا بَِأحَدِ هَذِهِ الَْأجْسَامِ، وَمُتهصِلًا بَِها، وَالِْجسْمُ الهذِي لَا يَكُونُ نَارًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'إِذَا اخْتَـلَطَ بَِأجْسَامٍ عَظِيمَةٍ لَيْسَتْ بِنَارٍ وَلَا وَاحِدٍ مِنْـهَا، لَا يَكُونُ مُسْتَعِدًّا لَِأنْ يَـنْـقَلِبَ نَارًا لَِأنههُ فِي نَـفْسِهِ لَيْسَ بِنَارٍ، وَالَْأجْسَامُ الْمُخْتَلِطَةُ بَارِدَةٌ، فَكَيْفَ يَكُونُ مُسْتَعِدًّا لِانْقِلَابِهِ نَارًا؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'فَإِنْ قُـلْتُمْ: لََِ لَا تَكُونُ هُنَاكَ أَجْ زَاءٌ نَارِيهةٌ تَـقْلِبُ هَذِهِ الَْأجْسَامَ، وَتَعََْلُهَا نَارًا بِسَبَبِ مَُخالَطَتِهَا إهياهَا؟ قُـلْنَا: الْكَلَامُ فِي حُصُولِ تِلْكَ الَْأجْ زَاءِ النهارِيهةِ كَالْكَلَامِ فِي الَْأهولِ، فَإِنْ قُـلْتُمْ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'إهنا نَـرَى مِنْ رَشِّ الْمَاءِ عَلَى النهـوْرَةِ »7« الْمُطْفَأَةِ تَـنْـفَصِلُ مِنْـهَا نارا، وَإِذَا وَقَعَ شُعَاعُ الشهمْسِ عَلَى الْبَـلُّورَةِ، ظَهَرَتِ النهارُ مِنْـهَا، وَإِذَا ضَرَبْـنَا الَْحجَرَ عَلَى الَْحدِيدِ، ظَهَرَتِ النهارُ، وَكُلُّ هَذِهِ النهارِيهةِ حَدَثَتْ عِنْدَ الِاخْتِلَاطِ، وَذَلِكَ يُـبْطِلُ مَا قَـهررْتُوَُهُ فِي الْقِسْمِ الَْأهولِ أَيْضًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'قَالَ الْمُنْكِرُونَ: نَنُْْ لَا نُـنْكِرُ أن تكون المصاكّة ]2[ لشديدة مُدُِْثَةً لِلنهارِ، كَمَا فِي ضَرْبِ الِْحجَارَةِ عَلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'الَْحدِيدِ، أَوْ تَكُونُ قُـهوةُ تَسْخِيِن الشهمْسِ مُدُِْثَةً لِلنهارِ، كَمَا فِي الْبَـلُّورَةِ، لَكِنها نَسْتَـبْعِدُ ذَلِكَ جِدًّا فِي أَجْرَامِ النهـبَاتِ وَالَْحيَـوَانِ، إذْ لَيْسَ في أجرامها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, '(7) تطلعه النّورة على حجر الكلس، م غلب هذا اللفظ على مواد تضاف إلى الكلس من زرنيخ وغيره.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'مِنَ الِاصْطِكَاكِ مَا يُوجِبُ حُدُوثَ النهارِ، وَلَا فِيهَا مِنَ الصهفَاءِ وَالصِّقَالِ مَا يَـبْـلُغُ إِلَى حَدِّ الْبَـلُّورَةِ، كَيْفَ وَشُعَاعُ الشهمْسِ يَـقَعُ عَلَى ظَاهِرِهَا، فَلَا تَـتَـوَلهدُ النهارُ الْبَـتهةَ، فَالشُّعَاعُ الهذِي يَصِلُ إِلَى بَاطِنِهَا كَيْفَ يُـوَلِّدُ النهارَ؟.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'الْوَجْ هُ الثهانِي: فِي أَصْلِ الْمَسْأَلَةِ: أَنه الَْأطِبهاءَ مُمَِْعُونَ عَلَى أَنه الشهرَابَ الْعَتِيقَ فِي غَايَةِ السُّخُونَةِ بِالطهبْعِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'فَـلَوْ كَانَتْ تِلْكَ السُّخُونَةُ بِسَبَبِ الَْأجْ زَاءِ النهارِيهةِ، لَكَانَتْ مُاَُلًا إذْ تِلْكَ الَْأجْ زَاءُ النهارِيهةُ مَعَ حَقَارَتَِها كَيْفَ يُـعْقَلُ بَـقَاؤُهَا فِي الَْأجْ زَاءِ المائية الغالبة دهرا طويلا، بحيث لا تنطفىء مَعَ أَهنا نَـرَى النهارَ الْعَظِيمَةَ تُطْفَأُ بِالْمَاءِ الْقَلِيلِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'الْوَجْ هُ الثهالِثُ : أَنههُ لَوْ كَانَ فِي الَْحيَـوَانِ وَالنهـبَاتِ جُزْءٌ نَارِيٌّ بِالْفِعْلِ، لَكَانَ مَغْلُوبًا بِالُْجزْءِ الْمَائِيِّ الهذِي فِيهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَكَانَ الُْجزْءُ الهنارِيُّ مَقْهُورًا بِهِ، وَغَلَبَةُ بَـعْضِ الطهبَائِعِ وَالْعَنَاصِرِ عَلَى بَـعْضٍ يَـقْتَضِي انْقِلَابَ طَبِيعَةِ الْمَغْلُوبِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'إِلَى طَبِيعَةِ الغالب، فكان يلزم بالضرورة انقلاؤب تِلْكَ الَْأجْ زَاءِ النهارِيهةِ الْقَلِيلَةِ جِدًّا إِلَى طَبِيعَةِ الْمَاءِ الهذِي هُوَ ضِدُّ النهارِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'الْوَجْ هُ الهرابِعُ: أَنه ا هللََّ سُبْحَانَهُ وَتَـعَالَى ذكََرَ خَلْقَ الِْإنْسَانِ فِي كِتَابِهِ فِي مَوَاضِعَ مُتَـعَدِّدَةٍ، يُْخبَُِ فِي بَـعْضِهَا أَنههُ خَلَقَهُ مِنْ مَاءٍ، وَفِي بَـعْضِهَا أَنههُ خَلَقَهُ مِنْ تُـرَابٍ، وَفِي بَـعْضِهَا أَنههُ خَلَقَهُ مِنَ الْمُرَكهبِ مِنْـهُمَا وَهُوَ الطِّيُن،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'وَفِي بَـعْضِهَا أَنههُ خَلَقَهُ مِنْ صَلْصَالٍ كَالْفَخهارِ، وَهُوَ الطِّيُن الهذِي ضَرَبَـتْهُ الشهمْسُ وَالرِّيحُ حَ هتى صَارَ صَلْصَالًا كَالْفَخهارِ، وَلََْ يُْخبَِْ فِي مَوْضِ عٍ وَاحِدٍ أَنههُ خَلَقَهُ مِنْ نَارٍ، بَلْ جَعَلَ ذَلِكَ خَاصِّ يهةَ إبْلِيسَ . وَثَـبَتَ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, '«صَحِيحِ مسلم» : عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ» خُلِقَتِ الْمَلَائِكَةُ مِنْ نُورٍ، وَخُلِقَ الَْجانُّ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'مَارِجٍ مِنْ نَارٍ، وَخُلِقَ آدَمُ مِمها وُصِفَ لَكُمْ» »7« . وَهَذَا صَرِيحٌ فِي أَنههُ خُلِقَ مِمها وَصَفَهُ ا هللَُّ فِي كِتَابِهِ فَـقَطْ ، وَلََْ يَصِفْ لَنَا سُبْحَانَهُ أَنههُ خَلَقَهُ مِنْ نَارٍ، وَلَا أَنه فِي مَادهتِهِ شَيْـئًا مِنَ النهارِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'الْوَجْ هُ الَْخامِسُ : أَنه غَايَةَ مَا يَسْتَدِلِّونَ بِهِ مَا يُشَاهِدُونَ مِنَ الَْحرَارَةِ فِي أَبْدَانِ الَْحيَـوَانِ، وَهِيَ دَلِيلٌ عَلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'الَْأجْ زَاءِ الهنارِيهةِ، وَهَذَا لَا يَدُلُّ، فَإِنه أَسْبَابَ الَْحرَارَةِ أَعَمُّ مِنَ الهنارِ، فَإِنَِّها تَكُونُ عَنِ النهارِ تَارَةً، وَعَنِ الَْحرَكَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'أُخْ رَى، وَعَنِ انْعِكَاسِ الَْأشِعهةِ، وَعَنْ سُخُونَةِ الَْهوَاءِ، وَعَنْ مُاََوَرَةِ النهارِ، وَذَلِكَ بِوَاسِطَةِ سُخُونَةِ الَْهوَاءِ أَيْضًا، وَتَكُونُ عَنْ أَسْبَابٍ أُخَرَ، فَلَا يَـلْزَمُ مِنَ الَْحرَارَةِ النار.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, '(7) لَ يخرجه البخاري. وقد رواه الإمام أحدْ والإمام مسلم في آخر صحيحه عن عائشة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'قَالَ أَصْحَابُ النهارِ: مِنَ الْمَعْلُومِ أَنه التُّـرَابَ وَالْمَاءَ إِذَا اخْتَـلَطَا فَلَا بُده لَهمَُا مِنْ حَرَارَةٍ تَـقْتَضِي طَبْخَهُمَا وَامْتِزَاجَهُمَا، وَإِهلا كَانَ كُلٌّ مِنْـهُمَا غَيْـرَ مَُمازِجٍ لِلْخَْرِ، وَلَا مُتهحِدًا بِهِ، وَكَذَلِكَ  إِذَا أَلْقَيْـنَا الْبَذْرَ فِي الطِّيِن بَِحيْثُ لَا يَصِلُ إِلَيْهِ الَْهوَاءُ وَلَا الشهمْسُ فَسَدَ، فَلَا يَْخلُو، إِمها أَنْ يَْحصُلَ فِي الْمُرَكهبِ جِسْمٌ مُنْضِجٌ طَابِخٌ بِالطهبْعِ أَوْ لَا، فَإِنْ حَصَلَ، فَـهُوَ الُْجزْءُ النهارِيُّ، وَإِنْ لََْ يَْحصُلْ، لَ يكن المركب مسخنا بطبعه، بل بَلْ إِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'سَخهنَ كَانَ التهسْخِيُن عَرَضِيها، فَإِذَا زَالَ التهسْخِيُن الْعَرَضِ يُّ، لََْ يَكُنِ الشهيْ ءُ حَارًّا فِي طَبْعِهِ، وَلَا فِي كَيْفِيهتِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'وَكَانَ بَارِدًا مُطْلَقًا، لَكِنْ مِنَ الَْأغْذِيَةِ وَالَْأدْوِيَةِ مَا يَكُونُ حارا بالطبع، فعل أَنه حَرَارَتَـهَا إِهنَما كَانَتْ ، لَِأنه فِيهَا جَوْهَرًا نَارِيًّا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'وَأَيْضًا فَـلَوْ لََْ يَكُنْ فِي الْبَدَنِ جُزْءٌ مُسَخِّ نٌ لَوَجَبَ أَنْ يَكُونَ فِي نَِهايَةِ الْبَـرْدِ، لَِأنه الطهبِيعَةَ إِذَا كَانَتْ مُقْتَضِيَةً', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'لِلْبَـرْدِ، وَكَانَتْ خَالِيَةً عَنِ الْمُعَاوِنِ وَالْمُعَارِضِ ، وَجَبَ انْتِهَاءُ الْبَـرْدِ إِلَى أَقْصَى الْغَايَةِ، وَلَوْ كَانَ كَذَلِكَ لَمَا حَصَلَ لََها الِْإحْسَاسُ بِالْبَـرْدِ، لَِأنه الْبَـرْدَ الْوَاصِلَ إِلَيْهِ إِذَا كَانَ فِي الْغَايَةِ كَانَ مِثْـلَهُ، وَالشهيْ ءُ لَا يَـنْـفَعِلُ عَنْ مِثْلِهِ، وَإِذَا لََْ يَـنْـفَعِلْ عَنْهُ لََْ يَُحسه بِهِ، وَإِذَا لََْ يَُحسه بِهِ لََْ يَـتَأَهلَْ عَنْهُ، وَإِنْ كَانَ دُونَهُ فَـعَدَمُ الِانْفِعَالِ يَكُونُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 48, 'أَوْلَى، فَـلَوْ لََْ يَكُنْ فِي الْبَدَنِ جُزْءٌ مُسَخِّ نٌ بِالطهبْعِ لَمَا انْـفَعَلَ عَنِ الْبَـرْدِ، وَلَا تَهََلََ بِهِ. قَالُوا: وَأَدِلهتُكُمْ إِهنَما', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 49, 'تُـبْطِلُ قَـوْلَ مَنْ يَـقُولُ: الَْأجْ زَاءُ النهارِيهةُ بَاقِيَةٌ فِي هَذِهِ الْمُرَكهبَاتِ عَلَى حَالِهاَ، وَطَبِيعَتِهَا النهارِيهةِ، وَنَنُْْ لَا نَـقُولُ بِذَلِكَ ، بَلْ نَـقُولُ: إِنه صُورَتَـهَا النهـوْعِيهةَ تَـفْسُدُ عِنْدَ الِامْتِزَاجِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 50, 'قَالَ الْآخَرُونَ «لََِ لَا يَُجوزُ أَنْ يُـقَالَ: إِنه الَْأرْضَ وَالْمَاءَ وَالَْهوَاءَ إِذَا اخْتَـلَطَتْ ، فَالَْحرَارَةُ الْمُنْضِجَةُ الطهاخِةَُِ لَهاَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 51, 'هِيَ حَرَارَةُ الشهمْسِ وَسَائِرِ الْكَوَاكِبِ، ُ مه ذَلِكَ الْمُرَكهبُ عِنْدَ كَمَالِ نضجه مستعد لقبور الْهيَْـئَةِ التهـرْكِيبِيهةِ بِوَاسِطَةِ السُّخُونَةِ نَـبَاتًا كَانَ أَوْ حَيَـوَانًا أَوْ مَعْدِنًا، وَمَا الْمَانِعُ أَنه تِلْكَ السُّخُونَةَ وَالَْحرَارَةَ الهتِي فِي الْمُرَكهبَاتِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 52, 'هِيَ بِسَبَبِ خَوَاصه وَقُـوًى يُْحدِثُـهَا ا هللَُّ تَـعَالَى عِنْدَ ذَلِكَ الِامْتِزَاجِ لَا مِنْ أَجْزَاءٍ نَارِيهةٍ بِالْفِعْلِ؟ وَلَا سَبِيلَ لَكُمْ إِلَى إِبْطَالِ هَذَا الِْإمْكَانِ الْبَـتهةَ، وَقَدِ اعْتَـرَفَ جَاََعَةٌ مِنْ فُضَلَاءِ الَْأطِبهاءِ بِذَلِكَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 53, 'وَأَمها حَدِيثُ إِحْسَاسِ الْبَدَنِ بِالْبَـرْدِ، فَـنَـقُولُ: هَذَا يَدُلُّ عَلَى أَنه فِي الْبَدَنِ حَرَارَةً وَتَسْخِينًا، وَمَنْ يُـنْكِرُ ذَلِكَ ؟ لَكِنْ مَا الدهلِيلُ عَلَى انِْصَْارِ الْمُسَخِّ نِ فِي النهارِ، فَإِنههُ وَإِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 54, 'كَانَ كُلُّ نَارٍ مُسَخِّ نًا، فَإِنه هَذِهِ الْقَضِ يهةَ لَا تَـنْـعَكِسُ كُلِّيهةً، بَلْ عَكْسُهَا الصهادِقُ بَـعْضُ الْمُسَخِّ نِ نَارٌ. وَأَمها قَـوْلُكُمْ بِفَسَادِ صُورَةِ النهارِ النهـوْعِيهةِ، فَأَكْ ثَـرُ الَْأطِبهاءِ عَلَى بَـقَاءِ صُورَتَِها، النهـوْعِيهةِ، وَالْقَوْلُ بِفَسَادِهَا قَـوْلٌ فَاسِدٌ قَدِ اعْتَـرَفَ بِفَسَادِهِ أفضل متأخريكم »7« في كتابه المسمى بالشفاء، وَبَـرْهَنَ عَلَى بَـقَاءِ الَْأرْكَانِ أَجْعَََ عَلَى طَبَائِعِهَا في المركبات. وبالله التوفيق.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل: في علاجه ص للمرض', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَكَانَ عِلَاجُهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لِلْمَرَضِ ثَلَاثَةَ أَنْـوَاعٍ : أَحَدُهَا: بِالَْأدْوِيَةِ الطهبِيعِيهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَالثهانِي: بِالَْأدْوِيَةِ  الِْإلَِهيهةِ. وَالثهالِثُ : بِالْمُرَكهبِ مِنَ الَْأمْرَيْنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَنَنُْْ نَذْكُرُ الَْأنْـوَاعَ الثهلَاثَةَ مِنْ هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَـنَـبْدَأُ بِذِكْرِ الَْأدْوِيَةِ الطهبِيعِيهةِ الهتِي وَصَفَهَا وَاسْتَـعْمَلَهَا، ُ مه نَذْكُرُ الَْأدْوِيَةَ الِْإلَِهيهةَ، ُ مه الْمُرَكهبَةَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَهَذَا إِنَِّما نُشِيُر إِلَيْهِ إِشَارَةً، فَإِنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إِنَِّما بُعِثَ هَادِيًا، وَدَاعِيًا إِلَى ا هلِلَّ، وَإِلَى جَنهتِهِ، وَمُعَرِّفًا بَِا هلِلَّ، وَمُبَـيِّنًا لِلْمُِهةِ مَوَاقِعَ رِضَاهُ وَآمِرًا لَهمُْ بَِها، وَمَوَاقِعَ سَخَطِهِ وَنَاهِيًا لَهمُْ عَنْـهَا، وَمُْخبِهََُمْ أَخْ بَارَ الَْأنْبِيَاءِ وَالرُّسُلِ وَأَحْوَالَهمُْ مَعَ أُمَِمهِمْ، وَأَخْ بَارَ تَْخلِيقِ الْعَالََِ، وَأَمْرَ الْمَبْدَأِ وَالْمَعَادِ، وَكَيْفِيهةَ شَقَاوَةِ النُّـفُوسِ وَسَعَادَتَِها، وَأَسْبَابَ ذَلِكَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَأَمها طِبُّ الَْأبْدَانِ «فَجَاءَ مِنْ تَكْمِيلِ شَرِيعَتِهِ، وَمَقْصُودًا لِغَيِْرهِ، بَِحيْثُ إِهنَما يُسْتَـعْمَلُ عِنْدَ الَْحاجَةِ إِلَيْهِ، فَإِذَا قَدَرَ عَلَى الِاسْتِغْنَاءِ عَنْهُ، كَانَ صَرْفُ الِْهمَمِ وَالْقُوَى إِلَى عِلَاجِ الْقُلُوبِ وَالَْأرْوَاحِ، وَحِفْظِ صِحهتِهَا، وَدَفْعِ أَسْقَامِهَا، وَحِيَْْتِهَا مِمها يُـفْسِدُهَا هُوَ الْمَقْصُودَ بِالْقَصْدِ الَْأهولِ، وَإِصْلَاحُ الْبَدَنِ بِدُونِ إِصْلَاحِ الْقَلْبِ لَا يَـنْـفَعُ، وَفَسَادُ الْبَدَنِ مَعَ إِصْلَاحِ الْقَلْبِ مَضَ هرتُهُ يَسِيَرةٌ جِدًّا، وَهِيَ مَضَ هرةٌ زَائِلَةٌ تَـعْقُبُـهَا الْمَنْـفَعَةُ الدائمة التامة، وبالله التوفيق.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(7) أي الشيخ الرئيس أبو علي الحسين بن عبد الله بن سينا توفي عام 429 هـ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'ذِكْ رُ الْقِسْمِ الَْأهولِ وَهُوَ الْعِلَاجُ بِالَْأدْوِيَةِ الطهبِيعِيهةِ فَصْلٌ فِي هَدْيِهِ فِي عِلَاجِ الُْحمهى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'ثَـبَتَ فِي «الصهحِيحَيِْن» : عَنْ نافع، عَنِ ابْنِ عُمَرَ، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ: «إنّما الحمىّ أو شدّة مِنْ فَـيْحِ جَهَنهمَ، فَأَبْرِدُوهَا بِالْمَاءِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَقَدْ أَشْكَلَ هَذَا الَْحدِيثُ عَلَى كَثِيٍر مِنْ جَهَلَةِ الَْأطِبهاءِ، وَرَأَوْهُ مُنَافِيًا لِدَوَاءِ الُْحمهى وَعِلَاجِهَا، وَنَنُْْ نُـبَـيُِّن بَِحوْلِ ا هلِلَّ وَقُـهوتِهِ وَجْ هَهُ وَفِقْهَهُ، فَـنَـقُولُ: «خِطَابُ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ نَـوْعَانِ: عَامٌّ لَِأهْلِ الَْأرْضِ ، وَخَاصٌّ بِبَـعْضِهِمْ، فَالَْأهولُ «كَعَامهةِ خِطَابِهِ، وَالثهانِي: كَقَوْلِهِ: «لَا تَسْتَـقْبِلُوا الْقِبْـلَةَ بِغَائِطٍ» . وَلَا بول، ولا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'تسدبروها، وَلَكِنْ شَرِّقُوا، أَوْ غَرِّبُوا» »2« ، فَـهَذَا لَيْسَ خِِطَِابٍ لَِأهْلِ الْمَشْرِقِ وَالْمَغْرِبِ وَلَا الْعِرَاقِ، وَلَكِنْ لَِأهْلِ الْمَدِينَةِ وَمَا عَلَى سَْمتِهَا، كَالشهامِ وَغَيِْرهَا. وَكَذَلِكَ قَـوْلُهُ: «مَا بَـيَْن الْمَشْرِقِ وَالْمَغْرِبِ قِبْـلَةٌ» »', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, '.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَإِذَا عُرِفَ هَذَا، فَخِطَابُهُ فِي هَذَا الَْحدِيثِ خَاصٌّ بأهل الحجاز، وما وَالَاهُمْ، إِذْ كَانَ أَكْثَـرُ الُْحمِّيهاتِ الهتِي تَـعْرِضُ لَهمُْ مِنْ نَـوْعِ الُْحمهى الْيَـوْمِيهةِ الْعَرَضِ يهةِ الَْحادِثَةِ عَنْ شِدهةِ حَرَارَةِ الشهمْسِ ، وَهَذِهِ يَـنْـفَعُهَا الْمَاءُ الْبَارِدُ شُرْبًا وَاغْتِسَالًا، فَإِنه الُْحمهى حَرَارَةٌ غَرِيبَةٌ تَشْتَعِلُ فِي الْقَلْبِ، وَتَـنْـبَثُّ مِنْهُ بِتَـوَسُّطِ الرُّوحِ وَالدهمِ فِي الشهرَايِيِن وَالْعُرُوقِ إِلَى جَِيَعِ الْبَدَنِ، فَـتَشْتَعِلُ فِيهِ اشْتِعَالًا يُضِرُّ بِالَْأفْـعَالِ الطهبِيعِيهةِ، وَهِيَ تَـنْـقَسِمُ إِلَى قِسْمَيِْن:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'عَرَضِ يهةٌ: وَهِيَ الَْحادِثَةُ إِمها عَنِ الْوَرَمِ، أَوِ الَْحرَكَةِ، أَوْ إِصَابَةِ حَرَارَةِ الشمس، أو القيظ الشديد، ونوْ ذلك.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, '(7) أخرجه الإمام أحدْ، والبخاري عن ابن عباس في الطب- ورواه مسلم في السلام: باب لكل داء دواء', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, '(2) أخرجه البخاري في القبلة. ومسلم في الطهارة. قال البغوي: هذا خطاب لأهل المدينة، ولمن كانت قبلته على ذلك السمت. فأما من كانت جهته إلى المشرق والمغرب فإنه ينحرف إلى الجنوب أو الشمال.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, '(3) أخرجه الترمذي وابن ماجه والحاكم في الصلاة عن أبي هريرة. قال الترمذي- حسن صحيح. وقال الحاكم صحيح على شرطهما. أي البخاري ومسلم. وأقره الذهب وقال النسائي منكر. وأقره عليه الحافظ العراقي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَمَرَضِ يهةٌ: وَهِيَ ثَلَاثَةُ أَنْـوَاعٍ ، وَهِيَ لَا تَكُونُ إِهلا فِي مَادهةٍ أُولَى، ُ مه مِنْـهَا يُسَخهنُ جَِيَعُ الْبَدَنِ، فَإِنْ كَانَ مَبْدَأُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'تَـعَلُّقِهَا بِالرُّوحِ سُِّميَتْ حُهْى يَـوْمٍ، لَِأنهـهَا فِي الْغَالِبِ تَـزُولُ فِي يَـوْمٍ، وَنَِهايَـتُـهَا ثَلَاثَةُ أَهيامٍ، وَإِنْ كَانَ مَبْدَأُ تَـعَلُّقِهَا بِالَْأخْلَاطِ سُِّميَتْ عَفَنِيهةً، وَهِيَ أَرْبَـعَةُ أصناف: صفراوية، وسوداوية، بلغمية، وَدَمَوِيهةٌ. وَإِنْ كَانَ مَبْدَأُ تَـعَلُّقِهَا بِالَْأعْضَاءِ الصُّلْبَةِ الَْأصْلِيهةِ، سُِّميَتْ حُهْى دِقٍّ ، وَتَتََْ هَذِهِ الَْأنْـوَاعِ أَصْنَافٌ كَثِيَرةٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَقَدْ يَـنْـتَفِعُ الْبَدَنُ بِالُْحمهى انْتِفَاعًا عَظِيمًا لَا يَـبْـلُغُهُ الدهوَاءُ، وَكَثِيًرا مَا يَكُونُ حُهْى يَـوْمٍ، وَحُهْى الْعَفَنِ سَبَـبًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'لِِإنْضَاجِ مَوَاده غَلِيظَةٍ لََْ تَكُنْ تَـنْضَجُ بِدُونَِها، وَسَبَـبًا لِتَـفَتُّحِ سُدَدٍ لََْ يَكُنْ تَصِلُ إِلَيْـهَا الَْأدْوِيَةُ الْمُفَتِّحَةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وأما الرمد الحديث والمتقادم، فإنها تبىَء أكثر أنواعه برآ عَجِيبًا سَرِيعًا، وَتَـنْـفَعُ مِنَ الْفَالِجِ، وَاللِّقْوَةِ »7« ، وَالتهشَنُّجِ الأمتلائي، وكثيرا مِنَ الَْأمْرَاضِ الَْحادِثَةِ عَنِ الْفُضُولِ الْغَلِيظَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَقَالَ لِِ بَـعْضُ فُضَلَاءِ الَْأطِبهاءِ: إِنه كَثِيًرا مِنَ الَْأمْرَاضِ نَسْتَـبْشِرُ فِيهَا بِالُْحمهى، كَمَا يَسْتَـبْشِرُ الْمَرِيضُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'بِالْعَافِيَةِ، فَـتَكُونُ الُْحمهى فِيهِ أَنْـفَعَ مِنْ شُرْبِ الدهوَاءِ بِكَثِيٍر، فَإِنهـهَا تُـنْضِجُ مِنَ الَْأخْلَاطِ وَالْمَوَادِّ الْفَاسِدَةِ مَا يَضُرُّ بِالْبَدَنِ، فَإِذَا أَنْضَجَتْـهَا صَادَفَـهَا الدهوَاءُ مُتَـهَيِّئَةً لِلْخُرُوجِ بِنِضَاجِهَا، فَأَخْ رَجَهَا، فَكَانَتْ سَبَـبًا لِلشِّ فَاءِ. وَإِذَا عُرِفَ هَذَا، فَـيَجُوزُ أَنْ يَكُونَ مُرَادُ الَْحدِيثِ مِنْ أَقْسَامِ الُْحمِّيَاتِ الْعَرَضِ يهةِ، فَإِنَِّها تَسْكُنُ عَلَى الْمَكَانِ بِالِانْغِمَاسِ فِي الْمَاءِ الْبَارِدِ، وَسَقْيِ الْمَاءِ الْبَارِدِ الْمَثْـلُوجِ، وَلَا يَْحتَاجُ صَاحِبُـهَا مَعَ ذَلِكَ إِلَى عِلَاجٍ آخَرَ، فَإِنَِّها مُهََردُ كَيْفِيهةٍ حَارهةٍ مُتَـعَلِّقَةٍ بِالرُّوحِ، فَـيَكْفِي فِي زَوَالَِها مُهََردُ وُصُولِ كَيْفِيهةٍ بَارِدَةٍ تُسَكِّنُـهَا، وَتُْخمِدُ لَهبََـهَا مِنْ غَيِْر حَاجَةٍ إِلَى اسْتِفْرَاغِ مَادهةٍ، أَوِ انْتِظَارِ نُضْجٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَيَُجوزُ أَنْ يُـرَادَ بِهِ جَِيَعُ أَنْـوَاعِ الُْحمِّيَاتِ، وَقَدِ اعْتَـرَفَ فَاضِلُ الَْأطِبهاءِ جالينوس: بَِأنه الْمَاءَ الْبَارِدَ يَـنْـفَعُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'فِيهَا، قَالَ فِي الْمَقَالَةِ الْعَاشِرَةِ مِنْ كِتَابِ «حِيلَةِ الْبُـرْءِ» : وَلَوْ أَنه رَجُلًا شَاهبا حَسَنَ اللهحْمِ، خِصْبَ الْبَدَنِ فِي وَقْتِ الْقَيْظِ، وَفِي وَقْتِ مُنْـتَـهَى الُْحمهى، وَلَيْسَ فِي أَحْشَائِهِ وَرَمٌ، اسْتَحَمه بَِماءٍ بَارِدٍ، أو سبح فيه، لا نتفع بذلك. قال: وننْ نأمر بذلك بلا توقف.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, '(7) داء يكون في الوجه يعوج منه الشدق', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَقَالَ الرازي فِي كِتَابِهِ الْكَبِيِر: إِذَا كَانَتِ الْقُهوةُ قَوِيهةً، وَالُْحمهى حَادهةً جِدًّا، وَالنُّضْجُ بَـيٌِّن وَلَا وَرَمَ فِي الَْجوْفِ، وَلَا فَـتْقَ، يَـنْـفَعُ الْمَاءُ الْبَارِدُ شُرْبًا، وَإِنْ كَانَ الْعَلِيلُ خِصْبَ الْبَدَنِ وَالهزمَانُ حَارٌّ، وَكَانَ مُعْتَادًا لِاسْتِعْمَالِ الْمَاءِ الْبَارِدِ مِنْ خَارِجٍ، فَـلْيُـؤْذَنْ فِيهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَقَـوْلُهُ: «الُْحمهى مِنْ فَـيْحِ جَهَنهمَ» ، هُوَ شِدهةُ لَهبَِهَا، وَانْتِشَارِهَا، وَنَظِيُرهُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, '«قَـوْلُهُ: شِدهةُ الَْحرِّ مِنْ فَـيْحِ جَهَنهمَ» . وَفِيهِ وَجْ هَانِ: أَحَدُ هَُاُ: أَنه ذَلِكَ أُنُْموذَجٌ وَرَقِيقَةٌ اُشْتُـقهتْ مِنْ جَهَنهمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'لِيَسْتَدِ هل بَِها الْعِبَادُ عَلَيْـهَا، وَيَـعْتَبِوَُا بَِها، ُ مه إِنه ا هللََّ سُبْحَانَهُ قَدهرَ ظُهُورَهَا بَِأسْبَابٍ تَـقْتَضِيهَا،؛ كَمَا أَنه الرُّوحَ وَالْفَرَحَ وَالسُّرُورَ وَاللهذهةَ مِنْ نَعِيمِ الَْجنهةِ أَظْهَرَهَا ا هللَُّ فِي هَذِهِ الدهارِ عِبْـرَةً وَدَلَالَةً، وَقَدهرَ ظُهُورَهَا بَِأسْبَابٍ تُوجِبُـهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'وَالثهانِي: أَنْ يَكُونَ الْمُرَادُ التهشْبِيهَ، فَشَبههَ شِدهةَ الُْحمهى وَلََهبَـهَا بِفَيْحِ جَهَنهمَ، وَشَبههَ شِدهةَ الَْحرِّ بِهِ أَيْضًا تَـنْبِيهًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'لِلنُّـفُوسِ عَلَى شِدهةِ عَذَابِ الهنارِ، وَأَنه هَذِهِ الَْحرَارَةَ الْعَظِيمَةَ مُشَبهـهَةٌ بِفَيْحِهَا، وَهُوَ مَا يُصِيبُ مَنْ قَـرُبَ مِنْـهَا مِنْ حَرِّهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وَقَـوْلُهُ: «فَأَبْرِدُوهَا» ، رُوِيَ بِوَجْ هَيِْن: بِقَطْعِ الَْهمْزَةِ وَفَـتْحِهَا، رُبَاعِيٌّ: مِنْ أَبْـرَدَ الشهيْ ءَ: إِذَا صَيهـرَهُ بَارِدًا، مِثْلَ أَسْخَنَهُ: إِذَا صَيهـرَهُ سَخِنًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'وَالثهانِي: بَِهمْزَةِ الْوَصْلِ مَضْمُومَةً مِنْ بَـهردَ الشهيْ ءَ يُـبَـرِّدُهُ، وَهُوَ أَفْصَحُ لُغَةً وَاسْتِعْمَالًا، وَالرُّبَاعِيُّ لُغَةٌ رَدِيئَةٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'عِنْدَهُمْ قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'إِذَا وَجَدْتُ لَِهيبَ الُْحبِّ فِي كَبِدِي ... أَقْـبَـلْتُ نَوَْْ سِقَاءِ الْقَوْمِ أَبْـتَِردُ هَبْنِِ بَـرَدْتُ بِبَـرْدِ الْمَاءِ ظَاهِرَهُ ... فَمَنْ لِنَارٍ عَلَى الَْأحْشَاءِ تَـتهقِدُ وَقَـوْلُهُ: «بِالْمَاءِ» فِيهِ قَـوْلَانِ: أَحَدُهُاَُ: أَنههُ كُلُّ مَاءٍ وَهُوَ الصهحِيحُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'وَالثهانِي: أَنههُ مَاءُ زَمْزَمَ، وَاحْ تَجه أَصْحَابُ هَذَا الْقَوْلِ بَِما رَوَاهُ الْبُخَارِيُّ فِي «صَحِيحِهِ» ، عَنْ أبي جرَة نصر', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'بن عمران الضبعي، قَالَ: كُنْتُ أُجَالِسُ ابْنَ عَبهاسٍ بَِمكهةَ، فَأَخَذَتْنِِ الُْحمهى، فَـقَالَ: أَبْرِدْهَا عَنْكَ بَِماءِ زَمْزَمَ، فَإِنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'فِيهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'قَالَ: «إِنه الُْحمهى مِنْ فَـيْحِ جَهَنهمَ فَأَبْرِدُوهَا بِالْمَاءِ، أَوْ قَالَ: بَِماءِ زَمْزَمَ» »7« . وَرَاوِي هَذَا قَدْ شَكه وَلَوْ جَزَمَ بِهِ لَكَانَ أَمْرًا لَِأهْلِ مَكهةَ بَِماءِ زَمْزَمَ، إذْ هُوَ مُتَـيَسِّ رٌ عِنْدَهُمْ، وَلِغَيِْرهِمْ بَِما عِنْدَهُمْ مِنَ الْمَاءِ. ُ مه اخْتَـلَفَ مَنْ قَالَ: إنههُ عَلَى عُمُومِهِ، هَلِ الْمُرَادُ بِهِ الصهدَقَةُ بِالْمَاءِ، أَوِ اسْتِعْمَالُهُ؟ عَلَى قَـوْلَيِْن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'وَالصهحِيحُ أَنههُ اسْتِعْمَالٌ، وَأَظُنُّ أَنه اهلذِي حَلََْ مَنْ قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'الْمُرَادُ الصهدَقَةُ بِهِ أَنههُ أَشْكَلَ عَلَيْهِ اسْتِعْمَالُ الْمَاءِ الْبَارِدِ فِي الُْحمهى، وَلََْ يَـفْهَمْ وَجْ هَهُ مَعَ أَنه لِقَوْلِهِ وَجْ هًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'حَسَنًا، وَهُوَ أَنه الَْجزَاءَ مِنْ جِنْسِ الْعَمَلِ، فَكَمَا أَخَْمدَ لَِهيبَ الْعَطَشِ عَنِ الظهمْآنِ بِالْمَاءِ الْبَارِدِ، أَخَْمدَ ا هللَُّ لَِهيبَ الُْحمهى عَنْهُ جَزَاءً وِفَاقًا، وَلَكِنه هَذَا يُـؤْخَذُ مِنْ فِقْهِ الَْحدِيثِ وَإِشَارَتِهِ، وَأَمها الْمُرَادُ بِهِ فَاسْتِعْمَالُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'وَقَدْ ذكََرَ أبو نعيم وَغَيْـرُهُ مِنْ حَدِيثِ أنس يَـرْفَـعُهُ: «إِذَا حُمه أَحَدُكُمْ، فَـلْيَـرُشه عَلَيْهِ الْمَاءَ الْبَارِدَ ثَلَاثَ لَيَالٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'مِنَ السهحَرِ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» عَنْ أَبِي هُرَيْـرَةَ يَـرْفَـعُهُ: «الُْحمهى كِيٌر مِنْ كِيِر جَهَنهمَ، فَـنَحُّوهَا عَنْكُمْ بِالْمَاءِ الْبَارِدِ»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 48, '. »3«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 49, 'وَفِي «الْمُسْنَدِ» وَغَيِْرهِ، مِنْ حَدِيثِ الحسن، عَنْ سمرة يَـرْفَـعُهُ: «الُْحمهى قِطْعَةٌ مِنَ النهارِ، فَأَبْرِدُوهَا عَنْكُمْ بِالْمَاءِ الْبَارِدِ» ، وَكَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إِذَا حُمه دَعَا بِقِرْبَةٍ مِنْ مَاءٍ، فَأَفْـرَغَهَا عَلَى رَأْسِهِ فَاغْتَسَلَ »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 50, '(7) أخرجه البخاري في بدء الخلق، والنسائي وابن ماجه ومالك وأحدْ: ومعنى الحديث: أن الحمى من شدة حر الطبيعة وهو يشبه نار جهنم في كونها معذبة ومذيبة للجسد، والمراد أنها أنموذج ودقيقة اشتقت من جهنم يستدل بها العباد ويعتبوَن بها، كما أظهر الفرح واللذة ليدل على نعيم الجة. «فأبردوها بالماء» أي أسكنوا حرارتها بالماء، بأن تغسلوا أطراف المحموم منه، وتسقوه إياه ليقع به التبدَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 51, '(2) أخرجه النسائي والحاكم في المستدرك، والطباَني في الأوسط، ورجاله ثقات (3) خرجه ابن ماجه، ورجاله ثقات', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 52, '(4) رواه الطباَني في الكبير والحاكم في الطب، وكذا الباَر عن سمرة بن جندب. قال الحاكم: صحيح، وأقره عليه الذهب. لكن قال ابن حجر في فتح الباري بعد ما عزاه للبزار والحاكم وأنه صححه في سنده راو ضعيف، وقال الهيثمي بعد ما عزاه للطباَني: فيه اسماعيل بن مسلم، وهو متروك. و «إذا حمّ أحدكم» أي أخذته الحمى التي هي حرارة بين الجلد واللحم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 53, 'وَفِي «السُّنَنِ» : مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ قَالَ: ذكُِرَتِ الُْحمهى عِنْدَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَسَبهـهَا رَجُلٌ، فَـقَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «لَا تَسُبهـهَا فَإِنهـهَا تَـنْفِي الذُّنُوبَ ، كَمَا تَـنْفِي النهارُ خَبَثَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 54, 'الَْحدِيدِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 55, 'لِمَا كَانَتِ الُْحمهى يَـتْـبَـعُهَا حِيَْْةٌ عَنِ الَْأغْذِيَةِ الهردِيئَةِ، وَتَـنَاوُلِ الَْأغْذِيَةِ وَالَْأدْوِيَةِ النهافِعَةِ، وَفِي ذَلِكَ إعانة على تنقية البدن، ونفي أخبائثه وَفُضُولِهِ، وَتَصْفِيَتِهِ مِنْ مَوَادِّهِ الهردِيئَةِ، وَتَـفْعَلُ فِيهِ كَمَا تَـفْعَلُ النهارُ فِي الَْحدِيدِ فِي نَـفْيِ خَبَثِهِ، وَتَصْفِيَةِ جَوْهَرِهِ، كَانَتْ أَشْبَهَ الَْأشْيَاءِ بِنَارِ الْكِيِر الهتِي تُصَفِّي جَوْهَرَ الَْحدِيدِ، وَهَذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 56, 'الْقَدْرُ هُوَ الْمَعْلُومُ عِنْدَ أَطِبهاءِ الَْأبْدَانِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 57, 'وَأَمها تَصْفِيَـتُـهَا الْقَلْبَ مِنْ وَسَخِهِ وَدَرَنِهِ، وَإِخْرَاجَهَا خَبَائِثَهُ، فَأَمْرٌ يَـعْلَمُهُ أَطِبهاءُ الْقُلُوبِ، وَيَِجدُونَهُ كَمَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 58, 'أَخْ بَـرَهُمْ بِهِ نَبِيُّـهُمْ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَلَكِنْ مَرَضُ الْقَلْبِ إِذَا صَارَ مَأْيُوسًا مِنْ بُـرْئِهِ، لََْ يَـنْـفَعْ فِيهِ هَذَا الْعِلَاجُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 59, 'فَالُْحمهى تَـنْـفَعُ الْبَدَنَ وَالْقَلْبَ ، وَمَا كَانَ بَِهذِهِ الْمَثَابَةِ فَسَبُّهُ ظُلْمٌ وَعُدْوَانٌ، وَذكََرْتُ مَ هرةً وَأَنَا مَمُُْومٌ قول بعض الشعراء يسبّها:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 60, 'زارت مكفّارة الذُّنُوبِ وَوَدهعَتْ ... تَـبًّا لََها مِنْ زَائِرٍ وَمُوَدِعِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 61, 'قَالَتْ وَقَدْ عَزَمَتْ عَلَى تَـرْحَالَِها ... مَاذَا تُرِيدُ فقلت ألاترجعي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 62, 'فَـقُلْتُ : تَـبًّا لَهُ إذْ سَبه مَا نَـهَى رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عن سبه، ولو قال: زارت مكفّارة الذُّنُوبِ لِصَبِّهَا ... أَهْلًا بَِها مِنْ زَائِرٍ وَمُوَدِعِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 63, 'قَالَتْ وَقَدْ عَزَمَتْ عَلَى تَـرْحَالَِها ... مَاذَا تُرِيدُ فقلت: ألاتقلعي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 64, 'لَكَانَ أَوْلَى بِهِ، وَلََأقْـلَعَتْ عَنْهُ، فَأَقْـلَعَتْ عَنِِّ سَرِيعًا. وَقَدْ رُوِيَ فِي أَثَرٍ لَا أَعْرِفُ حَالَهُ «حُهْى يَـوْمٍ كَ هفارَةُ سَنَةٍ» . وَفِيهِ قَـوْلَانِ، أحدهاُ: أن الحمّى تدخل في', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 65, '(7) أخرجه مسلم في الأدب عن جابر بن عبد الله قال: قَالَ دَخَلَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وسلم على أم السائب فقال: مالك تزقزقين؟ «ترتعدين» قالت: الحمى لا بارك الله فيها فقال لا تسب الحمى فإنها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 66, 'تذهب خطايا بنِ آدم كما يذهب الكبير خبث الحديد والحديث المذكور في الكتاب أخرجه ابن ماجه وفي سنده موسى بن عبيدة وهو ضعيف. و «الكير» هو منفاخ من زق أو جلد غليظ ذو حافات: والكلام على التشبيه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 67, 'كُلِّ الَْأعْضَاءِ وَالْمَفَاصِلِ، وَعِدهتُـهَا ثَلَاثُاَِئَةٍ وَسِتُّونَ مَفْصِلًا، فَـتُكَفِّرُ عَنْهُ- بِعَدَدِ كُلِّ مَفْصِلٍ- ذُنُوبَ يَـوْمٍ. وَالثهانِي: أَنهـهَا تُـؤَثِّرُ فِي الْبَدَنِ تَثَِْيًرا لَا يَـزُولُ بِالْكُلِّيهةِ إِلَى سَنَةٍ، كَمَا قِيلَ فِي قَـوْلِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَنْ شَرِبَ الَْخمْرَ لََْ تُـقْبَلْ لَهُ صَلَاةٌ أَرْبَعِيَن يَـوْمًا» »7« . إِنه أَثَـرَ الَْخمْرِ يَـبْـقَى فِي جَوْفِ الْعَبْدِ، وَعُرُوقِهِ، وَأَعْضَائِهِ أَرْبَعِيَن يَـوْمًا وَاَ هللَُّ أَعْلَمُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 68, 'قَالَ أبو هريرة: ما من مرض يصيا بنِ أَحَبه إلَهِ مِنَ الُْحمهى، لَِأنهـهَا تَدْخُلُ فِي كُلِّ عُضْوٍ مِنِِّ، وَإِنه ا هللََّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 69, 'سُبْحَانَهُ يُـعْطِي كُله عُضْوٍ حَظههُ مِنَ الَْأجْرِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 70, 'وَقَدْ رَوَى الترمذي فِي «جَامِعِهِ» مِنْ حَدِيثِ رَافِعِ بْنِ خَدِيجٍ يَـرْفَـعُهُ: «إِذَا أَصَابَتْ أَحَدَكُمُ الُْحمهى- وَإِنه الُْحمهى قِطْعَةٌ مِنَ النهارِ فَـلْيُطْفِئْـهَا بِالْمَاءِ الْبَارِدِ، وَيَسْتَـقْبِلْ نَـهَرًا جَارِيًا، فَـلْيَسْتَـقْبِلْ جَرْيَةَ الْمَاءِ بَـعْدَ الْفَجْرِ وَقَـبْلَ طُلُوعِ الشهمْسِ ، وَلْيَـقُلْ: بِسْمِ ا هلِلَّ اللههُمه اشْفِ عَبْدَكَ، وَصَدِّقْ رَسُولَكَ ، وَيَـنْـغَمِسُ فِيهِ ثلاث غمسات ثلاثة أيام، فإن برىء، وَإِهلا فَفِي خَْمسٍ ، فَإِنْ لََْ يَـبْـرَأْ فِي خَْمسٍ ، فَسَبْعٌ، فَإِنْ لََْ يَـبْـرَأْ فِي سَبْعٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 71, 'فَتِسْعٌ، فَإِنهـهَا لَا تَكَادُ تُاََوِزُ تِسْعًا بِِإذْنِ ا هلِلَّ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 72, 'قُـلْتُ : وَهُوَ يَـنْـفَعُ فِعْلُهُ فِي فَصْلِ الصهيْفِ فِي الْبِلَادِ الَْحارهةِ عَلَى الشهرَائِطِ الهتِي تَـقَدهمَتْ ، فَإِنه الْمَاءَ فِي ذَلِكَ الْوَقْتِ أَبْـرَدُ مَا يَكُونُ لِبُـعْدِهِ عَنْ مُلَاقَاةِ الشهمْسِ ، وَوُفُورِ الْقُوَى فِي ذَلِكَ الْوَقْتِ لَمها أَفَادَهَا النهـوْمُ، وَالسُّكُونُ، وَبَـرْدُ الَْهوَاءِ، فَـتَجْتَمِعُ فِيهِ قُـهوةُ الْقُوَى، وَقُـهوةُ الدهوَاءِ، وَهُوَ الْمَاءُ الْبَارِدُ عَلَى حَرَارَةِ الُْحمهى الْعَرَضِ يهةِ، أَوِ الْغِبِّ الَْخالِصَةِ، أَعْنِِ الهتِي لَا وَرَمَ مَعَهَا، وَلَا شَيْ ءَ مِنَ الَْأعْرَاضِ الهردِيئَةِ وَالْمَوَادِّ الْفَاسِدَةِ، فَـيُطْفِئُـهَا بِِإذْنِ ا هلِلَّ، لَا سِيِّمَا فِي أَحَدِ الَْأهيامِ الْمَذْكُورَةِ فِي الَْحدِيثِ، وَهِيَ الَْأهيامُ الهتِي يَـقَعُ فِيهَا بُْحرَانُ الَْأمْرَاضِ الَْحادهةِ كَثِيًرا، سِيِّمَا فِي الْبِلَادِ الْمَذْكُورَةِ لِرِقهةِ أَخْلَاطِ سُكهانَِها، وَسُرْعَةِ انْفِعَالِِهمْ عَنِ الدِّوَاءِ النهافِعِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 73, '(7) أخرجه الترمذي والنسائي وابن ماجه من حديث عبد الله بن عمرو بن العاص وإساده صحيح وصححه الحاكم ووافقه الذهب على ذلك.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 74, '(2) أخرجه الترمذي من حديث ثوبان وليس من حديث رافع بن خدِيج كما ذكره المصنف وأخرجه الإمام أحدْ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ فِي عِلَاجِ اسْتِطْلَاقِ الْبَطْنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'فِي «الصهحِيحَيِْن» : مِنْ حَدِيثِ أبي المتوكل، عَنْ أَبِي سَعِيدٍ الُْخدْرِيِّ ، أَنه رَجُلًا أَتَى النهبِه صَلهى ا هللَُّ عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَسَلهمَ، فَـقَالَ: إِنه أَخِي يَشْتَكِي بَطْنَهُ، وَفِي رِوَايَةٍ: اسْتَطْلَقَ بَطْنُهُ، فَـقَالَ: «اسْقِهِ عَسَلًا» ، فَذَهَبَ ُ مه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'رَجَعَ، فَـقَالَ: قَدْ سَقَيْـتُهُ، فَـلَمْ يُـغْنِ عَنْهُ شَيْـئًا. وَفِي لَفْظٍ: فَـلَمْ يَزِدْهُ إِهلا اسْتِطْلَاقًا مَ هرتَـيِْن أَوْ ثَلَاثًَ، كُلُّ ذَلِكَ يَـقُولُ لَهُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '«اسْقِهِ عَسَلًا» ، فَـقَالَ لَهُ فِي الثهالِثَةِ أَوِ الهرابِعَةِ: «صَدَقَ ا هللَُّ، وَكَذَبَ بَطْنُ أَخِيكَ » »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَفِي «صَحِيحِ مسلم» فِي لَفْظٍ لَهُ: «إِنه أَخِي عَرِبَ بَطْنُهُ» ، أَيْ فَسَدَ هَضْمُهُ، وَاعْتَـلهتْ مَعِدَتُهُ، وَالِاسْمُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الْعَرَبُ بِفَتْحِ الهراءِ، وَالذهرَبُ أَيْضًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَالْعَسَلُ فِيهِ مَنَافِعُ عَظِيمَةٌ، فَإِنههُ جَلَاءٌ لِلْوَِْسَاخِ الهتِي فِي الْعُرُوقِ وَالَْأمْعَاءِ وَغَيِْرهَا، مُلَُِّلٌ لِلرُّطُوبَاتِ أَكْلًا وَطِلَاءً، نَافِعٌ لِلْمَشَايِخِ وَأَصْحَابِ الْبَـلْغَمِ، وَمَنْ كَانَ مِزَاجُهُ بَارِدًا رَطْبًا، وَهُوَ مُغَذٍّ مُلَيٌِّن لِلطهبِيعَةِ، حَافِظٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'لِقُوَى الْمَعَاجِيِن وَلِمَا اسْتُودِعَ فِيهِ، مُذْهِبٌ لِكَيْفِيهاتِ الَْأدْوِيَةِ الْكَرِيهَةِ، مُنَقٍّ لِلْكَبِدِ وَالصهدْرِ، مُدِرٌّ لِلْبَـوْلِ، مُوَافِقٌ لِلسُّعَالِ الْكَائِنِ عَنِ الْبَـلْغَمِ، وَإِذَا شُرِبَ حَارًّا بِدُهْنِ الْوَرْدِ، نَـفَعَ مِنْ نَـهْشِ الَْهوَامِّ، وَشُرْبِ الَْأفْـيُونِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَإِنْ شُرِبَ وَحْدَهُ مَْمزُوجًا بَِماءٍ نَـفَعَ مِنْ عَضهةِ الْكَلْبِ الْكَلِبِ، وَأَكْلِ الْفِطْرِ» »2« الْقَتهالِ، وَإِذَا جُعِلَ فِيهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'اللهحْمُ الطهرِيُّ، حَفِظَ طَرَاوَتَهُ ثَلَاثَةَ أَشْهُرٍ، وَكَذَلِكَ إِنْ جُعِلَ فِيهِ الْقِثهاءُ، وَالِْخيَارُ، وَالْقَرْعُ، وَالْبَاذِنْاَْنُ، وَيَْحفَظُ كَثِيًرا مِنَ الْفَاكِهَةِ سِتهةَ أَشْهُرٍ، وَيَْحفَظُ جُثهةَ الْمَوْتَى، وَيُسَمهى الَْحافِظَ الَْأمِيَن. وَإِذَا لُطِّخَ بِهِ الْبَدَنُ الْمُقَمِّلُ وَالشهعْرُ، قَـتَلَ قَمْلَهُ وَصِ ئْـبَانَهُ، وَطَهولَ الشهعْرَ، وَحَسهنَهُ، وَنَـعهمَهُ، وَإِنِ اكْتُحِلَ بِهِ، جَلَا ظُلْمَةَ الْبَصَرِ، وَإِنِ اسْ هُتُ بِهِ، بَـيهضَ الَْأسْنَانَ وَصَقَلَهَا، وَحَفِظَ صِحهتَـهَا، وَصِحهةَ اللهثَةِ، وَيَـفْتَحُ أَفْـوَاهَ الْعُرُوقِ، وَيُدِرُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'الطهمْثَ ، وَلَعْقُهُ على الريق', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '(7) أخرجه البخاري في الطب ومسلم في السلام. (2) «الفطر» ضرب من الكمشأة قتّال. قاموس.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'يُذْهِبُ الْبَـلْغَمَ، وَيَـغْسِلُ خَْملَ الْمَعِدَةِ، وَيَدْفَعُ الْفَضَلَاتِ عَنْـهَا، وَيُسَخِّ نُـهَا تَسْخِينًا مُعْتَدِلًا، وَيَـفْتَحُ سُدَدَهَا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَيَـفْعَلُ ذَلِكَ بِالْكَبِدِ وَالْكُلَى وَالْمَثَانَةِ، وَهُوَ أَقَلُّ ضَرَرًا لِسُدَدِ الْكَبِدِ وَالطِّحَالِ مِنْ كُلِّ حُلْوٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَهُوَ مَعَ هَذَا كُلِّهِ مَأْمُونُ الْغَائِلَةِ، قَلِيلُ الْمَضَارِّ، مُضِرٌّ بِالْعَرَضِ لِلصهفْرَاوِيِّيَن، وَدَفْـعُهَا بِالَْخلِّ وَنَوِْْهِ، فَـيَـعُودُ حِينَئِذٍ نَافِعًا لَهُ جِدًّا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَهُوَ غِذَاءٌ مَعَ الَْأغْذِيَةِ، وَدَوَاءٌ مَعَ الَْأدْوِيَةِ، وَشَرَابٌ مَعَ الَْأشْرِبَةِ، وَحُلْوٌ مَعَ الَْحلْوَى، وَطِلَاءٌ مَعَ الْأطْلِيَةِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَمُفَرِّحٌ مع المفرّحات، فما خلق شَيْ ءٌ فِي مَعْنَاهُ أَفْضَلُ مِنْهُ، وَلَا مِثْـلُهُ، ولا قريبا مِنْهُ، وَلََْ يَكُنْ مُعَهولُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'الْقُدَمَاءِ إِهلا عَلَيْهِ، وَأَكْ ثَـرُ كُتُبِ الْقُدَمَاءِ لَا ذِكْ رَ فِيهَا لِلسُّكهرِ الْبَـتهةَ، وَلَا يَـعْرِفُونَهُ، فَإِنههُ حَدِيثُ الْعَهْدِ حَدَثَ قَرِيبًا، وَكَانَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يشر به بِالْمَاءِ عَلَى الرِّيقِ، وَفِي ذَلِكَ سِرٌّ بَدِيعٌ فِي حِفْظِ الصِّحهةِ لَا يُدْركُِهُ إِهلا الْفَطِنُ الْفَاضِلُ، وَسَنَذْكُرُ ذَلِكَ إِنْ شَاءَ ا هللَُّ عِنْدَ ذِكْرِ هَدْيِهِ فِي حِفْظِ الصِّحهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» مَرْفُوعًا مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ: «مَنْ لَعِقَ الْعَسَلَ ثَلَاثَ غَدَوَاتٍ كُله شَهْرٍ، لََْ يُصِبْهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'عَظِيمٌ مِنَ الْبَلَاءِ» »7« ، وَفِي أَثَرٍ آخَرَ: «عَلَيْكُمْ بِالشِّ فَاءَيْنِ: الْعَسَلِ وَالْقُرْآنِ» »2« . فَجَمَعَ بَـيَْن الطِّبِّ الْبَشَرِيِّ وَالِْإلَِهيِّ، وَبَـيَْن طِبِّ الَْأبْدَانِ ، وَطِبِّ الَْأرْوَاحِ، وَبَـيَْن الدهوَاءِ الَْأرْضِيِّ وَالدهوَاءِ السهمَائِيِّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'إذَا عُرِفَ هَذَا، فَـهَذَا الهذِي وَصَفَ لَهُ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ الْعَسَلَ، كَانَ اسْتِطْلَاقُ بَطْنِهِ عَنْ تَُخمَةٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'أَصَابَـتْهُ عَنِ امْتِلَاءٍ، فَأَمَرَهُ بِشُرْبِ الْعَسَلِ لِدَفْعِ الْفُضُولِ الْمُجْتَمِعَةِ فِي نَـوَاحِي الْمَعِدَةِ وَالَْأمْعَاءِ، فَإِنه الْعَسَلَ فِيهِ جِلَاءٌ، وَدَفْعٌ لِلْفُضُولِ، وَكَانَ قَدْ أَصَابَ الْمَعِدَةَ أَخْلَاطٌ لَزِجَةٌ، تَنََْعُ اسْتِقْرَارَ الْغِذَاءِ فِيهَا لِلُزُوجَتِهَا، فَإِنه الْمَعِدَةَ لََها خَْملٌ كَخَمْلِ الْقَطِيفَةِ، فَإِذَا عَلِقَتْ بَِها الَْأخْلَاطُ اللهزِجَةُ، أَفْسَدَتْـهَا وَأَفْسَدَتِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'الْغِذَاءَ، فَدَوَاؤُهَا بَِما يَْجلُوهَا مِنْ تِلْكَ الَْأخْلَاطِ، وَالْعَسَلُ جِلَاءٌ، وَالْعَسَلُ مِنْ أَحْسَنِ مَا عُولِجَ بِهِ هَذَا الدهاءُ، لا سيما إن مزج بالماء الحار.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, '(7) «من لعق العسل» وتخصيص الثلاث لسر علمه الشارع. والعسل يذكر ويؤنث، وأسماؤه تزيد على المائة. وأخرج الحديث ابن ماجه عن أبي هريرة. وأورده ابن الجوزي في الموضوعات. وقال العقيلي: ليس لهذا الحديث أصل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, '(2) أخرجه ابن ماجه والحاكم في الطب عن ابن مسعود. قال الحاكم: صحيح على شرطهما أي البخاري ومسلم. وقال البيهقي في الشعب: صحيح موقوف على ابن مسعود', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَفِي تَكْ رَارِ سَقْيِهِ الْعَسَلَ مَعْنًى طِبٌِّّ بَدِيعٌ، وَهُوَ أَنه الدِّوَاءَ يَِجبُ أَنْ يَكُونَ لَهُ مِقْدَارٌ، وَكَمِّيهةٌ بَِحسْبِ حَالِ الدهاءِ، إِنْ قَصَرَ عَنْهُ، لََْ يُزِلْهُ بِالْكُلِّيهةِ، وَإِنْ جَاوَزَهُ، أَوْهَى الْقُوَى، فَأَحْدَثَ ضَرَرًا آخَرَ، فَـلَمها أَمَرَهُ أَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'يَسْقِيَهُ الْعَسَلَ، سَقَاهُ مِقْدَارًا لَا يَفِي بُِمقَاوَمَةِ الدهاءِ، وَلَا يَـبْـلُغُ الْغَرَضَ ، فَـلَمها أَخْ بَـرَهُ، عَلِمَ أَنه الهذِي سَقَاهُ لَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'يَـبْـلُغُ مِقْدَارَ الَْحاجَةِ، فَـلَمها تَكَ هررَ تَـرْدَادُهُ إِلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ؛ أَكهدَ عَلَيْهِ الْمُعَاوَدَةَ لِيَصِلَ إِلَى الْمِقْدَارِ الْمُقَاوِمِ لِلدهاءِ، فَـلَمها تَكَ هررَتِ الشهرَبَاتُ بَِحسْبِ مَادهةِ الدهاءِ، بَـرَأَ، بِِإذْنِ ا هلِلَّ، وَاعْتِبَارُ مَقَادِيرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'الأدوية، وكيفياتها، ومقدار قوة المرض والمريض مِنْ أَكْ بََِ قَـوَاعِدِ الطِّبِّ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَفِي قَـوْلِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «صَدَقَ ا هللَُّ وَكَذَبَ بَطْنُ أَخِيكَ » ، إشَارَةٌ إِلَى تَقَِْيقِ نَـفْعِ هَذَا الدهوَاءِ، وَأَنه بَـقَاءَ الدهاءِ لَيْسَ لِقُصُورِ الدهوَاءِ فِي نَـفْسِهِ، وَلَكِنْ لِكَذِبِ الْبَطْنِ، وَكَثْـرَةِ الْمَادهةِ الْفَاسِدَةِ فِيهِ، فَأَمَرَهُ بِتَكْ رَارِ الدهوَاءِ لِكَثْـرَةِ الْمَادهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'وَلَيْسَ طبّه صلّى الله عليه وسلم كطبّ الأباء، فَإِنه طِبه النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مُتَـيَـقهنٌ قَطْعِيٌّ إلَِهيٌّ، صَادِرٌ عَنِ الْوَحْيِ ، وَمِشْكَاةِ النُّـبُـهوةِ، وَكَمَالِ الْعَقْلِ. وَطِبُّ غَيِْرهِ، أَكْ ثَـرُهُ حَدْسٌ وَظُنُونٌ، وَتَاََرِبُ ، وَلَا يُـنْكَرُ عَدَمُ انْتِفَاعِ كَثِيٍر مِنَ الْمَرْضَى بِطِبِّ النُّـبُـهوةِ، فَإِنههُ إِنَِّما يَـنْـتَفِعُ بِهِ مَنْ تَـلَقهاهُ بِالْقَبُولِ، وَاعْتِقَادِ الشِّ فَاءِ بِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَكَمَالُ التهـلَقِّي لَهُ بِالِْإيَمانِ وَالِْإذْعَانِ، فَـهَذَا الْقُرْآنُ الهذِي هُوَ شِفَاءٌ لِمَا فِي الصُّدُورِ- إِنْ لََْ يُـتَـلَقه هَذَا التهـلَقِّيَ- لََْ يَْحصُلْ بِهِ شِفَاءُ الصُّدُورِ مِنْ أَدْوَائِهَا، بَلْ لَا يَزِيدُ الْمُنَافِقِيَن إِهلا رِجْسًا إِلَى رِجْسِهِمْ، وَمَرَضًا إِلَى مَرَضِ هِمْ، وَأَيْنَ يَـقَعُ طِبُّ الَْأبْدَانِ مِنْهُ، فَطِبُّ النُّـبُـهوةِ لَا يُـنَاسِبُ إِهلا الَْأبْدَانَ الطهيِّبَةَ، كَمَا أَنه شِفَاءَ الْقُرْآنِ لَا يُـنَاسِبُ إِهلا الَْأرْوَاحَ الطهيِّبَةَ وَالْقُلُوبَ الَْحيهةَ، فَإِعْرَاضُ النهاسِ عَنْ طِبِّ النُّـبُـهوةِ كَإِعْرَاضِهِمْ عَنِ الِاسْتِشْفَاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'بِالْقُرْآنِ الهذِي هُوَ الشِّ فَاءُ النهافِعُ، وَلَيْسَ ذَلِكَ لِقُصُورٍ فِي الدهوَاءِ، وَلَكِنْ لُِخبْثِ الطهبِيعَةِ، وَفَسَادِ الْمَحَلِّ، وَعَدَمِ قَـبُولِهِ، والله الموفق.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَقَدِ اخْ تَـلَفَ النهاسُ فِي قَـوْلِهِ تَـعَالَى: يَْخرُجُ مِنْ بُطُونِها شَرابٌ مُْختَلِفٌ أَلْوانُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'فِيهِ شِفاءٌ لِلنهاسِ »7« ، هَلِ الضهمِيُر فِي «فِيهِ» رَاجِعٌ إِلَى الشهرَابِ، أَوْ رَاجِعٌ إِلَى الْقُرْآنِ؟ عَلَى قَـوْلَيِْن:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الصهحِيحُ: رُجُوعُهُ إِلَى الشهرَابِ، وَهُوَ قَـوْلُ ابْنِ مَسْعُودٍ، وَابْنِ عَبهاسٍ ، والحسن، وقتادة، وَالَْأكْ ثَرِينَ، فَإِنههُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'هُوَ الْمَذْكُورُ، وَالْكَلَامُ سِيقَ لَِأجْ لِهِ، وَلَا ذِكْرَ لِلْقُرْآنِ فِي الْآيَةِ، وَهَذَا الَْحدِيثُ الصهحِيحُ وَهُوَ قَـوْلُهُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '«صَدَقَ ا هللَُّ» كَالصهرِيحِ فِيهِ، وَاَ هللَُّ تَـعَالَى أَعْلَمُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ فِي الطهاعُونِ، وَعِلَاجِهِ، وَالِاحْتَِرازِ مِنْهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'فِي «الصهحِيحَيِْن» عَنْ عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقهاصٍ ، عَنْ أَبِيهِ، أَنههُ سَِمعَهُ يَسْأَلُ أُسَامَةَ بْنَ زَيْدٍ: مَاذَا سَِمعْتُ مِنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ في الطهاعُونِ؟ فَـقَالَ أسامة:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «الطهاعُونُ رِجْزٌ أُرْسِلَ عَلَى طَائِفَةٍ مِنْ بَنِِ إِسْرَائِيلَ، وَعَلَى مَنْ كَانَ قَـبْـلَكُمْ، فَإِذَا سَِمعْتُمْ بِهِ بَِأرْضٍ ، فَلَا تَدْخُلُوا عَلَيْهِ، وَإِذَا وَقَعَ بَِأرْضٍ وَأَنْـتُمْ بَِها، فَلَا تَْخرُجُوا مِنْـهَا فِرَارًا مِنْهُ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '»2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَفِي «الصهحِيحَيِْن» أَيْضًا: عن حفصة بنت سيزين، قَالَتْ : قَالَ أَنَسُ بْنُ مَالِكٍ : قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «الطهاعُونُ شَهَادَةٌ لِكُلِّ مُسْلِمٍ» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'ال هطاعُونُ- مِنْ حَيْثُ اللُّغَةُ:- نَـوْعٌ مِنَ الْوَبَاءِ، قَالَهُ صَاحِبُ «الصِّحَاحِ» ، وَهُوَ عِنْدَ أَهْلِ الطِّبِّ : وَرَمٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'رَدِيءٌ قَـتهالٌ يَْخرُجُ مَعَهُ تَـلَهُّبٌ شَدِيدٌ مُؤْلٌَِ جِدًّا يَـتَجَاوَزُ الْمِقْدَارَ فِي ذَلِكَ ، وَيَصِيُر مَا حَوْلَهُ فِي الَْأكْ ثَرِ أَسْوَدَ أو أخضر، أو أكمد، ويؤول أَمْرُهُ إِلَى التهـقَرُّحِ سَرِيعًا. وَفِي الَْأكْ ثَرِ، يَْحدُثُ فِي ثَلَاثَةِ مَوَاضِعَ: فِي الِْإبِطِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَخَلْفَ الُْأذُنِ، والأرنبة، وفي اللحوم الرخوة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(7) النحل- .19', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, '(2) أخرجه البخاري في الأنبياء، وأخرجه مسلم أيضا و «من بنِ إسرائيل» هم الذي أمرهم الله أن يدخلوا الباب سجدا، فخالفوا فأرسل عليهم الطاعون فمات منهم في ساعة سبعون ألفا. وهذا الذي جاء في الحديث هو ما يطلق عليه في أيامنا هذه بالحجر الصحي، وقد أمر بِهِ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَسَلهمَ قبل زهاء ألف وأربعمائة سنة، مما يدل على أن هذا الإسلام من عند الله «لا تَيه الباطل من يديه ولا من خلفه» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, '(3) أخرجه الإمام أحدْ والبخاري ومسلم: ومعنى الحديث أي أن الطاعون سبب لكون الميت منه شهيدا في حكم الآخرة. وظاهره يشمل الفاسق فيكون شهيدا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَفِي أَثَرٍ عَنْ عائشة أَنهـهَا قَالَتْ لِلنهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «الطهعْنُ قَدْ عَرَفْـنَاهُ، فَمَا الطهاعُونُ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'قَالَ: «غُدهةٌ »7« كَغُدهةِ الْبَعِيِر يَْخرُجُ فِي الْمَرَاقِّ وَالِْإبْطِ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'قَالَ الَْأطِبهاءُ: إِذَا وَقَعَ الُْخهراجُ فِي اللُّحُومِ الرِّخْوَةِ، وَالْمَغَابِنِ، وَخَلْفَ الُْأذُنِ وَالَْأرْنَـبَةِ، وَكَانَ مِنْ جِنْسٍ فَاسِدٍ، سُِّميَ طَاعُونًا، وَسَبَـبُهُ دَمٌ رَدِيءٌ مَائِلٌ إِلَى الْعُفُونَةِ وَالْفَسَادِ، مُسْتَحِيلٌ إِلَى جَوْهَرٍ سُِّميٍّ، يُـفْسِدُ الْعُضْوَ وَيُـغَيُِّر مَا يَلِيهِ، وَرُهبَما رَشَحَ دَمًا وَصَدِيدًا، وَيُـؤَدِّي إِلَى الْقَلْبِ كَيْفِيهةً رَدِيئَةً، فَـيَحْدُثُ الْقَيْ ءُ وَالَْخفَقَانُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَالْغَشْيُ، وَهَذَا الِاسْمُ وَإِنْ كَانَ يَـعُمُّ كُله وَرَمٍ يُـؤَدِّي إِلَى الْقَلْبِ كَيْفِيهةً رَدِيئَةً حَ هتى يَصِيَر لِذَلِكَ قَـتهالًا، فَإِنههُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'يَْختَصُّ بِهِ الَْحادِثُ فِي اللهحْمِ الْغُدَدِيِّ ، لَِأنههُ لِرَدَاءَتِهِ لَا يَـقْبَـلُهُ مِنَ الَْأعْضَاءِ إِهلا مَا كَانَ أَضْعَفَ بِالطهبْعِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَأَرْدَؤُهُ مَا حَدَثَ فِي الِْإبِطِ وَخَلْفَ الُْأذُنِ لِقُرْبِِهمَا مِنَ الَْأعْضَاءِ الهتِي هِيَ أَرْأَسُ ، وَأَسْلَمُهُ الَْأحْرَُْ، ُ مه الَْأصْفَرُ. وَاَلهذِي إِلَى السهوَادِ، فَلَا يَـفْلِتُ مِنْهُ أَحَدٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَلَمها كَانَ الطهاعُونُ يَكْ ثُـرُ فِي الْوَبَاءِ، وَفِي الْبِلَادِ الْوَبِيئَةِ، عُبََِّ عَنْهُ بِالْوَبَاءِ، كَمَا قَالَ الخليل: الْوَبَاءُ: الطهاعُونُ. وَقِيلَ: هُوَ كُلُّ مَرَضٍ يَـعُمُّ، وَالتهحْقِيقُ أَنه بَـيَْن الْوَبَاءِ وَالطهاعُونِ عُمُومًا وَخُصُوصًا، فَكُلُّ طَاعُونٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَبَاءٌ، وَلَيْسَ كُلُّ وَبَاءٍ طَاعُونًا، وَكَذَلِكَ الَْأمْرَاضُ الْعَامهةُ أَعَمُّ مِنَ الطهاعُونِ، فَإِنههُ وَاحِدٌ مِنْـهَا، وَالطهوَاعِيُن خُ هراجَاتٌ وَقُـرُوحٌ وَأَوْرَامٌ رَدِيئَةٌ حَادِثَةٌ فِي الْمَوَاضِعِ الْمُتَـقَدِّمِ ذِكْ رُهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'قُـلْتُ : هَذِهِ الْقُرُوحُ، وَالَْأوْرَامُ، وَالِْجرَاحَاتُ ، هِيَ آثَرَُ الطهاعُونِ، وَلَيْسَتْ نَـفْسَهُ، وَلَكِنه الَْأطِبهاءَ لَمها لََْ تُدْرِكْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'مِنْهُ إِهلا الَْأثَـرَ الظهاهِرَ، جَعَلُوهُ نَـفْسَ الطهاعُونِ. وَالطهاعُونُ يُـعَبهـرُ بِهِ عَنْ ثَلَاثَةِ أُمُورٍ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'أَحَدُهَا: هَذَا الَْأثَـرُ الظهاهِرُ، وَهُوَ الهذِي ذكََرَهُ الَْأطِبهاءُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'وَالثهانِي: الْمَوْتُ الَْحادِثُ عَنْهُ، وَهُوَ الْمُرَادُ بِالَْحدِيثِ الصهحِيحِ فِي قَـوْلِهِ: «الطهاعُونُ شهادة لكل مسلم» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, '(7) «غده كغدة البعير ... » الغدة: كل غده في الجسد أطاف بها شحم، وكل قطعة صلبة بين العصب- قاموس- «في المراقّ » مراقّ البطن بفتح الميم وتشديد القاف: ما رقّ منه ولا جعَ مرقّ أولا واحد له- قاموس- أخرجه الإمام أحدْ. وقد جاء بلفظ: «الطاعون غدة كفدة البعير، المقيم بها كالشهيد، والفار منها كالفار من الزحف:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, '(2) قال الهيثمي: رجاله ثقات.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَالثهالِثُ : السهبَبُ الْفَاعِلُ لَِهذَا الدهاءِ، وَقَدْ وَرَدَ فِي الَْحدِيثِ الصهحِيحِ: «أَنههُ بَقِيهةُ رِجْزٍ أُرْسِلَ عَلَى بَنِِ إِسْرَائِيلَ» »7« ، وَوَرَدَ فِيهِ «أَنههُ وَخْ زُ الِْجنِّ» »2« وَجَاءَ أَنههُ دَعْوَةُ نَبٍِّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَهَذِهِ الْعِلَلُ وَالَْأسْبَابُ لَيْسَ عِنْدَ الَْأطِبهاءِ مَا يَدْفَـعُهَا، كَمَا لَيْسَ عِنْدَهُمْ مَا يَدُلُّ عَلَيْـهَا، وَالرُّسُلُ تُْخبَُِ بِالُْأمُورِ الْغَائِبَةِ، وَهَذِهِ الْآثَرَُ الهتِي أَدْركَُوهَا مِنْ أَمْرِ الطهاعُونِ لَيْسَ مَعَهُمْ مَا يَـنْفِي أَنْ تَكُونَ بِتَـوَسُّطِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'الَْأرْوَاحِ، فَإِنه تَثَِْيَر الَْأرْوَاحِ فِي الطهبِيعَةِ وَأَمْرَاضِهَا وَهَلَاكِهَا أَمْرٌ لَا يُـنْكِرُهُ إِهلا مَنْ هُوَ أَجْهَلُ النهاسِ بِالَْأرْوَاحِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'وَتَثَِْيَراتَِها، وَانْفِعَالِ الَْأجْسَامِ وَطَبَائِعِهَا عَنْـهَا، وَاَ هللَُّ سُبْحَانَهُ قَدْ يَْجعَلُ لَِهذِهِ الَْأرْوَاحِ تَصَرُّفًا فِي أَجْسَامِ بَنِِ آدَمَ عِنْدَ حُدُوثِ الْوَبَاءِ، وَفَسَادِ الَْهوَاءِ، كَمَا يَْجعَلُ لَهاَ تَصَرُّفًا عِنْدَ بَـعْضِ الْمَوَادِّ الهردِيئَةِ الهتِي تُدَِْثُ لِلنُّـفُوسِ هَيْـئَةً رَدِيئَةً، وَلَا سِيهمَا عِنْدَ هَيَجَانِ الدهمِ، وَالْمِ هرةِ السهوْدَاءِ، وَعِنْدَ هَيَجَانِ الْمَنِِِّ، فَإِنه الَْأرْوَاحَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'الشهيْطَانِيهةَ تَـتَمَكهنُ مِنْ فِعْلِهَا بِصَاحِبِ هَذِهِ الْعَوَارِضِ مَا لَا تَـتَمَكهنُ مِنْ غَيِْرهِ، مَا لََْ يَدْفَـعْهَا دَافِعٌ أَقْـوَى مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'هَذِهِ الَْأسْبَابِ مِنَ الذِّكْرِ، وَالدُّعَاءِ، وَالِابْتِهَالِ وَالتهضَرُّعِ ، وَالصهدَقَةِ، وَقِرَاءَةِ الْقُرْآنِ، فَإِنههُ يَسْتَـنْزِلُ بِذَلِكَ مِنَ الَْأرْوَاحِ الْمَلَكِيهةِ مَا يَـقْهَرُ هَذِهِ الَْأرْوَاحَ الَْخبِيثَةَ، وَيُـبْطِلُ شَ هرهَا وَيَدْفَعُ تَثَِْيَرهَا، وَقَدْ جَ هربْـنَا نَنُْْ وَغَيْـرُنَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'هَذَا مِرَارًا لَا يُْحصِيهَا إِهلا ا هللَُّ، وَرَأَيْـنَا لا ستنزال هَذِهِ الَْأرْوَاحِ الطهيِّبَةِ وَاسْتِجْلَابِ قُـرْبَِها تَثَِْيًرا عَظِيمًا فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'تَـقْوِيَةِ الطهبِيعَةِ، وَدَفْعِ الْمَوَادِّ الهردِيئَةِ، وَهَذَا يَكُونُ قَـبْلَ اسْتِحْكَامِهَا وَتَكََُّنِهَا، وَلَا يَكَادُ يَـنْخَرِمُ، فَمَنْ وَفهـقَهُ ا هللَُّ، بَادَرَ عِنْدَ إِحْسَاسِهِ بَِأسْبَابِ الشهرِّ إِلَى هَذِهِ الَْأسْبَابِ الهتِي تَدْفَـعُهَا عَنْهُ، وَهِيَ لَهُ مِنْ أَنْـفَعِ الدهوَاءِ، وَإِذَا أَرَادَ ا هللَُّ عَهز وَجَله إِنْـفَاذَ قَضَائِهِ وَقَدَرِهِ، أَغْفَلَ قَـلْبَ الْعَبْدِ عَنْ مَعْرِفَتِهَا وَتَصَوُّرِهَا وَإِرَادَتَِها، فَلَا يَشْعُرُ بَِها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'وَلَا يُرِيدُهَا، لِيَـقْضِيَ ا هللَُّ فِيهِ أَمْرًا كَانَ مَفْعُولًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'وَسَنَزِيدُ هَذَا الْمَعْنَى إِنْ شَاءَ ا هللَُّ تَـعَالَى إِيضَاحًا وَبَـيَانًا عِنْدَ الْكَلَامِ عَلَى التهدَاوِي بِالرُّقَى،؛ وَالْعُوَذِ النهـبَوِيهةِ، وَالَْأذكَْارِ، وَالدهعَوَاتِ، وَفِعْلِ الَْخيْـرَاتِ، وَنُـبَـيُِّن أَنه نِسْبَةَ طِبِّ الَْأطِبهاءِ إِلَى هَذَا الطِّبِّ النهـبَوِيِّ ، كَنِسْبَةِ طِبِّ الطهرْقِيهةِ والعجائز الى طبهم، كما', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, '(7) أخرجه البخاري ومسلم والترمذي من حديث أسامة بن زيد', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, '(2) «وخز الجن» أي طعن أعدائكم: أخرجه الحاكم عن أبي موسى الاشعري بلفظ- «الطاعون وخز أعدائكم من الجن وهو لكم شهادة» . وهو حديث صحيح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'اعْتَـرَفَ بِهِ حُذهاقُـهُمْ وَأَئِمهتُـهُمْ، وَنُـبَـيُِّن أَنه الطهبِيعَةَ الِْإنْسَانِيهةَ أَشَدُّ شَيْ ءٍ انْفِعَالًا عَنِ الَْأرْوَاحِ، وَأَنه قُـوَى الْعُوَذِ، وَالرُّقَى، وَالدهعَوَاتِ، فَـوْقَ قُـوَى الَْأدْوِيَةِ، حَ هتى إِنهـهَا تُـبْطِلُ قُـوَى السُّمُومِ الْقَاتِلَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'وَالْمَقْصُودُ: أَنه فَسَادَ الَْهوَاءِ جُزْءٌ مِنْ أَجْ زَاءِ السهبَبِ التهامِّ، وَالْعِلهةِ الْفَاعِلَةِ لِلطهاعُونِ، فَإِنه فَسَادَ جَوْهَرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'الَْهوَاءِ الْمُوجِبِ لُِحدُوثِ الْوَبَاءِ وَفَسَادِهِ، يَكُونُ لِاسْتِحَالَةِ جَوْهَرِهِ إِلَى الهردَاءَةِ، لِغَلَبَةِ إِحْدَى الْكَيْفِيهاتِ الهردِيئَةِ عَلَيْهِ، كَالْعُفُونَةِ، وَالنهـتَُِ وَالسُّمِّيهةِ فِي أَيِّ وَقْتٍ كَانَ مِنْ أَوْقَاتِ السهنَةِ، وَإِنْ كَانَ أَكْ ثَـرُ حدوته فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'أَوَاخِرِ الصهيْفِ، وَفِي الَْخرِيفِ غَالِبًا لِكَثْـرَةِ اجْتِمَ اعِ الْفَضَلَاتِ الْمَرَارِيهةِ الَْحادهةِ وَغَيِْرهَا فِي فَصْلِ الصهيْفِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'وَعَدَمِ تَلََُّلِهَا فِي آخِرِهِ، وَفِي الَْخرِيفِ لِبَـرْدِ الَْجوِّ، وَرَدْغَةِ الَْأخِْرَِةِ وَالْفَضَلَاتِ الهتِي كَانَتْ تَـتَحَلهلُ فِي زَمَنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'الصهيْفِ، فَـتَـنْحَصِرُ، فَـتَسْخَنُ، وَتُـعَهفنُ، فَـتُحْدِثُ الَْأمْرَاضَ الْعَفِنَةَ، وَلَا سِيهمَا إِذَا صَادَفَتِ الْبَدَنَ مُسْتَعِدًّا، قَابِلًا، رَهِلًا، قَلِيلَ الَْحرَكَةِ، كَثِيَر الْمَوَادِّ، فَـهَذَا لَا يَكَادُ يُـفْلِتُ مِنَ الْعَطَبِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'وأصح الفصول فيه فصل الربيع. قال بقراط: إِنه فِي الَْخرِيفِ أَشَده مَا تَكُونُ مِنَ الَْأمْرَاضِ ، وَأَقْـتَلَ، وَأَمها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'الهربِيعُ، فَأَصَحُّ الَْأوْقَاتِ كُلِّهَا وَأَقَـلُّهَا مَوْتًا، وَقَدْ جَرَتْ عَادَةُ الصهيَادِلَةِ، وَمُهََِّزِي الْمَوْتَى أَنهـهُمْ يَسْتَدِينُونَ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'وَيَـتَسَلهفُونَ فِي الهربِيعِ وَالصهيْفِ عَلَى فَصْلِ الَْخرِيفِ، فَـهُوَ رَبِيعُهُمْ، وَهُمْ أَشْوَقُ شَيْ ءٍ إِلَيْهِ، وَأَفْـرَحُ بِقُدُومِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 48, 'وَقَدْ رُوِيَ فِي حَدِيثِ: «إِذَا طَلَعَ النهجْمُ ارْتَـفَعَتِ الْعَاهَةُ عَنْ كُلِّ بَـلَدٍ» »7« . وَفُسِّ رَ بِطُلُوعِ الثُّـرَهيا، وَفُسِّ رَ بِطُلُوعِ النهـبَاتِ زَمَنَ الهربِيعِ، وَمِنْهُ وَالنهجْمُ وَالشهجَرُ يَسْجُدانِ »2« فَإِنه كَمَالَ طُلُوعِهِ وَتَاََمَهُ يَكُونُ فِي', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلِ الهربِيعِ، وَهُوَ الْفَصْلُ الهذِي تَـرْتَفِعُ فِيهِ الْآفَاتُ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَمها الثُّـرَهيا، فَالَْأمْرَاضُ تَكْثُـرُ وَقْتَ طُلُوعِهَا مَعَ الْفَجْرِ وَسُقُوطِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'قَالَ التميمي فِي كِتَابِ «مَادهةِ الْبَـقَاءِ» : أَشَدُّ أَوْقَاتِ السهنَةِ فَسَادًا، وَأَعْظَمُهَا بَلِيهةً عَلَى الَْأجْسَادِ وَقْـتَانِ، أَحَدُهُاَُ: وَقْتُ سُقُوطِ الثُّـرَهيا للمغيب عند طلوع الفجر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(7) أخرجه محمد بن الحسن في الآثرَ، والطباَني في «الصغير» وأبو نعيم في تاريخ أصبهان بلفظ «إذا طلع النجم رفعت العاهة عن كل بلد» وإسناده صحح', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(2) الرحنْ- 1', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَالثهانِي: وَقْتُ طُلُوعِهَا مِنَ الْمَشْرِقِ قَـبْلَ طُلُوعِ الشهمْسِ عَلَى الْعَالََِ، بَِمنْزِلَةٍ مِنْ مَنَازِلِ الْقَمَرِ، وَهُوَ وَقْتُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'تَصَرُّمِ فَصْلِ الهربِيعِ وَانْقِضَائِهِ، غَيْـرَ أَنه الْفَسَادَ الْكَائِنَ عِنْدَ طُلُوعِهَا أَقَلُّ ضَرَرًا مِنَ الْفَسَادِ الْكَائِنِ عِنْدَ سُقُوطِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَقَالَ أَبُو مُمَُهدِ بْنُ قُـتَـيْـبَةَ: يُـقَالُ: مَا طَلَعَتِ الثُّـرَهيا، وَلَا نََأتْ إِهلا بِعَاهَةٍ فِي النهاسِ وَالِْإبِلِ، وَغُرُوبُـهَا أَعْوَهُ »7« مِنْ طُلُوعِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَفِي الَْحدِيثِ قَـوْلٌ ثَلَِثٌ - وَلَعَلههُ أَوْلَى الَْأقْـوَالِ بِهِ- أَنه الْمُرَادَ بِالنهجْمِ: الثُّـرَهيا، وَبِالْعَاهَةِ: الْآفَةُ الهتِي تَـلْحَقُ الزُّرُوعَ وَالثِّمَارَ فِي فَصْلِ الشِّ تَاءِ وَصَدْرِ فَصْلِ الهربِيعِ، فَحَصَلَ الَْأمْنُ عَلَيْـهَا عِنْدَ طُلُوعِ الثُّـرَهيا فِي الْوَقْتِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'الْمَذْكُورِ، وَلِذَلِكَ نَـهَى صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَنْ بَـيْعِ الثهمَرَةِ وَشِرَائِهَا قَـبْلَ أَنْ يَـبْدُوَ صَلَاحُهَا. وَالْمَقْصُودُ: الْكَلَامُ عَلَى هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عِنْدَ وُقُوعِ الطهاعُونِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَقَدْ جَعَََ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لِلْمُِهةِ فِي نَـهْيِهِ عَنِ الدُّخُولِ إِلَى الَْأرْضِ الهتِي هُوَ بَِها، وَنَـهْيِهِ عَنِ الُْخرُوجِ مِنْـهَا بَـعْدَ وُقُوعِهِ كَمَالَ التهحَرُّزِ مِنْهُ، فَإِنه فِي الدُّخُولِ فِي الَْأرْضِ الهتِي هُوَ بَِها تَـعَرُّضًا لِلْبَلَاءِ، وَمُوَافَاةً', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'لَهُ فِي مَلَُِّ سُلْطَانِهِ، وَإِعَانَةً لِلِْنْْسَانِ عَلَى نَـفْسِهِ، وَهَذَا مَُخالِفٌ لِلشهرْعِ وَالْعَقْلِ، بَلْ تَنََُّبُ الدُّخُولِ إِلَى أَرْضِهِ مِنْ بَابِ الِْحمْيَةِ الهتِي أَرْشَدَ ا هللَُّ سُبْحَانَهُ إِلَيْـهَا، وَهِيَ حِيَْْةٌ عَنِ الَْأمْكِنَةِ، وَالَْأهْوِيَةِ الْمُؤْذِيَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَأَمها نَـهْيُهُ عَنِ الُْخرُوجِ مِنْ بَـلَدِهِ، فَفِيهِ مَعْنَـيَانِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'أَحَدُهُاَُ: حَلُْْ النُّـفُوسِ عَلَى الثِّقَةِ بَِا هلِلَّ، وَالتهـوَكُّلِ عَلَيْهِ، والصبَ على أقضيته، والرضى بَِها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَالثهانِي: مَا قَالَهُ أَئِمهةُ الطِّبِّ : أَنههُ يَِجبُ عَلَى كُلِّ مُتَُِْرزٍ مِنَ الْوَبَاءِ أَنْ يُْخرِجَ عَنْ بَدَنِهِ الرُّطُوبَاتِ الْفَضْلِيهةِ، وَيُـقَلِّلَ الْغِذَاءَ، وَيَِميلَ إِلَى التهدْبِيِر الْمُجَفِّفِ مِنْ كُلِّ وَجْهٍ إِهلا الرِّيَاضَةَ وَالَْحمهامَ، فَإِنهـهُمَا مِمها يَِجبُ أَنْ يُْحذَرَا، لَِأنه الْبَدَنَ لَا يَْخلُو غَالِبًا مِنْ فَضْلٍ رَدِيءٍ كَامِنٍ فِيهِ، فَـتُثِيُرهُ الرِّيَاضَةُ وَالَْحمهامُ، ويخلطانه بالكيموس الجيد، وذلك يجلب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(7) أعوه: أشد عاهة وإصابة من: عاه الشيء: إذا أصابته عاهة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'عِلهةً عَظِيمَةً، بَلْ يَِجبُ عِنْدَ وُقُوعِ الطهاعُونِ السُّكُونُ وَالدهعَةُ، وَتَسْكِيُن هَيَجَانِ الَْأخْلَاطِ، وَلَا يُْمكِنُ الُْخرُوجُ مِنْ أَرْضِ الْوَبَاءِ وَالسهفَرُ مِنْـهَا إِهلا بَِحرَكَةٍ شَدِيدَةٍ، وَهِيَ مُضِ هرةٌ جِدًّا، هَذَا كَلَامُ أَفْضَلِ الَْأطِبهاءِ الْمُتَأَخِّرِينَ، فَظَهَرَ الْمَعْنَى الطِّبُِّّ مِنَ الَْحدِيثِ النهـبَوِيِّ ، وَمَا فِيهِ مِنْ عِلَاجِ الْقَلْبِ وَالْبَدَنِ وَصَلَاحِهِمَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'فَإِنْ قِيلَ: فَفِي قَـوْلِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «لَا تَْخرُجُوا فِرَارًا مِنْهُ» ، مَا يُـبْطِلُ أَنْ يَكُونَ أَرَادَ هَذَا الْمَعْنَى الهذِي ذكََرْتُوَُهُ، وَأَنههُ لَا يَْمنَعُ الُْخرُوجَ لِعَارِضٍ ، وَلَا يَْحبِسُ مُسَافِرًا عَنْ سَفَرِهِ؟ قِيلَ: لََْ يَـقُلْ أَحَدٌ طَبِيبٌ وَلَا غَيْـرُهُ، إِنه النهاسَ يَـتْـرُكُونَ حَرَكَاتِِهمْ عِنْدَ الطهوَاعِيِن، وَيَصِ يُرونَ بَِمنْزِلَةِ الَْجمَادَاتِ، وَإِهنَما يَـنْـبَغِي فِيهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'التهـقَلُّلُ مِنَ الَْحرَكَةِ بَِحسْبِ الِْإمْكَانِ، وَالْفَارُّ مِنْهُ لَا مُوجِبَ لَِحرَكَتِهِ إِهلا مُهََردُ الْفِرَارِ مِنْهُ، وَدَعَتُهُ وَسُكُونُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'أَنْـفَعُ لِقَلْبِهِ وَبَدَنِهِ، وَأَقْـرَبُ إِلَى تَـوَكُّلِهِ عَلَى ا هلِلَّ تَـعَالَى، وَاسْتِسْلَامِهِ لِقَضَائِهِ. وَأَمها مَنْ لَا يَسْتَـغْنِِ عَنِ الَْحرَكَةِ، كَالصُّنهاعِ ، وَالُْأجَرَاءِ، وَالْمُسَافِرِينَ، وَالْبُـرُدِ، وَغَيِْرهِمْ، فَلَا يُـقَالُ لَهمُُ: اتْـرُكُوا حَرَكَاتِكُمْ جُلََْةً، وَإِنْ أُمِرُوا أَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'يَـتْـرُكُوا مِنْـهَا مَا لَا حَاجَةَ لَهمُْ إِلَيْهِ، كَحَرَكَةِ الْمُسَافِرِ فَارًّا مِنْهُ وَاَ هللَُّ تَـعَالَى أَعْلَمُ. وَفِي الْمَنْعِ مِنَ الدُّخُولِ إِلَى الَْأرْضِ الهتِي قَدْ وَقَعَ بَِها عِدهةُ حِكَمٍ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'أَحَدُهَا: تَنََُّبُ الَْأسْبَابِ الْمُؤْذِيَةِ، وَالْبُـعْدُ مِنْـهَا. الثهانِي: الَْأخْذُ بِالْعَافِيَةِ الهتِي هِيَ مَادهةُ الْمَعَاشِ وَالْمَعَادِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'الثالث: ألايستنشقوا الهواء الدي قد عفن وفسد فيمرضون.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'الرابع: ألايجاوروا الْمَرْضَى الهذِينَ قَدْ مَرِضُوا بِذَلِكَ ، فَـيَحْصُلُ لَهمُْ بُِمجَاوَرَتِِهمْ مِنْ جِنْسِ أَمْرَاضِهِمْ. وَفِي «سُنَنِ أبي داود» مَرْفُوعًا: «إِنه مِنَ الْقَرَفِ التهـلَفَ » »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'قَالَ ابن قتيبة: الْقَرَفُ مُدَانَاةُ الْوَبَاءِ، وَمُدَانَاةُ الْمَرْضَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'الَْخامِسُ : حِيَْْةُ النُّـفُوسِ عَنِ الطِّيَـرَةِ وَالْعَدْوَى، فَإِنهـهَا تَـتَأَثهـرُ بِِهمَا، فَإِنه الطِّيَـرَةَ عَلَى مَنْ تَطَيهـرَ بَِها، وَبِالُْجمْلَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'فَفِي النهـهْيِ عَنِ الدِّخُولِ فِي أَرْضِهِ الَْأمْرُ بِالَْحذَرِ وَالِْحمْيَةِ، وَالنهـهْيِ عَنِ التهـعَرُّضِ لَِأسْبَابِ التهـلَفِ . وَفِي النهـهْيِ عَنِ الْفِرَارِ مِنْهُ الَْأمْرُ بِالتهـوَكُّلِ، وَالتهسْلِيمِ، وَالتهـفْوِيضِ ، فَالَْأهولُ: تَدَِْيبٌ وَتَـعْلِيمٌ، والثاني: تفويض وتسليم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, '(7) أخرجه أبو داود والإمام أحدْ وفي سنده جهالة. والقرف: مداناة المرض وبابه طرب. مختار.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَفِي الصهحِيحِ: أَنه عمر بن الخطاب خَرَجَ إِلَى الشهامِ، حَ هتى إِذَا كَانَ بِسَرْغَ، لَقِيَهُ أَبُو عُبَـيْدَةَ بْنُ الَْجهراحِ وَأَصْحَابُهُ، فَأَخْ بَـرُوهُ أَنه الْوَبَاءَ قَدْ وَقَعَ بِالشهامِ، فَاخْ تَـلَفُوا، فَـقَالَ لِابْنِ عَبهاسٍ : ادعُْ لَِِ الْمُهَاجِرِينَ الَْأهولِيَن، قَالَ: فَدَعَوْتُـهُمْ، فَاسْتَشَارَهُمْ، وَأَخْ بَـرَهُمْ أَنه الْوَبَاءَ قَدْ وَقَعَ بِالشهامِ، فَاخْ تَـلَفُوا، فَـقَالَ لَهُ بَـعْضُهُمْ: خَرَجْتَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'لَِأمْرٍ، فَلَا نَـرَى أَنْ تَـرْجِعَ عَنْهُ. وَقَالَ آخَرُونَ: مَعَكَ بَقِيهةُ النهاسِ ، وَأَصْحَابُ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَلَا نَـرَى أَنْ تُـقْدِمَهُمْ عَلَى هَذَا الْوَبَاءِ، فَـقَالَ عمر: ارْتَفِعُوا عَنِِّ، ُ مه قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'ادعُْ لَِِ الَْأنْصَارَ، فَدَعَوْتُـهُمْ لَهُ، فَاسْتَشَارَهُمْ، فَسَلَكُوا سَبِيلَ الْمُهَاجِرِينَ، وَاخْ تَـلَفُوا كَاخْ تِلَافِهِمْ، فَـقَالَ: ارْتَفِعُوا عنِ، م قال: ادع لِ من ها هنا مِنْ مَشْيَخَةِ قُـرَيْشٍ مِنْ مُهَاجِرَةِ الْفَتْحِ، فَدَعَوْتُـهُمْ لَهُ، فَـلَمْ يَْختَلِفْ عَلَيْهِ مِنْـهُمْ رَجُلَانِ، قَالُوا: نَـرَى أَنْ تَـرْجِعَ بِالنهاسِ وَلَا تُـقْدِمَهُمْ عَلَى هَذَا الْوَبَاءِ، فَأَذهنَ عمر فِي النهاسِ إِنِّي مُصْبِحٌ عَلَى ظَهْرٍ، فَأَصْبِحُوا عَلَيْهِ، فَـقَالَ أَبُو عُبَـيْدَةَ بْنُ الَْجهراحِ: يَا أَمِيَر الْمُؤْمِنِيَن! أَفِرَارًا مِنْ قَدَرِ ا هلِلَّ تَـعَالَى؟ قَالَ: لَوْ غَيْـرُكَ قَالَهاَ يَا أبا عبيدة، نَـعَمْ نَفِرُّ مِنْ قَدَرِ ا هلِلَّ تَـعَالَى إِلَى قَدَرِ ا هلِلَّ تَـعَالَى، أَرَأَيْتَ لَوْ كَانَ لَكَ إِبِلٌ فَـهَبَطَتْ وَادِيًا لَهُ عُدْوَتَانِ، إِحْدَاهُاَُ- خِصْبَةٌ، وَالُْأخْ رَى، جَدْبَةٌ، أَلَسْتَ إِنْ رَعَيْـتَـهَا الِْخصْبَةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'رَعَيْـتَـهَا بِقَدَرِ ا هلِلَّ تَـعَالَى، وَإِنْ رَعَيْـتَـهَا الَْجدْبَةَ رَعَيْـتَـهَا بِقَدَرِ ا هلِلَّ تَـعَالَى؟ قَالَ: فَجَاءَ عَبْدُ الهرحْنَِْ بْنُ عَوْفٍ وَكَانَ مُتَـغَيِّبًا فِي بَـعْضِ حَاجَاتِهِ، فَـقَالَ: إِنه عِنْدِي فِي هَذَا عِلْمًا، سَِمعْتُ مِنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـقُولُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, '«إِذَا كَانَ بَِأرْضٍ وَأَنْـتُمْ بَِها، فَلَا تَْخرُجُوا فِرَارًا مِنْهُ، وَإِذَا سَِمعْتُمْ بِهِ بَِأرْضٍ ، فَلَا تَـقْدَمُوا عَلَيْهِ» »7« .', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ فِي دَاءِ الِاسْ تِسْقَاءِ وَعِلَاجِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'فِي «الصهحِيحَيِْن» : مِنْ حَدِيثِ أَنَسِ بْنِ مَالِكٍ ، قَالَ: «قَدِمَ رَهْطٌ مِنْ عُرَيْـنَةَ وَعُكَلٍ عَلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَاجْ تَـوَوُا الْمَدِينَةَ، فَشَكَوْا ذَلِكَ إِلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَـقَالَ: «لو', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '(7) أخرجه البخاري في الطب ومسلم في السلام. و «سرغ» موضع قرب الشام بين المغيشة وتبوك. قاموس. والعدوة: بضم العين وكسرها جانب الوادي وحافتاه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'خَرَجْ تُمْ إِلَى إِبِلِ الصهدَقَةِ فَشَرِبْـتُمْ مِنْ أَبْـوَالَِها وَأَلْبَانَِها، فَـفَعَلُوا، فَـلَمها صَحُّوا، عَمَدُوا إِلَى الرُّعَاةِ فَـقَتَـلُوهُمْ، وَاسْتَاقُوا الِْإبِلَ، وَحَارَبُوا ا هللََّ وَرَسُولَهُ، فَـبَـعَثَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ في آثَرَِهِمْ، فَأُخِذُوا، فَـقَطَعَ أَيْدِيَـهُمْ، وَأَرْجُلَهُمْ، وَسََملَ أَعْيُـنَـهُمْ، وَأَلْقَاهُمْ فِي الشهمْسِ حَ هتى مَاتُوا» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَالدهلِيلُ عَلَى أن هذا المرض كان الاستقساء، مَا رَوَاهُ مسلم فِي «صَحِيحِهِ» فِي هَذَا الَْحدِيثِ أَنهـهُمْ قَالُوا: إِهنا اجْ تَـوَيْـنَا الْمَدِينَةَ، فَـعَظُمَتْ بُطُونُـنَا، وَارْتَـهَشَتْ أَعْضَاؤُنَا، وَذكََرَ تَاََمَ الَْحدِيثِ ...', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَالَْجوَى: داء من أدواء الجوف- والاستقساء: مَرَضٌ مَادِّيٌّ سَبَـبُهُ مَادهةٌ غَرِيبَةٌ بَارِدَةٌ تَـتَخَلهلُ الَْأعْضَاءَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'فَـتَـرْبُو لَهاَ إِمها الَْأعْضَاءُ الظهاهِرَةُ كُلُّهَا، وَإِمها الْمَوَاضِعُ الَْخالِيَةُ مِنَ النهـوَاحِي الهتِي فِيهَا تَدْبِيُر الْغِذَاءِ وَالَْأخْلَاطُ، وَأَقْسَامُهُ ثَلَاثَةٌ: لَْحمِيٌّ، وَهُوَ أَصْعَبُـهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَزِقِّيٌّ، وَطَبْلِيٌّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَلَمها كَانَتِ الَْأدْوِيَةُ الْمُحْ تَاجُ إِلَيْـهَا فِي عِلَاجِهِ هِيَ الَْأدْوِيَةُ الَْجالِبَةُ الهتِي فِيهَا إطْلَاقٌ مُعْتَدِلٌ، وَإِدْرَارٌ بَِحسْبِ الَْحاجَةِ، وَهَذِهِ الُْأمُورُ مَوْجُودَةٌ فِي أَبْـوَالِ الِْإبِلِ وَأَلْبَانَِها، أَمَرَهُمُ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بِشُرْبَِها، فَإِنه فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'لَبَِن اللِّقَاحِ جَلَاءً وَتَـلْيِينًا، وَإِدْرَارًا وَتَـلْطِيفًا، وَتَـفْتِيحًا لِلسُّدَدِ، إِذْ كَانَ أَكْ ثَـرُ رَعْيِهَا الشِّ يحَ، وَالْقَيْصُومَ، وَالْبَابُونَجَ، وَالُْأقْحُوَانَ، وَالِْإذْخِرَ، وَغَيْـرَ ذَلِكَ مِنَ الَْأدْوِيَةِ النهافِعَةِ لِلِاسْتِسْقَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَهَذَا الْمَرَضُ لَا يَكُونُ إِهلا مَعَ آفَةٍ فِي الْكَبِدِ خَاصهةً، أَوْ مَعَ مُشَاركََةٍ، وَأَكْثَـرُهَا عَنِ السهدَدِ فِيهَا، وَلَبَُن اللِّقَاحِ الْعَرَبِيهةِ نَافِعٌ مِنَ السهدَدِ، لِمَا فِيهِ مِنَ التهـفْتِيحِ، وَالْمَنَافِعِ الْمَذْكُورَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'قَالَ الرازي: لَبَُن اللِّقَاحِ يَشْفِي أَوْجَاعَ الْكَبِدِ، وَفَسَادَ الْمِزَاجِ، وَقَالَ الإسرائيلي: لَبَُن اللِّقَاحِ أَرَقُّ الَْألْبَانِ ، وَأَكْ ثَـرُهَا مَائِيهةً وَحِدهةً، وَأَقَـلُّهَا غِذَاءً، فَلِذَلِكَ صَارَ أَقْـوَاهَا عَلَى تَـلْطِيفِ الْفُضُولِ، وَإِطْلَاقِ الْبَطْنِ، وَتَـفْتِيحِ السُّدَدِ، وَيَدُلُّ على ذلك ملوحته اليسيرة التي فيه الإفراط حَرَارَةٍ حَيَـوَانِيهةٍ بِالطهبْعِ، وَلِذَلِكَ صَارَ أَخَصه الَْألْبَانِ بِتَطْرِيَةِ الْكَبِدِ، وَتَـفْتِيحِ سُدَدِهَا، وَتَلَِْيلِ صَلَابَةِ الطِّحَالِ إذا كان حديثا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '(7) أخرجه البخاري وأبو داود والترمذي وابن ماجه والنسائي. و «عرينة» قبيلة منهم العرينون المرتدون عن الإسلام «عكل» وعكل بالضم بلد وأبو قبيلة فيهم غباوة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَالنهـفْعُ مِنَ الِاسْتِسْقَاءِ خَاصهةً إِذَا اسْتُـعْمِلَ لَِحرَارَتِهِ الهتِي يَْخرُجُ بَِها مِنَ الضهرْعِ مَعَ بَـوْلِ الفصيل، وهو حاركما يَْخرُجُ مِنَ الَْحيَـوَانِ، فَإِنه ذَلِكَ مِمها يَزِيدُ فِي مِلْوَحَتِهِ، وَتَـقْطِيعِهِ الْفُضُولَ، وَإِطْلَاقِهِ الْبَطْنَ، فَإِنْ تَـعَذهرَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'انِْدَْارُهُ وَإِطْلَاقُهُ الْبَطْنَ، وَجَبَ أَنْ يُطْلَقَ بِدَوَاءٍ مُسَهِّلٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'قَالَ صَاحِبُ الْقَانُونِ: وَلَا يُـلْتَـفَتُ إِلَى مَا يُـقَالُ: مِنْ أَنه طَبِيعَةَ اللهبَِن مُضَادهةٌ لِعِلَاجِ الِاسْتِسْقَاءِ. قَالَ: وَاعْلَمْ أَنه لَبََن النُّوقِ دَوَاءٌ نَافِعٌ لِمَا فِيهِ مِنَ الَْجلَاءِ بِرِفْقٍ، وَمَا فِيهِ مِنْ خَاصِّ يهةٍ، وَأَنه هَذَا اللهبََن شَدِيدُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'الْمَنْـفَعَةِ، فَـلَوْ أَنه إِنْسَانًا أَقَامَ عَلَيْهِ بَدَلَ الْمَاءِ وَالطهعَامِ شُفِيَ بِهِ، وَقَدْ جُرِّبَ ذَلِكَ فِي قَـوْمٍ دُفِعُوا إِلَى بِلَادِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'الْعَرَبِ، فَـقَادَتْـهُمُ الضهرُورَةُ إِلَى ذَلِكَ ، فَـعُوفُوا. وَأَنْـفَعُ الَْأبْـوَالِ: بَـوْلُ الَْجمَلِ الَْأعْرَابِِّي، وَهُوَ النهجِيبُ ، انْـتَـهَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَفِي الْقِصهةِ: دَلِيلٌ عَلَى التهدَاوِي وَالتهطَبُّبِ ، وَعَلَى طَهَارَةِ بَـوْلِ مَأْكُولِ اللهحْمِ، فَإِنه التهدَاوِيَ بِالْمُحَ هرمَاتِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'غَيْـرُ جَائِزٍ، وَلََْ يُـؤْمَرُوا مَعَ قُـرْبِ عَهْدِهِمْ بِالِْإسْلَامِ بِغَسْلِ أَفْـوَاهِهِمْ، وَمَا أَصَابَـتْهُ ثِيَابُـهُمْ مِنْ أَبْـوَالَِها لِلصهلَاةِ، وَتَخَِْيُر الْبَـيَانِ لَا يَُجوزُ عَنْ وَقْتِ الَْحاجَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَعَلَى مُقَاتَـلَةِ الَْجانِي بِِمثْلِ مَا فَـعَلَ، فَإِنه هَؤُلَاءِ قَـتَـلُوا الهراعِيَ ، وَسََملُوا عَيْـنَـيْهِ، ثَـبَتَ ذَلِكَ فِي «صَحِيحِ مسلم» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَعَلَى قَـتْلِ الَْجمَاعَةِ، وَأَخْذِ أَطْرَافِهِمْ بِالْوَاحِدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَعَلَى أَنههُ إِذَا اجْتَمَعَ فِي حَقِّ الَْجانِي حَدٌّ وَقِصَاصٌ اسْتُوفِيَا مَعًا، فَإِنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَطَعَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'أَيْدِيَـهُمْ وَأَرْجُلَهُمْ حَدًّا هِلِلَّ عَلَى حِرَابِِهمْ، وَقَـتَـلَهُمْ لِقَتْلِهِمُ الهراعِيَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَعَلَى أَنه الْمُحَارِبَ إِذَا أَخَذَ الْمَالَ، وَقَـتَلَ، قُطِعَتْ يَدُهُ وَرِجْلُهُ فِي مَقَامٍ وَاحِدٍ وَقُتِلَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'وَعَلَى أَنه الِْجنَايَاتِ إِذَا تَـعَدهدَتْ ، تَـغَلهظَتْ عُقُوبَاتُـهَا، فَإِنه هَؤُلَاءِ ارْتَدُّوا بَـعْدَ إسْلَامِهِمْ، وَقَـتَـلُوا النهـفْسَ ، وَمَثهـلُوا بِالْمَقْتُولِ، وَأَخَذُوا الْمَالَ، وَجَاهَرُوا بِالْمُحَارَبَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَعَلَى أَنه حُكْمَ رِدْءِ الْمُحَارِبِيَن حُكْمُ مُبَاشِرِهِمْ، فَإِنههُ مِنَ الْمَعْلُومِ أَنه كُله وَاحِدٍ مِنْـهُمْ لََْ يُـبَاشِرِ الْقَتْلَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'بِنَـفْسِهِ، وَلَا سَأَلَ النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَنِ ذلك.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَعَلَى أَنه قَـتْلَ الْغِيلَةِ يُوجِبُ قَـتْلَ الْقَاتِلِ حَدًّا، فَلَا يُسْقِطُهُ الْعَفْوُ، وَلَا تُـعْتَـبَـرُ فِيهِ الْمُكَافَأَةُ، وَهَذَا مَذْهَبُ أَهْلِ الْمَدِينَةِ، وَأَحَدُ الْوَجْهَيِْن فِي مَذْهَبِ أحدْ، اخْ تَارَهُ شَيْخُنَا، وَأَفْـتَى بِهِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ فِي عِلَاجِ الُْجرْحِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'فِي «الصهحِيحَيِْن» : عَنْ أبي حازم، أَنههُ سَِمعَ سَهْلَ بْنَ سَعْدٍ يَسْأَلُ عَمها دُووِيَ بِهِ جُرْحُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـوْمَ أُحُدٍ، فَـقَالَ: «جُرِحَ وَجْهُهُ، وَكُسِرَتْ رَبَاعِيَـتُهُ، وَهُشِمَتِ الْبَـيْضَةُ عَلَى رَأْسِهِ، وَكَانَتْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'فاطمة بِنْتُ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَ هلمَ تَـغْسِلُ الدهمَ، وَكَانَ عَلِيُّ بْنُ أَبِي طَالِبٍ يَسْكُبُ عَلَيْـهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'بِالْمِجَنِّ، فَـلَمها رَأَتْ فاطمة الدهمَ لَا يَزِيدُ إِهلا كَثْـرَةً، أَخَذَتْ قِطْعَةَ حَصِيٍر، فَأَحْ رَقَـتْـهَا حَ هتى إِذَا صَارَتْ رَمَادًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'أَلْصَقَتْهُ بِالُْجرْحِ فَاسْتَمْسَكَ الدهمُ» »7« ، بِرَمَادِ الَْحصِيِر الْمَعْمُولِ مِنَ الْبَـرْدِيِّ »2« وَلَهُ فِعْلٌ قَوِيٌّ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'حَبْسِ الدهمِ، لَِأنه فِيهِ تَفَِْيفًا قَوِيًّا، وَقِلهةَ لَذْعٍ ، فَإِنه الَْأدْوِيَةَ الْقَوِيهةَ التهجْفِيفِ إِذَا كَانَ فِيهَا لَذْعٌ هَيهجَتِ الدهمَ وَجَلَبَـتْهُ، وَهَذَا الهرمَادُ إِذَا نُفِخَ وَحْدَهُ، أَوْ مَعَ الَْخلِّ فِي أَنْفِ الهراعِفِ قُطِعَ رُعَافُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَقَالَ صَاحِبُ الْقَانُونِ: الْبَـرْدِيُّ يَـنْـفَعُ مِنَ النهـزْفِ ، وَيَْمنَـعُهُ، وَيُذَرُّ عَلَى الِْجرَاحَاتِ الطهرِيهةِ، فَـيُدْمِلُهَا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَالْقِرْطَاسُ الْمِصْرِيُّ كَانَ قَدِيًما يُـعْمَلُ مِنْهُ، وَمِزَاجُهُ بَارِدٌ يَابِسٌ ، وَرَمَادُهُ نَافِعٌ مِنْ أَكَلَةِ الْفَمِ، وَيَْحبِسُ نَـفْثَ الدم، ويمنع القروح الخبيثة أن تسعى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(7) أخرجه البخاري في الجهاد ومسلم في الجهاد أيضا «رباعيته» السن التي بين الثنية والناب، والجمع رباعيات: ويقال للذي يلقي رباعيته: رباع: بوزن ثاَن و «هشمت» الهشم: كسر الشيء اليابس.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, '«البيضة» واحدة البيض من الحديد «المجن» بالكسر الترس (2) البدَيّ: نبات يعمل منه الحصر. انظر المصباح المنير', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ فِي الْعِلَاجِ بِشُرْبِ الْعَسَلِ، وَالِْحجَامَةِ، وَالْكَيِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'فِي «صَحِيحِ الْبُخَارِيِّ » : عَنْ سَعِيدِ بْنِ جُبَـيٍْر، عَنِ ابْنِ عَبهاسٍ ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، قَالَ: «الشِّ فَاءُ فِي ثَلَاثٍ: شَرْبَةِ عَسَلٍ، وَشَرْطَةِ مِجَُْمٍ، وَكَيهةِ نَارٍ، وَأَنَا أَنْـهَى أُمهتِي عَنِ الْكَيِّ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'قَالَ أَبُو عَبْدِ ا هلِلَّ الْمَازِرِيُّ: الَْأمْرَاضُ الِامْتِلَائِيهةُ: إِمها أَنْ تَكُونَ دَمَوِيهةً، أَوْ صَفْرَاوِيهةً، أَوْ بَـلْغَمِيهةً، أَوْ سَوْدَاوِيهةً. فَإِنْ كَانَتْ  دَمَوِيهةً، فَشِفَاؤُهَا إِخْ رَاجُ الدهمِ، وَإِنْ كَانَتْ  مِنَ الَْأقْسَامِ الثهلَاثَةِ الْبَاقِيَةِ، فَشِفَاؤُهَا بِالِْإسْهَالِ الهذِي يَلِيقُ بِكُلِّ خَلْطٍ مِنْـهَا، وَكَأَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ نَـبههَ بِالْعَسَلِ عَلَى الْمُسَهِّلَاتِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَبِالِْحجَامَةِ عَلَى الْفَصْدِ، وَقَدْ قَالَ بَـعْضُ النهاسِ : إِنه الْفَصْدَ يَدْخُلُ فِي قَـوْلِهِ: «شَرْطَةِ مِجَُْمٍ» . فَإِذَا أَعْيَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الدهوَاءُ، فَآخِرُ الطِّبِّ الْكَيُّ، فَذَكَرَهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي الَْأدْوِيَةِ، لَِأنههُ يُسْتَـعْمَلُ عِنْدَ غَلَبَةِ الطِّبَاعِ لِقُوَى الَْأدْوِيَةِ، وَحَيْثُ لَا يَـنْـفَعُ الدهوَاءُ الْمَشْرُوبُ . وَقَـوْلُهُ: «وَأَنَا أَنْـهَى أُمهتِي عَنِ الْكَيِّ» ، وَفِي الَْحدِيثِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الْآخَرِ: «وَمَا أُحِبُّ أَنْ أَكْتَوِيَ» »2« ، إِشَارَةٌ إِلَى أَنْ يُـؤَخهرَ الْعِلَاجُ بِهِ حَ هتى تَدْفَعَ الضهرُورَةُ إِلَيْهِ، وَلَا يُـعَجهلُ التهدَاوِي بِهِ لِمَا فِيهِ مِنَ اسْتِعْجَالِ الَْألََِ الشهدِيدِ فِي دَفْعِ أَلٍََ قَدْ يَكُونُ أَضْعَفَ مِنْ أَلََِ الْكَيِّ، انْـتَـهَى كَلَامُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَقَالَ بَـعْضُ الَْأطِبهاءِ: الَْأمْرَاضُ الْمِزَاجِيهةُ: إِمها أَنْ تَكُونَ بَِمادهةٍ، أَوْ بِغَيِْر مَادهةٍ، وَالْمَادِّيهةُ مِنْـهَا: إِمها حَارهةٌ، أَوْ بَارِدَةٌ، أَوْ رَطْبَةٌ، أَوْ يَابِسَةٌ، أَوْ مَا تَـرَكهبَ مِنْـهَا، وَهَذِهِ الْكَيْفِيهاتُ الَْأرْبَعُ، مِنْـهَا كَيْفِيهـتَانِ فَاعِلَتَانِ : وَهُاَُ الَْحرَارَةُ وَالْبُـرُودَةُ، وَكَيْفِيهـتَانِ  مُنْـفَعِلَتَانِ؛ وَهُاَُ الرُّطُوبَةُ وَالْيُـبُوسَةُ، وَيَـلْزَمُ مِنْ  غَلَبَةِ إِحْدَى الْكَيْفِيهـتَـيِْن الْفَاعِلَتَـيِْن اسْتِصْحَابُ كَيْفِيهةٍ مُنْـفَعِلَةٍ مَعَهَا، وَكَذَلِكَ كَانَ لِكُلِّ وَاحِدٍ مِنَ الَْأخْلَاطِ الْمَوْجُودَةِ فِي الْبَدَنِ، وَسَائِرِ الْمُرَكهبَاتِ كَيْفِيهـتَانِ: فَاعِلَةٌ ومنفعلة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '(7) أخرجه البخاري، وابن ماجه في الطب عن ابن عباس. (2) أخرجه البخاري في الطب ومسلم في السلام.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'فَحَصَلَ مِنْ ذَلِكَ أَنه أَصْلَ الَْأمْرَاضِ الْمِزَاجِيهةِ هِيَ التهابِعَةُ لَِأقْـوَى كَيْفِيهاتِ الَْأخْلَاطِ الهتِي هِيَ الَْحرَارَةُ وَالْبُـرُودَةُ، فَجَاءَ كَلَامُ النُّـبُـهوةِ فِي أَصْلِ مُعَالََجةِ الَْأمْرَاضِ الهتِي هِيَ الَْحارهةُ وَالْبَارِدَةُ عَلَى طَرِيقِ التهمْثِيلِ، فَإِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'كَانَ الْمَرَضُ حَارًّا، عَالَْجنَاهُ بِِإخْرَاجِ الدهمِ، بِالْفَصْدِ كَانَ أَوْ بِالِْحجَامَةِ، لَِأنه فِي ذَلِكَ اسْتِفْرَاغًا لِلْمَادهةِ، وَتَـبِْيَدًا لِلْمِزَاجِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَإِنْ كَانَ بَارِدًا عَالَْجنَاهُ بِالتهسْخِيِن، وَذَلِكَ مَوْجُودٌ فِي الْعَسَلِ، فَإِنْ كَانَ يُْحتَاجُ مَعَ ذَلِكَ إِلَى اسْتِفْرَاغِ الْمَادهةِ الْبَارِدَةِ، فَالْعَسَلُ أَيْضًا يَـفْعَلُ فِي ذَلِكَ لِمَ ا فِيهِ مِنَ الِْإنْضَاجِ، وَالتهـقْطِيعِ، وَالتهـلْطِيفِ، وَالَْجلَاءِ، وَالتهـلْيِيِن، فَـيَحْصُلُ بِذَلِكَ اسْتِفْرَاغُ تِلْكَ الْمَادهةِ بِرِفْقٍ وَأَمْنٍ مِنْ نِكَايَةِ الْمُسْهِلَاتِ الْقَوِيهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَأَمها الْكَيُّ: فَلِنَِه كُله وَاحِدٍ مِنَ الَْأمْرَاضِ الْمَادِّيهةِ، إِمها أَنْ يَكُونَ حَادًّا فَـيَكُونَ سَرِيعَ الِْإفْضَاءِ لَِأحَدِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'الطهرَفَـيِْن، فَلَا يُْحتَاجُ إِلَيْهِ فِيهِ، وَإِمها أَنْ يَكُونَ مُزْمِنًا، وَأَفْضَلُ عِلَاجِهِ بَـعْدَ الِاسْتِفْرَاغِ الْكَيُّ فِي الَْأعْضَاءِ الهتِي يَُجوزُ فِيهَا الْكَيُّ، لَِأنههُ لَا يَكُونُ مُزْمِنًا إِهلا عَنْ مَادهةٍ بَارِدَةٍ غَلِيظَةٍ قَدْ رَسَخَتْ فِي الْعُضْوِ، وَأَفْسَدَتْ مِزَاجَهُ، وَأَحَالَتْ جَِيَعَ مَا يَصِلُ إِلَيْهِ إِلَى مُشَابَـهَةِ جَوْهَرِهَا، فَـيَشْتَعِلُ فِي ذَلِكَ الْعُضْوِ، فَـيُسْتَخْ رَجُ بِالْكَيِّ تِلْكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'الْمَادهةُ مِنْ ذَلِكَ الْمَكَانِ الهذِي هُوَ فِيهِ بِِإفْـنَاءِ الُْجزْءِ النهارِيِّ الْمَوْجُودِ بِالْكَيِّ لِتِلْكَ الْمَادهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'فَـتَـعَلهمْنَا بَِهذَا الَْحدِيثِ  الشهرِيفِ أَخْذَ مُعَالََجةِ الَْأمْرَاضِ الْمَادِّيهةِ جَِيَعِهَا، كَمَا اسْتَـنْـبَطْنَا مُعَالََجةَ الَْأمْرَاضِ السهاذَجَةِ مِنْ قَـوْلِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إِنه شِدهةَ الُْحمهى مِنْ فَـيْحِ جَهَنهمَ، فأبردوها بالماء» .', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل: [في الحجامة]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَمها الِْحجَامَةُ، فَفِي «سُنَنِ ابْنِ مَاجَهْ» مِنْ حَدِيثِ جُبَارَةَ بْنِ الْمُغَلِّسِ ، - وَهُوَ ضَعِيفٌ - عَنْ كثير بن سليم، قَالَ: سَِمعْتُ أَنَسَ بْنَ مَالِكٍ يَـقُولُ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَا مَرَرْتُ لَيْـلَةً أُسْرِيَ بِي بَِملٍَْ إِهلا قَالُوا: يَا مُمَُهدُ! مُرْ أُمهتَكَ بِالِْحجَامَةِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَرَوَى الترمذي فِي «جَامِعِهِ» مِنْ حَدِيثِ ابْنِ عَبهاسٍ هَذَا الَْحدِيثَ : وَقَالَ فِيهِ: «عَلَيْكَ بالحجامة يا ممُّد»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(7) أخرجه ابن ماجه. وسنده ضعيف وهو حديث صحيح بشواهده وفي الباب عن ابن مسعود وابن عباس عند الترمذي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وفي «الصحيحين» : من حديث طاووس، عَنِ ابْنِ عَهباسٍ ، أَنه الهنبِه صَلهى ا هللَُّ عَلَيْهِ وَسَ هلمَ «احْتَجَمَ وَأَعْطَى الَْحجهامَ أَجْ رَهُ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَفِي «الصهحِيحَيِْن» أَيْضًا، عَنْ حُيَْْدٍ الطهوِيلِ، عَنْ أنس، أن رسول الله هللا ىلص حَجَمَهُ أبو طيبة، فَأَمَرَ لَهُ بِصَاعَيِْن مِنْ طَعَامٍ، وَكَلهمَ مَوَالِيَهُ، فَخَ هففُوا عَنْهُ مِنْ ضَرِيبَتِهِ، وَقَالَ: «خَيْـرُ مَا تَدَاوَيْـتُمْ بِهِ الِْحجَامَةُ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَفِي «جَامِعِ الترمذي» عَنْ عَبهادِ بْنِ مَنْصُورٍ، قَالَ: سَِمعْتُ عكرمة يَـقُولُ: كَانَ لِابْنِ عَبهاسٍ غِلْمَةٌ ثَلَاثَةٌ حَجهامُونَ، فَكَانَ اثْـنَانِ يُـغَهلانِ عَلَيْهِ، وَعَلَى أَهْلِهِ، وَوَاحِدٌ لَِحجْمِهِ، وَحَجْمِ أَهْلِهِ. قَالَ: وَقَالَ ابْنُ عَبهاسٍ : قَالَ نَبُِّ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «نِعْمَ الْعَبْدُ الَْحجهامُ يَذْهَبُ بِالدهمِ، وَيُِخفُّ الصُّلْبَ ، وَيَْجلُو الْبَصَرَ» ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَقَالَ: إِنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ حَيْثُ عُرجَِ به، ما مرّ على ملاء مِنَ الْمَلَائِكَةِ إِهلا قَالُوا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '«عَلَيْكَ بِالِْحجَامَةِ» ، وَقَالَ: «إِنه خَيْـرَ مَا تَتََْجِمُونَ فِيهِ يَـوْمَ سَبْعَ عشرة، ويوم تسع عَشْرَةَ، وَيَـوْمَ تِسْعَ عَشْرَةَ، وَيَـوْمَ إِحْدَى وَعِشْرِينَ، وَقَالَ: «إِنه خَيْـرَ مَا تَدَاوَيْـتُمْ بِهِ السُّعُوطُ وَاللُّدُودُ وَالِْحجَامَةُ وَالْمَشْيُ، وَأَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لُده فَـقَالَ: «مَنْ لَدهنِي» ؟ فَكُلُّهُمْ أَمْسَكُوا، فَـقَالَ: «لَا يَـبْـقَى أَحَدٌ فِي الْبَـيْتِ إِهلا لُده إِهلا الْعَبهاسَ » . قَالَ: هَذَا حديث غريب، ورواه ابن ماجه» .', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل: [في منافع الحجامة]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'أما منافع الحجامة: فإنها تنفي سَطْحَ الْبَدَنِ أَكْ ثَـرَ مِنَ الْفَصْدِ، وَالْفَصْدُ لَِأعْمَاقِ الْبَدَنِ أَفْضَلُ، وَالِْحجَامَةُ تَسْتَخْرِجُ الدهمَ مِنْ نَـوَاحِي الِْجلْدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'قُـلْتُ : وَالتهحْقِيقُ فِي أَمْرِهَا وَأَمْرِ الْفَصْدِ، أَنهـهُمَا يَْختَلِفَانِ بِاخْتِلَافِ الهزمَانِ، وَالْمَكَانِ، وَالَْأسْنَانِ، وَالَْأمْزِجَةِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'فالبلاد الحارة، والأزمنة الحارة، والأمزجة الحارة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(7) أخرجه البخاري في الطب ومسلم في المساقاة. وفي الجامع الصغير: «خير ما تداويتم به الحجامة» رواه الإمام أحدْ والطباَني في الكبير عن سمرة بن جندب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(2) أخرجه الترمذي وابن ماجه وسنده ضعيف لضعف عباد بن منصور: «السّعوط» دواء يصب في الأنف- انظر المصباح المنير. الّلدود كصبور ما يصب بالمسط من الدواء في أحد شقي الفم كالّديد- انظر القاموس المحيط.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الهتِي دَمُ أَصْحَابَِها فِي غَايَةِ النُّضْجِ الِْحجَامَةُ فِيهَا أَنْـفَعُ مِنَ الْفَصْدِ بِكَثِيٍر، فَإِنه الدهمَ يَـنْضَجُ وَيَرِقُّ وَيَْخرُجُ إِلَى سَطْحِ الَْجسَدِ الدهاخِلِ، فَـتُخْرِجُ الِْحجَامَةُ مَا لَا يُْخرِجُهُ الْفَصْدُ، وَلِذَلِكَ كَانَتْ أَنْـفَعَ لِلصِّ بْـيَانِ مِنَ الْفَصْدِ، وَلِمَنْ لَا يَـقْوَى عَلَى الْفَصْدِ وَقَدْ نَصه الَْأطِبهاءُ عَلَى أَنه الْبِلَادَ الَْحارهةَ الِْحجَامَةُ فِيهَا أَنْـفَعُ وَأَفْضَلُ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الْفَصْدِ، وَتُسْتَحَبُّ فِي وَسَطِ الشههْرِ، وَبَـعْدَ وَسَطِهِ. وَبِالُْجمْلَةِ، فِي الرُّبُعِ الثهالِثِ مِنْ أَرْبَاعِ الشههْرِ، لَِأنه الدهمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'فِي أَهولِ الشههْرِ لََْ يَكُنْ بَـعْدُ قَدْ هَاجَ وَتَـبَـيهغَ، وَفِي آخِرِهِ يَكُونُ قَدْ سَكَنَ. وَأَمها فِي وَسَطِهِ وَبُـعَيْدَهُ، فَـيَكُونُ فِي نَِهايَةِ التهـزَيُّدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'قَالَ صَاحِبُ الْقَانُونِ: وَيُـؤْمَرُ بِاسْتِعْمَالِ الِْحجَامَةِ لَا فِي أَهولِ الشههْرِ، لَِأنه الَْأخْلَاطَ لَا تَكُونُ قَدْ تَهََركَتْ وَهَاجَتْ ، وَلَا فِي آخِرِهِ لَِأنهـهَا تَكُونُ قَدْ نَـقَصَتْ ، بَلْ فِي وَسَطِ الشههْرِ حِيَن تَكُونُ الَْأخْلَاطُ هَائِجَةً بَالِغَةً فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'تَـزَايُدِهَا لِتَـزَيُّدِ النُّورِ فِي جُرْمِ الْقَمَرِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَقَدْ رُوِيَ عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، أَنههُ قَالَ: «خَيْـرُ مَا تَدَاوَيْـتُمْ بِهِ الِْحجَامَةُ وَالْفَصْدُ» »7« . وَفِي حَدِيثٍ: «خَيْـرُ الدهوَاءِ الِْحجَامَةُ وَالْفَصْدُ» . انْـتَـهَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَقَـوْلُهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «خَيْـرُ مَا تَدَاوَيْـتُمْ بِهِ الِْحجَامَةُ» إِشَارَةٌ إِلَى أَهْلِ الِْحجَازِ، وَالْبِلَادِ الَْحارهةِ، لَِأنه دِمَاءَهُمْ رَقِيقَةٌ، وَهِيَ أَمْيَلُ إِلَى ظَاهِرِ أَبْدَانِِهمْ لَِجذْبِ الَْحرَارَةِ الَْخارِجَةِ لَهاَ إِلَى سَطْحِ الَْجسَدِ، وَاجْتِمَاعِهَا فِي نَـوَاحِي الِْجلْدِ، وَلَِأنه مَسَامه أَبْدَانِِهمْ وَاسِعَةٌ، وَقُـوَاهُمْ مُتَخَلْخِلَةٌ، فَفِي الْفَصْدِ لَهمُْ خَطَرٌ، وَالِْحجَامَةُ تَـفَرُّقٌ اتِّصَالٌِِّ إِرَادِيٌّ يَـتْـبَـعُهُ اسْتِفْرَاغٌ كُلِّيٌّ مِنَ الْعُرُوقِ وَخَاصهةً الْعُرُوقَ الهتِي لَا تُـفْصَدُ كَثِيًرا وَلِفَصْدِ كُلِّ وَاحِدٍ مِنْـهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'نَـفْعٌ خَاصٌّ، فَـفَصْدُ الْبَاسَلِيقِ: يَـنْـفَعُ مِنْ حَرَارَةِ الْكَبِدِ وَالطِّحَالِ وَالَْأوْرَامِ الْكَائِنَةِ فِيهِمَا مِنَ الدهمِ، وَيَـنْـفَعُ مِنْ أَوْرَامِ الرِّئَةِ، وَيَـنْـفَعُ مِنَ الشُّوصَةِ »2« وَذَاتِ الَْجنْبِ وَجَِيَعِ الَْأمْرَاضِ الدهمَوِيهةِ الْعَارِضَةِ مِنْ أَسْفَلِ الرُّكْ بَةِ إِلَى الْوَرِكِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَفَصْدُ الَْأكْحَلِ: يَـنْـفَعُ مِنَ الِامْتِلَاءِ الْعَارِضِ فِي جَِيَعِ الْبَدَنِ إِذَا كَانَ دَمَوِيًّا، وَكَذَلِكَ إِذَا كَانَ الدهمُ قَدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'فَسَدَ فِي جَِيَعِ الْبَدَنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَفَصْدُ الْقِيفَالِ: »3« يَـنْـفَعُ مِنَ الْعِلَلِ الْعَارِضَةِ فِي الهرأْسِ وَالهرقَـبَةِ مِنْ كَثْـرَةِ الدهمِ أو فساده.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, '(7) أخرجه ابو نعيم في كتاب الطب النبوي بلفظ «خير ما تداويتم به الحجم والفصد» عن علي أمير المؤمنين هللا يضر، أما لفظ «خير ما تداويتم به الحجامة والفصد» بتأنيث الحجامة لَ نعثر عليه في شيء من كتب الحديث التي اطلعنا عليها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, '(2) الشّوصة: وجع في البطن، أو هي ريح تعتقب في الأضلاع، أو ورم في حجابها من داخل، واحتلاح', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'العرق- انظر القاموس المحيط', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, '(3) القيفال بالكسر: عرق في اليد يفصد- المرجع السابق', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَفَصْدُ الْوَدَجَيِْن: يَـنْـفَعُ مِنْ وَجَعِ الطِّحَالِ، وَالهربْوِ، وَالْبَـهَرِ، وَوَجَعِ الَْجبِيِن: وَالِْحجَامَةُ عَلَى الْكَاهِلِ: تَـنْـفَعُ مِنْ وَجَعِ الْمَنْكِبِ وَالَْحلْقِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَالِْحجَامَةُ عَلَى الَْأخْدَعَيِْن، تَـنْـفَعُ مِنْ أَمْرَاضِ الهرأْسِ ، وَأَجْ زَائِهِ، كَالْوَجْهِ، وَالَْأسْنَانِ، وَالُْأذُنَـيِْن، وَالْعَيْـنَـيِْن، وَالَْأنْفِ، وَالَْحلْقِ إِذَا كَانَ حُدُوثُ ذَلِكَ عَنْ كَثْـرَةِ الدهمِ أَوْ فَسَادِهِ، أَوْ عَنْـهُمَا جَِيَعًا. قَالَ أنس رَضِيَ ا هللَُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'تَـعَالَى عَنْهُ: كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَْحتَجِمُ فِي الَْأخْدَعَيِْن وَالْكَاهِلِ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَفِي «الصهحِيحَيِْن» عَنْهُ: كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يحتحم ثَلَاثًَ: وَاحِدَةً عَلَى كَاهِلِهِ، وَاثْـنَـتَـيِْن عَلَى الَْأخْدَعَيِْن »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'وَفِي الصهحِيحِ: عَنْهُ، أَنههُ احْتَجَمَ وَهُوَ مُرُِْمٌ فِي رَأْسِهِ لِصُدَاعٍ كَانَ بِهِ »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» عَنْ علي، نَـزَلَ جِبِْيَلُ عَلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بِِحجَامَةِ الَْأخْدَعَيِْن وَالْكَاهِلِ »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, '«احْتَجَمَ فِي وَركِِهِ مِنْ وَثْ ءٍ كَانَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَفِي «سُنَنِ أبي داود» مِنْ حَدِيثِ جابر، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بِهِ» »5« .', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَاخْتَـلَفَ الَْأطِبهاءُ فِي الِْحجَامَةِ عَلَى نُـقْرَةِ الْقَفَا، وَهِيَ الْقَمَحْدُوَةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَذكََرَ أبو نعيم فِي كِتَابِ الطِّبِّ النهـبَوِيِّ حَدِيثًا مَرْفُوعًا «عَلَيْكُمْ بِالِْحجَامَةِ في جوزة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(7) أخرجه الترمذي في سننه وفي كتاب الشمائل له وأبو داود وابن ماجه والإمام أحدْ والحاكم وصححه وأقره الذهب على ذلك: وهذا الحديث بزيادة «وكان يحتجم لسبع عشرة، وتسع عشرة، وإحدى وعشرين: أخرجه الترمذي والحاكم في الطب عن أنس بن مالك، والطباَني في الكبير- والحاكم في الطب أيضا عن ابن عباس وقال صحيح على شرطهما وقال الترمذي: حسن غريب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(2) لَ يخرّج هذا الحديث في الصحيحين، وإنما خرجه الإمام أحدْ وأصحاب السنن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(3) أخرجه البخاري في الطب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(4) أخرجه ابن ماجه. وسنده ضعيف', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '(5) أخرجه أبو داود ورجاله ثقات. والوشء، والوشاءة: وصم يصيب اللحم لا يبلغ العظم، أو توجّع في العظم بلا كسر أو هو الفلك: وثئت يده كفرح تثأ وشأ فهي وثئة كفرحة- انظر القاموس المحيط.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'الْقَمَحْدُوَةِ، فَإِنهـهَا تَشْفِي مِنْ خَْمسَةِ أَدْوَاءٍ» ، ذكََرَ مِنْـهَا الُْجذَامَ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَفِي حَدِيثٍ آخَرَ: «عَلَيْكُمْ بِالِْحجَامَةِ فِي جَوْزَةِ الْقَمَحْدُوَةِ، فَإِنهـهَا شِفَاءٌ مِنَ اثْـنَـيِْن وَسَبْعِيَن دَاءً» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'فَطَائِفَةٌ مِنْـهُمُ اسْتَحْسَنَـتْهُ وَقَالَتْ : إِنهـهَا تَـنْـفَعُ مِنْ جَحْظِ الْعَيِْن، وَالنُّـتُوءِ الْعَارِضِ فِيهَا، وَكَثِيٍر مِنْ أَمْرَاضِهَا، وَمِنْ ثِقَلِ الَْحاجِبَـيِْن وَالَْجفْنِ، وَتَـنْـفَعُ مِنْ جَرَبِهِ. وَرُوِيَ أَنه أَحْدََْ بْنَ حَنْـبَلٍ احْ تَاجَ إِلَيْـهَا، فَاحْتَجَمَ فِي جَانِبَْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'قَـفَاهُ، وَلََْ يَْحتَجِمْ فِي النُّـقْرَةِ، وَمِمهنْ كَرِهَهَا صَاحِبُ «الْقَانُونِ» وَقَالَ: إِنهـهَا تُورِثُ النِّسْيَانَ حَقًّا، كَمَا قَالَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'سَيِّدُنَا وَمَوْلَانَا وَصَاحِبُ شَرِيعَتِنَا مُمَُهدٌ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَإِنه مُؤَخهرَ الدِّمَاغِ مَوْضِعُ الِْحفْظِ، وَالِْحجَامَةُ تُذْهِبُهُ، انْـتَـهَى كَلَامُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَرَده عَلَيْهِ آخَرُونَ، وَقَالُوا: الَْحدِيثُ لَا يَـثْـبُتُ ، وَإِنْ ثَـبَتَ فَالِْحجَامَةُ إِهنَما تُضْعِفُ مُؤَخهرِ الدِّمَاغِ إِذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'اسْتُـعْمِلَتْ لِغَيِْر ضَرُورَةٍ، فَأَمها إِذَا اسْتُـعْمِلَتْ  لِغَلَبَةِ الدهمِ عَلَيْهِ، فَإِنهـهَا نَافِعَةٌ لَهُ طِبًّا وَشَرْعًا، فَـقَدْ ثَـبَتَ  عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ احْتَجَمَ فِي عِدهةِ أَمَاكِنَ مِنْ قَـفَاهُ بَِحسْبِ مَا اقْـتَضَاهُ الَْحالُ فِي ذَلِكَ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَاحْتَجَمَ فِي غَيِْر الْقَفَا بَِحسْبِ مَا دَعَتْ إِلَيْهِ حاجته.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل: [في منافع الحجامة تتَ الذقن]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَالِْحجَامَةُ تَْتََ الذهقَنِ تَـنْـفَعُ مِنْ وَجَعِ الَْأسْنَانِ وَالْوَجْهِ وَالُْحلْقُومِ، إِذَا اسْتُـعْمِلَتْ فِي وَقْتِهَا، وَتُـنَـقِّي انرأس', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَالْفَكهيِْن، وَالِْحجَامَةُ عَلَى ظَهْرِ الْقَدَمِ تَـنُوبُ عَنْ فَصْدِ الصهافِنِ، وَهُوَ عِرْقٌ عَظِيمٌ عِنْدَ الْكَعْبِ، وَتَـنْـفَعُ مِنْ قُـرُوحِ الْفَخِذَيْنِ وَالسهاقَـيِْن، وَانْقِطَاعِ الطهمْثِ، وَالَْحكهةِ الْعَارِضَةِ فِي الُْأنْـثَـيَـيِْن، وَالِْحجَامَةُ فِي أَسْفَلِ الصهدْرِ نَافِعَةٌ مِنْ دَمَامِيلِ الْفَخِذِ، وَجَرَبِهِ وَبُـثُورِهِ، وَمِنَ النِّقْرِسِ وَالْبَـوَاسِيِر، وَالْفِيلِ وَحَكهةِ الظههْرِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل فِي هَدْيِهِ فِي أَوْقَاتِ الِْحجَامَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى الترمذي فِي «جَامِعِهِ» : مِنْ حَدِيثِ ابْنِ عَبهاسٍ يَـرْفَـعُهُ: «إنّ خير ما تتَجمون فيه يَـوْمِ سَابِعَ عَشْرَةَ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'أَوْ تَاسِعَ عَشْرَةَ، وَيَـوْمِ إحدى وعشرين »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(7) رواه الطباَني في الكب، وابن السنِ، وأبو نعيم عن صهيب بلفظ «عليكم بالحجامة في جوزة القمدوة، فإنها دواء من اثنين وسبعين داء وخمسة أدواء: من الجنون، والجذام، والبصَ «وجع الضرس» والحديث بهذا النص يجمع بين الحديث الذي قال المصنف: رواه أبو نعيم، وبين الحديث الذي ذكره بعده.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(2) أخرجه الترمذي وسنده ضعيف فيه عباد بن منصور', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَفِيهِ عَنْ أنس كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَ هلمَ يَْحتَجِمُ فِي الَْأخْدَعَيِْن وَالْكَاهِلِ، وَكَانَ يَْحتَجِمُ لِسَبْـعَةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'عَشَرَ، وَتِسْعَةَ عَشَرَ، وَفِي إِحْدَى وَعِشْرِينَ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» عَنْ أنس مَرْفُوعًا: «مَنْ أَرَادَ الِْحجَامَةَ فَـلْيَـتَحَ هر سَبْـعَةَ عَشَرَ، أَوْ تِسْعَةَ عَشَرَ، أَوْ إِحْدَى وَعِشْرِينَ، لَا يَـتَـبَـيهغْ بَِأحَدِكُمُ الدهمُ فَـيَـقْتُـلَهُ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَفِي «سُنَنِ أبي داود» مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ مَرْفُوعًا: «مَنِ احْتَجَمَ لِسَبْعَ عَشْرَةَ، أَوْ تِسْعَ عَشْرَةَ، أَوْ إِحْدَى وَعِشْرِينَ، كَانَتْ شِفَاءً مِنْ كُلِّ دَاءٍ »2« وَهَذَا مَعْنَاهُ مِنْ كُلِّ دَاءٍ سَبَـبُهُ غَلَبَةُ الدهمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَهَذِهِ الَْأحَادِيثُ مُوَافِقَةٌ لِمَا أَجْعَََ عَلَيْهِ الَْأطِبهاءُ، أَنه الِْحجَامَةَ فِي النِّصْفِ الثهانِي، وَمَا يَلِيهِ مِنَ الرُّبُعِ الثهالِثِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'مِنْ أَرْبَاعِهِ أَنْـفَعُ مِنْ أَهولِهِ وَآخِرِهِ، وَإِذَا اسْتُـعْمِلَتْ عِنْدَ الَْحاجَةِ إِلَيْـهَا نَـفَعَتْ أَيه وَقْتٍ كَانَ مِنْ أَهولِ الشههْرِ وَآخِرِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'قَالَ الخلال: أَخْ بَـرَنِي عصمة بن عصام، قَالَ حَدهثَـنَا حنبل، قَالَ: كَانَ أَبُو عَبْدِ ا هلِلَّ أَحْدَُْ بْنُ حَنْـبَلٍ يَْحتَجِمُ أَيه وَقْتٍ هَاجَ بِهِ الدهمُ، وَأَيه سَاعَةٍ كَانَتْ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَقَالَ صَاحِبُ «الْقَانُونِ» : أَوْقَاتُـهَا فِي النهـهَارِ: السهاعَةُ الثهانِيَةُ أَوِ الثهالِثَةُ، وَيَِجبُ تَـوَقِّيهَا بَـعْدَ الَْحمهامِ إِهلا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'فِيمَنْ دَمُهُ غَلِيظٌ، فَـيَجِبُ أَنْ يَسْتَحِمه، ُ مه يَسْتَجِمه سَاعَةً، ُ مه يَْحتَجِمَ، انْـتَـهَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَتُكْ رَهُ عِنْدَهُمُ الِْحجَامَةُ عَلَى الشِّ بَعِ فَإِنَِّها رُهبَما أَوْرَثَتْ سَدَدًا وَأَمْرَاضًا رَدِيئَةً، لَا سِيهمَا إِذَا كَانَ الْغِذَاءُ رَدِيئًا غَلِيظًا. وَفِي أَثَرٍ الِْحجَامَةُ عَلَى الرِّيقِ دَوَاءٌ، وَعَلَى الشِّ بَعِ دَاءٌ، وَفِي سَبْـعَةَ عَشَرَ مِنَ الشههْرِ شِفَاءٌ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَاخْ تِيَارُ هَذِهِ الَْأوْقَاتِ لِلْحِجَامَةِ، فِيمَا إِذَا كَانَتْ عَلَى سَبِيلِ الِاحْتِيَاطِ وَالتهحَرُّزِ مِنَ الَْأذَى، وَحِفْظًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'لِلصِّحهةِ. وَأَمها فِي مُدَاوَاةِ الَْأمْرَاضِ ، فَحَيْـثُمَا وُجِدَ الِاحْ تِيَاجُ إِلَيْـهَا وَجَبَ اسْتِعْمَالَُها. وَفِي قَـوْلِهِ: «لَا يَـتَـبَـيهغْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'بَِأحَدِكُمُ الدهمُ فَـيَـقْتُـلَهُ» ، دَلَالَةٌ عَلَى ذَلِكَ ، يَـعْنِِ لِئَهلا يتبيغ، فحذف حرف الجرمع )أَنْ ( ، ُ مه حُذِفَتْ )أَنْ( . وَالتهـبَـيُّغُ: الَْهيْجُ، وَهُوَ مَقْلُوبُ الْبَـغْيِ ، وَهُوَ بَِمعْنَاهُ، فَإِنههُ بَـغْيُ الدهمِ وَهَيَجَانُهُ. وَقَدْ تَـقَدهمَ أَنه الِْإمَامَ أَحْدََْ كَانَ يحتجم أيّ وقت احتاج من الشهر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, '(7) أخرجه الترمذي في الطب وقال حديث حسن غريب، ورجاله ثقات (2) أخرجه ابن ماجه وهو ضعيف في سنده النهاس بن قهم', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل [في وقت الحجامة]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَمها اخْ تِيَارُ أَهيامِ الُْأسْبُوعِ لِلْحِجَامَةِ، فَـقَالَ الخلال في «جامعه» : أخبنَا حرب ابن إِسَْماعِيلَ، قَالَ: قُـلْتُ لأحدْ تُكْ رَهُ الِْحجَامَةُ فِي شَيْ ءٍ مِنَ الَْأهيامِ؟ قَالَ: قَدْ جَاءَ فِي الَْأرْبِعَاءِ وَالسهبْتِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَفِيهِ: عَنِ الحسين بن حسان، أَنههُ سَأَلَ أبا عبد الله عَنِ الِْحجَامَةِ: أَيه يَـوْمٍ تُكْرَهُ؟ فَـقَالَ: فِي يَـوْمِ السهبْتِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَيَـوْمِ الَْأرْبِعَاءِ، وَيَـقُولُونَ: يَـوْمَ الُْجمُعَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَرَوَى الَْخهلالُ، عَنْ أبي سلمة وأبي سعيد المقبيَ، عَنْ أَبِي هُرَيْـرَةَ مَرْفُوعًا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '«مَنِ احْتَجَمَ يَـوْمَ الَْأرْبِعَاءِ أَوْ يَـوْمَ السهبْتِ، فَأَصَابَهُ بَـيَاضٌ أَوْ بَـرَصٌ ، فَلَا يَـلُومَنه إِهلا نَـفْسَهُ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَقَالَ الخلال: أَخْ بَـرَنَا محمد بن علي بن جعفر، أَنه يعقوب بن ختِان حدثهم، فال: سُئِلَ أحدْ عَنِ النهـوْرَةِ وَالِْحجَامَةِ يَـوْمَ السهبْتِ وَيَـوْمَ الَْأرْبِعَاءِ؟ فَكَرِهَهَا. وَقَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'بَـلَغَنِِ عَنْ رَجُلٍ أَنههُ تَـنَـهورَ وَاحْتَجَمَ يَـعْنِِ يَـوْمَ الَْأرْبِعَاءِ، فَأَصَابَهُ الْبَـرَصُ. قُـلْتُ لَهُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'كَأَنههُ تَـهَاوَنَ بِالَْحدِيثِ؟ قَالَ: نَـعَمْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَفِي كِتَابِ «الَْأفْـرَادِ» لِلدهارَقُطْنِِِّ، مِنْ حَدِيثِ نافع قَالَ: قَالَ لِِ عبد الله بن عمر: تَـبَـيهغَ بِي الدهمُ »2« ، فَابْغِ لِِ حَجهامًا، وَلَا يَكُنْ صَبِيًّا وَلَا شَيْخًا كَبِيًرا، فَإِنِّي سَِمعْتُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـقُولُ: «الِْحجَامَةُ تَزِيدُ الَْحافِظَ حِفْظًا، وَالْعَاقِلَ عَقْلًا، فَاحْ تَجِمُوا عَلَى اسْمِ ا هلِلَّ تَـعَالَى، وَلَا تَتََْجِمُوا الَْخمِيسَ ، وَالُْجمُعَةَ، وَالسهبْتَ ، وَالَْأحَدَ، وَاحْ تَجِمُوا الِاثْـنَـيِْن، وَمَا كَانَ مِنْ جُذَامٍ وَلَا بَـرَصٍ ، إِهلا نَـزَلَ يَـوْمَ الَْأرْبِعَاءِ» . قَالَ الدهارَقُطْنُِِّ: تَـفَهردَ بِهِ زياد بن يحيى وَقَدْ رَوَاهُ أيوب عَنْ نافع، وَقَالَ فِيهِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, '«وَاحْ تَجِمُوا يَـوْمَ الِاثْـنَـيِْن وَالثُّلَاثَءَِ، وَلَا تَتََْجِمُوا يَـوْمَ الَْأرْبِعَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَقَدْ رَوَى أبو داود فِي «سُنَنِهِ» مِنْ حَدِيثِ أبي بكرة، أَنههُ كَانَ يَكْ رَهُ الِْحجَامَةَ يَـوْمَ الثُّلَاثَءَِ، وَقَالَ: إِنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وسلم قال: «يَـوْمُ الثُّلَاثَءَِ يَـوْمُ الدُّمِ وَفِيهِ سَاعَةٌ لَا يرقأ فيها الدّم» »3«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, '(7) أخرجه البيهقي والحاكم وفي سند هذا الحديث سليمان بن أرقم وهو متروك (2) «تبيغ بي الدم» البيغ: ثوران الدم: أخرجه ابن ماجه والحاكم', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, '(3) أخرجه أبو داود', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَفِي ضِمْنِ هَذِهِ الَْأحَادِيثِ الْمُتَـقَدِّمَةِ اسْتِحْبَابُ التهدَاوِي، وَاسْتِحْبَابُ الِْحجَامَةِ، وَأَنهـهَا تَكُونُ فِي الْمَوْضِ عِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'اهلذِي يَـقْتَضِيهِ الَْحالُ، وَجَوَازُ احْتِجَامِ الْمُحْرِمِ، وَإِنْ آلَ إِلَى قَطْعِ شَيْ ءٍ مِنَ الشهعْرِ، فَإِنه ذَلِكَ جَائِزٌ. وَفِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وُجُوبِ الْفِدْيَةِ عَلَيْهِ نَظَرٌ، وَلَا يَـقْوَى الْوُجُوبُ ، وَجَوَازُ احْتِجَامِ الصهائِمِ، فَإِنه فِي «صَحِيحِ الْبُخَارِيِّ » أَنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ «احْتَجَمَ وَهُوَ صَائِمٌ» »7« . وَلَكِنْ هَلْ يُـفْطِرُ بِذَلِكَ ، أَمْ لَا؟ مَسْأَلَةٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'أُخْ رَى، الصهوَابُ : الْفِطْرُ بِالِْحجَامَةِ، لِصِحهتِهِ عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مِنْ غَيِْر مُعَارِضٍ ، وَأَصَحُّ مَا يُـعَارَضُ بِهِ حَدِيثُ حِجَامَتِهِ وَهُوَ صَائِمٌ؛ وَلَكِنْ لَا يَدُلُّ عَلَى عَدَمِ الْفِطْرِ إلا بعد أربعة أموره أَحَدُهَا: أَنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الصهوْمَ كَانَ فَـرْضًا. الهثانِي: أَنههُ كَانَ مُقِيمًا. الثهالِثُ : أَنههُ لََْ يَكُنْ بِهِ مَرَضٌ احْتَاجَ مَعَهُ إِلَى الِْحجَامَةِ. الهرابِعُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'أَنه هَذَا الَْحدِيثَ مُتَأَخِّرٌ عَنْ قَـوْلِهِ: «أَفْطَرَ الَْحاجِمُ وَالْمَحْجُومُ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'فَإِذَا ثَـبَـتَتْ هَذِهِ الْمُقَدِّمَاتُ الَْأرْبَعُ، أَمْكَنَ الِاسْتِدْلَالُ بِفِعْلِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَلَى بَـقَاءِ الصهوْمِ مَعَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'الِْحجَامَةِ، وَإِهلا فَمَا الْمَانِعُ أَنْ يَكُونَ الصهوْمُ نَـفْلًا يَُجوزُ الُْخرُوجُ مِنْهُ بِالِْحجَامَةِ وَغَيِْرهَا، أَوْ مِنْ رَمَضَانَ لَكِنههُ فِي السهفَرِ، أَوْ مِنْ رَمَضَانَ فِي الَْحضَرِ، لَكِنْ دَعَتِ الَْحاجَةُ إِلَيْـهَا كَمَا تَدْعُو حَاجَةُ مَنْ بِهِ مَرَضٌ إِلَى الْفِطْرِ، أَوْ يَكُونُ فَـرْضًا مِنْ رَمَضَانَ فِي الَْحضَرِ مِنْ غَيِْر حَاجَةٍ إِلَيْـهَا، لَكِنههُ مُبْـقًى عَلَى الَْأصْلِ. وَقَـوْلُهُ: «أَفْطَرَ الَْحاجِمُ وَالْمَحْجُومُ» ، نَاقِلٌ وَمُتَأَخِّرٌ، فَـيَـتَـعَهيُن الْمَصِيُر إِلَيْهِ، وَلَا سَبِيلَ إِلَى إِثْـبَاتِ وَاحِدَةٍ مِنْ هَذِهِ الْمُقَدِّمَاتِ الَْأرْبَعِ، فَكَيْفَ بِِإثْـبَاتَِها كُلِّهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَفِيهَا دَلِيلٌ عَلَى اسْتِئْجَارِ الطهبِيبِ وَغَيِْرهِ مِنْ غَيِْر عَقْدِ إِجَارَةٍ، بَلْ يُـعْطِيهِ أُجْرَةَ الْمِثْلِ، أَوْ مَا يُـرْضِ يهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَفِيهَا دَلِيلٌ عَلَى جَوَازِ التهكَسُّبِ بِصِنَاعَةِ الِْحجَامَةِ، وَإِنْ كَانَ لَا يَطِيبُ لِلْحُرِّ أَكْلُ أُجْرَتِهِ مِنْ غَيِْر تَرَِْيٍم عَلَيْهِ، فَإِنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَعْطَاهُ أَجْ رَهُ، وَلََْ يَْمنَـعْهُ مِنْ أَكْ لِهِ، وَتَسْمِيَـتُهُ إِهياهُ خَبِيثًا كَتَسْمِيَتِهِ لِلثهـوْمِ وَالْبَصَلِ خَبِيثَـيِْن، وَلََْ يَـلْزَمْ مِنْ ذَلِكَ ترَيمهما.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '(7) أخرجه البخاري', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, '(2) أخرجه الإمام أحدْ وأبو داود وابن ماجه والحاكم عن توبان وهو متواتر: قال القاضي البيضاوي: ذهب إلى ظاهر الخبَ جعَ فقالوا: بفطرهاُ منهم أحدْ وذهب الأكثر للكراهة، وصحة الصوم، وحلْوا الخبَ على التشديد، وذهب قوم إلى منسوخ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَفِيهَا دَلِيلٌ عَلَى جَ وَازِ ضَرْبِ الهرجُلِ الَْخرَاجَ عَلَى عَبْدِهِ كُله يَـوْمٍ شَيْـئًا مَعْلُومًا بِقَدْرِ طَاقَتِهِ، وَأَنه لِلْعَبْدِ أَنْ يَـتَصَ هرفَ فِيمَا زَادَ عَلَى خَرَاجِهِ، وَلَوْ مُنِعَ مِنَ التهصَرُّفِ، لَكَانَ كَسْبُهُ كُلُّهُ خَرَاجًا وَلََْ يَكُنْ لِتَـقْدِيرِهِ فَائِدَةٌ، بَلْ مَا زَادَ عَلَى خَرَاجِهِ، فَـهُوَ تَلَِْيكٌ من سيده له بتصرف فيه كما أراد، والله أعلم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي قَطْعِ الْعُرُوقِ وَالْكَيِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'ثَـبَتَ فِي «الصهحِيحِ» مِنْ حَدِيثِ جَابِرِ بْنِ عَبْدِ ا هلِلَّ، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بَـعَثَ إِلَى أُبَِّي بْنِ كَعْبٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'طَبِيبًا، فَـقَطَعَ لَهُ عِرْقًا وَكَوَاهُ عَلَيْهِ »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَلَمها رُمِيَ سَعْدُ بْنُ مُعَاذٍ فِي أَكْحَلِهِ حَسَمَهُ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ ُ مه وَرِمَتْ ، فَحَسَمَهُ الثهانِيَةَ »2« . وَالَْحسْمُ: هُوَ الْكَيُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَفِي طَرِيقٍ آخَرَ: أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَوَى سَعْدَ بْنَ مُعَاذٍ فِي أَكْحَلِهِ بِِمشْقَصٍ ، ُ مه حَسَمَهُ سَعْدُ بْنُ مُعَاذٍ أَوْ غَيْـرُهُ مِنْ أَصْحَابِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَفِي لَفْظٍ آخَرَ: أَنه رَجُلًا مِنَ الَْأنْصَارِ رُمِيَ فِي أَكْحَلِهِ بِِمشْقَصٍ ، فَأَمَرَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بِهِ فَكُوِيَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَقَالَ أبو عبيد: وَقَدْ أُتَِي النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بِرَجُلٍ نُعِتَ لَهُ الْكَيُّ، فَـقَالَ: «اكْوُوهُ وَارْضِفُوهُ» »3« قَالَ أبو عبيد: الهرضْفُ الِْحجَارَةُ تُسَخهنُ، ُ مه يُكْمَدُ بَِها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَقَالَ الْفَضْلُ بْنُ دُكَيٍْن: حَدهثَـنَا سفيان، عَنْ أبي الزبير، عَنْ جابر، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَوَاهُ فِي أَكْحَلِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَفِي «صَحِيحِ الْبُخَارِيِّ » مِنْ حَدِيثِ أنس، أَنههُ كُوِيَ مِنْ ذَاتِ الَْجنْبِ وَالنهبُِّ صَلهى ا هللَُّ عليه وسلم حيّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, '. »4«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, '(7) أخرجه مسلم في السلام (2) أخرجه مسلم وأحدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, '(3) أخرجه عبد الرزاق في المصنف.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '(4) أخرجه البخاري في الطب: باب ذات الجنب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَفِي الترمذي، عَنْ أنس، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ «كَوَى أَسْعَدَ بْنَ زُرَارَةَ مِنَ الشهوْكَةِ» »7« ، وَقَدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'تَـقَدهمَ الَْحدِيثُ الْمُتهـفَقُ عَلَيْهِ وَفِيهِ «وَمَا أُحِبُّ أَنْ أَكْتَوِيَ» وَفِي لَفْظٍ آخَرَ: «وَأَنَا أَنْـهَى أُمهتِي عَنِ الْكَيِّ» . وَفِي «جَامِعِ الترمذي» وَغَيِْرهِ عَنْ عِمْرَانَ بْنِ حُصَيٍْن، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ نَـهَى عَنِ الْكَيِّ قَالَ: فَابْـتُلِينَا فَاكْ تَـوَيْـنَا فَمَا أَفْـلَحْ نَا، وَلَا أَنْحَْْ نَا. وَفِي لَفْظٍ: نُِهينَا عَنِ الْكَيِّ وَقَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'فَمَا أَفْـلَحْنَ وَلَا أَ نَْحْْنَ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'قَالَ الخطابي: إِهنَما كَوَى سعدا لِيَـرْقَأَ الدهمَ مِنْ جُرْحِهِ، وَخَافَ عَلَيْهِ أَنْ يَـنْزِفَ فَـيَـهْلَكَ . وَالْكَيُّ مُسْتَـعْمَلٌ فِي هَذَا الْبَابِ، كَمَا يُكْ وَى مَنْ تُـقْطَعُ يَدُهُ أَوْ رِجْلُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَأَمها النهـهْيُ عَنِ الْكَيِّ، فَـهُوَ أَنْ يَكْتَوِيَ طَلَبًا لِلشِّ فَاءِ، وَكَانُوا يَـعْتَقِدُونَ أَنههُ مَتَى لََْ يَكْ تَوِ، هَلَكَ ، فَـنَـهَاهُمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'عَنْهُ لَِأجْلِ هَذِهِ النِّيهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَقِيلَ إِهنَما نَـهَى عَنْهُ عِمْرَانَ بْنَ حُصَيٍْن خَاصهةً، لَِأنههُ كَانَ بِهِ نَاصُورٌ، وَكَانَ مَوْضِ عُهُ خَطَرًا، فَـنَـهَاهُ عَنْ كَيِّهِ، فَـيُشْبِهُ أَنْ يَكُونَ النهـهْيُ مُنْصَرِفًا إِلَى الْمَوْضِ عِ الْمُخَ هوفِ مِنْهُ، وَاَ هللَُّ أَعْلَمُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَقَالَ ابن قتيبة: الْكَيُّ جِنْسَانِ: كَيُّ الصهحِيحِ لِئَهلا يَـعْتَله، فَـهَذَا الهذِي قِيلَ فِيهِ: لََْ يَـتَـوَكهلْ مَنِ اكْتَـوَى، لَِأنههُ يُرِيدُ أَنْ يَدْفَعَ الْقَدَرَ عَنْ نَـفْسِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَالثهانِي: كَيُّ الُْجرْحِ إِذَا نَغِلَ، وَالْعُضْوِ إِذَا قُطِعَ، فَفِي هَذَا الشِّ فَاءُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَأَمها إِذَا كَانَ الْكَيُّ لِلتهدَاوِي الهذِي يَُجوزُ أَنْ يَـنْجَعَ، وَيَُجوزُ ألاينجع، فَإِنههُ إِلَى الْكَرَاهَةِ أَقْـرَبُ . انْـتَـهَى. وَثَـبَتَ فِي «الصهحِيحِ» فِي حَدِيثِ السهبْعِيَن أَلْفًا الهذِينَ يَدْخُلُونَ الَْجنهةَ بِغَيِْر حِسَابٍ أَنهـهُمُ الهذِينَ لَا يَسْتَـرْقُونَ وَلَا يَكْ تَـوُونَ وَلَا يَـتَطَيهـرُونَ، وَعَلَى رَبِِّهمْ يَـتَـوَكهلُونَ» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'فَـقَدْ تَضَمهنَتْ أَحَادِيثُ الْكَيِّ أَرْبَـعَةَ أَنْـوَاعٍ ، أَحَدُهَا: فِعْلُهُ؛ وَالثهانِي: عَدَمُ مَبَُهتِهِ لَهُ، وَالثهالِثُ : الثهـنَاءُ عَلَى مَنْ تَـرَكَهُ، وَالهرابِعُ: النهـهْيُ عَنْهُ، وَلَا تعارض بينهما بَِحمْدِ ا هلِلَّ تَـعَالَى، فَإِنه فِعْلَهُ يَدُلُّ عَلَى جِوَازِهِ، وَعَدَمُ مَبَُهتِهِ لَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'لَا يَدُلُّ عَلَى المنع منه. وأما الثناء على', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, '(7) أخرجه الترمذي- «الشوكة» داء معروف- انظر القاموس (2) أخرجه الترمذي وأبو داود وابن ماجه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, '(3) أخرجه البخاري ومسلم', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'تَاركِِهِ، فَـيَدُلُّ عَلَى أَنه تَـرْكَهُ أَوْلَى وَأَفْضَلُ. وَأَمها النهـهْيُ عَنْهُ، فَـعَلَى سَبِيلِ الِاخْتِيَارِ وَالْكَرَاهَةِ، أَوْ عَنِ النهـوْعِ الهذِي لَا يُْحتَاجُ إِلَيْهِ، بَلْ يُـفْعَلُ خَوْفًا مِنْ حُدُوثِ الدهاءِ، وَاَ هللَُّ أعلم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الصهرَعِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'أَخْ رَجَا فِي «الصهحِيحَيِْن» مِنْ حَدِيثِ عَطَاءِ بْنِ أَبِي رَبَاحٍ، قَالَ: قَالَ ابْنُ عَبهاسٍ : أَلَا أُرِيكَ امْرَأَةً مِنْ أَهْلِ الَْجنهةِ؟ قُـلْتُ بَـلَى. قَالَ: هَذِهِ الْمَرْأَةُ السهوْدَاءُ، أَتَتِ النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فَـقَالَتْ إِنِّي أُصْرَعُ، وَإِنِّي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'أَتَكَشهفُ ، فَادعُْ ا هللََّ لِِ، فَـقَالَ: «إِنْ شِئْتِ صَبَـرْتِ وَلَكِ الَْجنهةُ، وَإِنْ شِئْتِ دَعَوْتُ ا هللََّ لَكِ أَنْ يُـعَافِيَكِ » ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'فَـقَالَتْ : أصبَ. قالت فإني أتكشّف، فادع الله ألاأتكشف، فَدَعَا لََها »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'قُـلْتُ : الصهرَعُ صَرَعَانِ: صَرَعٌ مِنَ الَْأرْوَاحِ الَْخبِيثَةِ الَْأرْضِ يهةِ، وَصَرَعٌ مِنَ الَْأخْلَاطِ الهردِيئَةِ. وَالثهانِي: هُوَ الهذِي يَـتَكَلهمُ فِيهِ الَْأطِبهاءُ فِي سَبَبِهِ وَعِلَاجِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَأَمها صَرَعُ الَْأرْوَاحِ، فَأَئِمهتُـهُمْ وَعُقَلَاؤُهُمْ يَـعْتَِرفُونَ بِهِ، وَلَا يَدْفَـعُونَهُ، وَيَـعْتَِرفُونَ بَِأنه عِلَاجَهُ بُِمقَابَـلَةِ الَْأرْوَاحِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الشهرِيفَةِ الَْخيَِّرةِ الْعُلْوِيهةِ لِتِلْكَ الَْأرْوَاحِ الشِّ رِّيرَةِ الَْخبِيثَةِ، فَـتُدَافُعُ آثَرََهَا، وَتُـعَارِضُ أَفْـعَالََها وَتُـبْطِلُهَا، وقد نص', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'على ذلك بقراط فِي بَـعْضِ كُتُبِهِ، فَذَكَرَ بَـعْضَ عِلَاجِ الصهرَعِ ، وَقَالَ: هَذَا إِهنَما يَـنْـفَعُ مِنَ الصهرَعِ الهذِي سَبَـبُهُ الَْأخْلَاطُ وَالْمَادهةُ. وَأَمها الصهرَعُ الهذِي يَكُونُ مِنَ الَْأرْوَاحِ، فَلَا يَـنْـفَعُ فِيهِ هَذَا الْعِلَاجُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَأَمها جَهَلَةُ الَْأطِبهاءِ وَسَقَطُهُمْ وَسِفْلَتُـهُمْ، وَمَنْ يَـعْتَقِدُ بالزندقة فضيلة، فأؤلئك يُـنْكِرُونَ صَرَعَ الَْأرْوَاحِ، وَلَا يُقِرُّونَ بَِأنهـهَا تُـؤَثِّرُ فِي بَدَنِ الْمَصْرُوعِ ، وَلَيْسَ مَعَهُمْ إِهلا الَْجهْلُ، وَإِهلا فَـلَيْسَ فِي الصِّنَاعَةِ الطِّبِّيهةِ مَا يَدْفَعُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'ذَلِكَ ، وَالِْحسُّ وَالْوُجُودُ شَاهِدٌ بِهِ، وَإِحَالَتُـهُمْ ذَلِكَ على غلبة بعض الأخلاط، وصادق فِي بَـعْضِ أَقْسَامِهِ لَا فِي كُلِّهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَقُدَمَاءُ الَْأطِبهاءِ كَانُوا يُسَمُّونَ هَذَا الصهرَعَ: الْمَرَضَ الِْإلَِهيه، وَقَالُوا: إنههُ مِنَ الَْأرْوَاحِ، وَأَمها جَالِينُوسُ وَغَيْـرُهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'فَـتَأَهولُوا عَلَيْهِمْ هَذِهِ التهسْمِيَةَ، وَقَالُوا: إِهنَما سَمهوْهُ بِالْمَرَضِ الِْإلَِهيِّ لِكَوْنِ هَذِهِ الْعِلهةِ تَدَُْثُ فِي الهرأْسِ ، فَـتَضُرُّ بِالُْجزْءِ الِْإلَِهيِّ الطهاهِرِ الهذِي مَسْكَنُهُ الدماغ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '(7) أخرجه البخاري في المرض ومسلم في البَ والصلة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَهَذَا التهأْوِيلُ نَشَأَ لَهمُْ مِنْ جَهْلِهِمْ بَِهذِهِ الَْأرْوَاحِ وَأَحْكَامِهَا، وَتَثَِْيَراتَِها، وَجَاءَتْ زَنَادِقَةُ الَْأطِبهاءِ فَـلَمْ يُـثْبِتُوا إِهلا صَرَعَ الَْأخْلَاطِ وَحْدَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَمَنْ لَهُ عَقْلٌ وَمَعْرِفَةٌ بَِهذِهِ الَْأرْوَاحِ وَتَثَِْيَراتَِها يَضْحَكُ مِنْ جَهْلِ هَؤُلَاءِ وَضَعْفِ عُقُولِِهمْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَعِلَاجُ هَذَا النهـوْعِ يَكُونُ بَِأمْرَيْنِ: أَمْرٍ مِنْ جِهَةِ الْمَصْرُوعِ ، وَأَمْرٍ مِنْ جِهَةِ الْمُعَالِجِ، فَاَلهذِي مِنْ جِهَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'الْمَصْرُوعِ يَكُونُ بِقُهوةِ نَـفْسِهِ، وَصِدْقِ تَـوَجُّهِهِ إِلَى فَاطِرِ هَذِهِ الَْأرْوَاحِ وَبَارِئِهَا، وَالتهـعَوُّذِ الصهحِيحِ الهذِي قَدْ تَـوَاطَأَ عَلَيْهِ الْقَلْبُ وَاللِّسَانُ، فَإِنه هَذَا نَـوْعُ مُاَُرَبَةٍ، وَالْمُحَارِبُ لَا يَتِمُّ لَهُ الِانْتِصَافُ مِنْ عَدُوِّهِ بِالسِّ لَاحِ إِهلا بَِأمْرَيْنِ: أَنْ يَكُونَ السِّ لَاحُ صَحِيحًا فِي نَـفْسِهِ جَيِّدًا، وَأَنْ يَكُونَ السهاعِدُ قَوِيًّا، فَمَتَى تََخلهفَ أَحَدُهُاَُ لََْ يُـغْنِ السِّ لَاحُ كَثِيَر طَائِلٍ، فَكَيْفَ إِذَا عُدِمَ الَْأمْرَانِ جَِيَعًا: يَكُونُ الْقَلْبُ خَرَابًا مِنَ التهـوْحِيدِ، وَالتهـوَكُّلِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَالتهـقْوَى، وَالتهـوَجُّهِ، وَلَا سِلَاحَ لَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَالثهانِي: مِنْ جِهَةِ الْمُعَالِجِ، بَِأنْ يَكُونَ فِيهِ هَذَانِ الَْأمْرَانِ أَيْضًا، حَ هتى إِنه مِنَ الْمُعَالِِجيَن مَنْ يَكْتَفِي بِقَوْلِهِ: «اخْ رُجْ مِنْهُ» . أَوْ بِقَوْلِ: «بِسْمِ ا هلِلَّ» ، أَوْ بِقَوْلِ «لَا حَوْلَ وَلَا قُـهوةَ إِهلا بَِا هلِلَّ» ، وَالنهبُِّ صَلهى ا هللَُّ عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَسَلهمَ كَانَ يَـقُولُ: «اخْ رُجْ عَدُ هو ا هلِلَّ أَنَا رَسُولُ ا هلِلَّ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَشَاهَدْتُ شَيْخَنَا يُـرْسِلُ إِلَى الْمَصْرُوعِ مَنْ يَُخاطِبُ الرُّوحَ الهتِي فِيهِ، وَيَـقُولُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'قَالَ لَكِ الشهيْخُ: اخْرُجِي، فَإِنه هَذَا لَا يَِحلُّ لَكِ ، فَـيُفِيقُ الْمَصْرُوعُ، وَرُهبَما خَاطَبَـهَا بِنَـفْسِهِ، وَرُهبَما كَانَتِ الرُّوحُ مَارِدَةً فَـيُخْرِجُهَا بِالضهرْبِ، فَـيُفِيقُ الْمَصْرُوعُ وَلَا يَُحسُّ بَِألٍََ، وَقَدْ شَاهَدْنَا نَنُْْ وَغَيْـرُنَا مِنْهُ ذَلِكَ مِرَارًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وكان كثيرا ما يقرأ في أذن المضروع: أَفَحَسِبْـتُمْ أَهنما خَلَقْناكُمْ عَبَثاً وَأَنهكُمْ إِلَيْنا لَا تُـرْجَعُونَ »2« وَحَدهثَنِِ أَنههُ قَـرَأَهَا مَ هرةً فِي أُذُنِ الْمَصْرُوعِ ، فَـقَالَتِ الرُّوحُ: نَـعَمْ، وَمَده بَِها صَوْتَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'قَالَ: فَأَخَذْتُ لَهُ عَصًا، وَضَرَبْـتُهُ بَِها فِي عُرُوقِ عُنُقِهِ حَ هتى كَلهتْ يَدَايَ مِنَ الضهرْبِ، وَلََْ يشكّ الحاضرون أنه يموت لذلك الضربة ففي أثناء الضرب قالت: «أنا أحبّه،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, '(7) أخرجه الإمام أحدْ من حديث يعلى بن مرة عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, '(2) المؤمنون- -775 ومعنى الآية: أي خلقناكم لنتعبدكم في الأمر والنهي وترجعون إلينا وناْزي على ذلك', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'فَـقُلْتُ لََها: هُوَ لَا يُِحبُّكِ ، قَالَتْ : أَنَا أُرِيدُ أَنْ أَحُجه بِهِ، فَـقُلْتُ لَهاَ هُوَ لَا يُرِيدُ أَنْ يَُحجه مَعَكِ ، فَـقَالَتْ أَنَا أَدَعُهُ كَرَامَةً لَكَ ، قَالَ: قُـلْتُ : لَا وَلَكِنْ طَاعَةً هِلِلَّ وَلِرَسُولِهِ، قَالَتْ :', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'فَأَنَا أَخْ رُجُ مِنْهُ، قَالَ: فَـقَعَدَ الْمَصْرُوعُ يَـلْتَفِتُ يَِمينًا وَشَِمالًا، وَقَالَ: مَا جَاءَ بِي إِلَى حَضْرَةِ الشهيْخِ، قَالُوا لَهُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَهَذَا الضهرْبُ كُلُّهُ؟ فَـقَالَ وَعَلَى أَيِّ شَيْ ءٍ يَضْرِبُنِِ الشهيْخُ وَلََْ أُذْنِبْ ، وَلََْ يَشْعُرْ بَِأنههُ وَقَعَ بِهِ ضَرْبٌ الْبَـتهةَ وَكَانَ يُـعَالِجُ بِيَِةِ الْكُرْسِيِّ، وَكَانَ مََُْرُ بِكَثْـرَةِ قِرَاءَتَِها الْمَصْرُوعَ وَمَنْ يُـعَالُِجهُ بَِها، وَبِقِرَاءَةِ الْمُعَوِّذَتَـيِْن. وَبِالُْجمْلَةِ فَـهَذَا النهـوْعُ مِنَ الصهرَعِ ، وَعِلَاجِهِ لَا يُـنْكِرُهُ إِهلا قَلِيلُ الَْحظِّ مِنَ الْعِلْمِ وَالْعَقْلِ وَالْمَعْرِفَةِ، وَأَكْثَـرُ تَسَلُّطِ الَْأرْوَاحِ الَْخبِيثَةِ عَلَى أَهْلِهِ تَكُونُ مِنْ جِهَةِ قِلهةِ دِينِهِمْ، وَخَرَابِ قُـلُوبِِهمْ وَأَلْسِنَتِهِمْ مِنْ حَقَائِقِ الذِّكْرِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'وَالتهـعَاوِيذِ، وَالتهحَصُّنَاتِ النهـبَوِيهةِ وَالِْإيَمانِيهةِ، فَـتَـلْقَى الرُّوحُ الَْخبِيثَةُ الهرجُلَ أَعْزَلَ لَا سِلَاحَ مَعَهُ، وَرُهبَما كَانَ عُرْيَانًا فَـيُـؤَثِّرُ فِيهِ هَذَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَلَوْ كُشِفَ الْغِطَاءُ، لَرَأَيْتَ أَكْثَـرَ النُّـفُوسِ الْبَشَرِيهةِ صَرْعَى هَذِهِ الَْأرْوَاحِ الَْخبِيثَةِ، وَهِيَ فِي أَسْرِهَا وَقَـبْضَتِهَا تَسُوقُـهَا حَيْثُ شَاءَتْ ، وَلَا يُْمكِنُـهَا الِامْتِنَاعُ عَنْـهَا وَلَا مَُخالَفَتُـهَا، وَبَِها الصهرَعُ الَْأعْظَمُ الهذِي لَا يُفِيقُ صَاحِبُهُ إِهلا عِنْدَ الْمُفَارَقَةِ وَالْمُعَايَـنَةِ، فَـهُنَاكَ يَـتَحَقهقُ أَنههُ كَانَ هُوَ الْمَصْرُوعَ حَقِيقَةً، وَبَِا هلِلَّ الْمُسْتَـعَانُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'وَعِلَاجُ هَذَا الصهرَعِ بِاقْتَِرانِ الْعَقْلِ الصهحِيحِ إِلَى الِْإيَمانِ بَِما جَاءَتْ بِهِ الرُّسُلُ، وَأَنْ تَكُونَ الَْجنهةُ وَالنهارُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'نُصْبَ عَيْـنَـيْهِ وَقِبْـلَةَ قَـلْبِهِ، وَيَسْتَحْضِرَ أَهْلَ الدُّنْـيَا، وَحُلُولَ الْمَثُلَاتِ وَالْآفَاتِ بِِهمْ، وَوُقُوعَهَا خِلَالَ دِيَارِهِمْ كَمَوَاقِعِ الْقَطْرِ، وَهُمْ صَرْعَى لَا يُفِيقُونَ، وَمَا أَشَده دَاءَ هَذَا الصهرَعِ ، وَلَكِنْ لَمها عَمهتِ الْبَلِيهةُ بِهِ بَِحيْثُ لَا يُـرَى إِهلا مَصْرُوعًا، لََْ يَصِرْ مُسْتَـغْرَبًا وَلَا مُسْتَـنْكَرًا، بَلْ صَارَ لِكَثْـرَةِ الْمَصْرُوعِيَن عَيَْن الْمُسْتَـنْكَرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'الْمُسْتَـغْرَبِ خِلَافَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'فَإِذَا أَرَادَ ا هللَُّ بِعَبْدٍ خَيْـرًا أَفَاقَ مِنْ هَذِهِ الصهرْعَةِ، وَنَظَرَ إِلَى أَبْـنَاءِ الدُّنْـيَا مَصْرُوعِيَن حَوْلَهُ يَِمينًا وَشَِمالًا عَلَى اخْتِلَافِ طَبَـقَاتِِهمْ، فَمِنْـهُمْ مَنْ أَطْبَقَ بِهِ الُْجنُونُ، وَمِنْـهُمْ مَنْ يُفِيقُ أَحْ يَانًا قَلِيلَةً، وَيَـعُودُ إِلَى جُنُونِهِ، وَمِنْـهُمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'مَنْ يُفِيقُ مَ هرةً، وَيَُجنُّ أُخْ رَى، فَإِذَا أَفَاقَ عَمِلَ عَمَلَ أَهْلِ الِْإفَاقَةِ وَالْعَقْلِ، ُ مه يعاوده الصرع فيقع في التخبط.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل [في صرع الأخلاط]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَمها صَرَعُ الَْأخْلَاطِ، فَـهُوَ عِلهةٌ تَنََْعُ الَْأعْضَاءَ النهـفْسِيهةَ عَنِ الَْأفْـعَالِ وَالَْحرَكَةِ وَالِانْتِصَابِ مَنْـعًا غَيْـرَ تَامٍّ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَسَبَـبُهُ خِلْطٌ غَلِيظٌ لَزِجٌ يَسُدُّ مَنَافِذَ بُطُونِ الدِّمَاغِ سَدهةً غَيْـرَ تَامهةٍ، فَـيَمْتَنِعُ نُـفُوذُ الِْحسِّ وَالَْحرَكَةِ فِيهِ وَفِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الَْأعْضَاءِ نُـفُوذًا تَامها مِنْ غَيِْر انْقِطَاعٍ بِالْكُلِّيهةِ، وَقَدْ تَكُونُ لَِأسْبَابٍ أُخَرَ كَرِيحٍ غَلِيظٍ يُْحتَـبَسُ فِي مَنَافِذِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الرُّوحِ، أَوْ خُاَِرٍ رَدِيءٍ يَـرْتَفِعُ إِلَيْهِ مِنْ بَـعْضِ الَْأعْضَاءِ، أَوْ كَيْفِيهةٍ لَاذِعَةٍ، فَـيَـنْـقَبِضُ الدِّمَاغُ لِدَفْعِ الْمُؤْذِي، فَـيَـتْـبَـعُهُ تَشَنُّجٌ فِي جَِيَعِ الَْأعْضَاءِ، وَلَا يُْمكِنُ أَنْ يَـبْـقَى الِْإنْسَانُ مَعَهُ مُنْـتَصِبًا، بَلْ يَسْقُطُ، وَيَظْهَرُ فِي فِيهِ الهزبَدُ غَالِبًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَهَذِهِ الْعِلهةُ تُـعَدُّ مِنْ جُلََْةِ الَْأمْرَاضِ الَْحادهةِ بِاعْتِبَارِ وَقْتِ وُجُودِهِ الْمُؤْلَِِ خَاصهةً، وَقَدْ تُـعَدُّ مِنْ جُلََْةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الَْأمْرَاضِ الْمُزْمِنَةِ بِاعْتِبَارِ طُولِ مُكْ ثِهَا، وَعُسْرِ بُـرْئِهَا، لَا سِيهمَا أَنْ تَاََوَزَ فِي السِّ نِّ خَْمسًا وَعِشْرِينَ سَنَةً، وَهَذِهِ الْعِلهةُ فِي دِمَاغِهِ، وَخَاصهةً فِي جَوْهَرِهِ، فَإِنه صَرَعَ هَؤُلَاءِ يَكُونُ لَازِمًا. قَالَ أبقراط: إِنه الصهرَعَ يَـبْـقَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'فِي هَؤُلَاءِ حَ هتى يَُموتُوا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'إِذَا عُرِفَ هَذَا، فَـهَذِهِ الْمَرْأَةُ الهتِي جَاءَ الَْحدِيثُ أَنهـهَا كَانَتْ تُصْرَعُ وَتَـتَكَشهفُ ، يَُجوزُ أَنْ يَكُونَ صَرَعُهَا مِنْ هَذَا النهـوْعِ ، فَـوَعَدَهَا النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ الَْجنهةَ بِصَبِْهََا عَلَى هَذَا الْمَرَضِ ، وَدَعَا لََها ألاتتكشف، وَخَيهـرَهَا بَـيَْن الصهبَِْ وَالَْجنهةِ، وَبَـيَْن الدُّعَاءِ لََها بِالشِّ فَاءِ مِنْ غَيِْر ضَمَانٍ، فَاخْتَارَتِ الصهبْـرَ وَالَْجنهةَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَفِي ذَلِكَ دَلِيلٌ عَلَى جَوَازِ تَـرْكِ الْمُعَالََجةِ وَالتهدَاوِي، وَأَنه عِلَاجَ الَْأرْوَاحِ بِالدهعَوَاتِ وَالتهـوَجُّهِ إِلَى ا هلِلَّ يَـفْعَلُ مَا لَا يَـنَالُهُ عِلَاجُ الَْأطِبهاءِ، وَأَنه تَثَِْيَرهُ وَفِعْلَهُ، وَتَثََُّـرَ الطهبِيعَةِ عَنْهُ وَانْفِعَالََها أَعْظَمُ مِنْ تَثَِْيِر الَْأدْوِيَةِ الْبَدَنِيهةِ، وَانْفِعَالِ الطهبِيعَةِ عَنْـهَا، وَقَدْ جَ هربْـنَا هَذَا مِرَارًا نَنُْْ وَغَيْـرُنَا، وَعُقَلَاءُ الَْأطِبهاءِ مُعْتَِرفُونَ بَِأنه لِفِعْلِ الْقُوَى النهـفْسِيهةِ، وَانْفِعَالَاتَِها فِي شِفَاءِ الَْأمْرَاضِ عَجَائِبُ ، وَمَا عَلَى الصِّنَاعَةِ الطِّبِّيهةِ أَضَرُّ مِنْ زَنَادِقَةِ الْقَوْمِ، وَسِفْلَتِهِمْ، وَجُ ههالِِهمْ. وَالظهاهِرُ أَنه صَرَعَ هَذِهِ الْمَرْأَةِ كَانَ مِنْ هَذَا النهـوْعِ ، وَيَُجوزُ أَنْ يَكُونَ مِنْ جِهَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'الَْجنهةِ، وَبَـيَْن الدُّعَاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'الَْأرْوَاحِ، وَيَكُونُ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَدْ خَيهـرَهَا بَـيَْن الصهبَِْ عَلَى ذَلِكَ مَعَ لََها بِالشِّ فَاءِ، فاختارت الصبَ والستر، والله أعلم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ عِرْقِ النهسَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى ابْنُ مَاجَهْ فِي «سُنَنِهِ» مِنْ حَدِيثِ مُمَُهدِ بْنِ سِيِرينَ، عَنْ أَنَسُ بْنُ مَالِكٍ ، قَالَ: سَِمعْتُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـقُولُ: «دَوَاءُ عِرْقِ النهسَا أَلْيَةُ شَاةٍ أَعْرَابِيهةٍ تُذَابُ ، ُُّ م تُهََزأُ ثَلَاثَةَ أَجْ زَاءٍ، ُ مه يُشْرَبُ عَلَى الرِّيقِ فِي كُلِّ يَـوْمٍ جُزْءٌ» »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'عِرْقُ النهسَاءِ: وَجَعٌ يبتدىء مِنْ مَفْصِلِ الْوَرِكِ، وَيَـنْزِلُ مِنْ خَلْفٍ عَلَى الْفَخِذِ، وَرُهبَما عَلَى الْكَعْبِ، وَكُلهمَا طَالَتْ مُدهتُهُ، زَادَ نُـزُولُهُ، وَتَـهْزُلُ مَعَهُ الرِّجْلُ وَالْفَخِذُ، وَهَذَا الَْحدِيثُ فِيهِ مَعْنًى لُغَوِيٌّ، وَمَعْنًى طِبٌِّّ. فَأَمها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الْمَعْنَى اللُّغَوِيُّ، فَدَلِيلٌ عَلَى جَوَازِ تَسْمِيَةِ هَذَا الْمَرَضِ بِعِرْقِ النهسَا خِلَافًا لِمَنْ مَنَعَ هَذِهِ التهسْمِيَةَ، وَقَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'النهسَا هُوَ الْعِرْقُ نَـفْسُهُ، فَـيَكُونُ مِنْ بَابِ إِضَافَةِ الشهيْ ءِ إِلَى نَـفْسِهِ، وَهُوَ مُْمتَنِعٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَجَوَابُ هَذَا الْقَائِلِ مِنْ وَجْ هَيِْن. أَحَدُ هَُاُ أَنه الْعِرْقَ أَعَمُّ مِنَ النهسَا، فَـهُوَ مِنْ بَابِ إِضَافَةِ الْعَامِّ إِلَى الَْخاصِّ نَوَْْ: كُلُّ الدهرَاهِمِ أَوْ بَـعْضُهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الثهانِي: أَنه النهسَا هُوَ الْمَرَضُ الَْحالُّ بِالْعِرْقِ، وَالِْإضَافَةُ فِيهِ مِنْ بَابِ إِضَافَةِ الشهيْ ءِ إِلَى مَلَُِّهِ وَمَوْضِ عِهِ. قِيلَ: وَسُِّميَ بِذَلِكَ لَِأنه أَلَمَهُ يُـنْسِي مَا سِوَاهُ، وَهَذَا الْعِرْقُ مُْمتَدٌّ مِنْ مَفْصِلِ الْوَرِكِ، وَيَـنْـتَهِي إِلَى آخِرِ الْقَدَمِ وَرَاءَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الْكَعْبِ، مِنَ الَْجانِبِ الْوَحْشِيِّ فِيمَا بَـيَْن عَظْمِ السهاقِ وَالْوَتَرِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَأَمها الْمَعْنَى الطِّبُِّّ فَـقَدْ تَـقَدهمَ أَنه كَلَامَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ نَـوْعَانِ: أَحَدُهُاَُ عَامٌّ بَِحسْبِ الَْأزْمَانِ، وَالَْأمَاكِنِ، وَالَْأشْخَاصِ ، وَالَْأحْ وَالِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَالثهانِي خَاصٌّ بَِحسْبِ هَذِهِ الُْأمُورِ أَوْ بَـعْضِهَا، وَهَذَا مِنْ هَذَا الْقِسْمِ، فَإِنه هَذَا خِطَابٌ لِلْعَرَبِ، وَأَهْلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'الِْحجَازِ، وَمَنْ جَاوَرَهُمْ، وَلَا سِيهمَا أَعْرَابُ الْبَـوَادِي، فَإِنه هَذَا الْعِلَاجَ مِنْ أَنْـفَعِ الْعِلَاجِ لَهمُْ ، فَإِنه هَذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'الْمَرَضَ يَْحدُثُ مِنْ يُـبْسٍ ، وَقَدْ يَْحدُثُ مِنْ مَادهةٍ غَلِيظَةٍ لَزِجَةٍ، فَعِلَاجُهَا بِالِْإسْهَالِ وَالَْألْيَةُ فِيهَا الَْخاصِّ يهـتَانِ الِْإنْضَاجُ، وَالتهـلْيِيُن، فَفِيهَا الِْإنْضَاجُ، وَالِْإخْرَاجُ. وَهَذَا الْمَرَضُ يَْحتَاجُ عِلَاجُهُ إِلَى هَذَيْنِ الَْأمْرَيْنِ، وَفِي تَـعْيِيِن الشهاةِ الَْأعْرَابِيهةِ لِقِلهةِ فُضُولَِها، وَصِ غَرِ مِقْدَارِهَا، وَلُطْفِ جَوْهَرِهَا، وَخَاصِّ يهةِ مَرْعَاهَا لَِأنهـهَا تَـرْعَى أَعْشَابَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'إِذَا تَـغَذهى بَِها الَْحيَـوَانُ، صَارَ فِي لَْحمِهِ مِنْ طَبْعِهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'الْبَـرِّ الَْحارهةَ، كَالشِّ يحِ، وَالْقَيْصُومِ، وَنَوِْْهِاَُ، وَهَذِهِ النهـبَاتَاتُ بَـعْدَ أَنْ يُـلَطِّفَهَا تغذية بها، ويكسبها مزاجا ألطف', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, '(7) أخرجه ابن ماجه في الطب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'مِنْـهَا، وَلَا سِيهمَا الَْألْيَةُ، وَظُهُورُ فِعْلِ هَذِهِ النباتات فِي اللهبَِن »7« ، وَهَذَا كَمَا تَـقَدهمَ أَنه أَدْوِيَةَ غَالِبِ الُْأمَمِ وَالْبَـوَادِي هِيَ الَْأدْوِيَةُ الْمُفْرَدَةُ، وَعَلَيْهِ أَطِبهاءُ الِْهنْدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَأَمها الرُّومُ وَالْيُونَانُ، فَـيَـعْتَـنُونَ بِالْمُرَكهبَةِ وَهُمْ مُتهفِقُونَ كُلُّهُمْ عَلَى أَنه مِنْ مَهَارَةِ الطهبِيبِ أَنْ يُدَاوِيَ بِالْغِذَاءِ، فَإِنْ عَجَزَ فَبِالْمُفْرَدِ، فَإِنْ عَجَزَ، فَبِمَا كَانَ أَقَله تَـرْكِيبًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَقَدْ تَـقَدهمَ أَنه غَالِبَ عَادَاتِ الْعَرَبِ وَأَهْلِ الْبَـوَادِي الَْأمْرَاضُ الْبَسِيطَةُ، فَالَْأدْوِيَةُ الْبَسِيطَةُ تُـنَاسِبُـهَا، وَهَذَا لِبَسَاطَةِ أَغْذِيَتِهِمْ فِي الْغَالِبِ وَأَمها الَْأمْرَاضُ الْمُرَكهبَةُ، فَـغَالِبًا مَا تَدَُْثُ عَنْ تَـرْكِيبِ الَْأغْذِيَةِ وَتَـنَـوِّعِهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَاخْ تِلَافِهَا، فَاخْ تِيَرتْ لََها الَْأدْوِيَةُ الْمُرَكهبَةُ، وَا هللَُّ تَـعَالَى أَعْلَمُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ يُـبْسِ الطهبْعِ، وَاحْ تِيَاجِهِ إِلَى مَا يَُمشِّ يهِ وَيُـلَيِّنُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى الترمذي فِي «جَامِعِهِ» وَابْنُ مَاجَهْ فِي «سُنَنِهِ» مِنْ حَدِيثِ أسماء بنت عميس، قَالَتْ : قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «بَِماذَا كُنْتِ تَسْتَمْشِيَن» ؟ قَالَتْ : بِالشُّبْـرُمِ، قَالَ «حَارٌّ جَارٌّ» ، قَالَتْ : ُ مه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'اسْتَمْشَيْتُ بِالسهنَا، فَـقَالَ: «لَوْ كَانَ شَيْ ءٌ يَشْفِي مِنَ الْمَوْتِ لَكَانَ السهنَا» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» عَنْ إِبْـرَاهِيمَ بْنِ أَبِي عَبْـلَةَ، قَالَ: سَِمعْتُ عبد الله بن أم حرام، وَكَانَ قَدْ صَلهى مَعَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ الْقِبْـلَتَـيِْن يَـقُولُ: سَِمعْتُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـقُولُ: «عَلَيْكُمْ بِالسهنَا وَالسهنُوتِ فَإِنه فِيهِمَا شِفَاءً مِنْ كُلِّ دَاءٍ إِهلا السهامَ» ، قِيلَ: يَا رَسُولَ ا هلِلَّ! وَمَا السهامُ؟ قَالَ: «الموت» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(7) قال الدكتور عادل الأزهري: عرق النسا: هو مرض يصيب الرجال والنساء على السواء، وآلامه مفرطة تبتدىء غالبا في أسفل العمود الفقري، ويمتد الألَ ألى إلى إحدى الأليتين، م إلى الجزء الخلفي من الفخذ، وأحيانا حتى الكعب. وينتج غالبا من انفصال غضروفي بأسفل العمود الفقري، أو التهاب روماتزمي بالعصب الإنسي، وعلاجه الأساسي الراحة التامة على الظهر لمدة خمسة عشر يوما على الأقل مع إعطاء مهدئات لللَِ مثل الإسبيَن، والحجامات الجافة والكي أحيانا يساعدان على علاجه. (2) أخرجه الترمذي وابن ماجه والحاكم', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(3) أخرجه ابن ماجه والحاكم في الطب قال الحاكم صحيح، وتعقبه الذهب بأن عمرو بن بكراتهمه ابن عديّ بأن له مناكير.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'قَـوْلُهُ: «بَِماذَا كُنْتِ تَسْتَمْشِيَن» ؟ أَيْ تُـلَيِّنِيَن الطهبْعَ حَ هتى يَْمشِيَ ، وَلَا يَصِيَر بَِمنْزِلَةِ الْوَاقِفِ، فَـيُـؤْذِيَ بِاحْتِبَاسِ النهجْوِ، وَلَِهذَا سُِّميَ الدهوَاءُ الْمُسَهِّلُ مَشِيًّا عَلَى وَزْنِ فَعِيلٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَقِيلَ: لَِأنه الْمَسْهُولَ يُكْثِرُ الْمَشْيَ وَالِاخْتِلَافَ لِلْحَاجَةِ وَقَدْ رُوِيَ: «بَِماذَا تَسْتَشْفِيَن» ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'فَـقَالَتْ : بِالشُّبْـرُمِ، وَهُوَ مِنْ جُلََْةِ الَْأدْوِيَةِ الْيَـتُوعِيِّةِ، وَهُوَ قِشْرُ عِرْقِ شَجَرَةٍ، وَهُوَ حَارٌّ يَابِسٌ فِي الدهرَجَةِ الهرابِعَةِ، وَأَجْ وَدُهُ الْمَائِلُ إِلَى الُْحمْرَةِ، الَْخفِيفُ الهرقِيقُ الهذِي يُشْبِهُ الِْجلْدَ الْمَلْفُوفَ ، وَبِالُْجمْلَةِ فَـهُوَ مِنَ الَْأدْوِيَةِ الهتِي أَوْصَى الَْأطِبهاءُ بِتَـرْكِ اسْتِعْمَالَِها لَِخطَرِهَا، وَفَـرْطِ إِسْهَالَِها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَقَـوْلُهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ «حَارٌّ جَارٌّ» وَيُـرْوَى: «حَارٌّ يَارٌّ» ، قَالَ أبو عبيد: وَأَكْثَـرُ كَلَامِهِمْ بِالْيَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'قُـلْتُ : وَفِيهِ قَـوْلَانِ ، أَحَدُهُاَُ أَنه الَْحاره الَْجاره بِالِْجيمِ الشهدِيدُ الِْإسْهَالِ، فَـوَصَفَهُ بِالَْحرَارَةِ، وَشَدِّةِ الِْإسْهَالِ وَكَذَلِكَ هُوَ، قَالَهُ أبو حنيفة الدِّينَـوَرِيُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَالثهانِي- وَهُوَ الصهوَابُ - أَنه هَذَا مِنَ الِْإتْـبَاعِ الهذِي يُـقْصَدُ بِهِ تَكَِْيدُ الَْأهولِ، وَيَكُونُ بَـيَْن التهأْكِيدِ اللهفْظِيِّ وَالْمَعْنَوِيِّ ، وَلَِهذَا يُـرَاعُونَ فِيهِ إِتْـبَاعَهُ فِي أَكْثَرِ حُرُوفِهِ، كَقَوْلِِهمْ: حَسَنٌ بَسَنٌ، أَيْ : كَامِلُ الُْحسْنِ، وَقَـوْلُهمُْ: حَسَنٌ قَسَنٌ بِالْقَافِ، وَمِنْهُ شَيْطَانٌ لَيْطَانُ، وَحَارٌّ جَارٌّ، مَعَ أَنه فِي الَْجارٌّ مَعْنًى آخَرَ، وَهُوَ الهذِي يَُجرُّ الشهيْ ءَ الهذِي يُصِيبُهُ مِنْ شِدهةِ حَرَارَتِهِ وَجَذْبِهِ لَهُ، كَأَنههُ يَـنْزِعُهُ وَيَسْلُخُهُ. وَيَارٌّ: إِمها لُغَةٌ فِي جَارٍّ، كَقَوْلِِهمْ: صِ هْرِيٌّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَصِ هْرِيجٌ، وَالصههَارِي وَالصههَارِيجُ، وَإِمها إِتْـبَاعُ مُسْتَقِلٌّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَأَمها السهنَا، فَفِيهِ لُغَتَانِ الْمَدُّ وَالْقَصْرُ، وَهُوَ نَـبْتٌ حِجَازِيٌّ أَفْضَلُهُ الْمَكِّيُّ، وَهُوَ دَوَاءٌ شَرِيفٌ مَأْمُونُ الْغَائِلَةِ، قَرِيبٌ مِنَ الِاعْتِدَالِ، حَارٌّ يَابِسٌ فِي الدهرَجَةِ الُْأولَى، يُسْهِلُ الصهفْرَاءَ وَالسهوْدَاءَ، وَيُـقَوِّي جِرْمَ الْقَلْبِ، وَهَذِهِ فَضِيلَةٌ شَرِيفَةٌ فِيهِ، وَخَاصِّ يهـتُهُ النهـفْعُ مِنَ الْوَسْوَاسِ السهوْدَاوِيِّ ، وَمِنَ الشِّ قَاقِ الْعَارِضِ فِي الْبَدَنِ، وَيَـفْتَحُ الْعَضَلَ وَيَـنْـفَعُ مِنِ انْتِشَارِ الشهعَرِ، وَمِنَ الْقُمهلِ وَالصُّدَاعِ الْعَتِيقِ، وَالَْجرَبِ، وَالْبُـثُورِ، وَالِْحكهةِ، وَالصهرعِِ ، وَشُرْبِ مَائِهِ مَطْبُوخًا أَصْلَحُ مِنْ شُرْبِهِ مَدْقُوقًا، وَمِقْدَارُ الشهرْبَةِ مِنْهُ ثَلَاثَةُ دَرَاهِمَ، وَمِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'مَائِهِ خَْمسَةُ دَرَاهِمَ، وَإِنْ طُبِخَ مَعَهُ شَيْ ءٌ مِنْ زَهْرِ الْبَـنَـفْسَجِ وَالهزبِيبِ الَْأحْرَِْ الْمَنْـزُوعِ الْعَجَمُ، كَانَ أَصْلَحَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'قَالَ الهرازِيُّ: السهنَاءُ وَالشهاهَتْـرَجُ يُسَهِّلَانِ الَْأخْلَاطَ الْمُحْ تَِرقَةَ، وَيَـنْـفَعَانِ مِنَ الَْجرَبِ وَالِْحكهةِ، وَالشهرْبَةُ مِنْ كُلِّ وَاحِدٍ مِنْـهُمَا مِنْ أَرْبَـعَةِ دَرَاهِمَ إِلَى سَبْـعَةِ دَرَاهِمَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَأَمها السهنُوتُ ، فَفِيهِ ثَاََنِيَةُ أَقْـوَالٍ؛ أَحَدُهَا: أَنههُ الْعَسَلُ. وَالثهانِي: أَنههُ ربّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'عكة السمن يخرج خططا سوداء على السمن، حَكَاهُاَُ عمرو بن بكر السكسكي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'الثهالِثُ : أَنههُ حَبٌّ يُشْبِهُ الْكَمُّونَ وَلَيْسَ بِهِ، قَالَهُ ابْنُ الَْأعْرَابِِّي. الهرابِعُ: أَنههُ الْكَمُّونُ الْكَرْمَانُِّي. الَْخامِسُ : أَنههُ الهرازْيَانِجُ. حَكَاهُاَُ أَبُو حَنِيفَةَ الدِّينَـوَرِيُّ عَنْ بَـعْضِ الَْأعْرَابِ. السهادِسُ : أَنههُ الشِّ بِتُّ. السهابِعُ: أَنههُ التهمْرُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'حَكَاهُاَُ أَبُو بَكْرِ بْنُ السُّنِِِّّ الَْحافِظُ. الثهامِنُ: أَنههُ الْعَسَلُ الهذِي يَكُونُ فِي زِقَاقِ السهمْنِ، حَكَاهُ عبد اللطيف', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'البغدادي. قَالَ بَـعْضُ الَْأطِبهاءِ: وَهَذَا أَجْدَرُ بِالْمَعْنَى، وَأَقْـرَبُ إِلَى الصهوَابِ، أَيْ : يُْخلَطُ السهنَاءُ مَدْقُوقًا بِالْعَسَلِ الْمُخَالِطِ لِلسهمْنِ، ُ مه يُـلْعَقُ فَـيَكُونُ أَصْلَحَ مِنِ اسْتِعْمَالِهِ مُفْرَدًا لِمَا فِي الْعَسَلِ وَالسهمْنِ مِنْ إِصْلَاحِ السهنَا، وَإِعَانَتِهِ لَهُ عَلَى الِْإسْهَالِ. وَا هللَُّ أَعْلَمُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَقَدْ رَوَى الترمذي وَغَيْـرُهُ مِنْ حَدِيثِ ابْنِ عَبهاسٍ يَـرْفَـعُهُ: «إن خير ما تداويتم به السعوط واللدود', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'وَالِْحجَامَةُ وَالْمَشِيُّ» »', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَالْمَشِيُّ: هُوَ الهذِي يَُمشِّ ي الطهبْعَ ويلينّه ويسهّل خروج الخارج.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ حِكهةِ الِْجسْمِ وَمَا يُـوَلِّدُ الْقَمْلَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'فِي «الصهحِيحَيِْن» مِنْ حَدِيثِ قَـتَادَةَ، عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: رَخهصَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لِعَبْدِ الهرحْنَِْ بْنِ عَوْفٍ، والزبير بن العوام رضي الله تعالى عنهما فِي لُبْسِ الَْحرِيرِ لِِحكهةٍ كَانَتْ بِِهمَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَفِي رِوَايَةٍ: أَنه عَبْدَ الهرحْنَِْ بْنَ عَوْفٍ، وَالزُّبَـيْـرَ بْنَ الْعَهوامِ رَضِيَ ا هللَُّ تَـعَالَى عَنْـهُمَا، شَكَوَا الْقَمْلَ إِلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي غَزَاةٍ لَهمَُا، فَـرَخهصَ لَهمَُا فِي قُمُصِ الَْحرِيرِ، وَرَأَيْـتُهُ عَلَيْهِمَا « »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'هَذَا الَْحدِيثُ يَـتَـعَلهقُ بِهِ أمران: أحدهاُ: فقهي، والآخر طب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(7) أخرجه الترمذي. وفي سنده عباد بن منصور وهو ضعيف (2) أخرجه البخاري في الجهاد ومسلم في اللباس', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'فَأَمها الْفِقْهِيُّ: فَالهذِي اسْتَـقَهرتْ عَلَيْهِ سُنهـتُهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إِبَاحَةُ الَْحرِيرِ لِلنِّسَاءِ مُطْلَقًا، وَتَرَِْيُمهُ عَلَى الرِّجَالِ إِهلا لَِحاجَةٍ وَمَصْلَحَةٍ رَاجِحَةٍ، فَالَْحاجَةُ إِمها مِنْ شِدهةِ الْبَـرْدِ، وَلَا يَِجدُ غَيْـرَهُ، أَوْ لَا يَِجدُ سُتْـرَةً سِوَاهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَمِنْـهَا: لِبَاسُهُ لِلْجَرَبِ، وَالْمَرَضِ ، وَالِْحكهةِ، وَكَثْـرَةِ الْقَمْلِ كَمَا دَ هل عَلَيْهِ حَدِيثُ أنس هَذَا الصهحِيحُ. وَالَْجوَازُ: أَصَحه الرّوَايَـتَـيِْن عَنِ الِْإمَامِ أحدْ، وَأَصَحُّ قَـوْلَِِ الشهافِعِيِّ، إِذِ الَْأصْلُ عَدَمُ التهخْصِيصِ ، وَالرُّخْصَةُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'إِذَا ثَـبَـتَتْ فِي حَقِّ بَـعْضِ الُْأمهةِ لِمَعْنًى تَـعَدهتْ إِلَى كُلِّ مَنْ وُجِدَ فِيهِ ذَلِكَ الْمَعْنَى، إِذِ الُْحكْمُ يَـعُمُّ بِعُمُومِ سَبَبِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَمَنْ مَنَعَ مِنْهُ، قَالَ: أَحَادِيثُ التهحْرِيِم عَامهةٌ، وَأَحَادِيثُ الرُّخْصَةِ يُْحتَمَلُ اخْتِصَاصُهَا بِعَبْدِ الهرحْنَِْ بْنِ عَوْفٍ والزبير، وَيُْحتَمَلُ تَـعَدِّيهَا إِلَى غَيِْرهِاَُ. وَإِذَا احْتُمِلَ الَْأمْرَانِ، كَانَ الَْأخْذُ بِالْعُمُومِ أَوْلَى، وَلَِهذَا قَالَ بَـعْضُ الرُّوَاةِ فِي هَذَا الَْحدِيثِ: فَلَا أَدْرِي أَبْـلَغَتِ الرُّخْصَةُ مِنْ بَـعْدِهِاَُ، أَمْ لَا؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَالصهحِيحُ: عُمُومُ الرُّخْصَةِ، فَإِنههُ عُرْفُ خِطَابِ الشهرْعِ فِي ذَلِكَ مَا لََْ يُصَرِّحْ بِالتهخْصِيصِ ، وَعَدَمِ إِلَْحاقِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'غَيِْر مَنْ رَخهصَ لَهُ أَهولًا بِهِ، كَقَوْلِهِ لَِأبِي بُـرْدَةَ فِي تَضْحِيَتِهِ بِالَْجذَعَةِ مِنَ الْمَعْزِ: «تَزَِْيكَ وَلَنْ تَزَِْيَ عَنْ أَحَدٍ بَـعْدَكَ» وَكَقَوْلِهِ تَـعَالَى لِنَبِيِّهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي نِكَاحِ مَنْ وَهَبَتْ نَـفْسَهَا لَهُ: خالِصَةً لَكَ مِنْ دُونِ الْمُؤْمِنِيَن »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَتَرَِْيُم الَْحرِيرِ: إِهنَما كَانَ سَدًّا لِلذهرِيعَةِ، وَلَِهذَا أُبِيحَ لِلنِّسَاءِ، وَلِلْحَاجَةِ، وَالْمَصْلَحَةِ الهراجِحَةِ، وَهَذِهِ قَاعِدَةُ مَا حُرِّمَ لِسَدِّ الذهرَائِعِ، فَإِنههُ يُـبَاحُ عِنْدَ الَْحاجَةِ وَالْمَصْلَحَةِ الهراجِحَةِ، كَمَا حَرُمَ النهظَرُ سَدًّا لِذَرِيعَةِ الْفِعْلِ، وَأُبِيحَ مِنْهُ مَا تَدْعُو إِلَيْهِ الَْحاجَةُ وَالْمَصْلَحَةُ الهراجِحَةُ، وَكَمَا حَرُمَ التهـنَـفُّلُ بِالصهلَاةِ فِي أَوْقَاتِ النهـهْيِ سَدًّا لِذَرِيعَةِ الْمُشَابَـهَةِ الصُّورِيِّةِ بِعُبهادِ الشهمْسِ ، وَأُبِيحَتْ لِلْمَصْلَحَةِ الهراجِحَةِ، وَكَمَا حَرُمَ رِبَا الْفَضْلِ سَدًّا لِذَرِيعَةِ رِبَا النهسِيئَةِ، وَأُبِيحَ مِنْهُ مَا تَدْعُو إِلَيْهِ الَْحاجَةُ مِنَ الْعَرَايَا »2« ، وَقَدْ أَشْبَـعْنَا الْكَلَامَ فِيمَا يَِحلُّ وَيَْحرُمُ مِنْ لِبَاسِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'الَْحرِيرِ فِي كِتَابِ «التهحْ بِيُر لِمَا يَِحلُّ ويحرم من لباس الحرير» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, '(7) الأحزاب- .-51', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, '(2) العرايا: جعَ عرية بوزن مضيّة، وهي النخلة التي يعطيها صاحبها لفقير لينتفع بثمرتها إلى سنة، فتدفعه الحاجة إلى أن خَذ بثمرتها ترَا قبل أن ترَز ثرَتها فلا يضر الفضل حينئذ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَمها الَْأمْرُ الطِّبُِّّ: فَـهُوَ أَنه الَْحرِيرَ مِنَ الَْأدْوِيَةِ الْمُتهخَذَةِ مِنَ الَْحيَـوَانِ، وَلِذَلِكَ يُـعَدُّ فِي الَْأدْوِيَةِ الَْحيَـوَانِيهةِ، لَِأنه مَْخرَجَهُ مِنَ الَْحيَـوَانِ ، وَهُوَ كَثِيُر الْمَنَافِعِ، جَلِيلُ الْمَوْقِعِ، وَمِنْ خَاصِّ يهتِهِ تَـقْوِيَةُ الْقَلْبِ، وَتَـفْرِيُحهُ، وَالنهـفْعُ مِنْ كَثِيٍر مِنْ أَمْرَاضِهِ، وَمِنْ غَلَبَةِ الْمِ هرةِ السهوْدَاءِ، وَالَْأدْوَاءِ الَْحادِثَةِ عَنْـهَا؛ وَهُوَ مُقَوٍّ لِلْبَصَرِ إِذَا اكْ تُحِلَ بِهِ، وَالَْخامُ مِنْهُ- وَهُوَ الْمُسْتَـعْمَلُ فِي صِنَاعَةِ الطِّبِّ - حَارٌّ يَابِسٌ فِي الدهرَجَةِ الُْأولَى. وَقِيلَ: حَارٌّ رَطْبٌ فِيهَا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَقِيلَ: مُعْتَدِلٌ. وَإِذَا اتُِّخذَ مِنْهُ مَلْبُوسٌ كَانَ مُعْتَدِلَ الَْحرَارَةِ فِي مِزَاجِهِ، مُسَخِّ نًا لِلْبَدَنِ، وَرُهبَما بَـرُدَ الْبَدَنُ بِتَسْمِينِهِ إِهياهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'قَالَ الهرازِيُّ: الِْإبْـرَيْسَمُ أَسْخَنُ مِنَ الْكَتهانِ، وَأَبْـرَدُ مِنَ الْقُطْنِ، يُـرَبِّي اللهحْمَ، وَكُلُّ لِبَاسٍ خَشِنٍ، فَإِنههُ يُـهْزِلُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَيُصْلِبُ الْبَشَرَةَ وَبِالْعَكْسِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'قُـلْتُ : وَالْمَلَابِسُ ثَلَاثَةُ أَقْسَامٍ: قِسْمٌ يُسَخِّ نُ الْبَدَنَ وَيُدَفِّئُهُ، وَقِسْمٌ يُدَفِّئُهُ وَلَا يُسَخِّ نُهُ، وَقِسْمٌ لَا يُسَخِّ نُهُ وَلَا يُدَفِّئُهُ، وَلَيْسَ هُنَاكَ مَا يُسَخِّ نُهُ وَلَا يُدَفِّئُهُ، إِذْ مَا يُسَخِّ نُهُ فَـهُوَ أَوْلَى بِتَدْفِئَتِهِ، فَمَلَابِسُ الَْأوْبَارِ والأصواف تسخن وتدفىء، وملابس الكتان والحرير والقطن تدفىء وَلَا تُسَخِّ نُ، فَثِيَابُ الْكَتهانِ بَارِدَةٌ يَابِسَةٌ، وَثِيَابُ الصُّوفِ حَارَةٌ يَابِسَةٌ، وَثِيَابُ الْقُطْنِ مُعْتَدِلَةُ الَْحرَارَةِ، وَثِيَابُ الَْحرِيرِ أَلْيَُن مِنَ الْقُطْنِ وَأَقَلُّ حَرَارَةً مِنْهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'قَالَ صَاحِبُ «الْمِنْـهَاجِ» : وَلُبْسُهُ لَا يُسَخِّ نُ كَالْقُطْنِ، بَلْ هُوَ مُعْتَدِلٌ، وَكُلُّ لِبَاسٍ أَمْلَسَ صَقِيلٍ، فَإِنههُ أَقَلُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'إِسْخَانًا لِلْبَدَنِ ، وَأَقَلُّ عَوْنًا فِي تَلََُّلٍ مَا يَـتَحَلهلُ مِنْهُ، وَأَحْ رَى أَنْ يُـلْبَسَ فِي الصهيْفِ، وَفِي الْبِلَادِ الَْحارهةِ. وَلَمها كَانَتْ ثِيَابُ الَْحرِيرِ كَذَلِكَ ، وَلَيْسَ فِيهَا شَيْءٌ مِنَ الْيُـبْسِ وَالُْخشُونَةِ الْكَائِنَـيِْن فِي غَيِْرهَا، صَارَتْ نَافِعَةً مِنَ الِْحكهةِ، إِذِ الِْحكهةُ لَا تَكُونُ إِهلا عَنْ حَرَارَةٍ وَيُـبْسٍ وَخُشُونَةٍ، فَلِذَلِكَ رَخهصَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ للزبير وعبد الرحنْ فِي لِبَاسِ الَْحرِيرِ لِمُدَاوَاةِ الِْحكهةِ، وَثِيَابُ الَْحرِيرِ أَبْـعَدُ عَنْ تَـوَلُّدِ الْقَمْلِ فِيهَا، إِذْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'كَانَ مِزَاجُهَا مَُخالِفًا لِمِزَاجِ مَا يَـتَـوَلهدُ منه القمل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وأما القسم الذي لا يدفىء وَلَا يُسَخِّ نُ، فَالْمُتهخَذُ مِنَ الَْحدِيدِ وَالهرصَاصِ ، وَالَْخشَبِ وَالتُّـرَابِ، وَنَوِْْهَا، فَإِنْ قِيلَ: فَإِذَا كَانَ لِبَاسُ الَْحرِيرِ أَعْدَلَ اللِّبَاسِ وَأَوْفَـقَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'لِلْبُدْنِ ، فَلِمَاذَا حَ هرمَتْهُ الشهرِيعَةُ الْكَامِلَةُ الْفَاضِلَةُ الهتِي أَبَاحَتِ الطهيِّبَاتِ، وَحَ هرمَتِ الَْخبَائِثَ ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'قِيلَ: هَذَا السُّؤَالُ يُِجيبُ عَنْهُ كُلُّ طَائِفَةٍ مِنْ طَوَائِفِ الْمُسْلِمِيَن بِوََِابٍ، فَمُنْكِرُو الُْحكْمِ وَالتهـعْلِيلِ لِمَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'رُفِعَتْ قَاعِدَةُ التهـعْلِيلِ مِنْ أَصْلِهَا لََْ يَْحتَاجُوا إِلَى جَوَابٍ عَنْ هَذَا السُّؤَالِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَمُثْبِتُو التهـعْلِيلِ وَالُْحكْمِ- وَهُمُ الَْأكْ ثَـرُونَ- مِنْـهُمْ مَنْ يُِجيبُ عَنْ هَذَا بَِأنه الشهرِيعَةَ حَ هرمَتْهُ لِتَصْبََِ النُّـفُوسُ عَنْهُ، وَتَـتْـرُكَهُ هِلِلَّ، فَـتُـثَابُ عَلَى ذَلِكَ لَا سِيِّمَا وَلَهاَ عِوَضٌ عَنْهُ بِغَيِْرهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَمِنْـهُمْ مَنْ يُِجيبُ عَنْهُ بَِأنههُ خُلِقَ فِي الَْأصْلِ لِلنِّسَاءِ، كَالِْحلْيَةِ بِالذههَبِ، فَحَرُمَ عَلَى الرِّجَالِ لِمَا فِيهِ مِنْ مَفْسَدَةِ تَشَبُّهِ الرِّجَالِ بِالنِّسَاءِ، وَمِنْـهُمْ مَنْ قَالَ: حَرُمَ لِمَا يُورِثُهُ مِنَ الْفَخْرِ وَالُْخيَلَاءِ وَالْعُجْبِ. وَمِنْـهُمْ مَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'قَالَ: حَرُمَ لِمَا يُورِثُهُ بُِملَامَسَتِهِ لِلْبَدَنِ مِنَ الُْأنُوثَةِ وَالتهخَنُّثِ، وَضِدُّ الشههَامَةِ وَالرُّجُولَةِ، فَإِنه لُبْسَهُ يُكْسِبُ الْقَلْبَ صِفَةً مِنْ صِفَاتِ الِْإنَاثِ، وَلَِهذَا لَا تَكَادُ تَِدَُ مَنْ يَـلْبَسُهُ فِي الَْأكْثَرِ إِهلا وَعَلَى شََمائِلِهِ مِنَ التهخَنُّثِ وَالتهأَنُّثِ، وَالهرخَاوَةِ مَا لَا يَْخفَى، حَ هتى لَوْ كَانَ مِنْ أَشْهَمِ النهاسِ وَأَكْ ثَرِهِمْ فُحُولِيهةً وَرُجُولِيهةً، فَلَا بُده أَنْ يُـنْقِصَهُ لُبْسُ الَْحرِيرِ مِنْـهَا، وَإِنْ لََْ يُذْهِبْـهَا، وَمَنْ غَلُظَتْ طِبَاعُهُ وَكَثُـفَتْ عَنْ فَـهْمِ هَذَا، فَـلْيُسَلِّمْ لِلشهارعِِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'الَْحكِيمِ، وَلَِهذَا كَانَ أَصَحُّ الْقَوْلَيِْن: أَنههُ يَْحرُمُ عَلَى الْوَلِِِّ أَنْ يُـلْبِسَهُ الصهبِه لِمَا يَـنْشَأُ عَلَيْهِ مِنْ صِفَاتِ أَهْلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'التهأْنِيثِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَقَدْ رَوَى النهسَائِيُّ مِنْ حَدِيثِ أَبِي مُوسَى الَْأشْعَرِيِّ ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «إِنه ا هللََّ أَحَله لِِإنَاثِ أُمهتِي الَْحرِيرَ وَالذههَبَ ، وَحَ هرمَهُ عَلَى ذكُُورِهَا» . وَفِي لَفْظٍ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, '«حَرُمَ لِبَاسُ الَْحرِيرِ وَالذههَبِ عَلَى ذكُُورِ أُمهتِي، وَأُحِله لِِإنَاثِهِمْ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَفِي «صَحِيحِ الْبُخَارِيِّ » عَنْ حذيفة قَالَ: نَـهَى رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَنْ لُبْسِ الَْحرِيرِ وَالدِّيبَاجِ، وَأَنْ يُْجلَسَ عَلَيْهِ، وَقَالَ: «هُوَ لَهمُْ فِي الدُّنْـيَا، ولكم في الآخرة» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, '(7) أخرجه عبد الرزاق في المصنف. والنسائي في الزينة والترمذي في اللباس وهو حديث صحيح (2) أخرجه البخاري في اللباس', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ ذَاتِ الَْجنْبِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى الترمذي فِي «جَامِعِهِ» مِنْ حَدِيثِ زَيْدِ بْنِ أَرْقَمَ، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '«تَدَاوَوْا مِنْ ذَاتِ الَْجنْبِ بِالْقُسْطِ الْبَحْرِيِّ وَالهزيْتِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَذَاتُ الَْجنْبِ عِنْدَ الَْأطِبهاءِ نَـوْعَانِ: حَقِيقِيٌّ وَغَيْـرُ حَقِيقِيٍّ. فالحقيقي: وره حَارٌّ يَـعْرِضُ فِي نَـوَاحِي الَْجنْبِ فِي الْغِشَاءِ الْمُسْتَـبْطِنِ لِلْضَِْلَاعِ . وَغَيْـرُ الَْحقِيقِيِّ: أَلٌََ يُشْبِهُهُ يَـعْرِضُ فِي نَـوَاحِي الَْجنْبِ عَنْ رِيَاحٍ غَلِيظَةٍ مُؤْذِيَةٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'تَتََْقِنُ بَـيَْن الصهفَاقَاتِ، فَـتُحْدِثُ وَجَعًا قَرِيبًا مِنْ وَجَعِ ذَاتِ الَْجنْبِ الَْحقِيقِيِّ، إِهلا أَنه الْوَجَعَ فِي هَذَا الْقِسْمِ مَْمدُودٌ، وَفِي الَْحقِيقِيِّ نَاخِسٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'قَالَ صَاحِبُ «الْقَانُونِ» : قَدْ يَـعْرِضُ فِي الَْجنْبِ، وَالصهفَاقَاتِ، وَالْعَضَلِ الهتِي فِي الصهدْرِ، وَالَْأضْلَاعِ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَنَـوَاحِيهَا أَوْرَامٌ مُؤْذِيَةٌ جِدًّا مُوجِعَةٌ، تُسَمهى شَوْصَةً وَبِرْسَامًا، وَذَاتَ الَْجنْبِ. وَقَدْ تَكُونُ أَيْضًا أَوْجَاعًا فِي هَذِهِ الَْأعْضَاءِ لَيْسَتْ مِنْ وَرَمٍ، وَلَكِنْ مِنْ رِيَاحٍ غَلِيظَةٍ، فَـيُظَنه أَنهـهَا مِنْ هَذِهِ الْعِلهةِ، وَلَا تَكُونُ مِنْـهَا. قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَاعْلَمْ أَنه كُله وَجَعٍ فِي الَْجنْبِ قَدْ يُسَمهى ذَاتَ الَْجنْبِ اشْتِقَاقًا مِنْ مَكَانِ الَْألََِ، لَِأنه مَعْنَى ذَاتِ الجنب صاحبة الجنب، والغرض به ها هنا وَجَعُ الَْجنْبِ، فَإِذَا عَرَضَ فِي الَْجنْبِ أَلٌََ عَنْ أَيِّ سَبَبٍ كَانَ نُسِبَ إِلَيْهِ، وَعَلَيْهِ حُِلَْ كَلَامُ بُـقْرَاطَ فِي قَـوْلِهِ: إِنه أَصْحَابَ ذَاتِ الَْجنْبِ يَـنْـتَفِعُونَ بِالَْحمَامِ. قِيلَ: الْمُرَادُ بِهِ كُلُّ مَنْ بِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَجَعُ جَنْبٍ، أَوْ وَجَعُ رِئَةٍ مِنْ سُوءِ مِزَاجٍ، أَوْ مِنْ أَخْلَاطٍ غَلِيظَةٍ، أَوْ لَذهاعَةٍ مِنْ غَيِْر وَرَمٍ وَلَا حُهْى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'قَالَ بَـعْضُ الَْأطِبهاءِ: وَأَمها مَعْنَى ذَاتِ الَْجنْبِ فِي لُغَةِ الْيُونَانِ، فَـهُوَ وَرَمُ الَْجنْبِ الَْحارُّ، وَكَذَلِكَ وَرَمُ كُلِّ وَاحِدٍ مِنَ الَْأعْضَاءِ الْبَاطِنَةِ، وَإِهنَما سُِّميَ ذَاتَ الَْجنْبِ وَرَمَ ذَلِكَ الْعُضْوِ إِذَا كَانَ وَرَمًا حَارًّا فَـقَطْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَيَـلْزَمُ ذَاتَ الَْجنْبِ الَْحقِيقِيِّ خَْمسَةُ أَعْرَاضٍ : وَهِيَ الُْحمهى وَالسُّعَالُ، وَالْوَجَعُ النهاخِسُ ، وَضِ يقُ النِّفَسِ ، وَالنهـبْضُ الْمِنْشَارِيُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَالْعِلَاجُ الْمَوْجُودُ فِي الَْحدِيثِ، لَيْسَ هُوَ لَِهذَا الْقِسْمِ، لَكِنْ لِلْقِسْمِ الثهانِي الْكَائِنِ عَنِ الرِّيحِ الْغَلِيظَةِ، فَإِنه الْقُسْطَ الْبَحْرِيه- وَهُوَ الْعُودُ الِْهنْدِيُّ على ما جاء', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '(7) أخرجه الترمذي والإمام أحدْ والحاكم في الطب. قال الحاكم: صحيح وأقره الذهب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'مُفَسهرًا فِي أَحَادِيثَ أُخَرَ- صِنْفٌ مِنَ الْقُسْطِ إِذَا دُقه دَقًّا نَاعِمًا، وَخُلِطَ بِالهزيْتِ الْمُسَخهنِ، وَدُلِكَ بِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'مَكَانُ الرِّيحِ الْمَذْكُورُ، أَوْ لُعِقَ، كَانَ دَوَاءً مُوَافِقًا لِذَلِكَ ، نَافِعًا لَهُ، مُلَُِّلًا لِمَادهتِهِ، مُذْهِبًا لََها، مُقَوِّيًا لِلْعَِْضَاءِ الْبَاطِنَةِ، مُفَتِّحًا لِلسُّدَدِ، وَالْعُودُ الْمَذْكُورُ فِي مَنَافِعِهِ كَذَلِكَ ..', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'قَالَ المسبحي »7« : الْعُودُ: حَارٌّ يَابِسٌ ، قَابِضٌ يَْحبِسُ الْبَطْنَ، وَيُـقَوِّي الَْأعْضَاءَ الْبَاطِنَةَ، وَيَطْرُدُ الرِّيحَ، وَيَـفْتَحُ السُّدَدَ، نَافِعٌ مِنْ ذَاتِ الَْجنْبِ، وَيُذْهِبُ فَضْلَ الرُّطُوبَةِ، وَالْعُودُ الْمَذْكُورُ جَيِّدٌ لِلدِّمَاغِ . قَالَ: وَيَُجوزُ أَنْ يَـنْـفَعَ الْقُسْطُ مِنْ ذَاتِ الَْجنْبِ الَْحقِيقِيهةِ أَيْضًا إِذَا كَانَ حُدُوثُـهَا عَنْ مَادهةٍ بَـلْغَمِيِّةٍ لَا سِيِّمَا فِي وَقْتِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'انِْطَْاطِ الْعِلهةِ، وَا هللَُّ أَعْلَمُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَذَاتُ الَْجنْبِ: مِنَ الَْأمْرَاضِ الَْخطِرَةِ؛ وَفِي الَْحدِيثِ الصهحِيحِ: عَنْ أم سلمة، أَنهـهَا قَالَتْ : بَدَأَ رَسُولُ ا هلِلَّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بَِمرَضِهِ فِي بَـيْتِ ميمونة، وَكَانَ كُلهمَا خَفه عَلَيْهِ، خَرَجَ وَصَلهى بِالنهاسِ ، وَكَانَ كُلهمَا وَجَدَ ثِقَلًا قَالَ: «مُرُوا أبا بكر فَـلْيُصَلِّ بِالنهاسِ » ، وَاشْتَده شَكْ وَاهُ حَ هتى غُمِرَ عَلَيْهِ مِنْ شِدهةِ الْوَجَعِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'فَاجْتَمَعَ عِنْدَهُ نِسَاؤُهُ، وَعَمُّهُ العباس، وأم الفضل بنت الحارث وأسماء بنت عميس، فَـتَشَاوَرُوا فِي لَدِّهِ، فَـلَدُّوهُ وَهُوَ مَغْمُورٌ، فَـلَمها أَفَاقَ قَالَ: «مَنْ فَـعَلَ بِي هَذَا، هَذَا مِنْ عَمَلِ نساء جئن من ها هنا، وَأَشَارَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'بِيَدِهِ إِلَى أَرْضِ الَْحبَشَةِ، وَكَانَتْ أم سلمة وَأَسَْماءُ لَدهتَاهُ، فَـقَالُوا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'يَا رَسُولَ ا هلِلَّ! خَشِينَا أَنْ يَكُونَ بِكَ ذَاتُ الَْجنْبِ. قَالَ: «فَبِمَ لَدَدْتُوَُنِي» ؟ قَالُوا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'بِالْعُودِ الِْهنْدِيِّ ، وَشَيْ ءٍ مِنْ وَرْسٍ ، وَقَطَرَاتٍ مِنْ زَيْتٍ . فَـقَالَ: «مَا كَانَ ا هللَُّ لِيَـقْذِفَنِِ بِذَلِكَ الدهاءِ» ، ُ مه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'قَالَ: «عَزَمْتُ عليكم ألايبقى فِي الْبَـيْتِ أَحَدٌ إِهلا لُده إِهلا عَمِّي العباس» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَفِي «الصهحِيحَيِْن» عَنْ عائشة رَضِيَ ا هللَُّ تَـعَالَى عَنْـهَا قَالَتْ : لَدَدْنَا رَسُولَ ا هلِلَّ صَلهى الله عليه وسلم، فأشار ألاتلدّوني، فَـقُلْنَا: كَرَاهِيَةَ الْمَرِيضِ لِلدهوَاءِ، فَـلَمها أَفَاقَ قَالَ: «أَلََْ أَنْـهَكُمْ أَنْ تَـلُدُّونِي، لَا يَـبْـقَى مِنْكُمْ أَحَدٌ إِهلا لُده غَيْـرَ عَمِّي العباس، فَإِنههُ لَ يشهدكم» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, '(7) أخرجه ابن سعد من طريق الواقدي وهو ضعيف. وأخرجه بنحوه عبد الرزاق في «المصنف» من حديث أسماء بنت عميس، وإسناده صحيح', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, '(2) أخرجه البخاري في الطب، ومسلم في اللباس.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'قَالَ أبو عبيد عن الأصمعي: اللُّدُودُ: مَا يُسْقَى الِْإنْسَانُ فِي أَحَدِ شِقهيِ الْفَمِ، أُخِذَ مِنْ لَدِيدَيِ الْوَادِي، وَهُاَُ جَانِبَاهُ. وَأَمها الْوَجُورُ: فَـهُوَ فِي وَسَطِ الْفَمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'قُـلْتُ : وَاللهدُودُ- بِالْفَتْحِ: - هُوَ الدهوَاءُ الهذِي يُـلَدُّ بِهِ. وَالسهعُوطُ: مَا أُدْخِلَ مِنْ أَنْفِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'وَفِي هَذَا الَْحدِيثِ مِنَ الْفِقْهِ مُعَاقَـبَةُ الَْجانِي بِِمثْلِ مَا فَـعَلَ سَوَاءٌ، إِذَا لََْ يَكُنْ فِعْلُهُ مُهَُرمًا لَِحقِّ ا هلِلَّ، وَهَذَا هُوَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'الصهوَابُ الْمَقْطُوعُ بِهِ لِبِضْعَةَ عَشَرَ دَلِيلًا قَدْ ذكََرْنَاهَا فِي مَوْضِ عٍ آخَرَ، وَهُوَ مَنْصُوصُ أحدْ، وَهُوَ ثَبَِتٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'عَنِ الُْخلَفَاءِ الهراشِدِينَ، وَتَـرْجَةََُ الْمَسْأَلَةِ بِالْقِصَاصِ فِي اللهطْمَةِ وَالضهرْبَةِ، وَفِيهَا عِدهةُ أَحَادِيثَ لَا مُعَارِضَ لَهاَ الْبَـتهةَ، فَـيَـتَـعَهيُن القول بها.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الصُّدَاعِ وَالشهقِيقَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى ابْنُ مَاجَهْ فِي «سُنَنِهِ» حَدِيثًا فِي صِحهتِهِ نَظَرٌ: أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ إِذَا صُدعَِ، غَلهفَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'رَأْسَهُ بِالِْحنهاءِ، وَيَـقُولُ: «إِنههُ نَافِعٌ بإذن مِنَ الصُّدَاعِ » »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَالصُّدَاعُ: أَلٌََ فِي بَـعْضِ أَجْزَاءِ الهرأْسِ أَوْ كُلِّهِ، فَمَا كَانَ مِنْهُ فِي أَحَدِ شِقهيِ الهرأْسِ لَازِمًا يُسَمهى شَقِيقَةً، وَإِنْ كَانَ شَامِلًا لَِجمِيعِهِ لَازِمًا، يُسَمهى بَـيْضَةً وَخُودَةً تَشْبِيهًا بِبَـيْضَةِ السِّ لَاحِ الهتِي تَشْتَمِلُ عَلَى الهرأْسِ كُلِّهِ، وَرُهبَما', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'كَانَ فِي مُؤَخهرِ الهرأْسِ أَوْ فِي مُقَ هدمِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَأَنْـوَاعُهُ كَثِيَرةٌ، وَأَسْبَابُهُ مُْختَلِفَةٌ. وَحَقِيقَةُ الصّدع سُخُونَةُ الهرأْسِ ، وَاحْ تِمَاؤُهُ لِمَا دَارَ فِيهِ مِنَ الْبُخَارِ يَطْلُبُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'النُّـفُوذَ مِنَ الهرأْسِ ، فَلَا يَِجدُ مَنْـفَذًا، فَـيَصْدَعُهُ كَمَا يَصْدَعُ الْوَعْيُ »2« إِذَا حَِيَْ مَا فِيهِ وَطَلَبَ النُّـفُوذَ، فَكُلُّ شَيْ ءٍ رَطْبٍ إذا حيْ، طلب مكانا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '(7) الحديث الذي في سنن ابن ماجه «كان لا يصيبه قُـرْحَةٌ وَلَا شَوْكَةٌ إِهلا وَضَعَ عَلَيْـهَا الِْحنهاءَ» وأخرج ابن السنِ في الطب وأبو نعيم في الطب أيضا عن أبي هريرة «كان إذا نزل عليه الوحي صدع فيلف رأسه بالحناء.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(2) الوعي: القح والمدّة- انظر القاموس المحيط- و «المدّة بالكسر: القيح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'أَوْسَعَ مِنْ مَكَانِهِ الهذِي كَانَ فِيهِ، فَإِذَا عَرَضَ هَذَا الْبُخَارُ فِي الهرأْسِ كُلِّهِ بَِحيْثُ لَا يُْمكِنُهُ التهـفَشِّ ي وَالتهحَلُّلُ، وَجَالَ فِي الهرأْسِ ، سُِّميَ السهدْرُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَالصُّدَاعُ يَكُونُ عَنْ أَسْبَابٍ عَدِيدَةٍ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'أَحَدُهَا: مِنْ غَلَبَةِ وَاحِدٍ مِنَ الطهبَائِعِ الَْأرْبَـعَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَالَْخامِسُ : يَكُونُ مِنْ قُـرُوحٍ تَكُونُ فِي الْمَعِدَةِ، فَـيَأْلََُ الهرأْسُ لِذَلِكَ الْوَرَمِ لِاتِّصَالِ الْعَصَبِ الْمُنْحَدِرِ مِنَ الهرأْسِ بِالْمَعِدَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَالسهادِسُ : مِنْ رِيحٍ غَلِيظَةٍ تَكُونُ فِي الْمَعِدَةِ، فَـتَصْعَدُ إِلَى الهرأْسِ فَـتَصْدَعُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَالسهابِعُ: يَكُونُ مِنْ وَرَمٍ فِي عُرُوقِ الْمَعِدَةِ، فَـيَأْلََُ الهرأْسُ بَِألََِ الْمَعِدَةِ لِلِاتِّصَالِ الهذِي بَـيْـنَـهُمَا. وَالثهامِنُ: صُدَاعٌ يَْحصُلُ عَنِ امْتِلَاءِ الْمَعِدَةِ مِنَ الطهعَامِ، ُ مه يَـنْحَدِرُ وَيَـبْـقَى بَـعْضُهُ نِيئًا، فَـيُصَدّعُِ الهرأْسَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَيُـثْقِلُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَالتهاسِعُ: يَـعْرِضُ بَـعْدَ الِْجمَاعِ لِتَخَلْخُلِ الِْجسْمِ، فَـيَصِلُ إِلَيْهِ مِنْ حَرِّ الَْهوَاءِ أَكْثَـرُ مِنْ قَدْرِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَالْعَاشِرُ: صُدَاعٌ يَْحصُلُ بَـعْدَ الْقَيْ ءِ وَالِاسْتِفْرَاغِ ، إِمها لِغَلَبَةِ الْيُـبْسِ ، وَإِمها لِتَصَاعُدِ الَْأخِْرَِةِ مِنَ الْمَعِدَةِ إِلَيْهِ. وَالَْحادِيَ عَشَرَ: صُدَاعٌ يَـعْرِضُ عَنْ شِدهةِ الَْحرِّ وَسُخُونَةِ الَْهوَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَالثهانِي عَشَرَ: مَا يَـعْرِضُ عَنْ شِدهةِ الْبَـرْدِ، وَتَكَاثُفِ الَْأخِْرَِةِ فِي الهرأْسِ وَعَدَمِ تَلََُّلِهَا. وَالثهالِثَ عَشَرَ: مَا يَْحدُثُ مِنَ السههَرِ وَعَدَمِ النهـوْمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَالهرابِعَ عَشَرَ: مَا يَْحدُثُ مِنْ ضَغْطِ الهرأْسِ وَحَلِْْ الشهيْ ءِ الثهقِيلِ عَلَيْهِ. وَالَْخامِسَ عَشَرَ: مَا يَْحدُثُ مِنْ كَثْـرَةِ الْكَلَامِ، فَـتَضْعُفُ قُـهوةُ الدِّمَاغِ لَِأجْ لِهِ. وَالسهادِسَ عَشَرَ: مَا يَْحدُثُ مِنْ كَثْـرَةِ الَْحرَكَةِ وَالرِّيَاضَةِ الْمُفْرِطَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَالسهابِعَ عَشَرَ: مَا يَْحدُثُ مِنَ الَْأعْرَاضِ النهـفْسَانِيهةِ، كَالْهمُُومِ، وَالْغُمُومِ، وَالَْأحْ زَانِ، وَالْوَسَاوِسِ ، وَالَْأفْكَارِ الهردِيئَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَالثهامِنَ عَشَرَ: مَا يَْحدُثُ مِنْ شِدهةِ الُْجوعِ ، فَإِنه الَْأخِْرَِةَ لَا تَِدَُ مَا تَـعْمَلُ فِيهِ، فَـتَكْ ثُـرُ وَتَـتَصَاعَدُ إِلَى الدِّمَاغِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'فَـتُـؤْلِمُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'وَالتهاسِعَ عَشَرَ مَا يَْحدُثُ عَنْ وَرَمٍ فِي صِفَاقِ الدِّمَاغِ ، وَيَِجدُ صَاحِبُهُ كَأَنههُ يُضْرَبُ بِالْمَطَارِقِ عَلَى رَأْسِهِ. وَالْعِشْرُونَ: مَا يَْحدُثُ بِسَبَبِ الُْحمهى لِاشْتِعَالِ حَرَارَتَِها فِيهِ فَـيَـتَأَهلَُ، وَا هللَُّ أَعْلَمُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ [في سبب صداع الشقيقة]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَسَبَبُ صُدَاعِ الشهقِيقَةِ مَادهةٌ فِي شَرَايِيِن الهرأْسِ وَحْدَهَا حَاصِلَةٌ فِيهَا، أَوْ مُرْتَقِيَةٌ إِلَيْـهَا، فَـيَـقْبَـلُهَا الَْجانِبُ الَْأضْعَفُ مِنْ جَانِبَـيْهِ، وَتِلْكَ الْمَادهةُ إِمها خُاَِرِيهةٌ، وَإِمها أَخْلَاطٌ حَارهةٌ أَوْ بَارِدَةٌ، وَعَلَامَتُـهَا الَْخاصهةُ بَِها ضَرْبَانِ الشهرَايِيِن، وَخَاصهةً فِي الدهمَوِيِّ . وَإِذَا ضُبِطَتْ بِالْعَصَائِبِ، وَمُنِعَتْ مِنَ الضهرَبَانِ، سَكَنَ الْوَجَعُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَقَدْ ذكََرَ أبو نعيم فِي كِتَابِ «الطِّبُّ النهـبَوِيُّ» لَهُ: أَنه هَذَا النهـوْعَ كَانَ يُصِيبُ النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَـيَمْكُثُ الْيَـوْمَ وَالْيَـوْمَيِْن، وَلَا يَْخرُجُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَفِيهِ: عَنِ ابْنِ عَهباسٍ قَالَ: خَطَبَـنَا رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَقَدْ عَصَبَ رَأْسَهُ بِعِصَابَةٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَفِي «الصهحِيحِ» ، أَنههُ قَالَ فِي مَرَضِ مَوْتِهِ: «وَارْأَسَاهُ» »7« وَكَانَ يُـعَصِّبُ رَأْسَهُ فِي مَرَضِهِ، وَعَصْبُ الهرأْسِ يَـنْـفَعُ فِي وَجَعِ الشهقِيقَةِ وَغَيِْرهَا مِنْ أَوْجَاعِ الرأس.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل [في علاج صداع الشقيقة]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَعِلَاجُهُ يَْختَلِفُ بِاخْتِلَافِ أَنْـوَاعِهِ وَأَسْبَابِهِ، فَمِنْهُ مَا عِلَاجُهُ بِالِاسْتِفْرَاغِ ، وَمِنْهُ مَا عِلَاجُهُ بِتَـنَاوُلِ الْغِذَاءِ، وَمِنْهُ مَا عِلَاجُهُ بِالسُّكُونِ وَالدهعَةِ، وَمِنْهُ مَا عِلَاجُهُ بِالضهمَادَاتِ، وَمِنْهُ مَا عِلَاجُهُ بِالتهـبِْيَدِ، وَمِنْهُ مَا عِلَاجُهُ بِالتهسْخِيِن، وَمِنْهُ مَا عِلَاجُهُ بَِأنْ يَْجتَنِبَ سََماعَ الَْأصْوَاتِ وَالَْحرَكَاتِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'إِذَا عُرِفَ هَذَا، فَعِلَاجُ الصُّدَاعِ فِي هَذَا الَْحدِيثِ بِالِْحنهاءِ، هُوَ جُزْئِيٌّ لَا كُلِّيٌّ، وَهُوَ عِلَاجُ نَـوْعٍ مِنْ أَنْـوَاعِهِ، فَإِنه الصُّدَاعَ إِذَا كَانَ مِنْ حَرَارَةٍ ملهبة، ولَ يكن من', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(7) أخرجه البخاري في المرض', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'مداة يَِجبُ اسْتِفْرَاغُهَا، نَـفَعَ فِيهِ الِْحنهاءُ نَـفْعًا ظَاهِرًا، وَإِذَا دُقه وَضُمِّدَتْ بِهِ الَْجبْـهَةُ مَعَ الَْخلِّ، سَكَنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الصُّدَاعُ، وَفِيهِ قُـهوةٌ مُوَافِقَةٌ لِلْعَصَبِ إِذَا ضُمِّدَ بِهِ، سَكَنَتْ أَوْجَاعُهُ، وَهَذَا لَا يَْختَصُّ بِوَجَعِ الهرأْسِ ، بَلْ يَـعُمُّ الَْأعْضَاءَ، وَفِيهِ قَـبْضٌ تُشَدُّ بِهِ الَْأعْضَاءُ، وَإِذَا ضُمِّدَ بِهِ مَوْضِعُ الْوَرَمِ الَْحارِّ وَالْمُلْتَهِبِ، سَكهنَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَقَدْ رَوَى الْبُخَارِيُّ فِي «تَارِيِخهِ» وأبو داود فِي «السُّنَنِ» أَنه رسول الله هللا ىلص ما شَكَى إِلَيْهِ أَحَدٌ وَجَعًا فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'رَأْسِهِ إِهلا قَالَ لَهُ: «احْتَجِمْ» ، وَلَا شَكَى إِلَيْهِ وَجَعًا فِي رِجْ لَيْهِ إِهلا قَالَ لَهُ: «اخْتَضِبْ بِالِْحنهاءِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَفِي الترمذي: عَنْ سلمى أم رافع خَادِمَةِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَتْ : كَانَ لَا يُصِيبُ النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قُـرْحَةٌ وَلَا شَوْكَةٌ إِهلا وَضَعَ عَلَيْـهَا الِْحنهاءَ »2« .', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل [في الحناء]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَالِْحنهاءُ بَارِدٌ فِي الُْأولَى، يَابِسٌ فِي الثهانِيَةِ، وَقُـهوةُ شَجَرِ الِْحنهاءِ وَأَغْصَانُـهَا مُرَكهبَةٌ مِنْ قُـهوةٍ مُلَُِّلَةٍ اكْ تَسَبَـتْـهَا مِنْ جَوْهَرٍ فِيهَا مَائِيٍّ، حَارٍّ بِاعْتِدَالٍ، وَمِنْ قُـهوةٍ قَابِضَةٍ اكْتَسَبَـتْـهَا مِنْ جَوْهَرٍ فِيهَا أَرْضِيٍّ بَارِدٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَمِنْ مَنَافِعِهِ إِنههُ مُلَُِّلٌ نَافِعٌ مِنْ حَرْقِ النهارِ، وَفِيهِ قُـهوةٌ مُوَافِقَةٌ لِلْعَصَبِ إِذَا ضُمِّدَ بِهِ، وَيَـنْـفَعُ إِذَا مُضِغَ من قروح الفم والسّلاق »3« العارض فيه، ويبىَء الْقُلَاعَ »4« الَْحادِثَ فِي أَفْـوَاهِ الصِّبْـيَانِ ، وَالضِّمَادُ بِهِ يَـنْـفَعُ مِنَ الَْأوْرَامِ الَْحارهةِ الْمُلْهِبَةِ، وَيَـفْعَلُ فِي الجراحات فعل دَمُ الَْأخَوَيْنِ. وَإِذَا خُلِطَ نَـوْرُهُ مَعَ الشهمْعِ الْمُصَ هفى، وَدُهْنِ الْوَرْدِ، يَـنْـفَعُ مِنْ أَوْجَاعِ الَْجنْبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَمِنْ خَوَاصِّهِ أَنههُ إِذَا بَدَأَ الُْجدَرِيُّ يَْخرُجُ بِصَبٍِّ، فَخُضِبَتْ أَسَافِلُ رِجْ لَيْهِ بِِحنهاءٍ، فَإِنههُ يُـؤْمَنُ عَلَى عَيْـنَـيْهِ أَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'يَْخرُجَ فِيهَا شَيْ ءٌ مِنْهُ، وَهَذَا صَحِيحٌ مُهََربٌ لَا شَكه فِيهِ. وَإِذَا جُعِلَ نَـوْرُهُ بَـيَْن طَيِّ ثِيَابِ الصُّوفِ طَيهـبَـهَا، وَمَنَعَ السُّوسَ عَنْـهَا، وَإِذَا نُقِعَ وَرَقُهُ فِي ماء عذب يَـغْمُرُهُ، ُ مه عُصِرَ وَشُرِبَ مَنْ صَفْوِهِ أَرْبَعِيَن يوما كلّ يوم عشرون', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(7) أخرجه أبو داود (2) أخرجه ابن ماجه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(3) السّلاق: كغراب: بثر يخرج على أصل اللسان، أو تعثر في أصول الأسنان انظر القاموس. (4) القلاع: داء في الفم- المرجع السابق', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'دِرْهَاًُ مَعَ عَشَرَةِ دَرَاهِمَ سُكهرٍ، وَيُـغَذهى عَلَيْهِ بِلَحْمِ الضهأْنِ الصهغِيِر، فَإِنههُ يَـنْـفَعُ مِنِ ابْتِدَاءِ الُْجذَامِ خِاَِصِّ يهةٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'فِيهِ عَجِيبَةٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَحُكِيَ أَنه رَجُلًا تَشَقهقَتْ أَظَافِيُر أَصَابِعِ يَدِهِ، وَأَنههُ بَذَلَ لِمَنْ يُـبِْئَُهُ مَالًا، فَـلَمْ يُْجدِ، فَـوَصَفَتْ لَهُ امْرَأَةٌ، أَنْ يَشْرَبَ عَشَرَةَ أَهيامٍ حِنهاءَ، فَـلَمْ يُـقْدِمْ عَلَيْهِ، ُ مه نَـقَعَهُ بَِماءٍ وَشَرِبَهُ، فَـبَـرَأَ وَرَجَعَتْ  أَظَافِيُرهُ إِلَى حُسْنِهَا. وَالِْحنهاءُ إِذَا أُلْزِمَتْ بِهِ الَْأظْفَارُ مَعْجُونًا حَسهنَـهَا وَنَـفَعَهَا، وَإِذَا عُجِنَ بِالسهمْنِ وضمّد به بقايا الأورام الحارة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'التي تشرح مَاءً أَصْفَرَ، نَـفَعَهَا وَنَـفَعَ مِنَ الَْجرَبِ الْمُتَـقَرِّحِ الْمُزْمِنِ مَنْـفَعَةً بَلِيغَةً، وَهُوَ يُـنْبِتُ الشهعْرَ وَيُـقَوِّيهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَيَُحسِّ نُهُ، وَيُـقَوِّي الهرأْسَ ، وَيَـنْـفَعُ مِنَ النهـهفاطَاتِ، وَالْبُـثُورِ الْعَارِضَةِ فِي السهاقَـيِْن وَالرِّجْ لَيِْن، وَسَائِرِ الْبَدَنِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي مُعَالََجةِ الْمَرْضَى بِتَـرْكِ إِعْطَائِهِمْ مَا يَكْرَهُونَهُ مِنَ الطعام والشراب، وأنهم لا يكرهون على تناولها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى الترمذي فِي «جَامِعِهِ» ، وَابْنُ مَاجَهْ، عَنْ عُقْبَةَ بْنِ عَامِرٍ الُْجهَنِِِّ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «لَا تُكْرِهُوا مَرْضَاكُمْ عَلَى الطهعَامِ وَالشهرَابِ، فَإِنه ا هللََّ عَهز وَجَله يُطْعِمُهُمْ وَيَسْقِيهِمْ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'قَالَ بَـعْضُ فُضَلَاءِ الَْأطِبهاءِ: مَا أَغْزَرَ فَـوَائِدَ هَذِهِ الْكَلِمَةِ النهـبَوِيهةِ الْمُشْتَمِلَةِ عَلَى حِكَمٍ إِلَِهيهةٍ، لَا سِيهمَا لِلْطَِِبهاءِ، وَلِمَنْ يُـعَالِجُ الْمَرْضَى، وَذَلِكَ أَنه الْمَرِيضَ إِذَا عَافَ الطهعَامَ أَوِ الشهرَابَ ، فَذَلِكَ لِاشْتِغَالِ الطهبِيعَةِ بُِمجَاهَدَةِ الْمَرَضِ ، أَوْ لِسُقُوطِ شَهْوَتِهِ، أَوْ نُـقْصَانَِها لِضَعْفِ الَْحرَارَةِ الْغَرِيزِيهةِ أَوْ خُُمودِهَا، وَكَيْـفَمَا كَانَ، فَلَا يَُجوزُ حِينَئِذٍ إِعْطَاءُ الْغِذَاءِ فِي هَذِهِ الَْحالَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(7) أخرجه الترمذي وهو حديث قوي، وأخرجه ابن ماجه والحاكم في الطب- «يطعمهم ويسقيهم» أي يحفظ قواهم ويمدهم بما تقع موقع الطعام والشراب في حفظ الروح وتقويم البدن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَاعْلَمْ أَنه الُْجوعَ إِهنَما هُوَ طَلَبُ الَْأعْضَاءِ لِلْغِذَاءِ لِتَخَلُّفِ الطهبِيعَةِ بِهِ عَلَيْـهَا عِوَضَ مَا يَـتَحَلهلُ مِنْـهَا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'فَـتَجْذِبُ الَْأعْضَاءَ الْقُصْوَى مِنَ الَْأعْضَاءِ الدُّنْـيَا حَ هتى يَـنْـتَهِيَ الَْجذْبُ إِلَى الْمَعِدَةِ، فَـيُحِسه الِْإنْسَانُ بِالَْجوْعِ ، فَـيَطْلُبُ الْغِذَاءَ، وَإِذَا وُجِدَ الْمَرَضُ ، اشْتَـغَلَتِ الطهبِيعَةُ بَِمادهتِهِ وَإِنْضَاجِهَا وَإِخْرَاجِهَا عَنْ طَلَبِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الْغِذَاءِ، أَوِ الشهرَابِ، فَإِذَا أُكْرِهَ الْمَرِيضُ عَلَى اسْتِعْمَالِ شَيْ ءٍ مِنْ ذَلِكَ ، تَـعَطهلَتْ بِهِ الطهبِيعَةُ عَنْ فِعْلِهَا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَاشْتَـغَلَتْ بَِهضْمِهِ وَتَدْبِيِرهِ عَنْ إِنْضَاجِ مَادهةِ الْمَرَضِ وَدَفْعِهِ، فَـيَكُونُ ذَلِكَ سَبَـبًا لِضَرَرِ الْمَرِيضِ ، وَلَا سِيهمَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'فِي أَوْقَاتِ الْبُحْ رَانِ »7« ، أَوْ ضَعْفِ الَْحارِّ الْغَرِيزِيِّ أَوْ خُُمودِهِ، فَـيَكُونُ ذَلِكَ زِيَادَةً فِي الْبَلِيهةِ، وَتَـعْجِيلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'النهازِلَةِ الْمُتَـوَقهـعَةِ، وَلَا يَـنْـبَغِي أَنْ يُسْتَـعْمَلَ فِي هَذَا الْوَقْتِ وَالَْحالِ إِهلا مَا يَْحفَظُ عَلَيْهِ قُـهوتَهُ وَيُـقَوِّيهَا مِنْ غَيِْر اسْتِعْمَالٍ مُزْعِجٍ لِلطهبِيعَةِ الْبَـتهةَ، وَذَلِكَ يَكُونُ بَِما لَطُفَ قِوَامُهُ مِنَ الَْأشْرِبَةِ وَالَْأغْذِيَةِ، وَاعْتَدَلَ مِزَاجُهُ كَشَرَابِ اللهيْـنُوفَرِ، وَالتِّهفاحِ، وَالْوَرْدِ الطهرِيِّ ، وَمَا أَشْبَهَ ذَلِكَ ، وَمِنَ الَْأغْذِيَةِ مَرَقُ الْفَرَارِيجِ الْمُعْتَدِلَةِ الطهيِّبَةِ فَـقَطْ ، وَإِنْـعَاشُ قُـوَاهُ بِالَْأرَايِيحِ الْعَطِرَةِ الْمُوَافِقَةِ، وَالَْأخْ بَارِ السهارهةِ، فَإِنه الطهبِيبَ خَادِمُ الطهبِيعَةِ، وَمُعِينُـهَا لَا مُعِيقُهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَاعْلَمْ أَنه الدهمَ الَْجيِّدَ هُوَ الْمُغَذِّي لِلْبَدَنِ ، وَأَنه الْبَـلْغَمَ دَمٌ فَجٌّ قَدْ نَضِجَ بَـعْضَ النُّضْجِ، فَإِذَا كَانَ بَـعْضُ الْمَرْضَى فِي بَدَنِهِ بَـلْغَمٌ كَثِيٌر، وَعَدِمَ الْغِذَاءَ، عَطَفَتِ الطهبِيعَةُ عَلَيْهِ، وَطَبَخَتْهُ، وَأَنْضَجَتْهُ، وَصَيهـرَتْهُ دَمًا، وَغَذهتْ بِهِ الَْأعْضَاءَ، وَاكْتَـفَتْ بِهِ عَمها سِوَاهُ، وَالطهبِيعَةُ هِيَ الْقُهوةُ الهتِي وَكَلَهَا ا هللَُّ سُبْحَانَهُ بِتَدْبِيِر الْبَدَنِ وَحِفْظِهِ وَصِحهتِهِ، وَحِرَاسَتِهِ مُدهةَ حَيَاتِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَاعْلَمْ أَنههُ قَدْ يَْحتَاجُ فِي النهدْرَةِ إِلَى إِجْبَارِ الْمَرِيضِ عَلَى الطهعَامِ وَالشهرَابِ، وَذَلِكَ فِي الَْأمْرَاضِ الهتِي يَكُونُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'مَعَهَا اخْتِلَاطُ الْعَقْلِ، وَعَلَى هَذَا فَـيَكُونُ الَْحدِيثُ مِنَ الْعَامِّ الْمَخْصُوصِ ، أَوْ مِنَ الْمُطْلَقِ الهذِي قَدْ دَ هل عَلَى تَـقْيِيدِهِ دَلِيلٌ، وَمَعْنَى الَْحدِيثِ: أَنه الْمَرِيضَ قَدْ يَعِيشُ بِلَا غِذَاءٍ أَهيامًا لَا يَعِيشُ الصهحِيحُ فِي مِثْلِهَا. وَفِي قَـوْلِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «فَإِنه ا هللََّ يُطْعِمُهُمْ وَيَسْقِيهِمْ» مَعْنًى لَطِيفٌ زَائِدٌ عَلَى مَا ذكََرَهُ الَْأطِبهاءُ لَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'يَـعْرِفُهُ إِهلا مَنْ لَهُ عِنَايَةٌ بَِأحْكَامِ الْقُلُوبِ وَالَْأرْوَاحِ، وَتَثَِْيِرهَا فِي طَبِيعَةِ الْبَدَنِ، وَانْفِعَالِ الطهبِيعَةِ عَنْـهَا، كَمَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'تَـنْـفَعِلُ هِيَ كَثِيًرا عَنِ الطهبِيعَةِ، وَنَنُْْ نُشِيُر إِلَيْهِ إِشَارَةً، فَـنَـقُولُ: النهـفْسُ إِذَا حَصَلَ لََها مَا يَشْغَلُهَا مِنْ مَبُُْوبٍ أَوْ مَكْ رُوهٍ أَوْ مَُخوفٍ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, '(7) البحران: بضم فسكون: وهو التغير الذي يحدث دفعة في الأمراض الحادة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'اشْتَـغَلَتْ بِهِ عَنْ طَلَبِ الْغِذَاءِ وَالشهرَابِ، فَلَا تُِسَُّ بِوُِعٍ وَلَا عَطَشٍ ، بَلْ وَلَا حَرٍّ وَلَا بَـرْدٍ، بَلْ تَشْتَغِلُ بِهِ عَنِ الِْإحْسَاسِ الْمُؤْلَِِ الشهدِيدِ الَْألََِ، فَلَا تُِسَُّ بِهِ، وَمَا مِنْ أَحَدٍ إِهلا وَقَدْ وَجَدَ فِي نَـفْسِهِ ذَلِكَ أَوْ شَيْـئًا مِنْهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَإِذَا اشْتَـغَلَتِ النهـفْسُ بَِما دَهَهََُا، وَوَرَدَ عَلَيْـهَا، لََْ تُِسَه بَِألََِ الُْجوعِ ، فَإِنْ كَانَ الْوَارِدُ مُفْرِحًا قَوِيه التهـفْرِيحِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'قَامَ لََها مَقَامَ الْغِذَاءِ، فَشَبِعَتْ بِهِ، وَانْـتَـعَشَتْ قُـوَاهَا، وَتَضَاعَفَتْ ، وَجَرَتِ الدهمَوِيهةُ فِي الَْجسَدِ حَ هتى تَظْهَرَ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'سَطْحِهِ، فَـيُشْرِقُ وَجْهُهُ، وَتَظْهَرُ دَمَوِيهـتُهُ، فَإِنه الْفَرَحَ يُوجِبُ انْبِسَاطَ دَمِ الْقَلْبِ ، فَـيَـنْـبَعِثُ في العروق، فتمتلىء بِهِ، فَلَا تَطْلُبُ الَْأعْضَاءُ حَظههَا مِنَ الْغِذَاءِ الْمُعْتَادِ لِاشْتِغَالَِها بَِما هُوَ أَحَبُّ إِلَيْـهَا، وَإِلَى الطهبِيعَةِ مِنْهُ، وَالطهبِيعَةُ إِذَا ظَفِرَتْ بَِما تُِبَُّ، آثَـرَتْهُ عَلَى مَا هُوَ دُونَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَإِنْ كَانَ الْوَارِدُ مُؤْلِمًا أَوْ مُزُِْنًا أَوْ مَُخوفًا، اشْتَـغَلَتْ بُِمحَارَبَتِهِ وَمُقَاوَمَتِهِ وَمُدَافَـعَتِهِ عَنْ طَلَبِ الْغِذَاءِ، فَهِيَ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'حَالِ حَرْبَِها فِي شَغْلٍ عَنْ طَلَبِ الطهعَامِ وَالشهرَابِ. فَإِنْ ظَفِرَتْ فِي هَذَا الَْحرْبِ، انْـتَـعَشَتْ قُـوَاهَا، وَأَخْلَفَتْ عَلَيْـهَا نَظِيَر مَا فَاتَـهَا مِنْ قُـهوةِ الطهعَامِ وَالشهرَابِ، وَإِنْ كَانَتْ مَغْلُوبَةً مَقْهُورَةً، انْطَْهتْ قُـوَاهَا بَِحسَبِ مَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'حَصَلَ لََها مِنْ ذَلِكَ ، وَإِنْ كَانَتِ الَْحرْبُ بَـيْـنَـهَا وَبَـيَْن هَذَا الْعَدُوِّ سِجَالًا، فَالْقُهوةُ تَظْهَرُ تَارَةً وَتَْختَفِي أُخْ رَى،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'وَبِالُْجمْلَةِ فَالَْحرْبُ بَـيْـنَـهُمَا عَلَى مِثَالِ الَْحرْبِ الَْخارِجِ بَـيَْن الْعَدُ هويْنِ الْمُتَـقَاتِلَيِْن، وَالنهصْرُ لِلْغَالِبِ، وَالْمَغْلُوبُ إِمها قَتِيلٌ، وَإِمها جَرِيحٌ، وَإِمها أَسِيٌر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'فَالْمَرِيضُ لَهُ مَدَدٌ مِنَ ا هلِلَّ تَـعَالَى يُـغَذِّيهِ بِهِ زَائِدًا عَلَى مَا ذكََرَهُ الَْأطِبهاءُ مِنْ تَـغْذِيَتِهِ بِالدهمِ، وَهَذَا الْمَدَدُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'بَِحسَبِ ضَعْفِهِ وَانْكِسَارِهِ وَانْطِرَاحِهِ بَـيَْن يَدَيْ رَبِّهِ عَهز وَجَله، فَـيَحْصُلُ لَهُ مِنْ ذَلِكَ مَا يُوجِبُ لَهُ قُـرْبًا مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'رَبِّهِ، فَإِنه الْعَبْدَ أَقْـرَبُ مَا يَكُونُ مِنْ رَبِّهِ إِذَا انْكَسَرَ قَـلْبُهُ، وَرَحْةَُْ رَبِّهِ عِنْدَئِذٍ قَرِيبَةٌ مِنْهُ، فَإِنْ كَانَ وَلِيًّا لَهُ، حَصَلَ لَهُ مِنَ الَْأغْذِيَةِ الْقَلْبِيهةِ مَا تَـقْوَى بِهِ قُـوَى طَبِيعَتِهِ، وَتَـنْـتَعِشُ بِهِ قُـوَاهُ أَعْظَمَ مِنْ قُـهوتَِها، وَانْتِعَاشِهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'بِالَْأغْذِيَةِ الْبَدَنِهيةِ، وَكُلهمَا قَوِيَ إِيَمانُهُ وَحُبُّهُ لِرَبِّهِ، وَأُنْسُهُ بِهِ، وَفَـرَحُهُ بِهِ، وَقَوِيَ يَقِينُهُ بِرَبِّهِ، وَاشْتَده شَوْقُهُ إِلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَرِضَاهُ بِهِ وَعَنْهُ، وَجَدَ فِي نَـفْسِهِ مِنْ هَذِهِ الْقُهوةِ مَا لَا يُـعَبَُِّ عَنْهُ، وَلَا يُدْركُِهُ وَصْفُ طَبِيبٍ، وَلَا يَـنَالُهُ عِلْمُهُ. وَمَنْ غَلُظَ طَبْـعُهُ، وَكَثُـفَتْ نَـفْسُهُ عَنْ فَـهْمِ هَذَا وَالتهصْدِيقِ بِهِ، فَـلْيَـنْظُرْ حَالَ كَثِيٍر مِنْ عُشهاقِ الصُّوَرِ الهذِينَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'قَدِ امْتَلَتَِْ قُـلُوبُـهُمْ بُِحبِّ مَا يَـعْشَقُونَهُ مِنْ صُورَةٍ، أَوْ جَاهٍ، أَوْ مَالٍ، أَوْ عِلْمٍ، وَقَدْ شَاهَدَ النهاسُ مِنْ هَذَا عَجَائِبَ فِي أَنْـفُسِهِمْ وَفِي غَيِْرهِمْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَقَدْ ثَـبَتَ فِي «الصهحِيحِ» : عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، أَنههُ كَانَ يُـوَاصِلُ فِي الصِّيَامِ الَْأهيامَ ذَوَاتِ الْعَدَدِ، وَيَـنْـهَى أَصْحَابَهُ عَنِ الْوِصَالِ وَيَـقُولُ «لَسْتُ كَهَيْـئَتِكُمْ إِنِّي أَظَلُّ يُطْعِمُنِِ رَبِّي وَيَسْقِينِِ» »7« . وَمَعْلُومٌ أَنه هَذَا الطهعَامَ وَالشهرَابَ لَيْسَ هُوَ الطهعَامَ الهذِي كََُْلُهُ الِْإنْسَانُ بِفَمِهِ، وَإِهلا لََْ يَكُنْ مُوَاصِلًا وَلََْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'يَـتَحَقهقِ الْفَرْقُ ، بَلْ لََْ يَكُنْ صَائِمًا، فَإِنههُ قَالَ «أَظَلُّ يُطْعِمُنِِ رَبِّي وَيَسْقِينِِ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَأَيْضًا فَإِنههُ فَـهرقَ بَـيْـنَهُ وَبَـيْـنَـهُمْ فِي نَـفْسِ الْوِصَالِ، وَأَنههُ يَـقْدِرُ مِنْهُ على ما لا يق يَـقْدِرُونَ عَلَيْهِ، فَـلَوْ كَانَ كََُْلُ وَيَشْرَبُ بِفَمِهِ، لََْ يَـقُلْ لَسْتُ كَهَيْـئَتِكُمْ، وَإِهنَما فَهِمَ هَذَا مِنَ الَْحدِيثِ مَنْ قَله نَصِيبُهُ مِنْ غِذَاءِ الَْأرْوَاحِ وَالْقُلُوبِ، وَتَثَِْيُرهُ فِي الْقُهوةِ وَإِنْـعَاشِهَا، وَاغْتِذَائِهَا بِهِ فَـوْقَ تَثَِْيِر الْغِذَاءِ الُْجسْمَانِِّي، وَا هللَُّ الْمُوَفِّقُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الْعُذْرَةِ، وَفِي الْعِلَاجِ بِالسهعُوطِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'ثَـبَتَ عَنْهُ فِي «الصهحِيحَيِْن» أَنههُ قَالَ: «خَيْـرُ مَا تَدَاوَيْـتُمْ بِهِ الِْحجَامَةُ، وَالْقُسْطُ الْبَحْرِيِّ ، وَلَا تُـعَذِّبُوا صِ بْـيَانَكُمْ بِالْغَمْزِ مِنَ الْعُذْرَةِ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَفِي «السُّنَنِ» وَ «الْمُسْنَدِ» عَنْهُ مِنْ حَدِيثِ جَابِرِ بْنِ عَبْدِ ا هلِلَّ قَالَ: دَخَلَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَسَلهمَ عَلَى عائشة، وَعِنْدَهَا صَبٌِّ يُسِيلُ مَنْخَرَاهُ دَمًا، فَـقَالَ: «مَا هَذَا؟» . فَـقَالُوا: بِهِ الْعُذْرَةُ، أَوْ وَجَعٌ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'رَأْسِهِ، فَـقَالَ: «وَيْـلَكُنه لَا تَـقْتُـلْنَ أَوْلَادكَُنه، أَيَُّما امْرَأَةٍ أَصَابَ وَلَدَهَا عُذْرَةٌ أَوْ وَجَعٌ فِي رَأْسِهِ، فَـلْتَأْخُذْ قُسْطًا هِنْدِيًّا فَـلْتَحُكههُ بَِماءٍ، ُ مه تُسْعِطْهُ إِهياهُ» فَأَمَرَتْ عائشة رَضِيَ ا هللَُّ عَنْـهَا فَصُنِعَ ذَلِكَ بِالصهبِِّ، فَـبَـرَأَ »3«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'قَالَ أبو عبيد عَنْ أبي عبيدة: الْعُذْرَةُ تَـهَيُّجٌ فِي الَْحلْقِ مِنَ الدهمِ، فَإِذَا عُولِجَ مِنْهُ، قِيلَ: قَدْ عُذِرَ بِهِ، فَـهُوَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'مَعْذُورٌ انْـتَـهَى. وَقِيلَ الْعُذْرَةُ: قُـرْحَةٌ تَْخرُجُ فِيمَا بَـيَْن الُْأذُنِ وَالَْحلْقِ، وَتَـعْرِضُ لِلصِّ بْـيَانِ غَالِبًا. وَأَمها نَـفْعُ السهعُوطِ مِنْـهَا بِالْقُسْطِ الْمَحْكُوكِ، فَلِنَِه الْعُذْرَةَ مادتها دم يغلب عليه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '(7) أخرجه البخاري ومسلم في الصيام', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(2) أخرجه البخاري في الطب، ومسلم في المساقاة، والإمام أحدْ، والنسائي (3) أخرجه الإمام أحدْ، وإسناده صحيح', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'الْبَـلْغَمُ، لَكِنه تَـوَلُّدَهُ فِي أَبْدَانِ الصِّ بْـيَانِ أَكْ ثَـرُ، وَفِي الْقُسْطِ تَفَِْيفٌ يَشُدُّ اللههَاةَ وَيَـرْفَـعُهَا إِلَى مَكَانَِها، وَقَدْ يَكُونُ نَـفْعُهُ فِي هَذَا الدهاءِ بِالَْخاصِّ يهةِ، وَقَدْ يَـنْـفَعُ فِي الَْأدْوَاءِ الَْحارهةِ، وَالَْأدْوِيَةِ الَْحارهةِ بِالذهاتِ تَارَةً وَبِالْعَرْضِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'أُخْ رَى. وَقَدْ ذكََرَ صَاحِبُ «الْقَانُونِ» فِي مُعَالََجةِ سُقُوطِ اللههَاةِ: الْقُسْطَ مَعَ الشهبِّ الْيَمَانِِّي، وَبِزْرِ الْمَرْوِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَالْقُسْطُ الْبَحْرِيُّ الْمَذْكُورُ فِي الَْحدِيثِ: هُوَ الْعُودُ الِْهنْدِيُّ، وَهُوَ الَْأبْـيَضُ مِنْهُ، وَهُوَ حُلْوٌ، وَفِيهِ مَنَافِعُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'عَدِيدَةٌ، وَكَانُوا يُـعَالُِجونَ أَوْلَادَهُمْ بِغَمْزِ اللههَاةِ وَبِالْعِلَاقِ، وَهُوَ شَيْ ءٌ يُـعَلِّقُونَهُ عَلَى الصِّ بْـيَانِ، فَـنَـهَاهُمُ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَنْ ذَلِكَ ، وَأَرْشَدَهُمْ إِلَى مَا هُوَ أَنْـفَعُ لِلْطَِْفَالِ، وَأَسْهَلُ عَلَيْهِمْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَالسهعُوطُ: مَا يُصَبُّ فِي الَْأنْفِ، وَقَدْ يَكُونُ بَِأدْوِيَةٍ مُفْرَدَةٍ وَمُرَكهبَةٍ تُدَقُّ وَتُـنْخَلُ وَتُـعْجَنُ وَتُهََففُ ، ُ مه تُلََُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'عِنْدَ الَْحاجَةِ، وَيُسْعَطُ بَِها فِي أَنْفِ الِْإنْسَانِ، وَهُوَ مُسْتَـلْقٍ عَلَى ظَهْرِهِ، وَبَـيَْن كَتِفَيْهِ ما يرفعهما لينخفض رَأْسُهُ، فَـيَـتَمَكهنُ السهعُوطُ مِنَ الْوُصُولِ إِلَى دِمَاغِهِ، وَيَسْتَخْرِجُ مَا فِيهِ مِنَ الدهاءِ بِالْعُطَاسِ ، وَقَدْ مَدَحَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ التهدَاوِي بِالسهعُوطِ فِيمَا يُْحتَاجُ إِلَيْهِ فِيهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَذكََرَ أبو داود فِي «سُنَنِهِ» أَنه النهبِه صَلهى ا هللَُّ عليه وسلم استعط »7«', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ في علاج المفؤود', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى أبو داود فِي «سُنَنِهِ» مِنْ حَدِيثِ ماَهد، عَنْ سعد، قَالَ: مَرِضْتُ مَرَضًا، فَأَتَانِي رَسُولُ ا هلِلَّ صَلهى ا هللَُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'عَلَيْهِ وَسَلهمَ يَـعُودُنِي، فَـوَضَعَ يَدَهُ بَـيَْن ثَدْيَيه حَ هتى وَجَدْتُ بَـرْدَهَا على فؤادي، وقال لِ «إنّك رجل مفؤود فَأْتِ الحارث بن كلدة مِنْ ثَقِيفٍ، فَإِنههُ رَجُلٌ يَـتَطَبهبُ ، فَـلْيَأْخُذْ سَبْعَ تَرَََاتٍ مِنْ عَجْوَةِ المدينة، فليجأهنّ بنواهنّ م ليلدّك بهنّ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'المفؤود: الهذِي أُصِيبَ فُـؤَادُهُ، فَـهُوَ يَشْتَكِيهِ، كَالْمَبْطُونِ الهذِي يَشْتَكِي بَطْنَهُ وَاللهدُودُ مَا يُسْقَاهُ الِْإنْسَانُ مِنْ أَحَدِ جَانِبَِ الْفَمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَفِي التهمْرِ خَاصِّ يهةٌ عَجِيبَةٌ لَِهذَا الدهاءِ، وَلَا سِيهمَا تَرََْ الْمَدِينَةِ، وَلَا سيما العجوة منه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(7) أخرجه أبو داود من حديث ابن عباس', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(2) أخرجه أبو داود في الطب «فليجأهن بنواهن» يريد ليرضعهن، والوجيئة: حساء يتخذ من التمر والدقيق، فيتحساه المريض', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَفِي كَوْنَِها سَبْـعًا خَاصِّ يهةٌ أُخْ رَى، تُدْرَكُ بِالْوَحْيِ ، وفي «الصحيحين» من حديث عامر ابن سَعْدِ بْنِ أَبِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَهقاصٍ ، عَنْ أَبِيهِ قَالَ: قَالَ رَسُولُ ا هلِلَّ صَ هلى ا هللَُّ عَلَيْهِ وَسَلهمَ «مَنْ تَصَبهحَ بِسَبْعِ تَرَََاتٍ مِنْ تَرَِْ الْعَالِيَةِ لَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'يمرّه ذَلِكَ الْيَـوْمَ سَمٌّ وَلَا سِحْرٌ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَفِي لَفْظٍ: مَنْ أَكَلَ سَبْعَ تَرَََاتٍ مِمها بَـيَْن لَابَـتَـيْـهَا حِيَن يُصْبِحُ، لََْ يَضُهرهُ سَمٌّ حَ هتى يُْمسِيَ » »7« . وَالتهمْرُ حَارٌّ فِي الثهانِيَةِ، يَابِسٌ فِي الُْأولَى. وَقِيلَ: رَطْبٌ فِيهَا. وَقِيلَ: مُعْتَدِلٌ، وَهُوَ غِذَاءٌ فَاضِلٌ حَافِظٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'لِلصِّحهةِ لَا سِيهمَا لِمَنِ اعْتَادَ الْغِذَاءَ بِهِ، كَأَهْلِ الْمَدِينَةِ وَغَيِْرهِمْ، وَهُوَ مِنْ أَفْضَلِ الَْأغْذِيَةِ فِي الْبِلَادِ الْبَارِدَةِ وَالَْحارهةِ الهتِي حَرَارَتُـهَا فِي الدهرَجَةِ الثهانِيَةِ، وَهُوَ لَهمُْ أَنْـفَعُ مِنْهُ لَِأهْلِ الْبِلَادِ الْبَارِدَةِ، لِبُـرُودَةِ بَـوَاطِنِ سُكهانَِها، وَحَرَارَةِ بَـوَاطِنِ سُكهانِ الْبِلَادِ الْبَارِدَةِ، وَلِذَلِكَ يُكْثِرُ أَهْلُ الِْحجَازِ وَالْيَمَنِ وَالطهائِفِ، وَمَا يَلِيهِمْ مِنَ الْبِلَادِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'الْمُشَابَِهةِ لََها مِنَ الَْأغْذِيَةِ الَْحارهةِ مَا لَا يَـتَأَتهى لِغَيِْرهِمْ، كَالتهمْرِ وَالْعَسَلِ، وَشَاهَدْنَاهُمْ يَضَعُونَ فِي أَطْعِمَتِهِمْ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'الْفُلْفُلِ وَالهزنْبَِْيلِ فَـوْقَ مَا يصنعه غَيْـرُهُمْ نَوَْْ عَشَرَةِ أَضْعَافٍ أَوْ أَكْ ثَـرَ وَكََُْلُونَ الهزنْبَِْيلَ كَمَا كََُْلُ غَيْـرُهُمُ الَْحلْوَى، وَلَقَدْ شَاهَدْتُ مَنْ يَـتَـنَـقهلُ بِهِ مِنْـهُمْ كَمَا يَـتَـنَـقهلُ بِالنهـقْلِ، وَيُـوَافِقُهُمْ ذَلِكَ وَلَا يَضُرُّهُمْ لِبُـرُودَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'أَجْ وَافِهِمْ وَخُرُوجِ الَْحرَارَةِ إِلَى ظَاهِرِ الَْجسَدِ، كَمَا تُشَاهَدُ مِيَاهُ الْآبَارِ تَـبْـرُدُ فِي الصهيْفِ، وَتَسْ خَنُ فِي الشِّ تَاءِ، وَكَذَلِكَ تُـنْضِجُ الْمَعِدَةُ مِنَ الَْأغْذِيَةِ الْغَلِيظَةِ فِي الشِّ تَاءِ مَا لَا تُـنْضِجُهُ فِي الصهيْفِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَأَمها أَهْلُ الْمَدِينَةِ، فَالتهمْرُ لَهمُْ يَكَادُ أَنْ يَكُونَ بَِمنْزِلَةِ الِْحنْطَةِ لِغَيِْرهِمْ، وَهُوَ قُوتُـهُمْ وَمَادهتُـهُمْ، وَتَرَُْ الْعَالِيَةِ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'أَجْ وَدِ أَصْنَافِ تَرَِْهِمْ، فَإِنههُ مَتِيُن الِْجسْمِ، لَذِيذُ الطهعْمِ، صَادِقُ الَْحلَاوَةِ، وَالتهمْرُ يَدْخُلُ فِي الَْأغْذِيَةِ وَالَْأدْوِيَةِ وَالْفَاكِهَةِ، وَهُوَ يُـوَافِقُ أَكْ ثَـرَ لأبدان، مُقَوٍّ لِلْحَارِّ الْغَرِيزِيِّ ، وَلَا يَـتَـوَلهدُ عَنْهُ مِنَ الْفَضَلَاتِ الهردِيئَةِ مَا يَـتَـوَلهدُ عَنْ غَيِْرهِ مِنَ الَْأغْذِيَةِ وَالْفَاكِهَةِ، بَلْ يَْمنَعُ لِمَنِ اعْتَادَهُ مِنْ تَـعَفُّنِ الَْأخْلَاطِ وَفَسَادِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَهَذَا الَْحدِيثُ مِنَ الِْخطَابِ الهذِي أُرِيدَ بِهِ الَْخاصُّ، كَأَهْلِ الْمَدِينَةِ وَمَنْ جَاوَرَهُمْ، وَلَا رَيْبَ أَنه لِلْمَِْكِنَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'اخْتِصَاصًا بِنَـفْعِ كَثِيٍر مِنَ الَْأدْوِيَةِ فِي ذَلِكَ الْمَكَانِ دُونَ غيره، فيكون الدواء الذي يَـنْـبُتُ فِي هَذَا الْمَكَانِ نَافِعًا مِنَ الدهاءِ، وَلَا يُوجَدُ فِيهِ ذَلِكَ النهـفْعُ إِذَا نَـبَتَ فِي مَكَانٍ غَيِْرهِ لِتَأْثِيِر نَـفْسِ التُّـرْبَةِ أَوِ الهواء، أو هاُ جيَعا فإن للرِض', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, '(7) أخرجه الإمام البخاري في الأطعمة، ومسلم في الأشربة والإمام أحدْ وأبو داود.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'خواص وَطَبَائِعَ يُـقَارِبُ اخْتِلَافُـهَا اخْتِلَافَ طَبَائِعِ الِْإنْسَانِ، وَكَثِيٌر مِنَ النهـبَاتِ يَكُونُ فِي بَـعْضِ الْبِلَادِ غِذَاءً مَأْكُولًا، وَفِي بَـعْضِهَا سَمها قَاتِلًا، وَرُبه أَدْوِيَةٍ لقوم أغفية لِآخَرِينَ، وَأَدْوِيَةٍ لِقَوْمٍ مِنْ أَمْرَاضٍ هِيَ أَدْوِيَةٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'لِآخَرِينَ فِي أَمْرَاضٍ سِوَاهَا، وَأَدْوِيَةٍ لَِأهْلِ بَـلَدٍ لَا تُـنَاسِبُ غَيْـرَهُمْ، وَلَا تَـنْـفَعُهُمْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَأَمها خَاصِّ يهةُ السهبْعِ، فَإِنهـهَا قَدْ وَقَـعَتْ قَدْرًا وَشَرْعًا، فَخَلَقَ ا هللَُّ عَهز وَجَله السّمَاوَاتِ سَبْـعًا، وَالَْأرَضِيَن سَبْـعًا، وَالَْأهيامَ سَبْـعًا، وَالِْإنْسَانُ كَمُلَ خَلْقُهُ فِي سَبْـعَةِ أَطْوَارٍ، وَشَرَعَ ا هللَُّ سُبْحَانَهُ لِعِبَادِهِ الطهوَافَ سَبْـعًا، وَالسهعْيَ بَـيَْن الصهفَا وَالْمَرْوَةِ سَبْـعًا وَرَمْيَ الِْجمَارِ سَبْـعًا سَبْـعًا، وَتَكْ بِيَراتِ الْعِيدَيْنِ سَبْـعًا فِي الُْأولَى وَقَالَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'صَلهى ا هللَُّ عَلَيْهِ وَسَ هلمَ «مُرُوهُمْ بِالصهلَاةِ لِسَبْعٍ» »7« : «وَإِذَا صَارَ لِلْغُلَامِ سَبْعُ سِنِيَن خُيَِّر بَـيَْن أَبَـوَيْهِ»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, '»2« فِي رِوَايَةٍ. وَفِي رِوَايَةٍ أُخْ رَى: «أَبُوهُ أَحَقُّ بِهِ مِنْ أُمِّهِ» وَفِي ثَلَِثَةٍ «أُمُّهُ أَحَقُّ بِهِ» وَأَمَرَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي مَرَضِهِ أَنْ يُصَبه عَلَيْهِ مِنْ سَبْعِ قِرَبٍ »3« ، وَسَخهرَ ا هللَُّ الرِّيحَ عَلَى قَـوْمِ عَادٍ سَبْعَ لَيَالٍ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'وَدَعَا النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنْ يُعِينَهُ ا هللَُّ عَلَى قَـوْمِهِ بِسَبْعٍ كَسَبْعِ يُوسُفَ »4« ، وَمَثهلَ ا هللَُّ سُبْحَانَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'مَا يُضَاعِفُ بِهِ صَدَقَةَ الْمُتَصَدِّقِ بَِحبهةٍ أَنْـبَـتَتْ  سَبْعَ سَنَابِلَ فِي كُلِّ سُنْـبُـلَةٍ مِائَةُ حَبهةٍ، وَالسهنَابِلُ الهتِي رَآهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'صَاحِبُ يُوسُفَ سَبْـعًا، وَالسِّ نِيَن الهتِي زَرَعُوهَا دَأَبًا سَبْـعًا، وَتُضَاعَفُ الصهدَقَةُ إِلَى سَبْعِمِائَةِ ضِعْفٍ إِلَى أَضْعَافٍ كَثِيَرةٍ، وَيَدْخُلُ الَْجنهةَ مِنْ هَذِهِ الُْأمهةِ بِغَيِْر حِسَابٍ سَبْـعُونَ أَلْفًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'فَلَا رَيْبَ أَنه لَِهذَا الْعَدَدِ خَاصِّ يهةً لَيْسَتْ لِغَيِْرهِ، وَالسهبْـعَةُ جَعَََتْ مَعَانَِي الْعَدَدِ كُلِّهِ وَخَوَاصِّهُ، فَإِنه الْعَدَدَ شَفْعٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'وَوَتْـرٌ وَالشهفْعُ أَهولٌ وَثَنٍَ. وَالْوَتْـرُ: كَذَلِكَ ، فَـهَذِهِ أَرْبَعُ مَرَاتِبَ : شَفْعٌ أَهولٌ، وَثَنٍَ وَوَتْـرٌ أَهولٌ وَثَنٍَ، وَلَا تَتََْمِعُ هَذِهِ الْمَرَاتِبُ فِي أَقَله مِنْ سَبْـعَةٍ، وَهِيَ عَدَدٌ كَامِلٌ جَامِعٌ لِمَرَاتِبِ الْعَدَدِ الَْأرْبَـعَةِ، أَعْنِِ الشهفْعَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَالْوَتْـرَ، وَالَْأوَائِلَ وَالثهـوَانَِي، وَنَـعْنِِ بِالْوَتْرِ الَْأهولِ الثهلَاثَةَ، وَبِالثهانِي الَْخمْسَةَ، وَبِالشهفْعِ الَْأهولِ الِاثْـنَـيِْن، وَبِالثهانِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'الَْأرْبَـعَةَ، وَلِلْطَِِبهاءِ اعْتِنَاءٌ عَظِيمٌ بِالسهبْـعَةِ، وَلَا سِيهمَا فِي البحارين. وقد قال', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, '(7) أخرجه الإمام أحدْ وأبو داود بلفظ «مروا الصب بالصلاة إذا بلغ سبع سنين، وإذا بلغ عشر سنين فاضربوه عليها» وسنده صحيح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, '(2) ثبت أنه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ خَيهـرَ غُلَامًا بَـيَْن أبيه وأمه» أخرجه أحدْ والترمذي وابن ماجه وقال', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'الترمذي: حديث حسن صحيح. (3) أخرجه البخاري في المغازي (4) أخرجه البخاري في المغازي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'بقراط: كُلُّ شَيْ ءٍ مِنْ هَذَا الْعَالََِ، فَـهُوَ مُقَدهرٌ عَلَى سَبْـعَةِ أَجْ زَاءَ، وَالنُّجُومُ سَبْـعَةٌ، وَالَْأهيامُ سَبْـعَةٌ، وَأَسْنَانُ النهاسِ سَبْـعَةٌ، أَهولُهاَ طِفْلٌ إِلَى سَبْعٍ، ُ مه صَبٌِّ إِلَى أَرْبَعَ عَشْرَةَ، ُ مه مُرَاهِقٌ، ُ مه شَابٌّ، ُ مهكَهْلٌ، ُ مه شَيْخٌ، ُ مه هَرَمٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'إِلَى مُنْـتَـهَى الْعُمُرِ، وَا هللَُّ تَـعَالَى أَعْلَمُ بِِحكْمَتِهِ وَشَرْعِهِ، وَقَدْرِهِ فِي تَْخصِيصِ هَذَا الْعَدَدِ هَلْ هُوَ لَِهذَا الْمَعْنَى أَوْ لِغَيِْرهِ؟.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'وَنَـفَعَ هَذَا الْعَدَدُ مِنْ هَذَا التهمْرِ مِنْ هَذَا الْبَـلَدِ مِنْ هَذِهِ الْبُـقْعَةِ بِعَيْنِهَا مِنَ السهمِّ وَالسِّ حْرِ، بَِحيْثُ تَنََْعُ إِصَابَـتُهُ، مِنَ الَْخوَاصِّ الهتِي لَوْ قَالََها بقراط وجالينوس وَغَيْـرُهُاَُ مِنَ الَْأطِبهاءِ، لَتَـلَقهاهَا عَنْـهُمُ الَْأطِبهاءُ بِالْقَبُولِ وَالِْإذْعَانِ وَالِانْقِيَادِ، مَعَ أَنه الْقَائِلَ إِهنَما مَعَهُ الَْحدْسُ وَالتهخْمِيُن وَالظهنُّ، فَمَنْ كَلَامُهُ كُلُّهُ يَقِيٌن، وَقَطْعٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'وَبُـرْهَانٌ، وَوَحْيٌ أَوْلَى أَنْ تُـتَـلَقهى أَقْـوَالُهُ بِالْقَبُولِ وَالتهسْلِيمِ، وَتَـرْكِ الِاعْتَِراضِ . وَأَدْوِيَةُ السُّمُومِ تَارَةً تَكُونُ بِالْكَيْفِيهةِ، وتارة تتكون بِالَْخاصِّ يهةِ كَخَوَاصِّ كَثِيٍر مِنَ الَْأحْجَارِ وَالَْجوَاهِرِ وَالْيَـوَاقِيتِ، والله أعلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'ِ   ِ ِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'ِ ِ               ِ              ِ     ِ       ِ', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَيَُجوزُ نَـفْعُ التهمْرِ الْمَذْكُور في بَـعْضِ السُّمُوم، فَـيَكُونُ الَْحديثُ منَ الْعَامّ الْمَخْصُوصِ ، وَيَُجوزُ نَـفْعُهُ لَخاصّيهة تِلْكَ الْبَـلَدِ، وَتِلْكَ التُّـرْبَةِ الَْخاصهةِ من كل سم، ولكن ها هنا أمر لابد مِنْ بَـيَانِهِ، وَهُوَ أَنه مِنْ شَرْطِ انْتِفَاعِ الْعَلِيلِ بِالدهوَاءِ قَـبُولَهُ، وَاعْتِقَادَ النهـفْعِ بِهِ، فَـتَـقْبَـلُهُ الطهبِيعَةُ، فَـتَسْ تَعِيُن بِهِ عَلَى دَفْعِ الْعِلهةِ، حَ هتى إِنه كَثِيًرا مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الْمُعَالََجاتِ يَـنْـفَعُ بِالِاعْتِقَادِ، وَحُسْنِ الْقَبُولِ، وَكَمَالِ التهـلَقِّي، وَقَدْ شَاهَدَ النهاسُ مِنْ ذَلِكَ عَجَائِبَ ، وَهَذَا لَِأنه الطهبِيعَةَ يَشْتَدُّ قَـبُولَُها لَهُ، وَتَـفْرَحُ النهـفْسُ بِهِ، فَـتَـنْـتَعِشُ الْقُهوةُ، وَيَـقْوَى سُلْطَانُ الطهبِيعَةِ، وَيَـنْـبَعِثُ الَْحارٌّ الْغَرِيزِيٌّ، فَـيُسَاعِدُ عَلَى دَفْعِ الْمُؤْذِي، وَبِالْعَكْسِ يَكُونُ كَثِيٌر مِنَ الَْأدْوِيَةِ نَافِعًا لِتِلْكَ الْعِلهةِ، فَـيَـقْطَعُ عَمَلَهُ سُوءُ اعْتِقَادِ الْعَلِيلِ فِيهِ، وَعَدَمُ أَخْذِ الطهبِيعَةِ لَهُ بِالْقَبُولِ، فَلَا يُْجدِي عَلَيْـهَا شَيْـئًا. وَاعْتَـبَـرَ هَذَا بَِأعْظَمِ الَْأدْوِيَةِ وَالَْأشْفِيَةِ، وَأَنْـفَعِهَا لِلْقُلُوبِ وَالَْأبْدَانِ ، وَالْمَعَاشِ وَالْمَعَادِ، وَالدُّنْـيَا وَالْآخِرَةِ، وَهُوَ الْقُرْآنُ الهذِي هُوَ شِفَاءٌ مِنْ كُلِّ دَاءٍ، كَيْفَ لَا يَـنْـفَعُ الْقُلُوبَ الهتِي لَا تَـعْتَقِدُ فِيهِ الشِّ فَاءَ وَالنهـفْعَ، بَلْ لَا يَزِيدُهَا إِهلا مَرَضًا إِلَى مَرَضِ هَا، وَلَيْسَ لِشِفَاءِ الْقُلُوبِ دَوَاءٌ قَطُّ أَنْـفَعُ مِنَ الْقُرْآنِ، فَإِنههُ شِفَاؤُهَا التهامُّ الْكَامِلُ الهذِي لَا يُـغَادِرُ فِيهَا سَقَمًا إِهلا أَبْـرَأَهُ، وَيَْحفَظُ عَلَيْـهَا صِحهتَـهَا الْمُطْلَقَةَ، وَيَْحمِيهَا الَْحمِيهةَ التهامهةَ مِنْ كُلِّ مُؤْذٍ ومضر،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَمَعَ هَذَا فَإِعْرَاضُ أَكْثَرِ الْقُلُوبِ عَنْهُ، وَعَدَمُ اعتقادها الجازم الذي لا ريب فيه نه كَذَلِكَ ، وَعَدَمُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'اسْتِعْمَالِهِ، وَالْعُدُولُ عَنْهُ إِلَى الَْأدْوِيَةِ الهتِي ركَهبَـهَا بَـنُو جِنْسِهَا حَالَ بَـيْـنَـهَا وَبَـيَْن الشِّ فَاءِ بِهِ، وَغَلَبَتِ الْعَوَائِدُ، وَاشْتَده الِْإعْرَاضُ ، وَتَكََهنَتِ الْعِلَلُ وَالَْأدْوَاءُ الْمُزْمِنَةُ مِنَ الْقُلُوبِ، وَتَـرَهبَ الْمَرْضَى وَالَْأطِبهاءُ عَلَى عِلَاجِ بَنِِ جِنْسِهِمْ وَمَا وَضَعَهُ لَهمُْ شُيُوخُهُمْ، وَمَنْ يُـعَظِّمُونَهُ وَيُْحسِنُونَ بِهِ ظُنُونَـهُمْ، فعظم المصاب، واستحكم الداء،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وتركبت أمراض وعل أَعْيَا عَلَيْهِمْ عِلَاجُهَا، وَكُلهمَا عَالَُجوهَا بِتِلْكَ الْعِلَاجَاتِ الَْحادِثَةِ تَـفَاقَمَ أَمْرُهَا، وَقَوِيَتْ ، وَلِسَانُ الَْحالِ يُـنَادِي عَلَيْهِمْ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَمِنَ الْعَجَائِبِ وَالْعَجَائِبُ جَهَةٌ ... قُـرْبُ الشِّ فَاءِ وَمَا إِلَيْهِ وُصُولُ كَالْعِيسِ فِي الْبَـيْدَاءِ يَـقْتُـلُهَا الظما ... والماء فوق ظهورها ممُول', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي دَفْعِ ضَرَرِ الَْأغْذِيَةِ وَالْفَاكِهَةِ وَإِصْلَاحِهَا بَِما يَدْفَعُ ضَرَرَهَا، وَيُـقَوِّي نَـفْعَهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'ثَـبَتَ فِي «الصهحِيحَيِْن» مِنْ حَدِيثِ عَبْدِ ا هلِلَّ بْنِ جعفر، قَالَ: رأيت رسول صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كََُْلُ الرُّطَبَ بِالْقِثهاءِ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَالرُّطَبُ : حَارٌّ رَطْبٌ فِي الثهانِيَةِ، يُـقَوِّي الْمَعِدَةَ الْبَارِدَةَ، وَيُـوَافِقُهَا، وَيَزِيدُ فِي الْبَاهِ، وَلَكِنههُ سَرِيعُ التهـعَفُّنِ، مُعَطِّشٌ مُعَكِّرٌ لِلدهمِ، مُصَدّعٌِ مُوَلِّدٌ لِلسهدَدِ، وَوَجَعِ الْمَثَانَةِ، وَمُضِرٌّ بِالَْأسْنَانِ، وَالْقِثهاءُ بَارِدٌ رَطْبٌ فِي الثهانِيَةِ، مُسَكِّنٌ لِلْعَطَشِ ، مُنْعِشٌ لِلْقُوَى بِشَمِّهِ لما فيه من العطرية، مطفىء لَِحرَارَةِ الْمَعِدَةِ الْمُلْتَهِبَةِ، وَإِذَا جُفِّفَ بِزْرُهُ، وَدُقه وَاسْتُحْلِبَ بِالْمَاءِ، وَشُرِبَ ، سَكهنَ الْعَطَشَ ، وَأَدَره الْبَـوْلَ، وَنَـفَعَ مِنْ وَجَعِ الْمَثَانَةِ. وَإِذَا دُقه وَنُِلَُ، وَدُلِكَ بِهِ الَْأسْنَانُ، جَلَاهَا، وَإِذَا دُقه وَرَقُهُ وَعُمِلَ مِنْهُ ضِمَادٌ مَعَ الْمَيْـبَخْتَجِ، نَـفَعَ مِنْ عَضهةِ الْكَلْبِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الْكَلِبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَبِالُْجمْلَةِ: فَـهَذَا حَارٌّ، وَهَذَا بَارِدٌ، وَفِي كُلٍّ مِنْـهُمَا صَلَاحُ الْآخَرِ، وَإِزَالَةٌ لأكثر', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(7) أخرجه البخاري في الأطعمة ومسلم في الأشربة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'ضَرَرِهِ، وَمُقَاوَمَةُ كُلِّ كَيْفِيهةٍ بِضِدِّهَا، وَدَفْعِ سُورَتَِها بِالُْأخْ رَى، وَهَذَا أَصْلُ الْعِلَاجِ كُلِّهِ، وَهُوَ أَصْلٌ فِي حِفْظِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الصِّحهةِ، بَلْ عِلْمُ الطِّبِّ كُلُّهُ يُسْتَـفَادُ مِنْ هَذَا. وَفِي اسْتِعْمَالِ ذَلِكَ وَأَمْثَالِهِ فِي الَْأغْذِيَةِ وَالَْأدْوِيَةِ إِصْلَاحٌ لََها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَتَـعْدِيلٌ، وَدَفْعٌ لِمَا فِيهَا مِنَ الْكَيْفِيهاتِ الْمُضِ هرةِ لِمَا يُـقَابِلُهَا، وَفِي ذَلِكَ عَوْنٌ عَلَى صِحهةِ الْبَدَنِ، وَقُـهوتِهِ وَخَصْبِهِ، قَالَتْ عائشة رَضِيَ ا هللَُّ عَنْـهَا: سَمهنُونِي بِكُلِّ شَيْ ءٍ، فَـلَمْ أَسَْمنْ ، فَسَمهنُونِي بِالْقِثهاءِ وَالرُّطَبِ، فَسَمِنْتُ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَبِالُْجمْلَةِ: فَدَفْعُ ضَرَرِ الْبَارِدِ بِالَْحارِّ، وَالَْحارِّ بِالْبَارِدِ، وَالرُّطَبِ بِالْيَابِسِ ، وَالْيَابِسِ بِالرُّطَبِ، وَتَـعْدِيلُ أَحَدِهِاَُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'بِالْآخَرِ مِنْ أَبْـلَغِ أَنْـوَاعِ الْعِلَاجَاتِ، وَحِفْظِ الصِّحهةِ، وَنَظِيُر هَذَا مَا تَـقَدهمَ مِنْ أَمْرِهِ بِالسهنَا والسنوات، وَهُوَ الْعَسَلُ الهذِي فِيهِ شَيْ ءٌ مِنَ السهمْنِ يَصْلُحُ بِهِ السهنَا، وَيُـعْدِلُهُ، فَصَلَوَاتُ ا هلِلَّ وَسَلَامُهُ عَلَى مَنْ بُعِثَ بِعِمَارَةِ الْقُلُوبِ وَالَْأبْدَانِ، وَبَِمصَالِحِ الدنيا والآخرة.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي الِْحمْيَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'الدهوَاءُ كُلُّهُ شَيْـئَانِ: حِيَْْةٌ وَحِفْظُ صِحهةٍ. فَإِذَا وَقَعَ التهخْلِيطُ، احْتِيجَ إِلَى الِاسْتِفْرَاغِ الْمُوَافِقِ، وَكَذَلِكَ مَدَارُ الطِّبِّ كُلِّهِ عَلَى هَذِهِ الْقَوَاعِدِ الثهلَاثَةِ. وَالِْحمْيَةُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'حِيَْْـتَانِ: حِيَْْةٌ عَمها يَْجلِبُ الْمَرَضَ ، وَحِيَْْةٌ عَمها يَزِيدُهُ، فَـيَقِفُ عَلَى حَالِهِ، فَالَْأهولُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'حِيَْْةُ الَْأصِحهاءِ وَالثهانِيَةُ: حِيَْْةُ الْمَرْضَى، فَإِنه الْمَرِيضَ إِذَا احْتَمَى، وَقَفَ مَرَضُهُ عَنِ التهـزَايُدِ، وَأَخَذَتِ الْقُوَى فِي دَفْعِهِ. وَالَْأصْلُ فِي الِْحمْيَةِ قَـوْلُهُ تَـعَالَى: وَإِنْ كُنْـتُمْ مَرْضى أَوْ عَلى سَفَرٍ أَوْ جاءَ أَحَدٌ مِنْكُمْ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الْغائِطِ أَوْ لامَسْتُمُ النِّساءَ فَـلَمْ تَِدَُوا مَاءً فَـتَـيَمهمُوا صَعِيداً طَيِّباً »7« ، فَحَمَى الْمَرِيضَ مِنِ اسْتِعْمَالِ الْمَاءِ، لَِأنههُ يَضُرُّهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» وَغَيِْرهِ عَنْ أم المنذر بنت قيس الأنصارية، قَالَتْ :', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'دَخَلَ عَلَيه رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وسلم ومعه علي، وعلي نَاقِهٌ مِنْ مَرَضٍ ، وَلَنَا دَوَالِِ مُعَلهقَةٌ، فَـقَامَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كََُْلُ مِنْـهَا، وَقَامَ علي كََُْلُ مِنْـهَا، فَطَفِقَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يقول لعلي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '(7) النساء- -43 المائدة- 1', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '«إِنهكَ نَاقِهٌ» حَ هتى كَفه . قَالَتْ : وَصَنَـعْتُ شَعِيًرا وَسِلْقًا، فَجِئْتُ بِهِ، فَـقَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لعلي: «مِنْ هَذَا أَصِبْ ، فَإِنههُ أَنْـفَعُ لَكَ » وَفِي لَفْظٍ فَـقَالَ: «مِنْ هَذَا فَأَصِبْ ، فَإِنههُ أَوْفَقُ لَكَ » »7« . وَفِي «سُنَنِ ابْنِ مَاجَهْ» أَيْضًا عَنْ صهيب قَالَ: قَدِمْتُ عَلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَبَـيَْن يَدَيْهِ خُبْـزٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَتَرٌَْ، فَـقَالَ: «ادْنُ فَكُلْ» ، فَأَخَذْتُ تَرًَْا فَأَكَلْتُ ، فَـقَالَ: «أَتَكَُْلُ تَرًَْا وَبِكَ رَمَدٌ» ؟ فَـقُلْتُ : يا رسول', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'الله! أمضع مِنَ الهناحِيَةِ الُْأخْ رَى، فَـتَـبَسهمَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَ هلمَ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَفِي حَدِيثٍ مَفُُْوظٍ عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إِنه ا هللََّ إِذَا أَحَبه عَبْدًا، حَاَْهُ مِنَ الدُّنْـيَا، كَمَا يَْحمِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'أَحَدُكُمْ مَرِيضَهُ عَنِ الطهعَامِ وَالشهرَابِ» . وَفِي لَفْظٍ: «إِنه ا هللََّ يَْحمِي عَبْدَهُ الْمُؤْمِنَ مِنَ الدُّنْـيَا» » .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَأَمها الَْحدِيثُ الدهائِرُ عَلَى أَلْسِنَةِ كَثِيٍر مِنَ النهاسِ : «الِْحمْيَةُ رَأْسُ الدهوَاءِ، وَالْمَعِدَةُ بَـيْتُ الدهاءِ، وَعَوِّدُوا كُله جِسْمٍ مَا اعْتَادَ» فَـهَذَا الَْحدِيثُ إِهنَما هُوَ مِنْ كَلَامِ الحارث بن كلدة طَبِيبِ الْعَرَبِ، وَلَا يَصِحُّ رَفْـعُهُ إِلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، قَالَهُ غَيْـرُ وَاحِدٍ مِنْ أَئِمهةِ الَْحدِيثِ. وَيُذْكَرُ عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ. «أَنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'الْمَعِدَ ةَ حَوْضُ الْبَدَنِ، وَالْعُرُوقُ إِلَيْـهَا وَارِدَةٌ، فَإِذَا صَحهتِ الْمَعِدَةُ صَدَرَتِ الْعُرُوقُ بِالصِّحهةِ، وَإِذَا سَقِمَتِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'الْمَعِدَةُ، صَدَرَتِ الْعُرُوقُ بِالسُّقَمِ» »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَقَالَ الحارث: رَأْسُ الطِّبِّ الِْحمْيَةُ، وَالِْحمْيَةُ عِنْدَهُمْ لِلصهحِيحِ فِي الْمَضَ هرةِ بَِمنْزِلَةِ التهخْلِيطِ لِلْمَرِيضِ وَالنهاقِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَأَنْـفَعُ مَا تَكُونُ الِْحمْيَةُ لِلنهاقِهِ مِنَ الْمَرَضِ ، فَإِنه طَبِيعَتَهُ لََْ تَـرْجِعْ بَـعْدُ إِلَى قُـهوتَِها، وَالْقُهوةُ الَْهاضِمَةُ ضَعِيفَةٌ، وَالطهبِيعَةُ قَابِلَةٌ، وَالَْأعْضَاءُ مُسْتَعِدهةٌ، فَـتَخْلِيطُهُ يُوجِبُ انْتِكَاسَهَا، وَهُوَ أَصْعَبُ مِنِ ابْتِدَاءِ مَرَضِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَاعْلَمْ أَنه فِي مَنْعِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لعلي مِنَ الَْأكْلِ مِنَ الدهوَالِِ، وَهُوَ نَاقِهٌ أَحْسَنُ التهدْبِيِر، فَإِنه الدهوَالَِِ أَقْـنَاءٌ مِنَ الرُّطَبِ تُـعَلهقُ فِي الْبَـيْتِ لِلْكَِْلِ بَِمنْزِلَةِ عَنَاقِيدِ الْعِنَبِ، وَالْفَاكِهَةِ تَضُرُّ بِالنهاقِهِ مِنَ الْمَرَضِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'لِسُرْعَةِ اسْتِحَالَتِهَا، وَضَعْفِ الطهبِيعَةِ عَنْ دفعها،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, '(7) أخرجه ابن ماجه وأبو داود والترمذي (2) أخرجه ابن ماجه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, '(3) أخرجه أحدْ والترمذي، وصححه الحاكم، ووافقه الذهب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, '(4) ورد في كتاب ممَع الزوائد إلا أن في سنده يحيى البابلتي وهو ضعيف', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'فَإِنهـهَا لََْ تَـتَمَكهنْ بَـعْدُ مِنْ قُـهوتَِها، وَهِيَ مَشْغُولَةٌ بِدَفْعِ آثَرَِ الْعِلهةِ، وَإِزَالَتِهَا مِنَ الْبَدَنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَفِي الرُّطَبِ خَاصهةً نَـوْعُ ثِقَلٍ عَلَى الْمَعِدَةِ، فَـتَشْتَغِلُ بُِمعَالََجتِهِ وَإِصْلَاحِهِ عَمها هِيَ بِصَدَدِهِ مِنْ إِزَالَةِ بَقِيهةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'الْمَرَضِ وَآثَرَِهِ، فَإِمها أَنْ تَقِفَ تِلْكَ الْبَقِيهةُ، وَإِمها أَنْ تَـتَـزَايَدَ، فَـلَمها وُضِعَ بَـيَْن يَدَيْهِ السِّ لْقُ وَالشهعِيُر، أَمَرَهُ أَنْ يُصِيبَ مِنْهُ، فَإِنههُ مِنْ أَنْـفَعِ الَْأغْذِيَةِ لِلنهاقِهِ، فَإِنه فِي مَاءِ الشهعِيِر مِنَ التهـبِْيَدِ وَالتهـغْذِيَةِ، وَالتهـلْطِيفِ وَالتهـلْيِيِن، وَتَـقْوِيَةِ الطهبِيعَةِ مَا هُوَ أَصْلَحُ لِلنهاقِهِ، وَلَا سِيهمَا إِذَا طُبِخَ بُِأصُولِ السهلْقِ، فَـهَذَا مِنْ أَوْفَقِ الْغِذَاءِ لِمَنْ فِي مَعِدَتِهِ ضَعْفٌ ، وَلَا يَـتَـوَلهدُ عَنْهُ مِنَ الَْأخْلَاطِ مَا يَُخافُ مِنْهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَقَالَ زَيْدُ بْنُ أَسْلَمَ: حَىَْ عمر رَضِيَ ا هللَُّ عَنْهُ مَرِيضًا لَهُ، حَ هتى إِنههُ مِنْ شِدهةِ مَا حَاَْهُ كَانَ يَُمصُّ النهـوَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَبِالُْجمْلَةِ: فَالِْحمْيَةُ مِنْ أَنْـفَعِ الَْأدْوِيَةِ قَـبْلَ الدهاءِ، فَـتَمْنَعُ حُصُولَهُ، وَإِذَا حَصَلَ، فَـتَمْنَعُ تَـزَايُدَهُ وَانْتِشَارَهُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَمِمها يَـنْـبَغِي أَنْ يُـعْلَمَ أَنه كَثِيًرا مِمها يُْحمَى عَنْهُ الْعَلِيلُ وَالنهاقِهُ وَالصهحِيحُ، إِذَا اشْتَدهتِ الشههْوَةُ إِلَيْهِ، وَمَالَتْ إِلَيْهِ الطهبِيعَةُ، فَـتَـنَاوَلَ مِنْهُ الشهيْ ءَ الْيَسِيَر الهذِي لَا تَـعْجِزُ الطهبِيعَةُ عَنْ هَضْمِهِ، لََْ يَضُهرهُ تَـنَاوُلُهُ، بَلْ رُهبَما انْـتَـفَعَ بِهِ، فَإِنه الطهبِيعَةَ وَالْمَعِدَةَ تَـتَـلَقهيَانِهِ بِالْقَبُولِ وَالْمَحَبهةِ، فَـيُصْلِحَانِ مَا يُْخشَى مِنْ ضَرَرِهِ، وَقَدْ يَكُونُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'أَنْـفَعَ مِنْ تَـنَاوُلِ مَا تَكْ رَهُهُ الطهبِيعَةُ، وَتَدْفَـعُهُ مِنَ الدهوَاءِ، وَلَِهذَا أَقَـهر النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ صهيبا وَهُوَ أَرْمَدُ عَلَى تَـنَاوُلِ التهمَرَاتِ الْيَسِيَرةِ، وَعَلِمَ أَنهـهَا لَا تَضُرُّهُ، وَمِنْ هَذَا مَا يُـرْوَى عَنْ علي أَنههُ دَخَلَ عَلَيه رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَهُوَ أَرْمَدُ، وَبَـيَْن يَدَيِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ تَرٌَْ كََُْلُهُ، فَـقَالَ: يَا علي! تَشْتَهِيهِ؟ وَرَمَى إِلَيْهِ بِتَمْرَةٍ، ُ مه بُِأخْ رَى حَ هتى رَمَى إِلَيْهِ سَبْـعًا، ُ مه قَالَ: «حَسْبُكَ يَا علي» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَمِنْ هَذَا مَا رَوَاهُ ابْنُ مَاجَهْ فِي «سُنَنِهِ» مِنْ حَدِيثِ عكرمة، عَنِ ابْنِ عَبهاسٍ ، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَادَ رَجُلًا، فَـقَالَ لَهُ: «مَا تَشْتَهِي» ؟ فَـقَالَ: أَشْتَهِي خُبْـزَ بُـرٍّ. وَفِي لَفْظٍ: أَشْتَهِي كَعْكًا، فَـقَالَ النهبُِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَنْ كَانَ عِنْدَهُ خُبْـزُ بُـرٍّ فَـلْيَـبْـعَثْ إِلَى أَخِيهِ» ، ُ مه قَالَ: «إِذَا اشْتَـهَى مَرِيضُ أَحَدِكُمْ شيئا، فليطعمه» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(7) أخرجه ابن ماجه في الجنائز.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'فَفِي هَذَا الَْحدِيثِ سِرٌّ طِبٌِّّ لَطِيفٌ ، فَإِنه الْمَرِيضَ إِذَا تَـنَاوَلَ مَا يَشْتَهِيهِ عَنْ جُوعٍ صَادِقٍ طَبِيعِيٍّ ، وَكَانَ فِيهِ ضَرَرٌ مَا، كَانَ أَنْـفَعَ وَأَقَله ضَرَرًا مِمها لَا يَشْتَهِيهِ، وَإِنْ كَانَ نَافِعًا فِي نَـفْسِهِ، فَإِنه صِدْقَ شَهْوَتِهِ، وَمَبَُهةَ الطهبِيعَةِ يَدْفَعُ ضَرَرَهُ، وَبُـغْضَ الطهبِيعَةِ وَكَرَاهَتَـهَا لِلنهافِعِ، قَدْ يَْجلِبُ لََها مِنْهُ ضَرَرًا. وَبِالُْجمْلَةِ: فَاللهذِيذُ الْمُشْتَـهَى تُـقْبِلُ الطهبِيعَةُ عَلَيْهِ بِعِنَايَةٍ، فَـتَـهْضِمُهُ عَلَى أَحْدَِْ الْوُجُوهِ، سِيهمَا عِنْدَ انْبِعَاثِ النهـفْسِ إِلَيْهِ بِصِدْقِ الشههْوَةِ، وَصِحهةِ الْقُهوةِ، وَا هللَُّ أَعْلَمُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الهرمَدِ بِالسُّكُونِ، وَالدهعَةِ، وَتَـرْكِ الَْحرَكَةِ، وَالِْحمْيَةِ مِمها يَهِيجُ الهرمَدَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَقَدْ تَـقَدهمَ أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ حَىَْ صهيبا مِنَ التهمْرِ، وَأَنْكَرَ عَلَيْهِ أَكْ لَهُ، وَهُوَ أَرْمَدُ، وَحَىَْ عليا مِنَ الرُّطَبِ لَمها أَصَابَهُ الهرمَدُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وذكر أبو نعيم في كتاب «الطب النبوي» : أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ إِذَا رَمِدَتْ عَيُْن امْرَأَةٍ مِنْ نِسَائِهِ لََْ تَََِْها حَ هتى تَـبْـرَأَ عَيْـنُـهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الهرمَدُ: وَرَمٌ حَارٌّ يَـعْرِضُ فِي الطهبَـقَةِ الْمُلْتَحِمَةِ مِنَ الْعَيِْن، وَهُوَ بَـيَاضُهَا الظهاهِرُ، وَسَبَـبُهُ انْصِبَابُ أَحَدِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الَْأخْلَاطِ الَْأرْبَـعَةِ، أَوْ رِيحٌ حَارهةٌ تَكْ ثُـرُ كَمِّيهـتُـهَا فِي الهرأْسِ وَالْبَدَنِ، فَـيَـنْـبَعِثُ مِنْـهَا قِسْطٌ إِلَى جَوْهَرِ الْعَيِْن، أَوْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'ضَرْبَةٌ تُصِيبُ الْعَيَْن، فَـتُـرْسِلُ الطهبِيعَةُ إِلَيْـهَا مِنَ الدهمِ وَالرُّوحِ مِقْدَارًا كَثِيًرا، تَـرُومُ بِذَلِكَ شِفَاءَهَا مِمها عَرَضَ لََها، وَلَِأجْلِ ذَلِكَ يَرِمُ الْعُضْوَ الْمَضْرُوبَ ، وَالْقِيَاسُ يُوجِبُ ضِدههُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَاعْلَمْ أَنههُ كَمَا يَـرْتَفِعُ مِنَ الَْأرْضِ إِلَى الَْجوِّ خُاَِرَانِ ، أَحَدُهُاَُ: حَارٌّ يَابِسٌ ، وَالْآخَرُ: حَارٌّ رَطْبٌ ، فَـيَـنْـعَقِدَانِ سَحَابًا مُتَـرَاكِمًا، وَيَْمنَـعَانِ أَبْصَارَنَا مِنْ إِدْرَاكِ السهمَاءِ، فَكَذَلِكَ يَـرْتَفِعُ مِنْ قَـعْرِ الْمَعِدَةِ إِلَى مُنْـتَـهَاهَا مِثْلُ ذَلِكَ ، فَـيَمْنَـعَانِ النهظَرَ، وَيَـتَـوَلهدُ عَنْـهُمَا عِلَلٌ شَ هتى، فَإِنْ قَوِيَتِ الطهبِيعَةُ عَلَى ذَلِكَ  وَدَفَـعَتْهُ إِلَى الَْخيَاشِيمِ، أَحْدَثَ الزُّكَامَ، وَإِنْ دَفَـعَتْهُ إِلَى اللههَاةِ وَالْمَنْخِرَيْنِ أَحْدَثَ الُْخنَاقَ ، وَإِنْ دَفَـعَتْهُ إِلَى الَْجنْبِ، أَحْدَثَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الشهوْصَةَ، وَإِنْ دَفَـعَتْهُ إِلَى الصهدْرِ، أَحْدَثَ النهـزْلَةَ، وَإِنِ انْدََْرَ إِلَى الْقَلْبِ، أَحْدَثَ الَْخبْطَةَ، وَإِنْ دَفَـعَتْهُ إِلَى الْعَيِْن أَحْدَثَ رَمَدًا، وَإِنِ انْدََْرَ إِلَى الَْجوْفِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'أَحْدَثَ السهيَلَانَ، وَإِنْ دَفَـعَتْهُ إِلَى مَنَازِلِ الدِّمَاغِ أَحْدَثَ النِّسْيَانَ، وَإِنْ تَـرَطهبَتْ أَوْعِيَةُ الدِّمَاغِ مِنْهُ، وَامْتَلَتَِْ بِهِ عُرُوقُهُ أَحْدَثَ النهـوْمَ الشهدِيدَ، وَلِذَلِكَ كَانَ النهـوْمُ رَطْبًا، وَالسههَرُ يَابِسًا. وَإِنْ طَلَبَ الْبُخَارُ النُّـفُوذَ مِنَ الهرأْسِ ، فَـلَمْ يَـقْدِرْ عَلَيْهِ، أَعْقَبَهُ الصُّدَاعُ وَالسههَرُ، وَإِنْ مَالَ الْبُخَارُ إِلَى أَحَدِ شِقهيِ الهرأْسِ ، أَعْقَبَهُ الشهقِيقَةُ، وَإِنْ مَلَكَ قِمهةَ الهرأْسِ وَوَسَطَ الَْهامَةِ، أَعْقَبَهُ دَاءُ الْبَـيْضَةِ، وَإِنْ بَـرُدَ مِنْهُ حِجَابُ الدِّمَاغِ ، أَوْ سَخُنَ، أَوْ تَـرَطهبَ وَهَاجَتْ مِنْهُ أَرْيَاحٌ، أَحْدَثَ الْعُطَاسَ ، وَإِنْ أَهَاجَ الرُّطُوبَةَ الْبَـلْغَمِيهةَ فِيهِ حَ هتى غَلَبَ الَْحارُّ الْغَرِيزِيُّ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'أَحْدَثَ الِْإغْمَاءَ وَالسُّكَاتَ ، وَإِنْ أَهَاجَ الْمِ هرةَ السهوْدَاءَ حَ هتى أَظْلَمَ هَوَاءُ الدِّمَاغِ ، أَحْدَثَ الْوَسْوَاسَ ، وَإِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'فَاضَ ذَلِكَ إِلَى مََاَرِي الْعَصَبِ، أَحْدَثَ الصهرَعَ الطهبِيعِيه، وَإِنْ تَـرَطهبَتْ مََاَمِعُ عَصَبِ الهرأْسِ وَفَاضَ ذَلِكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'فِي مَاََرِيهِ، أَعْقَبَهُ الْفَالِجُ، وَإِنْ كَانَ الْبُخَارُ مِنْ مِهرةٍ صَفْرَاءَ مُلْتَهِبَةٍ مَمُِْيهةٍ لِلدِّمَاغِ ، أَحْدَثَ الْبِْسََامَ، فَإِنْ شَركَِهُ الصهدْرُ فِي ذَلِكَ ، كَانَ سِرْسَامًا، فَافْـهَمْ هَذَا الْفَصْلَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَالْمَقْصُودُ: أَنه أَخْلَاطَ الْبَدَنِ وَالهرأْسِ تَكُونُ مُتَحَرّكَِةً هَائِجَةً فِي حَالِ الهرمَدِ، وَالِْجمَاعُ مِمها يَزِيدُ حَرَكَتَـهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَثَـوَرَانَـهَا، فَإِنههُ حَرَكَةٌ كُلِّيهةٌ لِلْبَدَنِ وَالرُّوحِ وَالطهبِيعَةِ. فَأَمها الْبَدَنُ، فَـيَسْخُنُ بِالَْحرَكَةِ لَا مَاَُلَةَ، وَالنهـفْسُ تَشْتَدُّ حَرَكَتُـهَا طَلَبًا لِلهذهةِ وَاسْتِكْمَالَِها، وَالرُّوحُ تَـتَحَ هركُ تَـبَـعًا لَِحرَكَةِ النهـفْسِ وَالْبَدَنِ، فَإِنه أَهولَ تَـعَلُّقِ الرُّوحِ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'الْبَدَنِ بِالْقَلْبِ، وَمِنْهُ يَـنْشَأُ الرُّوحُ، وَتَـنْـبَثُّ فِي الَْأعْضَاءِ. وَأَمها حَرَكَةُ الطهبِيعَةِ، فَلِجَِْلِ أَنْ تُـرْسِلَ مَا يَِجبُ إِرْسَالُهُ مِنَ الْمَنِِِّ عَلَى الْمِقْدَارِ الهذِي يَِجبُ إِرْسَالُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَبِالُْجمْلَةِ: فالجماع حركة كلية عامة يتحرك فها الْبَدَنُ وَقُـوَاهُ، وَطَبِيعَتُهُ وَأَخْلَاطُهُ، وَالرُّوحُ وَالنهـفْسُ ، فَكُلُّ حَرَكَةٍ فَهِيَ مُثِيَرةٌ لِلْخَِْلَاطِ مُرَقِّقَةٌ لََها تُوجِبُ دَفْـعَهَا وَسَيَلَانَـهَا إِلَى الَْأعْضَاءِ الضهعِيفَةِ، وَالْعَيُْن فِي حَالِ رَمَدِهَا أَضْعَفُ مَا تَكُونُ، فَأَضَ هر مَا عَلَيْـهَا حَرَكَةُ الِْجمَاعِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'قَالَ بقراط فِي كِتَابِ «الْفُصُولِ» : وَقَدْ يَدُلُّ ركُُوبُ السُّفُنِ أَنه الَْحرَكَةَ تُـثَـوِّرُ الَْأبْدَانَ. هَذَا مَعَ أَنه فِي الهرمَدِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'مَنَافِعَ كَثِيَرةً، مِنْـهَا مَا يَسْتَدْعِيهِ مِنَ الِْحمْيَةِ وَالِاسْتِفْرَاغِ ، وَتَـنْقِيَةِ الهرأْسِ وَالْبَدَنِ مِنْ فَضَلَاتِِهمَا وَعُفُونَاتِِهمَا، وَالْكَفُّ عَمها يُـؤْذِي النهـفْسَ وَالْبَدَنَ مِنَ الْغَضَبِ، وَالْهمَِّ وَالُْحزْنِ، وَالَْحرَكَاتِ الْعَنِيفَةِ، وَالَْأعْمَالِ الشهاقهةِ. وَفِي أَثَرٍ سَلَفِيٍّ: لَا تَكْ رَهُوا الهرمَدَ، فَإِنههُ يَـقْطَعُ عروق العمى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَمِنْ أَسْبَابِ عِلَاجِهِ مُلَازَمَةُ السُّكُونِ وَالهراحَةِ، وَتَـرْكُ مَسه الْعَيِْن وَالِاشْتِغَالُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'بَِها، فَإِنه أَضْدَادَ ذَلِكَ يُوجِبُ انْصِبَابَ الْمَوَادِّ إِلَيْـهَا. وَقَدْ قَالَ بَـعْضُ السهلَفِ: مَثَلُ أَصْحَابِ مُمَُهدٍ مَثَلُ الْعَيِْن، وَدَوَاءُ الْعَيِْن تَـرْكُ مَسِّ هَا. وَقَدْ رُوِيَ فِي حَدِيثٍ مَرْفُوعٍ ، ا هللَُّ أَعْلَمُ بِهِ: «عِلَاجُ الهرمَدِ تَـقْطِيُر الْمَاءِ الْبَارِدِ فِي الْعَيِْن» وَهُوَ مِنْ أَنْـفَعِ الَْأدْوِيَةِ لِلهرمَدِ الَْحارِّ، فَإِنه الْمَ اءَ دَوَاءٌ بَارِدٌ يُسْتَـعَانُ بِهِ عَلَى إِطْفَاءِ حَرَارَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'الهرمَدِ إِذَا كَانَ حَارًّا، وَلَِهذَا قَالَ عَبْدُ ا هلِلَّ بْنُ مَسْعُودٍ رَضِيَ ا هللَُّ عَنْهُ لِامْرَأَتِهِ زينب وَقَدِ اشْتَكَتْ عَيْـنُـهَا: لَوْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'فَـعَلْتِ كَمَا فَـعَلَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ خَيْـرًا لَكِ وَأَجْدَرَ أَنْ تُشْفِي، تَـنْضَحِيَن فِي عَيْنِكِ الْمَاءَ، ُ مه تَـقُولِيَن: «أَذْهِبِ الْبَأْسَ رَبه النهاسِ ، وَاشْفِ أَنْتَ الشهافِي، لَا شِفَاءَ إِهلا شِفَاؤُكَ، شِفَاءً لَا يُـغَادِرُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'سَقَمًا» »7« . وَهَذَا مِمها تَـقَدهمَ مِرَارًا أَنههُ خَاصٌّ بِبَـعْضِ الْبِلَادِ، وَبَـعْضِ أَوْجَاعِ الْعَيِْن، فَلَا يُْجعَلُ كَلَامُ النُّـبُـهوةِ الُْجزْئِيُّ الَْخاصُّ كُلِّيًّا عَامًّا، وَلَا الْكُلِّيُّ الْعَامُّ جُزْئِيًّا خَاصًّا، فَـيَـقَعُ مِنَ الَْخطَأِ، وَخِلَافُ الصهوَابِ مَا يَـقَعُ، وَا هللَُّ أَعْلَمُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الَْخدَرَانِ الْكُلِّيِّ الهذِي يَْجمُدُ مَعَهُ الْبَدَنُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'ذكََرَ أبو عبيد فِي «غَرِيبِ الَْحدِيثِ» مِنْ حَدِيثِ أَبِي عُثْمَانَ النهـهْدِيِّ : أَنه قَـوْمًا مَرُّوا بِشَجَرَةٍ فَأَكَلُوا مِنْـهَا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'فَكَأَهنَما مَ هرتْ بِِهمْ رِيحٌ، فَأَجْدَََتْـهُمْ، فَـقَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '«قَـرِّسُوا الْمَاءَ فِي الشِّ نَانِ، وَصُبُّوا عَلَيْهِمْ فِيمَا بَـيَْن الَْأذَانَـيِْن» ، ُ مه قَالَ أبو عبيد:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'قَـرِّسُوا: يَـعْنِِ بَـرِّدُوا. وَقَـوْلُ النهاسِ : قَدْ قَـرَسَ الْبَـرْدُ، إِهنَما هُوَ مِنْ هَذَا بِالسِّ يِن لَيْسَ بِالصهادِ. وَالشِّ نَانُ: الَْأسْقِيَةُ وَالْقِرَبُ الُْخلْقَانِ، يُـقَالُ لِلسِّ قَاءِ: شَنٌّ، وَلِلْقِرْبَةِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'شَنهةٌ. وَإِهنَما ذكََرَ الشِّ نَانَ دُونَ الُْجدُدِ لَِأنهـهَا أَشَدُّ تَـبِْيَدًا لِلْمَاءِ. وَقَـوْلُهُ: «بَـيَْن الَْأذَانَـيِْن» ، يَـعْنِِ أَذَانَ الْفَجْرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَالِْإقَامَةَ، فَسَمهى الِْإقَامَةَ أَذَانًا، انْـتَـهَى كَلَامُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'قَالَ بَـعْضُ الَْأطِهباءِ: وَهَذَا الْعِلَاجُ مِنَ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مِنْ أَفْضَلِ عِلَاجِ هَذَا الدهاءِ إِذَا كَانَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وُقُوعُهُ بِالِْحجَازِ، وَهِيَ بِلَادٌ حَارهةٌ يَابِسَةٌ، وَالَْحارُّ الْغَرِيزِيُّ ضعيف في بواطن (7) أخرجه ابن ماجه وأبو داود', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'سُكهانَِها، وَصَبُّ الْمَاءِ الْبَارِدِ عَلَيْهِمْ فِي الْوَقْتِ الْمَذْكُورِ، - وَهُوَ أَبْـرَدُ أَوْقَاتِ الْيَـوْمَ- يُوجِبُ جَعََْ الَْحارِّ الْغَرِيزِيِّ الْمُنْـتَشِرِ فِي الْبَدَنِ الَْحامِلِ لَِجمِيعِ قُـوَاهُ، فَـيُـقَوِّي الْقُهوةَ الدهافِعَةَ، وَيَْجتَمِعُ مِنْ أَقْطَارِ الْبَدَنِ إِلَى بَاطِنِهِ الهذِي هُوَ مَلَُُّ ذَاكَ الدهاءِ، وَيَسْتَظْهِرُ بِبَاقِي الْقُوَى عَلَى دَفْعِ الْمَرَضِ الْمَذْكُورِ، فَـيَدْفَـعُهُ بِِإذْنِ ا هلِلَّ عَهز', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَجَله، وَلَوْ أَنه بقراط، أَوْ جالينوس، أَوْ غَيْـرَهُاَُ، وَصَفَ هذا الدواء لهذا الداء، لخصعت لَهُ الَْأطِبهاءُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَعَجِبُوا مِنْ كَمَالِ مَعْرِفَتِهِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي إِصْلَاحِ الطهعَامِ الهذِي يَـقَعُ فِيهِ الذُّبَابُ ، وَإِرْشَادِهِ إِلَى دَفْعِ مَضَ هراتِ السُّمُومِ بَِأضْدَادِهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'فِي «الصهحِيحَيِْن» مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ: «إِذَا وَقَعَ الذُّبَابُ فِي إِنَاءِ أَحَدِكُمْ، فَامْقُلُوهُ، فَإِنه فِي أَحَدِ جَنَاحَيْهِ دَاءً، وَفِي الْآخَرِ شِفَاءً» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» عَنْ أَبِي سَعِيدٍ الُْخدْرِيِّ ، أن رسول الله هللا ىلص قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '«أَحَدُ جَنَاحَيِ الذُّبَابِ سُمٌّ، وَالْآخَرُ شِفَاءٌ، فَإِذَا وَقَعَ فِي الطهعَامِ، فَامْقُلُوهُ، فَإِنههُ يُـقَدِّمُ السُّمه، وَيُـؤَخِّرُ الشِّ فَاءَ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'هَذَا الَْحدِيثُ فِيهِ أَمْرَانِ: أَمْرٌ فِقْهِيٌّ، وَأَمْرٌ طِبٌِّّ، فَأَمها الْفِقْهِيُّ، فَـهُوَ دَلِيلٌ ظَاهِرُ الدهلَالَةِ جِدًّا عَلَى أَنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الذُّبَابَ إِذَا مَاتَ فِي مَاءٍ أَوْ مَائِعٍ، فَإِنههُ لَا يُـنَجِّ سُهُ، وَهَذَا قَـوْلُ جُهَُْورِ الْعُلَمَاءِ، وَلَا يُـعْرَفُ فِي السهلَفِ مَُخالِفٌ فِي ذَلِكَ . وَوَجْ هُ الِاسْتِدْلَالِ بِهِ أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَمَرَ بَِمقْلِهِ، وَهُوَ غَمْسُهُ فِي الطهعَامِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَمَعْلُومٌ أَنههُ يَُموتُ مِنْ ذَلِكَ ، وَلَا سِيهمَا إِذَا كَانَ الطهعَامُ حَارًّا. فَـلَوْ كَانَ يُـنَجِّسُهُ لَكَانَ أَمْرًا بِِإفْسَادِ الطهعَامِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَهُوَ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إِهنَما أَمَرَ بِِإصْلَاحِهِ، ُ مه عُدِّيَ هَذَا الُْحكْمُ إِلَى كُلِّ مَا لَا نَـفْسَ لَهُ سَائِلَةٌ، كَالنهحْلَةِ وَالزُّنْـبُورِ، وَالْعَنْكَبُوتِ وَأَشْبَاهِ ذَلِكَ ، إِذِ الُْحكْمُ يَـعُمُّ بِعُمُومِ عِلهتِهِ، وَيَـنْـتَفِي لِانْتِفَاءِ سببه، فلما', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(7) أخرجه البخاري وأبو داود في الطب (2) أخرجه ابن ماجه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'كَانَ سَبَبُ التهـنْجِيسِ هُوَ الدهمُ الْمُحْتَقِنُ فِي الَْحيَـوَانِ بَِموْتِهِ، وَكَانَ ذَلِكَ مَفْقُودًا فِيمَا لَا دَمَ لَهُ سَائِلٌ انْـتَـفَى الُْحكْمُ بِالتهـنْجِيسِ لِانْتِفَاءِ عِلهتِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'ُ مه قَالَ مَنْ لََْ يَْحكُمْ بِنَجَاسَةِ عَظْمِ الْمَيْـتَةِ: إِذَا كَانَ هَذَا ثَبَِتًا فِي الَْحيَـوَانِ الْكَامِلِ مَعَ مَا فِيهِ مِنَ الرُّطُوبَاتِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَالْفَضَلَاتِ، وَعَدَمِ الصهلَابَةِ، فَـثُـبُوتُهُ فِي الْعَظْمِ الهذِي هُوَ أَبْـعَدُ عَنِ الرُّطُوبَاتِ وَالْفَضَلَاتِ، وَاحْتِقَانِ الدهمِ أَوْلَى، وَهَذَا فِي غَايَةِ الْقُهوةِ، فَالْمَصِيُر إِلَيْهِ أَوْلَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَأَهولُ مَنْ حُفِظَ عَنْهُ فِي الِْإسْلَامِ أَنههُ تَكَلهمَ بَِهذِهِ اللهفْظَةِ، فَـقَالَ: مَا لَا نَـفْسَ لَهُ سَائِلَةٌ، إِبْـرَاهِيمُ النهخَعِيُّ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَعَنْهُ تَـلَقهاهَا الْفُقَهَاءُ- وَالنهـفْسُ فِي اللُّغَةِ: يُـعَبهـرُ بَِها عَنِ الدهمِ، وَمِنْهُ نَـفَسَتِ الْمَرْأَةُ- بِفَتْحِ النُّونِ- إِذَا حَاضَتْ ، وَنُفِسَتْ - بِضَمِّهَا- إِذَا وَلَدَتْ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَأَمها الْمَعْنَى الطِّبُِّّ، فَـقَالَ أبو عبيد: مَعْنَى امْقُلُوهُ: اغْمِسُوهُ ليخرج الشفاء بضمها مِنْهُ، كَمَا خَرَجَ الدهاءُ، يُـقَالُ لِلهرجُلَيِْن: هُاَُ يَـتَمَاقَلَانِ، إِذَا تَـغَاطها فِي الْمَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَاعْلَمْ أَنه فِي الذُّبَابِ عِنْدَهُمْ قُـهوةً سُِّميهةً يَدُلُّ عَلَيْـهَا الْوَرَمُ، وَالِْحكهةُ الْعَارِضَةُ عَنْ لَسْ عِهِ، وَهِيَ بَِمنْزِلَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'السِّ لَاحِ، فَإِذَا سَقَطَ فِيمَا يُـؤْذِيهِ، اتهـقَاهُ بِسِلَاحِهِ، فَأَمَرَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنْ يُـقَابِلَ تِلْكَ السُّمِّيهةَ بَِما أَوْدَعَهُ ا هللَُّ سُبْحَانَهُ فِي جَنَاحِهِ الْآخَرِ مِنَ الشِّ فَاءِ، فَـيُـغْمَسُ كُلُّهُ فِي الْمَاءِ وَالطهعَامِ، فَـيُـقَابِلُ الْمَادهةَ السُّمِّيهةَ الْمَ ادهةُ النهافِعَةُ، فَـيَـزُولُ ضَرَرُهَا، وَهَذَا طِبٌّ لَا يَـهْتَدِي إِلَيْهِ كِبَارُ الَْأطِبهاءِ وَأَئِمهتُـهُمْ، بَلْ هُوَ خَارِجٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'مِنْ مِشْكَاةِ النُّـبُـهوةِ، وَمَعَ هَذَا فَالطهبِيبُ الْعَالَُِ الْعَارِفُ الْمُوَفهقُ يَْخضَعُ لَِهذَا الْعِلَاجِ، وَيُقِرُّ لِمَنْ جَاءَ بِهِ بَِأنههُ أَكْمَلُ الَْخلْقِ عَلَى الِْإطْلَاقِ، وَأَنههُ مُؤَيهدٌ بِوَحْيٍ إِلَِهيٍّ خَارِجٍ عَنِ الْقُوَى الْبَشَرِيهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَقَدْ ذكََرَ غَيْـرُ وَاحِدٍ مِنَ الَْأطِبهاءِ أَنه لَسْعَ الزُّنْـبُورِ وَالْعَقْرَبِ إِذَا دُلِكَ مَوْضِ عُهُ بِالذُّبَابِ نَـفَعَ مِنْهُ نَـفْعًا بَـيِّنًا، وَسَكهنَهُ، وَمَا ذَاكَ إِهلا لِلْمَادهةِ الهتِي فِيهِ مِنَ الشِّ فَاءِ، وَإِذَا دُلِكَ بِهِ الْوَرَمُ الهذِي يَْخرُجُ فِي شعر العين المسمى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'شعرة بعد قطع رؤوس الذباب، أبرأه.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الْبَـثْـرَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'ذكََرَ ابْنُ السُّنِِِّّ فِي كِتَابِهِ عَنْ بَـعْضِ أَزْوَاجِ النهبِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَتْ : دَخَلَ عَلَيه رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَقَدْ خَرَجَ فِي أُصْبُعِي بَـثْـرَةٌ، فَـقَالَ: «عِنْدَكِ ذَرِيرَةٌ؟ قُـلْتُ : نَـعَمْ. قال:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '«ضَعِيهَا عَلَيْـهَا» وَقُولِِ: اللههُمه مُصَغِّرَ الْكَبِيِر، وَمُكَبََِّ الصهغِيِر، صَغِّرْ مَا بِي» »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الذهرِيرَةُ: دَوَاءٌ هِنْدِيٌّ يُـتهخَذُ مِنْ قَصَبِ الذهرِيرَةِ، وَهِيَ حَارهةٌ يَابِسَةٌ تَـنْـفَعُ مِنْ أَوْرَامِ الْمَعِدَةِ وَالْكَبِدِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَالِاسْتِسْقَاءِ، وَتُـقَوِّي الْقَلْبَ  لِطِيبِهَا، وَفِي «الصهحِيحَيِْن» عَنْ  عائشة أَنهـهَا قَالَتْ : طَيهـبْتُ  رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بِيَدِي بِذَرِيرَةٍ فِي حَجهةِ الْوَدَاعِ لِلْحِلِّ وَالِْإحْ رَامِ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَالْبَـثْـرَةُ: خُ هراجٌ صَغِيٌر يَكُونُ عَنْ مَادهةٍ حَارهةٍ تَدْفَـعُهَا الطهبِيعَةُ، فَـتَسْتَِرقُ مَكَانًا مِنَ الَْجسَدِ تَْخرُجُ مِنْهُ، فَهِيَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'مُتَُْاجَةٌ إِلَى مَا يُـنْضِجُهَا وَيُْخرِجُهَا، وَالذهرِيرَةُ أَحَدُ مَا يُـفْعَلُ بَِها ذَلِكَ ، فَإِنه فِيهَا إِنْضَاجًا وَإِخْ رَاجًا مَعَ طِيبِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'رَائِحَتِهَا، مَعَ أَنه فِيهَا تَـبِْيَدًا لِلهنارِيهةِ اهلتِي فِي تِلْكَ الْمَادهةِ، وَكَذَلِكَ قَالَ صَاحِبُ «الْقَانُونِ» : إِنههُ لَا أَفْضَلَ لَِحرْقِ الهنارِ مِنَ الذهرِيرَةِ بِدُهْنِ الورد والخل.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ في علاج الأورام، والخراجات الهتِي تَـبْـرَأُ بِالْبَطِّ وَالْبَـزْلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'يُذْكَرُ عَنْ علي أَنههُ قَالَ: دَخَلْتُ مَعَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَلَى رَجُلٍ يَـعُودُهُ بِظَهْرِهِ وَرَمٌ، فَـقَالُوا: يَا رَسُولَ ا هلِلَّ! بَِهذِهِ مِدهةٌ. قَالَ: «بُطُّوا عَنْهُ» ، قَالَ علي: فَمَا بَرِحْتُ حَ هتى بُطهتْ ، وَالنهبُِّ صَلهى ا هللَُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'عَلَيْهِ وَسَلهمَ شَاهِدٌ »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَيُذْكَرُ عَنْ أَبِي هُرَيْـرَةَ، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَمَرَ طَبِيبًا أَنْ يَـبُطه بَطْنَ رَجُلٍ أَجْ وَى الْبَطْنِ، فَقِيلَ: يَا رَسُولَ ا هلِلَّ: هَلْ يَـنْـفَعُ الطِّبُّ؟ قَالَ: «الهذِي أَنْـزَلَ الدهاءَ، أَنْـزَلَ الشِّ فَاءَ، فِيمَا شَاءَ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الْوَرَمُ: مَادهةٌ فِي حَجْمِ الْعُضْوِ لِفَضْلِ مَادهةٍ غَيِْر طبيعية تنصب اليه، ويوجد في', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(7) أخرجه ابن السنِ وأحدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(2) أخرجه البخاري في اللباس، ومسلم في الحج، والإمام أحدْ (3) أخرجه أبو يعلى: وفي سنده أبو الربيع السمان وهو ضعيف', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'أَجْنَاسِ الَْأمْرَاضِ كُلِّهَا، وَالْمَوَادُّ الهتِي تَكَ هونَ عَنْـهَا مِنَ الَْأخْلَاطِ الَْأرْبَـعَةِ، وَالْمَائِيهةِ، وَالرِّيحِ، وَإِذَا اجْتَمَعَ الْوَرَمُ سُِّميَ خُ هراجًا، وَكُلُّ وَرَمٍ حَارٍّ يَـؤُولُ أَمْرُهُ إِلَى أَحَدِ ثَلَاثَةِ أَشْيَاءَ: إِمها تَلََُّلٍ، وَإِمها جَعَِْ مِدهةٍ، وَإِمها اسْتِحَالَةٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'إِلَى الصهلَابَةِ. فَإِنْ كَانَتِ الْقُهوةُ قَوِيهةً، اسْتَـوْلَتْ عَلَى مَادهةِ الْوَرَمِ وَحَلهلَتْهُ، وَهِيَ أَصْلَحُ الَْحالَاتِ الهتِي يَـؤُولُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'حَالُ الْوَرَمِ إِلَيْـهَا، وَإِنْ كَانَتْ دُونَ ذَلِكَ ، أَنْضَجَتِ الْمَادهةَ، وَأَحَالَتْـهَا مِدهةً بَـيْضَاءَ، وَفَـتَحَتْ لََها مَكَانًا أَسَالَتْـهَا مِنْهُ. وَإِنْ نَـقَصَتْ  عَنْ ذَلِكَ  أَحَالَتِ الْمَادهةَ مِدهةً غَيْـرَ مُسْتَحْكِمَةِ النُّضْجِ، وَعَجَزَتْ  عَنْ فَـتْحِ مَكَانٍ فِي الْعُضْوِ تَدْفَـعُهَا مِنْهُ، فَـيُخَافُ عَلَى الْعُضْوِ الْفَسَادَ بِطُولِ لُبْثِهَا فِيهِ، فَـيَحْ تَاجُ حِينَئِذٍ إِلَى إِعَانَةِ الطهبِيبِ بِالْبَطِّ ، أَوْ غَيِْرهِ لِِإخْ رَاجِ تِلْكَ الْمَادهةِ الهردِيئَةِ الْمُفْسِدَةِ لِلْعُضْوِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَفِي الْبَطِّ فَائِدَتَانِ: إِحْدَاهُاَُ: إِخْرَاجُ الْمَادهةِ الهردِيئَةِ الْمُفْسِدَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَالثهانِيَةُ: مَنْعُ اجْ تِمَاعِ مَادهةٍ أُخْ رَى إِلَيْـهَا تُـقَوِّيهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَأَمها قَـوْلُهُ فِي الَْحدِيثِ الثهانِي: «إِنههُ أَمَرَ طَبِيبًا أَنْ يَـبُطه بَطْنَ رَجُلٍ أَجْ وَى الْبَطْنِ» ، فَالَْجوَى يُـقَالُ عَلَى مَعَانٍ مِنْـهَا: الْمَاءُ الْمُنْتُُِ الهذِي يَكُونُ فِي الْبَطْنِ يَْحدُثُ عَنْهُ الِاسْتِسْقَاءُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَقَدِ اخْ تَـلَفَ الَْأطِبهاءُ فِي بَـزْلِهِ لُِخرُوجِ هَذِهِ الْمَادهةِ، فَمَنَـعَتْهُ طَائِفَةٌ مِنْـهُمْ لَِخطَرِهِ، وَبُـعْدِ السهلَامَةِ مَعَهُ، وَجَ هوزَتْهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'طَائِفَةٌ أُخْ رَى، وَقَالَتْ : لَا عِلَاجَ لَهُ سِوَاهُ، وَهَذَا عِنْدَهُمْ إِهنَما هُوَ فِي الِاسْتِسْقَاءِ الزِّقِّيِّ، فَإِنههُ كَمَا تَـقَدهمَ ثَلَاثَةُ أَنْـوَاعٍ : طَبْلِيٌّ، وَهُوَ الهذِي يَـنْـتَفِخُ مَعَهُ الْبَطْنُ بَِمادهةٍ رِيِحيهةٍ إِذَا ضَرَبْتَ عَلَيْهِ سُِمعَ لَهُ صَوْتٌ كَصَوْتِ الطهبْلِ، وَلَْحمِيٌّ: وَهُوَ الهذِي يَـرْبُو مَعَهُ لَْحمُ جَِيَعِ الْبَدَنِ بَِمادهةٍ بَـلْغَمِيهةٍ تَـفْشُو مَعَ الدهمِ فِي الَْأعْضَاءِ، وَهُوَ أَصْعَبُ مِنَ الَْأهولِ، وَزِقِّيٌّ: وَهُوَ الهذِي يَْجتَمِعُ مَعَهُ فِي الْبَطْنِ الَْأسْفَلِ مَادهةٌ رَدِيئَةٌ يُسْمَعُ لََها عِنْدَ الَْحرَكَةِ خَضْخَضَةٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'كَخَضْخَضَةِ الْمَاءِ فِي الزِّقِّ ، وَهُوَ أَرْدَأُ أَنْـوَاعِهِ عِنْدَ الَْأكْ ثَرِينَ مِنَ الَْأطِبهاءِ. وَقَالَتْ طَائِفَةٌ: أَرْدَأُ أَنْـوَاعِهِ اللهحْمِيُّ لِعُمُومِ الْآفَةِ بِهِ. وَمِنْ جُلََْةِ عِلَاجِ الزِّقِّيِّ إِخْرَاجُ ذَلِكَ بِالْبَـزْلِ وَيَكُونُ ذَلِكَ بَِمنْزِلَةِ فَصْدِ الْعُرُوقِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'لِِإخْ رَاجِ الدهمِ الْفَاسِدِ، لَكِنههُ خَطَرٌ كَمَا تَـقَدهمَ، وَإِنْ ثَـبَتَ هَذَا الَْحدِيثُ ، فَـهُوَ دَلِيلٌ عَلَى جَوَازِ بَـزْلِهِ، والله أعلم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الْمَرْضَى بِتَطْيِيبِ نُـفُوسِهِمْ وَتَـقْوِيَةِ قُـلُوبِِهمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى ابْنُ مَاجَهْ «فِي سُنَنِهِ» مِنْ حَدِيثِ أَبِي سَعِيدٍ الُْخدْرِيِّ ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '«إِذَا دَخَلْتُمْ عَلَى الْمَرِيضِ ، فَـنَـفِّسُوا لَهُ فِي الَْأجَلِ، فَإِنه ذَلِكَ لَا يَـرُدُّ شَيْـئًا، وَهُوَ يُطَيِّبُ نَـفْسَ الْمَرِيضِ »', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '. »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَفِي هَذَا الَْحدِيثِ نَـوْعٌ شَرِيفٌ جِدًّا مِنْ أَشْرَفِ أَنْـوَاعِ الْعِلَاجِ، وَهُوَ الِْإرْشَادُ إِلَى مَا يُطَيِّبُ نَـفْسَ الْعَلِيلِ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الْكَلَامِ الهذِي تَـقْوَى بِهِ الطهبِيعَةُ، وَتَـنْـتَعِشُ بِهِ الْقُهوةُ، وَيَـنْـبَعِثُ بِهِ الَْحارُّ الْغَرِيزِيُّ، فَـيَـتَسَاعَدُ عَلَى دَفْعِ الْعِلهةِ أَوْ تَْخفِيفِهَا الهذِي هُوَ غَايَةُ تَثَِْيِر الطهبِيبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَتَـفْرِيحُ نَـفْسِ الْمَرِيضِ ، وَتَطْيِيبُ قَـلْبِهِ، وَإِدْخَالُ مَا يَسُرُّهُ عَلَيْهِ، لَهُ تَثَِْيٌر عَجِيبٌ فِي شِفَاءِ عِلهتِهِ وَخِهفتِهَا، فَإِنه الَْأرْوَاحَ وَالْقُوَى تَـقْوَى بِذَلِكَ ، فَـتُسَاعِدُ الطهبِيعَةَ عَلَى دَفْعِ الْمُؤْذِي، وَقَدْ شَاهَدَ النهاسُ كَثِيًرا مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الْمَرْضَى تَـنْـتَعِشُ قُـوَاهُ بِعِيَادَةِ مَنْ يُِحبُّونَهُ، وَيُـعَظِّمُونَهُ، وَرُؤْيَتِهِمْ لَهمُْ، وَلُطْفِهِمْ بِِهمْ، وَمُكَالَمَتِهِمْ إِهياهُمْ، وَهَذَا أَحَدُ فَـوَائِدِ عِيَادَةِ الْمَرْضَى الهتِي تَـتَـعَلهقُ بِِهمْ، فَإِنه فِيهَا أَرْبَـعَةَ أَنْـوَاعٍ مِنَ الْفَوَائِدِ: نَـوْعٌ يَـرْجِعُ إِلَى الْمَرِيضِ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَنَـوْعٌ يَـعُودُ عَلَى الْعَائِدِ، وَنَـوْعٌ يَـعُودُ عَلَى أَهْلِ الْمَرِيضِ ، وَنَـوْعٌ يَـعُودُ عَلَى الْعَامهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَقَدْ تَـقَدهمَ فِي هَدْيِهِ صَلَى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ كَانَ يَسْأَلُ الْمَرِيضَ عَنْ شَكْ وَاهُ، وَكَيْفَ يَِجدُهُ وَيَسْأَلُهُ عَمها يَشْتَهِيهِ، وَيَضَعُ يَدَهُ عَلَى جَبْـهَتِهِ، وَرُهبَما وَضَعَهَا بَـيَْن ثَدْيَـيْهِ، وَيَدْعُو لَهُ، وَيَصِفُ لَهُ مَا يَـنْـفَعُهُ فِي عِلهتِهِ، وَرُهبَما تَـوَضهأَ وَصَبه عَلَى الْمَرِيضِ مِنْ وَضُوئِهِ، وَرُهبَما كَانَ يَـقُولُ لِلْمَرِيضِ : «لَا بَْأسَ طَهُورٌ إِنْ شَاءَ ا هللَُّ» »2« ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَهَذَا مِنْ كَمَالِ اللُّطْفِ ، وَحُسْنِ الْعِلَاجِ وَالتهدْبِيِر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, '(7) أخرجه الترمذي في الطب، وابن ماجه في الجنائز. ومعنى «فنفسوا له في الأجل» أي وسعوا له وأطمعوه في طول الحياة، وأذهبوا حزنه فيما يتعلق بأجله، بأن تقولوا: لا بأس، طهور، فإن في ذلك تنفيسا لما هو فيه من الكرب وطمأنينة لقلبه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '(2) أخرجه البخاري', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الَْأبْدَانِ بَِما اعْتَادَتْهُ مِنَ الَْأدْوِيَةِ وَالَْأغْذِيَةِ دُونَ مَا لََْ تَـعْتَدْهُ هَذَا أَصْلٌ عَظِيمٌ مِنْ أُصُولِ الْعِلَاجِ، وَأَنْـفَعُ شَيْ ءٍ فِيهِ، وَإِذَا أَخْطَأَهُ الطهبِيبُ ، أَضَ هر الْمَرِيضَ مِنْ حَيْثُ يَظُنُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'أَنههُ يَـنْـفَعُهُ، وَلَا يَـعْدِلُ عَنْهُ إِلَى مَا يَِجدُهُ مِنَ الَْأدْوِيَةِ فِي كُتُبِ الطِّبِّ إِهلا طَبِيبٌ جَاهِلٌ، فَإِنه مُلَاءَمَةَ الَْأدْوِيَةِ وَالَْأغْذِيَةِ لِلْبَِْدَانِ بَِحسَبِ اسْتِعْدَادِهَا وَقَـبُولَِها، وَهَؤُلَاءِ أَهْلُ الْبَـوَادِي وَالَْأكهارُونَ وَغَيْـرُهُمْ لَا يَـنْجَعُ فِيهِمْ شَرَابُ اللِّينُوفَرِ وَالْوَرْدِ الطهرِيِّ وَلَا الْمَغْلِيِّ، وَلَا يُـؤَثِّرُ فِي طِبَاعِهِمْ شَيْـئًا، بَلْ عَامهةُ أَدْوِيَةِ أَهْلِ الَْحضَرِ وأهل الرفاهية لا تدَي عليهم، وَالتهجْرِبَةُ شَاهِدَةٌ بِذَلِكَ ، وَمَنْ تَمََهلَ مَا ذكََرْنَاهُ مِنَ الْعِلَاجِ النهـبَوِيِّ ، رَآهُ كُلههُ مُوَافِقًا لِعَادَةِ الْعَلِيلِ وَأَرْضِهِ، وَمَا نَشَأَ عَلَيْهِ. فَـهَذَا أَصْلٌ عَظِيمٌ مِنْ أُصُولِ الْعِلَاجِ يَِجبُ الِاعْتِنَاءُ بِهِ، وَقَدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'صَ هرحَ بِهِ أَفَاضِلُ أَهْلِ الطِّبِّ حَ هتى قَالَ طَبِيبُ الْعَرَبِ بَلْ أَطَبُّـهُمُ الحارث بن كلدة، وَكَانَ فِيهِمْ كأبقراط فِي قَـوْمِهِ: الِْحمْيَةُ رَأْسُ الدهوَاءِ، وَالْمَعِدَةُ بَـيْتُ الدهاءِ، وَعَوِّدُوا كُله بَدَنٍ مَا اعْتَادَ. وَفِي لَفْظٍ عَنْهُ: الَْأزْمُ دَوَاءٌ، وَالَْأزْمُ: الِْإمْسَاكُ عَنِ الَْأكْلِ يَـعْنِِ بِهِ الُْجوعَ، وَهُوَ مِنْ أَكْ بََِ الَْأدْوِيَةِ فِي شِفَاءِ الَْأمْرَاضِ الِامْتِلَائِيهةِ كُلِّهَا بَِحيْثُ إِنههُ أَفْضَلُ فِي عِلَاجِهَا مِنَ الْمُسْتَـفْرِغَاتِ إِذَا لََْ يَِخفه مِنْ كَثْـرَةِ الِامْتِلَاءِ، وَهَيَجَانِ الَْأخْلَاطِ، وَحِدهتَِها أَوْ غَلَيَانَِها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَقَـوْلُهُ: الْمَعِدَةُ بَـيْتُ الدهاءِ. الْمَعِدَةُ: عُضْوٌ عَصَبٌِّ مُهََوفٌ كَالْقَرْعَةِ فِي شَكْ لِهَا، مُرَكهبٌ مِنْ ثَلَاثِ طَبَـقَاتٍ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'مُؤَلهفَةٍ مِنْ شَظَايَا دَقِيقَةٍ عَصَبِيهةٍ تُسَمهى اللِّيفَ ، وَيُِحيطُ بَِها لَْحمٌ، وَلِيفٌ إِحْدَى الطهبَـقَاتِ بِالطُّولِ، وَالُْأخْرَى بِالْعَرْضِ ، وَالثهالِثَةُ بِالْوَرْبِ، وَفَمُ الْمَعِدَةِ أَكْ ثَـرُ عَصَبًا، وَقَـعْرُهَا أَكْ ثَـرُ لَْحمًا، وَفِي بَاطِنِهَا خَْملٌ، وَهِيَ مَصُُْورَةٌ فِي وَسَطِ الْبَطْنِ، وَأَمْيَلُ إِلَى الَْجانِبِ الَْأيَْمنِ قَلِيلًا، خُلِقَتْ عَلَى هَذِهِ الصِّفَةِ لِِحكْمَةٍ لَطِيفَةٍ مِنَ الَْخالِقِ الَْحكِيمِ سُبْحَانَهُ، وَهِيَ بَـيْتُ الدهاءِ، وَكَانَتْ مَلًَُّا لِلْهَضْمِ الَْأهولِ، وَفِيهَا يَـنْضَجُ الْغِذَاءُ وَيَـنْحَدِرُ مِنْـهَا بَـعْدَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'ذَلِكَ إِلَى الْكَبِدِ وَالَْأمْعَاءِ، وَيَـتَخَلهفُ مِنْهُ فِيهَا فَضَلَاتٌ قَدْ عَجَزَتِ الْقُهوةُ الْهاَضِمَةُ عَنْ تَاََمِ هَضْمِهَا، إِمها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'لِكَثْـرَةِ الْغِذَاءِ، أَوْ لِرَدَاءَتِهِ، أَوْ لِسُوءِ تَـرْتِيبٍ فِي اسْتِعْمَالِهِ، أَوْ لِمَجْمُوعِ ذَلِكَ ، وَهَذِهِ الَْأشْيَاءُ بَـعْضُهَا مِمها لَا يَـتَخَلهصُ الِْإنْسَانُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'مِنْهُ غَالِبًا، فَـتَكُونُ الْمَعِدَةُ بَـيْتَ الدهاءِ لِذَلِكَ ، وَكَأَنههُ يُشِيُر بِذَلِكَ إِلَى الَْحثِّ عَلَى تَـقْلِيلِ الْغِذَاءِ، وَمَنْعِ النهـفْسِ مِنِ اتِّبَاعِ الشههَوَاتِ، وَالتهحَرُّزِ عَنِ الْفَضَلَاتِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَأَمها الْعَادَةُ فَلِنَِهـهَا كَالطهبِيعَةِ لِلِْنْْسَانِ، وَلِذَلِكَ يُـقَالُ: الْعَادَةُ طَبْعٌ ثَنٍَ، وَهِيَ قُـهوةٌ عَظِيمَةٌ فِي الْبَدَنِ، حَ هتى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'إِنه أَمْرًا وَاحِدًا إِذَا قِيسَ إِلَى أَبْدَانٍ مُْختَلِفَةِ الْعَادَاتِ، كَانَ مُْختَلِفَ النِّسْبَةِ إِلَيْـهَا. وَإِنْ كَانَتْ تِلْكَ الَْأبْدَانُ مُتهفِقَةً فِي الْوُجُوهِ الُْأخْ رَى مِثَالُ ذَلِكَ أَبْدَانٌ ثَلَاثَةٌ حَارهةُ الْمِزَاجِ فِي سِنِّ الشهبَابِ، أَحَدُهَا: عُوِّدُ تَـنَاوُلَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'الَْأشْيَاءِ الَْحارهةِ؛ وَالثهانِي: عُوِّدُ تَـنَاوُلَ الَْأشْيَاءِ الْبَارِدَةِ، وَالثهالِثُ : عُوِّدَ تَـنَاوُلَ الَْأشْيَاءِ الْمُتَـوَسِّطَةِ، فَإِنه الَْأهولَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'مَتَى تَـنَاوَلَ عَسَلًا لََْ يَضُهر بِهِ، وَالثهانِي: مَتَى تَـنَاوَلَهُ، أَضَ هر بِهِ، وَالثهالِثُ :', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'يَضُرُّ بِهِ قَلِيلًا، فَالْعَادَةُ ركُْنٌ عَظِيمٌ فِي حِفْظِ الصِّحهةِ، وَمُعَالََجةِ الَْأمْرَاضِ ، وَلِذَلِكَ جَاءَ الْعِلَاجُ النهـبَوِيُّ بِِإجْ رَاءِ كُلِّ بَدَنٍ عَلَى عَادَتِهِ فِي استعمال الأغذية والأدوية وغير ذَلِكَ .', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي تَـغْذِيَةِ الْمَرِيضِ بَِألْطَفِ مَا اعْتَادَهُ مِنَ الَْأغْذِيَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'فِي «الصهحِيحَيِْن» مِنْ حَدِيثِ عروة عَنْ عائشة، أَنهـهَا كَانَتْ إِذَا مَاتَ الْمَيِّتُ مِنْ أَهْلِهَا، وَاجْتَمَعَ لِذَلِكَ النِّسَاءُ، ُ مه تَـفَهرقْنَ إِلَى أَهْلِهِنه، أَمَرَتْ بِبُـرْمَةٍ مِنْ تَـلْبِينَةٍ فَطُبِخَتْ ، وَصَنَـعَتْ ثَرِيدًا، ُ مه صَبهتِ التهـلْبِينَةَ عَلَيْهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'ُ مه قَالَتْ : كُلُوا مِنْـهَا، فَإِنِّي سَِمعْتُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـقُولُ: «التهـلْبِينَةُ مَمََهةٌ لِفُؤَادِ الْمَرِيضِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'تَذْهَبُ بِبَـعْضِ الُْحزْنِ» »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَفِي «السُّنَنِ» مِنْ حَدِيثِ عائشة أَيْضًا، قَالَتْ : قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '«عَلَيْكُمْ بِالْبَغِيضِ النهافِعِ التهـلْبِيِن» ، قَالَتْ : وَكَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إِذَا اشْتَكَى أَحَدٌ مِنْ أَهْلِهِ لََْ تَـزَلِ الْبُـرْمَةُ عَلَى النهارِ حَ هتى يَـنْـتَهِيَ أحد طرفيه. يعنِ يبأَ أو يموت. »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(7) أخرجه البخاري في الأطعمة ومسلم في اللباس (2) أخرجه ابن ماجه وأحدْ والحاكم', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَعَنْـهَا: كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إِذَا قِيلَ لَهُ: إِنه فُلَانًا وَجِعٌ لَا يَطْعَمُ الطهعَامَ، قَالَ: «عَلَيْكُمْ بِالتهـلْبِينَةِ فَحَسُّوهُ إِهياهَا» ، وَيَـقُولُ: «وَالهذِي نَـفْسِي بِيَدِهِ إِنهـهَا تَـغْسِلُ بَطْنَ أَحَدِكُمْ كَمَا تَـغْسِلُ إِحْدَاكُنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَجْ هَهَا مِنَ الْوَسَخِ» »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'التهـلْبِيُن: هُوَ الِْحسَاءُ الهرقِيقُ اهلذِي هُوَ فِي قِوَامِ الهلبَِن، وَمِنْهُ اشْتُقه اسُْمهُ، قَالَ الهروي: سُِّميَتْ تَـلْبِينَةً لِشَبَهِهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'بِاللهبَِن لِبَـيَاضِهَا وَرِقهتِهَا، وَهَذَا الْغِذَاءُ هُوَ الهنافِعُ لِلْعَلِيلِ، وَهُوَ الهرقِيقُ النضيج لَا الْغَلِيظُ النِّءُِ، وَإِذَا شِئْتَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'أَنْ تَـعْرِفَ فَضْلَ التهـلْبِينَةِ، فَاعْرِفْ فَضْلَ مَاءِ الشهعِيِر، بَلْ هِيَ مَاءُ الشهعِيِر لَهمُْ، فَإِنهـهَا حِسَاءٌ مُتهخَذٌ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'دَقِيقِ الشهعِيِر بِنُخَالَتِهِ، وَالْفَرْقُ بَـيْـنَـهَا وَبَـيَْن مَاءِ الشهعِيِر أَنههُ يُطْبَخُ صِحَاحًا، وَالتهـلْبِينَةُ تُطْبَخُ من مَطْحُونًا، وَهِيَ أَنْـفَعُ مِنْهُ لُِخرُوجِ خَاصِّ يهةِ الشهعِيِر بِالطهحْنِ، وَقَدْ تَـقَدهمَ أَنه لِلْعَادَاتِ تَثَِْيًرا فِي الِانْتِفَاعِ بِالَْأدْوِيَةِ وَالَْأغْذِيَةِ، وَكَانَتْ عَادَةُ الْقَوْمِ أَنْ يتخدوا مَاءَ الشهعِيِر مِنْهُ مَطْحُونًا لَا صِحَاحًا، وَهُوَ أَكْ ثَـرُ تَـغْذِيَةً، وَأَقْـوَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'فِعْلًا، وَأَعْظَمُ جَلَاءً، وَإِهنَما اهتَخذَهُ أَطِبهاءُ الْمُدُنِ مِنْهُ صِحَاحًا لِيَكُونَ أَرَقه وَأَلْطَفَ ، فَلَا يَـثْـقُلُ عَلَى طَبِيعَةِ الْمَرِيضِ ، وَهَذَا بَِحسَبِ طَبَائِعِ أَهْلِ الْمُدُنِ وَرَخَاوَتَِها، وَثِقَلِ مَاءِ الشهعِيِر الْمَطْحُونِ عَلَيْـهَا. وَالْمَقْصُودُ: أَنه مَاءَ الشهعِيِر مَطْبُوخًا صِحَاحًا يَـنْـفُذُ سَرِيعًا، وَيَْجلُو جَلَاءً ظَاهِرًا، وَيُـغَذِّي غِذَاءً لَطِيفًا. وَإِذَا شُرِبَ حَارًّا كَانَ جَلَاؤُهُ أَقْـوَى، وَنُـفُوذُهُ أَسْرَعَ، وَإِنَْماؤُهُ لِلْحَرَارَةِ الْغَرِيزِيهةِ أَكْ ثَـرَ، وَتَـلْمِيسُهُ لِسُطُوحِ الْمَعِدَةِ أَوْفَقَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَقَـوْلُهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِيهَا: «مَمََهةٌ لِفُؤَادِ الْمَرِيضِ » يُـرْوَى بِوَجْ هَيِْن. بِفَتْحِ الْمِيمِ وَالِْجيمِ، وَبِضَمِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'الْمِيمِ، وَكَسْرِ الِْجيمِ، وَالَْأهولُ: أَشْهَرُ، وَمَعْنَاهُ: أَنهـهَا مُرِيَحةٌ لَهُ، أَيْ : تُرِيُحهُ وَتُسَكِّنُهُ مِنَ الِْإجْاََمِ، وَهُوَ الهراحَةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَقَـوْلُهُ: «تَذْهَبُ بِبَـعْضِ الُْحزْنِ» ، هَذَا- وَا هللَُّ أَعْلَمُ- لَِأنه الْغَمه وَالُْحزْنَ يُـبَـرِّدَانِ الْمِزَاجَ، وَيُضْعِفَانِ الَْحرَارَةَ الْغَرِيزِيهةَ لِمَيْلِ الرُّوحِ الَْحامِلِ لََها إِلَى جِهَةِ الْقَلْبِ الهذِي هُوَ مَنْشَؤُهَا، وَهَذَا الِْحسَاءُ يُـقَوِّي الَْحرَارَةَ الْغَرِيزِيهةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'بِزِيَادَتِهِ فِي مَادهتَِها، فَـتُزِيلُ أَكْ ثَـرَ مَا عَرَضَ لَهُ مِنَ الْغَمِّ وَالُْحزْنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَقَدْ يُـقَالُ- وَهُوَ أَقْـرَبُ :- إِنهـهَا تَذْهَبُ بِبَـعْضِ الُْحزْنِ خِاَِصِّ يهةٍ فِيهَا مِنْ جِنْسِ خَوَاصِّ الَْأغْذِيَةِ الْمُفْرِحَةِ، فَإِنه مِنَ الَْأغْذِيَةِ مَا يُـفْرِحُ بِالَْخاصِّ يهةِ، وَا هللَُّ أَعْلَمُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَقَدْ يُـقَالُ: إِنه قُـوَى الَْحزِينِ تضعف باستيلاء اليبس على أعضائه، وعلى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, '(7) أخرجه الإمام أحدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'مَعِدَتِهِ خَاصهةً لِتَـقْلِيلِ الْغِذَاءِ، وَهَذَا الِْحسَاءُ يُـرَطِّبُـهَا، وَيُـقَوِّيهَا، وَيُـغَذِّيهَا، وَيَـفْعَلُ مِثْلَ ذَلِكَ بِفُؤَادِ الْمَرِيضِ ، لَكِنه الْمَرِيضَ كَثِيًرا مَا يَْجتَمِعُ فِي مَعِدَتِهِ خَلْطٌ مَرَارِيٌّ، أَوْ بَـلْغَمِيٌّ، أَوْ صَدِيدِيٌّ، وَهَذَا الِْحسَاءُ يَْجلُو ذَلِكَ عَنِ الْمَعِدَةِ وَيَسْرُوهُ، وَيَْحدُرُهُ، وَيَُميِّعُهُ، وَيُـعَدِّلُ كَيْفِيهـتَهُ، وَيَكْسِرُ سَوْرَتَهُ، فَـيُِريُحهَا وَلَا سِيهمَا لِمَنْ عَادَتُهُ الِاغْتِذَاءُ خِبُِْزِ الشهعِيِر، وَهِيَ عَادَةُ أَهْلِ الْمَدِينَةِ إِذْ ذَاكَ، وَكَانَ هُوَ غَالِبَ قُوتِِهمْ، وَكَانَتِ الِْحنْطَةُ عَزِيزَةً', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'عِنْدَهُمْ. وَا هللَُّ أعلم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ السُّمِّ الهذِي أَصَابَهُ خِيَِْـبَـرَ مِنَ الْيَـهُودِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'ذكََرَ عبد الرزاق، عَنْ معمر، عَنِ الزُّهْرِيِّ ، عَنْ عبد الرحنْ بن كعب بن مالك: أَنه امْرَأَةً يَـهُودِيهةً أَهْدَتْ إِلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ شَاةً مَصْلِيهةً خِيَِْـبَـرَ، فَـقَالَ: «مَا هَذِهِ» ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'قَالَتْ : هَدِيهةٌ، وَحَذِرَتْ أَنْ تَـقُولَ: مِنَ الصهدَقَةِ، فَلَا كََُْلُ مِنْـهَا، فَأَكَلَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَأَكَلَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الصهحَابَةُ، ُ مه قَالَ: «أَمْسِكُوا» ، ُ مه قَالَ لِلْمَرْأَةِ: «هَلْ سََممْتِ هَذِهِ الشهاةَ» ؟ قَالَتْ : مَنْ أَخْبَـرَكَ بَِهذَا؟ قَالَ: «هَذَا الْعَظْمُ لِسَاقِهَا» ، وَهُوَ فِي يَدِهِ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'قَالَتْ : نَـعَمْ. قَالَ: «لََِ» ؟ قَالَتْ : أَرَدْتُ إِنْ كُنْتَ كَاذِبًا أَنْ يَسْتَِريحَ مِنْكَ النهاسُ ، وَإِنْ كُنْتَ نَبِيًّا، لََْ يَضُهركَ، قَالَ: فَاحْتَجَمَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ ثَلَاثَةً عَلَى الْكَاهِلِ، وَأَمَرَ أَصْحَابَهُ أَنْ يَْحتَجِمُوا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'فَاحْ تَجَمُوا، فَمَاتَ بَـعْضُهُمْ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَفِي طَرِيقٍ أُخْ رَى: وَاحْتَجَمَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَلَى كَاهِلِهِ مِنْ أَجْلِ الهذِي أَكَلَ مِنَ الشهاةِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'حَجَمَهُ أبو هند بِالْقَرْنِ وَالشهفْرَةِ، وَهُوَ مَوْلًى لِبَنِِ بَـيَاضَةَ مِنَ الَْأنْصَارِ، وَبَقِيَ بَـعْدَ ذَلِكَ ثَلَاثَ سِنِيَن حَ هتى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'كَانَ وَجَعُهُ الهذِي تُـوُفَِّي فِيهِ، فَـقَالَ: «مَا زِلْتُ أَجِدُ مِنَ الُْأكْ لَةِ الهتِي أَكَلْتُ مِنَ الشهاةِ يَـوْمَ خَيْـبَـرَ حَ هتى كَانَ هَذَا أَوَانَ انْقِطَاعِ الَْأبْـهَرِ مِنِِّ» فَـتُـوُفَِّي رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ شَهِيدًا، قَالَهُ مُوسَى بْنُ عقبة»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, '. »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, '(7) ذكره عبد الرزاق في المصنف ورجاله ثقات (2) ذكره عبد الرزاق في المصنف ورجاله ثقات', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'مُعَالََجةُ السُّمِّ تَكُونُ بِالِاسْتِفْرَاغَاتِ، وَبِالَْأدْوِيَةِ الهتِي تُـعَارِضُ فِعْلَ السُّمِّ وَتُـبْطِلُهُ، إِمها بِكَيْفِيهاتَِها، وَإِمها خِوََِاصِّهَا، فَمَنْ عَدِمَ الدهوَاءَ، فَـلْيُـبَادِرْ إِلَى الِاسْتِفْرَاغِ الْكُلِّيِّ وَأَنْـفَعُهُ الِْحجَامَةُ، وَلَا سِيهمَا إِذَا كَانَ الْبَـلَدُ حَارًّا، وَالهزمَانُ حَارًّا، فَإِنه الْقُهوةَ السُّمِّيهةَ تَسْرِي إِلَى الدهمِ، فَـتَـنْـبَعِثُ فِي الْعُرُوقِ وَالْمَجَارِي حَ هتى تَصِلَ إِلَى الْقَلْبِ، فَـيَكُونُ الَْهلَاكُ، فَالدهمُ هُوَ الْمَنْـفَذُ الْمُوَصِّلُ لِلسُّمِّ إِلَى الْقَلْبِ وَالَْأعْضَاءِ، فَإِذَا بَادَرَ الْمَسْمُومُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَأَخْ رَجَ الدهمَ، خَرَجَتْ مَعَهُ تِلْكَ الْكَيْفِيهةُ السُّمِّيهةُ الهتِي خَالَطَتْهُ، فَإِنْ كَانَ اسْتِفْرَاغًا تَامًّا لََْ يَضُهرهُ السُّمُّ، بَلْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'إِمها أَنْ يَذْهَبَ ، وَإِمها أَنْ يَضْعُفَ فَـتَـقْوَى عَلَيْهِ الطهبِيعَةُ، فَـتُـبْطِلُ فِعْلَهُ أَوْ تُضْعِفُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَلَمها احْتَجَمَ النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، احْتَجَمَ فِي الْكَاهِلِ، وَهُوَ أَقْـرَبُ الْمَوَاضِعِ الهتِي يُْمكِنُ فِيهَا الِْحجَامَةُ إِلَى الْقَلْبِ، فَخَرَجَتِ الْمَادهةُ السُّمِّيهةُ مَعَ الدهمِ لَا خُرُوجًا كُلِّيًّا، بَلْ بَقِيَ أَثَـرُهَا مَعَ ضَعْفِهِ لِمَا يُرِيدُ ا هللَُّ سُبْحَانَهُ مِنْ تَكْمِيلِ مَرَاتِبِ الْفَضْلِ كُلِّهَا لَهُ، فَـلَمها أَرَادَ ا هللَُّ إِكْرَامَهُ بِالشههَادَةِ، ظَهَرَ تَثَِْيُر ذَلِكَ الَْأثَرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'الْكَامِنِ مِنَ السُّمِّ لِيَـقْضِيَ ا هللَُّ أَمْرًا كَانَ مَفْعُولًا، وَظَهَرَ سِرُّ قَـوْلِهِ تَـعَالَى لَِأعْدَائِهِ مِنَ الْيَـهُودِ: أَفَكُلهما جاءكَُمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'رَسُولٌ بِما لَا تَـهْوى أَنْـفُسُكُمُ اسْتَكْبَـرْتُْم فَـفَرِيقاً كَذهبْـتُمْ وَفَرِيقاً تَـقْتُـلُونَ [الْبَـقَرَةِ: ]91 ، فَجَاءَ بِلَفْظِ كَذهبْـتُمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'بِالْمَاضِي الهذِي قَدْ وَقَعَ مِنْهُ، وَتَقََهقَ، وَجَاءَ بِلَفْظِ: «تَـقْتُـلُونَ» بِالْمُسْتَـقْبَلِ الذي يتوقعونه وينتظرونه، والله أعلم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ السِّ حْرِ الهذِي سَحَرَتْهُ الْيَـهُودُ بِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'قَدْ أَنْكَرَ هَذَا طَائِفَةٌ مِنَ النهاسِ ، وَقَالُوا: لَا يَُجوزُ هَذَا عَلَيْهِ، وَظَنُّوهُ نَـقْصًا وَعَيْـبًا، وَلَيْسَ الَْأمْرُ كَمَا زَعَمُوا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'بَلْ هُوَ مِنْ جِنْسِ مَا كَانَ يَـعْتَِريهِ صَلهى ا هللَُّ عَلَيْهِ وَسَ هلمَ مِنَ الَْأسْقَامِ وَالَْأوْجَاعِ ، وَهُوَ مَرَضٌ مِنَ الَْأمْرَاضِ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَإِصَابَـتُهُ بِهِ كَإِصَابَتِهِ بِالسُّمِّ لَا فَـرْقَ بَـيْـنَـهُمَا، وَقَدْ ثَـبَتَ فِي «الصهحِيحَيِْن» عَنْ عائشة رَضِيَ ا هللَُّ عَنْـهَا، أَنهـهَا قَالَتْ : سُحِرَ رَسُولُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ حَ هتى إِنْ كَانَ لَيُخَيهلُ إِلَيْهِ أَنههُ تََِْي نِسَاءَهُ، وَلََْ تََِِْهنه، وَذَلِكَ أَشَدُّ مَا يَكُونُ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'السِّ حْرِ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'قَالَ الْقَاضِي عِيَاضٌ : وَالسِّ حْرُ مَرَضٌ مِنَ الَْأمْرَاضِ ، وَعَارِضٌ مِنَ الْعِلَلِ يَُجوزُ عَلَيْهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، كَأَنْـوَاعِ الَْأمْرَاضِ مِمها لَا يُـنْكَرُ، وَلَا يَـقْدَحُ فِي نُـبُـهوتِهِ، وَأَمها كَوْنُهُ يَُخيهلُ إِلَيْهِ أَنههُ فَـعَلَ الشهيْ ءَ وَلََْ يَـفْعَلْهُ، فَـلَيْسَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'فِي هَذَا مَا يُدْخِلُ عَلَيْهِ دَاخِلَةً فِي شَيْ ءٍ مِنْ صِدْقِهِ، لِقِيَامِ الدهلِيلِ وَالِْإجْاََعِ عَلَى عِصْمَتِهِ مِنْ هَذَا، وَإِهنَما', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'هَذَا فِيمَا يَُجوزُ طُرُوُّهُ عَلَيْهِ فِي أَمْرِ دُنْـيَاهُ الهتِي لََْ يُـبْـعَثْ لِسَبَبِهَا، وَلَا فُضِّلَ مِنْ أَجْلِهَا، وَهُوَ فِيهَا عُرْضَةٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'لِلْفَْاتِ كَسَائِرِ الْبَشَرِ، فَـغَيْـرُ بَعِيدٍ أَنههُ يَُخيهلَ إِلَيْهِ مِنْ أُمُورِهَا مَا لَا حَقِيقَةَ لَهُ، ُ مه يَـنْجَلِي عَنْهُ كَمَا كَانَ. وَالْمَقْصُودُ: ذِكْ رُ هَدْيِهِ فِي عِلَاجِ هَذَا الْمَرَضِ ، وَقَدْ رُوِيَ عَنْهُ فِيهِ نَـوْعَانِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'أَحَدُهُاَُ- وَهُوَ أَبْـلَغُهُمَا:- اسْتِخْ رَاجُهُ وَإِبْطَالُهُ، كَمَا صَحه عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ سَأَلَ رَبههُ سُبْحَانَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'فِي ذَلِكَ ، فَدَ هل عَلَيْهِ، فَاسْتَخْ رَجَهُ مِنْ بِئْرٍ، فَكَانَ فِي مُشْطٍ وَمُشَاطَةٍ، وَجُفِّ طَلْعَةِ ذكََرٍ، فَـلَمها اسْتَخْ رَجَهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'ذَهَبَ مَا بِهِ، حَ هتى كَأَهنَما أُنْشِطَ مِنْ عِقَالٍ، فَـهَذَا مِنْ أَبْـلَغِ مَا يُـعَالََُ بِهِ الْمَطْبُوبُ ، وَهَذَا بَِمنْزِلَةِ إِزَالَةِ الْمَادهةِ الَْخبِيثَةِ وَقَـلْعِهَا مِنَ الَْجسَدِ بِالِاسْتِفْرَاغِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَالنهـوْعُ الثهانِي: الِاسْتِفْرَاغُ فِي الْمَحَلِّ الهذِي يَصِلُ إِلَيْهِ أَذَى السِّ حْرِ، فَإِنه لِلسِّ حْرِ تَثَِْيًرا فِي الطهبِيعَةِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَهَيَجَانَ أَخْلَاطِهَا، وَتَشْوِيشَ مِزَاجِهَا، فَإِذَا ظَهَرَ أَثَـرُهُ فِي عُضْوٍ، وَأَمْكَنَ اسْتِفْرَاغُ الْمَادهةِ الهردِيئَةِ مِنْ ذَلِكَ الْعُضْوِ، نَـفَعَ جِدًّا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَقَدْ ذكََرَ أبو عبيد فِي كِتَابِ «غَرِيبِ الَْحدِيثِ» لَهُ بِِإسْنَادِهِ، عَنْ عَبْدِ الهرحْنَِْ بْنِ أَبِي لَيْـلَى، أَنه النهبِه صَلهى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'ا هللَُّ عَلَيْهِ وَسَلهمَ احْتَجَمَ عَلَى رَأْسِهِ بِقَرْنٍ حِيَن طُبه »2« . قَالَ أبو عبيد: مَعْنَى طُبه : أَيْ سُحِرَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَقَدْ أَشْكَلَ هَذَا عَلَى مَنْ قَله عِلْمُهُ، وَقَالَ: مَا لِلْحِجَامَةِ وَالسِّ حْرِ، وَمَا الهرابِطَةُ بَـيَْن هَذَا الدهاءِ وَهَذَا الدهوَاءِ، وَلَوْ وَجَدَ هَذَا الْقَائِلُ أبقراط، أَوِ ابْنَ سِينَا، أَوْ غَيْـرَهُاَُ قَدْ نَصه عَلَى هَذَا الْعِلَاجِ، لَتَـلَقهاهُ بِالْقَبُولِ وَالتهسْلِيمِ، وَقَالَ: قَدْ نَصه عَلَيْهِ مَنْ لَا يُشَكه فِي مَعْرِفَتِهِ وَفَضْلِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, '(7) أخرجه البخاري في الطب، ومسلم في باب السحر. (2) هذا الحديث لا يصح', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'فَاعْلَمْ أَنه مَادهةَ السِّ حْرِ اهلذِي أُصِيبَ بِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ انْـتَـهَتْ إِلَى رَأْسِهِ إِلَى إِحْدَى قُـوَاهُ الهتِي فِيهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'بَِحيْثُ كَانَ يَُخيهلُ إِلَيْهِ أَنههُ يَـفْعَلُ الشهيْ ءَ وَلََْ يَـفْعَلْهُ، وَهَذَا تَصَرُّفٌ مِنَ السهاحِرِ فِي الطهبِيعَةِ وَالْمَادهةِ الدهمَوِيهةِ بَِحيْثُ غَلَبَتْ تِلْكَ الْمَادهةُ عَلَى الْبَطْنِ الْمُقَدهمِ مِنْهُ، فَـغَيهـرَتْ مِزَاجَهُ عَنْ طَبِيعَتِهِ الَْأصْلِيهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَالسِّ حْرُ: هُوَ مُرَكهبٌ مِنْ تَثَِْيَراتِ الَْأرْوَاحِ الَْخبِيثَةِ، وَانْفِعَالِ الْقُوَى الطهبِيعِيهةِ عَنْـهَا، وَهُوَ أَشَدُّ مَا يَكُونُ مِنَ السِّ حْرِ، وَلَا سِيهمَا فِي الْمَوْضِ عِ الهذِي انْـتَـهَى السِّ حْرُ إِلَيْهِ، وَاسْتِعْمَالُ الِْحجَامَةِ عَلَى ذَلِكَ الْمَكَانِ الهذِي تَضَ هررَتْ أَفْـعَالُهُ بِالسِّ حْرِ مِنْ أَنْـفَعِ الْمُعَالََجةِ إِذَا اسْتُـعْمِلَتْ عَلَى الْقَانُونِ الهذِي يَـنْـبَغِي. قَالَ أبقراط:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'الَْأشْيَاءُ الهتِي يَـنْـبَغِي أَنْ تُسْتَـفْرَغَ يَِجبُ أَنْ تُسْتَـفْرَغَ مِنَ الْمَوَاضِعِ الهتِي هِيَ إِلَيْـهَا أَمْيَلُ بِالَْأشْيَاءِ الهتِي تَصْلُحُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'لِاسْتِفْرَاغِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَقَالَتْ طَائِفَةٌ مِنَ النهاسُ : إِنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لَمها أُصِيبَ بَِهذَا الدهاءِ، وَكَانَ يَُخيهلُ إِلَيْهِ أَنههُ فَـعَلَ الشهيْ ءَ وَلََْ يَـفْعَلْهُ، ظَنه أَنه ذَلِكَ عَنْ مَادهةٍ دَمَوِيهةٍ أَوْ غَيِْرهَا مَالَتْ إِلَى جِهَةِ الدِّمَاغِ ، وَغَلَبَتْ عَلَى الْبَطْنِ الْمُقَدهمِ مِنْهُ، فَأَزَالَتْ مِزَاجَهُ عَنِ الَْحالَةِ الطهبِيعِيهةِ لَهُ، وَكَانَ اسْتِعْمَالُ الِْحجَامَةِ إِذْ ذَاكَ مِنْ أَبْـلَغِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'الَْأدْوِيَةِ، وَأَنْـفَعِ الْمُعَالََجةِ، فَاحْتَجَمَ، وَكَانَ ذَلِكَ قَـبْلَ أَنْ يُوحَى إِلَيْهِ أَنه ذَلِكَ مِنَ السِّ حْرِ، فَـلَمها جَاءَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'الْوَحْيُ مِنَ ا هلِلَّ تَـعَالَى، وَأَخْبَـرَهُ أَنههُ قَدْ سُحِرَ، عَدَلَ إِلَى الْعِلَاجِ الَْحقِيقِيِّ وَهُوَ اسْتِخْ رَاجُ السِّ حْرِ وَإِبْطَالُهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'فَسَأَلَ ا هللََّ سُبْحَانَهُ، فَدَلههُ عَلَى مَكَ انِهِ، فَاسْتَخْ رَجَهُ، فَـقَامَ كَأَهنَما أُنْشِطَ مِنْ عِقَالٍ، وَكَانَ غَايَةُ هَذَا السِّ حْرِ فِيهِ إِهنَما هُوَ فِي جَسَدِهِ، وَظَاهِرِ جَوَارِحِهِ، لَا عَلَى عَقْلِهِ وَقَـلْبِهِ، وَلِذَلِكَ لََْ يَكُنْ يَـعْتَقِدُ صِحهةَ مَا يَُخيهلُ إِلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'مِنْ إِتْـيَانِ النِّسَاءِ، بَلْ يَـعْلَمُ أَنههُ خَيَالٌ لَا حَقِيقَةَ لَهُ، وَمِثْلُ هَذَا قَدْ يَْحدُثُ مِنْ بَـعْضِ الَْأمْرَاضِ ، وَا هللَُّ أَعْلَمُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَمِنْ أَنْـفَعِ عِلَاجَاتِ السِّ حْ رِ الَْأدْوِيَةُ الِْإلَِهيهةُ، بَلْ هِيَ أَدْوِيَـتُهُ النهافِعَةُ بِالذهاتِ، فَإِنههُ مِنْ تَثَِْيَراتِ الَْأرْوَاحِ الَْخبِيثَةِ السُّفْلِيهةِ، وَدَفْعُ تَثَِْيِرهَا يَكُونُ بَِما يُـعَارِضُهَا وَيُـقَاوِمُهَا مِنَ الَْأذكَْارِ، وَالْآيَاتِ، وَالدهعَوَاتِ الهتِي تُـبْطِلُ فِعْلَهَا وَتَثَِْيَرهَا، وَكُلهمَا كَانَتْ أَقْـوَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَأَشَده، كَانَتْ أَبْـلَغَ فِي النُّشْرَةِ »7« ، وَذَلِكَ بَِمنْزِلَةِ الْتِقَاءِ جَيْشَيِْن مَعَ كُلِّ وَاحِدٍ مِنْـهُمَا عُدهتُهُ وَسِلَاحُهُ، فَأَيُّـهُمَا غَلَبَ الْآخَرَ، قَـهَرَهُ، وَكَانَ الُْحكْمُ لَهُ، فَالْقَلْبُ إِذَا كَانَ مُْمتَلِئًا مِنَ ا هلِلَّ مَغْمُورًا بِذِكْرِهِ، وَلَهُ مِنَ التهـوَجُّهَاتِ وَالدهعَوَاتِ وَالَْأذكَْارِ وَالتهـعَوُّذَاتِ وِرْدٌ لَا يُِخلُّ بِهِ يُطَابِقُ فِيهِ قَـلْبُهُ لِسَانَهُ، كَانَ هَذَا مِنْ أَعْظَمِ الَْأسْبَابِ الهتِي تَنََْعُ إِصَابَةَ السِّ حْرِ لَهُ، وَمِنْ أَعْظَمِ الْعِلَاجَاتِ لَهُ بَـعْدَ مَا يُصِيبُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَعِنْدَ السهحَرَةِ: أَنه سِحْ رَهُمْ إِهنَما يَتِمُّ تَثَِْيُرهُ فِي الْقُلُوبِ الضهعِيفَةِ الْمُنْـفَعِلَةِ، وَالنُّـفُوسِ الشههْوَانِيهةِ الهتِي هِيَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'مُعَلهقَةٌ بِالسُّفْلِيهاتِ، وَلَِهذَ ا فَإِنه غَالِبَ مَا يُـؤَثِّرُ فِي النِّسَاءِ، وَالصِّ بْـيَانِ، وَالُْج ههالِ، وَأَهْلِ الْبَـوَادِي، وَمَنْ ضَعُفَ حَظُّهُ مِنَ الدِّينِ وَالتهـوَكُّلِ وَالتهـوْحِيدِ، وَمَنْ لَا نَصِيبَ لَهُ مِنَ الَْأوْرَادِ الِْإلَِهيهةِ وَالدهعَوَاتِ وَالتهـعَوُّذَاتِ النهـبَوِيهةِ. وَبِالُْجمْلَةِ: فَسُلْطَانُ تَثَِْيِرهِ فِي الْقُلُوبِ الضهعِيفَةِ الْمُنْـفَعِلَةِ الهتِي يَكُونُ مَيْـلُهَا إِلَى السُّفْلِيهاتِ، قَالُوا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَالْمَسْحُورُ هُوَ الهذِي يُعِيُن عَلَى نَـفْسِهِ، فَإِهنا نَِدُْ قَـلْبَهُ مُتَـعَلِّقًا بِشَيْ ءٍ كَثِيُر الِالْتِفَاتِ إِلَيْهِ، فَـيَـتَسَلهطُ عَلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'قَـلْبِهِ بَِما فِيهِ مِنَ الْمَيْلِ وَالِالْتِفَاتِ، وَالَْأرْوَاحُ الَْخبِيثَةُ إِهنَما تَـتَسَلهطُ عَلَى أَرْوَاحٍ تَـلْقَاهَا مُسْتَعِدهةً لِتَسَلُّطِهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'عَلَيْـهَا بَِميْلِهَا إِلَى مَا يُـنَاسِبُ تِلْكَ الَْأرْوَاحَ الَْخبِيثَةَ، وَبِفَرَاغِهَا مِنَ الْقُهوةِ الِْإلَِهيهةِ، وَعَدَمِ أَخْذِهَا لِلْعُدهةِ الهتِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'تُاََرِبُـهَا بَِها، فَـتَجِدُهَا فَارِغَةً لَا عُدهةَ مَعَهَا، وَفِيهَا مَيْلٌ إِلَى مَا يُـنَاسِبُـهَا، فَـتَـتَسَلهطُ عَلَيْـهَا، وَيَـتَمَكهنُ تَثَِْيُرهَا فيها بالسحر وغيره، والله أعلم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي الِاسْتِفْرَاغِ بِالْقَيْ ءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى الترمذي فِي «جَامِعِهِ» عَنْ معدان بن أبي طلحة، عَنْ أَبِي الدهرْدَاءِ، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'قَاءَ، فَـتَـوَضهأَ فَـلَقِيتُ ثَـوْبَانَ فِي مَسْجِدِ دِمَشْقَ، فَذَكَرْتُ لَهُ ذَلِكَ ، فَـقَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'صَدَقَ ، أَنَا صَبَـبْتُ لَهُ وَضُوءَهُ. قَالَ الترمذي: وَهَذَا أَصَحُّ شَيْ ءٍ في الباب »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(7) النشرة بالضم: رقية يعالَ بها المجنون والمريض- القاموس المحيط (2) أخرجه الإمام أحدْ والحاكم والدارقطنِ والبيهقي والطحاوي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الْقَيْ ءُ: أَحَدُ الِْاسْتِفْرَاغَاتِ الَْخمْسَةِ الهتِي هِيَ أُصُولُ الِاسْتِفْرَاغِ ، وَهِيَ الِْإسْهَالُ، وَالْقَيْ ءُ، وَإِخْرَاجُ الدهمِ، وَخُرُوجُ الَْأخِْرَِةِ وَالْعَرَقِ، وَقَدْ جَاءَتْ بَِها السُّنهةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'فَأَمها الِْإسْهَالُ: فَـقَدْ مَ هر فِي حَدِيثِ «خَيْـرُ مَا تَدَاوَيْـتُمْ بِهِ الْمَشِيُّ» وَفِي حَدِيثٍ «السهنَا. وَأَمها إِخْ رَاجُ الدهمِ، فَـقَدْ تَـقَدهمَ فِي أَحَادِيثِ الِْحجَامَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَأَمها اسْتِفْرَاغُ الَْأخِْرَِةِ، فَـنَذْكُرُهُ عَقِيبَ هَذَا الْفَصْلِ إِنْ شَاءَ ا هللَُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَأَمها الِاسْتِفْرَاغُ بِالْعَرَقِ، فَلَا يَكُونُ غَالِبًا بِالْقَصْدِ، بَلْ بِدَفْعِ الطهبِيعَةِ لَهُ إِلَى ظَاهِرِ الَْجسَدِ، فَـيُصَادِفُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'الْمَسَامه مُفَتهحَةً، فَـيَخْ رُجُ منها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'والقيء استفراغ من أعلا الْمَعِدَةِ، وَالُْحقْنَةُ مِنْ أَسْفَلِهَا، وَالدهوَاءُ مِنْ أَعْلَاهَا وَأَسْفَلِهَا، وَالْقَيْ ءُ: نَـوْعَانِ: نَـوْعٌ بِالْغَلَبَةِ وَالَْهيَجَانِ، وَنَـوْعٌ بِالِاسْتِدْعَاءِ وَالطهلَبِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'فَأَمها الَْأهولُ: فَلَا يَسُوغُ حَبْسُهُ وَدَفْـعُهُ إِهلا إِذَا أَفْـرَطَ وَخِيفَ مِنْهُ التهـلَفُ ، فَـيُـقْطَعُ بِالَْأشْيَاءِ الهتِي تُسَِْكُهُ. وَأَمها الثهانِي: فَأَنْـفَعُهُ عِنْدَ الَْحاجَةِ إِذَا رُوعِيَ زَمَانُهُ وَشُرُوطُهُ الهتِي تُذْكَرُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَأَسْبَابُ الْقَيْ ءِ عَشَرَةٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'أَحَدُهَا: غَلَبَةُ الْمِ هرةِ الصهفْرَاءِ، وَطَفْوُهَا عَلَى رَأْسِ  الْمَعِدَةِ، فَـتَطْلُبُ الصُّعُودَ. الثهانِي: مِنْ غَلَبَةِ بَـلْغَمٍ لَزِجٍ قَدْ تَهََركَ فِي الْمَعِدَةِ، وَاحْ تَاجَ إِلَى الُْخرُوجِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'الثهالِثُ : أَنْ يَكُونَ مِنْ ضَعْفِ الْمَعِدَةِ فِي ذَاتَِها، فَلَا تَـهْضِمُ الطهعَامَ، فَـتَـقْذِفُهُ إِلَى جِهَةِ فَـوْقَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'الهرابِعُ: أَنْ يَُخالِطَهَا خَلْطٌ رَدِيءٌ يَـنْصَبُّ إِلَيْـهَا، فَـيُسِيءُ هَضْمَهَا، وَيُضْعِفُ فِعْلَهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'الَْخامِسُ : أَنْ يَكُونَ مِنْ زِيَادَةِ الْمَأْكُولِ أَوِ الْمَشْرُوبِ عَلَى الْقَدْرِ الهذِي تَتََْمِلُهُ الْمَعِدَةُ، فَـتَـعْجِزُ عَنْ إِمْسَاكِهِ، فَـتَطْلُبُ دَفْـعَهُ وَقَذْفَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'السهادِسُ : أَنْ يَكُونَ مِنْ عَدَمِ مُوَافَـقَةِ الْمَأْكُولِ وَالْمَشْرُوبِ لََها، وَكَرَاهَتِهَا لَهُ، فَـتَطْلُبُ دَفْـعَهُ وَقَذْفَهُ. السهابِعُ: أَنْ يَْحصُلَ فِيهَا مَا يُـثَـوِّرُ الطهعَامَ بِكَيْفِيهتِهِ وَطَبِيعَتِهِ، فَـتَـقْذِفُ بِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'الثهامِنُ: الْقَرَفُ ، وَهُوَ مُوجِبُ غَثَـيَانِ النهـفْسِ وَتَـهَوِّعِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'التهاسِعُ: مِنَ الَْأعْرَاضِ النهـفْسَانِيهةِ، كَالَْهمِّ الشهدِيدِ، وَالْغَمِّ، وَالَْحزَنِ، وَغَلَبَةِ اشْتِغَالِ الطهبِيعَةِ وَالْقُوَى الطهبِيعِيهةِ بِهِ، وَاهْتِمَامِهَا بِوُرُودِهِ عَنْ  تَدْبِيِر الْبَدَنِ ، وَإِصْلَاحِ الْغِذَاءِ، وَإِنْضَاجِهِ، وَهَضْمِهِ، فَـتَـقْذِفُهُ الْمَعِدَةُ، وَقَدْ يَكُونُ لَِأجْلِ تَرََُّكِ الَْأخْلَاطِ عِنْدَ تََخبُّطِ النهـفْسِ ، فَإِنه كُله وَاحِدٍ مِنَ النهـفْسِ وَالْبَدَنِ يَـنْـفَعِلُ عَنْ صَاحِبِهِ، وَيُـؤَثِّرُ فِي كَيْفِيهتِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'الْعَاشِرُ: نَـقْلُ الطهبِيعَةِ بَِأنْ يَـرَى مَنْ يَـتَـقَيهأُ، فَـيَـغْلِبُهُ هُوَ الْقَيْ ءُ مِنْ غَيِْر اسْتِدْعَاءٍ، فَإِنه الطهبِيعَةَ نَـقهالَةٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَأَخْ بَـرَنِي بَـعْضُ حُذهاقِ الَْأطِبهاءِ، قَالَ: كَانَ لِِ ابْنُ أُخْتٍ حَذَقَ فِي الْكُحْلِ، فَجَلَسَ كَحهالًا، فَكَانَ إِذَا فَـتَحَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'عَيَْن الهرجُلِ، وَرَأَى الهرمَدَ وَكَحهلَهُ، رَمِدَ هُوَ، وَتَكَ هررَ ذَلِكَ مِنْهُ، فَـتَـرَكَ الُْجلُوسَ . قُـلْتُ لَهُ: فَمَا سَبَبُ ذَلِكَ ؟ قَالَ: نَـقْلُ الطهبِيعَةِ، فَإِنهـهَا نَـقهالَةٌ، قَالَ: وَأَعْرِفُ آخَرَ، كَانَ رَأَى خُ هراجًا فِي مَوْضِ عٍ مِنْ جِسْمِ رَجُلٍ يَُحكُّهُ، فَحَكه هُوَ ذَلِكَ الْمَوْضِعَ، فَخَرَجَتْ فِيهِ خُ هراجَةٌ. قلت: وكل هذا لابد فِيهِ مِنِ اسْتِعْدَادِ الطهبِيعَةِ، وَتَكُونُ الْمَادهةُ سَاكِنَةً فِيهَا غَيْـرَ مُتَحَرّكَِةٍ، فَـتَـتَحَ هركُ لِسَبَبٍ مِنْ هَذِهِ الَْأسْبَابِ، فَـهَذِهِ أَسْبَابٌ لِتَحَرُّكِ الْمَادهةِ لَا أَنهـهَا هي الموجبة لهذا العارض.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَلَمها كَانَتِ الَْأخْلَاطُ فِي الْبِلَادِ الَْحارهةِ، وَالَْأزْمِنَةِ الَْحارهةِ تَرِقُّ وَتَـنْجَذِبُ إِلَى فَـوْقَ ، كَانَ الْقَيْ ءُ فِيهَا أَنْـفَعَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَلَمها كَانَتْ فِي الَْأزْمِنَةِ الْبَارِدَةِ وَالْبِلَادِ الْبَارِدَةِ تَـغْلُظُ، وَيَصْعُبُ جَذْبُـهَا إِلَى فَـوْقَ ، كَانَ اسْتِفْرَاغُهَا بِالِْإسْهَالِ أَنْـفَعَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَإِزَالَةُ الَْأخْلَاطِ وَدَفْـعُهَا تَكُونُ بِالَْجذْبِ وَالِاسْتِفْرَاغِ ، وَالَْجذْبُ يَكُونُ مِنْ أَبْـعَدِ الطُّرُقِ، وَالِاسْتِفْرَاغُ مِنْ أَقْـرَبَِها، وَالْفَرْقُ بَـيْـنَـهُمَا أَنه الْمَادهةَ إِذَا كَانَتْ عَامِلَةً فِي الِانْصِبَابِ أَوِ التهـرَقِّي لََْ تَسْتَقِهر بَـعْدُ، فَهِيَ مُتَُْاجَةٌ إِلَى الَْجذْبِ، فَإِنْ كَانَتْ مُتَصَاعِدَةً جُذِبَتْ مِنْ أَسْفَلَ، وَإِنْ كَانَتْ مُنْصَبهةً جُذِبَتْ مِنْ فَـوْقَ ، وَأَمها إِذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'اسْتَـقَهرتْ فِي مَوْضِ عِهَا، اسْتَـفْرَغَتْ مِنْ أَقْـرَبِ الطُّرُقِ إِلَيْـهَا، فَمَتَى أَضَ هرتِ الْمَادهةُ بِالَْأعْضَاءِ الْعُلْيَا، اجْ تُذِبَتْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'مِنْ أَسْفَلَ، وَمَتَى أَضَ هرتْ بِالَْأعْضَاءِ السُّفْلَى، اجْتُذِبَتْ مِنْ فَـوْقَ ، وَمَتَى اسْتَـقَهرتِ، اسْتَـفْرَغَتْ مِنْ أَقْـرَبِ مَكَانٍ إِلَيْـهَا، وَلَِهذَا احْتَجَمَ الهنبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَلَى كَاهِلِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'تَارَةً، وَفِي رَأْسِهِ أُخْ رَى، وَعَلَى ظَهْرِ قَدَمِهِ تَارَةً، فَكَانَ يَسْتَـفْرغُِ مَادهةَ الدهمِ الْمُؤْذِي مِنْ أقرب مكان إليه. والله أعلم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَالْقَيْ ءُ يُـنَـقِّي الْمَعِدَةَ وَيُـقَوِّيهَا، وَيُِحدُّ الْبَصَرَ، وَيُزِيلُ ثِقَلَ الهرأْسِ ، وَيَـنْـفَعُ قُـرُوحَ الْكُلَى، وَالْمَثَانَةِ، وَالَْأمْرَاضَ الْمُزْمِنَةَ كَالُْجذَامِ وَالِاسْتِسْقَاءِ، وَالْفَالِجِ وَالهرعْشَةِ، وَيَـنْـفَعُ الْيَـرَقَانَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَيَـنْـبَغِي أَنْ يَسْتَـعْمِلَهُ الصهحِيحُ فِي الشههْرِ مَ هرتَـيِْن مُتَـوَالِيَـتَـيِْن مِنْ غَيِْر حِفْظِ دَوْرٍ، لِيَـتَدَارَكَ الثهانِي مَا قَصهرَ عَنْهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الَْأهولُ، وَيُـنَـقِّي الْفَضَلَاتِ الهتِي انْصَبهتْ بِسَبَبِهِ، وَالِْإكْ ثَارُ مِنْهُ يَضُرُّ الْمَعِدَةَ، وَيَْجعَلُهَا قَابِلَةً لِلْفُضُولِ، وَيَضُرُّ بِالَْأسْنَانِ وَالْبَصَرِ وَالسهمْعِ، وَرُهبَما صَدَعَ عِرْقًا، وَيَِجبُ أَنْ يَْجتَنِبَهُ مَنْ بِهِ وَرَمٌ فِي الَْحلْقِ، أَوْ ضَعْفٌ فِي الصهدْرِ، أَوْ دَقِيقُ الهرقَـبَةِ، أَوْ مُسْتَعِدٌّ لِنَـفْثِ الدهمِ، أَوْ عُسْرِ الِْإجَابَةِ لَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَأَمها مَا يَـفْعَلُهُ كَثِيٌر مِمهنْ يُسِيءُ التهدْبِيَر، وَهُوَ أَنْ يمتلىء مِنَ الطهعَامِ، ُ مه يَـقْذِفُهُ، فَفِيهِ آفَاتٌ عَدِيدَةٌ، مِنْـهَا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'أَنههُ يُـعَجِّ لُ الَْهرَمَ، وَيُوقِعُ فِي أَمْرَاضٍ رَدِيئَةٍ، وَيَْجعَلُ الْقَيْ ءَ لَهُ عَادَةً. وَالْقَيْ ءُ مَعَ الْيُـبُوسَةِ، وَضَعْفِ الَْأحْشَاءِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَهُزَالِ الْمَرَاقِّ »7« . أَوْ ضَعْفِ الْمُسْتَقِيءِ خَطَرٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَأَحْدَُْ أَوْقَاتِهِ الصهيْفُ وَالهربِيعُ دُونَ الشِّ تَاءِ وَالَْخرِيفِ، وَيَـنْـبَغِي عِنْدَ الْقَيْ ءِ أَنْ يَـعْصِبَ الْعَيْـنَـيِْن، وَيَـقْمِطَ الْبَطْنَ، وَيَـغْسِلَ الْوَجْ هَ بَِماءٍ بَارِدٍ عِنْدَ الْفَرَاغِ ، وَأَنْ يَشْرَبَ عَقِيبَهُ شَرَابَ التِّهفاحِ مَعَ يَسِيٍر مِنْ مُصْطَكَى،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَمَاءُ الْوَرْدِ يَـنْـفَعُهُ نفعا بيتا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَالْقَيْ ءُ يُسْتَـفْرَغُ مِنْ أَعْلَى الْمَعِدَةِ، وَيُْجذَبُ مِنْ أَسْفَلَ، وَالِْإسْهَالُ بِالْعَكْسِ ، قَالَ أبقراط: وَيَـنْـبَغِي أَنْ يَكُونَ الِاسْتِفْرَاغُ فِي الصهيْفِ مِنْ فَـوْقَ أَكْ ثَـرَ مِنَ الِاسْتِفْرَاغِ بِالدهوَاءِ، وَفِي الشِّ تَاءِ مِنْ أَسْفَلَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, '(7) مراق البطن البطن: بفتح الميم وتشديد القاف: مارق منه ولان، ولا واحد له', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي الِْإرْشَادِ إِلَى مُعَالََجةِ أَحْذَقِ الطهبِيبَـيِْن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'ذكََرَ مالك فِي «مُوَطهئِهِ» : عَنْ زَيْدِ بْنِ أَسْلَمَ، أَنه رَجُلًا فِي زَمَانِ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَصَابَهُ جُرْحٌ، فَاحْ تَـقَنَ الُْجرْحُ الدهمَ، وَأَنه الهرجُلَ دَعَا رَجُلَيِْن مِنْ بَنِِ أَنَْمارَ، فَـنَظَرَا إِلَيْهِ فَـزَعَمَا أَنه رَسُولَ ا هلِلَّ صَلهى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ لَهمَُا: «أَيُّكُمَا أَطَبُّ» ؟ فَـقَالَ: أَوَ فِي الطِّبِّ خَيْـرٌ يَا رَسُولَ ا هلِلَّ؟ فَـقَالَ: «أَنْـزَلَ الدهوَاءَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الهذِي أَنْـزَلَ الدهاءَ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'فَفِي هَذَا الَْحدِيثِ أَنههُ يَـنْـبَغِي الِاسْتِعَانَةُ فِي كُلِّ عِلْمٍ وَصِ نَاعَةٍ بَِأحْذَقِ مَنْ فِيهَا فَالَْأحْذَقِ، فَإِنههُ إِلَى الِْإصَابَةِ أَقْـرَبُ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَهَكَذَا يَِجبُ عَلَى الْمُسْتَـفْتِي أَنْ يَسْتَعِيَن عَلَى مَا نَـزَلَ بِهِ بِالَْأعْلَمِ فَالَْأعْلَمِ، لَِأنههُ أَقْـرَبُ إِصَابَةً مِمهنْ هُوَ دُونَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَكَذَلِكَ مَنْ خَفِيَتْ عَلَيْهِ الْقِبْـلَةُ، فَإِنههُ يُـقَلِّدُ أَعْلَمَ مَنْ يَِجدُهُ، وَعَلَى هَذَا فَطَرَ ا هللَُّ عِبَادَهُ، كَمَا أَنه الْمُسَافِرَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'فِي الْبَـرِّ وَالْبَحْرِ إِهنَما سُكُونُ نَـفْسِهِ، وَطُمَأْنِينَـتُهُ إِلَى أَحْذَقِ الدهلِيلَيِْن وَأَخْ بَِهَِاَُ، وَلَهُ يَـقْصِدُ، وَعَلَيْهِ يَـعْتَمِدُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'فَـقَدِ اتهـفَقَتْ عَلَى هَذَا الشهرِيعَةُ وَالْفِطْرَةُ وَالْعَقْلُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَقَـوْلُهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «أَنْـزَلَ الدهوَاءَ الهذِي أَنْـزَلَ الدهاءَ» ، قَدْ جَاءَ مِثْـلُهُ عَنْهُ فِي أَحَادِيثَ كَثِيَرةٍ، فَمِنْـهَا مَا رَوَاهُ عَمْرُو بْنُ دِينَارٍ، عَنْ هلال بن يساف، قَالَ: دَخَلَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'مَرِيضٍ يَـعُودُهُ، فَـقَالَ: «أَرْسِلُوا إِلَى طَبِيبٍ» ، فَـقَالَ قَائِلٌ: وَأَنْتَ تَـقُولُ ذَلِكَ يَا رَسُولَ ا هلِلَّ؟ قَالَ: «نَـعَمْ إِنه ا هللََّ عَهز وَجَله لََْ يُـنْزِلْ دَاءً إِهلا أَنْـزَلَ لَهُ دَوَاءً» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَفِي «الصهحِيحَيِْن» مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ يَـرْفَـعُهُ: «مَا أَنْـزَلَ ا هللَُّ مِنْ دَاءٍ إِهلا أَنْـزَلَ لَهُ شِفَاءً» ، وَقَدْ تَـقَدهمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'هَذَا الَْحدِيثُ وَغَيْـرُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَاخْتُلِفَ فِي مَعْنَى «أَنْـزَلَ الدهاءَ وَالدهوَاءَ» ، فَـقَالَتْ طَائِفَةٌ: إِنْـزَالُهُ إِعْلَامُ الْعِبَادِ بِهِ، وَلَيْسَ بِشَيْ ءٍ، فَإِنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَخْ بَـرَ بِعُمُومِ الِْإنْـزَالِ لِكُلِّ دَاءٍ وَدَوَائِهِ، وَأَكْثَـرُ الَْخلْقِ لَا يَـعْلَمُونَ ذَلِكَ ، وَلِهذََا قَالَ: «عَلِمَهُ مَنْ علمه، وجهله من جهله» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, '(7) أخرجه مالك في الموطأ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَقَالَتْ طَائِفَةٌ: إِنْـزَالُهمَُا: خَلْقُهُمَا وَوَضْعُهُمَا فِي الَْأرْضِ ، كَمَا فِي الَْحدِيثِ الْآخَرِ: «إِنه ا هللََّ لََْ يَضَعْ دَاءً إِهلا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَضَعَ لَهُ دَوَاءً» ، وَهَذَا وَإِنْ كَانَ أَقْـرَبَ مِنَ الهذِي قَـبْـلَهُ، فَـلَفْظَةُ الِْإنْـزَالِ أَخَصُّ مِنْ لَفْظَةِ الَْخلْقِ وَالْوَضْعِ، فَلَا يَـنْـبَغِي إِسْقَاطُ خُصُوصِ يهةِ اللهفْظَةِ بِلَا مُوجِبٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَقَالَتْ طَائِفَةٌ: إِنْـزَالُهمَُا بِوَاسِطَةِ الْمَلَائِكَةِ الْمُوَكهلِيَن بُِمبَاشَرَةِ الَْخلْقِ مِنْ دَاءٍ وَدَوَاءٍ وَغَيِْر ذَلِكَ ، فَإِنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'الْمَلَائِكَةَ مُوَكهلَةٌ بَِأمْرِ هَذَا الْعَالََِ، وَأَمْرِ النهـوْعِ الِْإنْسَانِِّي مِنْ حِيِن سُقُوطِهِ فِي رَحِمِ أُمِّهِ إِلَى حِيِن مَوْتِهِ، فَإِنْـزَالُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'الدهاءِ وَالدهوَاءِ مَعَ الْمَلَائِكَةِ، وَهَذَا أَقْـرَبُ مِنَ الْوَجْهَيِْن قَـبْـلَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَقَالَتْ طَائِفَةٌ: إِنه عَامهةَ الَْأدْوَاءِ وَالَْأدْوِيَةِ هِيَ بِوَاسِطَةِ إِنْـزَالِ الْغَيْثِ مِنَ السهمَاءِ الهذِي تَـتَـوَلهدُ بِهِ الَْأغْذِيَةُ، وَالَْأقْـوَاتُ ، وَالَْأدْوِيَةُ، وَالَْأدْوَاءُ، وَآلَاتُ  ذَلِكَ كُلِّهِ، وَأَسْبَابُهُ وَمُكَمِّلَاتُهُ، وَمَا كَانَ مِنْـهَا مِنَ الْمَعَادِنِ الْعُلْوِيهةِ، فَهِيَ تَـنْزِلُ مِنَ الِْجبَالِ، وَمَا كَانَ مِنْـهَا مِنَ الَْأوْدِيَةِ وَالَْأنْـهَارِ وَالثِّمَارِ، فَدَاخِلٌ فِي اللهفْظِ عَلَى طَرِيقِ التهـغْلِيبِ وَالِاكْ تِفَاءِ عَنِ الْفِعْلَيِْن بِفِعْلٍ وَاحِدٍ يَـتَضَمهنُـهُمَا، وَهُوَ مَعْرُوفٌ مِنْ لُغَةِ الْعَرَبِ، بَلْ وَغَيِْرهَا مِنَ الُْأمَمِ، كَقَوْلِ الشهاعِرِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'عَلَفْتُـهَا تِبْـنًا وَمَاءً بَارِدًا ... حَتَى غَدَتْ هَهُالَةً عَيْـنَاهَا ]7[ وَقَـوْلِ الْآخَرِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَرَأَيْتُ زَوْجَكِ قَدْ غَدَا ... مُتَـقَلِّدًا سَيْـفًا وَرُمْاًُ ]2[ وَقَـوْلِ الْآخَرِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'إِذَا مَا الْغَانِيَاتُ بَـرَزْنَ يَـوْمًا ... وَزَجهجْنَ الَْحوَاجِبَ وَالْعُيُونَا ]3[ وَهَذَا أَحْسَنُ مِمها قَـبْـلَهُ مِنَ الْوُجُوهِ وَا هللَُّ أَعْلَمُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَهَذَا من تاَم حكمة الرب عزوجل، وَتَاََمِ رُبُوبِيهتِهِ، فَإِنههُ كَمَا ابْـتَـلَى عِبَادَهُ بِالَْأدْوَاءِ، أَعَانَـهُمْ عَلَيْـهَا بَِما', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'يَسهرَهُ لَهمُْ مِنَ الَْأدْوِيَةِ، وَكَمَا ابْـتَلَاهُمْ بِالذُّنُوبِ أَعَانَـهُمْ عَلَيْـهَا بِالتهـوْبَةِ، وَالَْحسَنَاتِ الماحية والمصائب المفكرة، وَكَمَا ابْـتَلَاهُمْ بِالَْأرْوَاحِ الَْخبِيثَةِ مِنَ الشهيَاطِيِن، أَعَانَـهُمْ عَلَيْـهَا بِنُِْدٍ مِنَ الَْأرْوَاحِ الطهيِّبَةِ، وَهُمُ الْمَلَائِكَةُ. وَكَمَا ابْـتَلَاهُمْ بِالشههَوَاتِ أَعَانَـهُمْ عَلَى قَضَائِهَا بَِما يَسهرَهُ لَهمُْ شَرْعًا وَقَدَرًا مِنَ الْمُشْتَـهَيَاتِ اللهذِيذَةِ النهافِعَةِ، فَمَا ابْـتَلَاهُمْ سُبْحَانَهُ بِشَيْ ءٍ إِهلا أَعْطَاهُمْ مَا يَسْتَعِينُونَ بِهِ عَلَى ذَلِكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'الْبَلَاءِ، وَيَدْفَـعُونَهُ بِهِ، وَيَـبْـقَى التهـفَاوُتُ بَـيْـنَـهُمْ فِي الْعِلْمِ بِذَلِكَ ، وَالْعِلْمِ بِطَرِيقِ حُصُولِهِ وَالتهـوَصُّلِ إِلَيْهِ، وبالله المستعان.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي تَضْمِيِن مَنْ طَبه النهاسَ ، وَهُوَ جَاهِلٌ بِالطِّبِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى أبو داود، وَالنهسَائِيُّ، وَابْنُ مَاجَهْ، مِنْ حَدِيثِ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: قَالَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَنْ تَطَبهبَ وَلََْ يُـعْلَمْ مِنْهُ الطِّبُّ قَـبْلَ ذَلِكَ ، فَـهُوَ ضَامِنٌ» »7« هَذَا الَْحدِيثُ يَـتَـعَلهقُ بِهِ ثَلَاثَةُ أُمُورٍ: أَمْرٌ لُغَوِيٌّ، وَأَمْرٌ فِقْهِيٌّ، وَأَمْرٌ طِبٌِّّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'فَأَمها اللُّغَوِيُّ: فَالطِّبُّ بِكَسْرِ الطهاءِ فِي لُغَةِ الْعَرَبِ، يُـقَالُ: عَلَى مَعَانٍ. مِنْـهَا الِْإصْلَاحُ، يُـقَالُ: طَبهـبْـتُهُ: إِذَا أَصْلَحْتَهُ. وَيُـقَالُ: لَهُ طِبٌّ بِالُْأمُورِ. أَيْ : لُطْفٌ وَسِيَاسَةٌ. قَالَ الشهاعِرُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَإِذَا تَـغَيهـرَ مِنْ تَيَِمٍ أَمْرُهَا ... كُنْتَ الطهبِيبَ لََها بِرَأْيٍ ثَقَِبٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَمِنْـهَا: الِْحذْقُ. قَالَ الجوهري: كُلُّ حَاذِقٍ طَبِيبٌ عِنْدَ الْعَرَبِ، قَالَ أبو عبيد: أَصْلُ الطِّبِّ : الِْحذْقُ بِالَْأشْيَاءِ وَالْمَهَارَةُ بَِها. يُـقَالُ لِلهرجُلِ: طِبٌّ وَطَبِيبٌ :', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'إِذَا كَانَ كَذَلِكَ ، وَإِنْ كَانَ فِي غَيِْر عِلَاجِ الْمَرِيضِ . وَقَالَ غَيْـرُهُ: رَجُلٌ طَبِيبٌ : أَيْ حَاذِقٌ ، سُِّميَ طَبِيبًا لِِحذْقِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَفِطْنَتِهِ. قَالَ علقمة:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'فَإِنْ تَسْأَلُونِي بِالنِّسَاءِ فَإِنهنِِ ... خَبِيٌر بِْأدْوَاءِ النِّسَاءِ طَبِيبُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'إِذَا شَابَ رَأْسُ الْمَرْءِ أَوْ قَله مَالُهُ ... فَـلَيْسَ لَهُ مِنْ وُدِّهِنه نَصِيبُ وَقَالَ عنترة:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'إِنْ تُـغْدِ فِي دُونِي الْقِنَاعَ فَإِنهنِِ ... طِبٌّ بأخد الفارس المستلئم', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, '(7) أخرجه أبو داود والنسائي متصلا ومنقطعا، وابن ماجه في الديات، والحاكم في الطب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'أَيْ : إِنْ تُـرْخِي عَنِِّ قِنَاعَكِ ، وَتَسْتُِري وَجْ هَكِ رَغْبَةً عَنِِّ، فَإِنِّي خَبِيٌر حَاذِقٌ بَِأخْذِ الْفَارِسِ الهذِي قَدْ لَبِسَ لَْأمَةَ حَرْبِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَمِنْـهَا: الْعَادَةُ، يُـقَالُ: لَيْسَ ذَاكَ بِطِبِّ، أَيْ : عَادَتِي، قَالَ فروة بن مسيك ]3[', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'فَمَا إِنْ طِبُّـنَا جُبٌْن وَلَكِنْ ... مَنَايَانَا وَدَوْلَةُ آخَرِينَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَقَالَ أحدْ بن الحسين المتنب:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَمَا التِّيهُ طِبِّ فِيهِمْ غَيْـرَ أَنهنِِ ... بَغِيضٌ إِلَهِ الَْجاهِلُ الْمُتَـعَاقِلُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَمِنْـهَا: السِّ حْرُ، يُـقَالُ: رَجُلٌ مَطْبُوبٌ ، أَيْ : مَسْحُورٌ، وَفِي «الصهحِيحِ» فِي حَدِيثِ عائشة لَمها سَحَرَتْ يَـهُودُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَجَلَسَ الْمَلَكَانِ عِنْدَ رَأْسِهِ وَعِنْدَ رِجْلَيْهِ، فَـقَالَ أَحَدُهُاَُ: مَا بَالُ الهرجُلِ؟ قَالَ الْآخَرُ: مَطْبُوبٌ . قَالَ: مَنْ طَبههُ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'قَالَ: فُلَانٌ الْيَـهُودِيُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'قَالَ أبو عبيد: إِهنَما قَالُوا لِلْمَسْحُورِ: مَطْبُوبٌ ، لَِأنهـهُمْ كَنهـوْا بِالطِّبِّ عَنِ السِّ حْرِ، كَمَا كَنهـوْا عَنِ اللهدِيغِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'فَـقَالُوا: سَلِيمٌ تَـفَاؤُلًا بِالسهلَامَةِ، وَكَمَا كَنهـوْا بِالْمَفَازَةِ عَنِ الْفَلَاةِ الْمُهْلِكَةِ الهتِي لَا مَاءَ فِيهَا، فَـقَالُوا: مَفَازَةٌ تَـفَاؤُلًا بِالْفَوْزِ مِنَ الَْهلَاكِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَيُـقَالُ: الطِّبُّ لِنَـفْسِ الدهاءِ. قَالَ ابْنُ أَبِي الَْأسْلَتِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'أَلَا مَنْ مُبْلِغٌ حَسهانَ عَنِِّ ... أَسِحْرٌ كَانَ طِبُّكَ أَمْ جُنُونُ وَأَمها قَـوْلُ الحماسي:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'فَإِنْ كُنْتُ مَطْبُوبًا فَلَا زِلْتُ هَكَذَا ... وَإِنْ كُنْتُ مَسْحُورًا فلا برىء السِّ حْرُ فَإِنههُ أَرَادَ بِالْمَطْبُوبِ الهذِي قَدْ سُحِرَ، وَأَرَادَ بِالْمَسْحُورِ: الْعَلِيلُ بِالْمَرَضِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'قَالَ الجوهري: وَيُـقَالُ لِلْعَلِيلِ: مَسْحُورٌ. وَأَنْشَدَ الْبَـيْتَ . وَمَعْنَاهُ: إِنْ كَانَ هَذَا الهذِي قَدْ عَرَانِي مِنْكِ وَمِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'حُبِّكِ أَسْأَلُ ا هللََّ دَوَامَهُ، وَلَا أُرِيدُ زَوَالَهُ، سَوَاءٌ كَانَ سِحْ رًا أَوْ مَرَضًا. وَالطِّبُّ: مُثَـلهثُ الطهاءِ، فَالْمَفْتُوحُ الطهاءِ: هُوَ الْعَالَُِ بِالُْأمُورِ، وَكَذَلِكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'الطهبِيبُ يُـقَالُ لَهُ: طَبٌّ أَيْضًا. وَالطِّبُّ: بِكَسْرِ الطهاءِ: فِعْلُ الطهبِيبِ، وَالطُّبُّ بِضَمِّ الطهاءِ: اسْمُ مَوْضِ عٍ، قَالَهُ ابن السيد، وَأَنْشَدَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'فَـقُلْتُ هَلِ انْـهَلْتُمْ بِطُبِّ ركَِابِكُمْ ... بِاَِئِزَةِ الْمَاءِ الهتِي طَابَ طِينُـهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَقَـوْلُهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَنْ تَطَبهبَ » ، وَلََْ يَـقُلْ: مَنْ طَبه ، لَِأنه لَفْظَ التهـفَعُّلِ يَدُلُّ عَلَى تَكَلُّفِ الشهيْ ءِ وَالدُّخُولِ فِيهِ بِعُسْرٍ وَكُلْفَةٍ، وَأَنههُ لَيْسَ مِنْ أَهْلِهِ، كَ تَحَلهمَ وَتَشَجهعَ وَتَصَبهـرَ وَنَظَائِرِهَا، وَكَذَلِكَ بَـنَـوْا تَكَلهفَ عَلَى هَذَا الْوَزْنِ ، قَالَ الشهاعِرُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'وَقَـيْسُ عَيْلَانَ وَمَنْ تَـقَيهسَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَأَمها الَْأمْرُ الشهرْعِيُّ، فَإِيَجابُ الضهمَانِ عَلَى الطهبِيبِ الَْجاهِلِ، فَإِذَا تَـعَاطَى عِلْمَ الطِّبِّ وَعَمَلَهُ، وَلََْ يَـتَـقَدهمْ لَهُ بِهِ مَعْرِفَةٌ، فَـقَدْ هَجَمَ بِهَِْلِهِ عَلَى إِتْلَافِ الَْأنْـفُسِ ، وَأَقْدَمَ بِالتهـهَوُّرِ عَلَى مَا لََْ يَـعْلَمْهُ، فَـيَكُونُ قَدْ غَهررَ بِالْعَلِيلِ، فَـيَـلْزَمُهُ الضهمَانُ لِذَلِكَ ، وَهَذَا إِجْاََعٌ مِنْ أَهْلِ العلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'وقال الخطابي: لَا أَعْلَمُ خِلَافًا فِي أَنه الْمُعَالِجَ إِذَا تَـعَدهى، فَـتَلِفَ الْمَرِيضُ كَانَ ضَامِنًا، وَالْمُتَـعَاطِي عِلْمًا أَوْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'عَمَلًا لَا يَـعْرِفُهُ مُتَـعَدٍّ، فَإِذَا تَـوَلهدَ مِنْ فِعْلِهِ التهـلَفُ ضَمِنَ الدِّيَةَ، وَسَقَطَ عَنْهُ الْقَوَدُ، لَِأنههُ لَا يَسْتَبِدُّ بِذَلِكَ بِدُونِ إِذْنِ الْمَرِيضِ وَجِنَايَةُ الْمُتَطَبِّبِ فِي قَـوْلِ عَامهةِ الفقهاء على عاقلته.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'قُـلْتُ : الَْأقْسَامُ خَْمسَةٌ: أَحَدُهَا: طَبِيبٌ حَاذِقٌ أَعْطَى الصهنْـعَةَ حَقههَا وَلََْ تَنَِْ يَدُهُ، فَـتَـوَلهدَ مِنْ فِعْلِهِ الْمَأْذُونِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'فِيهِ مِنْ جِهَةِ الشهارعِِ ، وَمِنْ جِهَةِ مَنْ يَطِبُّهُ تَـلَفُ الْعُضْوِ أَوِ النهـفْسِ ، أَوْ ذَهَابُ صِفَةٍ، فَـهَذَا لَا ضَمَانَ عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'اتِّفَاقًا، فَإِنهـهَا سِرَايَةُ مَأْذُونٍ فِيهِ، وَهَذَا كَمَا إِذَا خَتََُ الصهبِه فِي وَقْتٍ، وَسِنُّهُ قَابِلٌ لِلْخِتَانِ، وَأَعْطَى الصهنْـعَةَ حَقههَا، فَـتَلِفَ الْعُضْوُ أَوِ الصهبُِّ، لََْ يَضْمَنْ ، وَكَذَلِكَ إِذَا بَطه مِنْ عَاقِلٍ أَوْ غَيِْرهِ مَا يَـنْـبَغِي بَطُّهُ فِي وَقْتِهِ عَلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'الْوَجْهِ الهذِي يَـنْـبَغِي فَـتَلِفَ بِهِ، لََْ يَضْمَنْ ، وَهَكَذَا سِرَايَةُ كُلِّ مَأْذُونٍ فِيهِ لََْ يَـتَـعَده الْفَاعِلُ فِي سَبَبِهَا، كَسِرَايَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'الَْحدِّ بِالِاتِّفَاقِ. وَسِرَايَةُ الْقِصَاصِ عِنْدَ الُْجمْهُورِ خِلَافًا لأبي حنيفة في إيجابه الضمان بها، وسراية التعزيز،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'وَضَرْبِ الهرجُلِ امْرَأَتَهُ، وَالْمُعَلِّمِ الصهبِه، وَالْمُسْتَأْجِرِ الدهابهةَ، خِلَافًا لأبي حنيفة وَالشهافِعِيِّ فِي إِيَجابِِهمَا الضهمَانَ فِي ذَلِكَ ، وَاسْتَـثْـنَى الشهافِعِيُّ ضَرْبَ الدهابهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'وَقَاعِدَةُ الْبَابِ إِجْاََعًا وَنِزَاعًا: أَنه سِرَايَةَ الِْجنَايَةِ مَضْمُونَةٌ بِالِاتِّفَاقِ، وَسِرَايَةُ الْوَاجِبِ مُهْدَرَةٌ بِالِاتِّفَاقِ، وَمَا بَـيْـنَـهُمَا فَفِيهِ النِّزَاعُ. فأبو حنيفة أَوْجَبَ ضَمَانَهُ مُطْلَقًا، وأحدْ ومالك أَهْدَرَا ضَمَانَهُ، وَفَـهرقَ الشهافِعِيُّ بَـيَْن الْمُقَدهرِ، فَأَهْدَرَ ضَمَانَهُ، وَبَـيَْن غَيِْر الْمُقَدهرِ فَأَوْجَبَ ضَمَانَهُ. فأبو حنيفة نَظَرَ إِلَى أَنه الِْإذْنَ فِي الْفِعْلِ إِهنَما وَقَعَ مَشْرُوطًا بِالسهلَامَةِ، وأحدْ ومالك نَظَرَا إِلَى أَنه الِْإذْنَ أَسْقَطَ الضهمَانَ، وَالشهافِعِيُّ نَظَرَ إِلَى أَنه الْمُقَدهرَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'لَا يُْمكِنُ النُّـقْصَانُ مِنْهُ، فَـهُوَ بَِمنْزِلَةِ النهصِّ ، وَأَمها غَيْـرُ الْمُقَدهرِ كَالتهـعْزِيرَاتِ، وَالتهأْدِيبَاتِ، فَاجْ تِهَادِيهةٌ، فَإِذَا تَلِفَ بها، ضمن، لأنه في مظنّة العدوان.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'القسم الثاني: متطبّب جَاهِلٌ بَاشَرَتْ يَدُهُ مَنْ يَطِبُّهُ، فَـتَلِفَ بِهِ، فَـهَذَا إِنْ عَلِمَ الْمَجْنُِِّ عَلَيْهِ أَنههُ جَاهِلٌ لَا عِلْمَ لَهُ، وَأَذِنَ لَهُ فِي طِبِّهِ لََْ يَضْمَنْ ، وَلَا تَُخالِفُ هَذِهِ الصُّورَةُ ظَاهِرَ الَْحدِيثِ ، فَإِنه السِّ يَاقَ وَقُـهوةَ الْكَلَامِ يَدُلُّ عَلَى أَنههُ غَهر الْعَلِيلَ، وَأَوْهَهَُُ أَنههُ طَبِيبٌ ، وَلَيْسَ كَذَلِكَ ، وَإِنْ ظَنه الْمَرِيضُ أَنههُ طَبِيبٌ ، وَأَذِنَ لَهُ فِي طَبِّهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'لَِأجْلِ مَعْرِفَتِهِ، ضَمِنَ الطهبِيبُ مَا جَنَتْ يَدُهُ، وَكَذَلِكَ إِنْ وَصَفَ لَهُ دَوَاءً يَسْتَـعْمِلُهُ، وَالْعَلِيلُ يَظُنُّ أَنههُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَصَفَهُ لِمَعْرِفَتِهِ وَحِذْقِهِ فَـتَلِفَ بِهِ، ضَمِنَهُ، وَالَْحدِيثُ ظَاهِرٌ فِيهِ أو صريح. فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الْقِسْمُ الثهالِثُ : طَبِيبٌ حَاذِقٌ ، أَذِنَ لَهُ، وَأَعْطَى الصهنْـعَةَ حَقههَا، لَكِنههُ أَخْطَأَتْ يَدُهُ، وَتَـعَدهتْ إِلَى عُضْوٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'صَحِيحٍ فَأَتْـلَفَهُ، مِثْلَ: أَنْ سَبَـقَتْ يَدُ الَْخاتِنِ إِلَى الْكَمَرَةِ، فَـهَذَا يَضْمَنُ، لَِأنهـهَا جِنَايَةُ خَطَأٍ، ُ مه إِنْ كَانَتِ الثُّـلُثَ فَمَا زَادَ، فَـهُوَ عَلَى عَاقِلَتِهِ، فَإِنْ لََْ تَكُنْ عَاقِلَةٌ، فَـهَلْ تَكُونُ الدِّيَةُ فِي مَالِهِ، أَوْ فِي بَـيْتِ الْمَالِ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'عَلَى قَـوْلَيِْن، هُاَُ رِوَايَـتَانِ عَنْ أحدْ. وَقِيلَ: إِنْ كَانَ الطهبِيبُ ذِمِّيًّا، فَفِي مَالِهِ، وَإِنْ كَانَ مُسْلِمًا، فَفِيهِ الرِّوَايَـتَانِ، فَإِنْ لََْ يَكُنْ بَـيْتُ مَالٍ، أَوْ تَـعَذهرَ تَمَِْيلُهُ، فَـهَلْ تَسْقُطُ الدِّيَةُ، أَوْ تَبَُِ فِي مال الجاني؟ فيه وجهان أشهرهاُ: سقوطها.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'الْقِسْمُ الهرابِعُ: الطهبِيبُ الَْحاذِقُ الْمَاهِرُ بِصَنَاعَتِهِ، اجْتَـهَدَ فَـوَصَفَ لِلْمَرِيضِ دَوَاءً، فَأَخْطَأَ فِي اجْتِهَادِهِ، فَـقَتَـلَهُ، فَـهَذَا يَُخهرجُ عَلَى رِوَايَـتَـيِْن: إِحْدَاهُاَُ: أَنه دِيَةَ الْمَرِيضِ فِي بَـيْتِ الْمَالِ. وَالثهانِيَةُ: أَنهـهَا عَلَى عَاقِلَةِ الطهبِيبِ ، وَقَدْ نَصه عَلَيْهِمَا الِْإمَامُ أحدْ في خطأ الإمام والحاكم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'الْقِسْمُ الَْخامِسُ : طَبِيبٌ حَاذِقٌ ، أَعْطَى الصهنْـعَةَ حَقههَا، فَـقَطَعَ سِلْعَةً »7« مِنْ رَجُلٍ أَوْ صَبٍِّ، أَوْ مَنَُْونٍ بِغَيِْر إِذْنِهِ، أَوْ إِذْنِ وَلِيِّهِ، أَوْ خَتََُ صَبِيًّا بِغَيِْر إِذْنِ وَلِيِّهِ فَـتَلِفَ ، فَـقَالَ أَصْحَابُـنَا: يَضْمَنُ، لَِأنههُ تَـوَلهدَ مِنْ فِعْلٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'غَيِْر مَأْذُونٍ فِيهِ، وَإِنْ أَذِنَ لَهُ الْبَالِغُ، أَوْ وَلُِِّ الصهبِِّ وَالْمَجْ نُونِ، لََْ يَضْمَنْ ، وَيَْحتَمِلُ ألايضمن مُطْلَقًا لَِأنههُ مُسُِْنٌ، وَمَا عَلَى الْمُحْسِنِيَن مِنْ سَبِيلٍ. وَأَيْضًا فَإِنههُ إِنْ كَانَ مُتَـعَدِّيًا، فَلَا أَثَـرَ لِِإذْنِ الْوَلِِِّ فِي إِسْقَاطِ الضهمَانِ، وَإِنْ لََْ يَكُنْ مُتَـعَدِّيًا، فَلَا وَجْ هَ لِضَمَانِهِ. فَإِنْ قُـلْتَ : هُوَ مُتَـعَدٍّ عِنْدَ عَدَمِ الِْإذْنِ، غَيْـرُ مُتَـعَدٍّ عِنْدَ الِْإذْنِ، قُـلْتُ : الْعُدْوَانُ وَعَدَمُهُ إِهنَما يَـرْجِعُ إِلَى فِعْلِهِ هُوَ، فَلَا أَثَـرَ لِلِْذْْنِ وعدمه فيه، وهذا موضع نظر.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَالطهبِيبُ فِي هَذَا الَْحدِيثِ يَـتَـنَاوَلُ مَنْ يَطِبُّ بِوَصْفِهِ وَقَـوْلِهِ، وَهُوَ الهذِي يَُخصُّ بِاسْمِ الطهبَائِعِيِّ، ويمروده، وَهُوَ الْكَحهالُ، وَبِِمبْضَعِهِ وَمَرَاهِِهُِ وَهُوَ الَْجرَائِحِيُّ، وَبُِموسَاهُ وَهُوَ الَْخاتِنُ، وَبِرِيشَتِهِ وَهُوَ الْفَاصِدُ، وَبَِمحَاجِِهَِ وَمِشْرَطِهِ وَهُوَ الَْحجهامُ، وَخِلَِْعِهِ وَوَصْلِهِ وَرِبَاطِهِ وَهُوَ الْمُجَبَُِّ، وَبِِمكْ وَاتِهِ وَنَارِهِ وَهُوَ الْكَ هواءُ، وَبِقِرْبَتِهِ وَهُوَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الَْحاقِنُ، وَسَوَاءٌ كَانَ طِبُّهُ لَِحيَـوَانٍ بَِهيمٍ، أَوْ إِنْسَانٍ، فاسم الطبيب يطلق لغة على', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(7) السّلعة: زيادة تدَث في البدن كالغدة تتحرك إذا حركت', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'هَؤُلَاءِ كُلِّهِمْ، كَمَا تَـقَدهمَ، وَتَْخصِيصُ النهاسِ لَهُ بِبَـعْضِ أَنْـوَاعِ الَْأطِبهاءِ عُرْفٌ حَادِثٌ ، كَتَخْصِيصِ لَفْظِ الدهابهةِ بَِما يَُخصُّهَا بِهِ كُلُّ قَـوْمٍ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَالطهبِيبُ  الَْحاذِقُ : هُوَ الهذِي يُـرَاعِي فِي عِلَاجِهِ عِشْرِينَ  أَمْرًا: أَحَدُهَا: النهظَرُ فِي نَـوْعِ الْمَرَضِ مِنْ أَيِّ الَْأمْرَاضِ هُوَ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الثهانِي: النهظَرُ فِي سَبَبِهِ مِنْ أَيِّ شَيْ ءٍ حَدَثَ ، وَالْعِلهةُ الْفَاعِلَةُ الهتِي كَانَتْ سَبَبَ حُدُوثِهِ مَا هِيَ ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الثهالِثُ : قُـهوةُ الْمَرِيضِ ، وَهَلْ هِيَ مُقَاوِمَةٌ لِلْمَرَضِ ، أَوْ أضعف منه؟ فإذا كَانَتْ مُقَاوِمَةً لِلْمَرَضِ ، مُسْتَظْهِرَةً عَلَيْهِ، تَـرَكَهَا وَالْمَرَضَ ، وَلََْ يَُحرِّكْ بِالدهوَاءِ سَاكِنًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الهرابِعُ: مِزَاجُ الْبَدَنِ الطهبِيعِيُّ مَا هُوَ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الَْخامِسُ : الْمِزَاجُ الَْحادِثُ عَلَى غَيِْر الْمُجْ رَى الطهبِيعِيِّ. السهادِسُ : سِنُّ الْمَرِيضِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'السهابِعُ: عَادَتُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الثهامِنُ: الْوَقْتُ الَْحاضِرُ مِنْ فُصُولِ السهنَةِ وَمَا يَلِيقُ بِهِ. التهاسِعُ: بَـلَدُ الْمَرِيضِ وَتُـرْبَـتُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'الْعَاشِرُ: حَالُ الَْهوَاءِ فِي وَقْتِ الْمَرَضِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'الَْحادِيَ عَشَرَ: النهظَرُ فِي الدهوَاءِ الْمُضَادِّ لِتِلْكَ الْعِلهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'الثهانَِي عَشَرَ: النهظَرُ فِي قُـهوةِ الدهوَاءِ وَدَرَجَتِهِ، وَالْمُوَازَنَةُ بَـيْـنَـهَا وَبَـيَْن قُـهوةِ الْمَرِيضِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'الثهالِثَ عَشَرَ: أَهلا يَكُونَ كُلُّ قَصْدِهِ إِزَالَةَ تِلْكَ الْعِلهةِ فَـقَطْ ، بَلْ إِزَالَتُـهَا عَلَى وَجْهٍ مَََْنُ مَعَهُ حُدُوثَ أَصْعَبَ مِنْـهَا، فَمَتَى كَانَ إِزَالَتُـهَا لَا مَََْنُ مَعَهَا حُدُوثَ عِلهةٍ أُخْ رَى أَصْعَبَ مِنْـهَا، أَبْـقَاهَا عَلَى حَالَِها، وَتَـلْطِيفُهَا هُوَ الْوَاجِبُ ، وَهَذَا كَمَرَضِ أَفْـوَاهِ الْعُرُوقِ، فَإِنههُ مَتَى عُولِجَ بِقَطْعِهِ وَحَبْسِهِ خِيفَ حُدُوثُ مَا هُوَ أَصْعَبُ مِنْهُ. الهرابِعَ عَشَرَ: أَنْ يُـعَالِجَ بِالَْأسْهَلِ فَالَْأسْهَلِ، فَلَا يَـنْـتَقِلُ مِنَ الْعِلَاجِ بِالْغِذَاءِ إِلَى الدهوَاءِ إِهلا عِنْدَ تَـعَذُّرِهِ، وَلَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'يَـنْـتَقِلُ إِلَى الدهوَاءِ الْمُرَكهبِ إِهلا عِنْدَ تَـعَذُّرِ الدهوَاءِ الْبَسِيطِ فَمِنْ حِذْقِ الطهبِيبِ عِلَاجُهُ بِالَْأغْذِيَةِ بَدَلَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'الَْأدْوِيَةِ، وَبِالَْأدْوِيَةِ الْبَسِيطَةِ بدل المركبة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'الَْخامِسَ عَشَرَ: أَنْ يَـنْظُرَ فِي الْعِلهةِ، هَلْ هي مما يمكن علاجها أولا؟ فَإِنْ لََْ يُْمكِنْ عِلَاجُهَا، حَفِظَ صِ نَاعَتَهُ وَحُرْمَتَهُ، وَلَا يَْحمِلُهُ الطهمَعُ عَلَى عِلَاجٍ لَا يُفِيدُ شَيْـئًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَإِنْ أَمْكَنَ عِلَاجُهَا، نَظَرَ هَلْ يُْمكِنُ زَوَالَُها أَمْ لَا؟ فَإِنْ عَلِمَ أَنههُ لَا يُْمكِنُ زَوَالَُها، نَظَرَ هَلْ يُْمكِنُ تَْخفِيفُهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَتَـقْلِيلُهَا أم لا؟ فإن لَ يمكن تَـقْلِيلُهَا، وَرَأَى أَنه غَايَةَ الِْإمْكَانِ إِيقَافُـهَا وَقَطْعُ زِيَادَتَِها، قَصَدَ بِالْعِلَاجِ ذَلِكَ ، وَأَعَانَ الْقُهوةَ، وَأَضْعَفَ الْمَادهةَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'السهادِسَ عَشَرَ: أَهلا يَـتَـعَهرضَ لِلْخَلْطِ قَـبْلَ نُضْجِهِ بِاسْتِفْرَاغٍ ، بَلْ يَـقْصِدُ إِنْضَاجَهُ، فَإِذَا تَمه نُضْجُهُ، بَادَرَ إِلَى اسْتِفْرَاغِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'السهابِعَ عَشَرَ: أَنْ يَكُونَ لَهُ خِبْـرَةٌ بِاعْتِلَالِ الْقُلُوبِ وَالَْأرْوَاحِ وَأَدْوِيَتِهَا، وَذَلِكَ أَصْلٌ عَظِيمٌ فِي عِلَاجِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'الَْأبْدَانِ، فَإِنه انْفِعَالَ الْبَدَنِ وَطَبِيعَتَهُ عَنِ النهـفْسِ وَالْقَلْبِ أَمْرٌ مَشْهُودٌ، وَالطهبِيبُ إِذَا كَانَ عَارِفًا بَِأمْرَاضِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'الْقَلْبِ وَالرُّوحِ وَعِلَاجِهِمَا، كَانَ هُوَ الطهبِيبَ الْكَامِلَ، وَالهذِي لَا خِبْـرَةَ لَهُ بِذَلِكَ وَإِنْ كَانَ حَاذِقًا فِي عِلَاجِ الطهبِيعَةِ وَأَحْ وَالِ الْبَدَنِ نِصْفُ طَبِيبٍ. وَكُلُّ طَبِيبٍ لَا يُدَاوِي الْعَلِيلَ، بِتَـفَقُّدِ قَـلْبِهِ وَصَلَاحِهِ، وَتَـقْوِيَةِ رُوحِهِ وَقُـوَاهُ بِالصهدَقَةِ، وَفِعْلِ الَْخيِْر، وَالِْإحْسَانِ، وَالِْإقْـبَالِ عَلَى ا هلِلَّ وَالدهارِ الْآخِرَةِ، فَـلَيْسَ بِطَبِيبٍ ، بَلْ مُتَطَبِّبٌ قَاصِرٌ. وَمِنْ أَعْظَمِ عِلَاجَاتِ الْمَرَضِ فِعْلُ الَْخيِْر وَالِْإحْسَانُ وَالذِّكْرُ وَالدُّعَاءُ، وَالتهضَرُّعُ وَالِابْتِهَالُ إِلَى ا هلِلَّ، وَالتهـوْبَةُ، وَلِهذَِهِ الُْأمُورِ تَثَِْيٌر فِي دَفْعِ الْعِلَلِ، وَحُصُولِ الشِّ فَاءِ أَعْظَمُ مِنَ الَْأدْوِيَةِ الطهبِيعِيهةِ، وَلَكِنْ بَِحسَبِ اسْتِعْدَادِ النهـفْسِ وَقَـبُولَِها وَعَقِيدَتَِها فِي ذَلِكَ وَنَـفْعِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'الثهامِنَ عَشَرَ: التهـلَطُّفُ بِالْمَرِيضِ ، وَالرِّفْقُ بِهِ، كَالتهـلَطُّفِ بِالصهبِِّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'التهاسِعَ عَشَرَ: أَنْ يَسْتَـعْمِلَ أَنْـوَاعَ الْعِلَاجَاتِ الطهبِيعِيهةِ وَالِْإلَِهيهةِ، وَالْعِلَاجَ بِالتهخْيِيلِ، فَإِنه لُِحذهاقِ الَْأطِبهاءِ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'التهخْيِيلِ أُمُورًا عَجِيبَةً لَا يَصِلُ إِلَيْـهَا الدهوَاءُ، فَالطهبِيبُ الَْحاذِقُ يَسْتَعِيُن عَلَى الْمَرَضِ بِكُلِّ مُعِيٍن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'الْعِشْرُونَ: - وَهُوَ مِلَاكُ أَمْرِ الطهبِيبِ -، أَنْ يَْجعَلَ عِلَاجَهُ وَتَدْبِيَرهُ دَائِرًا عَلَى سِتهةِ أَرْكَانٍ: حِفْظُ الصِّحهةِ الْمَ وْجُودَةِ، وَرَدُّ الصِّحهةِ الْمَفْقُودَةِ بَِحسَبِ الِْإمْكَانِ، وَإِزَالَةُ الْعِلهةِ أَوْ تَـقْلِيلُهَا بَِحسَبِ الِْإمْكَانِ، وَاحْتِمَالُ أَدْنََ الْمَفْسَدَتَـيِْن لِِإزَالَةِ أَعْظَمِهِمَا، وَتَـفْوِيتُ أَدْنََ الْمَصْلَحَتَـيِْن لِتَحْصِيلِ أَعْظَمِهِمَا، فَـعَلَى هَذِهِ الُْأصُولِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'السِّ تهةِ مَدَارُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'الْعِلَاجِ، وَكُلُّ طَبِيبٍ لَا تَكُونُ هَذِهِ أَخِيهـتَهُ »7« الهتِي يَـرْجِعُ إِلَيْـهَا، فَـلَيْسَ بِطَبِيبٍ، وَا هللَُّ أَعْلَمُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَلَمها كَانَ لِلْمَرَضِ أَرْبَـعَةُ أَحْ وَالٍ: ابْتِدَاءٌ، وَصُعُودٌ، وَانْتِهَاءٌ، وَانِْطَْاطٌ، تَـعَهيَن عَلَى الطهبِيبِ مُرَاعَاةُ كُلِّ حَالٍ مِنْ أَحْ وَالِ الْمَرَضِ بَِما يُـنَاسِبُـهَا وَيَلِيقُ بَِها، وَيَسْتَـعْمِلُ فِي كُلِّ حَالٍ مَا يَِجبُ اسْتِعْمَالُهُ فِيهَا. فَإِذَا رَأَى فِي ابْتِدَاءِ الْمَرَضِ أَنه الطهبِيعَةَ مُتَُْاجَةٌ إِلَى مَا يَُحرِّكُ الْفَضَلَاتِ وَيَسْتَـفْرِغُهَا لِنُضْجِهَا، بَادَرَ إِلَيْهِ، فَإِنْ فَاتَهُ تَرَِْيكُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الطهبِيعَةِ فِي ابْتِدَاءِ الْمَرَضِ لِعَائِقٍ مَنَعَ مِنْ ذَلِكَ ، أَوْ لِضَعْفِ الْقُهوةِ وَعَدَمِ احْ تِمَالَِها للاستفراغ، أو لبوَدة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الفصل، أو لتفريط رقع، فَـيَـنْـبَغِي أَنْ يَْحذَرَ كُله الَْحذَرِ أَنْ يَـفْعَلَ ذَلِكَ فِي صُعُودِ الْمَرَضِ ، لَِأنههُ إِنْ فَـعَلَهُ، تَيََهـرَتِ الطهبِيعَةُ لِاشْتِغَالَِها بِالدهوَاءِ، وَتََخلهتْ عَنْ تَدْبِيِر الْمَرَضِ وَمُقَاوَمَتِهِ بِالْكُلِّيهةِ، وَمِثَالُهُ: أَنْ يَِجيءَ إِلَى فارس مشغول بموافقة عَدُوِّهِ، فَـيَشْغَلَهُ عَنْهُ بَِأمْرٍ آخَرَ. وَلَكِنه الْوَاجِبَ فِي هَذِهِ الَْحالِ أَنْ يُعِيَن الطهبِيعَةَ عَلَى حِفْظِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الْقُهوةِ مَا أَمْكَنَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'فَإِذَا انْـتَـهَى الْمَرَضُ وَوَقَفَ وَسَكَنَ، أَخَذَ فِي اسْتِفْرَاغِهِ، وَاسْتِئْصَالِ أَسْبَابِهِ، فَإِذَا أَخَذَ فِي الِانِْطَْاطِ، كَانَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'أَوْلَى بِذَلِكَ . وَمِثَالُ هَذَا مِثَالُ الْعَدُوِّ إِذَا انْـتَـهَتْ قُـهوتُهُ، وَفَـرَغَ سِلَاحُهُ، كَانَ أَخْذُهُ سَهْلًا، فَإِذَا وَهلى وَأَخَذَ فِي الَْهرَبِ، كَانَ أَسْهَلَ أَخْذًا، وَحِدهتُهُ وَشَوْكَتُهُ إِهنَما هِيَ فِي ابْتِدَائِهِ، وَحَالِ اسْتِفْرَاغِهِ، وَسَعَةِ قُـهوتِهِ، فَـهَكَذَا الدهاءُ وَالدهوَاءُ سَوَاءٌ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَمِنْ حِذْقِ الطهبِيبِ أَنههُ حَيْثُ أَمْكَنَ التهدْبِيُر بِالَْأسْهَلِ، فَلَا يَـعْدِلُ إِلَى الَْأصْعَبِ، وَيَـتَدَرهجُ مِنَ الَْأضْعَفِ إِلَى الَْأقْـوَى إِهلا أَنْ يََخافَ فَـوْتَ القوة حينئذ، فيجب أن يبتدىء بِالَْأقْـوَى، وَلَا يُقِيمَ فِي الْمُعَالََجةِ عَلَى حَالٍ واحدة فتألفها الطبيعة، ويقل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '(7) الأخية بزنة أبية: الحرمة والذمة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'انْفِعَالَُها عَنْهُ، وَلَا تَسَُْرُ عَلَى الَْأدْوِيَةِ الْقَوِيهةِ فِي الْفُصُولِ الْقَوِيهةِ، وَقَدْ تَـقَدهمَ أَنههُ إِذَا أَمْكَنَهُ الْعِلَاجُ بِالْغِذَاءِ، فَلَا يُـعَالِجُ بِالدهوَاءِ، وَإِذَا أَشْكَلَ عَلَيْهِ الْمَرَضُ أَحَارٌّ هُوَ أَمْ بَارِدٌ؟ فَلَا يُـقْدِمُ حَ هتى يَـتَـبَـهيَن لَهُ، وَلَا يَُجرِّبُهُ بَِما يََخافُ عَاقِبَـتَهُ، وَلَا بَْأسَ بِتَجْرِبَتِهِ بَِما لَا يَضُرُّ أَثَـرُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَإِذَا اجْتَمَعَتْ أَمْرَاضٌ ، بَدَأَ بَِما تَُخصُّهُ وَاحِدَةٌ مِنْ ثَلَاثِ خِصَالٍ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'إِحْدَاهَا: أَنْ يَكُونَ بُـرْءُ الْآخَرِ مَوْقُوفًا عَلَى بُـرْئِهِ كَالْوَرَمِ وَالْقُرْحَةِ، فَإِنههُ يَـبْدَأُ بِالْوَرَمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الثهانِيَةُ: أَنْ يَكُونَ أَحَدُهَا سَبَـبًا لِلْخَْرِ، كَالسُّدهةِ وَالُْحمهى الْعَفِنَةِ، فَإِنههُ يَـبْدَأُ بِِإزَالَةِ السهبَبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الثهالِثَةُ: أَنْ يَكُونَ أَحَدُهُاَُ أَهَمه مِنَ الْآخَرِ، كَالَْحادِّ وَالْمُزْمِنِ، فَـيَـبْدَأُ بالحاد، ومع هذا فلا يغافل عَنِ الْآخَرِ. وَإِذَا اجْتَمَعَ الْمَرَضُ وَالْعَرَضُ ، بَدَأَ بِالْمَرَضِ ، إِهلا أَنْ يَكُونَ الْعَرَضُ أَقْـوَى كَالْقُولَنْجِ »7« ، فَـيُسَكِّنَ الْوَجَعَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'أَهولًا، ُ مه يُـعَالِجَ السُّدهةَ، وَإِذَا أَمْكَنَهُ أَنْ يَـعْتَاضَ عَنِ الْمُعَالََجةِ بِالِاسْتِفْرَاغِ بِالُْجوعِ أَوِ الصهوْمِ أَوِ النهـوْمِ، لََْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'يَسْتَـفْرِغْهُ، وَكُلُّ صِحهةٍ أَرَادَ حِفْظَهَا، حَفِظَهَا بِالْمِثْلِ أَوِ الشهبَهِ، وَإِنْ أَرَادَ نَـقْلَهَا إِلَى مَا هُوَ أَفْضَلُ منها، نقلها بالضد.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي التهحَرُّزِ مِنَ الَْأدْوَاءِ الْمُعْدِيَةِ بِطَبْعِهَا وَإِرْشَادِهِ الَْأصِحهاءَ إِلَى مُاََنَـبَةِ أَهْلِهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'ثَـبَتَ فِي «صَحِيحِ مسلم» مِنْ حَدِيثِ جَابِرِ بْنِ عَبْدِ ا هلِلَّ، أَنههُ كَانَ فِي وَفْدِ ثَقِيفٍ رَجُلٌ مَذَُْومٌ، فَأَرْسَلَ إِلَيْهِ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «ارجع فقد بايعناك» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '(7) القولنج: مرض معوي مؤلَ يعسر معه خروج التفل والريح', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(2) أخرجه مسلم في السلام، وأخرجه ابن ماجه وأحدْ وابن خزيمة وابن جرير عن عمرو بن الشريد عن أبيه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَرَوَى الْبُخَارِيُّ فِي «صَحِيحِهِ» تَـعْلِيقًا مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «فِهر مِنَ الْمَجْذُومِ كَمَا تَفِرُّ مِنَ الَْأسَدِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» مِنْ حَدِيثِ ابْنِ عَبهاسٍ ، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ: «لَا تُدِيُموا النهظَرَ إِلَى الْمَجْذُومِيَن» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَفِي «الصهحِيحَيِْن» مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «لَا يُورِدَنه مُْمرِضٌ عَلَى مُصِحٍّ » »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَيُذْكَرُ عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «كَلِّمِ الْمَجْذُومَ، وَبَـيْـنَكَ وَبَـيْـنَهُ قَـيْدُ رُمْحٍ أَوْ رُمْيَُِْن» »4« . الُْجذَامُ: عِلهةٌ رَدِيئَةٌ تَدَُْثُ مِنَ انْتِشَارِ الْمِ هرةِ السهوْدَاءِ فِي الْبَدَنِ كُلِّهِ، فَـيَـفْسُدُ مِزَاجُ الَْأعْضَاءِ وَهَيْـئَـتُـهَا وَشَكْ لُهَا، وَرُهبَما فَسَدَ فِي آخِرِهِ اتِّصَالَُها حَ هتى تَـتَأَكهلَ الَْأعْضَاءُ وَتَسْقُطَ وَيُسَمهى دَاءَ الَْأسَدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَفِي هَذِهِ التهسْمِيَةِ ثَلَاثَةُ أَقْـوَالٍ لِلْطَِِبهاءِ: أَحَدُهَا: أَنهـهَا لِكَثْـرَةِ مَا تَـعْتَِري الَْأسَدَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَالثهانِي: لَِأنه هَذِهِ الْعِلهةَ تُهََِّمُ وَجْ هَ صَاحِبِهَا وَتَعََْلُهُ فِي سَحْنَةِ الَْأسَدِ. وَالثهالِثُ : أَنههُ يَـفْتَِرسُ مَنْ يَـقْرَبُهُ، أَوْ يَدْنُو مِنْهُ بِدَائِهِ افْتَِراسَ الَْأسَدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَهَذِهِ الْعِلهةُ عِنْدَ الَْأطِبهاءِ مِنَ الْعِلَلِ الْمُعْدِيَةِ الْمُتَـوَارَثَةِ، وَمُقَارِبُ الْمَجْذُومِ، وَصَاحِبِ السُّلِّ يَسْقَمُ بِرَائِحَتِهِ، فَالنهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لِكَمَالِ شَفَقَتِهِ عَلَى الُْأمهةِ، وَنُصْحِهِ لَهمُْ نَـهَاهُمْ عَنِ الَْأسْبَابِ الهتِي تُـعَرِّضُهُمْ لِوُصُولِ الْعَيْبِ وَالْفَسَادِ إِلَى أَجْسَامِهِمْ وَقُـلُوبِِهمْ، وَلَا رَيْبَ أَنههُ قَدْ يَكُونُ فِي الْبَدَنِ تَـهَيُّـؤٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَاسْتِعْدَادٌ كَامِنٌ لِقَبُولِ هَذَا الدهاءِ، وَقَدْ تَكُونُ الطهبِيعَةُ سَرِيعَةَ الِانْفِعَالِ قَابِلَةً لِلِاكْ تِسَابِ مِنْ أَبْدَانِ مَنْ تُاََوِرُهُ وَتَُخالِطُهُ، فَإِنهـهَا نَـقهالَةٌ، وَقَدْ يَكُونُ خَوْفُـهَا مِنْ ذَلِكَ وَوَهْهَُُا مِنْ أَكْ بََِ أَسْبَابِ إِصَابَةِ تِلْكَ الْعِلهةِ لََها، فَإِنه الْوَهْمَ فَـعهالٌ مُسْتَـوْلٍ عَلَى الْقُوَى وَالطهبَائِعِ، وَقَدْ تَصِلُ رَائِحَةُ الْعَلِيلِ إِلَى الصهحِيحِ فَـتُسْقِمُهُ، وَهَذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'مُعَايَنٌ فِي بَـعْضِ الَْأمْرَاضِ ، وَالهرائِحَةُ أَحَدُ أَسْبَابِ الْعَدْوَى، وَمَعَ هَذَا كُلِّهِ فَلَا بُده مِنْ وُجُودِ اسْ تِعْدَادِ الْبَدَنِ وَقَـبُولِهِ لِذَلِكَ الدهاءِ، وَقَدْ تَـزَهوجَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ امْرَأَةً، فَـلَمها أَرَادَ الدُّخُولَ بَِها، وَجَدَ بِكَشْحِهَا بَـيَاضًا، فَـقَالَ: «الحقي بأهلك» »5« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, '(7) أخرجه البخاري في الطب، وأخرجه موصولا أبو نعيم في مستخرجه وابن خزيمة وابن حبان في صحيحهما', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, '(2) أخرجه الإمام أحدْ وابن ماجه عن ابن عباس', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, '(3) أخرجه البخاري في الطب، ومسلم في السلام. وأبو داود وابن ماجه وأحدْ والبيهقي وابن جرير (4) أخرجه عبد الله بن الإمام أحدْ، وأخرجه ابن السنِ وأبو نعيم في الطب وصنعّفه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, '(5) أخرجه الإمام أحدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَقَدْ ظَنه طَائِفَةٌ مِنَ النهاسِ أَنه هَذِهِ الَْأحَادِيثَ مُعَارَضَةٌ بَِأحَادِيثَ أُخَرَ تُـبْطِلُهَا وَتُـنَاقِضُهَا، فَمِنْـهَا: مَا رَوَاهُ الترمذي، مِنْ حَدِيثِ جابر»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, '، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وسلم آخذ بِيَدِ رَجُلٍ مَذَُْومٍ، فَأَدْخَلَهَا مَعَهُ فِي الْقَصْعَةِ، وَقَالَ: «كُلْ بِسْمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'ا هلِلَّ ثِقَةً بِا هلِلَّ، وَتَـوَكُّلًا عَلَيْهِ» ، وَرَوَاهُ ابْنُ مَاجَهْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَبَِما ثَـبَتَ فِي «الصهحِيحِ» ، عَنْ أَبِي هُرَيْـرَةَ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «لَا عَدْوَى وَلَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'طِيَـرَةَ»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَنَنُْْ نَـقُولُ: لَا تَـعَارُضَ بَِحمْدِ ا هلِلَّ بَـيَْن أَحَادِيثِهِ الصهحِيحَةِ. فَإِذَا وَقَعَ التهـعَارُضُ ، فَإِمها أَنْ يَكُونَ أَحَدُ الَْحدِيثَـيِْن لَيْسَ مِنْ كَلَامِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَقَدْ غَلِطَ فِيهِ بَـعْضُ الرُّوَاةِ مَعَ كَوْنِهِ ثِقَةً ثَـبْـتًا، فَالثِّقَةُ يَـغْلَطُ ، أَوْ يَكُونُ أَحَدُ الَْحدِيثَـيِْن نَاسِخًا لِلْخَْرِ إِذَا كَانَ مِمها يَـقْبَلُ النهسْخَ، أَوْ يَكُونُ التهـعَارُضُ فِي فَـهْمِ السهامِعِ، لَا فِي نَـفْسِ كَلَامِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَلَا بُده مِنْ وَجْهٍ مِنْ هَذِهِ الْوُجُوهِ الثهلَاثَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'وَأَمها حَدِيثَانِ صَحِيحَانِ صَرِيَحانِ مُتَـنَاقِضَانِ مِنْ كُلِّ وَجْهٍ، لَيْسَ أَحَدُهُاَُ نَاسِخًا لِلْخَْرِ، فَـهَذَا لَا يُوجَدُ أَصْلًا، وَمَعَاذَ ا هلِلَّ أَنْ يُوجَدَ فِي كَلَامِ الصهادِقِ الْمَصْدُوقِ الهذِي لَا يَْخرُجُ مِنْ بَـيِْن شَفَتَـيْهِ إِهلا الَْحقُّ، وَالْآفَةُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'مِنَ التهـقْصِيِر فِي مَعْرِفَةِ الْمَنْـقُولِ، وَالتهمْيِيزِ بَـيَْن صَحِيحِهِ وَمَعْلُولِهِ، أَوْ مِنَ الْقُصُورِ فِي فَـهْمِ مُرَادِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَحَلِْْ كَلَامِهِ عَلَى غَيِْر مَا عَنَاهُ بِهِ، أَوْ مِنْـهُمَا مَعًا، وَمِنْ ها هنا وَقَعَ مِنَ الِاخْتِلَافِ وَالْفَسَادِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'مَا وَقَعَ، وَبِا هلِلَّ التهـوْفِيقُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'قَالَ ابن قتيبة فِي كِتَابِ «اخْتِلَافِ الَْحدِيثِ» لَهُ حِكَايَةً عَنْ أَعْدَاءِ الَْحدِيثِ وَأَهْلِهِ، قَالُوا: حَدِيثَانِ مُتَـنَاقِضَانِ رَوَيْـتُمْ عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «لَا عَدْوَى وَلَا طِيَـرَةَ» . وَقِيلَ لَهُ: إِنه النُّـقْبَةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'تَـقَعُ بِِمشْفَرِ الْبَعِيِر، فَـيَجْرَبُ لِذَلِكَ الِْإبِلُ. قَالَ: «فَمَا أَعْدَى الَْأهولَ» »2« ، ُ مه رَوَيْـتُمْ «لَا يُورَدُ ذُو عَاهَةٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'عَلَى مُصِحٍّ ، وَفِهر مِنَ الْمَجْذُومِ فِرَارَكَ مِنَ الَْأسَدِ» ، وَأَتَاهُ رَجُلٌ مَذَُْومٌ لِيُـبَايِعَهُ بَـيْـعَةَ الإسلام، فأرسل إليه البيعة، وأمره', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, '(7) أخرجه الترمذي في الأطعمة، وأبو داود في الطب، وابن ماجه في الطب وَقَالَ الترمذي: غَرِيبٌ لَا نَـعْرِفُهُ إِهلا مِنْ حَدِيثِ المفضل بن فضالة، والمفضل قال فيه ابن معين: ليس بذاك. أي ضعيف.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, '(2) أخرجه الإمام أحدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'بِالِانْصِ رَافِ، وَلََْ ذَََْنْ لَهُ، وَقَالَ: «الشُّؤْمُ فِي الْمَرْأَةِ وَالدهارِ وَالدهابهةِ. قَالُوا: وَهَذَا كُلُّهُ مُْختَلِفٌ لا يشبه بعضه بعا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'قَالَ أبو محمد: وَنَنُْْ نَـقُولُ: إِنههُ لَيْسَ فِي هَذَا اخْتِلَافٌ ، وَلِكُلِّ مَعْنًى مِنْـهَا وَقْتٌ وَمَوْضِعٌ، فَإِذَا وُضِعَ مَوْضِ عَهُ زَالَ الِاخْتِلَافُ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وَالْعَدْوَى جِنْسَانِ: أَحَدُهُاَُ: عَدْوَى الُْجذَامِ، فَإِنه الْمَجْذُومَ تَشْتَدُّ رَائِحَتُهُ حَ هتى يُسْقِمَ مَنْ أَطَالَ مُاََلَسَتَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'وَمُاَُدَثَـتَهُ، وَكَذَلِكَ الْمَرْأَةُ تَكُونُ تَتََْ الْمَجْذُومِ، فَـتُضَاجِعُهُ فِي شِعَارٍ وَاحِدٍ، فَـيُوصِلُ إِلَيْـهَا الَْأذَى، وَرُهبَما جُذِمَتْ ، وَكَذَلِكَ وَلَدُهُ يَـنْزِعُونَ فِي الْكِبََِ إِلَيْهِ، وَكَذَلِكَ مَنْ كَانَ بِهِ سِلٌّ وَدِقٌّ وَنُـقْبٌ . وَالَْأطِبهاءُ تَمَُْرُ أَنْ لَا يَُجالَسَ الْمَسْلُولُ وَلَا الْمَجْذُومُ، وَلَا يُرِيدُونَ بِذَلِكَ مَعْنَى الْعَدْوَى، وَإِهنَما يُرِيدُونَ بِهِ مَعْنَى تَـغَيُِّر الهرائِحَةِ، وَأَنهـهَا قَدْ تُسْقِمُ مَنْ أَطَالَ اشْتِمَامَهَا، وَالَْأطِبهاءُ أَبْـعَدُ النهاسِ عَنِ الِْإيَمانِ بِيُمْنٍ وَشُؤْمٍ، وَكَذَلِكَ النُّـقْبَةُ تَكُونُ بِالْبَعِيِر- وَهُوَ جَرَبٌ رَطْبٌ - فَإِذَا خَالَطَ الِْإبِلَ أَوْ حَاكههَا، وَأَوَى فِي مَبَاركِِهَا، وَصَلَ إِلَيْـهَا بِالْمَاءِ الهذِي يَسِيلُ مِنْهُ، وَبِالنهطَفِ نَوَْْ مَا بِهِ، فَـهَذَا هُوَ الْمَعْنَى الهذِي قَالَ فِيهِ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «لَا يُورَدُ ذُو', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'عَاهَةٍ عَلَى مُصِحٍّ » ، كَرِهَ أَنْ يَُخالِطَ الْمَعْيُوهُ الصهحِيحَ، لِئَهلا يَـنَالَهُ مِنْ نَطَفِهِ وَحِكهتِهِ نَوٌْْ مِمها بِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'قَالَ: وَأَمها الِْجنْسُ الْآخَرُ مِنَ الْعَدْوَى، فَـهُوَ الطهاعُونُ يَـنْزِلُ بِبَـلَدٍ، فَـيَخْ رُجُ مِنْهُ خَوْفَ الْعَدْوَى، وَقَدْ قَالَ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إِذَا وَقَعَ بِبَـلَدٍ، وَأَنْـتُمْ بِهِ، فَلَا تَْخرُجُوا مِنْهُ، وَإِذَا كَانَ بِبَـلَدٍ، فَلَا تَدْخُلُوهُ» . يُرِيدُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'بِقَوْلِهِ: لَا تَْخرُجُوا مِنَ الْبَـلَدِ إِذَا كَانَ فِيهِ كَأَنهكُمْ تَظُنُّونَ أَنه الْفِرَارَ مِنْ قَدَرِ ا هلِلَّ يُـنْجِيكُمْ مِنَ ا هلِلَّ، وَيُرِيدُ إِذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'كَانَ بِبَـلَدٍ، فَلَا تَدْخُلُوهُ، أَيْ : مَقَامُكُمْ فِي الْمَوْضِ عِ الهذِي لَا طَاعُونَ فِيهِ أَسْكَنُ لِقُلُوبِكُمْ، وَأَطْيَبُ لِعَيْشِكُمْ، وَمِنْ ذَلِكَ الْمَرْأَةُ تُـعْرَفُ بِالشُّؤْمِ أَوِ الدهارُ، فَـيَـنَالُ الهرجُلَ مَكْ رُوهٌ أَوْ جَائِحَةٌ، فَـيَـقُولُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'أَعَدَتْنِِ بِشُؤْمِهَا، فَـهَذَا هُوَ الْعَدْوَى الهذِي قَالَ فِيهِ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «لَا عَدْوَى» »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'وَقَالَتْ فِرْقَةٌ أُخْ رَى: بَلِ الَْأمْرُ بِاجْتِنَابِ الْمَجْذُومِ وَالْفِرَارِ مِنْهُ عَلَى الِاسْتِحْبَابِ، وَالِاخْ تِيَارِ، وَالِْإرْشَادِ. وَأَمها الَْأكْلُ مَعَهُ، فَـفَعَلَهُ لِبَـيَانِ الَْجوَازِ، وَأَنه هَذَا لَيْسَ بَِحرَامٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'وَقَالَتْ فِرْقَةٌ أُخْ رَى: بَلِ الِْخطَابُ بَِهذَيْنِ الِْخطَابَـيِْن جُزْئِيٌّ لَا كُلِّيٌّ، فَكُلُّ وَاحِدٍ خَاطَبَهُ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'وَسَلهمَ بَِما يَلِيقُ بَِحالِهِ، فَـبَـعْضُ النهاسِ يكون قويّ الإيمان، قويّ التوكل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, '(7) أخرجه الإمام مالك، والبخاري في النكاح، ومسلم في السلام والترمذي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'تَدْفَعُ قُـهوةُ تَـوَكُّلِهِ قُـهوةَ الْعَدْوَى، كَمَا تَدْفَعُ الطهبِيعَةِ قُـهوةَ الْعِلهةِ فَـتُـبْطِلُهَا، وَبَـعْضُ النهاسِ لَا يَـقْوَى عَلَى ذَلِكَ ، فَخَاطَبَهُ بِالِاحْتِيَاطِ وَالَْأخْذِ بِالتهحَفُّظِ، وَكَذَلِكَ هُوَ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فَـعَلَ الَْحالَتَـيِْن مَعًا، لِتَـقْتَدِيَ بِهِ الُْأمهةُ فِيهِمَا، فَـيَأْخُذَ مَنْ قَوِيَ مِنْ أُمهتِهِ بِطَرِيقَةِ التهـوَكُّلِ وَالْقُهوةِ وَالثِّقَةِ بِا هلِلَّ، وَخََُْذَ مَنْ ضَعُفَ مِنْـهُمْ بِطَرِيقَةِ التهحَفُّظِ وَالِاحْتِيَاطِ، وَهُاَُ طَرِيقَانِ صَحِيحَانِ. أَحَدُهُاَُ: لِلْمُؤْمِنِ الْقَوِيِّ ، وَالْآخَرُ لِلْمُؤْمِنِ الضهعِيفِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'فَـتَكُونُ لِكُلِّ وَاحِدٍ مِنَ الطهائِفَتَـيِْن حُجهةٌ وَقُدْوَةٌ بَِحسَبِ حَالِِهمْ وَمَا يُـنَاسِبُـهُمْ، وَهَذَا كَمَا أَنههُ صَلهى ا هللَُّ عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'وَسَلهمَ كَوَى، وَأَثْـنَى عَلَى تَارِكِ الْكَيِّ، وَقَـرَنَ تَـرْكَهُ بِالتهـوَكُّلِ، وَتَـرَكَ الطِّيَـرَةَ، وَلِهذََا نَظَائِرُ كَثِيَرةٌ، وَهَذِهِ طَرِيقَةٌ لَطِيفَةٌ حَسَنَةٌ جِدًّا مَنْ أَعْطَاهَا حَقههَا، وَرُزِقَ فِقْهَ نَـفْسِهِ فِيهَا، أَزَالَتْ عَنْهُ تَـعَارُضًا كَثِيًرا يَظُنُّهُ بِالسُّنهةِ الصهحِيحَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 48, 'وَذَهَبَتْ فِرْقَةٌ أُخْ رَى إِلَى أَنه الَْأمْرَ بِالْفِرَارِ مِنْهُ، وَمُاََنَـبَتِهِ لَِأمْرٍ طَبِيعِيٍّ، وَهُوَ انْتِقَالُ الدهاءِ مِنْهُ بِوَاسِطَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 49, 'الْمُلَامَسَةِ وَالْمُخَالَطَةِ وَالهرائِحَةِ إِلَى الصهحِيحِ، وَهَذَا يَكُونُ مَعَ تَكْرِيرِ الْمُخَالَطَةِ وَالْمُلَامَسَةِ لَهُ، وَأَمها أَكْ لُهُ مَعَهُ مِقْدَارًا يَسِيًرا مِنَ الهزمَانِ لِمَصْلَحَةٍ رَاجِحَةٍ، فَلَا بَْأسَ بِهِ، وَلَا تَصَُْلُ الْعَدْوَى مِنْ مَ هرةٍ وَاحِدَةٍ وَلَْحظَةٍ وَاحِدَةٍ، فَـنَـهَى سَدًّا لِلذهرِيعَةِ، وَحِاَْيَةً لِلصِّحهةِ، وَخَالَطَهُ مَُخالَطَةً مَا لِلْحَاجَةِ وَالْمَصْلَحَةِ، فَلَا تَـعَارُضَ بَـيَْن الَْأمْرَيْنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 50, 'وَقَالَتْ طَائِفَةٌ أُخْ رَى: يَُجوزُ أَنْ يَكُونَ هَذَا الْمَجْذُومُ الهذِي أَكَلَ مَعَهُ بِهِ مِنَ الُْجذَامِ أَمْرٌ يَسِيٌر لَا يُـعْدِي مِثْـلُهُ، وَلَيْسَ الَْجذْمَى كُلُّهُمْ سَوَاءً، وَلَا الْعَدْوَى حَاصِلَةٌ مِنْ جَِيَعِهِمْ، بَلْ مِنْـهُمْ مَنْ لَا تَضُرُّ مَُخالَطَتُهُ، وَلَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 51, 'تُـعْدِي، وَهُوَ مَنْ أَصَابَهُ مِنْ ذَلِكَ شَيْ ءٌ يَسِيٌر، ُ مه وَقَفَ وَاسْتَمَ هر عَلَى حَالِهِ، وَلََْ يُـعْدِ بَقِيهةَ جِسْمِهِ، فهو أن يُـعْدِيَ غَيْـرَهُ أَوْلَى وَأَحْ رَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 52, 'وَقَالَتْ فِرْقَةٌ أُخْ رَى: إِنه الَْجاهِلِيهةَ كَانَتْ تَـعْتَقِدُ أَنه الَْأمْرَاضَ الْمُعْدِيَةَ تُـعْدِي بِطَبْعِهَا مِنْ غَيِْر إِضَافَةٍ إِلَى ا هلِلَّ سُبْحَانَهُ، فَأَبْطَلَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ اعْتِقَادَهُمْ ذَلِكَ ، وَأَكَلَ مَعَ الْمَجْذُومِ لِيُـبَـيَِّن لَهمُْ أَنه ا هللََّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 53, 'سُبْحَانَهُ هُوَ الهذِي يُْمرِضُ وَيَشْفِي، وَنَـهَى عَنِ الْقُرْبِ مِنْهُ لِيَـتَـبَـهيَن لَهمُْ أَنه هَذَا مِنَ الَْأسْبَابِ الهتِي جَعَلَهَا ا هللَُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 54, 'مُفْضِيَةً إِلَى مُسَبهـبَاتَِها، فَفِي نَـهْيِهِ إِثْـبَاتُ الَْأسْبَابِ، وَفِي فِعْلِهِ بَـيَانُ أَنهـهَا لَا تَسْتَقِلُّ بِشَيْ ءٍ، بَلِ الهربُّ سُبْحَانَهُ إِنْ شَاءَ سَلَبَـهَا قُـوَاهَا، فَلَا تُـؤَثِّرُ شَيْـئًا، وَإِنْ شَاءَ أَبْـقَى عَلَيْـهَا قُـوَاهَا فَأَثهـرَتْ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 55, 'وَقَالَتْ فِرْقَةٌ أُخْ رَى: بَلْ هَذِهِ الَْأحَادِيثُ فِيهَا النهاسِخُ وَالْمَنْسُوخُ، فَـيُـنْظَرُ فِي تَارِيِخهَا، فَإِنْ عُلِمَ الْمُتَأَخِّرُ مِنْـهَا، حُكِمَ بَِأنههُ النهاسِخُ، وَإِهلا توقفنا فيها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 56, 'وَقَالَتْ فِرْقَةٌ أُخْ رَى: بَلْ بَـعْضُهَا مَفُُْوظٌ، وَبَـعْضُهَا غير مفُوظ، وتكلمات فِي حَدِيثِ «لَا عَدْوَى» ، وَقَالَتْ : قَدْ كَانَ أَبُو هُرَيْـرَةَ يَـرْوِيهِ أَهولًا، ُ مه شَكه فِيهِ فَـتَـرَكَهُ، وَرَاجَعُوهُ فِيهِ، وَقَالُوا: سَِمعْنَاكَ تُدََِّثُ بِهِ، فَأَبََ أَنْ يَُحدِّثَ بِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 57, 'قَالَ أبو سلمة: فَلَا أَدْرِي، أَنَسِيَ أَبُو هُرَيْـرَةَ، أَمْ نَسَخَ أَحَدُ الَْحدِيثَـيِْن الْآخَرَ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 58, 'وَأَمها حَدِيثُ جابر: أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَخَذَ بِيَدِ مَذَُْومٍ، فَأَدْخَلَهَا مَعَهُ فِي الْقَصْعَةِ، فَحَدِيثٌ لَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 59, 'يَـثْـبُتُ وَلَا يَصِحُّ، وَغَايَةُ مَا قَالَ فِيهِ الترمذي: إِنههُ غَرِيبٌ ، لََْ يُصَحِّ حْهُ وَلََْ يَُحسِّ نْهُ. وَقَدْ قَالَ شعبة وَغَيْـرُهُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 60, 'اتهـقُوا هَذِهِ الْغَرَائِبَ . قَالَ الترمذي: وَيُـرْوَى هَذَا مِنْ فِعْلِ عمر، وَهُوَ أَثْـبَتُ ، فَـهَذَا شَأْنُ هَذَيْنِ الَْحدِيثَـيِْن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 61, 'اللهذَيْنِ عُورِضَ بِِهمَا أَحَادِيثُ النهـهْيِ ، أَحَدُهُاَُ: رَجَعَ أَبُو هُرَيْـرَةَ عَنِ التهحْدِيثِ بِهِ وَأَنْكَرَهُ، وَالثهانِي: لَا يَصِحُّ عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَا هللَُّ أَعْلَمُ، وَقَدْ أَشْبَـعْنَا الْكَلَامَ فِي هَذِهِ الْمَسْأَلَةِ فِي كِتَابِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 62, '«الْمِفْتَاحِ» بَِأطْوَلَ مِنْ هذا، وَبِا هلِلَّ التهـوْفِيقُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي الْمَنْعِ مِنَ التهدَاوِي بِالْمُحَ هرمَاتِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى أبو داود فِي «سُنَنِهِ» مِنْ حَدِيثِ أَبِي الدهرْدَاءِ رَضِيَ ا هللَُّ عَنْهُ قَالَ: قَالَ رَسُولُ ا هلِلَّ هللا ىلص: «أن ا هللََّ أَنْـزَلَ الدهاءَ وَالدهوَاءَ، وَجَعَلَ لِكُلِّ دَاءٍ دَوَاءً، فَـتَدَاوَوْا، وَلَا تَدَاوَوْا بِالْمُحَ هرمِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَذكََرَ الْبُخَارِيُّ فِي «صَحِيحِهِ» عَنِ ابْنِ مَسْ عُودٍ: إِنه ا هللََّ لََْ يَْجعَلْ شِفَاءكَُمْ فِيمَا حَ هرمَ عَلَيْكُمْ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَفِي «السُّنَنِ» : عَنْ أَبِي هُرَيْـرَةَ، قَالَ: نَـهَى رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَنِ الدهوَاءِ الخبيث »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(7) أخرجه أبو داود في الطب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(2) أخرجه الطباَني في الكبير، وأخرجه البخاري تعليقا في الطب. ووصله الطباَني بإسناد رجاله رجال الصحيح، وأخرجه أحدْ وابن حبان في صحيحه والبزار وأبو يعلى ورجال أبي يعلى ثقات.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(3) أخرجه أبو داود والترمذي وابن ماجه وأحدْ. وسنده قوي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَفِي «صَحِيحِ مسلم» عَنْ طارق بن سويد الجعفي، أَنههُ سَأَلَ النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَنِ الَْخمْرِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'فَـنَـهَاهُ، أَوْ كَرِهَ أَنْ يَصْنَـعَهَا، فَـقَالَ: إِهنَما أَصْنَـعُهَا لِلدهوَاءِ، فَـقَالَ: «إِنههُ لَيْسَ بِدَوَاءٍ، وَلَكِنههُ دَاءٌ» »7« . وَفِي «السُّنَنِ» أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ سُئِلَ عَنِ الَْخمْرِ يُْجعَلُ فِي الدهوَاءِ، فَـقَالَ: «إِنهـهَا دَاءٌ وَلَيْسَتْ بِالدهوَاءِ» ، رَوَاهُ أبو داود، وَالتِّْرمِذِيُّ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَفِي «صَحِيحِ مسلم» عَنْ طارق بن سويد الحضرمي، قَالَ: قُـلْتُ : يَا رَسُولَ ا هلِلَّ! إِنه بَِأرْضِ نَا أَعْنَابًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'نَـعْتَصِ رُهَا فَـنَشْرَبُ مِنْـهَا، قَالَ: «لَا» فَـرَاجَعْتُهُ، قُـلْتُ : إِهنا نَسْتَشْفِي لِلْمَرِيضِ ، قَالَ: «إِنه ذَلِكَ لَيْسَ بِشِفَاءٍ وَلَكِنههُ دَاءٌ» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَفِي «سُنَنِ النهسَائِيِّ» أَنه طَبِيبًا ذكََرَ ضِفْدَعًا فِي دَوَاءٍ عِنْدَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَـنَـهَاهُ عَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'قَـتْلِهَا »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَيُذْكَرُ عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: مَنْ تَدَاوَى بِالَْخمْرِ، فَلَا شَفَاهُ ا هللَُّ» »5« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'الْمُعَالََجةُ بِالْمُحَ هرمَاتِ قَبِيحَةٌ عَقْلًا وَشَرْعًا، أَمها الشهرْعُ فَمَا ذكََرْنَا مِنْ هَذِهِ الَْأحَادِيثِ وَغَيِْرهَا، وَأَمها الْعَقْلُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'فَـهُوَ أَنه ا هللََّ سُبْحَانَهُ إِهنَما حَ هرمَهُ لُِخبْثِهِ، فَإِنههُ لََْ يَُحرِّمْ عَلَى هَذِهِ الُْأمهةِ طَيِّبًا عُقُوبَةً لََها، كَمَا حَ هرمَهُ عَلَى بَنِِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'إِسْرَائِيلَ بِقَوْلِهِ: فَبِظُلْمٍ مِنَ الهذِينَ هادُوا حَ هرمْنا عَلَيْهِمْ طَيِّباتٍ أُحِلهتْ لَهمُْ »1« . وَإِهنَما حَ هرمَ عَلَى هَذِهِ الُْأمهةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'مَا حَ هرمَ لُِخبْثِهِ، وَتَرَِْيُمهُ لَهُ حَِيْهةً لَهمُْ، وَصِ يَانَةً عَنْ تَـنَاوُلِهِ، فَلَا يُـنَاسِبُ أَنْ يُطْلَبَ بِهِ الشِّ فَاءُ مِنَ الَْأسْقَامِ وَالْعِلَلِ، فَإِنههُ وَإِنْ أَثهـرَ فِي إِزَالَتِهَا، لَكِنههُ يُـعْقِبُ سَقَمًا أَعْظَمَ مِنْهُ فِي الْقَلْبِ بِقُهوةِ الُْخبْثِ الهذِي فِيهِ، فَـيَكُونُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'الْمُدَاوَى بِهِ قَدْ سَعَى فِي إِزَالَةِ سُقْمِ الْبَدَنِ بسقم القلب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, '(7) أخرجه مسلم في الأشربة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, '(2) أخرجه أبو داود في الطب، والترمذي وقال: حسن صحيح. وصححه ابن حبان (3) أخرجه أحدْ في مسنده. ولَ يخرجه الإمام مسلم', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, '(4) أخرجه النسائي في الصيد، وأحدْ، وأخرجه أبو داود والحاكم. وإسناده قوي (5) أخرجه أبو نعيم في الطب بلفظ: «من تداوى بحرام لَ يجعل الله فيه شفاء» . (1) النساء- 711', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَأَيْضًا فَإِنه تَرَِْيَمهُ يَـقْتَضِ ي تَنََُّـبَهُ وَالْبُـعْدَ عَنْهُ بِكُلِّ طَرِيقٍ، وَفِي اتَِّخاذِهِ دَوَاءً حَضٌّ عَلَى التهـرْغِيبِ فِيهِ وَمُلَابَسَتِهِ، وَهَذَا ضِدُّ مَقْصُودِ الشهارعِِ ، وَأَيْضًا فَإِنههُ دَاءٌ كَمَا نَصه عَلَيْهِ صَاحِبُ الشهرِيعَةِ، فَلَا يَُجوزُ أَنْ يُـتهخَذَ دَوَاءً.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'وَأَيْضًا فَإِنههُ يُكْسِبُ الطهبِيعَةَ وَالرُّوحَ صِفَةَ الُْخبْثِ، لَِأنه الطهبِيعَةَ تَـنْـفَعِلُ عَنْ كَيْفِيهةِ الدهوَاءِ انْفِعَالًا بَـيِّنًا، فَإِذَا كَانَتْ كَيْفِيهـتُهُ خَبِيثَةً، اكْتَسَبَتِ الطهبِيعَةُ مِنْهُ خُبْـثًا فَكَيْفَ إِذَا كَانَ خَبِيثًا فِي ذَاتِهِ، وَلَِهذَا حَ هرمَ ا هللَُّ سُبْحَانَهُ عَلَى عِبَادِهِ الَْأغْذِيَةَ وَالَْأشْرِبَةَ وَالْمَلَابِسَ الَْخبِيثَةَ، لِمَا تُكْسِبُ النهـفْسَ مِنْ هَيْـئَةِ الُْخبْثِ وَصِ فَتِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَأَيْضًا فَإِنه فِي إِبَاحَةِ التهدَاوِي بِهِ، وَلَا سِيهمَا إِذَا كَانَتِ النهـفُوسُ تَيَِلُ إِلَيْهِ ذَرِيعَةً إِلَى تَـنَاوُلِهِ لِلشههْوَةِ وَاللهذهةِ، لَا سِيهمَا إِذَا عَرَفَتِ النُّـفُوسُ أَنههُ نَافِعٌ لَهاَ مُزِيلٌ لَِأسْقَامِهَا جَالِبٌ لِشِفَائِهَا، فَـهَذَا أَحَبُّ شَيْ ءٍ إِلَيْـهَا، وَالشهارعُِ سَده الذهرِيعَةَ إِلَى تَـنَاوُلِهِ بِكُلِّ مُْمكِنٍ، وَلَا رَيْبَ أَنه بَـيَْن سَدِّ الذهرِيعَةِ إِلَى تَـنَاوُلِهِ، وَفَـتْحِ الذهرِيعَةِ إِلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'تَـنَاوُلِهِ تَـنَاقُضًا وَتَـعَارُضًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَأَيْضًا فَإِنه فِي هَذَا الدهوَاءِ الْمُحَ هرمِ مِنَ الَْأدْوَاءِ مَا يَزِيدُ عَلَى مَا يُظَنُّ فِيهِ مِنَ الشِّ فَاءِ، وَلْنَـفْرِضِ الْكَلَامَ فِي أُمِّ الَْخبَائِثِ الهتِي مَا جَعَلَ ا هللَُّ لَنَا فِيهَا شِفَاءً قَطُّ، فَإِنهـهَا شَدِيدَةُ الْمَضَ هرةِ بِالدِّمَاغِ الهذِي هُوَ مَرْكَزُ الْعَقْلِ عِنْدَ الَْأطِبهاءِ، وَكَثِيٍر مِنَ الْفُقَهَاءِ وَالْمُتَكَلِّمِيَن. قَالَ أبقراط فِي أَثْـنَاءِ كَلَامِهِ فِي الَْأمْرَاضِ الَْحادهةِ: ضَرَرُ الَْخمْرَةِ بِالهرأْسِ شَدِيدٌ. لَِأنههُ يُسَرّعُِ الِارْتِفَاعَ إِلَيْهِ. وَيَـرْتَفِعُ بِارْتِفَاعِهِ الَْأخْلَاطُ الهتِي تَـعْلُو فِي الْبَدَنِ ، وَهُوَ كَذَلِكَ يَضُرُّ بِالذِّهْنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَقَالَ صَاحِبُ «الْكَامِلِ» : إِنه خَاصِّ يهةَ الشهرَابِ الِْإضْرَارُ بِالدِّمَاغِ وَالْعَصَبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَأَمها غَيْـرُهُ مِنَ الَْأدْوِيَةِ الْمُحَ هرمَةِ فَـنَـوْعَانِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'أَحَدُهُاَُ: تَـعَافُهُ النهـفْسُ وَلَا تَـنْـبَعِثُ لِمُسَاعَدَتِهِ الطهبِيعَةُ عَلَى دَفْعِ الْمَرَضِ بِهِ كَالسُّمُومِ، وَلُُحومِ الَْأفَاعِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَغَيِْرهَا مِنَ الْمُسْتَـقْذَرَاتِ، فَـيَـبْـقَى كَلًّا عَلَى الطهبِيعَةِ مُثْقِلًا لََها، فَـيَصِيُر حِينَئِذٍ دَاءً لَا دَوَاءً.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'وَالثهانِي: مَا لَا تَـعَافُهُ النهـفْسُ كَالشهرَابِ الهذِي تَسْتَـعْمِلُهُ الَْحوَامِلُ مَثَلًا، فَـهَذَا ضَرَرُهُ أَكْ ثَـرُ مِنْ نَـفْعِهِ، وَالْعَقْلُ يَـقْضِي بِتَحْرِيِم ذَلِكَ ، فَالْعَقْلُ وَالْفِطْرَةُ مطابق للشرع في ذلك.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وها هنا سِرٌّ لَطِيفٌ فِي كَوْنِ الْمُحَ هرمَاتِ لَا يُسْتَشْفَى بَِها، فَإِنه شَرْطَ الشِّ فَاءِ بِالدهوَاءِ تَـلَقِّيهِ بِالْقَبُولِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وَاعْتِقَادُ مَنْـفَعَتِهِ، وَمَا جَعَلَ ا هللَُّ فِيهِ مِنْ بَـرَكَةِ الشِّ فَاءِ، فَإِنه النهافِعَ هُوَ الْمُبَارَكُ، وَأَنْـفَعُ الَْأشْيَاءِ أَبْـرَكُهَا، وَالْمُبَارَكُ مِنَ النهاسِ أَيْـنَمَا كَانَ هُوَ الهذِي يُـنْـتَـفَعُ بِهِ حَيْثُ حَله، وَمَعْلُومٌ أَنه اعْتِقَادَ الْمُسْلِمِ تَرَِْيَم هَذِهِ الْعَيِْن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'مِمها يَُحولُ بَـيْـنَهُ وَبَـيَْن اعْتِقَادِ بَـرَكَتِهَا وَمَنْـفَعَتِهَا، وَبَـيَْن حُسْنِ ظَنِّهِ بَِها، وَتَـلَقِّي طَبْعِهِ لََها بِالْقَبُولِ، بَلْ كُلهمَا كَانَ الْعَبْدُ أَعْظَمَ إِيَمانًا، كَانَ أَكْرَهَ لََها وَأَسْوَأَ اعْتِقَادًا فِيهَا، وَطَبْـعُهُ أَكْ رَهَ شَيْ ءٍ لََها، فَإِذَا تَـنَاوَلََها فِي هَذِهِ الَْحالِ، كَانَتْ دَاءً لَهُ لَا دَوَاءً إِهلا أَنْ يَـزُولَ اعْتِقَادُ الُْخبْثِ فِيهَا، وَسُوءُ الظهنِّ وَالْكَرَاهَةُ لََها بِالْمَحَبهةِ، وَهَذَا يُـنَافِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'الِْإيَمانَ فَلَا يَـتَـنَاوَلَُها الْمُؤْمِنُ قَطُّ إِهلا عَلَى وَجْهِ دَاءٍ، وَا هللَُّ أعلم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الْقَمْلِ الهذِي فِي الهرأْسِ وَإِزَالَتِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'فِي «الصهحِيحَيِْن» عَنْ كَعْبِ بْنِ عُجْ رَةَ، قَالَ: كَانَ بِي أَذًى مِنْ رَأْسِي، فَحُمِلْتُ إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'عَلَيْهِ وَسَلهمَ وَالْقَمْلُ يَـتَـنَاثَـرُ عَلَى وَجْ هِي، فَـقَالَ: «مَا كُنْتُ أَرَى الَْجهْدَ قَدْ بَـلَغَ بِكَ مَا أَرَى» ، وَفِي رِوَايَةٍ: فَأَمَرَهُ أَنْ يَْحلِقَ رَأْسَهُ، وَأَنْ يُطْعِمَ فَـرَقًا بَـيَْن سِتهةٍ، أَوْ يُـهْدِيَ شَاةً، أَوْ يَصُومَ ثَلَاثَةَ أَهيامٍ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الْقَمْلُ يَـتَـوَهلدُ فِي الهرأْسِ وَالْبَدَنِ مِنْ شَيْـئَـيِْن: خَارِجٍ عَنِ الْبَدَنِ وَدَاخِلٍ فِيهِ، فَالَْخارِجُ: الْوَسَخُ وَالدهنَسُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الْمُتَـرَاكِمُ فِي سَطْحِ الَْجسَدِ، وَالثهانِي مِنْ خَلْطٍ رَدِيءٍ عَفِنٍ تَدْفَـعُهُ الطهبِيعَةُ بَـيَْن الِْجلْدِ وَاللهحْمِ، فَـيَـتَـعَهفنُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'بِالرُّطُوبَةِ الدهمَوِيهةِ فِي الْبَشَرَةِ بَـعْدَ خُرُوجِهَا مِنَ الْمَسَامِّ، فَـيَكُونُ مِنْهُ الْقَمْلُ، وَأَكْ ثَـرُ مَا يَكُونُ ذَلِكَ بَـعْدَ العلل والأسقام، وبسبب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(7) أخرجه البخاري ومسلم في الحج وأخرجه الإمام أحدْ أيضا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الأوساخ، وإنما كان في رؤوس الصِّبْـيَانِ أَكْثَـرَ لِكَثْـرَةِ رُطُوبَاتِِهمْ وَتَـعَاطِيهِمُ الَْأسْبَابَ الهتِي تُـوَلِّدُ الْقَمْلَ، وَلِذَلِكَ حَلَقَ النهبُِّ صَلهى ا هللَُّ عليه وسلم رؤوس بَنِِ جَعْفَرٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَمِنْ أَكْ بََِ عِلَاجِهِ حَلْقُ الهرأْسِ لِتَـنْـفَتِحَ مَسَامُّ الَْأخِْرَِةِ، فَـتَـتَصَاعَدَ الَْأخِْرَِةُ الهردِيئَةُ، فَـتُضْعِفَ مَادهةَ الَْخلْطِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَيَـنْـبَغِي أَنْ يُطْلَى الهرأْسُ بَـعْدَ ذَلِكَ بِالَْأدْوِيَةِ الهتِي تَـقْتُلُ الْقَمْلَ، وَتَنََْعُ تَـوَلهدَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَحَلْقُ الهرأْسِ ثَلَاثَةُ أَنْـوَاعٍ أَحَدُهَا نُسُكٌ وَقُـرْبَةٌ وَالثهانِي بِدْعَةٌ وَشِرْكٌ، وَالثهالِثُ حَاجَةٌ وَدَوَاءٌ فَالَْأهولُ: الحلق في أحد النسكين، الحج أو العمرةه وَالثهانِي: حَلْقُ الهرأْسِ لِغَيِْر ا هلِلَّ سُبْحَانَهُ، كَمَا يَْحلِقُهَا الْمُرِيدُونَ لِشُيُوخِهِمْ، فَـيَـقُولُ أَحَدُهُمْ: أَنَا حَلَقْتُ  رَأْسِي لِفُلَانٍ، وَأَنْتَ  حَلَقْتَهُ لِفُلَانٍ، وَهَذَا بَِمنْزِلَةِ أَنْ يَـقُولَ سَجَدْتُ لِفُلَانٍ فَإِنه حَلْقَ الهرأْسِ خُضُوعٌ وَعُبُودِيهةٌ وَذُلٌّ، وَلَِهذَا كَانَ مِنْ تَاََمِ الَْحجِّ ، حَ هتى إِنههُ عِنْدَ الشهافِعِيِّ ركُْ نٌ مِنْ أَرْكَانِهِ لَا يَتِمُّ إِهلا بِهِ، فَإِنههُ وَضْعُ النهـوَاصِي بَـيَْن يَدَيْ رَبَِّها خُضُوعًا لِعَظَمَتِهِ، وَتَذَلُّلًا لِعِهزتِهِ، وَهُوَ مِنْ أَبْـلَغِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'أَنْـوَاعِ الْعُبُودِيهةِ، وَلِهذََا كَانَتِ الْعَرَبُ إِذَا أَرَادَتْ إِذْلَالَ الَْأسِيِر مِنْـهُمْ وَعِتْـقَهُ، حَلَقُوا رَأْسَهُ وَأَطْلَقُوهُ، فَجَاءَ شُيُوخُ الضهلَالِ وَالْمُزَاحِوُْنَ لِلرُّبُوبِيهةِ الهذِينَ أَسَاسُ مَشْيَخَتِهِمْ عَلَى الشِّ رَكِ وَالْبِدْعَةِ، فَأَرَادُوا مِنْ مُرِيدِيهِمْ أَنْ يَـتَـعَبهدُوا لَهمُْ، فزيّنوا لهم حلق رؤوسهم لَهمُْ كَمَا زَيهـنُوا لَهمُُ السُّجُودَ لَهمُْ، وَسَمهوْهُ بِغَيِْر اسِْمهِ، وَقَالُوا: هُوَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَضْعُ الهرأْسِ بَـيَْن يَدَيِ الشهيْخِ، وَلَعَمْرُ ا هلِلَّ إِنه السُّجُودَ هِلِلَّ هُوَ وَضْعُ الهرأْسِ بَـيَْن يَدَيْهِ سُبْحَانَهُ، وَزَيهـنُوا لَهمُْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'أَنْ يَـنْذُرُوا لَهمُْ، وَيَـتُوبُوا لَهمُْ، وَيَْحلِفُوا بَِأسَْمائِهِمْ، وَهَذَا هُوَ اتَِّخاذُهُمْ أَرْبَابًا وَآلَِهةً مِنْ دُونِ ا هلِلَّ، قَالَ تَـعَالَى مَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'كانَ لِبَشَرٍ أَنْ يُـؤْتِيَهُ ا هللَُّ الْكِتابَ وَالُْحكْمَ وَالنُّـبُـهوةَ ُ مه يَـقُولَ لِلنهاسِ كُونُوا عِباداً لِِ مِنْ دُونِ ا هلِلَّ وَلكِنْ كُونُوا رَهبانِيِّيَن بِما كُنْـتُمْ تُـعَلِّمُونَ الْكِتابَ ، وَبِما كُنْـتُمْ تَدْرُسُونَ وَلا مََُْرَكُمْ أَنْ تَـتهخِذُوا الْمَلائِكَةَ وَالنهبِيِّيَن أَرْبابًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'أَمََُْرُكُمْ بِالْكُفْرِ بَـعْدَ إِذْ أَنْـتُمْ مُسْلِمُونَ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَأَشْرَفُ الْعُبُودِيهةِ عُبُودِيهةُ الصهلَاةِ، وَقَدْ تَـقَاسََمهَا الشهيُوخُ وَالْمُتَشَبِّهُونَ بِالْعُلَمَاءِ وَالَْجبَابِرَةُ، فَأَخَذَ الشهيُوخُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'مِنْـهَا أَشْرَفَ مَا فِيهَا، وَهُوَ السهجُودُ، وَأَخَذَ الْمُتَشَبِّهُونَ بِالْعُلَمَاءِ مِنْـهَا الرُّكُوعَ، فَإِذَا لَقِيَ بَـعْضُهُمْ بَـعْضًا ركََعَ له كما يركع المصلي لربه سواء', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, '(7) آل عمران- 19، 91', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَأَخَذَ الَْجبَابِرَةُ مِنْـهُمُ الْقِيَامَ، فَـيَـقُومُ الَْأحْ رَارُ وَالْعَبِيدُ على رؤوسهم عُبُودِيهةً لَهمُْ، وَهُمْ جُلُوسٌ ، وَقَدْ نَـهَى رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَنْ هَذِهِ الُْأمُورِ الثهلَاثَةِ عَلَى التهـفْصِيلِ، فَـتَـعَاطِيهَا مَُخالَفَةٌ صَرِيَحةٌ لَهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'فَـنَـهَى عَنِ السُّجُودِ لِغَيِْر ا هلِلَّ وَقَالَ: «لَا يَـنْـبَغِي لَِأحَدٍ أَنْ يَسْجُدَ لَِأحَدٍ» . وَأَنْكَرَ عَلَى معاذ لَمها سَجَدَ لَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَقَالَ: «مَهْ» »7« . وَتَرَِْيُم هَذَا مَعْلُومٌ مِنْ دِينِهِ بِالضهرُورَةِ، وَتَوَِْيزُ مَنْ جَ هوزَهُ لِغَيِْر ا هلِلَّ مُرَاغَمَةٌ هِلِلَّ وَرَسُولِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَهُوَ مِنْ أَبْـلَغِ أَنْـوَاعِ الْعُبُودِيهةِ، فَإِذَا جَ هوزَ هَذَا الْمُشْرِكُ هَذَا النهـوْعَ لِلْبَشَرِ، فَـقَدْ جَ هوزَ الْعُبُودِيهةَ لِغَيِْر ا هلِلَّ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'وَقَدْ صَحه أَنههُ قِيلَ لَهُ: الهرجُلُ يَـلْقَى أَخَاهُ أَيَـنْحَنِِ لَهُ؟ قَالَ: «لا» . قيل أيلتزمه ويقلّه قَالَ: «لَا» . قِيلَ أَيُصَافِحُهُ؟ قَالَ «نَـعَمْ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَأَيْضًا: فَالِانِْنَْاءُ عِنْدَ التهحِيهةِ سُجُودٌ، وَمِنْهُ قَـوْلُهُ تَـعَالَى: وَادْخُلُوا الْبابَ سُجهداً »3« أَيْ مُنْحَنِيَن، وَإِهلا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'فَلَا يُْمكِنُ الدهخُولُ عَلَى الِْجبَاهِ، وَصَحه عَنْهُ النهـهْيُ عَنِ الْقِيَامِ، وَهُوَ جَالِسٌ ، كَمَا تُـعَظِّمُ الَْأعَاجِمُ بَـعْضُهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'بَـعْضًا، حَ هتى مَنَعَ مِنْ ذَلِكَ فِي الصهلَاةِ، وَأَمَرَهُمْ إِذَا صَلهى جَالِسًا أَنْ يُصَلُّوا جُلُوسًا، وَهُمْ أَصِحهاءُ لَا عُذْرَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'لَهمُْ، لِئَهلا يَـقُومُوا عَلَى رَأْسِهِ وَهُوَ جَالِسٌ ، مَعَ أَنه قِيَامَهُمْ هِلِلَّ، فَكَيْفَ إِذَا كَانَ الْقِيَامُ تَـعْظِيمًا وَعُبُودِيهةً لِغَيِْرهِ سُبْحَانَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَالْمَقْصُودُ: أَنه النُّـفُوسَ الَْجاهِلَةَ الضهالهةَ أَسْقَطَتْ عُبُودِيهةَ ا هلِلَّ سُبْحَانَهُ، وَأَشْرَكَتْ فِيهَا مَنْ تُـعَظِّمُهُ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'الَْخلْقِ، فَسَجَدَتْ لِغَيِْر ا هلِلَّ، وَركََعَتْ لَهُ، وَقَامَتْ بَـيَْن يَدَيْهِ قِيَامَ الصهلَاةِ، وَحَلَفَتْ بِغَيِْرهِ، وَنَذَرَتْ لغيره، وحلقت لغيره، وذبحت لغيره، وطافت بغير بَـيْتِهِ وَعَظهمَتْهُ بِالُْحبِّ ، وَالَْخوْفِ، وَالهرجَاءِ، وَالطهاعَةِ، كَمَا يُـعَظهمُ الَْخالِقُ، بَلْ أَشَدُّ، وَسَ هوتْ مَنْ تَـعْبُدُهُ مِنَ الْمَخْ لُوقِيَن بِرَبِّ الْعَالَمِيَن، وَهَؤُلَاءِ هُمُ الْمُضَادُّونَ لِدَعْوَةِ الرُّسُلِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَهُمُ اهلذِينَ بِرَهبِهمْ يَـعْدِلُونَ، وَهُمُ اهلذِينَ يَـقُولُونَ- وَهُمْ فِي النهارِ مَعَ آلَِهتِهِمْ يخصمون- تَا هلِلَّ إِنْ كُنها لَفِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'ضَلالٍ مُبِيٍن إِذْ نُسَوِّيكُمْ بِرَبِّ الْعالَمِيَن. »4« وَهُمُ الهذِينَ قَالَ فِيهِمْ وَمِنَ النهاسِ مَنْ يَـتهخِذُ مِنْ دُونِ ا هلِلَّ أَنْداداً يُِحبُّونَـهُمْ كَحُبِّ ا هلِلَّ وَالهذِينَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, '(7) أخرجه الإمام أحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, '(2) أخرجه الترمذي في الاستئذان، وابن ماجه في الأدب، وأحدْ (3) البقرة- 59', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, '(4) الشعراء- 99', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'آمَنُوا أَشَدُّ حُبًّا هِلِلَّ »7« هذا كُلُّهُ مِنَ الشِّ رْكِ، وَا هللَُّ لَا يَـغْفِرُ أَنْ يُشْرَكَ بِهِ. فَـهَذَا فَصْلٌ مُعْتَـرَضٌ فِي هَدْيِهِ فِي حَلْقِ الهرأْسِ ، وَلَعَلههُ أَهَمُّ مِمها قُصِدَ الكلام فيه، والله الموفق.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, '[القسم الثاني وهو] فُصُولٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي الْعِلَاجِ بِالَْأدْوِيَةِ الرُّوحَانِيهةِ الِْإلَِهيهةِ الْمُفْرَدَةِ، وَالْمُرَكهبَةِ مِنْـهَا، وَمِنَ الَْأدْوِيَةِ الطهبِيعِيهةِ', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الْمُصَابِ بِالْعَيِْن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى مسلم فِي «صَحِيحِهِ» عَنِ ابْنِ عَبهاسٍ ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «الْعَيُْن حَقٌّ وَلَوْ كَانَ شَيْ ءٌ سَابَقَ الْقَدَرَ، لَسَبَـقَتْهُ الْعَيُْن» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَفِي «صَحِيحِهِ» أَيْضًا عَنْ أنس، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وسلم رخّص في الرّقية من الحمىّ وَالْعَيِْن وَالنهمْلَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '. »3«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَفِي «الصهحِيحَيِْن» مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «الْعَيُْن حَقٌّ» »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَفِي «سُنَنِ أبي داود» عَنْ عائشة رَضِيَ ا هللَُّ عَنْـهَا قَالَتْ : كَانَ يُـؤْمَرُ الْعَائِنُ فَـيَـتَـوَضهأُ ُ مه يَـغْتَسِلُ مِنْهُ الْمَعِيُن» »5« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَفِي «الصهحِيحَيِْن» عَنْ عائشة قَالَتْ أَمَرَنِي النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، أَوْ أَمَرَ أَنْ نَسْتَـرْقِيَ مِنَ الْعَيِْن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '. »1«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَذكََرَ الترمذي، مِنْ حَدِيثِ سُفْيَانَ بْنِ عُيَـيْـنَةَ، عَنْ عَمْرِو بْنِ دِينَارٍ، عن عروة (7) البقرة- 715', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, '(2) أخرجه مسلم في السلام، وأخرجه أيضا أحدْ وابن حبان والحاكم والطباَني (3) أخرجه مسلم في السلام', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, '(4) أخرجه البخاري في الطب ومسلم في السلام', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, '(5) أخرجه أبو داود في الطب. ورجاله ثقات، وإسناده صحيح. وأخرجه ابن ماجه والنسائي (1) أخرجه البخاري في الطب ومسلم في السلام', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'ابن عامر، عَنْ عبيد بن رفاعة الزرقي، أَنه أسماء بنت عميس، قَالَتْ : يَا رَسُولَ ا هلِلَّ! إِنه بَنِِ جَعْفَرٍ تُصِ يبُـهُمُ الْعَيُْن أَفَأَسْتَـرْقِي لَهمُْ؟ فَـقَالَ نَـعَمْ فَـلَوْ كَانَ شَيْ ءٌ يَسْبِقُ الْقَضَاءَ لَسَبَـقَتْهُ الْعَيُْن» قَالَ الترمذي:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'حَدِيثٌ حَسَنٌ صَحِيحٌ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَرَوَى مالك رَحِهَُْ ا هللَُّ: عَنِ ابْنِ شِهَابٍ عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَـيْفٍ ، قَالَ: رَأَى عَامِرُ بْنُ رَبِيعَةَ سَهْلَ بْنَ حُنَـيْفٍ يَـغْتَسِلُ، فَـقَالَ: وَا هلِلَّ مَا رَأَيْتُ كَالْيَـوْمِ وَلَا جِلْدَ مَُخبهأَةٍ قَالَ: فَـلُبِطَ سهل، فَأَتَى رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عامرا، فَـتَـغَيهظَ عَلَيْهِ وَقَالَ: «عَلَامَ يَـقْتُلُ أَحَدُكُمْ أَخَاهُ أَلَا بَـهركْتَ اغْتَسِلْ لَهُ» ، فَـغَسَلَ لَهُ عامر وَجْ هَهُ وَيَدَيْهِ وَمِرْفَـقَيْهِ وَركُْبَـتَـيْهِ، وَأَطْرَافَ رِجْ لَيْهِ، وَدَاخِلَةَ إِزَارِهِ فِي قَدَحٍ، ُ مه صَبه عَلَيْهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'فَـرَاحَ مَعَ النهاسِ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَرَوَى مالك رَحِهَُْ ا هللَُّ أَيْضًا عَنْ محمد بن أبي أمامة بن سهل، عَنْ أَبِيهِ هَذَا الَْحدِيثَ ، وَقَالَ فِيهِ إِنه الْعَيَْن حَقٌّ، تَـوَضهأْ لَهُ فَـتَـوَضهأَ لَهُ »3«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَذكََرَ عبد الرزاق، عَنْ معمر عَنِ ابن طاووس، عَنْ أَبِيهِ مَرْفُوعًا «الْعَيُْن حَقٌّ، وَلَوْ كَانَ شَيْ ءٌ سَابَقَ الْقَدَرَ، لَسَبَـقَتْهُ الْعَيُْن، وَإِذَا اسْتُـغْسِلَ أحكم، فَـلْيَـغْتَسِلْ» »4« وَوَصْلُهُ صَحِيحٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'قَالَ الزُّهْرِيُّ: يُـؤْمَرُ الهرجُلُ الْعَائِنُ بِقَدَحٍ، فَـيُدْخِلُ كَ هفهُ فِيهِ، فَـيَـتَمَضْمَضُ ، ُ مه يَُمجُّهُ فِي الْقَدَحِ، وَيَـغْسِلُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَجْ هَهُ فِي الْقَدَحِ، ُ مه يُدْخِلُ يَدَهُ الْيُسْرَى، فَـيَصُبُّ عَلَى ركُْ بَتِهِ اليمنى في القدح، م يدل يَدَهُ الْيُمْنَى، فَـيَصُبُّ عَلَى ركُْ بَتِهِ الْيُسْرَى، ُ مه يَـغْسِلُ دَاخِلَةَ إِزَارِهِ، وَلَا يُوضَعُ الْقَدَحُ فِي الَْأرْضِ ، ُ مه يُصَبُّ عَلَى رَأْسِ الهرجُلِ الهذِي نصيبه الْعَيُْن مِنْ خَلْفِهِ صَبهةً وَاحِدَةً »5« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَالْعَيُْن: عَيْـنَانِ: عَيٌْن إِنْسِيهةٌ، وَعَيٌْن جِنِّيهةٌ، فَـقَدْ صَحه عَنْ أم سلمة، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ رَأَى فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'بَـيْتِهَا جَارِيَةً فِي وَجْ هِهَا سَفْعَةٌ،، فَـقَالَ: «اسْتَـرْقُوا لََها، فَإِنه بَِها النهظْرَةَ» »1« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, '(7) أخرجه الترمذي وأحدْ وابن ماجه والنسائي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, '(2) أخرجه مالك في الموطأ، وأخرجه النسائي وابن ماجه وأحدْ وابن حبان والحاكم في صحيحهما (3) أخرجه مالك في الموطأ وابن ماجه وأحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, '(4) أخرجه عبد الرزاق في المصنف (5) ذكره البيهقي في السنن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, '(1) أخرجه البخاري في الطب، ومسلم في السلام. والحاكم وأبو نعيم', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'قَالَ الحسين بن مسعود الفراء: وَقَـوْلُهُ «سَفْعَةٌ» أَيْ نَظْرَةٌ يَـعْنِِ: مِنَ الِْجنِّ. يَـقُولُ: بَِها عَيٌْن أَصَابَـتْـهَا مِنْ نَظَرِ الِْجنِّ أَنْـفَذُ مِنْ أَسِنهةِ الرِّمَاحِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَيُذْكَرُ عَنْ جابر يَـرْفَـعُهُ: «إِنه العين لتخل الرّجل القبظر، وَالَْجمَلَ الْقِدْرَ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَعَنْ أبي سعيد، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ يَـتَـعَهوذُ مِنَ الَْجانِّ ، وَمِنْ عَيِْن الِْإنْسَانِ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'فَأَبْطَلَتْ طَائِفَةٌ مِمهنْ قَله نَصِ يبُـهُمْ مِنَ السهمْعِ وَالْعَقْلِ أَمْرَ الْعَيِْن، وقالوا: إنما ذلك أوهام لا حقيقة لها،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَهَؤُلَاءِ مِنْ أَجْهَلِ النهاسِ بِالسهمْعِ وَالْعَقْلِ، وَمِنْ أَغْلَظِهِمْ حِجَابًا، وَأَكْثَفِهِمْ طِبَاعًا، وَأَبْـعَدِهِمْ مَعْرِفَةً عَنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'الَْأرْوَاحِ وَالنُّـفُوسِ وَصِ فَاتَِها وَأَفْـعَالَِها وَتَثَِْيَراتَِها، وَعُقَلَاءُ الُْأمَمِ عَلَى اخْتِلَافِ مِلَلِهِمْ وَنِلَِْهِمْ لَا تَدْفَعُ أَمْرَ العين ولا تنكره، وإن اختلفوا في سببه وَجِهَةِ تَثَِْيِر الْعَيِْن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'فَـقَالَتْ طَائِفَةٌ: إِنه الْعَائِنَ إِذَا تَكَيهـفَتْ نَـفْسُهُ بِالْكَيْفِيهةِ الهردِيئَةِ، انْـبَـعَثَ مِنْ عَيْنِهِ قُـهوةٌ سُِّميهةٌ تَـتهصِلُ بِالْمَعِيِن، فَـيَـتَضَ هررُ. قَالُوا وَلَا يُسْتَـنْكَرُ هَذَا، كَمَا لَا يُسْتَـنْكَرُ انْبِعَاثُ قُـهوةٍ سُِّميهةٍ مِنَ الَْأفْـعَى تَـتهصِلُ بِالِْإنْسَانِ، فَـيَـهْلَكُ ، وَهَذَا أَمْرٌ قَدِ اشْتُهِرَ عَنْ نَـوْعٍ مِنَ الَْأفَاعِي أَنهـهَا إِذَا وَقَعَ بَصَرُهَا عَلَى الِْإنْسَانِ هَلَكَ فَكَذَلِكَ الْعَائِنُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وَقَالَتْ فِرْقَةٌ أُخْ رَى: لَا يُسْتَـبْـعَدُ أَنْ يَـنْـبَعِثَ مِنْ عَيِْن بَـعْضِ النهاسِ جَوَاهِرُ لَطِيفَةٌ غَيْـرُ مَرْئِيهةٍ، فَـتَـتهصِلُ بِالْمَعِيِن، وَتَـتَخَلهلُ مَسَامه جِسْمِهِ، فَـيَحْصُلُ لَهُ الضهرَرُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'وَقَالَتْ فِرْقَةٌ أُخْ رَى: قَدْ أَجْ رَى ا هللَُّ الْعَادَةَ خِلَِْقِ مَا يَشَاءُ مِنَ الضهرَرِ عِنْدَ مُقَابَـلَةِ عَيِْن الْعَائِنِ لِمَنْ يَعِينُهُ مِنْ غَيِْر أَنْ يَكُونَ مِنْهُ قُـهوةٌ وَلَا سَبَبٌ وَلَا تَثَِْيٌر أَصْلًا، وَهَذَا مَذْهَبُ مُنْكِرِي الَْأسْبَابِ وَالْقُوَى وَالتهأْثِيَراتِ فِي الْعَالََِ، وَهَؤُلَاءِ قَدْ سَدُّوا عَلَى أَنْـفُسِهِمْ بَابَ الْعِلَلِ وَالتهأْثِيَراتِ وَالَْأسْبَابِ، وَخَالَفُوا الْعُقَلَاءَ أَجْعََِيَن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'وَلَا رَيْبَ أَنه ا هللََّ سُبْحَانَهُ خَلَقَ فِي الَْأجْسَامِ وَالَْأرْوَاحِ قُـوًى وَطَبَائِعَ مُْختَلِفَةً، وَجَعَلَ فِي كَثِيٍر مِنْـهَا خَوَاصه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'وَكَيْفِيهاتٍ مُؤَثِّرَةً، وَلَا يُْمكِنُ لِعَاقِلٍ إِنْكَارُ تثَير الأرواح في', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, '(7) أخرجه البزار بسند حسن بمعناه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, '(2) أخرجه النسائي وابن ماجه، والترمذي وحسنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'الَْأجْسَامِ، فَإِنههُ أَمْرٌ مُشَاهَدٌ مَسُُْوسٌ ، وَأَنْتَ تَـرَى الْوَجْ هَ كَيْفَ يَْحمَرُّ حُرَْْةً شَدِيدَةً إِذَا نَظَرَ إليه من يحتشمه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'ويستحي منهج وَيَصْفَرُّ صُفْرَةً شَدِيدَةً عِنْدَ نَظَرِ مَنْ يََخافُهُ إِلَيْهِ، وَقَدْ شَاهَدَ النهاسُ مَنْ يَسْقَمُ مِنَ النهظَرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'وَتَضْعُفُ قُـوَاهُ، وَهَذَا كُلُّهُ بِوَاسِطَةِ تَثَِْيِر الَْأرْوَاحِ، وَلِشِدهةِ ارْتِبَاطِهَا بِالْعَيِْن يُـنْسَبُ  الْفِعْلُ إِلَيْـهَا، وَلَيْسَتْ  هِيَ الْفَاعِلَةَ، وَإِهنَما التهأْثِيُر لِلرُّوحِ، وَالَْأرْوَاحُ مُْختَلِفَةٌ فِي طَبَائِعِهَا وَقُـوَاهَا وَكَيْفِيهاتَِها وَخَوَاصِّهَا، فَـرُوحُ الَْحاسِدِ مُؤْذِيَةٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'لِلْمَحْسُودِ أَذًى بَـيِّنًا، وَلَِهذَا أَمَرَ ا هللَُّ- سُبْحَانَهُ رَسُولَهُ أَنْ يَسْتَعِيذَ بِهِ مِنْ شَرِّهِ، وَتَثَِْيُر الَْحاسِدِ فِي أَذَى الْمَحْسُودِ أَمْرٌ لَا يُـنْكِرُهُ إِهلا مَنْ هُوَ خَارِجٌ عَنْ حَقِيقَةِ الِْإنْسَانِيهةِ، وَهُوَ أَصْلُ الِْإصَابَةِ بِالْعَيِْن، فَإِنه النهـفْسَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'الَْخبِيثَةَ الَْحاسِدَةَ تَـتَكَيهفُ بِكَيْفِيهةٍ خَبِيثَةٍ، وَتُـقَابِلُ الْمَحْسُودَ، فَـتُـؤَثِّرُ فِيهِ بِتِلْكَ الَْخاصِّ يهةِ، وَأَشْبَهُ الَْأشْيَاءِ بَِهذَا الَْأفْـعَى فَإِنه السُّمه كَامِنٌ فِيهَا بِالْقُهوةِ، فَإِذَا قَابَـلَتْ عَدُ هوهَا انْـبَـعَثَتْ مِنْـهَا قُـهوةٌ غَضَبِيهةٌ، وَتَكَيهـفَتْ بِكَيْفِيهةٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'خَبِيثَةٍ مُؤْذِيَةٍ، فَمِنْـهَا مَا تَشْتَدُّ كَيْفِيهـتُـهَا وَتَـقْوَى حَ هتى تُـؤَثِّرَ فِي إِسْقَاطِ الَْجنِيِن، وَمِنْـهَا مَا تُـؤَثِّرُ فِي طَمْسِ الْبَصَرِ، كَمَا قَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي الَْأبْـتَِر، وَذِي الطُّفْيَـتَـيِْن مِنَ الَْحيهاتِ «إِنهـهُمَا يَـلْتَمِسَانِ الْبَصَرَ، وَيُسْقِطَانِ الَْحبَلَ» » .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'وَمِنْـهَا، مَا تُـؤَثِّرُ فِي الِْإنْسَانِ كَيْفِيهـتُـهَا بُِمجَ هردِ الرُّؤْيَةِ مِنْ غَيِْر اتِّصَالٍ بِهِ لِشِدهةِ خُبْثِ تِلْكَ النهـفْسِ ، وَكَيْفِيهتِهَا الَْخبِيثَةِ الْمُؤَثِّرَةِ وَالتهأْثِيُر غَيْـرُ مَوْقُوفٍ عَلَى الِاتِّصَالَاتِ الِْجسْمِيهةِ، كَمَا يَظُنُّهُ مَنْ قَله عِلْمُهُ وَمَعْرِفَـتُهُ بِالطهبِيعَةِ وَالشهرِيعَةِ، بَلِ التهأْثِيُر يَكُونُ تَارَةً بِالِاتِّصَالِ، وَتَارَةً بِالْمُقَابَـلَةِ، وَتَارَةً بِالرُّؤْيَةِ، وَتَارَةً بِتَـوَجُّهِ الرُّوحِ نَوَْْ مَنْ يُـؤَثِّرُ فِيهِ وَتَارَةً بِالَْأدْعِيَةِ وَالرُّقَى وَالتهـعَوُّذَاتِ، وَتَارَةً بِالْوَهْمِ وَالتهخَيُّلِ، وَنَـفْسُ الْعَائِنِ لَا يَـتَـوَقهفُ تَثَِْيُرهَا عَلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'الرُّؤْيَةِ، بَلْ قَدْ يَكُونُ أَعْمَى، فَـيُوصَفُ لَهُ الشهيْ ءُ، فَـتُـؤَثِّرُ نَـفْسُهُ فِيهِ وَإِنْ لََْ يَـرَهُ، وَكَثِيٌر مِنَ الْعَائِنِيَن يُـؤَثِّرُ فِي الْمَعِيِن بِالْوَصْفِ مِنْ غَيِْر رُؤْيَةٍ وَقَدْ قَالَ تَـعَالَى لِنَبِيِّهِ وَإِنْ يَكادُ الهذِينَ كَفَرُوا لَيُـزْلِقُونَكَ بَِأبْصارِهِمْ لَمها سَِمعُوا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 48, 'الذِّكْ رَ »2« وَقَالَ: قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ مِنْ شَرِّ مَا خَلَقَ وَمِنْ شَرِّ غاسِقٍ إِذا وَقَبَ وَمِنْ شَرِّ النهـهفاثتَِ فِي الْعُقَدِ وَمِنْ شَرِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 49, '(7) أخرجه البخاري في بدأ الخلق، ومسلم في السلام. وقد سمي بذلك لأن على ظهره خطين يشبهان الطّفيتين، اي الخوصتين. والأبتر: قصير الذنب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 50, '(2) القلم- 57', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 51, 'حاسِدٍ إِذا حَسَدَ، فَكُلُّ عَائِنٍ حَاسِدٌ، وَلَيْسَ كُلُّ حَاسِدٍ عَائِنًا، فَـلَمها كَانَ الَْحاسِدُ أَعَمه مِنَ الْعَائِنِ كَانَتِ الِاسْتِعَاذَةُ مِنْهُ اسْتِعَاذَةً مِنَ الْعَائِنِ، وَهِيَ سِهَامٌ تَْخرُجُ مِنْ نَـفْسِ الَْحاسِدِ وَالْعَائِنِ نَوَْْ الْمَحْسُودِ وَالْمَعِيِن تُصِيبُهُ تَارَةً وَتُْخطِئُهُ تَارَةً، فَإِنْ صَادَفَـتْهُ مَكْشُوفًا لَا وِقَايَةَ عَلَيْهِ، أَثهـرَتْ فِيهِ، وَلَا بُده، وَإِنْ صَادَفَـتْهُ حَذِرًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 52, 'شَاكِيَ السِّ لَاحِ لَا مَنْـفَذَ فِيهِ لِلسِّ هَامِ، لََْ تُـؤَثِّرْ فِيهِ، وَرُهبَما رُدهتِ السِّ هَامُ عَلَى صَاحِبِهَا، وَهَذَا بَِمثَابَةِ الهرمْيِ الِْحسِّ يِّ سَوَاءً فَـهَذَا مِنَ النُّـفُوسِ وَالَْأرْوَاحِ، وَذَاكَ مِنَ الَْأجْسَامِ وَالَْأشْبَاحِ. وَأَصْلُهُ مِنْ إِعْجَابِ الْعَائِنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 53, 'بِالشهيْ ءِ، ُ مه تَـتْـبَـعُهُ كَيْفِيهةُ نَـفْسِهِ الَْخبِيثَةِ، ُ مه تَسْتَعِيُن عَلَى تَـنْفِيذِ سُِّمهَا بِنَظْرَةٍ إِلَى الْمَعِيِن، وَقَدْ يَعِيُن الهرجُلُ نَـفْسَهُ، وَقَدْ يَعِيُن بِغَيِْر إِرَادَتِهِ بَلْ بِطَبْعِهِ، وَهَذَا أَرْدَأُ مَا يَكُونُ مِنَ النهـوْعِ الِْإنْسَانِِّي وَقَدْ قَالَ أَصْحَابُـنَا وَغَيْـرُهُمْ مِنَ الْفُقَهَاءِ: إِنه مَنْ عُرِفَ بِذَلِكَ حَبَسَهُ الِْإمَامُ، وَأَجْ رَى لَهُ مَا يُـنْفِقُ عَلَيْهِ إِلَى الموت، وهذا هو الصواب قطعا.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَالْمَقْصُودُ: الْعِلَاجُ النهـبَوِيُّ لَِهذِهِ الْعِلهةِ، وَهُوَ أَنْـوَاعٌ، وَقَدْ رَوَى أبو داود فِي «سُنَنِهِ» عَنْ سَهْلِ بْنِ حُنَـيْفٍ، قَالَ: مَرَرْنَا بِسَيْلٍ، فَدَخَلْتُ ، فَاغْتَسَلْتُ فِيهِ، فَخَرَجْتُ مَمُُْومًا، فَـنُمِيَ ذَلِكَ إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وسلم، فَـقَالَ: «مُرُوا أبا ثبَت يَـتَـعَهوذُ» ، قَالَ: فَـقُلْتُ يَا سَيِّدِي! وَالرُّقَى صَالَِحةٌ؟ فَـقَالَ «لَا رُقْـيَةَ إِهلا فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'نَـفْسٍ ، أَوْ حُةٍَْ أَوْ لَدْغَةٍ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَالنهـفْسُ : الْعَيُْن، يُـقَالُ: أَصَابَتْ فُلَانًا نَـفْسٌ ، أَيْ عَيٌْن. وَالنهافِسُ الْعَائِنُ. وَاللهدْغَةُ- بِدَالٍ مُهْمَلَةٍ وَغَيٍْن مُعْجَمَةٍ- وَهِيَ ضَرْبَةُ الْعَقْرَبِ وَنَوَْْهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'فَمِنَ التهـعَوُّذَاتِ وَالرُّقَى الِْإكْ ثَارُ مِنْ قِرَاءَةِ الْمُعَوِّذَتَـيِْن وَفَاتِةََِ الْكِتَابِ، وَآيَةِ الْكُرْسِيِّ، وَمِنْـهَا التهـعَوُّذَاتُ النهـبَوِيهةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'نَوَْْ أَعُوذُ بِكَلِمَاتِ ا هلِلَّ التهامهاتِ مِنْ شَرِّ مَا خَلَقَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(7) أخرجه أبو داود في الطب، وأخرجه الحاكم', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَنَوَْْ: أَعُوذُ بِكَلِمَاتِ ا هلِلَّ التهامهةِ مِنْ كُلِّ شَيْطَانٍ وَهَامهةٍ، وَمِنْ كُلِّ عَيٍْن لَامهةٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَنَوَْْ أَعُوذُ بِكَلِمَاتِ ا هلِلَّ التهامهاتِ الهتِي لَا يَُجاوِزُهُنه بَـرٌّ وَلَا فَاجِرٌ، مِنْ شَرِّ مَا خَلَقَ وَذَرَأَ وَبَـرَأَ، وَمِنْ شَرِّ مَا يَـنْزِلُ مِنَ السهمَاءِ، وَمِنْ شَرِّ مَا يَـعْرُجُ فِيهَا، وَمِنْ شَرِّ مَا ذَرَأَ فِي الَْأرْضِ ، وَمِنْ شَرِّ ما يخرج منها، ومن شرّفتُ اللهيْلِ، وَالنهـهَارِ، وَمِنْ شَرِّ طَوَارِقِ اللهيْلِ إِهلا طَارِقًا يَطْرُقُ خِيٍَِْر يَا رَحْنَُْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَمِنْـهَا: أَعُوذُ بِكَلِمَاتِ ا هلِلَّ التهامهةِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَمِنْ شَرِّ عِبَادِهِ، وَمِنْ هَزََُاتِ الشهيَاطِيِن وَأَنْ يَْحضُرُونِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَمِنْـهَا: اللههُمه إِنِّي أَعُوذُ بِوَجْ هِكَ الْكَرِيِم، وَكَلِمَاتِكَ التهامهاتِ مِنْ شَرِّ مَا أَنْتَ آخِذٌ بِنَاصِ يَتِهِ اللههُمه أَنْتَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'تَكْشِفُ الْمَأََْ م وَالْمَغْرَمَ، اللههُمه إِنههُ لَا يُـهْزَمُ جُنْدُكَ، وَلَا يُْخلَفُ وَعْدُكُ، سُبْحَانَكَ وَبَِحمْدِكَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَمِنْـهَا: أَعُوذُ بِوَجْهِ ا هلِلَّ الْعَظِيمِ الهذِي لَا شَيْ ءَ أَعْظَمُ مِنْهُ، وَبِكَلِمَاتِهِ التهامهاتِ الهتِي لَا يَُجاوِزُهُنه بَـرٌّ وَلَا فَاجِرٌ، وَأَسَْماءِ ا هلِلَّ الُْحسْنَى، مَا عَلِمْتُ مِنْـهَا وَمَا لََْ أَعْلَمْ، مِنْ شَرِّ مَا خَلَقَ وَذَرَأَ وَبَـرَأَ، وَمِنْ شَرِّ كُلِّ ذِي شَرٍّ لَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'أُطِيقُ شَ هرهُ، وَمِنْ شَرِّ كُلِّ ذِي شَرٍّ أَنْتَ آخِذٌ بِنَاصِ يَتِهِ، إِنه رَبِّي عَلَى صِرَاطٍ مُسْتَقِيمٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَمِنْـهَا اللههُمه أَنْتَ رَبِّي لَا إِلَهَ إِهلا أَنْتَ ، عَلَيْكَ تَـوَكهلْتُ ، وَأَنْتَ رَبُّ الْعَرْشِ الْعَظِيمِ، مَا شَاءَ ا هللكََُّانَ، وَمَا لََْ يَشَأْ لََْ يَكُنْ ، لَا حَوْلَ وَلَا قُـهوةَ إِهلا بِا هلِلَّ، أَعْلَمُ أَنه ا هللََّ عَلَى كُلِّ شَيْ ءٍ قَدِيرٌ، وَأَنه ا هللََّ قَدْ أَحَاطَ بِكُلِّ شَيْ ءٍ عِلْمًا، وَأَحْصَى كُله شَيْ ءٍ عَدَدًا، اللههُمه إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ نَـفْسِي، وَشَرِّ الشهيْطَانِ وَشِرْكِهِ، وَمِنْ شَرِّ كُلِّ دَابهةٍ أَنْتَ آخِذٌ بِنَاصِ يَتِهَا، إِنه رَبِّي عَلَى صِ رَاطٍ مُسْتَقِيمٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَإِنْ شَاءَ قَالَ تَصََهنْتُ بِا هلِلَّ الهذِي لَا إِلَهَ إِهلا هُوَ، إِلَِهي وَإِلَهِ كُلِّ شَيْ ءٍ، وَاعْتَصَمْتُ بِرَبِّي وَرَبِّ كُلِّ شَيْ ءٍ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَتَـوَكهلْتُ عَلَى الَْحيِّ الهذِي لَا يَُموتُ ، وَاسْتَدْفَـعْتُ الشه هر بِلَا حَوْلَ وَلَا قُـهوةَ إِهلا بِا هلِلَّ، حَسْبَِ ا هللَُّ وَنِعْمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'الْوَكِيلُ، حَسْبَِ الهربُّ مِنَ الْعِبَادِ، حَسَبَِ الَْخالِقُ مِنَ الْمَخْ لُوقِ، حَسَبَِ الهرازِقُ مِنَ الْمَرْزُوقِ حَسْبَِ الهذِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'هُوَ حَسْبِ، حَسْبَِ الهذِي بِيَدِهِ مَلَكُوتُ كُلِّ شَيْ ءٍ، وَهُوَ يُِجيُر وَلَا يَُجارُ عَلَيْهِ حَسْبَِ ا هللَُّ وَكَفَى، سَِمعَ ا هللَُّ لِمَنْ دَعَا، لَيْسَ وَرَاءَ ا هلِلَّ مَرْمَى، حَسْبَِ ا هللَُّ لَا إِلَهَ إِهلا هُوَ، عَلَيْهِ تَـوَكهلْتُ ، وَهُوَ رَبُّ الْعَرْشِ العظيم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَمَنْ جَ هربَ هَذِهِ الدهعَوَاتِ وَالْعُوَذَ، عَرَفَ مِقْدَارَ مَنْـفَعَتِهَا، وَشِدهةَ الَْحاجَةِ إِلَيْـهَا، وَهِيَ تَنََْعُ وُصُولَ أَثَرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'الْعَائِنِ، وَتَدْفَـعُهُ بَـعْدَ وُصُولِهِ بَِحسَبِ قُـهوةِ إِيَمانِ قَائِلِهَا، وَقُـهوةِ نَـفْسِهِ، وَاسْتِعْدَادِهِ، وَقُـهوةِ تَـوَكُّلِهِ وَثَـبَاتِ قَـلْبِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'فَإِنهـهَا سِلَاحٌ وَالسِّ لَاحُ بِضَارِبِهِ', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَإِذَا كَانَ الْعَائِنُ يَْخشَى ضَرَرَ عَيْنِهِ وَإِصَابَـتَـهَا لِلْمَعِيِن، فَـلْيَدْفَعْ شَ هرهَا بِقَوْلِهِ: اللههُمه بَارِكْ عَلَيْهِ، كَمَا قَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لِعَامِرِ بْنِ رَبِيعَةَ لَمها عَانَ سَهْلَ بْنَ حُنَـيْفٍ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '«أَلَا بَـهركْتَ » أَيْ : قُـلْتَ : اللههُمه بَارِكْ عَلَيْهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَمِمها يُدْفَعُ بِهِ إِصَابَةُ الْعَيِْن قَـوْلُ: مَا شَاءَ ا هللَُّ لَا قُـهوةَ إِهلا بِا هلِلَّ، رَوَى هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، أَنههُ كَانَ إِذَا رَأَى شَيْـئًا يُـعْجِبُهُ، أَوْ دَخَلَ حَائِطًا مِنْ حِيطَانِهِ، قَالَ: مَا شَاءَ ا هللَُّ، لَا قُـهوةَ إِهلا بِا هلِلَّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَمِنْـهَا رُقْـيَةُ جِبِْيَلَ عَلَيْهِ السهلَامُ لِلنهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ الهتِي رَوَاهَا مسلم فِي «صَحِيحِهِ» «بِاسْمِ ا هلِلَّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'أَرْقِيكَ ، مِنْ كُلِّ شَيْ ءٍ يُـؤْذِيكَ ، مِنْ شَرِّ كُلِّ نَـفْسٍ أَوْ عَيِْن حَاسِدٍ ا هللَُّ يَشْفِيكَ بِاسْمِ ا هلِلَّ أَرْقِيكَ » »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَرَأَى جَاََعَةٌ مِنَ السهلَفِ أَنْ تُكْتَبَ لَهُ الْآيَاتُ مِنَ الْقُرْآنِ، ُ مه يَشْرَبَـهَا. قَالَ ماَهد لَا بَْأسَ أَنْ يَكْتُبَ الْقُرْآنَ، وَيَـغْسِلَهُ، وَيَسْقِيَهُ الْمَرِيضَ ، وَمِثْـلُهُ عَنْ أبي قلابة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَيُذْكَرُ عَنِ ابْنِ عَبهاسٍ أَنههُ أَمَرَ أَنْ يُكْتَبَ لِامْرَأَةٍ تَـعَسهرَ عَلَيْـهَا وِلَادُهَا أَثَـرٌ مِنَ الْقُرْآنِ ُ مه يُـغْسَلُ وَتُسْقَى. وَقَالَ أيوب رَأَيْتُ أبا قلابة كَتَبَ كِتَابًا مِنَ الْقُرْآنِ ُ مه غَسَلَهُ بَِماءٍ، وَسَقَاهُ رَجُلًا كَانَ بِهِ وجع.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(7) أخرجه مسلم في السلام', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَمِنْـهَا أَنْ يُـؤْمَرَ الْعَائِنُ بِغَسْلِ مَغَابِنِهِ وَأَطْرَافِهِ وَدَاخِلَةِ إِزَارِهِ، وَفِيهِ قَـوْلَانِ أَحَدُهُاَُ أَنههُ فَـرْجُهُ. وَالثهانِي أَنههُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'طَرَفُ إِزَارِهِ الدهاخِلِ الهذِي يَلِي جَسَدَهُ مِنَ الَْجانِبِ الَْأيَْمنِ، ُ مه يُصَبُّ عَلَى رَأْسِ الْمَعِيِن مِنْ خَلْفِهِ بَـغْتَةً، وَهَذَا مِمها لَا يَـنَالُهُ عِلَاجُ الَْأطِبهاءِ، وَلَا يَـنْـتَفِعُ بِهِ مَنْ أَنْكَرَهُ، أَوْ سَخِرَ مِنْهُ، أَوْ شَكه فِيهِ، أَوْ فَـعَلَهُ مُرََِّبًا لَا يَـعْتَقِدُ أَنه ذَلِكَ يَـنْـفَعُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَإِذَا كَانَ فِي الطهبِيعَةِ خَوَاصُّ لَا تَـعْرِفُ الَْأطِبهاءُ عِلَلَهَا الْبَـتهةَ، بَلْ هِيَ عِنْدَهُمْ خَارِجَةٌ عَنْ قِيَاسِ الطهبِيعَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'تَـفْعَلُ بِالَْخاصِّ يهةِ، فَمَا الهذِي يُـنْكِرُهُ زَنَادِقَـتُـهُمْ وَجَهَلَتُـهُمْ مِنَ الَْخوَاصِّ الشهرْعِيهةِ، هَذَا مَعَ أَنه فِي الْمُعَالََجةِ بَِهذَا الِاسْتِغْسَالِ مَا تَشْهَدُ لَهُ الْعُقُولُ الصهحِيحَةُ، وَتُقِرُّ لِمُنَاسَبَتِهِ، فَاعْلَمْ أَنه تِرْيَاقَ سُمِّ الَْحيهةِ فِي لَْحمِهَا، وَأَنه عِلَاجَ تَثَِْيِر النهـفْسِ الْغَضَبِيهةِ فِي تَسْكِيِن غَضَبِهَا، وَإِطْفَاءِ نَارِهِ بِوَضْعِ يَدِكَ عَلَيْهِ وَالْمَسْحِ عَلَيْهِ، وَتَسْكِيِن غَضَبِهِ، وَذَلِكَ بَِمنْزِلَةِ رَجُلٍ مَعَهُ شُعْلَةٌ مِنْ نَارٍ، وَقَدْ أَرَادَ أَنْ يَـقْذِفَكَ بَِها، فَصَبَـبْتَ عَلَيْـهَا الْمَاءَ، وَهِيَ فِي يَدِهِ حَ هتى طُفِئَتْ ، وَلِذَلِكَ أُمِرَ الْعَائِنُ أَنْ يَـقُولَ: «اللههُمه بَارِكْ عَلَيْهِ لِيَدْفَعَ تِلْكَ الْكَيْفِيهةَ الَْخبِيثَةَ بِالدُّعَاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الهذِي هُوَ إِحْسَانٌ إِلَى الْمَعِيِن، فَإِنه دَوَاءَ الشهيْ ءِ بِضِدِّهِ، وَلَمها كَانَتْ هَذِهِ الْكَيْفِيهةُ الَْخبِيثَةُ تَظْهَرُ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الْمَوَاضِعِ الهرقِيقَةِ مِنَ الَْجسَدِ، لَِأنهـهَا تَطْلُبُ النُّـفُوذَ، فَلَا تَِدَُ أَرَقه مِنَ الْمَغَابِنِ، وَدَاخِلَةِ الِْإزَارِ، وَلَا سِيهمَا إِنْ كَانَ كِنَايَةً عَنِ الْفَرَجِ، فَإِذَا غُسِلَتْ بِالْمَاءِ، بَطَلَ تَثَِْيُرهَا وَعَمَلُهَا، وَأَيْضًا فَـهَذِهِ الْمَوَاضِعُ لِلْرَِْوَاحِ الشهيْطَانِيهةِ بَِها اخْتِصَاصٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَالْمَقْصُودُ: أَنه غَسْلَهَا بالماء يطفىء تِلْكَ النهارِيهةِ، وَيَذْهَبُ بِتِلْكَ السُّمِّيهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَفِيهِ أَمْرٌ آخَرُ، وَهُوَ وُصُولُ أَثَرِ الْغَسْلِ إِلَى الْقَلْبِ من أرقّ المواضع وأسرعها تنفيذا، فيطفىء تِلْكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'النهارِيهةَ وَالسُّمِّيهةَ بِالْمَاءِ، فَـيُشْفَى الْمَعِيُن، وَهَذَا كَمَا أَنه ذَوَاتِ السُّمُومِ إِذَا قُتِلَتْ بَـعْدَ لَسْعِهَا، خَفه أَثَـرُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'اللهسْعَةِ عَنِ الْمَلْسُوعِ ، وَوَجَدَ رَاحَةً، فَإِنه أَنْـفُسَهَا تَدَُُّ أَذَاهَا بَـعْدَ لَسْعِهَا، وَتُـوَصِّ لُهُ إِلَى الْمَلْسُوعِ . فَإِذَا قُتِلَتْ ، خَفه الَْألََُ، وهذا مشاهده وَإِنْ كَانَ مِنْ أَسْبَابِهِ فَـرَحُ الْمَلْسُوعِ ، وَاشْتِفَاءُ نَـفْسِهِ بِقَتْلِ عَدُوِّهِ، فَـتَـقْوَى الطهبِيعَةُ عَلَى الَْألََِ، فَـتَدْفَـعُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَبِالُْجمْلَةِ: غَسْلُ الْعَائِنِ يُذْهِبُ تِلْكَ الْكَيْفِيهةِ الهتِي ظَهَرَتْ مِنْهُ، وَإِهنَما يَـنْـفَعُ غَسْلُهُ عِنْدَ تَكَيُّفِ نَـفْسِهِ بِتِلْكَ الْكَيْفِيهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'فَإِنْ قِيلَ: فَـقَدْ ظَهَرَتْ مُنَاسَبَةُ الْغَسْلِ، فَمَا مُنَاسَبَةُ صَبِّ ذَلِكَ الْمَاءِ عَلَى الْمَعِيِن؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'قِيلَ: هُوَ فِي غَايَةِ الْمُنَاسَبَةِ، فَإِنه ذَلِكَ الْمَاءَ ماء طفىء بِهِ تِلْكَ النهارِيهةُ، وَأَبْطَلَ تِلْكَ الْكَيْفِيهةَ الهردِيئَةَ مِنَ الْفَاعِلِ، فَكَمَا طُفِئَتْ بِهِ النهارِيهةُ الْقَائِمَةُ بِالْفَاعِلِ طُفِئَتْ بِهِ، وَأُبْطِلَتْ عَنِ الْمَحَلِّ الْمُتَأَثِّرِ بَـعْدَ مُلَابَسَتِهِ لِلْمُؤَثِّرِ الْعَائِنِ، وَالْمَاءُ الهذِي يُطْفَأُ بِهِ الَْحدِيدُ يَدْخُلُ فِي أَدْوِيَةٍ عِدهةٍ طَبِيعِيهةٍ ذكرها الأطباء، فهذا الذي؟ طفىء بِهِ نَارِيهةُ الْعَائِنِ لَا يُسْتَـنْكَرُ أَنْ يَدْخُلَ فِي دَوَاءٍ يُـنَاسِبُ هَذَا الدهاءَ وَبِالُْجمْلَةِ فَطِبُّ الطهبَائِعِيهةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَعِلَاجُهُمْ بِالنِّسْبَةِ إِلَى الْعِلَاجِ النهـبَوِيِّ ، كَطِبِّ الطُّرُقِيهةِ بِالنِّسْبَةِ إِلَى طِبِّهِمْ، بَلْ أَقَلُّ، فَإِنه التهـفَاوُتَ الهذِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'بَـيْـنَـهُمْ وَبَـيَْن الَْأنْبِيَاءِ أَعْظَمُ، وَأَعْظَمُ مِنَ التهـفَاوُتِ الهذِي بَـيْـنَـهُمْ وَبَـيَْن الطُّرُقِيهةِ بَِما لَا يُدْرِكُ الِْإنْسَانُ مِقْدَارَهُ، فَـقَدْ ظَهَرَ لَكَ عَقْدُ الِْإخَاءِ الهذِي بَـيَْن الِْحكْمَةِ وَالشهرْعِ وَعَدَمُ مُنَاقَضَةِ أَحَدِهِاَُ لِلْخَْرِ، وَا هللَُّ يَـهْدِي مَنْ يَشَاءُ إِلَى الصهوَابِ، وَيَـفْتَحُ لِمَنْ أَدَامَ قَـرْعَ بَابِ التهـوْفِيقِ مِنْهُ كُله بَابٍ، وَلَهُ النِّعْمَةُ السهابِغَةُ، والحجة البالغة.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'من عِلَاجِ ذَلِكَ أَيْضًا وَالِاحْتَِرازِ مِنْهُ سَتْـرُ مَاَُسِنِ مَنْ يَُخافُ عَلَيْهِ الْعَيُْن بَِما يَـرُدُّهَا عَنْهُ، كَمَا ذكََرَ البغوي فِي كِتَابِ «شَرْحِ السُّنهةِ» : أَنه عثمان رَضِيَ ا هللَُّ عَنْهُ رَأَى صَبِيًّا مليحاج فَـقَالَ: دَسُِّموا نُونَـتَهُ لِئَهلا تُصِيبَهُ الْعَيُْن، ُ مه قَالَ فِي تَـفْسِيِرهِ وَمَعْنَى: دَسُِّموا نُونَـتَهُ أَيْ سَوِّدُوا نُونَـتَهُ، وَالنُّونَةُ النُّـقْرَةُ الهتِي تَكُونُ فِي ذَقَنِ الصهبِِّ الصهغِيِر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَقَالَ الخطابي فِي «غَرِيبِ الَْحدِيثِ» لَهُ عَنْ عثمان: إِنههُ رَأَى صَبِيًّا تخَذه العين، فقال: دسّموا نوننه؟؟؟ فَـقَالَ أبو عمرو سَأَلْتُ أَحْدََْ بْنَ يَْحيَى عَنْهُ، فَـقَالَ أَرَادَ بِالنُّونَةِ النُّـقْرَةَ الهتِي فِي ذقنه. والتدسيم التسويده أَرَادَ: سَوِّدُوا ذَلِكَ الْمَوْضِعَ مِنْ ذَقَنِهِ، لِيَـرُده الْعَيَْن قَالَ: وَمِنْ هَذَا حَدِيثُ عائشة أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ خَطَبَ ذَاتَ يَـوْمٍ، وَعَلَى رَأْسِهِ عِمَامَةٌ دَسَْماءُ أَيْ سَوْدَاءُ. أَرَادَ الِاسْتِشْهَادَ عَلَى اللهفْظَةِ، وَمِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'هَذَا أَخَذَ الشهاعِرُ قَـوْلَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'مَا كَانَ أَحْ وَجَ ذَا الْكَمَالِ إِلَى ... عَيْبٍ يُـوَقِّيهِ مِنَ الْعَيِْن', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَمِنَ الرُّقَى الهتِي تَـرُدُّ الْعَيَْن مَا ذكُِرَ عَنْ أبي عبد الله الساجي، أَنههُ كَانَ فِي بَـعْضِ أَسْفَارِهِ لِلْحَجِّ أَوِ الْغَزْوِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'عَلَى نَاقَةٍ فَارِهَةٍ، وَكَانَ فِي الرُّفْـقَةِ رَجُلٌ عَائِنٌ قَـلهمَا نَظَرَ إِلَى شَيْءٍ إِهلا أَتْـلَفَهُ، فَقِيلَ لأبي عبد الله: احْفَظْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'نَاقَـتَكَ مِنَ الْعَائِنِ، فَـقَالَ لَيْسَ لَهُ إِلَى نَاقَتِي سَبِيلٌ، فَأُخْبََِ الْعَائِنُ بِقَوْلِهِ، فَـتَحَ هيَن غَيْـبَةَ أبي عبد الله، فَجَاءَ إِلَى رَحْلِهِ، فَـنَظَرَ إِلَى النهاقَةِ، فَاضْطَرَبَتْ وَسَقَطَتْ ، فَجَاءَ أبو عبد الله، فَأُخْبََِ أَنه الْعَائِنَ قَدْ عَانَـهَا، وَهِيَ كَمَا تَـرَى، فَـقَالَ دِلُّونِي عَلَيْهِ، فَدُ هل، فَـوَقَفَ عَلَيْهِ، وَقَالَ بسم الله، حبس طبس، وحجر ياس، وَشِهَابٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'قَابِسٌ ، رَدَدْتُ عَيَْن الْعَائِنِ عَلَيْهِ، وَعَلَى أَحَبِّ النهاسِ إِلَيْهِ، فَارْجِعِ الْبَصَرَ هَلْ تَرى مِنْ فُطُورٍ، ُ مه ارْجِعِ الْبَصَرَ كَ هرتَـيِْن يَـنْـقَلِبْ إِلَيْكَ الْبَصَرُ خاسِئاً وَهُوَ حَسِيٌر »7« فَخَرَجَتْ حَدَقَـتَا الْعَائِنِ، وَقَامَتِ النهاقَةُ لَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'بَْأسَ بها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي العلاج لكل شكوى بالرقية الإلية', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'رَوَى أبو داود فِي «سُنَنِهِ» مِنْ حَدِيثِ أَبِي الدهرْدَاءِ، قَالَ سَِمعْتُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـقُولُ «مَنِ اشْتَكَى مِنْكُمْ شَيْـئًا، أَوِ اشْتَكَاهُ أَخٌ لَهُ فَـلْيَـقُلْ: رَبهـنَا ا هللََّ الهذِي فِي السهمَاءِ، تَـقَدهسَ اسُْمكَ ، أَمْرُكَ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'السهمَاءِ وَالَْأرْضِ كَمَا رَحْتَُْكَ فِي السهمَاءِ، فَاجْعَلْ رَحْتََْكَ فِي الَْأرْضِ وَاغْفِرْ لَنَا حُوبَـنَا وَخَطَايَانَا أَنْتَ رَبُّ الطهيِّبِيَن، أَنْزِلْ رَحْةًَْ مِنْ رحتْك، وشفاء من شفائيك عَلَى هَذَا الْوَجَعِ، فَـيَـبْـرَأُ بِِإذْنِ ا هلِلَّ» »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَفِي «صَحِيحِ مسلم» عَنْ أَبِي سَعِيدٍ الُْخدْرِيِّ ، أَنه جِبِْيَلَ- عَلَيْهِ السهلَامُ- أَتَى النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فَـقَالَ يَا مُمَُهدُ! اشْتَكَيْتَ ؟ فَـقَالَ: «نَـعَمْ» ، فَـقَالَ جِبِْيَلُ- عَلَيْهِ السهلَامُ:-', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, '«بِاسْمِ ا هلِلَّ أَرْقِيكَ مِنْ كُلِّ شَيْ ءٍ يُـؤْذِيكَ مِنْ شَرِّ كُلِّ نَـفْسٍ أَوْ عَيِْن حَاسِدٍ ا هللَُّ يَشْفِيكَ باسم الله أرقيك»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, '. »3«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '(7) الملك- -3 .4', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, '(2) أخرجه أبو داود في الطب. ورواه أحدْ (3) أخرجه مسلم في السلام', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'فَإِنْ قِيلَ فَمَا تَـقُولُونَ فِي الَْحدِيثِ الهذِي رَوَاهُ أبو داود «لَا رُقْـيَةَ إِهلا مِنْ عَيٍْن، أَوْ حُةٍَْ، وَالُْحمَةُ: ذَوَاتُ السُّمُومِ كُلُّهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'فَالَْجوَابُ أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لََْ يُرِدْ بِهِ نَـفْيَ جَوَازِ الرُّقْـيَةِ فِي غَيِْرهَا، بَلِ الْمُرَادُ بِهِ لَا رُقْـيَةَ أَوْلَى وَأَنْـفَعُ مِنْـهَا فِي الْعَيِْن وَالُْحمَةِ، وَيَدُلُّ عَلَيْهِ سِيَاقُ الَْحدِيثِ، فَإِنه سَهْلَ بْنَ حُنَـيْفٍ قَالَ لَهُ لما أصابته العين أّو في الرُّقَى خَيْـرٌ؟ فَـقَالَ «لَا رُقْـيَةَ إِهلا فِي نَـفْسٍ أَوْ حُةٍَْ وَيَدُلُّ عَلَيْهِ سَائِرُ أَحَادِيثِ الرُّقَى الْعَامهةِ وَالَْخاصهةِ، وَقَدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'رَوَى أبو داود مِنْ حَدِيثِ أنس قَالَ قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لَا رُقْـيَةَ إِهلا من عين أو حةْ أو دم يفرقأ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَفِي «صَحِيحِ مسلم» عَنْهُ أَيْضًا: رَخهصَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي الرُّقْـيَةِ من العين والحمة والنملة.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي رُقْـيَةِ اللهدِيغِ بِالْفَاتِةََِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'أَخْ رَجَا فِي «الصهحِيحَيِْن» مِنْ حَدِيثِ أَبِي سَعِيدٍ الُْخدْرِيِّ ، قَالَ: انْطَلَقَ نَـفَرٌ مِنْ أَصْحَابِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي سَفْرَةٍ سَافَـرُوهَا حَ هتى نَـزَلُوا عَلَى حَيٍّ مِنْ أَحْ يَاءِ الْعَرَبِ، فَاسْتَضَافُوهُمْ، فَأَبَـوْا أَنْ يُضَيِّفُوهُمْ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'فَـلُدغَِ سَيِّدُ ذَلِكَ الَْحيِّ، فَسَعَوْا لَهُ بِكُلِّ شَيْ ءٍ لَا يَـنْـفَعُهُ شَيْ ءٌ، فَـقَالَ بَـعْضُهُمْ لَوْ أَتَـيْـتُمْ هَؤُلَاءِ الهرهْطَ الهذِينَ نَـزَلُوا لَعَلههُمْ أَنْ يَكُونَ عِنْدَ بَـعْضِهِمْ شَيْ ءٌ، فَأَتَـوْهُمْ، فَـقَالُوا يَا أَيُّـهَا الهرهْطُ إِنه سَيهدَنَا لُدغَِ، وَسَعَيْـنَا لَهُ بِكُلِّ شَيْ ءٍ لَا يَـنْـفَعُهُ، فَـهَلْ عِنْدَ أَحَدٍ مِنْكُمْ مِنْ شَيْ ءٍ؟ فَـقَالَ بَـعْضُهُمْ: نَـعَمْ وَا هلِلَّ إِنِّي لََأرْقِي، وَلَكِنِ اسْتَضَفْنَاكُمْ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'فَـلَمْ تُضَيِّفُونَا، فَمَا أَنَا بَـرَاقٍ حَ هتى تَعََْلُوا لَنَا جُعْلًا، فَصَالَُحوهُمْ عَلَى قَطِيعٍ مِنَ الْغَنَمِ، فَانْطَلَقَ يَـتْـفُلُ عَلَيْهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَيَـقْرَأُ الَْحمْدُ هِلِلَّ رَبِّ الْعَالَمِيَن، فَكَأَهنَما أُنْشِطَ مِنْ عِقَالٍ، فَانْطَلَقَ يَْمشِي وَمَا بِهِ قَـلَبَةٌ، قَالَ فَأَوْفَـوْهُمْ جُعْلَهُمُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الهذِي صَالَُحوهُمْ عَلَيْهِ، فَـقَالَ بَـعْضُهُمْ: اقْـتَسِمُوا، فَـقَالَ الهذِي رَقَى لَا تَـفْعَلُوا حَ هتى نَْأتَِي رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عليه وسلم، فنذكر له', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(7) أخرجه أبو داود والترمذي بلفظ «ولا رقية إلا من عين أو حةْ» وإسناده صحيح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الهذِي كَانَ، فَـنَـنْظُرَ مَا مََُْرُنَا، فَـقَدِمُوا عَلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فَذَكَرُوا لَهُ ذَلِكَ ، فَـقَالَ «وَمَا يُدْرِيكَ أَنهـهَا رُقْـيَةٌ؟» ، ُ مه قَالَ «قَدْ أَصَبْـتُمْ، اقْسِمُوا وَاضْرِبُوا لِِ مَعَكُمْ سَهْمًا» »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَقَدْ رَوَى ابْنُ مَاجَهْ فِي «سُنَنِهِ» مِنْ حَدِيثِ علي قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ خَيْـرُ الدهوَاءِ الْقُرْآنُ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَمِنَ الْمَعْلُومِ أَنه بَـعْضَ الْكَلَامِ لَهُ خَوَاصُّ وَمَنَافِعُ مُهََربَةٌ، فَمَا الظهنُّ بِكَلَامِ رَبِّ الْعَالَمِيَن، الهذِي فَضْلُهُ عَلَى كُلِّ كَلَامٍ كَفَضْلِ ا هلِلَّ عَلَى خَلْقِهِ الهذِي هُوَ الشِّ فَاءُ التهامُّ، وَالْعِصْمَةُ النهافِعَةُ، وَالنُّورُ الَْهادِي، وَالهرحْةَُْ الْعَامهةُ، الهذِي لو أنزل ظل عَلَى جَبَلٍ لَتَصَدهعَ مِنْ عَظَمَتِهِ وَجَلَالَتِهِ. قَالَ تَـعَالَى وَنُـنَـزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفاءٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَرَحْةٌَْ لِلْمُؤْمِنِيَن »3« و «من» ها هنا لِبَـيَانِ الِْجنْسِ لَا لِلتهـبْعِيضِ هَذَا أَصَحُّ الْقَوْلَيِْن، كَقَوْلِهِ تَـعَالَى: وَعَدَ ا هللَُّ الهذِينَ آمَنُوا وَعَمِلُوا الصهالِحاتِ مِنْـهُمْ مَغْفِرَةً وَأَجْ راً عَظِيماً »4« . وَكُلُّهُمْ مِنَ الهذِينَ آمَنُوا وَعَمِلُوا الصهالَِحاتِ، فَمَا الظهنُّ بِفَاتِةََِ الْكِتَابِ الهتِي لََْ يُـنْـزَلْ فِي الْقُرْآنِ، وَلَا فِي التهـوْرَاةِ، وَلَا فِي الِْإنِْيْلِ، وَلَا فِي الهزبُورِ مِثْـلُهَا، الْمُتَضَمِّنَةِ لَِجمِيعِ مَعَانِي كُتُبِ ا هلِلَّ، الْمُشْتَمِلَةِ عَلَى ذِكْرِ أُصُولِ أَسَْماءِ الرب- تعالى-', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وماَمعها، وهي الله، والرب، وو الرحنْ، وَإِثْـبَاتِ الْمَعَادِ، وَذِكْرِ التهـوْحِيدَيْنِ: تَـوْحِيدِ الهربُوبِيهةِ، وَتَـوْحِيدِ الِْإلَِهيهةِ، وَذِكْرِ الِافْتِقَارِ إِلَى الهربِّ سُبْحَانَهُ فِي طَلَبِ الِْإعَانَةِ وَطَلَبِ الِْهدَايَةِ، وَتَْخصِيصِهِ سُبْحَانَهُ بِذَلِكَ ، وَذِكْرِ أَفْضَلِ الدُّعَاءِ عَلَى الِْإطْلَاقِ وَأَنْـفَعِهِ وَأَفْـرَضِهِ، وَمَا الْعِبَادُ أَحْ وَجُ شَيْ ءٍ إِلَيْهِ، وَهُوَ الِْهدَايَةُ إِلَى صِ رَاطِهِ الْمُسْتَقِيمِ، الْمُتَضَمِّنِ كَمَالَ مَعْرِفَتِهِ وَتَـوْحِيدِهِ وَعِبَادَتِهِ بِفِعْلِ مَا أَمَرَ بِهِ، وَاجْتِنَابِ مَا نَـهَى عَنْهُ، وَالِاسْتِقَامَةِ عَلَيْهِ إِلَى الْمَمَاتِ، وَيَـتَضَمهنُ ذِكْ رَ أَصْنَافِ الَْخلَائِقِ وَانْقِسَامَهُمْ إِلَى مُنْـعَمٍ عَلَيْهِ بَِمعْرِفَةِ الَْحقِّ، وَالْعَمَلِ بِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَمَبَُهتِهِ، وَإِيثَارِهِ، وَمَغْضُوبٍ عَلَيْهِ بِعُدُولِهِ عَنِ الَْحقِّ بَـعْدَ مَعْرِفَتِهِ لَهُ، وَضَالٍّ بِعَدَمِ مَعْرِفَتِهِ لَهُ. وَهَؤُلَاءِ أَقْسَامُ الَْخلِيقَةِ مَعَ تَضَمُّنِهَا لِِإثْـبَاتِ الْقَدَرِ، وَالشهرْعِ ، وَالَْأسَْماءِ، وَالصِّفَاتِ، والمعاد، والنبوات، وتزكية النفوس، وإصلاح', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, '(7) أخرجه البخاري في الطب، ومسلم في السلام، وأخرجه الترمذي وابن ماجه وأحدْ (2) أخرجه ابن ماجه في الطب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, '(3) الإسراء- 92', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, '(4) الفتح- 29', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'الْقُلُوبِ، وَذِكْرِ عَدْلِ ا هلِلَّ وَإِحْسَانِهِ، وَالهردِّ عَلَى جَِيَعِ أَهْلِ الْبِدَعِ وَالْبَاطِلِ، كَمَا ذكََرْنَا ذَلِكَ فِي كِتَابِنَا الْكَبِيِر «مَدَارِجِ السهالِكِيَن» فِي شَرْحِهَا. وَحَقِيقٌ بِسُورَةٍ هَذَا بَـعْضُ شَأْنَِها، أَنْ يُسْتَشْفَى بَِها مِنَ الَْأدْوَاءِ، وَيُـرْقَى بَِها اللهدِيغُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَبِالُْجمْلَةِ فما تنَته الفاتةَ ن إخلاص العبودية والثناء على الله، وتقويض الَْأمْرِ كُلِّهِ إِلَيْهِ، وَالِاسْتِعَانَةِ بِهِ، وَالتهـوَكُّلِ عَلَيْهِ، وَسُؤَالِهِ مَاََمِعَ النِّعَمِ كُلِّهَا، وَهِيَ الِْهدَايَةُ الهتِي تَلَِْبُ النِّعَمَ، وَتَدْفَعُ النِّقَمَ، مِنْ أَعْظَمِ الَْأدْوِيَةِ الشهافِيَةِ الْكَافِيَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَقَدْ قِيلَ: إِنه مَوْضِعَ الرُّقْـيَةِ منها: إِهياكَ نَـعْبُدُ وَإِهياكَ نَسْتَعِيُن، وَلَا رَيْبَ أَنه هَاتَـيِْن الْكَلِمَتَـيِْن مِنْ أَقْـوَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'أَجْ زَاءِ هَذَا الدهوَاءِ، فَإِنه فِيهِمَا مِنْ عُمُومِ التهـفْوِيضِ وَالتهـوَكُّلِ، وَالِالْتِجَاءِ وَالِاسْتِعَانَةِ، وَالِافْتِقَارِ وَالطهلَبِ، وَالَْجمْعِ بَـيَْن أَعْلَى الْغَايَاتِ، وَهِيَ عِبَادَةُ الهربِّ وَحْدَهُ، وَأَشْرَفِ الْوَسَائِلِ وَهِيَ الِاسْتِعَانَةُ بِهِ عَلَى عِبَادَتِهِ مَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'لَيْسَ فِي غَيِْرهَا، وَلَقَدْ مَ هر بِي وَقْتٌ بَِمكهةَ سَقِمْتُ فِيهِ وَفَـقَدْتُ الطهبِيبَ وَالدهوَاءَ، فَكُنْتُ أَتَـعَالََُ بَِها، آخُذُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'شَرْبَةً مِنْ مَاءِ زَمْزَمَ، وَأَقْـرَؤُهَا عَلَيْـهَا مِرَارًا، ُ مه أَشْرَبُهُ، فَـوَجَدْتُ بِذَلِكَ الْبُـرْءَ التها هم، ُ مه صِرْتُ أَعْتَمِدُ ذَلِكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'عِنْدَ كَثِيٍر مِنَ الَْأوْجَاعِ ، فَأَنْـتَفِعُ بَِها غَايَةَ الانتفاع.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وفي تثَير الرّقى بالفاتةَ وغيرها عِلَاجِ ذَوَاتِ السُّمُومِ سِرٌّ بَدِيعٌ، فَإِنه ذَوَاتِ السُّمُومِ أَثهـرَتْ بِكَيْفِيهاتِ نُـفُوسِهَا الَْخبِيثَةِ، كَمَا تَـقَدهمَ، وَسِلَاحُهَا حُاَْتُـهَا الهتِي تَـلْدَغُ بَِها، وَهِيَ لَا تَـلْدَغُ حَ هتى تَـغْضَبَ ، فَإِذَا غَضِبَتْ ، ثَرََ فِيهَا السُّمُّ، فَـتَـقْذِفُهُ بِلَِتِهَا، وَقَدْ جَعَلَ ا هللَُّ سُبْحَانَهُ لِكُلِّ دَاءٍ دَوَاءً، وَلِكُلِّ شَيْ ءٍ ضِدًّا وَنَـفْسُ الهراقِي تَـفْعَلُ فِي نَـفْسِ الْمَرْقِيِّ، فَـيَـقَعُ بَـيَْن نَـفْسَيْهِمَا فِعْلٌ وَانْفِعَالٌ، كَمَا يَـقَعُ بَـيَْن الدهاءِ وَالدهوَاءِ، فَـتَـقْوَى نَـفْسُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الهراقِي وَقُـهوتُهُ بِالرُّقْـيَةِ عَلَى ذَلِكَ الدهاءِ، فَـيَدْفَـعُهُ بِِإذْنِ ا هلِلَّ، وَمَدَارُ تَثَِْيِر الَْأدْوِيَةِ وَالَْأدْوَاءِ عَلَى الْفِعْلِ وَالِانْفِعَالِ وَهُوَ كَمَا يَـقَعُ بَـيَْن الدهاءِ وَالدهوَاءِ الطهبِيعِيهـيِْن، يَـقَعُ بَـيَْن الدهاءِ وَالدهوَاءِ الرُّوحَانِيهـيِْن، وَالرُّوحَانُِّي، وَالطهبِيعِيُّ، وَفِي النهـفْثِ وَالتهـفْلِ اسْتِعَانَةٌ بِتِلْكَ  الرُّطُوبَةِ وَالَْهوَاءِ، وَالنهـفَسِ  الْمُبَاشِرِ لِلرُّقْـيَةِ، وَالذِّكْرِ وَالدُّعَاءِ، فَإِنه الرُّقْـيَةَ تَْخرُجُ مِنْ قَـلْبِ الهراقِي وَفَمِهِ، فَإِذَا صَاحَبَـهَا شَيْ ءٌ مِنْ أَجْ زَاءِ بَاطِنِهِ مِنَ الرِّيقِ وَالَْهوَاءِ وَالنهـفَسِ ، كَانَتْ أتّم', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'تَثَِْيًرا، وَأَقْـوَى فِعْلًا وَنُـفُوذًا، وَيَْحصُلُ بِالِازْدِوَاجِ بَـيْـنَـهُمَا كَيْفِيهةٌ مُؤَثِّرَةٌ شَبِيهَةٌ بِالْكَيْفِيهةِ الَْحادِثَةِ عِنْدَ تَـرْكِيبِ الَْأدْوِيَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَبِالُْجمْلَةِ: فَـنَـفْسُ الهراقِي تُـقَابِلُ تِلْكَ  النهـفُوسَ الَْخبِيثَةَ، وَتَزِيدُ بِكَيْفِيهةِ نَـفْسِهِ، وَتَسْتَعِيُن بِالرُّقْـيَةِ وَبِالنهـفْثِ عَلَى إِزَالَةِ ذَلِكَ الَْأثَرِ، وَكُلهمَا كَانَتْ كَيْفِيهةُ نَـفْسِ الهراقِي أَقْـوَى، كَانَتِ الرُّقْـيَةُ أَتَمه، وَاسْتِعَانَـتُهُ بِنَـفْثِهِ كَاسْتِعَانَةِ تِلْكَ النُّـفُوسِ الهردِيئَةِ بِلَسْعِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَفِي النهـفْثِ سِرٌّ آخَرُ، فَإِنههُ مِمها تَسْتَعِيُن بِهِ الَْأرْوَاحُ الطهيِّبَةُ وَالَْخبِيثَةُ، وَلَِهذَا تَـفْعَلُهُ السهحَرَةُ كَمَا يَـفْعَلُهُ أَهْلُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الِْإيَمانِ قَالَ تَـعَالَى وَمِنْ شَرِّ النهـهفاثتَِ فِي الْعُقَدِ، وَذَلِكَ لَِأنه النهـفْسَ تَـتَكَيهفُ بِكَيْفِيهةِ الْغَضَبِ وَالْمُحَارَبَةِ، وَتُـرْسِلُ أَنْـفَاسَهَا سِهَامًا لَهاَ، وَتَدَُُّهَا بِالنهـفْثِ وَالتهـفْلِ الهذِي مَعَهُ شَيْ ءٌ مِنَ الرِّيقِ مُصَاحِبٌ لِكَيْفِيهةٍ مُؤَثِّرَةٍ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَالسهوَاحِرُ تَسْتَعِيُن بِالنهـفْثِ اسْتِعَانَةً بَـيِّنَةً، وَإِنْ لََْ تَـتهصِلْ بِِسِْمِ الْمَسْحُورِ، بَلْ تَـنْـفُثُ عَلَى الْعُقْدَةِ وَتَـعْقِدُهَا، وَتَـتَكَلهمُ بِالسِّ حْرِ، فَـيَـعْمَلُ ذَلِكَ فِي الْمَسْ حُورِ بِتَـوَسُّطِ الَْأرْوَاحِ السُّفْلِيهةِ الَْخبِيثَةِ، فَـتُـقَابِلُهَا الرُّوحُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'الهزكِيهةُ الطهيِّبَةُ بِكَيْفِيهةِ الدهفْعِ وَالتهكَلُّمِ بِالرُّقْـيَةِ، وَتَسْتَعِيُن بِالنهـفْثِ، فَأَيُّـهُمَا قَوِيَ كَانَ الُْحكْمُ لَهُ، وَمُقَابَـلَةُ الَْأرْوَاحِ بَـعْضِهَا لِبَـعْضٍ ، وَمُاَُرَبَـتُـهَا وَآلَتُـهَا مِنْ جِنْسِ مُقَابَـلَةِ الَْأجْسَامِ، وَمُاَُرَبَـتُـهَا وَآلَتُـهَا سَوَاءٌ، بَلِ الَْأصْلُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'فِي الْمُحَارَبَةِ وَالتهـقَابُلِ لِلْرَِْوَاحِ وَالَْأجْسَامِ آلَتُـهَا وَجُنْدُهَا وَلَكِنْ مَنْ غَلَبَ عَلَيْهِ الِْحسُّ لَا يَشْعُرُ بِتَأْثِيَراتِ الَْأرْوَاحِ وَأَفْـعَالَِها وَانْفِعَالَاتَِها لِاسْتِيلَاءِ سُلْطَانِ الِْحسِّ  عَلَيْهِ، وَبُـعْدِهِ مِنْ عَالََِ الَْأرْوَاحِ، وَأَحْكَامِهَا، وَأَفْـعَالَِها. وَالْمَقْصُودُ: أَنه الرُّوحَ إِذَا كَانَتْ قَوِيهةً وَتَكَيهـفَتْ بَِمعَانِي الْفَاتِةََِ، وَاسْتَـعَانَتْ بِالنهـفْثِ وَالتهـفْلِ، قَابَـلَتْ ذَلِكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'الَْأثَـرَ الهذِي حَصَلَ مِنَ النُّـفُوسِ الَْخبِيثَةِ، فَأَزَالَتْهُ والله أعلم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ لَدْغَةِ الْعَقْرَبِ بِالرُّقْـيَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى ابْنُ أَبِي شَيْـبَةَ فِي «مُسْنَدِهِ، مِنْ حَدِيثِ عَبْدِ ا هلِلَّ بْنِ مَسْعُودٍ، قَالَ: بَـيْـنَا رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يُصَلِّي، إِذْ سَجَدَ فَـلَدَغَتْهُ عَقْرَبٌ فِي أُصْبُعِهِ، فَانْصَرَفَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَقَالَ «لَعَنَ ا هللَُّ الْعَقْرَبَ مَا تَدَعُ نَبِيًّا وَلَا غَيْـرَهُ» ، قَالَ ُ مه دَعَا بِِإنَاءٍ فِيهِ مَاءٌ وَمِلْحٌ، فَجَعَلَ يَضَعُ مَوْضِعَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الهلدْغَةِ فِي الْمَاءِ وَالْمِلْحِ، وَيَـقْرَأُ قُلْ هُوَ ا هللَُّ أَحَدٌ، وَالْمُعَوِّذَتَـيِْن حَ هتى سَكَنَتْ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'فَفِي هَذَا الَْحدِيثِ الْعِلَاجُ بِالدهوَاءِ الْمُرَكهبِ مِنَ الَْأمْرَيْنِ: الطهبِيعِيِّ وَالِْإلَِهيِّ، فَإِنه فِي سُورَةِ الِْإخْلَاصِ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'كَمَالِ التهـوْحِيدِ الْعِلْمِيِّ الِاعْتِقَادِيِّ ، وَإِثْـبَاتِ الَْأحَدِيهةِ هِلِلَّ، الْمُسْتَـلْزِمَةِ نَـفْيَ كُلِّ شَركَِةٍ عَنْهُ، وَإِثْـبَاتِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الصهمَدِيهةِ الْمُسْتَـلْزِمَةِ لِِإثْـبَاتِ كُلِّ كَمَالٍ لَهُ مَعَ كَوْنِ الَْخلَائِقِ تَصْمُدُ إِلَيْهِ فِي حَوَائِجِهَا، أَيْ : تَـقْصِدُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الَْخلِيقَةُ، وَتَـتَـوَجههُ إِلَيْهِ، عُلْوِيُّـهَا وَسُفْلِيُّـهَا، وَنَـفْيِ الْوَالِدِ وَالْوَلَدِ، وَالْكُفْ ءِ عَنْهُ الْمُتَضَمهنِ لِنَـفْيِ الَْأصْلِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَالْفَرْعِ وَالنهظِيِر، وَالْمُمَاثِلِ مَِما اخْ تَصهتْ بِهِ وَصَارَتْ تَـعْدِلُ ثُـلُثَ الْقُرْآنِ ، فَفِي اسِْمهِ الصهمَدِ إِثْـبَاتُ كُلِّ الْكَمَالِ، وَفِي نَـفْيِ الْكُفْ ءِ التهـنْزِيهُ عَنِ الشهبِيهِ وَالْمِثَالِ. وَفِي الَْأحَدِ نفي كلّ شريك الذي الَْجلَالِ، وَهَذِهِ الُْأصُولُ الثهلَاثَةُ هِيَ مَاََمِعُ التهـوْحِيدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَفِي الْمُعَوِّذَتَـيِْن الِاسْتِعَاذَةُ مِنْ كُلِّ مَكْ رُوهٍ جُلََْةً وَتَـفْصِيلًا، فَإِنه الِاسْتِعَاذَةَ مِنْ شَرِّ مَا خَلَقَ تَـعُمُّ كُله شَرٍّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'يُسْتَـعَاذُ مِنْهُ، سَوَاءٌ كَانَ فِي الَْأجْسَامِ أَوِ الَْأرْوَاحِ وَالِاسْتِعَاذَةَ مِنْ شَرِّ الْغَاسِقِ وَهُوَ اللهيْلُ، وَآيَتِهِ وَهُوَ الْقَمَرُ إِذَا غَابَ ، تَـتَضَمهنُ الِاسْتِعَاذَةَ مِنْ شَرِّ مَا يَـنْـتَشِرُ فِيهِ مِنَ الَْأرْوَاحِ الَْخبِيثَةِ الهتِي كَانَ نُورُ النهـهَارِ يَُحولُ بَـيْـنَـهَا وَبَـيَْن الِانْتِشَارِ، فَـلَمها أَظْلَمَ اللهيْلُ عَلَيْـهَا وَغَابَ الْقَمَرُ، انْـتَشَرَتْ وَعَاثَتْ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَالِاسْتِعَاذَةَ مِنْ شَرِّ النهـهفاثَتَِ فِي الْعُقَدِ تَـتَضَمهنُ الِاسْتِعَاذَةَ مِنْ شَرِّ السهوَاحِرِ وَسِحْرِهِنه. وَالِاسْتِعَاذَةَ مِنْ شَرِّ الَْحاسِدِ تَـتَضَمهنُ الِاسْتِعَاذَةَ مِنَ النُّـفُوسِ الَْخبِيثَةِ الْمُؤْذِيَةِ بَِحسَدِهَا وَنَظَرِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَالسُّورَةُ الثهانِيَةُ: تَـتَضَمهنُ الِاسْتِعَاذَةَ مِنْ شَرِّ شَيَاطِيِن الِْإنْسِ وَالِْجنِّ، فَـقَدْ جَعَََتِ السُّورَتَانِ الِاسْتِعَاذَةَ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'كُلِّ شَرٍّ، وَلَهمَُا شَأْنٌ عَظِيمٌ في الاحتراس والتحصن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, '(7) أخرجه الترمذي، وأخرجه الطباَني في الكبير والأوسط، والبيهقي في الشعب وأبو نعيم في الطب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'مِنَ الشُّرُورِ قَـبْلَ وُقُوعِهَا، وَلَِهذَا أَوْصَى النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عُقْبَةَ بْنَ عَامِرٍ بِقِرَاءَتِِهمَا عَقِبَ كُلِّ صَلَاةٍ، ذكََرَهُ الترمذي فِي «جَامِعِهِ» »7« وَفِي هَذَا سِرٌّ عَظِيمٌ فِي اسْتِدْفَاعِ الشُّرُورِ مِنَ الصهلَاةِ إِلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'الصهلَاةِ. وَقَالَ: مَا تَـعَهوذَ الْمُتَـعَوِّذُونَ بِِمثْلِهِمَا. وَقَدْ ذكََرَ أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ سُحِرَ فِي إِحْدَى عَشْرَةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'عُقْدَةً، وَأَنه جِبِْيَلَ نَـزَلَ عَلَيْهِ بِِهمَا، فَجَعَلَ كُلهمَا قَـرَأَ آيَةً مِنْـهُمَا انْلَْهتْ عُقْدَةٌ، حَ هتى انْلَْهتِ الْعُقَدُ كُلُّهَا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَكَأَهنَما أُنْشِطَ مِنْ عِقَالٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَأَمها الْعِلَاجُ الطهبِيعِيُّ فِيهِ، فَإِنه فِي الْمِلْحِ نَـفْعًا لِكَثِيٍر مِنَ السُّمُومِ، وَلَا سِيهمَا لَدْغَةُ الْعَقْرَبِ، قَالَ صَاحِبُ «الْقَانُونِ» : يُضَمهدُ بِهِ مَعَ بَـزْرِ الْكَتهانِ لِلَسْعِ الْعَقْرَبِ، وَذكََرَهُ غَيْـرُهُ أَيْضًا. وَفِي الْمِلْحِ مِنَ الْقُهوةِ الَْجاذِبَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'الْمُحَلِّلَةِ مَا يَْجذِبُ السُّمُومَ وَيَُحلِّلُهَا، وَلَمها كَانَ فِي لَسْعِهَا قُـهوةٌ نَارِيهةٌ تَتََْاجُ إِلَى تَـبِْيَدٍ وَجَذْبٍ وَإِخْرَاجٍ جَعَََ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'بَـيَْن الْمَاءِ الْمُبَـهردِ لِنَارِ اللهسْعَةِ، وَالْمِلْحِ الهذِي فِيهِ جَذْبٌ وَإِخْرَاجٌ، وَهَذَا أَتَُّم مَا يَكُونُ مِنَ الْعِلَاجِ وَأَيْسَرُهُ وَأَسْهَلُهُ، وَفِيهِ تَـنْبِيهٌ عَلَى أَنه عِلَاجَ هَذَا الدهاءِ بِالتهـبِْيَدِ وَالَْجذْبِ وَالِْإخْ رَاجِ وَا هللَُّ أَعْلَمُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَقَدْ رَوَى مسلم فِي «صَحِيحِهِ» عَنْ أَبِي هُرَيْـرَةَ قَالَ: جَاءَ رَجُلٌ إِلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فَـقَالَ: يَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'رَسُولَ ا هلِلَّ! مَا لَقِيتُ مِنْ عَقْرَبٍ لَدَغَتْنِِ الْبَارِحَةَ فَـقَالَ: «أَمَا لَوْ قُـلْتَ حِيَن أَمْسَيْتَ : أَعُوذُ بِكَلِمَاتِ ا هلِلَّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'التهامهاتِ مِنْ شَرِّ مَا خَلَقَ، لََْ تَضُهركَ» »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'وَاعْلَمْ أَنه الَْأدْوِيَةَ الطهبِيعِهيةَ الِْإلَِههيةَ تَـنْـفَعُ مِنَ الدهاءِ بَـعْدَ حُصُولِهِ، وَتَنََْعُ مِنْ وُقُوعِهِ، وَإِنْ وَقَعَ لََْ يَـقَعْ وُقُوعًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'مُضِ رًّا، وَإِنْ كَانَ مُؤْذِيًا، وَالَْأدْوِيَةُ الطهبِيعِيهةُ إِهنَما تَـنْـفَعُ، بَـعْدَ حُصُولِ الدهاءِ، فَالتهـعَوُّذَاتُ وَالَْأذكَْارُ، إِمها أَنْ تَنََْعَ وُقُوعَ هَذِهِ الَْأسْبَابِ، وَإِمها أَنْ تَوَُلَ بَـيْـنَـهَا وَبَـيَْن كَمَالِ تَثَِْيِرهَا بَِحسَبِ كَمَالِ التهـعَوُّذِ وَقُـهوتِهِ وَضَعْفِهِ، فَالرُّقَى وَالْعُوَذُ تُسْتَـعْمَلُ لِِحفْظِ الصِّحهةِ، وَلِِإزَالَةِ الْمَرَضِ ، أَمها الَْأهولُ: فَكَمَا فِي «الصهحِيحَيِْن» مِنْ حَدِيثِ عائشة كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، إذ أَوَى إِلَى فِرَاشِهِ نَـفَثَ فِي كَ هفيْهِ قُلْ هُوَ ا هللَُّ أَحَدٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَالْمُعَوِّذَتَـيِْن. ُ مه يَْمسَحُ بِِهمَا وَجْ هَهُ، وَمَا بَـلَغَتْ يده من جسده »3«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, '(7) أخرجه أحدْ وأبو داود والنسائي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, '(2) أخرجه مسلم في السلام، وأخرجه أحدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, '(3) أخرجه البخاري في الدعوات، ومسلم في السلام', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'وَكَمَا فِي حَدِيثِ عُوذَةِ أَبِي الدهرْدَاءِ الْمَرْفُوعِ «اللههُمه أَنْتَ رَبِّي لَا إِلَهَ إِهلا أَنْتَ عَلَيْكَ تَـوَكهلْتُ وَأَنْتَ رَبُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'الْعَرْشِ الْعَظِيمِ» ، وَقَدْ تَـقَدهمَ وَفِيهِ: مَنْ قَالََها أَهولِ نَـهَارِهِ لََْ تُصِبْهُ مُصِيبَةٌ حَ هتى يُْمسِيَ ، وَمَنْ قَالََها آخِرَ نَـهَارِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'لََْ تُصِبْهُ مُصِيبَةٌ حَ هتى يُصْبِحَ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'وَكَمَا فِي «الصهحِيحَيِْن» : «مَنْ قَـرَأَ الْآيَـتَـيِْن مِنْ آخِرِ سُورَةِ الْبَـقَرَةِ فِي لَيْـلَةٍ كَفَتَاهُ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'وَكَمَا فِي «صحيح مسلم» عن النب صلى الله عليه وَسَلهمَ: «مَنْ نَـزَلَ مَنْزِلًا فَـقَالَ: أَعُوذُ بِكَلِمَاتِ ا هلِلَّ التهامهاتِ مِنْ شَرِّ مَا خَلَقَ، لََْ يَضُهرهُ شَيْ ءٌ حَ هتى يَـرْتَِلََ مِنْ مَنْزِلِهِ ذَلِكَ » »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'وَكَمَا فِي «سُنَنِ أبي داود» أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ فِي السهفَرِ يَـقُولُ بِاللهيْلِ: «يَا أَرْضُ ، رَبِّي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'وَرَبُّكِ ا هللَُّ، أَعُوذُ بِا هلِلَّ مِنْ شَرِّكِ وَشَرِّ مَا فِيكِ ، وَشَرِّ مَا يَدُبُّ عَلَيْكِ ، أَعُوذُ بِا هلِلَّ مِنْ أَسَدٍ وَأَسْ ودٍ، وَمِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'الَْحيهةِ وَالْعَقْرَبِ، وَمِنْ سَاكِنِ الْبَـلَدِ، وَمِنْ وَالِدٍ وَمَا وَلَدَ» »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'وَأَمها الثهانِي: فَكَمَا تَـقَدهمَ مِنَ الرُّقْـيَةِ بِالْفَاتِةََِ، وَالرُّقْـيَةِ للعقرب وغيرها مما تَي.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي رُقْـيَةِ النهمْلَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'قَدْ تَـقَدهمَ مِنْ حَدِيثِ أنس الهذِي فِي «صَحِيحِ مسلم» أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ رَخهصَ فِي الرُّقْـيَةِ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الُْحمَةِ وَالْعَيِْن وَالنهمْلَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَفِي «سُنَنِ أبي داود» عن الشّفاء بنت عبد الله، قالت: دخل عليّ رسول الله', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(7) أخرجه ابن السنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(2) أخرجه البخاري في فضائل القرآن، ومسلم في المسافرين. (3) أخرجه مسلم في الذكر والدعاء.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(4) أخرجه أبو داود وأحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَأَنَا عِنْدَ حفصة، فَـقَالَ: «أَلَا تُـعَلِّمِيَن هَذِهِ رُقْـيَةَ النهمْلَةِ كَمَا عَلهمْتِيهَا الْكِتَابَةَ» »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'النهمْلَةُ: قُـرُوحٌ تَْخرُجُ فِي الَْجنْـبَـيِْن، وَهُوَ دَاءٌ مَعْرُوفٌ ، وَسُِّميَ نَْملَةً، لَِأنه صَاحِبَهُ يُِحسُّ فِي مَكَانِهِ كَأَنه نَْملَةً تَدِبُّ عَلَيْهِ وَتَـعَضُّهُ، وَأَصْنَافُـهَا ثَلَاثَةٌ، قَالَ ابن قتيبة وَغَيْـرُهُ: كَانَ الْمَجُوسُ يَـزْعُمُونَ أَنه وَلَدَ الهرجُلِ مِنْ أُخْ تِهِ إِذَا خُطه عَلَى النهمْلَةِ، شَفَى صَاحِبَـهَا، وَمِنْهُ قَـوْلُ الشهاعِرِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَلَا عَيْبَ فِينَا غَيْـرَ عُرْفٍ لِمَعْشَرٍ ... كِرَامٍ وَأَهنا لَا نَطُُُّ عَلَى النهمْلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَرَوَى الخلال: أَنه الشفاء بنت عبد الله كَانَتْ تَـرْقِي فِي الَْجاهِلِيهةِ مِنَ النهمْلَةِ، فَـلَمها هَاجَرَتْ إِلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَكَانَتْ قَدْ بَايَـعَتْهُ بَِمكهةَ، قَالَتْ : يَا رَسُولَ ا هلِلَّ! إِنِّي كُنْتُ أَرْقِي فِي الَْجاهِلِيهةِ مِنَ النهمْلَةِ، وَإِنِّي أُرِيدُ أَنْ أَعْرِضَهَا عَلَيْكَ ، فَـعُرِضَتْ عَلَيْهِ فَـقَالَتْ : بِسْمِ ا هلِلَّ ضَلهتْ حَ هتى تَـعُودَ مِنْ أَفْـوَاهِهَا، وَلَا تَضُرُّ أَحَدًا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'اللههُمه اكْشِفِ الْبَأْسَ رَبه النهاسِ ، قَالَ: تَـرْقِي بَِها عَلَى عُودٍ سَبْعَ مَ هراتٍ، وَتَـقْصِدُ مَكَانًا نَظِيفًا، وَتَدْلُكُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'عَلَى حَجَرٍ خِلَِِّ خَْمرٍ حَاذِقٍ، وَتَطْلِيهِ عَلَى النهمْلَةِ. وَفِي الَْحدِيثِ: دَلِيلٌ عَلَى جَوَازِ تعليم النساء الكتابة.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي رُقْـيَةِ الَْحيهةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'قَدْ تَـقَدهمَ قَـوْلُهُ: «لَا رُقْـيَةَ إِهلا فِي عَيٍْن، أَوْ حُةٍَْ» »2« ، الُْحمَةُ: بِضَمِّ الَْحاءِ وَفَـتْحِ الْمِيمِ وَتَْخفِيفِهَا. وَفِي «سُنَنِ ابْنِ مَاجَهْ» مِنْ حَدِيثِ عائشة: رَخهصَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي الرُّقْـيَةِ مِنَ الَْحيهةِ وَالْعَقْرَبِ »3« . وَيُذْكَرُ عَنِ ابْنِ شِهَابٍ الزُّهْرِيِّ قَالَ: لَدَغَ بَـعْضَ أَصْحَابِ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ حَيهةٌ، فَـقَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «هَلْ مِنْ رَاقٍ؟» فقالوا: يا رسول', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '(7) أخرجه أبو داود وأحدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(2) الحمة: بضم الحاء وتخفيف الميم هم السم، والمراد بها ذوات السموم. (3) أخرجه ابن ماجه في الطب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الله! إن آل حزم كانوا يرون رُقْـيَةَ الَْحيهةِ، فَـلَمها نَـهَيْتَ عَنِ الرُّقَى تَـرَكُوهَا، فقال:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '«ادعو عمارة بن حزم» ، فَدَعَوْهُ، فَـعَرَضَ عَلَيْهِ رُقَاهُ، فَـقَالَ: «لَا بَْأسَ بَِها» فَأَذِنَ لَهُ فِيهَا فرقاه »7« .', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي رُقْـيَةِ الْقَرْحَةِ وَالُْجرْحِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'أَخْ رَجَا فِي «الصهحِيحَيِْن» عَنْ عائشة قَالَتْ : كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إِذَا اشْتَكَى الِْإنْسَانُ أَوْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'كَانَتْ بِهِ قَـرْحَةٌ أَوْ جُرْحٌ، قَالَ بُِأصْبُعِهِ: هَكَذَا وَوَضَعَ سُفْيَانُ سَبهابَـتَهُ بِالَْأرْضِ ، ُ مه رَفَـعَهَا، وَقَالَ: «بِسْمِ ا هلِلَّ، تُـرْبَةُ أَرْضِ نَا بِرِيقَةِ بَـعْضِنَا، يُشْفَى سَقِيمُنَا بِِإذْنِ رَبِّنَا» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'هَذَا مِنَ الْعِلَاجِ الْمُيَسهرِ النهافِعِ الْمُرَكهبِ، وَهِيَ مُعَالََجةٌ لَطِيفَةٌ يُـعَالََُ بَِها الْقُرُوحُ وَالِْجرَاحَاتُ الطهرِيهةُ، لَا سِيهمَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'عِنْدَ عَدَمِ غَيِْرهَا مِنَ الَْأدْوِيَةِ إِذْ كَانَتْ مَوْجُودَةً بِكُلِّ أَرْضٍ ، وَقَدْ عُلِمَ أَنه طَبِيعَةَ التُّـرَابِ الَْخالِصِ بَارِدَةٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'يَابِسَةٌ مُهََففَةٌ لِرُطُوبَاتِ الْقُرُوحِ وَالِْجرَاحَاتِ الهتِي تَنََْعُ الطهبِيعَةُ مِنْ جَوْدَةِ فِعْلِهَا، وَسُرْعَةِ انْدِمَالَِها، لَا سِيهمَا فِي الْبِلَادِ الَْحارهةِ، وَأَصْحَابِ الَْأمْزِجَةِ الَْحارهةِ، فَإِنه الْقُرُوحَ وَالِْجرَاحَاتِ يَـتْـبَـعُهَا فِي أَكْثَرِ الَْأمْرِ سُوءُ مِزَاجٍ حَارٍّ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'فَـيَجْتَمِعُ حَرَارَةُ الْبَـلَدِ وَالْمِزَاجُ وَالِْجرَاحُ، وَطَبِيعَةُ التُّـرَابِ الَْخالِصِ بَارِدَةٌ يَابِسَةٌ أَشَدُّ مِنْ بُـرُودَةِ جَِيَعِ الَْأدْوِيَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الْمُفْرَدَةِ الْبَارِدَةِ، فَـتُـقَابِلُ بُـرُودَةُ التُّـرَابِ حَرَارَةَ الْمَرَضِ ، لَا سِيهمَا إِنْ كَانَ التُّـرَابُ قَدْ غُسِلَ وَجُفِّفَ ، وَيَـتْـبَـعُهَا أَيْضًا كَثْـرَةُ الرُّطُوبَاتِ الهردِيئَةِ، وَالسهيَلَانُ، وَالتُّـرَابُ مُفََِّفٌ لََها، مُزِيلٌ لِشِدهةِ يُـبْسِهِ وَتَفَِْيفِهِ لِلرُّطُوبَةِ الهردِيئَةِ الْمَانِعَةِ مِنْ بَـرْئِهَا، وَيَْحصُلُ بِهِ- مَعَ ذَلِكَ - تَـعْدِيلُ مِزَاجِ الْعُضْوِ الْعَلِيلِ، وَمَتَى اعْتَدَلَ مِزَاجُ الْعُضْوِ قَوِيَتْ قُـوَاهُ الْمُدَبِّرَةُ، وَدَفَـعَتْ عَنْهُ الألَ بإذن الله.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(7) ذكره الحافظ في الإصابة، ورواه البخاري في «التاريخ الصغير» باسناد جيد، وأخرجه مسلم في صحيحه. أخرجه البخاري في الطب، ومسلم في السلام، وأخرجه أبو داود والنسائي وابن ماجه وأحدْ. قال بأصبعه: العرب تعَل القول عبارة عن جيَع الأفعال.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَمَعْنَى الَْحدِيثِ: أَنههُ خََُْذُ مِنْ رِيقِ نَـفْسِهِ عَلَى أُصْبُعِهِ السهبهابَةِ، ُ مه يَضَعُهَا عَلَى التُّـرَابِ، فَـيَـعْلَقُ بَِها مِنْهُ شَيْ ءٌ، فَـيَمْسَحُ بِهِ عَلَى الُْجرْحِ، وَيَـقُولُ هَذَا الْكَلَامَ لِمَا فِيهِ مِنْ بَـرَكَةِ ذِكْرِ اسْمِ ا هلِلَّ، وَتَـفْوِيضِ الَْأمْرِ إِلَيْهِ، وَالتهـوَكُّلِ عَلَيْهِ، فَـيَـنْضَمُّ أَحَدُ الْعِلَاجَيِْن إِلَى الْآخَرِ، فَـيَـقْوَى التهأْثِيُر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَهَلِ الْمُرَادُ بِقَوْلِهِ: «تُـرْبَةُ أَرْضِ نَا» جَِيَعُ الَْأرْضِ أَوْ أَرْضُ الْمَدِينَةِ خَاصهةً؟ فِيهِ قَـوْلَانِ، وَلَا رَيْبَ أَنه مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'التُّـرْبَةِ مَا تَكُونُ فِيهِ خَاصِّيهةٌ يَـنْـفَعُ خِاَِصِّ يهتِهِ مِنْ أَدْوَاءٍ كثرة، ويشفي بها أَسْقَامًا رَدِيئَةً. قَالَ جالينوس: رَأَيْتُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'بِالِْإسْكَنْدَرِيهةِ مَطْحُولِيَن، وَمُسْتَسْقِيَن، كَثِيًرا يَسْتَـعْمِلُونَ طِيَن مِصْرَ، وَيَطْلُونَ بِهِ عَلَى سُوقِهِمْ، وَأَفْخَاذِهِمْ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَسَوَاعِدِهِمْ، وَظُهُورِهِمْ، وَأَضْلَاعِهِمْ، فَـيَـنْـتَفِعُونَ بِهِ مَنْـفَعَةً بَـيِّنَةً. قَالَ: وَعَلَى هَذَا النهحْوِ فَـقَدْ يَـنْـفَعُ هَذَا الطِّلَاءُ لِلْوَِْرَامِ الْعَفِنَةِ وَالْمُتَـرَهِّلَةِ الهرخْوَةِ، قَالَ: وَإِنِّي لََأعْرِفُ قَـوْمًا تَـرَههلَتْ أَبْدَانُـهُمْ كُلُّهَا مِنْ كَثْـرَةِ اسْتِفْرَاغِ الدهمِ مِنْ أَسْفَلَ، انْـتَـفَعُوا بَِهذَا الطِّيِن نَـفْعًا بَـيِّنًا، وَقَـوْمًا آخَرِينَ شَفَوْا بِهِ أَوْجَاعًا مُزْمِنَةً كَانَتْ مُتَمَكِّنَةً فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'بَـعْضِ الَْأعْضَاءِ تَكََُّنًا شَدِيدًا، فَـبَـرَأَتْ وَذَهَبَتْ أَصْلًا. وَقَالَ صَاحِبُ الْكِتَابِ الْمَسِيحِيِّ: قُـهوةُ الطِّيِن الْمَجْ لُوبِ مِنْ كُنُوسَ - وَهِيَ جَزِيرَةُ الْمَصْطَكَى- قُـهوةٌ تَلَُْو وَتَـغْسِلُ، وَتُـنْبِتُ اللهحْمَ فِي الْقُرُوحِ، وَتَْختِمُ الْقُرُوحَ. انْـتَـهَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَإِذَا كَانَ هَذَا فِي هَذِهِ التُّـرْبَاتِ، فَمَا الظهنُّ بَِأطْيَبِ تُـرْبَةٍ عَلَى وَجْهِ الَْأرْضِ وَأَبْـرَكِهَا، وَقَدْ خَالَطَتْ رِيقَ رَسُولِ اِلله صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَقَارَنَتْ رُقْـيَـتَهُ بِاسْمِ رَبِّهِ، وَتَـفْوِيضِ الَْأمْرِ إِلَيْهِ، وَقَدْ تَـقَدهمَ أَنه قُـوَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'الرُّقْـيَةِ وَتَثَِْيَرهَا بَِحسَبِ الهراقِي، وَانْفِعَالِ الْمَرْقِيِّ عَنْ رُقْـيَتِهِ، وَهَذَا أَمْرٌ لَا يُـنْكِرُهُ طَبِيبٌ فَاضِلٌ عَاقِلٌ مُسْلِمٌ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'فَإِنِ انْـتَـفَى أَحَدُ الَْأوْصَافِ، فَـلْيَـقُلْ ما شاء.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الْوَجَعِ بِالرُّقْـيَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى مسلم فِي «صَحِيحِهِ» عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ ، أَنههُ شَكَى إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَجَعًا يَِجدُهُ فِي جَسَدِهِ مُنْذُ أَسْلَمَ، فَـقَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «ضَعْ يَدَكَ عَلَى الهذِي تَهََلََ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'جَسَدِكَ وَقُلْ: بِسْمِ ا هلِلَّ ثَلَاثًَ، وَقُلْ سَبْعَ مَ هراتٍ: أَعُوذُ بِعِهزةِ ا هلِلَّ وَقُدْرَتِهِ مِنْ شَرِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'مَا أَجِدُ وَأُحَاذِرُ» »7« فَفِي هَذَا الْعِلَاجِ مِنْ ذِكْرِ ا هلِلَّ، وَالتهـفْوِيضِ إِلَيْهِ، وَالِاسْتِعَاذَةِ بِعِهزتِهِ وَقُدْرَتِهِ مِنْ شَرِّ الَْألََِ مَا يَذْهَبُ بِهِ، وَتَكْ رَارُهُ لِيَكُونَ أَنْعََْ وَأَبْـلَغَ، كَتَكْرَارِ الدهوَاءِ لَِأخْرَاجِ الْمَادهةِ، وَفِي السهبْعِ خَاصِّ يهةٌ لَا تُوجَدُ فِي غَيِْرهَا، وَفِي «الصهحِيحَيِْن» :', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'أَنه النهبِه صَ هلى ا هللَُّ عَلَيْهِ وَسَلهمَ، كَانَ يُـعَوِّذُ بَـعْضَ أَهْلِهِ، يَْمسَحُ بِيَدِهِ الْيُمْنَى، وَيَـقُولُ: «اللههُمه رَبه النهاسِ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'أَذْهِبِ الْبَاسَ ، وَاشْفِ أَنْتَ الشهافِي، لَا شِفَاءَ إِهلا شِفَاؤُكَ، شِفَاءً لَا يُـغَادِرُ سَقَمًا» »2« . فَفِي هَذِهِ الرُّقْـيَةِ تَـوَسُّلٌ إِلَى ا هلِلَّ بِكَمَالِ رُبُوبِيهتِهِ، وَكَمَالِ رَحْتَِْهِ بِالشِّ فَاءِ، وَأَنههُ وَحْدَهُ الشهافِي، وَأَنههُ لَا شِفَاءَ إِهلا شِفَاؤُهُ، فَـتَضَمهنَتِ التهـوَسُّلَ إِلَيْهِ بِتَـوْحِيدِهِ وَإِحْسَانِهِ وربوبيته.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ حَرِّ الْمُصِيبَةِ وَحُزْنَِها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'قَالَ تَـعَالَى: وَبَشِّ رِ الصهابِرِينَ الهذِينَ إِذا أَصابَـتْـهُمْ مُصِيبَةٌ قالُوا: إِهنا هِلِلَّ وَإِهنا إِلَيْهِ راجِعُونَ أُولئِكَ عَلَيْهِمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'صَلَواتٌ مِنْ رَبِِّهمْ وَرَ حَْةٌْ وَأُولئِكَ هُمُ الْمُهْتَدُونَ »3« . وَفِي «الْمُسْنَدِ» عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'قَالَ: «مَا مِنْ أَحَدٍ تُصِيبُهُ مُصِيبَةٌ فَـيَـقُولُ: إِهنا هِلِلَّ وَإِهنا إِلَيْهِ رَاجِعُونَ، اللههُمه أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِِ خَيْـرًا مِنْـهَا، إِهلا أَجَارَهُ ا هللَُّ فِي مُصِ يبَتِهِ، وَأَخْلَفَ لَهُ خَيْـرًا مِنْـهَا» »4«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَهَذِهِ الْكَلِمَةُ مِنْ أَبْـلَغِ عِلَاجِ الْمُصَابِ، وَأَنْـفَعِهِ لَهُ فِي عَاجِلَتِهِ وَآجِلَتِهِ، فَإِنهـهَا تتضمن أصلين عظيمين إذا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'تقَق العبد بمعرفتها تَسَلهى عَنْ مُصِ يبَتِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'أَحَدُهُاَُ: أَنه الْعَبْدَ وَأَهْلَهُ وماله ملك لله عزوجلّ حَقِيقَةً، وَقَدْ جَعَلَهُ عِنْدَ الْعَبْدِ عَارِيَةً، فَإِذَا أَخَذَهُ مِنْهُ، فَـهُوَ كَالْمُعِيِر خََُْذُ مَتَاعَهُ مِنَ الْمُسْتَعِيِر، وَأَيْضًا فَإِنههُ مَفُُْوفٌ بِعَدَمَيِْن: عَدَمٍ قَـبْـلَهُ، وَعَدَمٍ بَـعْدَهُ، وَمِلْكُ الْعَبْدِ لَهُ مُتْـعَةٌ مُعَارَةٌ في زمن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '(7) أخرجه مسلم في السلام. وأخرجه ابن ماجه وأحدْ والطباَني. (2) أخرجه البخاري في الطب، ومسلم في السلام', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(3) البقرة. آية .755', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, '(4) أخرجه أحدْ ومسلم في الجنائز', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'يَسِيٍر، وَأَيْضًا فَإِنههُ لَيْسَ الهذِي أَوْجَدَهُ عَنْ عَدَمِهِ، حَ هتى يَكُونَ مِلْكُهُ حَقِيقَةً، وَلَا هُوَ الهذِي يَْحفَظُهُ مِنَ الْآفَاتِ بَـعْدَ وُجُودِهِ، وَلَا يُـبْقِي عَلَيْهِ وُجُودَهُ، فَـلَيْسَ لَهُ فِيهِ تَثَِْيٌر، وَلَا مِلْكٌ حَقِيقِيٌّ، وَأَيْضًا فَإِنههُ مُتَصَرِّفٌ فِيهِ بِالَْأمْرِ تَصَرُّفَ الْعَبْدِ الْمَأْمُورِ الْمَنْهِيِّ، لَا تَصَرُّفَ الْمُ هلاكِ، وَلَِهذَا لَا يُـبَاحُ لَهُ مِنَ التهصَرُّفَاتِ فِيهِ إِهلا مَا وَافَقَ أَمْرَ مَالِكِهِ الَْحقِيقِيِّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَالثهانِي: أَنه مَصِيَر الْعَبْدِ وَمَرْجِعَهُ إِلَى ا هلِلَّ مَوْلَاهُ الَْحقِّ، وَلَا بُده أَنْ يَُخلِّفَ الدُّنْـيَا وَرَاءَ ظَهْرِهِ، وَيَِجيءَ رَبههُ فَـرْدًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'كَمَا خَلَقَهُ أَهولَ مَ هرةٍ بِلَا أَهْلٍ وَلَا مَالٍ وَلَا عَشِيَرةٍ، وَلَكِنْ بِالَْحسَنَاتِ وَالسهيِّئَاتِ، فَإِذَا كَانَتْ هَذِهِ بِدَايَةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'الْعَبْدِ وَمَا خُوِّلَهُ وَنَِهايَـتَهُ، فَكَيْفَ يَـفْرَحُ بَِموْجُودٍ، أَوْ سَََْى عَلَى مَفْقُودٍ، فَفِكْ رُهُ فِي مَبْدَئِهِ وَمَعَادِهِ مِنْ أَعْظَمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'عِلَاجِ هَذَا الدهاءِ، وَمِنْ عِلَاجِهِ أَنْ يَـعْلَمَ عِلْمَ الْيَقِيِن أَنه مَا أَصَابَهُ لََْ يَكُنْ لِيُخْطِئَهُ، وَمَا أَخْطَأَهُ لََْ يَكُنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'لِيُصِيبَهُ. قَالَ تَـعَالَى: مَا أَصابَ مِنْ مُصِيبَةٍ فِي الَْأرْضِ وَلا فِي أَنْـفُسِكُمْ إِهلا فِي كِتابٍ مِنْ قَـبْلِ أَنْ نَـبْـرَأَها إِنه ذلِكَ عَلَى ا هلِلَّ يَسِيٌر لِكَيْلا تَسََْوْا عَلى مَا فاتَكُمْ وَلا تَـفْرَحُوا بِما آتاكُمْ وَا هللَُّ لَا يُِحبُّ كُله مُْختالٍ فَخُورٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, '»7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَمِنْ عِلَاجِهِ أَنْ يَـنْظُرَ إِلَى مَا أُصِيبَ بِهِ، فَـيَجِدُ رَبههُ قَدْ أَبْـقَى عَلَيْهِ مِثْـلَهُ، أَوْ أَفْضَلَ مِنْهُ، وَادهخَرَ لَهُ- إِنْ صَبَـرَ وَرَضِيَ- مَا هُوَ أَعْظَمُ مِنْ فَـوَاتِ تِلْكَ الْمُصِ يبَةِ بَِأضْعَافٍ مُضَاعَفَةٍ، وَأَنههُ لَوْ شَاءَ لََجعَلَهَا أعظم مما هي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'ومن علاجه أن يطفىء نَارَ مُصِ يبَتِهِ بِبَـرْدِ التهأَسِّي بَِأهْلِ الْمَصَائِبِ، وَلِيَـعْلَمَ أَنههُ فِي كُلِّ وَادٍ بَـنُو سَعْدٍ ]7[ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَلْيَـنْظُرْ يَْمنَةً، فَـهَلْ يَـرَى إِهلا مِنَُْةً؟ ُ مه لِيَـعْطِفْ يَسْرَةً، فَـهَلْ يَـرَى إِهلا حَسْرَةً؟ ]2[ ، وَأَنههُ لَوْ فتش العالَ لَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'يرفيهم إِهلا مُبْـتَـلًى، إِمها بِفَوَاتِ مَبُُْوبٍ، أَوْ حُصُولِ مَكْ رُوهٍ، وَأَنه شُرُورَ الدُّنْـيَا أَحْلَامُ نَـوْمٍ أَوْ كَظِلٍّ زَائِلٍ، إِنْ أَضْحَكَتْ قَلِيلًا، أَبْكَتْ كَثِيًرا، وَإِنْ سَ هرتْ يَـوْمًا، سَاءَتْ دَهْرًا، وَإِنْ مَتهـعَتْ قَلِيلًا، مَنَـعَتْ طَوِيلًا، وَمَا مَلَتَِْ دَارًا خِيَرةً إِهلا مَلَتَِْـهَا عَبْـرَةً، وَلَا سَ هرتْهُ بِيَـوْمِ سُرُورٍ إِهلا خَبهأَتْ لَهُ يَـوْمَ شُرُورٍ، قَالَ ابْنُ مَسْعُودٍ- رَضِيَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'ا هللَُّ عَنْهُ:- لِكُلِّ فَـرْحَةٍ تَـرْحَةٌ، وما ملىء بيت فرحا إلا ملىء تَـرَحًا. وَقَالَ ابْنُ سِيِرينَ: مَا كَانَ ضَحِكٌ قَطُّ إِهلا كَانَ مِنْ بَـعْدِهِ بُكَاءٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَقَالَتْ هند بنت النعمان: لَقَدْ رَأَيْـتُـنَا وَنَنُْْ مِنْ أَعَزِّ النهاسِ وَأَشَدِّهِمْ مُلْكًا، ُ مه لََْ تَغِبِ الشهمْسُ حَ هتى رَأَيْـتُـنَا وَنَنُْْ أَقَلُّ النهاسِ ، وَأَنههُ حَقٌّ عَلَى ا هلِلَّ أَهلا يَْملََِ دَارًا خِيَرةً إلا ملهِا عبةَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, '(7) الحديد- -22', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَسَأَلََها رَجُلٌ أَنْ تُدََِّثَهُ عَنْ أَمْرِهَا، فَـقَالَتْ ؛ أَصْبَحْ نَا ذَا صَبَاحٍ، وَمَا فِي الْعَرَبِ أَحَدٌ إِهلا يَـرْجُونَا، ُ مه أَمْسَيْـنَا وَمَا فِي الْعَرَبِ أَحَدٌ إِهلا يَـرْحَنَُْا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'وَبَكَتْ أُخْ تُـهَا حرقة بنت النعمان يوما، وهي في غزها، فَقِيلَ لََها: مَا يُـبْكِيكِ ، لَعَله أَحَدًا آذَاكِ؟ قَالَتْ : لَا، وَلَكِنْ رَأَيْتُ غَضَارَةً ]7[ فِي أَهْلِي، وَقَـلهمَا امْتَلَتَِْ دَارٌ سُرُورًا إِهلا امْتَلَتَِْ حُزْنًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'قَالَ إِسْحَاقُ بْنُ طَلْحَةَ: دَخَلْتُ عَلَيْـهَا يَـوْمًا، فَـقُلْتُ لََها: كَيْفَ رَأَيْتِ عَبَـرَاتِ الْمُلُوكِ؟ فَـقَالَتْ : مَا نَنُْْ فِيهِ الْيَـوْمَ خَيْـرٌ مِمها كُنها فِيهِ الَْأمْسَ ، إِهنا نَِدُْ فِي الْكُتُبِ أَنههُ لَيْسَ مِنْ أَهْلِ بَـيْتٍ يَعِيشُونَ فِي خِيَرةٍ إِهلا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'ٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'بِيَـوْم يَكْ رَهُونَهُ، ُ مه قَالَتْ :', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'سَيُـعْقَبُونَ بَـعْدَهَا عَبْـرَةً، وَأَنه الدههْرَ لََْ يَظْهَرْ لِقَوْمٍ بِيَـوْمٍ يُِحبُّونَهُ إِهلا بَطَنَ لَهمُْ فَـبَـيْـنَا نَسُوسُ النهاسَ وَالَْأمْرُ أَمْرُنَا ... إِذَا نَنُْْ فِيهِمْ سُوقَةٌ نَـتَـنَصهفُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'فَأُفٍّ لِدُنْـيَا لَا يَدُومُ نَعِيمُهَا ... تَـقَلهبُ تَارَاتٍ بِنَا وَتَصَ هرفُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, ']2[ وَمِنْ عِلَاجِهَا أَنْ يَـعْلَمَ أَنه الَْجزَعَ لَا يَـرُدُّهَا، بَلْ يُضَاعِفُهَا، وَهُوَ فِي الَْحقِيقَةِ مِنْ تَـزَايُدِ الْمَرَضِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَمِنْ عِلَاجِهَا أَنْ يَـعْلَمَ أَنه فَـوْتَ ثَـوَابِ الصهبَِْ وَالتهسْلِيمَ، وَهُوَ الصهلَاةُ وَالهرحْةَُْ وَالِْهدَايَةُ الهتِي ضَمِنَـهَا ا هللَُّ عَلَى الصهبَِْ، وَالِاسْتِْرجَاعِ أَعْظَمُ مِنَ الْمُصِيبَةِ فِي الَْحقِيقَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'ومن علاجها أن يعلم أن الجزع بشمت عَدُ هوهُ، وَيَسُوءُ صَدِيقَهُ، وَيُـغْضِبُ رَبههُ، وَيَسُرُّ شَيْطَانَهُ، وَيُْحبِطُ أَجْ رَهُ، وَيُضْعِفُ نَـفْسَهُ، وَإِذَا صَبَـرَ وَاحْتَسَبَ أَنْضَى شَيْطَانَهُ، وَرَدههُ خَاسِئًا، وَأَرْضَى رَبههُ، وَسَ هر صَدِيقَهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'وَسَاءَ عَدُ هوهُ، وَحَلََْ عَنْ إِخْ وَانِهِ، وَعَهزاهُمْ هُوَ قَـبْلَ أَنْ يُـعَزُّوهُ، فَـهَذَا هُوَ الثهـبَاتُ وَالْكَمَالُ الَْأعْظَمُ، لَا لَطْمُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'الُْخدُودِ، وَشَقُّ الُْجيُوبِ، وَالدُّعَاءُ بِالْوَيْلِ وَالثُّـبُورِ، وَالسُّخْطُ عَلَى الْمَقْدُورِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'وَمِنْ عِلَاجِهَا: أَنْ يَـعْلَمَ أَنه مَا يُـعْقِبُهُ الصهبْـرُ وَالِاحْتِسَابُ مِنَ اللهذهةِ وَالْمَسَ هرةِ أَضْعَافُ مَا كَانَ يَْحصُلُ لَهُ بِبَـقَاءِ مَا أُصِيبَ بِهِ لَوْ بَقِيَ عَلَيْهِ، وَيَكْفِيهِ مِنْ ذَلِكَ بَـيْتُ الَْحمْدِ الذي يا بنى لَهُ فِي الَْجنهةِ عَلَى حَدِْْهِ لِرَبِّهِ وَاسْتِْرجَاعِهِ، فَـلْيَـنْظُرْ: أَيُّ الْمُصِ يبَـتَـيِْن أَعْظَمُ؟: مُصِيبَةُ الْعَاجِلَةِ، أَوْ مُصِيبَةُ فَـوَاتِ بَـيْتِ الَْحمْدِ فِي جَنهةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'وفي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'الُْخلْدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'الترمذي مَرْفُوعًا: «يَـوَدُّ نَاسٌ يَـوْمَ الْقِيَامَةِ أَنه جلودهم كانت تقرض بالمقاريض في التدنيا لِمَا يَـرَوْنَ مِنْ ثَـوَابِ أَهْلِ الْبَلَاءِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'وَقَالَ بعض السلف: لولا مصائب الدنيا لوردنا القيامة مَفَالِيسَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'وَمِنْ عِلَاجِهَا: أَنْ يُـرَوّحَِ قَـلْبَهُ بِرُوحِ رَجَاءِ الَْخلَفِ مِنَ ا هلِلَّ، فَإِنههُ مِنْ كُلِّ شَيْ ءٍ عِوَضٌ إِهلا ا هللََّ، فَمَا مِنْهُ عِوَضٌ كَمَا قِيلَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'مِنْ كُلِّ شَيْ ءٍ إِذَا ضَيهـعْتَهُ عِوَضٌ ... وَمَا مِنَ ا هلِلَّ إِنْ ضَيهـعْتَهُ عِوَضُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'وَمِنْ عِلَاجِهَا: أَنْ يَـعْلَمَ أَنه حَظههُ مِنَ الْمُصِيبَةِ مَا تُدَِْثُهُ لَهُ، فَمَنْ رَضِيَ ، فَـلَهُ الرِّضَى، وَمَنْ سَخِطَ، فَـلَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'السُّخْطُ، فَحَظُّكَ مِنْـهَا مَا أَحْدَثَـتْهُ لَكَ ، فَاخْ تَـرْ خَيْـرَ الُْحظُوظِ أَوْ شَ هرهَا، فَإِنْ أَحْدَثَتْ لَهُ سُخْطًا وَكُفْرًا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'كُتِبَ فِي دِيوَانِ الَْهالِكِيَن، وَإِنْ أَحْدَثَتْ لَهُ جَزَعًا وَتَـفْرِيطًا فِي تَـرْكِ وَاجِبٍ، أَوْ فِعْلِ مُهَُرمٍ، كُتِبَ فِي دِيوَانِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'الْمُفَرِّطِيَن، وَإِنْ أَحْدَثَتْ  لَهُ شِكَايَةً، وَعَدَمَ صَبٍَْ، كُتِبَ فِي دِيوَانِ الْمَغْبُونِيَن، وَإِنْ أَحْ دَثَتْ  لَهُ اعْتَِراضًا عَلَى ا هلِلَّ، وَقَدْحًا فِي حِكْمَتِهِ، فَـقَدْ قَـرَعَ بَابَ الهزنْدَقَةِ أَوْ وَلََجهُ، وَإِنْ أَحْدَثَتْ لَهُ صَبْـرًا وَثَـبَاتًا هِلِلَّ، كُتِبَ فِي دِيوَانِ الصهابِرِينَ، وَإِنْ أَحْدَثَتْ لَهُ الرِّضَى عَنِ ا هلِلَّ، كُتِبَ فِي دِيوَانِ الهراضِيَن، وَإِنْ أَحْدَثَتْ لَهُ الَْحمْدَ وَالشُّكْرَ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 48, 'كُتِبَ فِي دِيوَانِ الشهاكِرِينَ، وَكَانَ تَتََْ لِوَاءِ الَْحمْدِ مَعَ الَْحمهادِينَ، وَإِنْ أَحْدَثَتْ لَهُ مَبَُهةً وَاشْتِيَاقًا إِلَى لِقَاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 49, 'رَبِّهِ، كُتِبَ فِي دِيوَانِ الْمُحِبِّيَن الْمُخْلِصِيَن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 50, 'وَفِي «مُسْنَدِ الِْإمَامِ أَحْدََْ» وَالتِّْرمِذِيِّ ، مِنْ حَدِيثِ مَمُُْودِ بْنِ لَبِيدٍ يَـرْفَـعُهُ: «إِنه ا هللََّ إِذَا أَحَبه قَـوْمًا ابْـتَلَاهُمُ، فَمَنْ رَضِيَ فَـلَهُ الرِّضَى، ومن سخط فله السّخط» . زاد «وَمَنْ جَزعَِ فَـلَهُ الَْجزَعُ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 51, 'وَمِنْ عِلَاجِهَا: أَنْ يَـعْلَمَ أَنههُ وَإِنْ بَـلَغَ فِي الَْجزَعِ غَايَـتَهُ، فَآخِرُ أَمْرِهِ إِلَى صَبَِْ الِاضْطِرَارِ، وَهُوَ غَيْـرُ مَمُُْودٍ وَلَا مُثَابٍ، قَالَ بَـعْضُ الُْحكَمَاءِ: الْعَاقِلُ يفعل في أوّل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 52, '(7) أخرجه الترمذي في باب الزهد.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 53, '(2) أخرجه أحدْ في المسند، وهو حديث صحيح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 54, 'يَـوْمٍ مِنَ الْمُصِيبَةِ مَا يَـفْعَلُهُ الَْجاهِلُ بَـعْدَ أَهيامٍ، وَمَنْ لََْ يَصْبَِْ صَبْـرَ الْكِرَامِ، سَلَا سُلُهو الْبَـهَائِمِ. وَفِي «الصهحِيحِ» مَرْفُوعًا: «الصهبْـرُ عِنْدَ الصهدْمَةِ الُْأولَى» »7« . وَقَالَ الَْأشْعَثُ بْنُ قَـيْسٍ : إِنهكَ إِنْ صَبَـرْتَ إِيَمانًا وَاحْ تِسَابًا، وَإِهلا سَلَوْتَ سُلُهو الْبَـهَائِمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 55, 'وَمِنْ عِلَاجِهَا: أَنْ يَـعْلَمَ أَنه أَنْـفَعَ الَْأدْوِيَةِ لَهُ مُوَافَـقَةُ رَبِّهِ وَإِلَِههِ فِيمَا أَحَ بههُ وَرَضِيَهُ لَهُ، وَأَنه خَاصِّ يهةَ الْمَحَبهةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 56, 'وَسِهرهَا مُوَافَـقَةُ الْمَحْ بُوبِ، فَمَنِ ادهعَى مَبَُهةَ مَبُُْوبٍ، ُ مه سَخِطَ مَا يُِحبُّهُ، وَأَحَبه مَا يَسْخَطُهُ، فَـقَدْ شَهِدَ عَلَى نَـفْسِهِ بِكَذِبِهِ، وَتَقََهتَ إِلَى مَبُُْوبِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 57, 'وَقَالَ أَبُو الدهرْدَاءِ: إِنه ا هللََّ إِذَا قَضَى قَضَاءً، أحب أن يرضى به، وكان عمران ابن حُصَيٍْن يَـقُولُ فِي عِلهتِهِ: أَحَبُّهُ إِلَهِ أَحَبُّهُ إِلَيْهِ، وَكَذَلِكَ قَالَ أبو العالية.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 58, 'وَهَذَا دَوَاءٌ وَعِلَاجٌ لَا يَـعْمَلُ إِهلا مَعَ الْمُحِبِّيَن، وَلَا يُْمكِنُ كُلُّ أَحَدٍ أَنْ يَـتَـعَالَََ بِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 59, 'وَمِنْ علاجها: أن يوازن بين أعظم اللذتين والتمتعين، وَأَدْوَمِهِمَا: لَذهةِ تَتََُّعِهِ بَِما أُصِيبَ بِهِ، وَلَذهةِ تَتََُّعِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 60, 'بِثَـوَابِ ا هلِلَّ لَهُ، فَإِنْ ظَهَرَ لَهُ الرُّجْحَانُ، فَآثَـرَ الهراجِحَ، فَـلْيَحْمَدِ ا هللََّ عَلَى تَـوْفِيقِهِ، وَإِنْ آثَـرَ الْمَرْجُوحَ مِنْ كُلِّ وَجْهٍ، فَـلْيَـعْلَمْ أَنه مُصِيبَـتَهُ فِي عَقْلِهِ وَقَـلْبِهِ وَدِينِهِ أَعْظَمُ مِنْ مُصِ يبَتِهِ الهتِي أُصِيبَ بَِها فِي دُنْـيَاهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 61, 'وَمِنْ عِلَاجِهَا أَنْ يَـعْلَمَ أَنه الهذِي ابْـتَلَاهُ بَِها أَحْكَمُ الَْحاكِمِيَن، وَأَرْحَمُ الهراحِِيَْن، وَأَنههُ سُبْحَانَهُ لََْ يُـرْسِلْ إِلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 62, 'الْبَلَاءَ لِيُـهْلِكَهُ بِهِ، وَلَا لِيُـعَذِّبَهُ بِهِ، وَلَا لِيَجْتَاحَهُ، وَإِهنَما افْـتَـقَدَهُ بِهِ لِيَمْتَحِنَ صَبْـرَهُ وَرِضَاهُ عَنْهُ وَإِيَمانَهُ، وَلِيَسْمَعَ تَضَرُّعَهُ وَابْتِهَالَهُ، وَلِيَـرَاهُ طَرِيًحا بِبَابِهِ، لَائِذًا بِنََِابِهِ، مَكْسُورَ الْقَلْبِ بَـيَْن يَدَ يْهِ، رَافِعًا قَصَصَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 63, 'الشهكْ وَى إِلَيْهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 64, 'قَالَ الشيخ عبد القادر: يَا بُـ هَنِ! إِنه المصيبة ما جاءت لتهلك، وَإِهنَما جَاءَتْ لِتَمْتَحِنَ صَبْـرَكَ وَإِيَمانَكَ ، يَا بُـ هَنِ! الْقَدَرُ سَبُعٌ، وَالسهبُعُ لَا كََُْلُ الْمَيْـتَةَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 65, 'وَالْمَقْصُودُ: أَنه الْمُصِيبَةَ كِيُر الْعَبْدِ الهذِي يُسْبَكُ بِهِ حَاصِلُهُ، فَإِمها أَنْ يَْخرُجَ ذَهَبًا أَحْرََْ، وَإِمها أَنْ يَْخرُجَ خَبَـثًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 66, 'كُلُّهُ، كَمَا قِيلَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 67, 'سَبَكْ نَاهُ وَنَسِْْبُهُ لَُجيْـنًا ... فَأَبْدَى الْكِيُر عَنْ خَبَثِ الَْحدِيدِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 68, '(7) أخرجه البخاري في الجنائز، ومسلم في الجنائز.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 69, 'فَإِنْ لََْ يَـنْـفَعْهُ هَذَا الْكِيُر فِي الدُّنْـيَا، فَـبَـيَْن يَدَيْهِ الْكِيُر الَْأعْظَمُ، فَإِذَا عَلِمَ الْعَبْدُ أَنه إِدْخَالَهُ كِيَر الدُّنْـيَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 70, 'وَمَسْبَكَهَا خَيْـرٌ لَهُ من ذلك الكير والمسبك، وأنه لابد مِنْ أَحَدِ الْكِيَريْنِ، فَـلْيَـعْلَمْ قَدْرَ نِعْمَةِ ا هلِلَّ عَلَيْهِ فِي الْكِيِر الْعَاجِلِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 71, 'وَمِنْ عِلَاجِهَا: أَنْ يَـعْلَمَ أَنههُ لَوْلَا مِنَُُ الدُّنْـيَا وَمَصَائِبُـهَا، لََأصَابَ الْعَبْدَ مِنْ أَدْوَاءِ الْكِبَِْ وَالْعُجْبِ وَالْفَرْعَنَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 72, 'وَقَسْوَةِ الْقَلْبِ مَا هُوَ سَبَبُ هَلَاكِهِ عَاجِلًا وَآجِلًا، فَمِنْ رَحْةَِْ أَرْحَمِ الهراحِِيَْن أَنْ يَـتَـفَقهدَهُ فِي الَْأحْ يَانِ بَِأنْـوَاعٍ مِنْ أَدْوِيَةِ الْمَصَائِبِ، تَكُونُ حَِيْهةً لَهُ مِنْ هَذِهِ الَْأدْوَاءِ، وَحِفْظًا لِصِحهةِ عُبُودِيهتِهِ، وَاسْتِفْرَاغًا لِلْمَوَادِّ الْفَاسِدَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 73, 'الهردِيئَةِ الْمُهْلِكَةِ مِنْهُ، فَسُبْحَانَ مَنْ يَـرْحَمُ بِبَلَائِهِ، وَيَـبْـتَلِي بِنَـعْمَائِهِ كَمَا قِيلَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 74, 'قد ينعم الله بِالْبَـلْوَى وَإِنْ عَظُمَتْ ... وَيَـبْـتَلِي ا هللَُّ بَـعْضَ الْقَوْمِ بِالنِّعَمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 75, 'فَـلَوْلَا أَنههُ- سُبْحَانَهُ- يُدَاوِي عِبَادَهُ بَِأدْوِيَةِ الْمِحَنِ وَالِابْتِلَاءِ، لَطَغَوْا، وَبَـغَوْا، وَعَتَـوْا، وَا هللَُّ- سُبْحَانَهُ- إِذَا أَرَادَ بِعَبْدٍ خَيْـرًا سَقَاهُ دَوَاءً مِنَ الِابْتِلَاءِ وَالِامْتِحَانِ عَلَى قَدْرِ حَالِهِ يَسْتَـفْرغُِ بِهِ مِنَ الَْأدْوَاءِ الْمُهْلِكَةِ، حَ هتى إِذَا هَذهبَهُ وَنَـقهاهُ وَصَ هفاهُ، أَههلَهُ لَِأشْرَفِ مَرَاتِبِ الدُّنْـيَا، وَهِيَ عُبُودِيهـتُهُ، وَأَرْفَعِ ثَـوَابِ الْآخِرَةِ، وَهُوَ رُؤْيَـتُهُ وَقُـرْبُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 76, 'وَمِنْ عِلَاجِهَا: أَنْ يَـعْلَمَ أَنه مَرَارَةَ الدُّنْـيَا هِيَ بِعَيْنِهَا حَلَاوَةُ الْآخِرَةِ، يَـقْلِبُـهَا ا هللَُّ سُبْحَانَهُ كَذَلِكَ ، وَحَلَاوَةَ الدُّنْـيَا بِعَيْنِهَا مَرَارَةُ الْآخِرَةِ، وَلََأنْ يَـنْـتَقِلَ مِنْ مَرَارَةٍ مُنْـقَطِعَةٍ إِلَى حَلَاوَةٍ دَائِمَةٍ خَيْـرٌ لَهُ مِنْ عَكْسِ ذَلِكَ ، فَإِنْ خَفِيَ عَلَيْكَ هَذَا، فَانْظُرْ إِلَى قَـوْلِ الصهادِقِ الْمَصْدُوقِ: «حُ هفتِ الَْجنهةُ بِالْمَكَارِهِ وَحُ هفتِ النهارُ بِالشههَوَاتِ»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 77, '. »', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 78, 'وَفِي هَذَا الْمَقَامِ تَـفَاوَتَتْ عُقُولُ الَْخلَائِقِ، وَظَهَرَتْ حَقَائِقُ الرِّجَالِ، فَأَكْثَـرُهُمْ آثَـرَ الَْحلَاوَةَ الْمُنْـقَطِعَةَ عَلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 79, 'الَْحلَاوَةِ الدهائِمَةِ الهتِي لَا تَـزُولُ، وَلََْ يَْحتَمِلْ مَرَارَةَ سَاعَةٍ لَِحلَاوَةِ الَْأبَدِ، وَلَا ذُ هل سَاعَةٍ لِعِزِّ الَْأبَدِ، وَلَا مِنَُْةَ سَاعَةٍ لِعَافِيَةِ الَْأبَدِ، فَإِنه الَْحاضِرَ عِنْدَهُ شَهَادَةٌ، وَالْمُنْـتَظَرَ غَيْبٌ ، وَالِْإيَمانَ ضَعِيفٌ ، وَسُلْطَانُ الشههْوَةِ حَاكِمٌ، فَـتَـوَلهدَ مِنْ ذَلِكَ إِيثَارُ الْعَاجِلَةِ، وَرَفْضُ الْآخِرَةِ، وَهَذَا حَالُ النهظَرِ الْوَاقِعِ عَلَى ظواهر الأمور،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 80, '(7) أخرجه مسلم في الجنة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 81, 'وَأَوَائِلِهَا وَمَبَادِئِهَا، وَأَمها النهظَرُ الثهاقِبُ الهذِي يَْخرِقُ حُجُبَ الْعَاجِلَةِ، وَيَُجاوِزُهُ إِلَى الْعَوَاقِبِ وَالْغَايَاتِ، فَـلَهُ شَأْنٌ آخَرُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 82, 'فَادعُْ نَـفْسَكَ إِلَى مَا أَعَده ا هللَُّ لَِأوْلِيَائِهِ وَأَهْلِ طَاعَتِهِ مِنَ النهعِيمِ الْمُقِيمِ، وَالسهعَادَةِ الَْأبَدِيهةِ، وَالْفَوْزِ الَْأكْ بََِ، وَمَا أَعَده لَِأهْلِ الْبِطَالَةِ وَالِْإضَاعَةِ مِنَ الِْخزْيِ وَالْعِقَابِ وَالَْحسَرَاتِ الدهائِمَةِ، ُ مه اخْ تَـرْ أَيُّ الْقِسْمَيِْن أَلْيَقُ بِكَ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 83, 'وَكُلٌّ يَـعْمَلُ عَلَى شَاكِلَتِهِ، وَكُلُّ أَحَدٍ يَصْبُو إِلَى مَا يُـنَاسِبُهُ، وَمَا هُوَ الَْأوْلَى بِهِ، وَلَا تَسْتَطِلْ هَذَا الْعِلَاجَ، فَشِدهةُ الَْحاجَةِ إِلَيْهِ مِنَ الطهبِيبِ وَالْعَلِيلِ دَعَتْ إِلَى بَسْطِهِ، وَبِا هلِلَّ التهـوْفِيقُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الْكَرْبِ وَالَْهمِّ وَالْغَمِّ وَالَْحزَنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'أَخْ رَجَا فِي «الصهحِيحَيِْن» مِنْ حَدِيثُ ابْنِ عَبهاسٍ ، إِنه رَسُولَ ا هلِلَّ صَلهى الله عليه وسلم كان يَـقُولُ عِنْدَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الْكَرْبِ: «لَا إِلَهَ إِهلا ا هللَُّ الْعَظِيمُ الَْحلِيمُ، لَا إِلَهَ إِهلا ا هللَُّ رَبُّ الْعَرْشِ الْعَظِيمُ، لَا إِلَهَ إِهلا ا هللَُّ رَبُّ السهمَاوَاتِ السهبْعِ، وَرَبُّ الَْأرْضِ رَبُّ الْعَرْشِ الْكَرِيُم» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَفِي «جَامِعِ الترمذي» عَنْ أَنَسٍ ، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، كَانَ إِذَا حَزَبَهُ أَمْرٌ، قَالَ: «يَا حَيُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'يَا قَـيُّومُ بِرَحْتَِْكَ أَسْتَغِيثُ » »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَفِيهِ: عَنْ أَبِي هُرَيْـرَةَ، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، كَانَ إِذَا أَ هههَُُ الَْأمْرُ، رَفَعَ طَرْفَهُ إِلَى السهمَاءِ فَـقَالَ: «سُبْحَانَ ا هلِلَّ الْعَظِيمِ» ، وَإِذَا اجْتَـهَدَ فِي الدُّعَاءِ قَالَ: «يَا حَيُّ يَا قَـيُّومُ» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَفِي «سُنَنِ أبي داود» عَنْ أبي بكرة، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ: «دَعَوَاتُ الْمَكْ رُوبِ: اللُّهُمه رَحْتََْكَ أَرْجُو، فَلَا تَكِلْنِِ إِلَى نَـفْسِي طَرْفَةَ عَيٍْن، وَأَصْلِحْ لِِ شَأْنِي كُلههُ، لا إله إلا أنت» »4« -', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '(7) أخرجه البخاري في الدعوات، ومسلم في الذكر والدعاء.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(2) أخرجه الترمذي في الدعوات. (3) أخرجه الترمذي في الدعوات.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, '(4) أخرجه أبو داود وأحدْ والبخاري في الأدب المفرد.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَفِيهَا أَيْضًا عَنْ أسماء بنت عميس قَالَتْ : قَالَ لِِ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عليه وَسَلهمَ: «أَلَا أُعَلِّمُكِ كَلِمَاتٍ تَـقُولِيهِنه عَنْدَ الْكَرْبِ، أَوْ فِي الْكَرْبِ: ا هللَُّ رَبِّي لَا أُشْرِكُ بِهِ شَيْـئًا» »7« . وَفِي رِوَايَةٍ أَنهـهَا تُـقَالُ سَبْعَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'مَ هراتٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَفِي «مُسْنَدِ الِْإمَامِ أَحْدََْ» عَنِ ابْنِ مَسْ عُودٍ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ: «مَا أَصَابَ عَبْدًا هَمٌّ وَلَا حُزْنٌ فَـقَالَ: اللههُمه إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيه حُكْمُكَ ، عَدْلٌ فِيه قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمهيْتَ بِهِ نَـفْسَكَ ، أَوْ أَنْـزَلْتَهُ فِي كِتَابِكَ ، أَوْ عَلهمْتَهُ أَحَدًا مِنْ خَلْقِكَ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'أَوِ اسْتَأْثَـرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ: أَنْ تَْعََلَ الْقُرْآنَ الْعَظِيمَ رَبِيعَ قَـلْبِ، وَنُورَ صَدْرِي، وَجَلَاءَ حُزْنِي،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَذَهَابَ هَِيُّ، إِهلا أَذْهَبَ ا هللَُّ حُزْنَهُ وَهَهُهُ، وَأَبْدَلَهُ مَكَانَهُ فَـرَحًا» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَفِي الترمذي عَنْ سَعْدِ بْنِ أَبِي وَقهاصٍ ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «دَعْوَةُ ذِي النُّونِ إِذْ دَعَا رَبههُ وَهُوَ فِي بَطْنِ الُْحوتِ: لَا إِلَهَ إِهلا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظهالِمِيَن، لََْ يَدْعُ بَِها رَجُلٌ مُسْلِمٌ فِي شَيْ ءٍ قَطُّ إِهلا اسْتُجِيبَ لَهُ» »3«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَفِي رِوَايَةٍ «إِنِّي لََأعْلَمُ كَلِمَةً لَا يَـقُولَُها مَكْ رُوبٌ إِهلا فَـهرجَ ا هللَُّ عَنْهُ: كَلِمَةَ أَخِي يُونُسَ » .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَفِي «سُنَنِ أبي داود» عَنْ أَبِي سَعِيدٍ الُْخدْرِيِّ ، قَالَ: دَخَلَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ ذَاتَ يَـوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الَْأنْصَارِ يُـقَالُ لَهُ: أبو أمامة، فَـقَالَ: «يَا أبا أمامة مَالِِ أَرَاكَ فِي الْمَسْجِدِ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'غَيِْر وَقْتِ الصهلَاةِ؟» فَـقَالَ: هُوُُمٌ لَزِمَتْنِِ، وَدُيُونٌ يَا رَسُولَ ا هلِلَّ، فَـقَالَ: «أَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُـلْتَهُ أَذْهَبَ ا هللَُّ عَهز وَجَله هَهُكَ وَقَضَى دَيْـنَكَ ؟» قَالَ: قُـلْتُ : بَـلَى يَا رَسُولَ ا هلِلَّ، قَالَ: «قُلْ إِذَا أَصْبَحْتَ وَإِذَا أَمْسَيْتَ : اللههُمه إِنِّي أَعُوذُ بِكَ مِنَ الَْهمِّ وَالَْحزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الُْجبِْن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَالْبُخْلِ، وَأَعُوذُ بِكَ  مِنْ غَلَبَةِ الدهيْنِ وَقَـهْرِ الرِّجَالِ» ، قال: (7) أخرجه أبو داود في الصلاة، وابن ماجه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, '(2) أخرجه أحدْ في «المسند» وسنده صحيح وصححه ابن حبان. (3) أخرجه الترمذي في الدعوات، وأحدْ، وصححه الحاكم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'فَـفَعَلْتُ ذَلِكَ ، فَأَذْهَبَ ا هللَُّ عَهز وَجَله هَِيُّ، وَقَضَى عَنِِّ دَيْنِِ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَفِي «سُنَنِ أبي داود» عَنِ ابْنِ عَبهاسٍ ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَنْ لَزِمَ الِاسْتِغْفَارَ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'جَعَلَ ا هللَُّ لَهُ مِنْ كُلِّ هَمٍّ فَـرَجًا، وَمِنْ كُلِّ ضِيقٍ مَْخرَجًا، وَرَزَقَهُ مِنْ حَيْثُ لَا يَْحتَسِبُ » »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَفِي «الْمُسْنَدِ» أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ إِذَا حَزَبَهُ أَمْرٌ، فَزعَِ إِلَى الصهلَاةِ وَقَدْ قَالَ تَـعَالَى: «وَاسْتَعِينُوا بالصبَ والصلاة» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'وَفِي «السُّنَنِ» : «عَلَيْكُمْ بِالِْجهَادِ، فَإِنههُ بَابٌ مِنْ أَبْـوَابِ الَْجنهةِ، يَدْفَعُ ا هللَُّ بِهِ عَنِ النُّـفُوسِ الْهمَه وَالْغَمه»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, '. »4«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَيُذْكَرُ عَنِ ابْنِ عَبهاسٍ ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَنْ كَثُـرَتْ هُوُُمُهُ وَغُمُومُهُ، فَـلْيُكْثِرْ مِنْ قَـوْلِ: لَا حَوْلَ وَلَا قُـهوةَ إِهلا بِا هلِلَّ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَثَـبَتَ فِي «الصهحِيحَيِْن» أَنهـهَا كَنْـزٌ مِنْ كُنُوزِ الَْجنهةِ »5« . وَفِي الترمذي: «أَنهـهَا بَابٌ مِنْ أَبْـوَابِ الَْجنهةِ» »1« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'هَذِهِ الَْأدْوِيَةُ تَـتَضَمهنُ خَْمسَةَ عَشَرَ نَـوْعًا مِنَ الدهوَاءِ، فَإِنْ لََْ تَـقْوَ عَلَى إِذْهَابِ دَاءِ الْهمَِّ وَالْغَمِّ وَالُْحزْنِ، فَـهُوَ دَاءٌ قَدِ اسْتَحْكَمَ، وَتَكََهنَتْ أَسْبَابُهُ، وَيَْحتَاجُ إِلَى اسْتِفْرَاغٍ كُلِّيٍّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'الَْأهولُ:  تَـوْحِيدُ   الرُّبُوبِيهةِ. الثهانِي: تَـوْحِيدُ الِْإلَِهيهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'الثهالِثُ : التهـوْحِيدُ الْعِلْمِيُّ الِاعْتِقَادِيُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, '(7) أخرجه أبو داود في الصلاة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, '(2) أخرجه أبو داود في الصلاة، وأحدْ، وابن ماجه. (3) البقرة- .45', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, '(4) أخرجه الطباَني في الأوسط، وأحدْ في «المسند» وصححه الحاكم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, '(5) أخرجه البخاري في الدعوات، ومسلم في الذكر والدعاء. (1) أخرجه الترمذي في الدعوات.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'الهرابِعُ: تَـنْزِيهُ الهربِّ تَـعَالَى عَنْ أَنْ يَظْلِمَ عَبْدَهُ، أَوْ خََُْذَهُ بِلَا سَبَبٍ مِنَ الْعَبْدِ يُوجِبُ ذَلِكَ . الَْخامِسُ : اعْتَِرافُ الْعَبْدِ بَِأنههُ هُوَ ال هظالَُِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'السهادِسُ : التهـوَسُّلُ إِلَى الهربِّ تَـعَالَى بَِأحَبِّ الَْأشْيَاءِ، وَهُوَ أَسَْماؤُهُ وَصِ فَاتُهُ، وَمِنْ أَجْعََِهَا لِمَعَانِي الَْأسَْماءِ وَالصِّفَاتِ: الَْحيُّ الْقَيُّومُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'السهابِعُ: الِاسْتِعَانَةُ بِهِ وَحْدَهُ. الثهامِنُ: إِقْـرَارُ الْعَبْدِ لَهُ بِالهرجَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'التهاسِعُ: تَقَِْيقُ التهـوَكُّلِ عَلَيْهِ، وَالتهـفْوِيضِ إِلَيْهِ، وَالِاعْتَِرافِ لَهُ بَِأنه نَاصِ يَـتَهُ فِي يَدِهِ، يَصْرِفُهُ كَيْفَ يَشَاءُ، وَأَنههُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'مَاضٍ فِيهِ حُكْمُهُ، عَدْلٌ فِيهِ قَضَاؤُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'الْعَاشِرُ: أَنْ يَـرْتَعَ قَـلْبُهُ فِي رِيَاضِ الْقُرْآنِ، وَيَْجعَلَهُ لِقَلْبِهِ كَالهربِيعِ لِلْحَيَـوَانِ، وَأَنْ يَسْتَضِيءَ بِهِ فِي ظُلُمَاتِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'الشُّبُـهَاتِ وَالشههَوَاتِ، وَأَنْ يَـتَسَلهى بِهِ عَنْ كُلِّ فَائِتٍ، وَيَـتَـعَهزى بِهِ عَنْ كُلِّ مُصِيبَةٍ، وَيَسْتَشْفِيَ بِهِ مِنْ أَدْوَاءِ صَدْرِهِ، فَـيَكُونَ جَلَاءَ حُزْنِهِ، وَشِفَاءَ هَِهُِّ وَغَمِّهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'الَْحادِيَ عَشَرَ: الِاسْتِغْفَارُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'الثهانَِي عَشَرَ: التهـوْبَةُ. الثهالِثَ عَشَرَ: الِْجهَادُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'الهرابِعَ عَشَرَ: الصهلَاةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'الَْخامِسَ عَشَرَ: الْبَـرَاءَةُ مِنَ الَْحوْلِ وَالْقُهوةِ وَتَـفْوِيضُهُمَا إِلَى مَنْ هُاَُ بِيَدِهِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي بَـيَانِ جِهَةِ تَثَِْيِر هَذِهِ الَْأدْوِيَةِ فِي هَذِهِ الَْأمْرَاضِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'خَلَقَ ا هللَُّ- سُبْحَانَهُ- ابْنَ آدَمَ وَأَعْضَاءَهُ، وَجَعَلَ لِكُلِّ عُضْوٍ مِنْـهَا كَمَالًا إِذَا فَـقَدَهُ أَحَسه بِالَْألََِ، وَجَعَلَ لِمَلِكِهَا وَهُوَ الْقَلْبُ كَمَالًا، إِذَا فَـقَدَهُ، حَضَرَتْهُ أَسْقَامُهُ وَآلَامُهُ مِنَ الْهمُُومِ وَالْغُمُومِ وَالَْأحْ زَانِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'فَإِذَا فَـقَدَتِ الْعَيُْن مَا خُلِقَتْ لَهُ مِنْ قُـهوةِ الِْإبْصَارِ، وَفَـقَدَتِ الُْأذُنُ مَا خُلِقَتْ لَهُ مِنْ قُـهوةِ السهمْعِ، وَاللهسَانُ مَا خُلِقَ لَهُ مِنْ قُـهوةِ الْكَلَامِ، فقدت كمالها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'والقلب: خلق لمعرفة فاطره ومبُته وتوحيده بِهِ، وَالِابْتِهَاجِ بُِحبِّهِ، وَالرِّضَى عَنْهُ، وَالتهـوَكُّلِ عَلَيْهِ، وَالُْحبِّ فِيهِ، وَالْبُـغْضِ فِيهِ، وَالْمُوَالَاةِ فِيهِ، وَالْمُعَادَاةِ فِيهِ، وَدَوَامِ ذِكْرِهِ، وَأَنْ يَكُونَ أَحَبه إِلَيْهِ مِنْ كُلِّ مَا سِوَاهُ، وَأَرْجَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'عِنْدَهُ مِنْ كُلِّ مَا سِوَاهُ، وَأَجَله فِي قَـلْبِهِ مِنْ كُلِّ مَا سِوَاهُ، وَلَا نَعِيمَ لَهُ وَلَا سُرُورَ وَلَا لَذهةَ، بَلْ وَلَا حَيَاةَ إِهلا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'بِذَلِكَ ، وَهَذَا لَهُ بَِمنْزِلَةِ الْغِذَاءِ وَالصِّحهةِ وَالَْحيَاةِ، فَإِذَا فَـقَدَ غِذَاءَهُ وَصِحهتَهُ، وَحَيَاتَهُ، فَالْهمُُومُ وَالْغُمُومُ وَالَْأحْ زَانُ مُسَارِعَةٌ مِنْ كُلِّ صَوْبٍ إِلَيْهِ، وَرَهْنٌ مُقِيمٌ عَلَيْهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَمِنْ أَعْظَمِ أَدْوَائِهِ: الشِّ رْكُ وَالذُّنُوبُ والغافلة وَالِاسْتِهَانَةُ بَِمحَابِّهِ وَمَرَاضِيهِ، وَتَـرْكُ التهـفْوِيضِ إِلَيْهِ، وَقِلهةُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الِاعْتِمَادِ عَلَيْهِ، وَالهركُونُ إِلَى مَا سِوَاهُ، وَالسُّخْطُ بَِمقْدُورِهِ، وَالشهكُّ فِي وَعْدِهِ وَوَعِيدِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَإِذَا تَمََهلْتَ أَمْرَاضَ الْقَلْبِ، وَجَدْتَ هَذِهِ الُْأمُورَ وَأَمْثَالََها هِيَ أَسْبَابُـهَا لَا سَبَبَ لََها سِوَاهَا، فَدَوَاؤُهُ الهذِي لَا دَوَاءَ لَهُ سِوَاهُ مَا تَضَمهنَـتْهُ هَذِهِ الْعِلَاجَاتُ النهـبَوِيهةُ مِنَ الُْأمُورِ الْمُضَادهةِ لِهذَِهِ الَْأدْوَاءِ، فَإِنه الْمَرَضَ يُـزَالُ بِالضِّدِّ، وَالصِّحهةُ تُفََْظُ بِالْمِثْلِ، فَصِحهتُهُ تُفََْظُ بَِهذِهِ الُْأمُورِ النهـبَوِيهةِ، وَأَمْرَاضُهُ بَِأضْدَادِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'فَالتهـوْحِيدُ: يَـفْتَحُ لِلْعَبْدِ بَابَ الَْخيِْر وَالسُّرُورِ وَاللهذهةِ وَالْفَرَحِ وَالِابْتِهَاجِ، وَالتهـوْبَةُ اسْتِفْرَاغٌ لِلْخَِْ لَاطِ وَالْمَوَادِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'الْفَاسِدَةِ الهتِي هِيَ سَبَبُ أَسْقَامِهِ، وَحِيَْْةٌ لَهُ مِنَ التهخْلِيطِ، فَهِيَ تُـغْلِقُ عَنْهُ بَابَ الشُّرُورِ، فَـيُـفْتَحُ لَهُ بَابُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'السهعَادَةِ وَالَْخيِْر بِالتهـوْحِيدِ، وَيُـغْلَقُ بَابُ الشُّرُورِ بِالتهـوْبَةِ وَالِاسْتِغْفَارِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'قَالَ بَـعْضُ الْمُتَـقَدِّمِيَن مِنْ أَئِمهةِ الطِّبِّ : مَنْ أَرَادَ عَافِيَةَ الِْجسْمِ، فَـلْيُـقَلِّلْ مِنَ الطهعَامِ وَالشهرَابِ، وَمَنْ أَرَادَ عَافِيَةَ الْقَلْبِ، فَـلْيَـتْـرُكِ الْآثَمََ. وَقَالَ ثَبَِتُ بْنُ قُـهرةَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'رَاحَةُ الِْجسْمِ فِي قِلهةِ الطهعَامِ، وَرَاحَةُ الرُّوحِ فِي قِلهةِ الْآثَمَِ، وَرَاحَةُ اللِّسَانِ فِي قِلهةِ الْكَلَامِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَالذُّنُوبُ لِلْقَلْبِ، بَِمنْزِلَةِ السُّمُومِ، إِنْ لََْ تُـهْلِكْهُ أَضْعَفَتْهُ، وَلَا بُده، وَإِذَا ضَعُفَتْ قُـهوتُهُ، لََْ يَـقْدِرْ عَلَى مُقَاوَمَةِ الَْأمْرَاضِ ، قَالَ طَبِيبُ الْقُلُوبِ عَبْدُ ا هلِلَّ بْنُ الْمُبَارَكِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'رَأَيْتُ الذُّنُوبَ تُيَِتُ الْقُلُوبَ ... وَقَدْ يُورِثُ الذُّ هل إِدْمَانُـهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَتَـرْكُ الذُّنُوبِ حَيَاةُ الْقُلُوبِ ... وَخَيْـرٌ لِنَـفْسِكَ عِصْيَانُـهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'فَالَْهوَى أَكْبَـرُ أَدْوَائِهَا، وَمَُخالَفَتُهُ أَعْظَمُ أَدْوِيَتِهَا، وَالنهـفْسُ فِي الَْأصْلِ خُلِقَتْ جَاهِلَةً ظَالِمَةً، فَهِيَ لَِجهْلِهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'تَظُنُّ شِفَاءَهَا فِي اتِّبَاعِ هَوَاهَا، وَإِهنَما فِيهِ تَـلَفُهَا وَعَطَبُـهَا، وَلِظُلْمِهَا لَا تَـقْبَلُ مِنَ الطِّبِيبِ النهاصِحِ، بَلْ تَضَعُ الدهاءَ مَوْضِعَ الدهوَاءِ فَـتَـعْتَمِدُهُ، وَتَضَعُ الدهوَاءَ مَوْضِعَ الدهاءِ فَـتَجْ تَنِبُهُ، فَـيَـتَـوَلهدُ مِنْ بَـيِْن إِيثَارِهَا لِلدهاءِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَاجْ تِنَابَِها لِلدهوَاءِ أَنْـوَاعٌ مِنَ الَْأسْقَامِ وَالْعِلَلِ الهتِي تُـعْيِي الَْأطِبهاءَ، وَيَـتَـعَذهرُ مَعَهَا الشِّ فَاءُ. وَالْمُصِيبَةُ الْعُظْمَى، أَنهـهَا تُـرَكِّبُ ذَلِكَ على القدر، فتبّىَء نَـفْسَهَا، وَتَـلُومُ رَبهـهَا بِلِسَانِ الَْحالِ دَائِمًا، وَيَـقْوَى اللهوْمُ حَ هتى يُصَرّحَِ بِهِ اللِّسَانُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَإِذَا وَصَلَ الْعَلِيلُ إِلَى هَذِهِ الَْحالِ، فَلَا يَطْمَعُ فِي بُـرْئِهِ إِهلا أَنْ تَـتَدَاركََهُ رَحْةٌَْ مِنْ رَبِّهِ، فَـيُحْ يِيهِ حَيَاةً جَدِيدَةً، وَيَـرْزُقُهُ طَرِيقَةً حَِيْدَةً، فَلِهَذَا كَانَ حَدِيثُ ابْنِ عَبهاسٍ فِي دُعَاءِ الْكَرْبِ مُشْتَمِلًا عَلَى تَـوْحِيدِ الِْإلَِهيهةِ وَالرُّبُوبِيهةِ، وَوَصْفِ الهربِّ سُبْحَانَهُ بِالْعَظَمَةِ وَالِْحلْمِ، وَهَاتَانِ الصِّفَتَانِ مُسْتَـلْزِمَتَانِ لِكَمَالِ الْقُدْرَةِ وَالهرحْةَِْ، وَالِْإحْسَانِ وَالتهجَاوُزِ، وَوَصْفِهِ بِكَمَالِ رُبُوبِيهتِهِ للعالَ العلوي والسفلي، والعرش هُوَ سَقْفُ الْمَخْ لُوقَاتِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَأَعْظَمُهَا. وَالرُّبُوبِيهةُ التهامهةُ تَسْتَـلْزِمُ تَـوْحِيدَهُ، وَأَنههُ الهذِي لَا تَـنْـبَغِي الْعِبَادَةُ وَالُْحبُّ وَالَْخوْفُ وَالهرجَاءُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَالِْإجْلَالُ وَالطهاعَةُ إِهلا لَهُ. وَعَظَمَتُهُ الْمُطْلَقَةُ تَسْتَـلْزِمُ إِثْـبَاتَ كُلِّ كَمَالٍ لَهُ، وَسَلْبَ كُلِّ نَـقْصٍ وَتَثَِْيلٍ عَنْهُ. وَحِلْمُهُ يَسْتَـلْزِمُ كَمَالَ رَحْتَِْهِ وَإِحْسَانِهِ إِلَى خَلْقِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'فَعِلْمُ الْقَلْبِ وَمَعْرِفَـتُهُ بِذَلِكَ تُوجِبُ مَبَُهـتَهُ وَإِجْلَالَهُ وَتَـوْحِيدَهُ، فَـيَحْصُلُ لَهُ مِنَ الِابْتِهَاجِ وَاللهذهةِ وَالسُّرُورِ مَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'يَدْفَعُ عَنْهُ أَلَََ الْكَرْبِ وَالْهمَِّ وَالْغَمِّ، وَأَنْتَ تَِدَُ الْمَرِيضَ إِذَا وَرَدَ عَلَيْهِ مَا يَسُرُّهُ وَيُـفْرِحُهُ، وَيُـقَوِّي نَـفْسَهُ، كَيْفَ تَـقْوَى الطهبِيعَةُ عَلَى دَفْعِ الْمَرَضِ الِْحسِّ يِّ، فَحُصُولُ هَذَا الشِّ فَاءِ لِلْقَلْبِ أَوْلَى وَأَحْ رَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'ُ مه إِذَا قَابَـلْتَ بَـيَْن ضِيقِ الْكَرْبِ وَسَعَةِ هَذِهِ الَْأوْصَافِ الهتِي تَضَمهنَـهَا دُعَاءُ الْكَرْبِ، وَجَدْتَهُ فِي غَايَةِ الْمُنَاسَبَةِ لِتَـفْرِيجِ هَذَا الضِّيقِ، وَخُرُوجِ الْقَلْبِ مِنْهُ إِلَى سَعَةِ الْبَـهْجَةِ وَالسُّرُورِ، وَهَذِهِ الُْأمُورُ إِهنَما يُصَدِّقُ بَِها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'مَنْ أَشْرَقَتْ فِيهِ أَنْـوَارُهَا، وَبَاشَرَ قَـلْبُهُ حَقَائِقَهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَفِي تَثَِْيِر قَـوْلِهِ: «يَا حَيُّ يَا قَـيُّومُ، بِرَحْتَِْكَ أَسْتَغِيثُ » فِي دَفْعِ هَذَا الدهاءِ مُنَاسَبَةٌ بَدِيعَةٌ، فَإِنه صِفَةَ الَْحيَاةِ مُتَضَمِّنَةٌ لَِجمِيعِ صِفَاتِ الَْأفْـعَالِ، وَلَِهذَا كَانَ اسْمُ ا هلِلَّ الَْأعْظَمُ الهذِي إِذَا دُعِيَ بِهِ أَجَابَ ، وَإِذَا سُئِلَ بِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'أَعْطَى: هُوَ اسْمُ الَْحيِّ الْقَيُّومِ، وَالَْحيَاةُ التهامهةُ تُضَادُّ جَِيَعَ الَْأسْقَامِ وَالْآلَامِ، وَلِهذََا لَمها كَمُلَتْ حَيَاةُ أَهْلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'الَْجنهةِ لََْ يَـلْحَقْهُمْ هَمٌّ وَلَا غَمٌّ وَلَا حَزَنٌ وَلَا شَيْ ءٌ مِنَ الْآفَاتِ. وَنُـقْصَانُ الَْحيَاةِ تَضُرُّ بِالَْأفْـعَالِ، وَتُـنَافِي الْقَيُّومِيهةَ، فَكَمَالُ الْقَيُّومِيهةِ لِكَمَالِ الَْحيَاةِ، فَالَْحيُّ الْمُطْلَقُ التهامُّ الَْحيَاةِ لَا تَـفُوتُهُ صِفَةُ الْكَمَالِ الْبَـتهةَ، وَالْقَيُّومُ لَا يَـتَـعَذهرُ عَلَيْهِ فِعْلٌ مُْمكِنٌ الْبَـتهةَ، فَالتهـوَسُّلُ بِصِفَةِ الحياة والقيومية لَهُ تَثَِْيٌر فِي إِزَالَةِ مَا يُضَادُّ الَْحيَاةَ، وَيَضُرُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'بِالَْأفْـعَالِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'وَنَظِيُر هَذَا تَـوَسُّلُ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إِلَى رَبِّهِ بِرُبُوبِيهتِهِ لِِجبِْيَلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ أَنْ يَـهْدِيَهُ لِمَا اخْتُلِفَ فِيهِ مِنَ الَْحقِّ بِِإذْنِهِ، فَإِنه حَيَاةَ الْقَلْبِ بِالِْهدَايَةِ، وَقَدْ وَكهلَ ا هللَُّ سُبْحَانَهُ هَؤُلَاءِ الَْأمْلَاكَ الثهلَاثَةَ بِالَْحيَاةِ، فَجِبِْيَلُ مُوَكهلٌ بِالْوَحْيِ الهذِي هُوَ حَيَاةُ الْقُلُوبِ، وَمِيكَائِيلُ بِالْقَطْرِ الهذِي هُوَ حَيَاةُ الَْأبْدَانِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَالَْحيَـوَانِ، وَإِسْرَافِيلُ بِالنهـفْخِ فِي الصُّورِ الهذِي هُوَ سَبَبُ حَيَاةِ الْعَالََِ وَعَوْدِ الَْأرْوَاحِ إِلَى أَجْسَادِهَا، فَالتهـوَسُّلُ إِلَيْهِ سُبْحَانَهُ بِرُبُوبِيهةِ هَذِهِ الَْأرْوَاحِ الْعَظِيمَةِ الْمُوَكهلَةِ بِالَْحيَاةِ، لَهُ تَثَِْيٌر فِي حُصُولِ الْمَطْلُوبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وَالْمَقْصُودُ: أَنه لِاسْمِ الَْحيِّ الْقَيُّومِ تَثَِْيًرا خَاصًّا فِي إِجَابَةِ الدهعَوَاتِ، وَكَشْفِ الْكُرُبَاتِ، وَفِي «السُّنَنِ» وَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, '«صَحِيحِ أبي حاتم» مَرْفُوعًا: «اسْمُ ا هلِلَّ الَْأعْظَمُ فِي هَاتَـيِْن الْآيَـتَـيِْن وَإِلهكُُمْ إِلهٌ واحِدٌ لا إِلهَ إِهلا هُوَ الهرحْنُْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'الهرحِيمُ »7« وَفَا تَِةَِ آلِ عِمْرَانَ الَ ا هللَُّ لَا إِلهَ إِهلا هُوَ الَْحيُّ الْقَيُّومُ، قَالَ الترمذي. حَدِيثٌ صَحِيحٌ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'وَفِي «السُّنَنِ» وَ «صَحِيحِ ابْنِ حِبهانَ» أَيْضًا: مِنْ حَدِيثِ أنس أَنه رَجُلًا دَعَا، فَـقَالَ: اللُّهُمه إِنِّي أَسْأَلُكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'بَِأنه لَكَ الَْحمْدَ، لَا إِلَهَ إِهلا أَنْتَ الْمَنهانُ، بَدِيعُ السهمَاوَاتِ وَالَْأرْضِ ، يَا ذَا الَْجلَالِ وَالِْإكْرَامِ، يَا حَيُّ يَا قَـيُّومُ، فَـقَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «لَقَدْ دَعَا ا هللََّ بِاسِْمهِ الَْأعْظَمِ الهذِي إِذَا دُعِيَ بِهِ أَجَابَ ، وإذا سئل به أعطى» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, '(7) البقرة- .713', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, '(2) أخرجه الترمذي في الدعوات، وابن ماجة في الدعاء، وأبو داود في الصلاة، والدارمي. (3) أخرجه النسائي في السهو، وأبو داود في الصلاة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'وَلَِهذَا كَانَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إِذَا اجْ تَـهَدَ فِي الدُّعَاءِ قَالَ: يَا حَيُّ يَا قَـيُّومُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'وَفِي قَـوْلِهِ: «اللههُمه رَحْتََْكَ أَرْجُو فَلَا تَكِلْنِِ إِلَى نَـفْسِي طَرْفَةَ عَيٍْن، وَأَصْلِحْ لِِ شَأْنِي كُلههُ لَا إِلَهَ إِهلا أَنْتَ » مِنْ تَقَِْيقِ الهرجَاءِ لِمَنِ الَْخيْـرُ كُلُّهُ بِيَدَيْهِ وَالِاعْتِمَادُ عَلَيْهِ وَحْدَهُ وَتَـفْوِيضُ الَْأمْرِ إِلَيْهِ، وَالتهضَرُّعُ إِلَيْهِ، أَنْ يَـتَـوَهلى إِصْلَاحَ شَأْنِهِ، وَلَا يَكِلَهُ إِلَى نَـفْسِهِ، وَالتهـوَسُّلُ إِلَيْهِ بِتَـوْحِيدِهِ مِمها لَهُ تَثَِْيٌر قَوِيٌّ فِي دَفْعِ هَذَا الدهاءِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'وَكَذَلِكَ قَـوْلُهُ: ا هللَُّ رَبِّي لَا أُشْرِكُ بِهِ شَيْـئًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'وَأَمها حَدِيثُ ابْنِ مَسْعُودٍ: «اللههُمه إِنِّي عَبْدُكَ ابْنُ عَبْدِكَ» ، فَفِيهِ مِنَ الْمَعَارِفِ الِْإلَِهيهةِ، وَأَسْرَارِ الْعُبُودِيهةِ مَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'لَا يَـتهسِعُ لَهُ كِتَابٌ ، فَإِنههُ يَـتَضَمهنُ الِاعْتَِرافَ بِعُبُودِيهتِهِ وَعُبُودِيهةِ آبَائِهِ وَأُمههَاتِهِ، وَأَنه نَاصِ يَـتَهُ بِيَدِهِ يُصَرِّفُـهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'كَيْفَ يَشَاءُ، فَلَا يَْملِكُ الْعَبْدُ دُونَهُ لِنَـفْسِهِ نَـفْعًا وَلَا ضَرًّا، وَلَا مَوْتًا وَلَا حَيَاةً، وَلَا نُشُورًا، لَِأنه مَنْ نَاصِ يَـتُهُ بِيَدِ غَيِْرهِ، فَـلَيْسَ إِلَيْهِ شَيْءٌ مِنْ أَمْرِهِ، بَلْ هُوَ عَانٍ فِي قَـبْضَتِهِ، ذَلِيلٌ تَتََْ سُلْطَانِ قَـهْرِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'وَقَـوْلُهُ: «مَاضٍ فِيه حُكْمُكَ عَدْلٌ فِيه قَضَاؤُكَ «مُتَضَمِّنٌ لَِأصْلَيِْن عَظِيمَيِْن عَلَيْهِمَا مَدَارُ التهـوْحِيدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 48, 'أَحَدُهُاَُ: إِثْـبَاتُ الْقَدَرِ، وَأَنه أَحْكَامَ الهربِّ تَـعَالَى نَافِذَةٌ فِي عَبْدِهِ مَاضِيَةٌ فِيهِ، لَا انْفِكَاكَ لَهُ عَنْـهَا، وَلَا حِيلَةَ لَهُ فِي دَفْعِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 49, 'وَالثهانِي: أَنههُ- سُبْحَانَهُ- عَدْلٌ فِي هَذِهِ الَْأحْكَامِ، غَيْـرُ ظَالٍَِ لِعَبْدِهِ، بَلْ لَا يَْخرُجُ فِيهَا عَنْ مُوجَبِ الْعَدْلِ وَالِْإحْسَانِ، فَإِنه الظُّلْمَ سَبَـبُهُ حَاجَةُ الظهالَِِ، أَوْ جَهْلُهُ أَوْ سَفَهُهُ، فَـيَسْتَحِيلُ صُدُورُهُ مِمهنْ هُوَ بِكُلِّ شَيْ ءٍ عَلِيمٌ، وَمَنْ هُوَ غَنٌِِّ عَنْ كُلِّ شَيْ ءٍ، وَكُلُّ شَيْءٍ فَقِيٌر إِلَيْهِ، وَمَنْ هُوَ أَحْ كَمُ الَْحاكِمِيَن، فَلَا تَْخرُجُ ذَرهةٌ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 50, 'مَقْدُورَاتِهِ عَنْ حِكْمَتِهِ وَحَدِْْهِ، كَمَا لََْ تَْخرُجْ عَنْ قُدْرَتِهِ وَمَشِيئَتِهِ، فَحِكْمَتُهُ نَافِذَةٌ حَيْثُ نَـفَذَتْ مَشِيئَـتُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 51, 'وَقُدْرَتُهُ، وَلِهذََا قَالَ نَبُِّ ا هلِلَّ هُودٌ صَلهى ا هللَُّ عَلَى نَبِيِّنَا وَعَلَيْهِ وَسَلهمَ، وَقَدْ خَ هوفَهُ قَـوْمُهُ بِلَِِهتِهِمْ: إِنِّي أُشْهِدُ ا هللََّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 52, 'وَاشْهَدُوا أَنِّي بَرِيءٌ مِمها تُشْركُِونَ مِنْ دُونِهِ فَكِيدُونِي جَِيَعاً ُ مه لا تُـنْظِرُونِ إِنِّي تَـوَكهلْتُ عَلَى ا هلِلَّ رَبِّي وَرَبِّكُمْ مَا مِنْ دَابهةٍ إِهلا هُوَ آخِذٌ بِناصِ يَتِها إِنه رَبِّي عَلى صِ راطٍ مُسْتَقِيمٍ »7« ، أَيْ : مَعَ كَوْنِهِ سُبْحَانَهُ آخِذًا بِنَـوَاصِي خَلْقِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 53, '(7) هود- -54 51', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 54, 'وَتَصْرِيفِهِمْ كَمَا يَشَاءُ، فَـهُوَ عَلَى صِ رَاطٍ مُسْتَقِيمٍ لَا يَـتَصَ هرفُ فِيهِمْ إِهلا بِالْعَدْلِ وَالِْحكْمَةِ، وَالِْإحْسَانِ وَالهرحْةَِْ. فَـقَوْلُهُ: مَاضٍ فِيه حُكْمُكَ ، مُطَابِقٌ لِقَوْلِهِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 55, 'مَا مِنْ دَابهةٍ إِهلا هُوَ آخِذٌ بِناصِ يَتِها، وَقَـوْلُهُ: عَدْلٌ فِيه قَضَاؤُكَ مُطَابِقٌ لِقَوْلِهِ: إِنه رَبِّي عَلى صِ راطٍ مُسْتَقِيمٍ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 56, 'ُ مه تَـوَسهلَ إِلَى رَبِّهِ بَِأسَْمائِهِ الهتِي سَمهى بَِها نَـفْسَهُ مَا عَلِمَ الْعِبَادُ مِنْـهَا وَمَا لََْ يَـعْلَمُوا. وَمِنْـهَا: مَا اسْتَأْثَـرَهُ فِي عِلْمِ الْغَيْبِ عِنْدَهُ، فَـلَمْ يُطْلِعْ عَلَيْهِ مَلَكًا مُقَهربًا، وَلَا نَبِيها مُرْسَلًا، وَهَذِهِ الْوَسِيلَةُ أَعْظَمُ الْوَسَائِلِ، وَأَحَبُّـهَا إِلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 57, 'ا هلِلَّ، وَأَقْـرَبُـهَا تَصَِْيلًا لِلْمَطْلُوبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 58, 'ُ مه سَأَلَهُ أَنْ يَْجعَلَ الْقُرْآنَ لِقَلْبِهِ كَالهربِيعِ الهذِي يَـرْتَعُ فِيهِ الَْحيَـوَانُ، وَكَذَلِكَ الْقُرْآنُ رَبِيعُ الْقُلُوبِ، وَأَنْ يَْجعَلَهُ شِفَاءَ هَِهُِّ وَغَمِّهِ، فَـيَكُونَ لَهُ بَِمنْزِلَةِ الدهوَاءِ الهذِي يَسْتَأْصِلُ الدهاءَ، وَيُعِيدُ الْبَدَنَ إِلَى صِحهتِهِ وَاعْتِدَالِهِ، وَأَنْ يَْجعَلَهُ لُِحزْنِهِ كَالَْجلَاءِ الذي يحلو الطُّبُوعَ وَالَْأصْدِيَةَ وَغَيْـرَهَا فَأَحْ رَى بَِهذَا الْعِلَاجِ إِذَا صَدَقَ الْعَلِيلُ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 59, 'اسْتِعْمَالِهِ أَنْ يُزِيلَ عَنْهُ دَاءَهُ، وَيُـعْقِبَهُ شِفَاءً تَامًّا، وَصِحهةً وَعَافِيَةً، وَا هللَُّ الْمُوَفِّقُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 60, 'وَأَمها دَعْوَةُ ذِي النُّونِ : فَإِنه فِيهَا مِنْ كَمَالِ التهـوْحِيدِ وَالتهـنْزِيهِ لِلهربِّ تَـعَالَى وَاعْتَِرافِ الْعَبْدِ بِظُلْمِهِ وَذَنْبِهِ مَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 61, 'هُوَ مِنْ أَبْـلَغِ أَدْوِيَةِ الْكَرْبِ وَالْهمَِّ وَالْغَمِّ، وَأَبْـلَغِ الْوَسَائِلِ إِلَى ا هلِلَّ- سُبْحَانَهُ- فِي قَضَاءِ الَْحوَائِجِ، فَإِنه التهـوْحِيدَ والتنزيه يتضمنان إثبات كل كمال لله، وَسَلْبَ كُلِّ نَـقْصٍ  وَعَيْبٍ وَتَثَِْيلٍ عَنْهُ. وَالِاعْتَِرافُ بِالظُّلْمِ يَـتَضَمهنُ إِيَمانَ الْعَبْدِ بِالشهرْعِ وَالثهـوَابِ وَالْعِقَابِ، وَيُوجِبُ انْكِسَارَهُ وَرُجُوعَهُ إِلَى ا هلِلَّ، وَاسْتِقَالَتَهُ عَثْـرَتَهُ، والاعتراف بعبوديته، وافتقاره إلى ربه، فها هنا أَرْبَـعَةُ أُمُورٍ قَدْ وَقَعَ التهـوَسُّلُ بَِها: التهـوْحِيدُ، وَالتهـنْزِيهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 62, 'وَالْعُبُودِيهةُ وَالِاعْتَِرافُ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 63, 'وَأَمها حَدِيثُ أبي أمامة: اللههُمه إِنِّي أَعُوذُ بِكَ مِنَ الْهمَِّ وَالَْحزَنِ، فَـقَدْ تَضَمهنَ الِاسْتِعَاذَةَ مِنْ ثَاََنِيَةِ أَشْيَاءَ، كُلُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 64, 'اثْـنَـيِْن مِنْـهَا قَرِينَانِ مُزْدَوَجَانِ، فَالَْهمُّ وَالَْحزَنُ أَخَوَانِ، وَالْعَجْزُ وَالْكَسَلُ أَخَوَانِ، وَالُْجبُْن وَالْبُخْلُ أَخَوَانِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 65, 'وَضَلَعُ الدهيْنِ وَغَلَبَةُ الرِّجَالِ أَخَوَانِ، فَإِنه الْمَكْ رُوهَ الْمُؤْلََِ إِذَا وَرَدَ عَلَى الْقَلْبِ، فَإِمها أَنْ يَكُونَ سَبَـبُهُ أَمْرًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 66, 'مَاضِ يًا، فَـيُوجِبُ لَهُ الُْحزْنَ، وَإِنْ كَانَ أَمْرًا مُتَـوَقهـعًا فِي الْمُسْتَـقْبَلِ، أَوْجَبَ الْهمَه، وَتََخلهفُ الْعَبْدِ عَنْ مَصَالِِحهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 67, 'وَتَـفْوِيتُـهَا عَلَيْهِ، إِمها أَنْ يَكُونَ مِنْ عَدَمِ الْقُدْرَةِ وَهُوَ الْعَجْزُ، أَوْ مِنْ عَدَمِ الِْإرَادَةِ وَهُوَ الْكَسَلُ، وَحَبْسُ خَيِْرهِ وَنَـفْعِهِ عَنْ نَـفْسِهِ وَعَنْ بَنِِ جِنْسِهِ، إما', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 68, 'أَنْ يَكُونَ مَنَعَ نَـفْعَهُ بِبَدَنِهِ، فَـهُوَ الُْجبُْن، أَوْ بَِمالِهِ، فَـهُوَ الْبُخْلُ، وَقَـهْرُ النهاسِ لَهُ إِمها بَِحقٍّ، فَـهُوَ ضَلَعُ الدهيْنِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 69, 'أَوْ بِبَاطِلٍ فَـهُوَ غَلَبَةُ الرِّجَالِ، فَـقَدْ تَضَمهنَ الَْحدِيثُ الِاسْتِعَاذَةَ مِنْ كُلِّ شَرٍّ، وَأَمها تَثَِْيُر الِاسْتِغْفَارِ فِي دَفْعِ الَْهمِّ وَالْغَمِّ وَالضِّيقِ، فَلِمَا اشْتَـرَكَ فِي الْعِلْمِ بِهِ أَهْلُ الْمِلَلِ وَعُقَلَاءُ كُلِّ أُمهةٍ أَنه الْمَعَاصِيَ وَالْفَسَادَ تُوجِبُ الَْهمه وَالْغَمه، وَالَْخوْفَ وَالُْحزْنَ، وَضِ يقَ الصهدْرِ، وَأَمْرَاضَ الْقَلْبِ، حَ هتى إِنه أَهْلَهَا إِذَا قَضَوْا مِنْـهَا أَوْطَارَهُمْ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 70, 'وَسَئِمَتْـهَا نَـفُوسُهُمُ، ارْتَكَبُوهَا دَفْـعًا لِمَا يَِجدُونَهُ فِي صُدُورِهِمْ مِنَ الضِّيقِ وَالْهمَِّ وَالْغَمِّ، كَمَا قَالَ شَيْخُ الْفُسُوقِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 71, 'وَكَأْسٍ شَرِبْتُ عَلَى لَذهةٍ ... وَأُخْ رَى تَدَاوَيْتُ مِنْـهَا بَِها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 72, 'وَإِذَا كَانَ هَذَا تَثَِْيَر الذُّنُوبِ وَالْآثَمَِ فِي الْقُلُوبِ، فَلَا دَوَاءَ لََها إِهلا التهـوْبَةُ وَالِاسْتِغْفَارُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 73, 'وَأَمها الصهلَاةُ، فَشَأْنُـهَا فِي تَـفْرِيحِ الْقَلْبِ وَتَـقْوِيتِهِ، وَشَرْحِهِ وَابْتِهَاجِهِ وَلَذهتِهِ أَكْ بَـرُ شَأْنٍ وَفِيهَا مِنَ اتِّصَالِ الْقَلْبِ وَالرُّوحِ بِا هلِلَّ، وَقُـرْبِهِ وَالتهـنَـعُّمِ بِذِكْرِهِ، وَالِابْتِهَاجِ بُِمنَاجَاتِهِ، وَالْوُقُوفِ بَـيَْن يَدَ يْهِ، وَاسْتِعْمَالِ جَِيَعِ الْبَدَنِ وَقُـوَاهُ وَآلَاتِهِ فِي عُبُودِيهتِهِ، وَإِعْطَاءِ كُلِّ عُضْوٍ حَظههُ مِنْـهَا، وَاشْتِغَالِهِ عَنِ التهـعَلُّقِ بِالَْخلْقِ وَمُلَابَسَتِهِمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 74, 'وَمُاَُوَرَاتِِهمْ، وَانِْذَْابِ قُـوَى قَـلْبِهِ وَجَوَارِحِهِ إِلَى رَبِّهِ وَفَاطِرِهِ، وَرَاحَتِهِ مِنْ عَدُوِّهِ حَالَةَ الصهلَاةِ مَا صَارَتْ  بِهِ مِنْ أَكْ بََِ الَْأدْوِيَةِ وَالْمُفَرِّحَاتِ وَالَْأغْذِيَةِ الهتِي لَا تُلَائِمُ إِهلا الْقُلُوبَ الصهحِيحَةَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 75, 'وَأَمها الْقُلُوبُ الْعَلِيلَةُ، فَهِيَ كَالَْأبْدَانِ لَا تُـنَاسِبُـهَا إِهلا الَْأغْذِيَةُ الْفَاضِلَةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 76, 'فَالصهلَاةُ مِنْ أَكْ بََِ الْعَوْنِ عَلَى تَصَِْيلِ مَصَالِحِ الدُّنْـيَا وَالْآخِرَةِ، وَدَفْعِ مَفَاسِدِ الدُّنْـيَا وَالْآخِرَةِ، وَهِيَ مَنْـهَاةٌ عَنِ الِْإِْ م، وَدَافِعَةٌ لَِأدْوَاءِ الْقُلُوبِ، وَمَطْرَدَةٌ لِلدهاءِ عَنِ الَْجسَدِ، وَمُنَـوِّرَةٌ لِلْقَلْبِ ، وَمُبَـيِّضَةٌ لِلْوَجْهِ، وَمُنَشِّ طَةٌ لِلْجَوَارِحِ وَالنهـفْسِ ، وجالية لِلرِّزْقِ، وَدَافِعَةٌ لِلظُّلْمِ، وَنَاصِ رَةٌ لِلْمَظْلُومِ، وَقَامِعَةٌ لَِأخْلَاطِ الشههَوَاتِ، وَحَافِظَةٌ لِلنِّعْمَةِ، وَدَافِعَةٌ لِلنِّقْمَةِ، وَمُنْزِلَةٌ لِلهرحْةَِْ، وَكَاشِفَةٌ لِلْغُمهةِ، وَنَافِعَةٌ مِنْ كَثِيٍر مِنْ أَوْجَاعِ الْبَطْنِ. وَقَدْ رَوَى ابْنُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 77, 'مَاجَهْ فِي «سُنَنِهِ» مِنْ حَدِيثِ ماَهد، عَنْ أَبِي هُرَيْـرَةَ قَالَ: رَآنِي رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَأَنَا نَائِمٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 78, 'أَشْكُو مِنْ وَجَعِ بَطْنِِ، فَـقَالَ لِِ: «يَا أَبَا هُرَيْـرَةَ أَشِكَمَتْ دَرْدْ؟» قَالَ: قُـلْتُ : نَـعَمْ يَا رَسُولَ ا هلِلَّ، قَالَ: «قُمْ فَصَلِّ، فَإِنه فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 79, 'الصهلَاةِ شِفَاءً» »7« . وَقَدْ رُوِيَ هَذَا الَْحدِيثُ مَوْقُوفًا عَلَى أَبِي هُرَيْـرَةَ، وَأَنههُ هُوَ الهذِي قَالَ ذَلِكَ لمجاهد، وَهُوَ أَشْبَهُ. وَمَعْنَى هَذِهِ اللهفْظَةِ بِالْفَارِسِيِّ: أَيُوجِعُكَ بَطْنُكَ ؟.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 80, 'فَإِنْ لََْ يَـنْشَرِحْ صَدْرُ زِنْدِيقِ الَْأطِبهاءِ بَِهذَا الْعِلَاجِ، فَـيُخَاطَبَ بِصِنَاعَةِ الطِّبِّ ، وَيُـقَالَ لَهُ: الصهلَاةُ رِيَاضَةُ النهـفْسِ وَالْبَدَنِ جَِيَعًا، إذا كَانَتْ تَشْتَمِلُ عَلَى حَرَكَاتٍ وَأَوْضَاعٍ مُْختَلِفَةٍ مِنَ الِانْتِصَابِ، وَالرُّكُوعِ ، وَالسُّجُودِ، وَالتهـوَرُّكِ، وَالِانْتِقَالَاتِ وَغَيِْرهَا مِنَ الَْأوْضَاعِ  الهتِي يَـتَحَ هركُ مَعَهَا أَكْ ثَـرُ الْمَفَاصِلِ، وَيَـنْـغَمِزُ مَعَهَا أَكْ ثَـرُ الَْأعْضَاءِ الْبَاطِنَةِ، كَالْمَعِدَةِ، وَالَْأمْعَاءِ، وَسَائِرِ آلَاتِ النهـفْسِ ، وَالْغِذَاءِ، فَمَا يُـنْكِرُ أَنْ يَكُونَ فِي هَذِهِ الَْحرَكَاتِ تَـقْوِيَةٌ وَتَلَِْيلٌ لِلْمَوَادِّ، وَلَا سِيهمَا بِوَاسِطَةِ قُـهوةِ النهـفْسِ وَانْشِرَاحِهَا فِي الصهلَاةِ، فَـتَـقْوَى الطهبِيعَةُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 81, 'فَـيَـنْدَفِعُ الَْألََُ، وَلَكِنْ دَاءُ الهزنْدَقَةِ وَالِْإعْرَاضِ عَمها جَاءَتْ بِهِ الرُّسُلُ، وَالتهـعَوُّضِ عَنْهُ بِالِْإلَْحادِ دَاءٌ لَيْسَ لَهُ دَوَاءٌ إِهلا نَارٌ تَـلَظهى لَا يَصْلَاهَا إِهلا الَْأشْقَى الهذِي كَذهبَ وَتَـوَهلى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 82, 'وَأَمها تَثَِْيُر الِْجهَادِ فِي دَفْعِ الَْهمِّ وَالْغَمِّ، فَأَمْرٌ مَعْلُومٌ بِالْوِجْدَانِ، فَإِنه النهـفْسَ مَتَى تَـرَكَتْ صَائِلَ الْبَاطِلِ وَصَوْلَتَهُ وَاسْتِيلَاءَهُ، اشْتَده هَهَُُّا وَغَمُّهَا، وَكَرْبُـهَا وَخَوْفُـهَا، فَإِذَا جَاهَدَتْهُ هِلِلَّ أَبْدَلَ ذَلِكَ الَْهمه وَالُْحزْنَ فَـرَحًا وَنَشَاطًا وَقُـهوةً، كَمَا قَالَ تَـعَالَى: قاتِلُوهُمْ يُـعَذِّبْـهُمُ ا هللَُّ بَِأيْدِيكُمْ وَيُْخزِهِمْ وَيَـنْصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَـوْمٍ مُؤْمِنِيَن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 83, 'وَيُذْهِبْ غَيْظَ قُـلُوبِِهمْ »2« . فَلَا شَيْ ءَ أَذْهَبُ لَِجوَى الْقَلْبِ وَغَمِّهِ وَهَِهُِّ وَحُزْنِهِ مِنَ الِْجهَادِ وَا هللَُّ الْمُسْتَـعَانُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 84, 'وَأَمها تَثَِْيُر لَا حَوْلَ وَلَا قُـهوةَ إِهلا بِا هلِلَّ فِي دَفْعِ هَذَا الدهاءِ، فَلِمَا فِيهَا مِنْ كَمَالِ التهـفْوِيضِ وَالتهـبَـرِّي مِنَ الَْحوْلِ وَالْقُهوةِ إِهلا بِهِ، وَتَسْلِيمِ الَْأمْرِ كُلِّهِ لَهُ، وَعَدَمِ مُنَازَعَتِهِ فِي شَيْ ءٍ مِنْهُ، وَعُمُومُ ذَلِكَ لِكُلِّ تَوََُّلٍ مِنْ حَالٍ إِلَى حَالٍ فِي الْعَالََِ الْعُلْوِيِّ وَالسُّفْلِيِّ، وَالْقُهوةِ عَلَى ذَلِكَ التهحَوُّلِ، وَأَنه ذَلِكَ كُلههُ بِا هلِلَّ وَحْدَهُ، فَلَا يَـقُومُ لَِهذِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 85, 'الْكَلِمَةِ شَيْ ءٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 86, 'وَفِي بَـعْضِ الْآثَرَِ: إِنههُ مَا يَـنْزِلُ مَلَكٌ مِنَ السهمَاءِ، وَلَا يَصْعَدُ إِلَيْـهَا إِهلا بِلَا حَوْلَ وَلَا قُـهوةَ إِهلا بِا هلِلَّ، وَلََها تَثَِْيٌر عجيب في طرد الشيطان، والله المستعان.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 87, '(7) رواه ابن ماجه في الطب، والإمام أحدْ. (2) التوبة- -74 75', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الْفَزَعِ وَالَْأرَقِ الْمَانِعِ مِنَ النهـوْمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى الترمذي فِي «جَامِعِهِ» عَنْ بريدة قَالَ: شَكَى خالد إِلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فَـقَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'يَا رَسُولَ ا هلِلَّ! مَا أَنَامُ اللهيْلَ مِنَ الَْأرَقِ، فَـقَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَـقُلِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'اللههُمه رَبه السهمَاوَاتِ السهبْعِ وَمَا أَظَلهتْ ، وَرَبه الَْأرَضِيَن، وَمَا أَقَـلهتْ ، وَرَبه الشهيَاطِيِن وَمَا أَضَلهتْ ، كُنْ لِِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'جَارًا مِنْ شَرِّ خَلْقِكَ كُلِّهِمْ جَِيَعًا أَنْ يَـفْرُطَ عَلَيه أَحَدٌ مِنْـهُمْ، أَوْ يَـبْغِيَ عَلَيه، عَهز جَارُكَ، وَجَله ثَـنَاؤُكَ، وَلَا إِلَهَ غَيْـرُكَ» »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَفِيهِ أَيْضًا: عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ يُـعَلِّمُهُمْ مِنَ الْفَزَعِ : «أَعُوذُ بِكَلِمَاتِ ا هلِلَّ التهامهةِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَزََُاتِ الشهيَاطِيِن، وَأَعُوذُ بِكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'بَنِيهِ. وَمَنْ لََْ يَـعْقِلْ كَتَـبَهُ، فَأَعْلَقَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'رَبِّ أَنْ يَْحضُرُونِ» ، قَالَ: وَكَانَ عَبْدُ ا هلِلَّ بْنُ عَمْرٍو يُـعَلِّمُهُنه مَنْ عَقَلَ مِنْ عَلَيْهِ »2« وَلَا يَْخفَى مُنَاسَبَةُ هَذِهِ الْعُوذَةِ لِعِلَاجِ هذا الداء.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ دَاءِ الَْحرِيقِ وَإِطْفَائِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'يُذْكَرُ عَنْ عَمْرِو بْنِ شُعَيْبٍ عَنْ أَبِيهِ عَنْ جَدِّهِ قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إِذَا رَأَيْـتُمُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الَْحرِيقَ فَكَبِّوَُا، فَإِنه التّكبير يطفئه» »3« . لما كان الحرق سَبَـبُهُ النهارُ، وَهِيَ مَادهةُ الشهيْطَانِ الهتِي خُلِقَ مِنْـهَا، وَكَانَ فِيهِ مِنَ الْفَسَادِ الْعَامِّ مَا يُـنَاسِبُ الشهيْطَانَ بَِمادِّتِهِ وَفِعْلِهِ، كَانَ لِلشهيْطَانِ إِعَانَةٌ عَلَيْهِ. وَتَـنْفِيذٌ لَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَكَانَتِ النهارُ تَطْلُبُ بِطَبْعِهَا الْعُلُهو وَالْفَسَادَ، وَهَذَانِ الَْأمْرَانِ، وَهُاَُ الْعُلُوُّ فِي الأرض والفساد هاُ هدي الشيطان،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(7) أخرجه الترمذي في الدعوات.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(2) أخرجه أبو داود في الطب، والترمذي وأحدْ في المسند، والحاكم. (3) أخرجه ابن السنِ، وابن عدي، وابن عساكر في تاريخه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَإِلَيْهِمَا يَدْعُو، وَبِِهمَا يُـهْلِكُ بَنِِ آدَمَ، فَالنهارُ وَالشهيْطَانُ كُلٌّ مِنْـهُمَا يُرِيدُ الْعُلُهو فِي الَْأرْضِ وَالْفَسَادَ، وَكِبِْيََاءَ الهربِّ - عَهز وَجَله- تَـقْمَعُ الشهيْطَانَ وَفِعْلَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَلَِهذَا كَانَ تَكْ بِيُر ا هلِلَّ- عَهز وَجَله- لَهُ أَثَـرٌ فِي إِطْفَاءِ الَْحرِيقِ، فَإِنه كِبِْيََاءَ ا هلِلَّ- عَهز وَجَله- لَا يَـقُومُ لََها شَيْ ءٌ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'فَإِذَا كَبهـرَ الْمُسْلِمُ رَبههُ، أَثهـرَ تَكْ بِيُرهُ فِي خُُمودِ النهارِ وَخُُمودِ الشهيْطَانِ الهتِي هِيَ مَادهتُهُ، فيطفىء الَْحرِيقَ، وَقَدْ جَ هربْـنَا نَنُْْ وَغَيْـرُنَا هَذَا، فَـوَجَدْنَاهُ كذلك، والله أعلم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي حِفْظِ الصِّحهةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'لَمها كَانَ اعْتِدَالُ الْبَدَنِ وَصِحهتُهُ وَبَـقَاؤُهُ إِهنَما هُوَ بِوَاسِطَةِ الرُّطُوبَةِ الْمُقَاوِمَةِ للحرارة، فالرطوبة مادة،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَالَْحرَارَةُ تُـنْضِجُهَا، وَتَدْفَعُ فَضَلَاتَِها وَتُصْلِحُهَا وَتُـلَطِّفُهَا، وَإِهلا أَفْسَدَتِ الْبَدَنَ وَلََْ يُْمكِنْ قِيَامُهُ، وَكَذَلِكَ الرُّطُوبَةُ هِيَ غِذَاءُ الَْحرَارَةِ، فَـلَوْلَا الرُّطُوبَةُ، لََأحْرَقَتِ الْبَدَنَ وَأَيْـبَسَتْهُ وَأَفْسَدَتْهُ، فَقِوَامُ كُلِّ وَاحِدَةٍ مِنْـهُمَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'بِصَاحِبَتِهَا، وَقِوَامُ الْبَدَنِ بِِهمَا جَِيَعًا، وَكُلٌّ مِنْـهُمَا مَادهةٌ لِلْخُِْ رَى، فَالَْحرَارَةُ مَادهةٌ لِلرُّطُوبَةِ تَفََْظُهَا وَتَنََْـعُهَا مِنَ الْفَسَادِ وَالِاسْتِحَالَةِ، وَالرُّطُوبَةُ مَادهةٌ لِلْحَرَارَةِ تَـغْذُوهَا وَتَمَِْلُهَا، وَمَتَى مَالَتِ احْدَاهُاَُ إِلَى الزِّيَادَةِ عَلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الُْأخْ رَى، حَصَلَ لِمِزَاجِ الْبَدَنِ الِانِْرَْافُ بَِحسَبِ ذَلِكَ ، فَالَْحرَارَةُ دَائِمًا تُلََِّلُ الرُّطُوبَةَ، فَـيَحْ تَاجُ الْبَدَنُ إِلَى مَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'بِهِ يُْخلَفُ عَلَيْهِ مَا حَلهلَتْهُ الَْحرَارَةُ- لِضَرُورَةِ بَـقَائِهِ- وَهُوَ الطهعَامُ وَالشهرَابُ ، وَمَتَى زَادَ عَلَى مِقْدَارِ التهحَلُّلِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'ضَعُفَتِ الَْحرَارَةُ عَنْ تَلَِْيلِ فَضَلَاتِهِ، فَاسْتَحَالَتْ مَوَاده رَدِيئَةً، فَـعَاثَتْ فِي الْبَدَنِ، وَأَفْسَدَتْ ، فَحَصَلَتِ الَْأمْرَاضُ الْمُتَـنَـوِّعَةُ بَِحسَبِ تَـنَـوُّعِ  مَوَادِّهَا وَقَـبُولِ الَْأعْضَاءِ وَاسْتِعْدَادِهَا، وَهَذَا كُلُّهُ مُسْتَـفَادٌ مِنْ قَـوْلِهِ تعالى: وَكُلُوا وَاشْرَبُوا وَلا تُسْرِفُوا »7« ، فَأَرْشَدَ عِبَادَهُ إِلَى إِدْخَالِ مَا يُقِيمُ الْبَدَنَ مِنَ الطهعَامِ وَالشهرَابِ عِوَضَ مَا تَلََهلَ مِنْهُ، وَأَنْ يَكُونَ بِقَدْرِ مَا يَـنْـتَفِعُ بِهِ الْبَدَنُ فِي الْكَمِّيهةِ وَالْكَيْفِيهةِ، فَمَتَى جَاوَزَ ذَلِكَ كَانَ إِسْرَافًا، وَكِلَاهُاَُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'مَانِعٌ مِنَ الصِّحهةِ جَالِبٌ لِلْمَرَضِ ، أَعْنِِ عَدَمَ الَْأكْلِ وَالشُّرْبِ أَوِ الِْإسْرَافَ فِيهِ. (7) الأعراف- .37', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'فَحِفْظُ الصِّحهةِ كُلُّهُ فِي هَاتَـيِْن الْكَلِمَتَـيِْن الِْإلَِهيهـتَـيِْن، وَلَا رَيْبَ أَنه الْبَدَنَ دَائِمًا فِي التهحَلُّلِ وَالِاسْتِخْلَافِ، وَكُلهمَا كَثُـرَ التهحَلُّلُ ضَعُفَتِ الَْحرَارَةُ لِفَنَاءِ مَادهتَِها، فَإِنه كَثْـرَةَ التهحَلُّلِ تُـفْنِِ الرُّطُوبَةَ، وَهِيَ مَادهةُ الَْحرَارَةِ، وَإِذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'ضَعُفَتِ الَْحرَارَةُ، ضَعُفَ الَْهضْمُ، ولا يزال كذلك حتى تفنى الرطوبة، وتنطفىء الَْحرَارَةُ جُلََْةً، فَـيَسْتَكْمِلُ الْعَبْدُ الَْأجَلَ الهذِي كَتَبَ ا هللَُّ لَهُ أَنْ يَصِلَ إِلَيْهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'فَـغَايَةُ عِلَاجِ الِْإنْسَانِ لِنَـفْسِهِ وَلِغَيِْرهِ حِرَاسَةُ الْبَدَنِ إِلَى أَنْ يَصِلَ إِلَى هَذِهِ الَْحالَةِ، لَا أَنههُ يَسْتَـلْزِمُ بَـقَاءَ الَْحرَارَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَالرُّطُوبَةِ اللهتَـيِْن بَـقَاءُ الشهبَابِ وَالصِّحهةِ وَالْقُهوةِ بِِهمَا، فَإِنه هَذَا مِمها لََْ يَْحصُلْ لِبَشَرٍ فِي هَذِهِ الدهارِ، وَإِهنَما غَايَةُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'الطهبِيبِ أَنْ يَْحمِيَ الرُّطُوبَةَ عَنْ مُفْسِدَاتَِها مِنَ الْعُفُونَةِ وغيرها، وَيَْحمِيَ الَْحرَارَةَ عَنْ مُضْعِفَاتَِها، وَيَـعْدِلَ بَـيْـنَـهُمَا بِالْعَدْلِ فِي التهدْبِيِر الهذِي بِهِ قَامَ بَدَنُ الِْإنْسَانِ، كَمَا أَنه بِهِ قَامَتِ السهمَاوَاتُ وَالَْأرْضُ وَسَائِرُ الْمَخْ لُوقَاتِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'إِهنَما قِوَامُهَا بِالْعَدْلِ، وَمَنْ تَمََهلَ هَدْيَ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَجَدَهُ أَفْضَلَ هَدْيٍ يُْمكِنُ حِفْظُ الصِّحهةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'بِهِ، فَإِنه حِفْظَهَا مَوْقُوفٌ عَلَى حُسْنِ تَدْبِيِر الْمَطْعَمِ وَالْمَشْرَبِ، وَالْمَلْبَسِ وَالْمَسْكَنِ، وَالَْهوَاءِ وَالنهـوْمِ، وَالْيَـقَظَةِ وَالَْحرَكَةِ، وَالسُّكُونِ وَالْمَنْكَحِ، وَالِاسْتِفْرَاغِ وَالِاحْتِبَاسِ ، فَإِذَا حَصَلَتْ هَذِهِ عَلَى الْوَجْ هِ الْمُعْتَدِلِ الْمُوَافِقِ الْمُلَائِمِ لِلْبَدَنِ وَالْبَـلَدِ وَالسِّ نِّ وَالْعَادَةِ، كَانَ أَقْـرَبَ إِلَى دَوَامِ الصِّحهةِ أَوْ غَلَبَتِهَا إِلَى انْقِضَاءِ الَْأجَلِ. وَلَمها كَانَتِ الصِّحهةُ وَالْعَافِيَةُ مِنْ أَجَلِّ نِعَمِ ا هلِلَّ عَلَى عَبْدِهِ، وَأَجْزَلِ عَطَايَاهُ، وَأَوْفَرِ مِنَحِهِ، بَلِ الْعَافِيَةُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'الْمُطْلَقَةُ أَجَلُّ النِّعَمِ عَلَى الِْإطْلَاقِ، فَحَقِيقٌ لِمَنْ رُزِقَ حَظًّا مِنَ التهـوْفِيقِ مُرَاعَاتُـهَا وَحِفْظُهَا وَحِاَْيَـتُـهَا عَمها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'يُضَادُّهَا، وَقَدْ رَوَى الْبُخَارِيُّ فِي «صَحِيحِهِ» مِنْ حَدِيثِ ابْنِ عَبهاسٍ ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيٌر مِنَ النهاسِ : الصِّحهةُ وَالْفَرَاغُ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَفِي الترمذي وَغَيِْرهِ مِنْ حَدِيثِ عبيد الله بن مصُن الأنصاري، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَنْ أَصْبَحَ مُعَافًى فِي جَسَدِهِ، آمِنًا فِي سِرْبِهِ، عِنْدَهُ قُوتُ يَـوْمِهِ، فَكَأَهنَما حِيزَتْ له الدّنيا» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, '(7) أخرجه البخاري في الرقاق، والترمذي وابن ماجه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, '(2) أخرجه الترمذي وابن ماجه في الزهد، والبخاري في الأدب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَفِي الترمذي أَيْضًا مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وسلم أنه قال: «أوّل ما يسأل الْعَبْدُ يَـوْمَ الْقِيَامَةِ مِنَ النهعِيمِ، أَنْ يُـقَالَ لَهُ: أَلََْ نُصِحه لَكَ جِسْمَكَ ، وَنَـرْوِكَ مِنَ الماء البارد» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'ومن ها هنا قَالَ مَنْ قَالَ مِنَ السهلَفِ فِي قَـوْلِهِ تعالى: ُ مه لَتُسْئَـلُنه يَـوْمَئِذٍ عَنِ النهعِيمِ، »2« ، قَالَ: عَنِ الصِّحهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَفِي «مُسْنَدِ الِْإمَامِ أَحْدََْ» أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ للعباس: «يَا عباس، يَا عَمه رَسُولِ ا هلِلَّ! سَلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'ا هللََّ الْعَافِيَةَ فِي الدُّنْـيَا وَالْآخِرَةِ» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَفِيهِ عَنْ أَبِي بَكْرٍ الصِّدِّيقِ، قَالَ: سَِمعْتُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـقُولُ: «سَلُوا ا هللََّ الْيَقِيَن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'وَالْمُعَافَاةَ، فَمَا أُوتَِي أَحَدٌ بَـعْدَ الْيَقِيِن خَيْـرًا مِنَ الْعَافِيَةِ» »4« . فَجَمَعَ بَـيَْن عَافِيَـتَِي الدِّينِ وَالدُّنْـيَا، وَلَا يَتِمُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'صَلَاحُ الْعَبْدِ فِي الدهارَيْنِ إِهلا بِالْيَقِيِن وَالْعَافِيَةِ، فَالْيَقِيُن يَدْفَعُ عَنْهُ عقوبات الآخرة، والآخرة تَدْفَعُ عَنْهُ أَمْرَاضَ الدُّنْـيَا فِي قَـلْبِهِ وَبَدَنِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَفِي «سُنَنِ النهسَائِيِّ» مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ يَـرْفَـعُهُ: «سَلُوا ا هللََّ الْعَفْوَ وَالْعَافِيَةَ وَالْمُعَافَاةَ، فَمَا أُوتَِي أَحَدٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'بَـعْدَ يَقِيٍن خَيْـرًا مِنْ مُعَافَاةٍ» »5« ، وَهَذِهِ الثهلَاثَةُ تَـتَضَمهنُ إِزَالَةَ الشُّرُورِ الْمَاضِيَةِ بِالْعَفْوِ، وَالَْحاضِ رَةِ بِالْعَافِيَةِ، وَالْمُسْتَـقْبَـلَةِ بِالْمُعَافَاةِ، فَإِنهـهَا تَـتَضَمهنُ الْمُدَاوَمَةَ وَالِاسْتِمْرَارَ عَلَى الْعَافِيَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'وَفِي الترمذي مَرْفُوعًا: «مَا سُئِلَ ا هللَُّ شَيْـئًا أَحَبه إِلَيْهِ مِنَ الْعَافِيَةِ» »1« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَقَالَ عَبْدُ الهرحْنَِْ بْنُ أَبِي لَيْـلَى: عَنْ أَبِي الدهرْدَاءِ، قُـلْتُ : يَا رَسُولَ ا هلِلَّ! لََأنْ أُعَافَى فَأَشْكُرَ أَحَبُّ إِلَهِ مِنْ أَنْ أُبْـتَـلَى فَأَصْبََِ، فَـقَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «ورسول الله يحبّ معك العافية» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, '(7) أخرجه الترمذي في التفسير. (2) التكاثر- .9', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, '(3) وأخرجه الترمذي في الدعوات. (4) وأخرجه ابن ماجه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, '(5) أخرجه النسائي في عمل اليوم والليلة. (1) أخرجه الترمذي في الدعوات.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'وَيُذْكَرُ عَنِ ابْنِ عَبهاسٍ أَنه أَعْرَابِيًّا جَاءَ إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وسلم، فَـقَالَ لَهُ: مَا أَسْأَلُ ا هللََّ بَـعْدَ الصهلَوَاتِ الَْخمْسِ ؟ فَـقَالَ: «سَلِ ا هللََّ الْعَافِيَةَ» ، فَأَعَادَ عَلَيْهِ، فَـقَالَ لَهُ فِي الثهالِثَةِ: «سَلِ ا هللََّ الْعَافِيَةَ فِي الدُّنْـيَا وَالْآخِرَةِ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'وَإِذَا كَانَ هَذَا شَأْنَ الْعَافِيَةِ وَالصِّحهةِ، فَـنَذْكُرُ مِنْ هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي مُرَاعَاةِ هَذِهِ الُْأمُورِ مَا يَـتَـبَـهيُن لِمَنْ نَظَرَ فِيهِ أَنههُ أَكْمَلُ هَدْيٍ عَلَى الِْإطْلَاقِ يَـنَالُ بِهِ حِفْظَ صِحهةِ الْبَدَنِ وَالْقَلْبِ، وَحَيَاةِ الدُّنْـيَا وَالْآخِرَةِ، وَا هللَُّ الْمُسْتَـعَانُ، وَعَلَيْهِ التُّكْلَانُ، وَلَا حَوْلَ وَلَا قُـهوةَ إِهلا بِا هلِلَّ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'فَأَمها الْمَطْعَمُ وَالْمَشْرَبُ ، فَـلَمْ يَكُنْ مِنْ عَادَتِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ حَبْسُ النهـفْسِ عَلَى نَـوْعٍ وَاحِدٍ مِنَ الَْأغْذِيَةِ لَا يَـتَـعَدهاهُ إِلَى مَا سِوَاهُ، فَإِنه ذَلِكَ يَضُرُّ بِالطهبِيعَةِ جِدًّا، وَقَدْ يَـتَـعَذهرُ عَلَيْـهَا أَحْ يَانًا، فَإِنْ لََْ يَـتَـنَاوَلْ غَيْـرَهُ، ضَعُفَ أَوْ هَلَكَ ، وَإِنْ تَـنَاوَلَ غَيْـرَهُ، لََْ تَـقْبَـلْهُ الطهبِيعَةُ، وَاسْتَضَ هر بِهِ، فَـقَصَرَهَا عَلَى نَـوْعٍ وَاحِدٍ دَائِمًا- وَلَوْ أَنههُ أَفْضَلُ الَْأغْذِيَةِ- خَطَرٌ مُضِرٌّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'بَلْ كَانَ كََُْلُ مَا جَرَتْ عَادَةُ أَهْلِ بَـلَدِهِ بَِأكْلِهِ مِنَ اللهحْمِ، وَالْفَاكِهَةِ وَالُْخبْزِ، وَالتهمْرِ، وَغَيِْرهِ مِمها ذكََرْنَاهُ فِي هَدْيِهِ فِي الْمَأْكُولِ، فَـعَلَيْكَ بُِمرَاجَعَتِهِ هُنَاكَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَإِذَا كَانَ فِي أَحَدِ الطهعَامَيِْن كَيْفِهيةٌ تَْتََاجُ إِلَى كَسْرٍ وَتَـعْدِيلٍ، كَسَرَهَا وَعَدَلََها بِضِدِّهَا إِنْ أَمْكَنَ، كَتَـعْدِيلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'حَرَارَةِ الرُّطَبِ بِالْبِطِّيخِ، وَإِنْ لََْ يَِجدْ ذَلِكَ ، تَـنَاوَلَهُ عَلَى حَاجَةٍ وَدَاعِيَةٍ مِنَ النهـفْسِ مِنْ غَيِْر إِسْرَافٍ، فَلَا تَـتَضَ هررُ بِهِ الطهبِيعَةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَكَانَ إِذَا عَافَتْ نَـفْسُهُ الطهعَامَ لََْ كََُْلْهُ، وَلََْ يَُحمِّلْهَا إِهياهُ عَلَى كُرْهٍ وَهَذَا أَصْلٌ عَظِيمٌ فِي حِفْظِ الصِّحهةِ، فَمَتَى أَكَلَ الِْإنْسَانُ مَا تَـعَافُهُ نَـفْسُهُ، وَلَا يَشْتَهِيهِ، كَانَ تَضَرُّرُهُ بِهِ أَكْثَـرَ مِنِ انْتِفَاعِهِ. قَالَ أَبُو هُرَيْـرَةَ» : مَا عَابَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ طَعَامًا قط، إن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(7) أخرجه البخاري ومسلم وأبو داود والترمذي وأحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'اشْتَـهَاهُ أَكَلَهُ، وَإِهلا تَـرَكَهُ، وَلََْ كََُْلْ مِنْهُ. وَلَمها قُدِّمَ إِلَيْهِ الضهبُّ الْمَشْوِيُّ لََْ كََُْلْ مِنْهُ، فَقِيلَ لَهُ: أَهُوَ حَرَامٌ؟ قَالَ: «لَا، وَلَكِنْ لََْ يَكُنْ بَِأرْضِ قَـوْمِي، فَأَجِدُنِي أَعَافُهُ» »7« . فَـرَاعَى عَادَتَهُ وَشَهْوَتَهُ، فَـلَمها لََْ يَكُنْ يَـعْتَادُ أَكْ لَهُ بَِأرْضِهِ، وَكَانَتْ نَـفْسُهُ لَا تَشْتَهِيهِ، أَمْسَكَ عَنْهُ، وَلََْ يَْمنَعْ مِنْ أَكْ لِهِ مَنْ يَشْتَهِيهِ، وَمَنْ عَادَتُهُ أَكْ لُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَكَانَ يُِحبُّ اللهحْمَ، وَأَحَبُّهُ إِلَيْهِ الذِّرَاعُ، وَمُقَدهمُ الشهاةِ، وَلِذَلِكَ سُمه فِيهِ، وَفِي «الصهحِيحَيِْن» : أُتَِي رَسُولُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بِلَحْمٍ، فَـرُفِعَ إِلَيْهِ الذِّرَاعُ، وَكَانَتْ تُـعْجِبُهُ »2« . وَذكََرَ أبو عبيدة وَغَيْـرُهُ عَنْ ضباعة بنت الزبير، أَنهـهَا ذَبََحتْ فِي بَـيْتِهَا شَاةً.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'فَأَرْسَلَ إِلَيْـهَا رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنْ أَطْعِمِينَا مِنْ شَاتِكُمْ، فَـقَالَتْ لِلهرسُولِ: ما بقي عندنا إلا الرقبة، وإني لأستحي أَنْ أُرْسِلَ بَِها إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَـرَجَعَ الهرسُولُ فَأَخْبَـرَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'فَـقَالَ: «ارْجِعْ إِلَيْـهَا فَـقُلْ لََها: أَرْسِلِي بَِها، فَإِنهـهَا هَادِيَةُ الشهاةِ وَأَقْـرَبُ إِلَى الَْخيِْر، وَأَبْـعَدُهَا مِنَ الَْأذَى» »3«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَلَا رَيْبَ أَنه أَخَفه لَْحمِ الشهاةِ لَْحمُ الهرقَـبَةِ، وَلَْحمُ الذِّرَاعِ وَالْعَضُدِ، وَهُوَ أَخَفُّ عَلَى الْمَعِدَ ةِ، وَأَسْرَعُ انِْهضَامًا، وَفِي هَذَا مُرَاعَاةُ الَْأغْذِيَةِ الهتِي تَمََْعُ ثَلَاثَةَ أَوْصَافٍ. أَحَدُهَا: كَثْـرَةُ نَـفْعِهَا وَتَثَِْيِرهَا فِي الْقُوَى الثهانِي: خِهفتُـهَا عَلَى الْمَعِدَةِ، وَعَدَمُ ثِقَلِهَا عَلَيْـهَا. الثهالِثُ : سُرْعَةُ هَضْمِهَا، وَهَذَا أَفْضَلُ مَا يَكُونُ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'الْغِذَاءِ، وَالتهـغَذِّي بِالْيَسِيِر مِنْ هَذَا أَنْـفَعُ مِنَ الْكَثِيِر مِنْ غَيِْرهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَكَانَ يُِحبُّ الَْحلْوَاءَ وَالْعَسَلَ، وَهَذِهِ الثهلَاثَةُ- أَعْنِِ: اللهحْمَ وَالْعَسَلَ وَالَْحلْوَاءَ- مِنْ أَفْضَلِ الَْأغْذِيَةِ، وَأَنْـفَعِهَا لِلْبَدَنِ وَالْكَبِدِ وَالَْأعْضَاءِ، وَلِلِاغْتِذَاءِ بَِها نَـفْعٌ عَظِيمٌ فِي حِفْظِ الصِّحهةِ وَالْقُهوةِ، وَلَا يَـنْفِرُ منها إلا من به علة وآفة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, '(7) أخرجه البخاري في الأطعمة، ومسلم في الصيد. (2) أخرجه البخاري في الأنبياء، ومسلم في الإيمان. (3) أخرجه أحدْ والنسائي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَكَانَ كََُْلُ الُْخبْـزَ مَأْدُومًا مَا وَجَدَ لَهُ إِدَامًا، فَـتَارَةً دََِْمُهُ بِاللهحْمِ وَيَـقُولُ: «هُوَ سَيِّدُ طَعَامِ أَهْلِ الدُّنْـيَا وَالْآخِرَةِ» . رَوَاهُ ابْنُ مَاجَهْ وَغَيْـرُهُ »7« . وَتَارَةً بِالْبِطِّيخِ، وَتَارَةً بِالتهمْرِ، فَإِنههُ وَضَعَ تَرََْةً عَلَى كِسْرَةِ شَعِيٍر، وَقَالَ: هَذَا إِدَامُ هَذِهِ» »2« . وَفِي هَذَا مِنْ تَدْبِيِر الْغِذَاءِ أَنه خُبْـزَ الشهعِيِر بَارِدٌ يَابِسٌ ، وَالتهمْرَ حَارٌّ رَطْبٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'عَلَى أَصَحِّ الْقَوْلَيِْن، فَأَدْمُ خُبْزِ الشهعِيِر بِهِ مِنْ أَحْسَنِ التهدْبِيِر، لَا سِيهمَا لِمَنْ تِلْكَ عَادَتُـهُمْ، كَأَهْلِ الْمَدِينَةِ، وَتَارَةً بِالَْخلِّ، وَيَـقُولُ: «نِعْمَ الِْإدَامُ الَْخلُّ» ، وَهَذَا ثَـنَاءٌ عَلَيْهِ بَِحسَبِ مُقْتَضَى الَْحالِ الَْحاضِرِ، لَا تَـفْضِيلٌ لَهُ عَلَى غَيِْرهِ،كَمَا يَظُنُّ الُْج ههالُ، وَسَبَبُ الَْحدِيثِ أَنههُ دَخَلَ عَلَى أَهْلِهِ يَـوْمًا، فَـقَدهمُوا لَهُ خُبْـزًا، فَـقَالَ: «هَلْ عِنْدَكُمْ مِنْ إِدَامٍ؟» قَالُوا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'مَا عِنْدَنَا إِهلا خَلٌّ، فَـقَالَ: «نِعْمَ الِْإدَامُ الَْخلُّ» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَالْمَقْصُودُ: أَنه أَكْلَ الُْخبْزِ مَأْدُومًا مِنْ أَسْبَابِ حِفْظِ الصِّحهةِ، خِِلَِافِ الِاقْتِصَارِ عَلَى أَحَدِهِاَُ وَحْدَهُ. وَسُِّميَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'الُْأدْمُ أُدْمًا: لِِإصْلَاحِهِ الُْخبْـزَ، وَجَعْلِهِ مُلَائِمًا لِِحفْظِ الصِّحهةِ. وَمِنْهُ قَـوْلُهُ فِي إِبَاحَتِهِ لِلْخَاطِبِ النهظَرَ: إِنههُ أَحْ رَى أَنْ يُـؤْدَمَ بَـيْـنَـهُمَا، أَيْ أَقْـرَبُ إِلَى الِالْتِئَامِ وَالْمُوَافَـقَةِ، فَإِنه الهزوْجَ يَدْخُلُ عَلَى بَصِيَرةٍ، فَلَا يَـنْدَمُ. وَكَانَ كََُْلُ مِنْ فَاكِهَةِ بَـلَدِهِ عِنْدَ مَِيَئِهَا، وَلَا يَْحتَمِي عَنْـهَا، وَهَذَا أَيْضًا مِنْ أَكْبََِ أَسْبَابِ حِفْظِ الصِّحهةِ، فَإِنه ا هللََّ سُبْحَانَهُ بِِحكْمَتِهِ جَعَلَ فِي كُلِّ بَـلْدَةٍ مِنَ الْفَاكِهَةِ مَا يَـنْـتَفِعُ بِهِ أَهْلُهَا فِي وَقْتِهِ، فَـيَكُونُ تَـنَاوُلُهُ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'أَسْبَابِ صِحهتِهِمْ وَعَافِيَتِهِمْ، وَيُـغْنِِ عَنْ كَثِيٍر مِنَ الَْأدْوِيَةِ، وَقَله مَنِ احْتَمَى عَنْ فَاكِهَةِ بَـلَدِهِ خَشْيَةَ السهقَمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'إِهلا وَهُوَ مِنْ أَسْقَمِ النهاسِ جِسْمًا، وَأَبْـعَدِهِمْ مِنَ الصِّحهةِ وَالْقُهوةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَمَا فِي تِلْكَ الْفَاكِهَةِ مِنَ الرُّطُوبَاتِ، فَحَرَارَةُ الْفَصْلِ وَالَْأرْضِ ، وَحَرَارَةُ الْمَعِدَةِ تُـنْضِجُهَا وَتَدْفَعُ شَ هرهَا إِذَا لََْ يُسْرِفْ فِي تَـنَاوُلَِها، وَلََْ يَُحمِّلْ مِنْـهَا الطهبِيعَةَ فَـوْقَ مَا تَتََْمِلُهُ، وَلََْ يُـفْسِدْ بَِها الْغِذَاءَ قَـبْلَ هَضْمِهِ، وَلَا أفسدها بشرب الماء عليها، وتناول', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, '(7) أخرجه ابن ماجة في الأطعمة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, '(2) أخرجه أبو داود والترمذي في الشمائل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, '(3) أخرجه مسلم في الأشربة، وأبو داود، والترمذي، وابن ماجه، والنسائي في الإيمان. والإمام أحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'الْغِذَاءِ بَـعْدَ التهحَلِّي مِنْـهَا، فَإِنه الْقُولَنْجَ كَثِيًرا مَا يَْحدُثُ عِنْدَ ذَلِكَ ، فَمَنْ أَكَلَ مِنْـهَا مَا يَـنْـبَغِي فِي الْوَقْتِ الهذِي يَـنْـبَغِي عَلَى الْوَجْهِ الهذِي يَـنْـبَغِي، كَانَتْ لَهُ دَوَاءً نَافِعًا.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي هَيْـئَةِ الُْجلُوسِ لِلْكَِْلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'صَحه عَنْهُ أَنههُ قَالَ: «لَا آكُلُ مُتهكِئًا »7« » ، وَقَالَ: «إِهنَما أَجْلِسُ كَمَا يَْجلِسُ الْعَبْدُ، وَآكُلُ كَمَا كََُْلُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الْعَبْدُ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَرَوَى ابْنُ مَاجَهْ فِي «سُنَنِهِ» أَنههُ نَـهَى أَنْ كََُْلَ الهرجُلُ وَهُوَ مُنْـبَطِحٌ عَلَى وَجْ هِهِ »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَقَدْ فُسِّ رَ الِاتِّكَاءُ بِالتهـرَبُّعِ، وَفُسِّ رَ بِالِاتِّكَاءِ عَلَى الشهيْ ءِ، وَهُوَ الِاعْتِمَادُ عَلَيْهِ، وَفُسِّ رَ بِالِاتِّكَاءِ عَلَى الَْجنْبِ. وَالَْأنْـوَاعُ الثهلَاثَةُ مِنَ الِاتِّكَاءِ، فَـنَـوْعٌ مِنْـهَا يَضُرُّ بِالْآكِلِ، وَهُوَ الِاتِّكَاءُ عَلَى الَْجنْبِ، فَإِنههُ يَْمنَعُ مَرََْى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الطهعَامِ الطهبِيعِيِّ عَنْ هَيْـئَتِهِ، وَيَـعُوقُهُ عَنْ سُرْعَةِ نُـفُوذِهِ إِلَى الْمَعِدَةِ، وَيَضْغَطُ الْمَعِدَةَ، فَلَا يُسْتَحْكَمُ فَـتْحُهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'لِلْغِذَاءِ، وَأَيْضًا فَإِنهـهَا تَيَِلُ وَلَا تَـبْـقَى مُنْـتَصِبَةً، فَلَا يَصِلُ الْغِذَاءُ إِلَيْـهَا بِسُهُولَةٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَأَمها النهـوْعَانِ الْآخَرَانِ : فَمِنْ جُلُوسِ الَْجبَابِرَةِ الْمُنَافِي لِلْعُبُودِيهةِ، وَلَِهذَا قَالَ: «آكُلُ كَمَا كََُْلُ الْعَبْدُ» وَكَانَ كََُْلُ وَهُوَ مُقْعٍ »4« ، وَيُذْكَرُ عَنْهُ أَنههُ كَانَ يَْجلِسُ لِلْكَِْلِ مُتَـوَرّكًِا عَلَى ركُْبَـتَـيْهِ، وَيَضَعُ بَطْنَ قَدَمِهِ الْيُسْرَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'عَلَى ظَهْرِ قَدَمِهِ الْيُمْنَى تَـوَاضُعًا لِرَبِّهِ عَهز وَجَله، وَأَدَبًا بَـيَْن يَدَيْهِ، وَاحْتَِرامًا لِلطهعَامِ وَلِلْمُؤَاكِلِ، فَـهَذِهِ الَْهيْـئَةُ أَنْـفَعُ هَيْـئَاتِ الَْأكْلِ وَأَفْضَلُهَا، لَِأنه الَْأعْضَاءَ كُلههَا تَكُونُ عَلَى وَضْعِهَا الطهبِيعِيِّ الهذِي خَلَقَهَا ا هللَُّ سُبْحَانَهُ عَلَيْهِ مَعَ مَا فِيهَا مِنَ الْهيَْـئَةِ الَْأدَبِيهةِ، وَأَجْ وَدُ مَا اغْتَذَى الِْإنْسَانُ إِذَا كَانَتْ أَعْضَاؤُهُ عَلَى وَضْعِهَا الطهبِيعِيِّ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَلَا يَكُونُ كَذَلِكَ إِهلا إذا كان الإنسان منتصبا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, '(7) أخرجه البخاري في الأطعمة، والإمام أحدْ، وأبو داود، وابن ماجة. (2) أخرجه أبو الشيخ من حديث عائشة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, '(3) أخرجه ابن ماجة في الأطعمة، وأبو داود. (4) أخرجه مسلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'الِانْتِصَابَ الطهبِيعِيِّ، وَأَرْدَأُ الِْجلْسَاتِ لِلْكَِْلِ الِاتِّكَاءُ عَلَى الَْجنْبِ، لِمَا تَـقَدهمَ مِنْ أَنه الْمَرِيءَ، وَأَعْضَاءَ الِازْدِرَادِ تَضِيقُ عِنْدَ هَذِهِ الَْهيْـئَةِ، وَالْمَعِدَ ةُ لَا تَـبْـقَى عَلَى وَضْعِهَا الطهبِيعِيِّ، لَِأنهـهَا تَـنْـعَصِرُ مِمها يَلِي الْبَطْنَ بِالَْأرْضِ ، وَمِمها يَلِي الظههْرَ بِالِْحجَابِ الْفَاصِلِ بَـيَْن آلَاتِ الْغِذَاءِ، وَآلَاتِ التهـنَـفُّسِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَإِنْ كَانَ الْمُرَادُ بِالِاتِّكَاءِ الِاعْتِمَادَ عَلَى الْوَسَائِدِ وَالْوَطَاءِ الهذِي تَتََْ الَْجالِسِ ، فَـيَكُونُ الْمَعْنَى أَنِّي إِذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'أَكَلْتُ لََْ أَقْـعُدْ مُتِّكِئًا عَلَى الَْأوْطِيَةِ وَالْوَسَائِدِ، كَفِعْلِ الَْجبَابِرَةِ، وَمَنْ يُرِيدُ الِْإكْ ثَارَ مِنَ الطهعَامِ، لَكِنِِّ آكُلُ بُـلْغَةًكَمَا كََُْلُ الْعَبْدُ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَكَانَ كََُْلُ بَِأصَابِعِهِ الثهلَاثِ، وَهَذَا أَنْـفَعُ مَا يَكُونُ مِنَ الَْأكَلَاتِ، فَإِنه الَْأكْلَ بُِأصْبُعٍ أَوْ أصبعين لا يستلذّ به الآكل، ولا يمر به، وَلَا يُشْبِعُهُ إِهلا بَـعْدَ طُولٍ، وَلَا تَـفْرَحُ آلَاتُ الطهعَامِ وَالْمَعِدَةُ بَِما يَـنَالَُها فِي كُلِّ أَكْلَةٍ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'فَـتَأْخُذُهَا عَلَى إِغْمَاضٍ ، كَمَا خََُْذُ الهرجُلُ حَقههُ حَبهةً أَوْ حَبهـتَـيِْن أَوْ نَوَْْ ذَلِكَ ، فَلَا يَـلْتَذُّ بَِأخْذِهِ، وَلَا يُسَرُّ بِهِ، وَالَْأكْلُ بالخمسة والراحة ازْدِحَامَ الطهعَامِ عَلَى آلَاتِهِ، وَعَلَى الْمَعِدَةِ، وَرُهبَما انسدت الالآت فمات،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وتغضب الْآلَاتُ عَلَى دَفْعِهِ، وَالْمَعِدَةُ عَلَى احْتِمَالِهِ، وَلَا يَِجدُ لَهُ لَذهةً وَلَا اسْتِمْرَاءً، فَأَنْـفَعُ الَْأكْلِ أَكْلُهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَأَكْلُ مَنِ اقتدى به بالأصابع الثلاث.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَمَنْ تَدَبهـرَ؟؟؟ أَغْذِيَـتَهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَمَا كَانَ كََُْلُهُ، وَجَدَهُ لََْ يَْجمَعْ قَطُّ بَـيَْن لَبٍَن وَسََمكٍ ، وَلَا بَـيَْن لَبٍَن وَحَامِضٍ ، وَلَا بَـيَْن غِذَاءَيْنِ حَارهيْنِ، وَلَا بَارِدَيْنِ، وَلَا لَزِجَيِْن، وَلَا قَابِضَيِْن، وَلَا مُسْهِلَيِْن، وَلَا غَلِيظَيِْن، وَلَا مُرْخِيَـيِْن، وَلَا مُسْتَحِيلَيِْن إِلَى خَلْطٍ وَاحِدٍ، وَلَا بَـيَْن مُْختَلِفَيِْن كَقَابِضٍ وَمُسْهِلٍ، وَسَرِيعِ الَْهضْمِ وَبَطِيئِهِ، وَلَا بَـيَْن شَوِيٍّ وَطَبِيخٍ، وَلَا بَـيَْن طَرِيٍّ وَقَدِيدٍ، وَلَا بَـيَْن لَبٍَن وَبَـيْضٍ ، وَلَا بَـيَْن لَْحمٍ وَلَبٍَن، وَلََْ يَكُنْ كََُْلُ طَعَامًا فِي وَقْتِ شِدهةِ حَرَارَتِهِ، وَلَا طَبِيخًا بَائِتًا يُسَخهنُ لَهُ بِالْغَدِ، وَلَا شَيْـئًا مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الَْأطْعِمَةِ الْعَفِنَةِ وَالْمَالَِحةِ، كَالْكَوَامِخِ وَالْمُخَلهلَاتِ، وَالْمُلُوحَاتِ، وَكُلُّ هَذِهِ الَْأنْـوَاعِ ضَارٌّ مُوَلِّدٌ لَِأنْـوَاعٍ مِنَ الُْخرُوجِ عَنِ الصِّحهةِ وَالِاعْتِدَالِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَكَانَ يُصْلِحُ ضَرَرَ بَـعْضِ الَْأغْذِيَةِ بِبَـعْضٍ إِذَا وَجَدَ إِلَيْهِ سَبِيلًا، فَـيَكْسِرُ حَرَارَةَ هَذَا بِبُـرُودَةِ هَذَا، وَيُـبُوسَةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'هَذَا بِرُطُوبَةِ هَذَا، كَمَا فَـعَلَ فِي الْقِثهاءِ وَالرُّطَبِ، وَكَمَا كَانَ كََُْلُ التهمْرَ بِالسهمْنِ، وَهُوَ الَْحيْسُ ، وَيَشْرَبُ نَقِيعَ التهمْرِ يُـلَطِّفُ بِهِ كَيْمُوسَاتِ الَْأغْذِيَةِ الشهدِيدَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَكَانَ مََُْرُ بِالْعَشَاءِ، وَلَوْ بِكَفٍّ مِنْ تَرٍَْ، وَيَـقُولُ: «تَـرْكُ الْعَشَاءِ مَهْرَمَةٌ» ، ذكََرَهُ الترمذي فِي «جَامِعِهِ» ، وَابْنُ مَاجَهْ فِي «سُنَنِهِ» »7« وَذكََرَ أبو نعيم عَنْهُ أَنههُ كَانَ يَـنْـهَى عَنِ النهـوْمِ عَلَى الَْأكْلِ، وَيَذْكُرُ أَنههُ يُـقَسِّ ي الْقَلْبَ ، وَلِهذََا فِي وَصَايَا الَْأطِبهاءِ لِمَنْ أَرَادَ حِفْظَ الصِّحهةِ: أَنْ يَْمشِيَ بَـعْدَ الْعَشَاءِ خُطُوَاتٍ وَلَوْ مِائَةَ خُطْوَةٍ، وَلَا يَـنَامُ عَقِبَهُ، فَإِنههُ مُضِرٌّ جِدًّا، وَقَالَ مُسْلِمُوهُمْ: أَوْ يُصَلِّي عَقِيبَهُ لِيَسْتَقِهر الْغِذَاءُ بِقَعْرِ الْمَعِدَةِ، فَـيَسْهُلَ هَضْمُهُ، وَيَُجودَ بِذَلِكَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَلََْ يَكُنْ مِنْ هَدْيِهِ أَنْ يَشْرَبَ عَلَى طَعَامِهِ فَـيُـفْسِدَهُ، وَلَا سِيهمَا إِنْ كَانَ الْمَاءُ حَارًّا أَوْ بَارِدًا، فَإِنههُ رَدِيءٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'جِدًّا. قَالَ الشهاعِرُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'لَا تَكُنْ عِنْدَ أَكْلِ سُخْنٍ وَبَـرْدٍ ... وَدُخُولِ الَْحمهامِ تَشْرَبُ مَاءَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'فَإِذَا مَا اجْتَـنَـبْتَ ذَلِكَ حَقًّا ... لََْ تََخفْ مَا حَيِيتَ فِي الَْجوْفِ دَاءَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَيُكْ رَهُ شُرْبُ الْمَاءِ عَقِيبَ الرِّيَاضَةِ، وَالتهـعَبِ، وَعَقِيبَ الِْجمَاعِ ، وَعَقِيبَ الطهعَامِ وَقَـبْـلَهُ، وَعَقِيبَ أَكْلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'الفاكهة، وإن كان الشرب عقيب بعضها أسهب مِنْ بَـعْضٍ ، وَعَقِبَ الَْحمهامِ، وَعِنْدَ الِانْتِبَاهِ مِنَ النهـوْمِ، فَـهَذَا كُلُّهُ مُنَافٍ لِِحفْظِ الصِّحهةِ، وَلَا اعتبار بالعوائد، فإنها طبائع ثوان.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '(7) أخرجه الترمذي في الأطعمة. وأخرجه ابن ماجه.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَمها هَدْيُهُ فِي الشهرَابِ، فَمِنْ أَكْمَلِ هَدْيٍ يُْحفَظُ بِهِ الصِّحهةُ، فَإِنههُ كَانَ يَشْرَبُ الْعَسَلَ الْمَمْزُوجَ بِالْمَاءِ الْبَارِدِ، وَفِي هَذَا مِنْ حِفْظِ الصِّحهةِ مَا لَا يَـهْتَدِي إِلَى مَعْرِفَتِهِ إِهلا أَفَاضِلُ الَْأطِبهاءِ، فَإِنه شُرْبَهُ وَلَعْقَهُ عَلَى الرِّيقِ يُذِيبُ الْبَـلْغَمَ، وَيَـغْسِلُ خَْملَ الْمَعِدَةِ، وَيَْجلُو لُزُوجَتَـهَا، وَيَدْفَعُ عَنْـهَا الْفَضَلَاتِ، وَيُسَخِّ نُـهَا بِاعْتِدَالٍ، وَيَـفْتَحُ سَدَدَهَا، وَيَـفْعَلُ مِثْلَ ذَلِكَ بِالْكَبِدِ وَالْكُلَى وَالْمَثَانَةِ، وَهُوَ أَنْـفَعُ لِلْمَعِدَةِ مِنْ كُلِّ حُلْوٍ دَخَلَهَا، وَإِهنَما', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'يَضُرُّ بِالْعَرَضِ لِصَاحِبِ الصهفْرَاءِ لِِحدهتِهِ وَحِدهةِ الصهفْرَاءِ، فَـرُهبَما هَيهجَهَا، وَدَفْعُ مَضَ هرتِهِ لَهمُْ بِالَْخلِّ، فَـيَـعُودُ حِينَئِذٍ لَهمُْ نَافِعًا جِدًّا، وَشُرْبُهُ أَنْـفَعُ مِنْ كَثِيٍر مِنَ الَْأشْرِبَةِ الْمُتهخَذَةِ مِنَ السُّكهرِ أَوْ أَكْ ثَرِهَا، وَلَا سِيهمَا لِمَنْ لََْ يَـعْتَدْ هَذِهِ الَْأشْرِبَةَ، وَلَا أَلِفَهَا طَبْـعُهُ، فَإِنههُ إِذَا شَرِبَـهَا لَا تُلَائِمُهُ مُلَاءَمَةَ الْعَسَلِ، وَلَا قَرِيبًا مِنْهُ، وَالْمُحَكهمُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'فِي ذَلِكَ الْعَادَةُ، فَإِنهـهَا تَـهْدِمُ أُصُولًا، وَتَـبْنِِ أُصُولًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَأَمها الشهرَابُ إِذَا جُِعََ وَصُفِّيَ الَْحلَاوَةُ وَالْبُـرُودَةُ، فَمِنْ أَنْـفَعِ شَيْ ءٍ لِلْبَدَنِ. وَمِنْ أَكْ بََِ أَسْبَابِ حِفْظِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الصِّحهةِ، وَلِلْرَِْوَاحِ وَالْقُوَى، وَالْكَبِدِ وَالْقَلْبِ، عِشْقٌ شَدِيدٌ لَهُ، وَاسْتِمْدَادٌ مِنْهُ، وَإِذَا كَانَ فِيهِ الْوَصْفَانِ، حَصَلَتْ بِهِ التهـغْذِيَةُ، وَتَـنْفِيذُ الطهعَامِ إِلَى الَْأعْضَاءِ، وَإِيصَالُهُ إِلَيْـهَا أَتَمه تَـنْفِيذٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَالْمَاءُ الْبَارِدُ رَطْبٌ يَـقْمَعُ الَْحرَارَةَ، وَيَْحفَظُ على البدن رطوباته الأصلية، ويرد عليه ما تلَل منها، ويرفّق الْغِذَاءَ وَيُـنْفِذُهُ فِي الْعُرُوقِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَاخْتَـلَفَ الَْأطِبهاءُ: هَلْ يُـغَذِّي الْبَدَنَ؟ عَلَى قَـوْلَيِْن: فَأَثْـبَـتَتْ طَائِفَةٌ التهـغْذِيَةَ بِهِ بِنَاءً عَلَى مَا يُشَاهِدُونَهُ مِنَ النُّمُوِّ وَالزِّيَادَةِ وَالْقُهوةِ فِي الْبَدَنِ بِهِ، وَلَا سِيهمَا عِنْدَ شِدهةِ الَْحاجَةِ إِلَيْهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'قَالُوا: وَبَـيَْن الَْحيَـوَانِ وَالنهـبَاتِ قَدْرٌ مُشْتَـرَكٌ مِنْ وُجُوهٍ عَدِيدَةٍ مِنْـهَا: النُّمُوُّ وَالِاغْتِذَاءُ وَالِاعْتِدَالُ، وَفِي النهـبَاتِ قُـهوةُ حِسٍّ تُـنَاسِبُهُ، وَلَِهذَا كَانَ غِذَاءُ النهـبَاتِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'بِالْمَاءِ، فَمَا يُـنْكَرُ أَنْ يَكُونَ لِلْحَيَـوَانِ بِهِ نَـوْعُ غِذَاءٍ، وَأَنْ يَكُونَ جُزْءًا مِنْ غِذَائِهِ التام.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'قالوا: وننْ لا تنكر أَنه قُـهوةَ الْغِذَاءِ وَمُعْظَمَهُ فِي الطهعَامِ، وَإِهنَما أَنْكَرْنَا أَنْ لَا يَكُونَ لِلْمَاءِ تَـغْذِيَةٌ الْبَـتهةَ. قَالُوا: وَأَيْضًا الطهعَامُ إِهنَما يُـغَذِّي بَِما فِيهِ مِنَ الْمَائِيهةِ. وَلَوْلَاهَا لَمَا حَصَلَتْ بِهِ التهـغْذِيَةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'قَالُوا: وَلَِأنه الْمَاءَ مَادهةُ حَيَاةِ الَْحيَـوَانِ وَالنهـبَاتِ، وَلَا رَيْبَ أَنه مَا كَانَ أَقْـرَبَ إِلَى مَادهةِ الشهيْ ءِ، حَصَلَتْ بِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'التهـغْذِيَةُ، فَكَيْفَ إِذَا كَانَتْ مَادهتَهُ الَْأصْلِهيةَ، قَالَ ا هللَُّ تَـعَالَى: وَجَعَلْنا مِنَ الْماءِ كُله شَيْ ءٍ حَيٍّ »7« فكيف تنكر حُصُولَ التهـغْذِيَةِ بَِما هُوَ مَادهةُ الَْحيَاةِ عَلَى الإطلاق؟.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'قالوا: وقد رأينا إِذَا حَصَلَ لَهُ الرِّيُّ بِالْمَاءِ الْبَارِدِ، تَـرَاجَعَتْ إِلَيْهِ قُـوَاهُ وَنَشَاطُهُ وَحَرَكَتُهُ، وَصَبَـرَ عَنِ الطهعَامِ، وَانْـتَـفَعَ بِالْقَدْرِ الْيَسِيِر مِنْهُ، وَرَأَيْـنَا الْعَطْشَانَ لَا يَـنْـتَفِعُ بِالْقَدْرِ الْكَثِيِر مِنَ الطهعَامِ، وَلَا يَِجدُ بِهِ الْقُهوةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَالِاغْتِذَاءَ، وَنَنُْْ لَا نُـنْكِرُ أَنه الْمَاءَ يُـنْفِذُ الْغِذَاءَ إِلَى أَجْ زَاءِ الْبَدَنِ، وَإِلَى جَِيَعِ الَْأعْضَاءِ، وَأَنههُ لَا يَتِمُّ أَمْرُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'الْغِذَاءِ إِهلا بِهِ، وَإِهنَما نُـنْكِرُ عَلَى مَنْ سَلَبَ قُـهوةَ التهـغْذِيَةِ عَنْهُ الْبَـتهةَ، وَيَكَادُ قَـوْلُهُ عِنْدَنَا يَدْخُلُ فِي إِنْكَارِ الُْأمُورِ الْوِجْدَانِيهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَأَنْكَرَتْ طَائِفَةٌ أُخْ رَى حُصُولَ التهـغْذِيَةِ بِهِ، وَاحْ تَجهتْ بُِأمُورٍ يَـرْجِعُ حَاصِلُهَا إِلَى عَدَمِ الِاكْ تِفَاءِ بِهِ، وَأَنههُ لَا يَـقُومُ مَقَامَ الطهعَامِ، وَأَنههُ لَا يَزِيدُ فِي نُُموِّ الَْأعْضَاءِ، وَلَا يَُخلِّفُ عَلَيْـهَا بَدَلَ مَا حَلهلَتْهُ الَْحرَارَةُ، وَنَوُْْ ذَلِكَ مِمها لَا يُـنْكِرُهُ أَصْحَابُ التهـغْذِيَةِ، فَإِنهـهُمْ يَْجعَلُونَ تَـغْذِيَـتَهُ بَِحسَبِ جَوْهَرِهِ، وَلَطَافَتِهِ وَرِقهتِهِ، وَتَـغْذِيَةُ كُلِّ شَيْ ءٍ بَِحسْبِهِ، وَقَدْ شُوهِدَ الَْهوَاءُ الهرطْبُ الْبَارِدُ اللهيُِّن اللهذِيذُ يُـغَذِّي بَِحسْبِهِ، وَالهرائِحَةُ الطهيِّبَةُ تُـغَذِّي نَـوْعًا مِنَ الْغِذَاءِ، فتغذية الْمَاءِ أَظْهَرُ وَأَظْهَرُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَالْمَقْصُودُ: أَنههُ إِذَا كَانَ بَارِدًا، وَخَالَطَهُ مَا يَُحلِّيهِ كَالْعَسَلِ أَوِ الهزبِيبِ، أَوِ التهمْرِ أَوِ السُّكهرِ، كَانَ مِنْ أَنْـفَعِ مَا يَدْخُلُ الْبَدَنَ، وَحَفِظَ عَلَيْهِ صِحهتَهُ، فَلِهَذَا كان أحبّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, '(7) الأنبياء- .31', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'الشهرَابِ إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ الْبَارِدَ الُْحلْوَ. وَالْمَاءُ الْفَاتِرُ يَـنْـفُخُ، وَيَـفْعَلُ ضِده هَذِهِ الَْأشْيَاءِ. وَلَمها كَانَ الْمَاءُ الْبَائِتُ أَنْـفَعَ مِنَ الهذِي يُشْرَبُ وَقْتَ اسْتِقَائِهِ، قَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَقَدْ دَخَلَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'إِلَى حَائِطِ أَبِي الَْهيْـثَمِ بْنِ التهـيِّهَانِ: «هَلْ مِنْ مَاءٍ بَاتَ فِي شَنهةٍ؟» فَأَتَاهُ بِهِ، فَشَرِبَ مِنْهُ، رَوَاهُ الْبُخَارِيُّ وَلَفْظُهُ: «إِنْ كَانَ عِنْدَكَ مَاءٌ بَاتَ فِي شَنهةٍ وَإِهلا كَرَعْنَا» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَالْمَاءُ الْبَائِتُ بَِمنْزِلَةِ الْعَجِيِن الَْخمِيِر، وَالهذِي شُرِبَ لِوَقْتِهِ بَِمنْزِلَةِ الْفَطِيِر، وَأَيْضًا فَإِنه الَْأجْزَاءَ التُّـرَابِيهةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَالَْأرْضِ يهةَ تُـفَارِقُهُ إِذَا بَاتَ ، وَقَدْ ذكُِرَ أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ يُسْتَـعْذَبُ لَهُ الْمَاءُ، وَيَْختَارُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'الْبَائِتَ مِنْهُ. وَقَالَتْ عَائِشَةُ: كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يُسْتَـقَى لَهُ الْمَاءُ الْعَذْبُ مِنْ بِئْرِ السُّقْيَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, '. »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'وَالْمَاءُ الهذِي فِي الْقِرَبِ وَالشِّ نَانِ، أَلَذُّ مِنَ الهذِي يَكُونُ فِي آنِيَةِ الْفَخهارِ وَالَْأحْجَارِ وَغَيِْرهِاَُ، وَلَا سِيهمَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'أَسْقِيَةُ الَْأدَمِ، وَلَِهذَا الْتَمَسَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مَاءً بَاتَ فِي شتة دُونَ غَيِْرهَا مِنَ الَْأوَانِي، وَفِي الْمَاءِ إِذَا وُضِعَ فِي الشِّ نَانِ، وَقِرَبِ الَْأدَمِ خَاصهةٌ لَطِيفَةٌ لما فيها من المسام المنتفخة الهتِي يَـرْشَحُ مِنْـهَا الْمَاءُ، وَلِهذََا كَانَ الْمَاءُ فِي الْفَخهارِ الهذِي يَـرْشَحُ أَلَذُّ مِنْهُ، وَأَبْـرَدُ فِي الهذِي لَا يَـرْشَحُ، فَصَلَاةُ ا هلِلَّ وَسَلَامُهُ عَلَى أَكْمَلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'الَْخلْقِ، وَأَشْرَفِهِمْ نَـفْسًا، وَأَفْضَلِهِمْ هَدْيًا فِي كُلِّ شَيْ ءٍ، لَقَدْ دَ هل أُمهتَهُ عَلَى أَفْضَلِ الُْأمُورِ وَأَنْـفَعِهَا لَهمُْ فِي الْقُلُوبِ وَالَْأبْدَانِ، وَالدُّنْـيَا وَالْآخِرَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'قَالَتْ عائشة: كَانَ أَحَبُّ الشهرَابِ إلى رسول الله هللا ىلص الُْحلْوَ الْبَارِدَ »3« . وَهَذَا يُْحتَمَلُ أَنْ يُرِيدَ بِهِ الْمَاءَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'الْعَذْبَ ، كَمِيَاهِ الْعُيُونِ وَالْآبَارِ الُْحلْوَةِ، فَإِنههُ كَانَ يُسْتَـعْذَبُ لَهُ الْمَاءُ. وَيُْحتَمَلُ أَنْ يُرِيدَ بِهِ الْمَاءَ الْمَمْزُوجَ بِالْعَسَلِ، أَوِ الهذِي نُقِعَ فِيهِ التهمْرُ أَوِ الهزبِيبُ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَقَدْ يُـقَالُ- وَهُوَ الأظهر:- يعمهما جيَعا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, '(7) أخرجه البخاري في الأشربة. (2) أخرجه أبو داود في الأشربة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, '(3) أخرجه أحدْ والترمذي في الجامع.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وَقَـوْلُهُ فِي الَْحدِيثِ الصهحِيحِ: «إِنْ كَانَ عِنْدَكَ ماء بات في سنّة وَإِهلا كَرَعْنَا» ، فِيهِ دَلِيلٌ عَلَى جَوَازِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'الْكَرْعِ ، وَهُوَ الشُّرْبُ بِالْفَمِ مِنَ الَْحوْضِ وَالْمِقْرَاةِ وَنَوِْْهَا، وَهَذِهِ- وَا هللَُّ أَعْلَمُ- وَاقِعَةُ عَيٍْن دَعَتِ الَْحاجَةُ فِيهَا إِلَى الْكَرْعِ بِالْفَمِ، أَوْ قَالَهُ مُبَـيِّنًا لجوازه، فإن من الناس من يكرهه، الأطباء تَكَادُ تُرََِّمُهُ، وَيَـقُولُونَ: إِنههُ يَضُرُّ بِالْمَعِدَةِ، وَقَدْ رُوِيَ فِي حَدِيثٍ لَا أَدْرِي مَا حَالُهُ عَنِ ابْنِ عُمَرَ، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ نَـهَانَا أَنْ نَشْرَبَ عَلَى بُطُونِنَا، وَهُوَ الْكَرْعُ، وَنَـهَانَا أَنْ نَـغْتَِرفَ بِالْيَدِ الْوَاحِدَةِ وَقَالَ: «لَا يَـلَغْ أَحَدُكُمْ كَمَا يَـلَغُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'الْكَلْبُ ، وَلَا يَشْرَبْ بِاللهيْلِ مِنْ إِنَاءٍ حَ هتى يَْختَبِهََُ إِهلا أَنْ يَكُونَ مَُخمهرًا» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'وَحَدِيثُ الْبُخَارِيِّ أَصَحُّ مِنْ هَذَا، وَإِنْ صَحه، فَلَا تَـعَارُضَ بَـيْـنَـهُمَا، إِذْ لَعَله الشُّرْبَ بِالْيَدِ لََْ يَكُنْ يُْمكِنُ حِينَئِذٍ، فَـقَالَ: وَإِهلا كَرَعْنَا، وَالشُّرْبُ بِالْفَمِ إِهنَما يَضُرُّ إِذَا انْكَبه الشهارِبُ عَلَى وَجْ هِهِ وَبَطْنِهِ، كَالهذِي يَشْ رَبُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'مِنَ النهـهْرِ وَالْغَدِيرِ، فَأَمها إِذَا شَرِبَ مُنْـتَصِبًا بِفَمِهِ مِنْ حَوْضٍ مُرْتَفِعٍ وَنَوِْْهِ، فَلَا فَـرْقَ بَـيَْن أَنْ يَشْرَبَ بِيَدِهِ أَوْ بفمه.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَكَانَ مِنْ هَدْيِهِ الشُّرْبُ قَاعِدًا، هَذَا كَانَ هَدْيَهُ الْمُعْتَادَ، وَصَحه عَنْهُ أَنههُ نَـهَى عَنِ الشُّرْبِ قَائِمًا، وَصَحه عَنْهُ أَنههُ أَمَرَ الهذِي شَرِبَ قَائِمًا أَنْ يَسْتَقِيءَ، وَصَحه عَنْهُ أَنههُ شَرِبَ قَائِمًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'قَالَتْ طَائِفَةٌ: هَذَا نَاسِخٌ لِلنهـهْيِ، وَقَالَتْ طَائِفَةٌ: بَلْ مُبَـيٌِّن أَنه النهـهْيَ لَيْسَ لِلتهحْرِيِم، بَلْ لِلِْرْْشَادِ وَتَـرْكِ الَْأوْلَى، وَقَالَتْ طَائِفَةٌ: لَا تَـعَارُضَ بَـيْـنَـهُمَا أَصْلًا، فَإِنههُ إِهنَما شَرِبَ قَائِمًا لِلْحَاجَةِ، فَإِنههُ جَاءَ إِلَى زَمْزَمَ، وَهُمْ يَسْتَـقُونَ مِنْـهَا، فَاسْتَـقَى فَـنَاوَلُوهُ الدهلْوَ، فَشَرِبَ وَهُوَ قَائِمٌ، وَهَذَا كَانَ مَوْضِعَ حَاجَةٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَلِلشُّرْبِ قَائِمًا آفَاتٌ عَدِيدَةٌ مِنْـهَا: أَنههُ لَا يَْحصُلُ به الرّي التام، ولا يستقرّ في', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(7) أخرجه ابن ماجه في الأشربة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الْمَعِدَةِ حَ هتى يَـقْسِمَهُ الْكَبِدُ عَلَى الَْأعْضَاءِ، وَيَـنْزِلَ بِسُرْعَةٍ وَحِدهةٍ إِلَى الْمَعِدَةِ، فَـيُخْشَى مِنْهُ أَنْ يُـبَـرِّدَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'حَرَارَتَـهَا، وَيُشَوِّشَهَا، وَيُسْرعَِ النُّـفُوذَ إِلَى أَسْفَلِ الْبَدَنِ بِغَيِْر تَدْرِيجٍ، وَكُلُّ هَذَا يَضُرُّ بِالشهارِبِ، وَأَمها إِذَا فَـعَلَهُ نَادِرًا أَوْ لَِحاجَةٍ، لََْ يَضُهرهُ، وَلَا يُـعْتَـرَضُ بِالْعَوَائِدِ عَلَى هَذَا، فَإِنه الْعَوَائِدَ طَبَائِعُ ثَـوَانٍ، وَلَهاَ أَحْكَامٌ أُخْ رَى، وَهِيَ بَِمنْزِلَةِ الَْخارِجِ عَنِ الْقِيَاسِ عِنْدَ الْفُقَهَاءِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَفِي «صَحِيحِ مسلم» مِنْ حَدِيثِ أَنَسِ بْنِ مَالِكٍ ، قَالَ: كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـتَـنَـهفسُ فِي الشهرَابِ ثَلَاثًَ، وَيَـقُولُ: «إِنههُ أَرْوَى وَأَمْرَأُ وَأَبْـرَأُ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الشهرَابُ فِي لِسَانِ الشهارعِِ وَحَلََْةِ الشهرْعِ : هُوَ الْمَاءُ، وَمَعْنَى تَـنَـفُّسِهِ فِي الشهرَابِ: إِبَانَـتُهُ الْقَدَحَ عَنْ فِيهِ، وَتَـنَـفُّسُهُ خَارِجَهُ، ُ مه يَـعُودُ إِلَى الشهرَابِ، كَمَا جَاءَ مُصَ هرحًا بِهِ فِي الَْحدِيثِ الْآخَرِ: «إِذَا شَرِبَ أَحَدُكُمْ فَلَا يَـتَـنَـهفسْ فِي الْقَدَحِ، وَلَكِنْ لِيُبِِن الِْإنَاءَ عَنْ فِيهِ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَفِي هَذَا الشُّرْبِ حِكَمٌ جَهَةٌ، وَفَـوَائِدُ مُهِمهةٌ، وَقَدْ نَـبههَ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَلَى مَاََمِعِهَا بِقَوْلِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '«إِنههُ أَرْوَى وَأَمْرَأُ وَأَبْـرَأُ» فَأَرْوَى: أَشَدُّ رِيًّا، وَأَبْـلَغُهُ وَأَنْـفَعُهُ، وَأَبْـرَأُ: أَفْـعَلُ مِنَ الْبُـرْءِ، وَهُوَ الشِّ فَاءُ، أَيْ يبىَء مِنْ شَدهةِ الْعَطَشِ وَدَائِهِ لِتَـرَدُّدِهِ عَلَى الْمَعِدَةِ الْمُلْتَهِبَةِ دُفُـعَاتٍ، فَـتُسَكِّنُ الدُّفْـعَةُ الثهانِيَةُ مَا عَجَزَتِ الُْأولَى عَنْ تَسْكِينِهِ، وَالثهالِثَةُ مَا عَجَزَتِ الثهانِيَةُ عَنْهُ، وَأَيْضًا فَإِنههُ أَسْلَمُ لَِحرَارَةِ الْمَعِدَةِ، وَأَبْـقَى عَلَيْـهَا مِنْ أَنْ يَـهْجُمَ عَلَيْـهَا الْبَارِدُ وَهْلَةً وَاحِدَةً، وَنَـهْلَةً وَاحِدَةً.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَأَيْضًا فَإِنههُ لَا يَـرْوِي لِمُصَادَفَتِهِ لَِحرَارَةِ الْعَطَشِ لَْحظَةً، ُ مه يُـقْلِعُ عَنْـهَا، وَلَمها تُكْسَرْ سَوْرَتُـهَا وَحِدهتُـهَا، وَإِنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'انْكَسَرَتْ لََْ تَـبْطُلْ بِالْكُلِّيهةِ خِِلَِافِ كَسْرِهَا عَلَى التهمَهُّلِ وَالتهدْرِيجِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '(7) أخرجه مسلم في الأشربة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(2) أخرجه ابن ماجه من حديث رواه الحارث بن أبي ذئاب عن عمه عن أبي هريرة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَأَيْضًا فَإِنههُ أَسْلَمُ عَاقِبَةً وَآمَنُ غَائِلَةً مِنْ تَـنَاوُلِ جَِيَعِ مَا يُـرْوِي دُفْـعَةً وَاحِدَةً، فَإِنههُ يخاف منه أن يطفىء', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'الَْحرَارَةَ الْغَرِيزِيهةَ بِشِدهةِ بَـرْدِهِ، وَكَثْـرَةِ كَمِّيهتِهِ، أَوْ يُضْعِفُهَا فَـيُـؤَدِّي ذَلِكَ إِلَى فَسَادِ مِزَاجِ الْمَعِدَةِ وَالْكَبِدِ، وَإِلَى أَمْرَاضٍ رَدِيئَةٍ، خُصُوصًا فِي سُكهانِ الْبِلَادِ الَْحارهةِ، كَالِْحجَازِ وَالْيَمَنِ وَنَوِْْهِاَُ، أَوْ فِي الَْأزْمِنَةِ الَْحارهةِ كَشِدهةِ الصهيْفِ، فَإِنه الشُّرْبَ وَهْلَةً وَاحِدَةً مَُخوفٌ عَلَيْهِمْ جِدًّا، فَإِنه الَْحاره الْغَرِيزِيه ضَعِيفٌ فِي بَـوَاطِنِ أَهْلِهَا، وَفِي تِلْكَ الَْأزْمِنَةِ الحارة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وقوله: «وأمرأ» : هو أفعل من مرىء الطهعَامُ وَالشهرَابُ فِي بَدَنِهِ: إِذَا دَخَلَهُ، وَخَالَطَهُ بِسُهُولَةٍ وَلَذهةٍ وَنَـفْعٍ. وَمِنْهُ: فَكُلُوهُ هَنِيئاً مَرِيئاً »7« هَنِيئًا فِي عَاقِبَتِهِ، مَرِيئًا فِي مَذَاقِهِ. وَقِيلَ: مَعْنَاهُ أَنههُ أَسْرَعُ انِْدَْارًا عَنِ الْمَرِيءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'لِسُهُولَتِهِ وَخِهفتِهِ عَلَيْهِ، خِِلَِافِ الْكَثِيِر، فَإِنههُ لَا يَسْهُلُ عَلَى الْمَرِيءِ انِْدَْارُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَمِنْ آفَاتِ الشُّرْبِ نَـهْلَةً واحدة أنه يخاف منه الشرق بأن يسدّ مَرََْى الشهرَابِ لِكَثْـرَةِ الْوَارِدِ عَلَيْهِ، فَـيَـغَصُّ بِهِ، فَإِذَا تَـنَـهفسَ رُوَيْدًا، ُ مه شَرِبَ ، أَمِنَ مِنْ ذَلِكَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَمِنْ فَـوَائِدِهِ: أَنه الشهارِبَ إِذَا شَرِبَ أَهولَ مَ هرةٍ تَصَاعَدَ الْبُخَارُ الدُّخَانُِّي الَْحارُّ الهذِي كَانَ عَلَى الْقَلْبِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَالْكَبِدِ لِوُرُودِ الْمَاءِ الْبَارِدِ عَلَيْهِ، فَأَخْ رَجَتْهُ الطهبِيعَةُ عَنْـهَا، فَإِذَا شَرِبَ مَ هرةً وَاحِدَةً، اتهـفَقَ نُـزُولُ الْمَاءِ الْبَارِدِ، وَصُعُودُ الْبُخَارِ، فَـيَـتَدَافَـعَانِ وَيَـتَـعَالََجانِ، وَمِنْ ذَلِكَ يَْحدُثُ الشهرَقُ وَالْغُصهةُ، وَلَا يَـتَـهَنهأُ الشهارِبُ بِالْمَاءِ، وَلَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'يُْمرِئْهُ، وَلَا يَتِمُّ رِيُّهُ. وَقَدْ رَوَى عَبْدُ ا هلِلَّ بْنُ الْمُبَارَكِ، والبيهقي، وَغَيْـرُهُاَُ عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إِذَا شَرِبَ أَحَدُكُمْ فَـلْيَمُصه الْمَاءَ مَصًّا، وَلَا يَـعُبه عَبًّا، فَإِنههُ مِنَ الْكُبَادِ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَالْكُبَادُ- بِضَمِّ الْكَافِ وَتَْخفِيفِ الْبَاءِ- هُوَ وَجَعُ الْكَبِدِ، وَقَدْ عُلِمَ بِالتهجْرِبَةِ أَنه وُرُودَ الْمَاءِ جُلََْةً وَاحِدَةً عَلَى الْكَبِدِ يُـؤْلِمُهَا وَيُضْعِفُ حَرَارَتَـهَا، وَسَبَبُ ذَلِكَ الْمُضَادهةُ الهتِي بَـيَْن حَرَارَتَِها، وَبَـيَْن مَا وَرَدَ عَلَيْـهَا مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'كَيْفِيهةِ الْمَبْـرُودِ وَكَمِّيهتِهِ. وَلَوْ وَرَدَ بِالتهدْرِيجِ شَيْـئًا فَشَيْـئًا، لََْ يُضَاده حَرَارَتَـهَا، وَلََْ يُضْعِفْهَا، وَهَذَا مِثَالُهُ صَبُّ الْمَاءِ البارد على القدر،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, '(7) النساء- .4', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, '(2) أخرجه الطباَني في الصغير وابن السي وأبو نعيم في الطب، والبيهقي في شعب الإيمان.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وهي تفوز لَا يَضُرُّهَا صَبُّهُ قَلِيلًا قَلِيلًا. وَقَدْ رَوَى الترمذي فِي «جَامِعِهِ» عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَاحْدَُْوا إِذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'ِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, '«لَا تَشْرَبُوا نَـفَسًا وَاحِدًا كَشُرْبِ الْبَعِيِر، وَلَكِنِ اشْرَبُوا مَثْـنَى وَثُلَاثَ ، وَسَُّموا إِذَا أَنْـتُمْ شَرِبْـتُمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'أَنْـتُمْ فَـرَغْتُمْ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَلِلتِّسْمِ يَةِ فِي أَهولِ الطهعَامِ وَالشهرَابِ، وَحَدِْْ ا هلِلَّ فِي آخِرِهِ تَثَِْيٌر عَجِيبٌ فِي نَـفْعِهِ وَاسْتِمْرَائِهِ، وَدَفْعِ مَضَ هرتهِ. قَالَ الِْإمَامُ أَحْدَُْ: إِذَا جَعَََ الطهعَامُ أَرْبَـعًا، فَـقَدْ كَمُلَ: إِذَا ذكُِرَ اسْمُ ا هلِلَّ فِي أَهولِهِ، وَحُِدَْ ا هللَُّ فِي آخِرِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَكَثُـرَتْ عَلَيْهِ الأيدي، وكان من حل.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَقَدْ رَوَى مسلم فِي «صَحِيحِهِ» : مِنْ حَدِيثِ جَابِرِ بْنِ عَبْدِ ا هلِلَّ، قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'سَِمعْتُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يقول: «غَطُّوا الِْإنَاءَ، وَأَوْكُوا السِّ قَاءَ، فَإِنه فِي السهنَةِ لَيْـلَةً يَـنْزِلُ فِيهَا وَبَاءٌ لَا يَُمرُّ بِِإنَاءٍ لَيْسَ عَلَيْهِ غِطَاءٌ، أَوْ سِقَاءٍ لَيْسَ عَلَيْهِ وكَِاءٌ إِهلا وَقَعَ فِيهِ مِنْ ذَلِكَ الدهاءِ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَهَذَا مِمها لَا تَـنَالُهُ عُلُومُ الَْأطِبهاءِ وَمَعَارِفُـهُمْ، وقد عرفه من عرفه من عقلاء الناس بالتجربة. قال الليث ابن سَعْدٍ أَحَدُ رُوَاةِ الَْحدِيثِ: الَْأعَاجِمُ عِنْدَنَا يَـتهـقُونَ تِلْكَ اللهيْـلَةَ فِي السهنَةِ فِي كَانُونَ الَْأهولِ مِنْـهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَصَحه عَنْهُ أَنههُ أَمَرَ بِتَخْمِيِر الِْإنَاءِ وَلَوْ أَنْ يَـعْرِضَ عَلَيْهِ عُودًا »3« وَفِي عَرْضِ الْعُودِ عَلَيْهِ مِنَ الِْحكْمَةِ، أَنههُ لَا يَـنْسَى تَْخمِيَرهُ. بَلْ يَـعْتَادُهُ حَ هتى بِالْعُودِ، وَفِيهِ: أَنههُ رُهبَما أَرَادَ الدهبِيبُ أَنْ يَسْقُطَ فِيهِ، فَـيَمُ هر عَلَى الْعُودِ، فَـيَكُونُ الْعُودُ جِسْرًا لَهُ يَْمنَـعُهُ مِنَ السُّقُوطِ فِيهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَصَحه عَنْهُ: أَنههُ أَمَرَ عِنْدَ إِيكَاءِ الِْإنَاءِ بِذِكْرِ اسْمِ ا هلِلَّ، فَإِنه ذكر اسم الله عند', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(7) أخرجه الترمذي في الأشربة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '(2) أخرجه مسلم في الأشربة، والامام أحدْ. (3) أخرجه البخاري ومسلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'تَْخمِيِر الِْإنَاءِ يَطْرُدُ عَنْهُ الشهيْطَانَ، وَإِيكَاؤُهُ يَطْرُدُ عَنْهُ الَْهوَامه وَلِذَلِكَ أَمَرَ بِذِكْرِ اسْمِ ا هلِلَّ فِي هَذَيْنِ الْمَوْضِ عَيِْن لَِهذَيْنِ الْمَعْنَـيَـيِْن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَرَوَى الْبُخَارِيُّ فِي «صَحِيحِهِ» مِنْ حَدِيثُ ابْنِ عَبهاسٍ ، إِنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ نَـهَى عَنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'الشُّرْبِ مِنْ فِي السِّ قَاءِ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَفِي هَذَا آدَابٌ عَدِيدَةٌ، مِنْـهَا: أَنه تَـرَدُّدَ أَنْـفَاسِ الشهارِبِ فِيهِ يُكْسِبُهُ زُهُومَةً وَرَائِحَةًكَرِيهَةً يُـعَافُ لَِأجْ لِهَا. وَمِنْـهَا: أَنههُ رُهبَما غَلَبَ الدهاخِلُ إِلَى جَوْفِهِ مِنَ الْمَاءِ، فَـتَضَ هررَ بِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَمِنْـهَا: أَنههُ رُهبَما كَانَ فِيهِ حَيَـوَانٌ لَا يَشْعُرُ بِهِ، فَـيُـؤْذِيهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'ومنها: أن الماء كَانَ فِيهِ قَذَاةٌ أَوْ غَيْـرُهَا لَا يَـرَاهَا عِنْدَ الشُّرْبِ، فَـتَلِجُ جَوْفَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَمِنْـهَا: أَنه الشُّرْبَ كَذَلِكَ يَْملَُِ الْبَطْنَ مِنَ الَْهوَاءِ، فَـيَضِيقُ عَنْ أَخْذِ حَظِّهِ مِنَ الْمَاءِ، أَوْ يُـزَاحِهُُْ، أَوْ يُـؤْذِيهِ، وَلِغَيِْر ذَلِكَ مِنَ الِْحكَمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'فَإِنْ قِيلَ: فَمَا تَصْنَـعُونَ بَِما فِي «جَامِعِ الترمذي» : أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ دَعَا بإداوة يوم أحد، فقال: «اخنث فم الإدواة» ، ُ مه شَرِبَ مِنْـهَا مِنْ فِيهَا »2« ؟ قُـلْنَا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'نَكْتَفِي فِيهِ بِقَوْلِ الترمذي: هَذَا حَدِيثٌ لَيْسَ إِسْنَادُهُ بِصَحِيحٍ، وَعَبْدُ ا هلِلَّ بْنُ عُمَرَ الْعُمَرِيُّ يُضَعهفُ مِنْ قِبَلِ حِفْظِهِ، وَلَا أَدْرِي سَِمعَ مِنْ عيسى أَوْ لَا انْـتَـهَى. يُرِيدُ عيسى بن عبد الله رَوَاهُ عَنْهُ، عَنْ رَجُلٍ مِنَ الَْأنْصَارِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَفِي «سُنَنِ أبي داود» مِنْ حَدِيثِ أَبِي سَعِيدٍ الُْخدْرِيِّ ، قَالَ: «نَـهَى رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَنِ الشُّرْبِ مِنْ ثُـلْمَةِ الْقَدَحِ، وَأَنْ يَـنْـفُخَ فِي الشهرَابِ» »3« ، وَهَذَا مِنَ الآداب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '(7) أخرجه البخاري في الأشربة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(2) أخرجه أبو داود. والإختاث: أنه يثنى رؤوسها ويعطفها م يشرب منها. (3) أخرجه أبو داود في الأشربة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الهتِي تَتِمُّ بَِها مَصْلَحَةُ الشهارِبِ، فَإِنه الشُّرْبَ مِنْ ثُـلْمَةِ الْقَدَحِ فِيهِ عِدهةُ مَفَاسِدَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'أَحَدُهَا: أَنه مَا يَكُونُ عَلَى وَجْهِ الْمَاءِ مِنْ قَذًى أَوْ غَيِْرهِ يَْجتَمِعُ إِلَى الثُّـلْمَةِ خِِلَِافِ الَْجانِبِ الصهحِيحِ. الثهانِي: أَنههُ رُهبَما شَ هوشَ عَلَى الشهارِبِ، وَلََْ يَـتَمَكهنْ مِنْ حُسْنِ الشُّرْبِ مِنَ الثُّـلْمَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الثهالِثُ : أَنه الْوَسَخَ وَالزُّهُومَةَ تَتََْمِعُ فِي الثُّـلْمَةِ، وَلَا يَصِلُ إِلَيْـهَا الْغَسْلُ، كَمَا يَصِلُ إِلَى الَْجانِبِ الصهحِيحِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الهرابِعُ: أَنه الثُّـلْمَةَ مَلَُُّ الْعَيْبِ فِي الْقَدَحِ، وَهِيَ أَرْدَأُ مَكَانٍ فِيهِ، فَـيَـنْـبَغِي تَنََُّـبُهُ، وَقَصْدُ الَْجانِبِ الصهحِيحِ، فَإِنه الهردِيءَ مِنْ كُلِّ شَيْءٍ لَا خَيْـرَ فِيهِ، وَرَأَى بَـعْضُ السهلَفِ رَجُلًا يَشْتَِري حَاجَةً رَدِيئَةً، فَـقَالَ: لَا تَـفْعَلْ أَمَا عَلِمْتَ أَنه ا هللََّ نَـزَعَ الْبَـرَكَةَ مِنْ كُلِّ رَدِيءٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'الَْخامِسُ : أَنههُ رُهبَما كَانَ فِي الثُّـلْمَةِ شَقٌّ أَوْ تَْدَِيدٌ يَْجرَحُ فَمَ الشهارِبِ، وَلِغَيِْر هَذِهِ مِنَ الْمَفَاسِدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَأَمها النهـفْخُ فِي الشهرَابِ، فَإِنههُ يُكْسِبُهُ مِنْ فَمِ النهافِخِ رَائِحَةً كَرِيهَةً يُـعَافُ لَِأجْ لِهَا، وَلَا سِيهمَا إِنْ كَانَ مُتَـغَيَِّر', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'الْفَمِ. وَبِالُْجمْلَةِ: فَأَنْـفَاسُ النهافِخِ تَُخالِطُهُ، وَلَِهذَا جَعَََ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بَـيَْن النهـهْيِ عَنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'التهـنَـفُّسِ فِي الِْإنَاءِ وَالنهـفْخِ فِيهِ فِي الَْحدِيثِ الهذِي رَوَاهُ الترمذي وَصَحهحَهُ، عَنِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'قَالَ: نَـهَى رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنْ يُـتَـنَـفهسَ فِي الِْإنَاءِ، أَوْ يُـنْـفَخَ فِيهِ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'فَإِنْ قِيلَ: فَمَا تَصْنَـعُونَ بَِما فِي «الصهحِيحَيِْن» . مِنْ حَدِيثِ أنس، إِنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'يَـتَـنَـهفسُ فِي الِْإنَاءِ ثَلَاثًَ؟ قِيلَ: نُـقَابِلُهُ بِالْقَبُولِ وَالتهسْلِيمِ، وَلَا مُعَارَضَةَ بَـيْـنَهُ وَبَـيَْن الَْأهولِ، فَإِنه مَعْنَاهُ أَنههُ كَانَ يَـتَـنَـهفسُ فِي شُرْبِهِ ثَلَاثًَ، وَذكََرَ الإناء لأنه آلة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, '(7) أخرجه الترمذي وأبو داود وابن ماجه وأحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'الشُّرْبِ، وَهَذَا كَمَا جَاءَ فِي الَْحدِيثِ الصهحِيحِ: أَنه إبراهيم ابن رسول الله صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مَاتَ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'الثهدْيِ »7« أَيْ : فِي مدة الرضاع.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَكَانَ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَشْرَبُ اللهبََن خَالِصًا تَارَةً، وَمَشُوبًا بِالْمَاءِ أُخْ رَى. وَفِي شُرْبِ اللهبَِن الُْحلْوِ فِي تِلْكَ الْبِلَادِ الَْحارهةِ خَالِصًا وَمَشُوبًا نَـفْعٌ عَظِيمٌ فِي حِفْظِ الصِّحهةِ، وَتَـرْطِيبُ الْبَدَنِ، وَرِيُّ الْكَبِدِ، وَلَا سِيهمَا اللهبََن الهذِي تَـرْعَى دَوَابُّهُ الشِّ يحَ وَالْقَيْصُومَ وَالُْخزَامَى وَمَا أَشْبَـهَهَا، فَإِنه لَبَـنَـهَا غِذَاءٌ مَعَ الَْأغْذِيَةِ، وَشَرَابٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'مَعَ الَْأشْرِبَةِ، وَدَوَاءٌ مَعَ الَْأدْوِيَةِ وَفِي «جَامِعِ الترمذي» عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إِذَا أَكَلَ أَحَدُكُمْ طَعَامًا فَـلْيَـقُلْ: اللههُمه بَارِكْ لَنَا فيه، فأطعمنا خَيْـرًا مِنْهُ وَإِذَا سُقِيَ لَبَـنًا فَـلْيَـقُلْ: اللههُمه بَارِكْ لَنَا فِيهِ، وَزِدْنَا مِنْهُ، فَإِنههُ لَيْسَ شيء يجزىء، مِنَ الطهعَامِ وَالشهرَابِ إِهلا اللهبَُن» . قَالَ الترمذي: هذا حديث حسن »2« .', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَثَـبَتَ فِي «صَحِيحِ مسلم» أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ يُـنْـبَذُ لَهُ أَهولَ اللهيْلِ، وَيَشْرَبُهُ إِذَا أَصْبَحَ يَـوْمَهُ ذَلِكَ ، وَاللهيْـلَةَ الهتِي تَِيَءُ، وَالْغَدَ، وَاللهيْـلَةَ الُْأخْ رَى، وَالْغَدَ إِلَى الْعَصْرِ، فَإِنْ بَقِيَ مِنْهُ شَيْ ءٌ سَقَاهُ الَْخادِمَ، أَوْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'أَمَرَ بِهِ فَصُبه »3« . وَهَذَا النهبِيذُ: هُوَ مَا يُطْرَحُ فِيهِ تَرٌَْ يَُحلِّيهِ، وَهُوَ يَدْخُلُ فِي الْغِذَاءِ وَالشهرَابِ، وَلَهُ نَـفْعٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'عَظِيمٌ فِي زِيَادَةِ الْقُهوةِ، وَحِفْظِ الصِّحهةِ، وَلََْ يَكُنْ يَشْرَبُهُ بَـعْدَ ثَلَاثٍ خَوْفًا مِنْ تَـغَيُِّرهِ إِلَى الِْإسْكَارِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(7) أخرجه مسلم في الفضائل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(2) أخرجه الترمذي في الدعوات، وأبو داود والامام أحدْ، والبيهقي في شعب الايمان، وابن ماجة. (3) أخرجه مسلم في الأشربة.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي تَدْبِيِرهِ لَِأمْرِ الْمَلْبَسِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَكَانَ مِنْ أَتَِّم الَْهدْيِ ، وَأَنْـفَعِهِ لِلْبَدَنِ، وَأَخَفِّهِ عَلَيْهِ، وَأَيْسَرِهِ لُبْسًا وَخَلْعًا، وَكَانَ أَكْ ثَـرُ لُبْسِهِ الَْأرْدِيَةَ وَالُْأزُرَ، وَهِيَ أَخَفُّ عَلَى الْبَدَنِ مِنْ غَيِْرهَا، وَكَانَ يَـلْبَسُ الْقَمِيصَ ، بَلْ كَانَ أَحَبه الثِّيَابِ إِلَيْهِ. وَكَانَ هَدْيُهُ فِي لَبْسِهِ لِمَا يَـلْبَسُهُ أَنْـفَعَ شَيْ ءٍ لِلْبَدَنِ، فَإِنههُ لََْ يَكُنْ يُطِيلُ أَكْمَامَهُ، وَيُـوَسِّعُهَا، بَلْ كَانَتْ كُمُّ قَمِيصِهِ إِلَى الرُّسْغِ لَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'يَُجاوِزُ الْيَدَ، فَـتَشُقُّ عَلَى لَابِسِهَا، وَتَنََْـعُهُ خِهفةَ الَْحرَكَةِ وَالْبَطْشِ ، وَلَا تَـقْصُرُ عَنْ هَذِهِ، فَـتَـبْـرُزُ لِلْحَرِّ وَالْبَـرْدِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَكَانَ ذَيْلُ قَمِيصِهِ وَإِزَارِهِ إلى أنصاف الساقين لَ يتجاوز الكعبين، فيؤدي الْمَاشِيَ وَيَـؤُودُهُ، وَيَْجعَلُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'كَالْمُقَيهدِ، وَلََْ يَـقْصُرْ عَنْ عضلة ساقيه، فتنكشف فيؤذي بِالَْحرِّ وَالْبَـرْدِ، وَلََْ تَكُنْ عِمَامَتُهُ بِالْكَبِيَرةِ الهتِي يؤذي الهرأْسَ حَلُْْهَا، وَيُضْعِفُهُ وَيَْجعَلُهُ عُرْضَةً لِلضهعْفِ وَالْآفَاتِ، كَمَا يُشَاهَدُ مِنْ حَالِ أَصْحَابَِها، وَلَا بِالصهغِيَرةِ الهتِي تَـقْصُرُ عَنْ وِقَايَةِ الهرأْسِ مِنَ الَْحرِّ وَالْبَـرْدِ، بَلْ وَسَطًا بَـيَْن ذَلِكَ ، وَكَانَ يُدْخِلُهَا تَتََْ حَنَكِهِ، وَفِي ذَلِكَ فَـوَائِدُ عَدِيدَةٌ: فَإِنهـهَا تَقِي الْعُنُقَ الَْحهر وَالْبَـرْدَ، وَهُوَ أَثْـبَتُ لََها، وَلَا سِيهمَا عِنْدَ ركُُوبِ الَْخيْلِ وَالِْإبِلِ، وَالْكَرِّ وَالْفَرِّ، وَكَثِيٌر مِنَ النهاسِ اهتَخذَ الْكَلَالِيبَ عِوَضًا عَنِ الَْحنَكِ ، وَيَا بُـعْدَ مَا بَـيْـنَـهُمَا فِي النهـفْعِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَالزِّينَةِ، وَأَنْتَ إِذَا تَمََهلْتَ هَذِهِ اللُّبْسَةَ وَجَدْتَـهَا مِنْ أَنْـفَعِ اللُّبْسَاتِ وَأَبْـلَغِهَا فِي حِفْظِ صِحهةِ الْبَدَنِ وَقُـهوتِهِ، وَأَبْـعَدِهَا مِنَ التهكَلُّفِ وَالْمَشَقهةِ عَلَى الْبَدَنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَكَانَ يَـلْبَسُ الِْخفَافَ فِي السهفَرِ دَائِمًا، أَوْ أَغْلَبَ أَحْوَالِهِ لَِحاجَةِ الرِّجْ لَيِْن إِلَى مَا يَقِيهِمَا مِنَ الَْحرِّ وَالْبَـرْدِ، وَفِي الَْحضَرِ أَحْ يَانًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَكَانَ أَحَبُّ أَلْوَانِ الثِّيَابِ إِلَيْهِ الْبَـيَاضَ ، وَالِْحبَـرَةَ، وَهِيَ الْبُـرُودُ الْمُحَبهـرَةُ، وَلََْ يَكُنْ مِنْ هَدْيِهِ لُبْسُ الَْأحْرَِْ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَلَا الَْأسْوَدِ، وَلَا الْمُصَبهغِ، وَلَا الْمَصْقُولِ. وَأَمها الُْحلهةُ الَْحمْرَاءُ الهتِي لَبِسَهَا، فَهِيَ الرِّدَاءُ الْيَمَانُِّي الهذِي فِيهِ سَوَادٌ وَحُرَْْةٌ وَبَـيَاضٌ ، كَالُْحلهةِ الَْخضْرَاءِ، فَـقَدْ لَبِسَ هَذِهِ وَهَذِهِ، وَقَدْ تَـقَدهمَ تَـقْرِيرُ ذَلِكَ ، وَتَـغْلِيطُ مَنْ زَعَمَ أَنههُ لَبِسَ الَْأحْرََْ الْقَانَِي بَِما فِيهِ كِفَايَةٌ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي تَدْبِيِرهِ لَِأمْرِ الْمَسْكَنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'لَمها عَلِمَ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ عَلَى ظَهْرِ سَيٍْر، وَأَنه الدُّنْـيَا مَرْحَلَةُ مُسَافِرٍ يَـنْزِلُ فِيهَا مُدهةَ عُمُرِهِ، ُ مه يَـنْـتَقِلُ عَنْـهَا إِلَى الْآخِرَةِ، لََْ يَكُنْ مِنْ هَدْيِهِ وَهَدْيِ أَصْحَابِهِ، وَمَنْ تَبِعَهُ الِاعْتِنَاءُ بِالْمَسَاكِنِ وَتَشْيِيدِهَا، وَتَـعْلِيَتِهَا وَزَخْ رَفَتِهَا وَتَـوْسِيعِهَا، بَلْ كَانَتْ مِنْ أَحْسَنِ مَنَازِلِ الْمُسَافِرِ تَقِي الَْحهر وَالْبَـرْدَ، وَتَسْتُـرُ عَنِ الْعُيُونِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَتَنََْعُ مِنْ وُلُوجِ الدهوَابِّ ، وَلَا يَُخافُ سُقُوطُهَا لِفَرْطِ ثِقَلِهَا، وَلَا تُـعَشِّ شُ فِيهَا الَْهوَامُّ لِسِعَتِهَا وَلَا تَـعْتَوِرُ عَلَيْـهَا الَْأهْوِيَةُ وَالرِّيَاحُ الْمُؤْذِيَةُ لِارْتِفَاعِهَا، وَلَيْسَتْ تَتََْ الَْأرْضِ فَـتُـؤْذِي سَاكِنَـهَا، وَلَا فِي غَايَةِ الِارْتِفَاعِ عَلَيْـهَا، بَلْ وَسَطٌ، وَتِلْكَ أَعْدَلُ الْمَسَاكِنِ وَأَنْـفَعُهَا، وَأَقَـلُّهَا حَرًّا وَبَـرْدًا، وَلَا تَضِيقُ عَنْ سَاكِنِهَا، فَـيَـنْحَصِرُ، وَلَا تَـفْضُلُ عَنْهُ بِغَيِْر مَنْـفَعَةٍ وَلَا فَائِدَةٍ، فَـتَأْوِي الَْهوَامُّ فِي خُلُوِّهَا، وَلََْ يَكُنْ فِيهَا كُنُفٌ تُـؤْذِي سَاكِنَـهَا بِرَائِحَتِهَا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'بَلْ رَائِحَتُـهَا مِنْ أَطْيَبِ الهروَائِحِ لَِأنههُ كَانَ يُِحبُّ الطِّيبَ ، وَلَا يَـزَالُ عِنْدَهُ، وَرِيُحهُ هُوَ مِنْ أَطْيَبِ الهرائِحَةِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَعَرَقُهُ مِنْ أَطْيَبِ الطِّيبِ، وَلََْ يَكُنْ فِي الدهارِ كَنِيفٌ تَظْهَرُ رَائِحَتُهُ، وَلَا رَيْبَ أَنه هَذِهِ مِنْ أَعْدَلِ الْمَسَاكِنِ وَأَنْـفَعِهَا وَأَوْفَقِهَا لِلْبَدَنِ، وَحِفْظِ صِحهتِهِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي تَدْبِيِرهِ لَِأمْرِ النوم واليقظة', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'من تدبر وَيَـقَظَتَهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَجَدَهُ أَعْدَلَ نَـوْمٍ، وَأَنْـفَعَهُ لِلْبَدَنِ وَالَْأعْضَاءِ وَالْقُوَى، فَإِنههُ كَانَ يَـنَامُ أَهولَ اللهيْلِ، وَيَسْتَـيْقِظُ فِي أَهولِ النِّصْفِ الثهانِي، فَـيَـقُومُ وَيَسْتَاكُ، وَيَـتَـوَضهأُ وَيُصَلِّي مَا كَتَبَ ا هللَُّ لَهُ، فَـيَأْخُذُ الْبَدَنُ وَالَْأعْضَاءُ، وَالْقُوَى حَظههَا مِنَ النهـوْمِ وَالهراحَةِ، وَحَظههَا مِنَ الرِّيَاضَةِ مَعَ وُفُورِ الَْأجْرِ، وَهَذَا غَايَةُ صَلَاحِ الْقَلْبِ وَالْبَدَنِ، وَالدُّنْـيَا وَالْآخِرَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَلََْ يَكُنْ خََُْذُ مِنَ النهـوْمِ فَـوْقَ الْقَدْرِ الْمُحْ تَاجِ إِلَيْهِ، وَلَا يَْمنَعُ نَـفْسَهُ من القدر', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الْمُحْ تَاجِ إِلَيْهِ مِنْهُ، وَكَانَ يَـفْعَلُهُ عَلَى أَكْمَلِ الْوُجُوهِ، فَـيَـنَامُ إِذَا دَعَتْهُ الَْحاجَةُ إِلَى النهـوْمِ عَلَى شِقِّهِ الَْأيَْمنِ، ذَاكِرًا ا هللََّ حَ هتى تَـغْلِبَهُ عيناه، غير ممتلىء الْبَدَنِ مِنَ الطهعَامِ وَالشهرَابِ، وَلَا مُبَاشِرٍ بِنَِْبِهِ الَْأرْضَ ، وَلَا مُتهخِذٍ لِلْفُرُشِ الْمُرْتَفِعَةِ، بَلْ لَهُ ضِجَاعٌ مَنْ أَدَمٍ حَشْوُهُ لِيفٌ ، وَكَانَ يَضْطَجِعُ عَلَى الْوِسَادَةِ، وَيَضَعُ يَدَ هُ تَتََْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'خَدِّهِ أَحْ يَانًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَنَنُْْ نَذْكُرُ فَصْلًا فِي النهـوْمِ وَالنهافِعِ مِنْهُ وَالضهارِّ، فَـنَـقُولُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'النهـوْمُ حَالَةٌ لِلْبَدَنِ يَـتْـبَـعُهَا غَوْرُ الَْحرَارَةِ الْغَرِيزِيهةِ وَالْقُوَى إِلَى بَاطِنِ الْبَدَنِ لِطَلَبِ الهراحَةِ، وَهُوَ نَـوْعَانِ: طَبِيعِيٌّ وَغَيْـرُ طَبِيعِيٍّ. فَالطهبِيعِيُّ: إِمْسَاكُ الْقُوَى النهـفْسَانِيهةِ عَنْ أَفْـعَالَِها، وَهِيَ قُـوَى الِْحسِّ وَالَْحرَكَةِ الِْإرَادِيهةِ، وَمَتَى أَمْسَكَتْ هَذِهِ الْقُوَى عَنْ تَرَِْيكِ الْبَدَنِ اسْتَـرْخَى، وَاجْتَمَعَتِ الرُّطُوبَاتُ وَالَْأخِْرَِةُ الهتِي كَانَتْ تَـتَحَلهلُ وَتَـتَـفَهرقُ بِالَْحرَكَاتِ وَالْيَـقَظَةِ فِي الدِّمَاغِ الهذِي هُوَ مَبْدَأُ هَذِهِ الْقُوَى، فَـيَـتَخَدهرُ وَيَسْتَـرْخِي، وَذَلِكَ النهـوْمُ الطهبِيعِيُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَأَمها النهـوْمُ غَيْـرُ الطهبِيعِيِّ، فَـيَكُونُ لِعَرَضٍ أَوْ مَرَضٍ ، وَذَلِكَ بَِأنْ تَسْتَـوْلَِِ الرُّطُوبَاتُ عَلَى الدِّمَاغِ اسْتِيلَاءً لَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'تَـقْدِرُ الْيَـقَظَةُ عَلَى تَـفْرِيقِهَا، أَوْ تَصْعَدُ أَخِْرَِةٌ رَطْبَةٌ كَثِيَرةٌ كَمَا يَكُونُ عَقِيبَ الِامْتِلَاءِ مِنَ الطهعَامِ وَالشهرَابِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'فَـتُـثْقِلُ الدِّمَاغَ وَتُـرْخِيهِ، فَـيَـتَخَدهرُ، وَيَـقَعُ إِمْسَاكُ الْقُوَى النهـفْسَانِيهةِ عَنْ أَفْـعَالَِها، فَـيَكُونُ النهـوْمُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَلِلنهـوْمِ فَائِدَتَانِ جَلِيلَتَانِ، إِحْدَاهُاَُ: سُكُونُ الَْجوَارِحِ وَرَاحَتُـهَا مِمها يَـعْرِضُ لََها مِنَ التهـعَبِ، فَـيُِريحُ الَْحوَاسه مِنْ نَصَبِ الْيَـقَظَةِ، وَيُزِيلُ الِْإعْيَاءَ وَالْكَلَالَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَالثهانِيَةُ: هَضْمُ الْغِذَاءِ، وَنُضْجُ الَْأخْلَاطِ لَِأنه الَْحرَارَةَ الْغَرِيزِيهةَ فِي وَقْتِ النهـوْمِ تَـغُورُ إِلَى بَاطِنِ الْبَدَنِ، فَـتُعِيُن عَلَى ذَلِكَ ، وَلَِهذَا يَـبْـرُدُ ظَاهِرُهُ وَيَْحتَاجُ النهائِمُ إِلَى فَضْلِ دِثَرٍَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَأَنْـفَعُ النهـوْمِ: أَنْ يَـنَامَ عَلَى الشِّ قِّ الَْأيَْمنِ، لِيَسْتَقِهر الطهعَامُ بَِهذِهِ الَْهيْـئَةِ في', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'الْمَعِدَةِ اسْتِقْرَارًا حَسَنًا، فَإِنه الْمَعِدَةَ أَمْيَلُ إِلَى الَْجانِبِ الَْأيْسَرِ قَلِيلًا، ُ مه يَـتَحَ هولُ إِلَى الشِّ قِّ الَْأيْسَرِ قَلِيلًا لِيُسْرعَِ الَْهضْمَ بِذَلِكَ لِاسْتِمَالَةِ الْمَعِدَةِ عَلَى الْكَبِدِ، ُ مه يَسْتَقِرُّ نَـوْمُهُ عَلَى الَْجانِبِ الَْأيَْمنِ، لِيَكُونَ الْغِذَاءُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'أَسْرَعَ انِْدَْارًا عَنِ الْمَعِدَةِ، فَـيَكُونُ النهـوْمُ عَلَى الَْجانِبِ الَْأيَْمنِ بُدَاءَةَ نَـوْمِهِ وَنَِهايَـتَهُ، وَكَثْـرَةُ النهـوْمِ عَلَى الَْجانِبِ الَْأيْسَرِ مُضِرٌّ بِالْقَلْبِ بِسَبَبِ مَيْلِ الَْأعْضَاءِ إِلَيْهِ، فَـتَـنْصَبُّ إِلَيْهِ المواد.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وأردأ النهـوْمُ عَلَى الظههْرِ، وَلَا يَضُرُّ الِاسْتِلْقَاءُ عَلَيْهِ لِلهراحَةِ مِنْ غَيِْر نَـوْمٍ، وَأَرْدَأُ مِنْهُ أَنْ يَـنَامَ مُنْـبَطِحًا عَلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَجْ هِهِ، وَفِي «الْمُسْنَدِ» وَ «سُنَنِ ابْنِ مَاجَهْ» عَنْ أبي أمامة قَالَ: مَ هر النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَلَى رَجُلٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'نَائِمٍ فِي الْمَسْجِدِ مُنْـبَطِحٍ عَلَى وَجْ هِهِ، فَضَرَبَهُ بِرِجْلِهِ، وَقَالَ: «قُمْ أَوِ اقْـعُدْ، فَإِنهـهَا نَـوْمَةٌ جَهَنهمِيهةٌ» »7« . قَالَ أبقراط فِي كِتَابِ «التهـقْدِمَةِ» : وَأَمها نَـوْمُ الْمَرِيضِ عَلَى بَطْنِهِ مِنْ غَيِْر أَنْ يَكُونَ عَادَتُهُ فِي صِحهتِهِ جَرَتْ بِذَلِكَ ، فذلك يَدُلُّ عَلَى اخْتِلَاطِ عَقْلٍ، وَعَلَى أَلٍََ فِي نَـوَاحِي الْبَطْنِ، قَالَ الشُّهراحُ لِكِتَابِهِ: لَِأنههُ خَالَفَ الْعَادَةَ الَْجيِّدَةَ إِلَى هَيْـئَةٍ رَدِيئَةٍ مِنْ غَيِْر سَبَبٍ ظَاهِرٍ وَلَا بَاطِنٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَالنهـوْمُ الْمُعْتَدِلُ مَُمكِّنٌ لِلْقُوَى الطهبِيعِيهةِ مِنْ أَفْـعَالَِها، مُرِيحٌ لِلْقُهوةِ النهـفْسَانِيهةِ، مُكْثِرٌ مِنْ جَوْهَرِ حَامِلِهَا، حَ هتى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'إِنههُ رُهبَما عَادَ بِِإرَخَائِهِ مَانِعًا مِنْ تَلََُّلِ. الَْأرْوَاحِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَنَـوْمُ النهـهَارِ رَدِيءٌ يُورِثُ الَْأمْرَاضَ الرُّطُوبِيهةَ وَالنهـوَازِلَ، وَيُـفْسِدُ اللهوْنَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَيُورِثُ الطِّحَالَ، وَيُـرْخِي الْعَصَبَ ، وَيُكْسِلُ، وَيُضْعِفُ الشههْوَةَ إِهلا فِي الصهيْفِ وَقْتَ الَْهاجِرَةِ، وَأَرْدَؤُهُ نوم أول النهار، أردأ مِنْهُ النهـوْمُ آخِرَهُ بَـعْدَ الْعَصْرِ، وَرَأَى عَبْدُ ا هلِلَّ بْنُ عَبهاسٍ ابْـنًا لَهُ نَائِمًا نَـوْمَةَ الصُّبْحَةِ، فَـقَالَ لَهُ: قُمْ، أَتَـنَامُ فِي السهاعَةِ التي تقسم فيها الأرزاق.؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, '(7) أخرجه ابن ماجه فى الأدب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'وَقِيلَ: نَـوْمُ النهـهَارِ ثَلَاثَةٌ: خُلُقٌ، وَحُرَقٌ ، وَحُقٌْْ. فَالُْخلُقُ: نَـوْمَةُ الَْهاجِرَةِ، وَهِيَ خُلُقُ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ. وَالُْحرَقُ : نَـوْمَةُ الضُّحَى، تَشْغَلُ عَنْ أَمْرِ الدُّنْـيَا وَالْآخِرَةِ. وَالُْحمْقُ: نَـوْمَةُ الْعَصْرِ. قَالَ بَـعْضُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'السهلَفِ: مَنْ نَامَ بَـعْدَ الْعَصْرِ، فَاخْتُلِسَ عَقْلُهُ، فَلَا يَـلُومَنه إِهلا نَـفْسَهُ. وَقَالَ الشهاعِرُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'أَلَا إِنه نَـوْمَاتِ الضُّحَى تُورِثُ الْفَتَى ... خَبَالًا وَنَـوْمَاتُ الْعُصَيِْر جُنُونُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَنَـوْمُ الصُّبْحَةِ يَْمنَعُ الرِّزْقَ ، لَِأنه ذَلِكَ وَقْتٌ تَطْلُبُ فِيهِ الَْخلِيقَةُ أَرْزَاقَـهَا، وَهُوَ وَقْتُ قِسْمَةِ الَْأرْزَاقِ، فَـنَـوْمُهُ حِرْمَانٌ إِهلا لِعَارِضٍ أَوْ ضَرُورَةٍ، وَهُوَ مُضِرٌّ جِدًّا بِالْبَدَنِ لِِإرْخَائِهِ الْبَدَنَ، وَإِفْسَادِهِ لِلْفَضَلَاتِ الهتِي يَـنْـبَغِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'تَلَِْيلُهَا بِالرِّيَاضَةِ، فَـيُحْدِثُ تَكَسُّرًا وَعِيًّا وَضَعْفًا. وَإِنْ كَانَ قَـبْلَ التهـبَـرُّزِ وَالَْحرَكَةِ وَالرِّيَاضَةِ وَإِشْغَالِ الْمَعِدَةِ بِشَيْ ءٍ، فَذَلِكَ الدهاءُ الْعُضَالُ الْمُوَلِّدُ لَِأنْـوَاعٍ مِنَ الَْأدْوَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَالنهـوْمُ فِي الشهمْسِ يُثِيُر الدهاءَ الدهفِيَن، وَنَـوْمُ الِْإنْسَانِ بَـعْضُهُ فِي الشهمْسِ ، وَبَـعْضُهُ فِي الظِّلِّ رَدِيءٌ، وَقَدْ رَوَى أبو داود فِي «سُنَنِهِ» مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إِذَا كَانَ أَحَدُكُمْ فِي الشهمْسِ فَـقَلَصَ عَنْهُ الظِّلُّ فَصَارَ بَـعْضُهُ فِي الشهمْسِ ، وَبَـعْضُهُ فِي الظِّلِّ فَـلْيَـقُمْ» » .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» وَغَيِْرهِ مِنْ حَدِيثِ بُـرَيْدَةَ بْنِ الُْحصَيْبِ، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ نَـهَى أَنْ يَـقْعُدَ الهرجُلُ بَـيَْن الظِّلِّ وَالشهمْسِ ، وَهَذَا تَـنْبِيهٌ عَلَى مَنْعِ النهـوْمِ بَـيْـنَـهُمَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَفِي «الصهحِيحَيِْن» عَنِ الْبَـرَاءِ بْنِ عَازِبٍ، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ: «إِذَا أَتَـيْتَ مَضْجَعَكَ فَـتَـوَضهأْ وُضُوءَكَ لِلصهلَاةِ، ُ مه اضْطَجِعْ عَلَى شِقِّكَ الَْأيَْمنِ، ُ مه قُلْ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'اللههُمه إِنِّي أَسْلَمْتُ نَـفْسِي إِلَيْكَ ، وَوَجههْتُ وَجْ هِي إِلَيْكَ وَفَـهوضْتُ أَمْرِي إِلَيْكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, '(7) أخرجه أبو داود في الأدب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وَأَلَْجأْتُ ظَهْرِي إِلَيْكَ رَغْبَةً وَرَهْبَةً إِلَيْكَ ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ ، إِهلا إِلَيْكَ ، آمَنْتُ بِكِتَابِكَ الهذِي أَنْـزَلْتَ ، وَنَبِيِّكَ الهذِي أَرْسَلْتَ . وَاجْعَلْهُنه آخِرَ كَلَامِكَ ، فَإِنْ مُته مِنْ لَيْـلَتِكَ ، مُته عَلَى الْفِطْرَةِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'وَفِي «صَحِيحِ الْبُخَارِيِّ » عَنْ عائشة أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عليه وسلم، كَانَ إِذَا صَلهى ركَْ عَتَِي الْفَجْرِ-', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'يَـعْنِِ سُنهـتَـهَا- اضْطَجَعَ عَلَى شِقِّهِ الَْأيَْمنِ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'وَقَدْ قِيلَ: إِنه الحكمة في النوم على الجانب الأيمن، ألايستغرق النهائِمُ فِي نَـوْمِهِ، لَِأنه الْقَلْبَ فِيهِ مَيْلٌ إِلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'جِهَةِ الْيَسَارِ، فَإِذَا نَامَ عَلَى جَنْبِهِ الَْأيَْمنِ، طَلَبَ الْقَلْبُ مُسْتَـقَهرهُ مِنَ الَْجانِبِ الَْأيْسَرِ، وَذَلِكَ يَْمنَعُ مِنِ اسْتِقْرَارِ النهائِمِ وَاسْتِثْـقَالِهِ فِي نَـوْمِهِ، خِِلَِافِ قَـرَارِهِ فِي النهـوْمِ عَلَى الْيَسَارِ، فَإِنههُ مُسْتَـقَرُّهُ، فَـيَحْصُلُ بِذَلِكَ الدهعَةُ التهامهةُ، فَـيَسْتَـغْرِقُ الِْإنْسَانُ فِي نَـوْمِهِ، وَيَسْتَـثْقِلُ، فَـيَـفُوتُهُ مَصَالِحُ دِينِهِ وَدُنْـيَاهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'وَلَمها كَانَ النهائِمُ بَِمنْزِلَةِ الْمَيِّتِ، وَالنهـوْمُ أَخُو الْمَوْتِ- وَلَِهذَا يَسْتَحِيلُ عَلَى الَْحيِّ الهذِي لَا يَُموتُ ، وَأَهْلُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'الَْجنهةِ لَا يَـنَامُونَ فِيهَا-كَانَ النهائِمُ مُتَُْاجًا إِلَى مَنْ يَْحرُسُ نَـفْسَهُ، وَيَْحفَظُهَا مِمها يَـعْرِضُ لََها مِنَ الْآفَاتِ، وَيَْحرُسُ بَدَنَهُ أَيْضًا مِنْ طَوَارِقِ الْآفَاتِ، وَكَانَ رَبُّهُ وَفَاطِرُهُ تَـعَالَى هُوَ الْمُتَـوَلِِّ لِذَلِكَ وَحْدَهُ. عَلهمَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ النهائِمَ أَنْ يَـقُولَ كَلِمَاتِ التهـفْوِيضِ وَالِالْتِجَاءِ، وَالهرغْبَةِ وَالهرهْبَةِ، لِيَسْتَدْعِيَ بَِها كَمَالَ حِفْظِ ا هلِلَّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'لَهُ، وَحِرَاسَتِهِ لِنَـفْسِهِ وَبَدَنِهِ، وَأَرْشَدَهُ مَعَ ذَلِكَ إِلَى أَنْ يَسْتَذْكِرَ الِْإيَمانَ، وَيَـنَامَ عَلَيْهِ، وَيَْجعَلَ التهكَلُّمَ بِهِ آخِرَ كَلَامِهِ، فَإِنههُ رُهبَما تَـوَفهاهُ ا هللَُّ فِي مَنَامِهِ، فَإِذَا كَانَ الِْإيَمانُ آخِرَ كَلَامِهِ دَخَلَ الَْجنهةَ، فَـتَضَمهنَ هَذَا الَْهدْيُ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'الْمَنَامِ مَصَالِحَ الْقَلْبِ وَالْبَدَنِ، وَالرُّوحِ فِي النهـوْمِ وَالْيَـقَظَةِ، وَالدُّنْـيَا وَالْآخِرَةِ، فَصَلَوَاتُ ا هلِلَّ وَسَلَامُهُ عَلَى مَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'نَالَتْ بِهِ أمّته كلّ خير.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, '(7) أخرجه البخاري في الأدب، ومسلم في الذكر والدعاء. (2) أخرجه البخاري في التهجير.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'وَقَـوْلُهُ: «أَسْلَمْتُ نَـفْسِي إِلَيْكَ » ، أَيْ : جَعَلْتُـهَا مُسَلهمَةً لَكَ تَسْلِيمَ الْعَبْدِ الْمَمْلُوكِ نَـفْسَهُ إِلَى سَيِّدِهِ وَمَالِكِهِ. وَتَـوْجِيهُ وَجْ هِهِ إِلَيْهِ يَـتَضَمهنُ إِقْـبَالَهُ بِالْكُلِّيهةِ عَلَى رَبِّهِ، وَإِخْلَاصَ الْقَصْدِ وَالِْإرَادَةِ لَهُ، وَإِقْـرَارَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'بِالُْخضُوعِ وَالذُّلِّ وَالِانْقِيَادِ، قَالَ تَـعَالَى: فَإِنْ حَاجُّوكَ فَـقُلْ أَسْلَمْتُ وَجْ هِيَ هِلِلَّ، وَمَنِ اتهـبَـعَنِ »7« وَذكََرَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'الْوَجْ هَ إِذْ هُوَ أَشْرَفُ مَا فِي الانسان، وممَع الحواس، وأيضا ففيه معنى الوجه وَالْقَصْدِ مِنْ قَـوْلِهِ: أَسْتَـغْفِرُ ا هللََّ ذَنْـبًا لَسْتُ مُصُِْيَهُ ... رَبه الْعِبَادِ إِلَيْهِ الْوَجْ هُ وَالْعَمَلُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 48, 'وَتَـفْوِيضُ الَْأمْرِ إِلَيْهِ رَدُّهُ إِلَى ا هلِلَّ سُبْحَانَهُ، وَذَلِكَ يُوجِبُ سُكُونَ الْقَلْبِ وَطُمَأْنِينَـتَهُ، وَالرِّضَى بَِما يَـقْضِيهِ وَيَْختَارُهُ لَهُ مِمها يُِحبُّهُ وَيَـرْضَاهُ، وَالتهـفْوِيضُ مِنْ أَشْرَفِ مَقَامَاتِ الْعُبُودِيهةِ، وَلَا عِلهةَ فِيهِ، وَهُوَ مِنْ مَقَامَاتِ الَْخاصهةِ خِلَافًا لِزَاعِمِي خِلَافِ ذَلِكَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 49, 'وَإِلَْجاءُ الظههْرِ إِلَيْهِ سُبْحَانَهُ يَـتَضَمهنُ قُـهوةَ الِاعْتِمَادِ عَلَيْهِ، وَالثِّقَةَ بِهِ، وَالسُّكُونَ إِلَيْهِ، وَالتهـوَكُّلَ عَلَيْهِ، فَإِنه مَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 50, 'أَسْنَدَ ظَهْرَهُ إِلَى ركُْنٍ وَثِيقٍ، لََْ يََخفِ السُّقُوطَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 51, 'وَلَمها كَانَ لِلْقَلْبِ قُـهوتَانِ: قُـهوةُ الطهلَبِ، وَهِيَ الهرغْبَةُ، وَقُـهوةُ الَْهرَبِ، وَهِيَ الهرهْبَةُ، وَكَانَ الْعَبْدُ طَالِبًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 52, 'لِمَصَالِِحهِ، هَارِبًا مِنْ مَضَارِّهِ، جَعَََ الَْأمْرَيْنِ فِي هَذَا التهـفْوِيضِ وَالتهـوَجُّهِ، فَـقَالَ: رَغْبَةً وَرَهْبَةً إِلَيْكَ ، ُ مه أَثْـنَى عَلَى رَبِّهِ، بَِأنههُ لَا مَلْجَأَ لِلْعَبْدِ سِوَاهُ، وَلَا مَنْجَا لَهُ مِنْهُ غَيْـرُهُ، فَـهُوَ الهذِي يَـلْجَأُ إِلَيْهِ الْعَبْدُ لِيُـنَجِّ يَهُ مِنْ نَـفْسِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 53, 'كَمَا فِي الَْحدِيثِ الْآخَرِ: «أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ ، وَبُِمعَافَاتِكَ مِنْ عُقُوبَتِكَ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 54, '(7) آل عمران- .21', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 55, 'وَأَعُوذُ بِكَ مِنْكَ » »7« ، فَـهُوَ سُبْحَانَهُ الهذِي يُعِيذُ عَبْدَهُ وَيُـنَجِّ يهِ مِنْ بَْأسِهِ الهذِي هُوَ بَِمشِيئَتِهِ وَقُدْرَتِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 56, 'فَمِنْهُ الْبَلَاءُ، وَمِنْهُ الِْإعَانَةُ، وَمِنْهُ مَا يَطْلُبُ النهجَاةَ مِنْهُ، وَإِلَيْهِ الِالْتِجَاءُ فِي النهجَاةِ، فَـهُوَ الهذِي يُـلْجَأُ إِلَيْهِ فِي أَنْ يُـنْجِيَ مِمها مِنْهُ، وَيُسْتَـعَاذُ بِهِ مِمها مِنْهُ، فَـهُوَ رَبُّ كُلِّ شَيْ ءٍ، وَلَا يَكُونُ شَيْءٌ إِهلا بَِمشِيئَتِهِ: وَإِنْ يَْمسَسْكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 57, 'ا هللَُّ بِضُرٍّ فَلا كاشِفَ لَهُ إِهلا هُوَ »2« قُلْ مَنْ ذَا الهذِي يَـعْصِمُكُمْ مِنَ ا هلِلَّ إِنْ أَرادَ بِكُمْ سُوءاً أَوْ أَرادَ بِكُمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 58, 'رَحْةًَْ »3« ُ مه خَتَمَ الدُّعَاءَ بِالِْإقْـرَارِ بِالِْإيَمانِ بِكِتَابِهِ وَرَسُولِهِ الهذِي هُوَ مَلَاكُ النهجَاةِ، وَالْفَوْزِ فِي الدُّنْـيَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 59, 'وَالْآخِرَةِ، فَـهَذَا هَدْيُهُ فِي نَـوْمِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 60, 'لَوْ لََْ يَـقُلْ إِنِّي رَسُولٌ لَكَا ... نَ شَاهِدٌ فِي هديه ينطق', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَمها هَدْيُهُ فِي يَـقَظَتِهِ، فَكَانَ يَسْتَـيْقِظُ إِذَا صَاحَ الصهارِخُ وَهُوَ الدِّيكُ ، فَـيَحْمَدُ ا هللََّ تَـعَالَى وَيُكَبِّهَُُ، وَيُـهَلِّلُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَيَدْعُوهُ، ُ مه يَسْتَاكُ، ُ مه يَـقُومُ إِلَى وُضُوئِهِ، ُ مه يَقِفُ لِلصهلَاةِ بَـيَْن يَدَيْ رَبِّهِ، مُنَاجِيًا لَهُ بِكَلَامِهِ، مُثْنِيًا عَلَيْهِ، رَاجِيًا لَهُ، رَاغِبًا رَاهِبًا، فَأَيُّ حِفْظٍ لِصِحهةِ الْقَلْبِ وَالْبَدَنِ، وَالرُّوحِ وَالْقُوَى، وَلِنَعِيمِ الدُّنْـيَا وَالْآخِرَةِ فوق هذا.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَمها تَدْبِيُر الَْحرَكَةِ وَالسُّكُونِ، وَهُوَ الرِّيَاضَةُ، فَـنَذْكُرُ مِنْـهَا فَصْلًا يُـعْلَمُ مِنْهُ مُطَابَـقَةُ هَدْيِهِ فِي ذَلِكَ لَِأكْمَلِ أَنْـوَاعِهِ وَأَحْدَِْهَا وَأَصْوَبَِها، فَـنَـقُولُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '(7) أخرجه مسلم في الصلاة. (2) الانعام- .71', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(3) الأحزاب- .71', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'مِنَ الْمَعْلُومِ افْتِقَارُ الْبَدَنِ فِي بَـقَائِهِ إِلَى الغذاء والشراب، ولا يصير الغذاء بمِلته جزآ من البدن، بل لابد أَنْ يَـبْـقَى مِنْهُ عِنْدَ كُلِّ هَضْمٍ بَقِيهةٌ مَا، إِذَا كَثُـرَتْ عَلَى مََمرِّ الهزمَانِ اجْتَمَعَ مِنْـهَا شَيْ ءٌ لَهُ كَمِّيهةٌ وَكَيْفِيهةٌ، فَـيَضُرُّ بِكَمِّيهتِهِ بَِأنْ يَسُده وَيُـثْقِلَ الْبَدَنَ، وَيُوجِبَ أَمْرَاضَ الِاحْتِبَاسِ ، وَإِنِ اسْتَـفْرَغَ تَذََهى الْبَدَنُ بِالَْأدْوِيَةِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'لَِأنه أَكْ ثَـرَهَا سُِّميهةٌ، وَلَا تَْخلُو مِنْ إِخْ رَاجِ الصهالِحِ الْمُنْـتَـفَعِ بِهِ، وَيَضُرُّ بِكَيْفِيهتِهِ، بَِأنْ يُسَخِّ نَ بِنَـفْسِهِ، أَوْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'بالعفن، أو يبدَ بنفسسه، أَوْ يُضْعِفَ الَْحرَارَةَ الْغَرِيزِيهةَ عَنْ إِنْضَاجِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَسُدَدُ الْفَضَلَاتِ لَا مَاَُلَةَ ضَارهةٌ تُركَِتْ ، أَوِ اسْتُـفْرِغَتْ ، والحركة أقوى الأسباب في منع تولدها، فإنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'تُسَخِّ نُ الَْأعْضَاءَ، وَتُسِيلُ فَضَلَاتَِها، فَلَا تَتََْمِعُ عَلَى طُولِ الهزمَانِ، وَتُـعَوِّدُ الْبَدَنَ الِْخهفةَ وَالنهشَاطَ، وَتَعََْلُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'قَابِلًا لِلْغِذَاءِ، وَتُصَلِّبُ الْمَفَاصِلَ، وَتُـقَوِّي الَْأوْتَارَ وَالرِّبَاطَاتِ، وَتُـؤَمِّنُ جَِيَعَ الَْأمْرَاضِ الْمَادِّيهةِ وَأَكْثَـرَ الَْأمْرَاضِ الْمِزَاجِيهةِ إِذَا اسْتُـعْمِلَ الْقَدْرُ الْمُعْتَدِلُ مِنْـهَا فِي وَقْتِهِ، وَكَانَ بَاقِي التهدْبِيِر صَوَابًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَوَقْتُ الرِّيَاضَةِ بَـعْدَ انِْدَْارِ الْغِذَاءِ، وَكَمَالِ الَْهضْمِ، وَالرِّيَاضَةُ الْمُعْتَدِلَةُ هِيَ الهتِي تَمََْرُّ فِيهَا الْبَشَرَةُ، وَتَـرْبُو', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَيَـتَـنَدهى بَِها الْبَدَنُ، وَأَمها الهتِي يَـلْزَمُهَا سَيَلَانُ الْعَرَقِ فَمُفْرِطَةٌ، وَأَيُّ عُضْوٍ كَثُـرَتْ  رِيَاضَتُهُ قَوِيَ، وَخُصُوصًا عَلَى نَـوْعِ تِلْكَ الرِّيَاضَةِ، بَلْ كُلُّ قُـهوةٍ فَـهَذَا شَأْنُـهَا، فَإِنه مَنِ اسْتَكْ ثَـرَ مِنَ الِْحفْظِ قَوِيَتْ حَافِظَتُهُ، وَمَنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'اسْتَكْ ثَـرَ مِنَ الْفِكْرِ قَوِيَتْ قُـهوتُهُ الْمُفَكِّرَةُ، وَلِكُلِّ عُضْوٍ رِيَاضَةٌ تَُخصُّهُ، فَلِلصهدْرِ الْقِرَاءَةُ، فليبتدىء فِيهَا مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'الُْخفْيَةِ إِلَى الَْجهْرِ بِتَدْرِيجٍ، وَرِيَاضَةُ السهمْعِ بِسَمْعِ الَْأصْوَاتِ، وَالْكَلَامِ بِالتهدْرِيجِ، فَـيَـنْـتَقِلُ مِنَ الَْأخَفِّ إِلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'الَْأثْـقَلِ، وَكَذَلِكَ رِيَاضَةُ اللِّسَانِ فِي الْكَلَامِ، وَكَذَلِكَ رِيَاضَةُ الْبَصَرِ، وَكَذَلِكَ رِيَاضَةُ الْمَشْيِ بِالتهدْرِيجِ شَيْـئًا فَشَيْـئًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَأَمها ركُُوبُ الَْخيْلِ، وَرَمْيُ النُّشهابِ، وَالصِّ رَاعُ، وَالْمُسَابَـقَةُ عَلَى الَْأقْدَامِ، فَرِيَاضَةٌ لِلْبَدَنِ كُلِّهِ، وَهِيَ قَالِعَةٌ لَِأمْرَاضٍ مُزْمِنَةٍ، كَالُْجذَامِ وَالِاسْتِسْقَاءِ، والقولنج.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَرِيَاضَةُ النُّـفُوسِ بِالتهـعَلُّمِ وَالتهأَدُّبِ، وَالْفَرَحِ وَالسُّرُورِ، وَالصهبَِْ وَالثهـبَاتِ، وَالِْإقْدَامِ وَالسهمَاحَةِ، وَفِعْلِ الَْخيِْر، وَنَوِْْ ذَلِكَ مِمها تَـرْتَاضُ بِهِ النُّـفُوسُ ، وَمِنْ أَعْظَمِ رِيَاضَتِهَا: الصهبْـرُ وَالُْحبُّ، وَالشهجَاعَةُ وَالِْإحْسَانُ، فَلَا تَـزَالُ تَـرْتَاضُ بِذَلِكَ شَيْـئًا فَشَيْـئًا حَ هتى تَصِيَر لََها هَذِهِ الصِّفَاتُ هَيْـئَاتٍ رَاسِخَةً، وَمَلَكَاتٍ ثَبَِتَةً.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَأَنْتَ إِذَا تَمََهلْتَ هَدْيَهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي ذَلِكَ ، وَجَدْتَهُ أَكْمَلَ هَدْيٍ حَافِظٍ لِلصِّحهةِ وَالْقُوَى، وَنَافِعٍ فِي الْمَعَاشِ وَالْمَعَادِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَلَا رَيْبَ أَنه الصلاة نفسها فيها من حفظ الْبَدَنِ، وَإِذَابَةِ أَخْلَاطِهِ وَفَضَلَاتِهِ مَا هُوَ مِنْ أَنْـفَعِ شَيْ ءٍ لَهُ سِوَى مَا فِيهَا مِنْ حِفْظِ صِحهةِ الِْإيَمانِ، وَسَعَادَةِ الدُّنْـيَا وَالْآخِرَةِ، وَكَذَلِكَ قِيَامُ اللهيْلِ مِنْ أَنْـفَعِ أَسْبَابِ حِفْظِ الصِّحهةِ، وَمِنْ أَمْنَعِ الُْأمُورِ لِكَثِيٍر مِنَ الَْأمْرَاضِ الْمُزْمِنَةِ، وَمِنْ أَنْشَطِ شَيْءٍ لِلْبَدَنِ وَالرُّوحِ وَالْقَلْبِ، كَمَا فِي «الصهحِيحَيِْن» عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، أَنههُ قَالَ: «يَـعْقِدُ الشهيْطَانُ عَلَى قَافِيَةِ رَأْسِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'أَحَدِكُمْ إِذَا هُوَ نَامَ ثَلَاثَ عُقَدٍ يَضْرِبُ عَلَى كُلِّ عُقْدَةٍ: عَلَيْكَ لَيْلٌ طَوِيلٌ، فَارْقُدْ، فَإِنْ هُوَ اسْتَـيْـقَظَ، فَذَكَرَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'ا هللََّ انْلَْهتْ عُقْدَةٌ، فَإِنْ تَـوَضهأَ، انْلَْهتْ عُقْدَةٌ ثَنَِيَةٌ، فَإِنْ صَلهى انْلَْهتْ عُقَدُهُ كُلُّهَا، فَأَصْبَحَ نَشِيطًا طَيِّبَ النهـفْسِ ، وَإِهلا أَصْبَحَ خَبِيثَ النهـفْسِ كَسْلَانَ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَفِي الصهوْمِ الشهرْعِيِّ مِنْ أَسْبَابِ حِفْظِ الصِّحهةِ وَرِيَاضَةِ الْبَدَنِ وَالنهـفْسِ مَا لَا يَدْفَـعُهُ صَحِيحُ الْفِطْرَةِ. وَأَمها الِْجهَادُ وَمَا فِيهِ مِنَ الَْحرَكَاتِ الْكُلِّيهةِ الهتِي هِيَ مِنْ أَعْظَمِ أَسْبَابِ الْقُهوةِ، وَحِفْظِ الصِّ حهةِ، وَصَلَابَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'الْقَلْبِ وَالْبَدَنِ، وَدَفْعِ فَضَلَاتِِهمَا، وَزَوَالِ الَْهمِّ وَالْغَمِّ وَالُْحزْنِ، فَأَمْرٌ إِهنَما يَـعْرِفُهُ مَنْ لَهُ مِنْهُ نَصِيبٌ ، وَكَذَلِكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'الَْحجُّ، وَفِعْلُ الْمَنَاسِكِ ، وكذلك المسابقة على الخيل، وبالنصال، والمشيء فِي الَْحوَائِجِ، وَإِلَى الِْإخْ وَانِ، وَقَضَاءُ حُقُوقِهِمْ، وَعِيَادَةُ مَرْضَاهُمْ، وَتَشْيِيعُ جَنَائِزِهِمْ، وَالْمَشْيُ إِلَى الْمَسَاجِدِ لِلْجُمُعَاتِ والجماعات، وحركة الوضوء والاغتسال، وغير ذلك.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, '(7) أخرجه البخاري في التهجير، ومسلم في صلاة المسافرين.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَمها الِْجمَاعُ وَالْبَاهُ، فَكَانَ هَدْيُهُ فِيهِ أَكْمَلَ هَدْيٍ ، يَْحفَظُ بِهِ الصِّحهةَ وَتَتِمُّ بِهِ اللهذهةُ وَسُرُورُ النهـفْسِ ، وَيَْحصُلُ بِهِ مَقَاصِدُهُ الهتِي وُضِعَ لَِأجْ لِهَا، فَإِنه الِْجمَاعَ وُضِعَ فِي الَْأصْلِ لِثَلَاثَةِ أُمُورٍ هِيَ مَقَاصِدُهُ الَْأصْلِيهةُ: أَحَدُهَا: حِفْظُ النهسْلِ، وَدَوَامُ النهـوْعِ إِلَى أَنْ تَـتَكَامَلَ الْعُدهةُ الهتِي قَدهرَ ا هللَُّ بُـرُوزَهَا إِلَى هَذَا الْعَالََِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الثهانِي: إِخْرَاجُ الْمَاءِ الهذِي يَضُرُّ احْ تِبَاسُهُ وَاحْتِقَانُهُ بِمُِْلَةِ الْبَدَنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الثهالِثُ : قَضَاءُ الْوَطَرِ، وَنَـيْلُ اللهذهةِ، وَالتهمَتُّعُ بِالنِّعْمَةِ، وَهَذِهِ وَحْدَهَا هِيَ الْفَائِدَةُ الهتِي فِي الَْجنهةِ، إِذْ لَا تَـنَاسُلَ هُنَاكَ، وَلَا احْ تِقَانَ يَسْتَـفْرِغُهُ الِْإنْـزَالُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَفُضَلَاءُ الَْأطِبهاءِ: يَـرَوْنَ أَنه الِْجمَاعَ مِنْ أَحَدِ أَسْبَابِ حِفْظِ الصِّحهةِ. قَالَ جالينوس: الْغَالِبُ عَلَى جَوْهَرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'الْمَنِِِّ النهارُ وَالَْهوَاءُ، وَمِزَاجُهُ حَارٌّ رَطْبٌ ، لَِأنه كَوْنَهُ مِنَ الدهمِ الصافي الذي تغتذي به الأعضاء الأصلية، وإذ ثَـبَتَ فَضْلُ الْمَنِِِّ. فَاعْلَمْ أَنههُ لَا يَـنْـبَغِي إِخْرَاجُهُ إِهلا فِي طَلَبِ النهسْلِ، أَوْ إِخْ رَاجُ الْمُحْتَقِنِ مِنْهُ، فَإِنههُ إِذَا دَامَ احْ تِقَانُهُ، أَحْدَثَ أَمْرَاضًا رَدِيئَةً، مِنْـهَا: الْوَسْوَاسُ ، وَالُْجنُونُ، وَالصهرَعُ وَغَيْـرُ ذلك، وقد يبىَء', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'اسْتِعْمَالُهُ مِنْ هَذِهِ الَْأمْرَاضِ كَثِيًرا، فَإِنههُ إِذَا طَالَ احْ تِبَاسُهُ، فَسَدَ وَاسْتَحَالَ إِلَى كَيْفِيهةٍ سُِّميهةٍ تُوجِبُ أَمْرَاضًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'رَدِيئَةً كَمَا ذكََرْنَا، وَلِذَلِكَ تَدْفَـعُهُ الطهبِيعَةُ بِالِاحْ تِلَامِ إِذَا كَثُـرَ عِنْدَهَا مِنْ غَيِْر جِاََعٍ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَقَالَ بَـعْضُ السهلَفِ: يَـنْـبَغِي لِلهرجُلِ أَنْ يتعاهد من نفسه ثلاثَ: ألايدع الْمَشْيَ ، فَإِنِ احْ تَاجَ إِلَيْهِ يَـوْمًا قَدَرَ عَلَيْهِ، وينبغي ألايدع الأكل، فإن أمعاءه تضيق، وينبغي ألايدع الِْجمَاعَ، فَإِنه الْبِئْـرَ إِذَا لََْ تُـنْـزَحْ ، ذَهَبَ مَاؤُهَا. وَقَالَ مُمَُهدُ بْنُ زكََرِهيا: مَنْ تَـرَكَ الِْجمَاعَ مُدهةً طَوِيلَةً، ضَعُفَتْ قُـوَى أَعْصَابِهِ، وَانْسَدهتْ مَاََرِيهَا، وَتَـقَلهصَ ذكََرُهُ. قَالَ: وَرَأَيْتُ جَاََعَةً تَـرَكُوهُ لِنَـوْعٍ مِنَ التهـقَشُّفِ، فَـبَـرُدَتْ أَبْدَانُـهُمْ، وَعَسُرَتْ حَرَكَاتُـهُمْ، وَوَقَـعَتْ عَلَيْهِمْ كَآبَةٌ بِلَا سَبَبٍ، وَقَـلهتْ شَهَوَاتُـهُمْ وهضمهم، انتهى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَمِنْ مَنَافِعِهِ: غَضُّ الْبَصَرِ، وَكَفُّ النهـفْسِ ، وَالْقُدْرَةُ عَلَى الْعِهفةِ عَنِ الَْحرَامِ، وَتَصَِْيلُ ذَلِكَ لِلْمَرْأَةِ، فَـهُوَ يَـنْـفَعُ نَـفْسَهُ فِي دُنْـيَاهُ وَأُخْرَاهُ، وَيَـنْـفَعُ الْمَرْأَةَ، وَلِذَلِكَ كَانَ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـتَـعَاهَدُهُ وَيُِحبُّهُ، وَيَـقُولُ: «حُبِّبَ إِلَهِ مِنْ دُنْـيَاكُمْ: النِّسَاءُ وَالطِّيبُ » »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَفِي كِتَابِ «الزُّهْدِ» لِلِْمَْامِ أَحْدََْ فِي هَذَا الَْحدِيثِ زِيَادَةٌ لَطِيفَةٌ، وَهِيَ : أَصْبَُِ عَنِ الطهعَامِ وَالشهرَابِ، وَلَا أَصْبَُِ عَنْـهُنه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَحَثه عَلَى التهـزْوِيجِ أُمهتَهُ فَـقَالَ: «تَـزَهوجُوا فَإِنِّي مُكَاثِرٌ بِكُمُ الُْأمَمَ» »2« . وَقَالَ ابْنُ عَبهاسٍ : خَيْـرُ هَذِهِ الُْأمهةِ أَكْثَـرُهَا نِسَاءً. »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَقَالَ: «إِنِّي أَتَـزَهوجُ النِّسَاءَ، وَأَنَامُ وَأَقُومُ، وَأَصُومُ وَأُفْطِرُ، فَمَنْ رَغِبَ عَنْ سُنهتِي فَـلَيْسَ مِنِِّ» »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَقَالَ: «يَا مَعْشَرَ الشهبَابِ! مَنِ اسْتَطَاعَ مِنْكُمُ الْبَاءَةَ فَـلْيَـتَـزَهوجْ ، فَإِنههُ أَغَضُّ لِلْبَصَرِ، وَأَحْفَظُ لِلْفَرْجِ، وَمَنْ لََْ يَسْتَطِعْ، فَـعَلَيْهِ بِالصهوْمِ، فَإِنههُ لَهُ وِجَاءٌ» »5« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَلَمها تَـزَهوجَ جابر ثَـيِّبًا قَالَ لَهُ: «هَهلا بِكْ رًا تُلَاعِبُـهَا وَتُلَاعِبُكَ » »1« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَفِي «سُنَنِهِ» أَيْضًا مِنْ حَدِيثِ ابْنِ عَبهاسٍ يَـرْفَـعُهُ قَالَ: «لََْ نَـرَ لِلْمُتَحَابهـيِْن مِثْلَ النِّكَاحِ» »1« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, '(7) أخرجه أحدْ، والنسائي في عشرة النساء. (2) أخرجه البيهقي في شعب الايمان.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, '(3) أخرجه البخاري.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, '(4) أخرجه البخاري ومسلم في النكاح. (5) أخرجه البخاري ومسلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, '(1) أخرجه البخاري في النكاح، ومسلم في المساقاة. (1) أخرجه ابن ماجة في النكاح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَفِي صَحِيحِ مسلم» مِنْ حَدِيثِ عبد الله بن عُمَرَ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «الدُّنْـيَا مَتَاعٌ، وَخَيْـرُ مَتَاعِ الدُّنْـيَا الْمَرْأَةُ الصهالَِحةُ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَكَانَ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَُحرِّضُ أُمهتَهُ عَلَى نِكَاحِ الَْأبْكَارِ الِْحسَانِ، وَذَوَاتِ الدِّينِ، وَفِي «سُنَنِ النهسَائِيِّ» عَنْ أَبِي هُرَيْـرَةَ قَالَ: سُئِلَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: أَيُّ النِّسَاءِ خَيْـرٌ؟ قَالَ: الهتِي تَسُرُّهُ إِذَا نَظَرَ، وَتُطِيعُهُ إِذَا أَمَرَ، وَلَا تَُخالِفُهُ فِيمَا يَكْ رَهُ فِي نَـفْسِهَا وَمَالِهِ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَفِي «الصهحِيحَيِْن» عَنْهُ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ: «تُـنْكَحُ الْمَرْأَةُ لِمَالَِها، وَلَِحسَبِهَا، وَلَِجمَالَِها، وَلِدِينِهَا، فَاظْفَرْ بِذَاتِ الدِّينِ، تَرِبَتْ يَدَاكَ» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'وَكَانَ يَُحثُّ عَلَى نِكَاحِ الْوَلُودِ، وَيَكْ رَهُ الْمَرْأَةَ الهتِي لَا تَلِدُ، كَمَا فِي «سُنَنِ أبي داود» عَنْ مَعْقِلِ بْنِ يَسَارٍ، أَنه رَجُلًا جَاءَ إِلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فَـقَالَ: إِنِّي أَصَبْتُ امْرَأَةً ذَاتَ حَسَبٍ وَجَاََلٍ، وَإِنهـهَا لَا تَلِدُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'أَفَأَتَـزَهوجُهَا؟ قَالَ: «لَا» ، ُ مه أَتَاهُ الثهانِيَةَ، فَـنَـهَاهُ، ُ مه أَتَاهُ الثهالِثَةَ، فَـقَالَ: «تَـزَهوجُوا الْوَدُودَ الْوَلُودَ، فَإِنِّي مُكَاثِرٌ بِكُمْ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'وَفِي الترمذي عَنْهُ مَرْفُوعًا: «أَرْبَعٌ مِنْ سُنَنِ الْمُرْسَلِيَن: النِّكَاحُ، وَالسِّ وَاكُ وَالتهـعَطُّرُ، وَالِْحنهاءُ» رُوِيَ فِي «الَْجامِعِ» بِالنُّونِ وَالْيَاءِ »4« وَسَِمعْتُ أبا الحجاج الحافظ يَـقُولُ: الصهوَابُ : أَنههُ الِْختَانُ، وَسَقَطَتِ النُّونُ مِنَ الَْحاشِيَةِ، وَكَذَلِكَ رَوَاهُ المحاملي عَنْ شَيْخِ أَبِي عِيسَى التِّْرمِذِيِّ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَمِمها يَـنْـبَغِي تَـقْدِيُمهُ عَلَى الِْجمَاعِ مُلَاعَبَةُ الْمَرْأَةِ، وَتَـقْبِيلُهَا، وَمَصُّ لِسَانَِها، وَكَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَسَلهمَ يُلَاعِبُ أَهْلَهُ، وَيُـقَبِّلُهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَرَوَى أبو داود فِي «سُنَنِهِ» أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ يُـقَبِّلُ عائشة، وَيَُمصُّ لِسَانَـهَا »5« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, '(7) أخرجه مسلم في الرضاع. والامام أحدْ والنسائي. (2) أخرجه النسائي في النكاح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, '(3) أخرجه البخاري في النكاح ومسلم في الرضاع. (4) أخرجه الترمذي في النكاح وأحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, '(5) أخرجه أبو داود في الصوم وأحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَيُذْكَرُ عَنْ جَابِرِ بْنِ عَبْدِ ا هلِلَّ قَالَ: نَـهَى رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَنِ الْمُوَاقَـعَةِ قَـبْلَ الْمُلَاعَبَةِ. وَكَانَ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ رُهبَما جَامَعَ نِسَاءَهُ كُلههُنه بِغُسْلٍ وَاحِدٍ، وَرُهبَما اغْتَسَلَ عِنْدَ كُلِّ وَاحِدَةٍ مِنْـهُنه، فَـرَوَى مسلم فِي «صَحِيحِهِ» عَنْ أنس، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، كَانَ يَطُوفُ عَلَى نِسَائِهِ بِغُسْلٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وَاحِدٍ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'وَرَوَى أبو داود فِي «سُنَنِهِ» عَنْ أَبِي رَافِعٍ مَوْلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'عَلَيْهِ وَسَلهمَ طَافَ عَلَى نِسَائِهِ فِي لَيْـلَةٍ، فَاغْتَسَلَ عِنْدَ كُلِّ امْرَأَةٍ مِنْـهُنه غُسْلًا، فَـقُلْتُ : يَا رَسُولَ ا هلِلَّ! لَوِ اغْتَسَلْتَ غُسْلًا وَاحِدًا، فَـقَالَ: «هَذَا أَزْكَى وَأَطْهَرُ وَأَطْيَبُ » »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'وَشُرعَِ لِلْمُجَامِعِ إِذَا أَرَادَ الْعَوْدَ قَـبْلَ الْغُسْلِ الْوُضُوءُ بَـيَْن الِْجمَاعَيِْن، كَمَا رَوَى مسلم فِي «صَحِيحِهِ» مِنْ حَدِيثِ أَبِي سَعِيدٍ الُْخدْرِيِّ ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, '«إِذَا أَتَى أَحَدُكُمْ أَهْلَهُ، ُ مه أَرَادَ أَنْ يَـعُودَ فَـلْيَـتَـوَضهأْ» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'وَفِي الْغُسْلِ وَالْوُضُوءِ بَـعْدَ الْوَطْ ءِ مِنَ النهشَاطِ، وَطِيبِ النهـفْسِ ، وَإِخْلَافِ بَـعْضِ مَا تَلََهلَ بِالِْجمَاعِ ، وَكَمَالِ الطُّهْرِ وَالنهظَافَةِ، وَاجْ تِمَاعِ الَْحارِّ الْغَرِيزِيِّ إِلَى دَاخِلِ الْبَدَنِ بَـعْدَ انْتِشَارِهِ بِالِْجمَاعِ ، وَحُصُولِ النهظَافَةِ الهتِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'يُِحبُّـهَا ا هللَُّ، وَيَـبْـغَضُ خِلَافَـهَا مَا هُوَ مِنْ أَحْسَنِ التهدْبِيِر فِي الجماع، وحفظ الصحة والقوى فيه.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَنْـفَعُ الِْجمَاعِ : مَا حَصَلَ بَـعْدَ الَْهضْمِ، وَعِنْدَ اعْتِدَالِ الْبَدَنِ فِي حَرِّهِ وَبَـرْدِهِ، وَيُـبُوسَتِهِ وَرُطُوبَتِهِ، وَخَلَائِهِ وَامْتِلَائِهِ. وَضَرَرُهُ عِنْدَ امْتِلَاءِ الْبَدَنِ أَسْهَلُ وَأَقَلُّ مِنْ ضَرَرِهِ عِنْدَ خُلُوِّهِ، وَكَذَلِكَ ضَرَرُهُ عِنْدَ كَثْـرَةِ الرُّطُوبَةِ أَقَلُّ مِنْهُ عِنْدَ اليبوسة، وعند', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '(7) أخرجه مسلم في الحيصن. (2) أخرجه أبو داود في الطهارة. (3) أخرجه مسلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'حَرَارَتِهِ أَقَلُّ مِنْهُ عِنْدَ بُـرُودَتِهِ، وَإِهنَما يَـنْـبَغِي أَنْ يَُجامِعَ إِذَا اشْتَدهتِ الشههْوَةُ، وَحَصَلَ الِانْتِشَارُ التهامُّ الهذِي لَيْسَ عَنْ تَكَلُّفٍ وَلَا فِكْرٍ فِي صُورَةٍ، وَلَا نَظَرٍ مُتَـتَابِعٍ، وَلَا يَـنْـبَغِي أَنْ يَسْتَدْعِيَ شَهْوَةَ الِْجمَاعِ وَيَـتَكَلهفَهَا، وَيَْحمِلَ نَـفْسَهُ عَلَيْـهَا، وَلْيُـبَادِرْ إِلَيْهِ إِذَا هَاجَتْ بِهِ كَثْـرَةُ الْمَنِِِّ، وَاشْتَده شَبَـقُهُ، وَلْيَحْذَرْ جِاََعَ الْعَجُوزِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَالصهغِيَرةِ الهتِي لَا يُوطَأُ مِثْـلُهَا، وَالهتِي لَا شَهْوَةَ لَهاَ، وَالْمَرِيضَةِ، وَالْقَبِيحَةِ الْمَنْظَرِ، وَالْبَغِيضَةِ، فَـوَطْ ءُ هَؤُلَاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'يُوهِنُ الْقُوَى، وَيُضْعِفُ الِْجمَاعَ بِالَْخاصِّ يهةِ، وَغَلِطَ مَنْ قَالَ مِنَ الَْأطِبهاءِ: إِنه جِاََعَ الثهـيِّبِ أَنْـفَعُ مِنْ جِاََعِ الْبِكْرِ وَأَحْفَظُ لِلصِّحهةِ، وَهَذَا مِنَ الْقِيَاسِ الْفَاسِدِ، حَ هتى رُهبَما حَذهرَ مِنْهُ بَـعْضُهُمْ، وَهُوَ مَُخالِفٌ لِمَا عَلَيْهِ عُقَلَاءُ النهاسِ ، وَلِمَا اتهـفَقَتْ عَلَيْهِ الطهبِيعَةُ وَالشهرِيعَةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَفِي جِاََعِ الْبِكْرِ مِنَ الَْخاصِّ يهةِ وَكَمَالِ التهـعَلُّقِ بَـيْـنَـهَا وَبَـيَْن مُاََمِعِهَا، وَامْتِلَاءِ قَـلْبِهَا مِنْ مَبَُهتِهِ، وَعَدَمِ تَـقْسِيمِ هَوَاهَا بَـيْـنَهُ وَبَـيَْن غَيِْرهِ، مَا لَيْسَ لِلثهـيِّبِ. وَقَدْ قَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لجابر: «هَهلا تَـزَهوجْتَ بِكْرًا» ، وَقَدْ جَعَلَ ا هللَُّ سُبْحَانَهُ مِنْ كَمَالِ نِسَاءِ أَهْلِ الَْجنهةِ مِنَ الُْحورِ الْعِيِن، أَنهـهُنه لََْ يَطْمِثْـهُنه أَحَدٌ قَـبْلَ مَنْ جُعِلْنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'لَهُ مِنْ أَهْلِ الَْجهنةِ. وَقَالَتْ عائشة لِلنهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: أَرَأَيْتَ لَوْ مَرَرْتَ بِشَجَرَةٍ قَدْ أُرْتِعَ فِيهَا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَشَجَرَةٍ لََْ يُـرْتَعْ فِيهَا، فَفِي أَيِّهِمَا كُنْتَ تُـرْتِعُ بَعِيَركَ؟ قَالَ: «فِي الهتِي لََْ يُـرْتَعْ فِيهَا» »7« . تُرِيدُ أَنههُ لََْ خََُْذْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'بِكْ رًا غَيْـرَهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَجِاََعُ الْمَرْأَةِ الْمَحْ بُوبَةِ فِي النهـفْسِ يَقِلُّ إِضْعَافُهُ لِلْبَدَنِ مَعَ كَثْـرَةِ اسْتِفْرَاغِهِ لِلْمَنِِِّ، وَجِاََعُ الْبَغِيضَةِ يُِحلُّ الْبَدَنَ، وَيُوهِنُ الْقُوَى مَعَ قِلهةِ اسْتِفْرَاغِهِ. وَجِاََعُ الَْحائِضِ حَرَامٌ طَبْـعًا وَشَرْعًا، فَإِنههُ مُضِرٌّ جِدًّا، وَالَْأطِبهاءُ قاطبة تذَر منه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَأَحْسَنُ أَشْكَالِ الِْجمَاعِ أَنْ يَـعْلُوَ الهرجُلُ الْمَرْأَةَ، مستفرشا لها بعد الملاعبة والبلة، وَبَِهذَا سُِّميَتِ الْمَرْأَةُ فِرَاشًا، كَمَا قَالَ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «الْوَلَدُ لِلْفِرَاشِ » »2« ، وَهَذَا مِنْ تَاََمِ قَـهوامِيهةِ الرُّجُلِ عَلَى الْمَرْأَةِ، كَمَا قَالَ تعالى: الرِّجالُ قَـهوامُونَ عَلَى النِّساءِ »3« ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '(7) أخرجه البخاري في نكاح الأبكار. (2) أخرجه البخاري في الوصايا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, '(3) النساء- .34', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَكَمَا قِيلَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'إِذَا رُمْتُـهَا كَانَتْ فِرَاشًا يُقِلُّنِِ ... وَعِنْدَ فَـرَاغِي خَادِمٌ يَـتَمَلهقُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَقَدْ قَالَ تَـعَالَى: هُنه لِباسٌ لَكُمْ وَأَنْـتُمْ لِباسٌ لَهنُه.، وَأَكْمَلُ اللِّبَاسِ وَأَسْبَـغُهُ عَلَى هَذِهِ الَْحالِ، فَإِنه فِرَاشَ الهرجُلِ لِبَاسٌ لَهُ، وَكَذَلِكَ لَِحافُ الْمَرْأَةِ لََها، فَـهَذَا الشهكْلُ الْفَاضِلُ مَأْخُوذٌ مِنْ هَذِهِ الْآيَةِ، وَبِهِ يَْحسُنُ مَوْقِعُ اسْتِعَارَةِ اللِّبَاسِ مِنْ كُلٍّ مِنَ الهزوْجَيِْن لِلْخَْرِ. وَفِيهِ وَجْ هٌ آخَرُ، وَهُوَ أَنهـهَا تَـنْـعَطِفُ عَلَيْهِ أَحْ يَانًا، فَـتَكُونُ عَلَيْهِ كَاللِّبَاسِ ، قَالَ الشهاعِرُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'إِذَا مَا الضهجِيعُ ثَـنَى جِيدَهَا ... تَـثَـنهتْ فَكَانَتْ عَلَيْهِ لِبَاسَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَأَرْدَأُ أَشْكَالِهِ أَنْ تَـعْلُوَهُ الْمَرْأَةُ، وَيَُجامِعَهَا عَلَى ظَهْرِهِ، وَهُوَ خِلَافُ الشهكْلِ الطهبِيعِيِّ الهذِي طَبَعَ ا هللَُّ عَلَيْهِ الهرجُلَ وَالْمَرْأَةَ، بَلْ نَـوْعَ الذهكَرِ وَالُْأنْـثَى، وَفِيهِ مِنَ الْمَفَاسِدِ، أَنه الْمَ ِ هنِ يَـتَـعَسهرُ خُرُوجُهُ كُلُّهُ، فَـرُهبَما بَقِيَ فِي الْعُضْوِ مِنْهُ فَـيَـتَـعَهفنُ وَيَـفْسُدُ، فَـيَضُرُّ وَأَيْضًا: فَـرُهبَما سَالَ إِلَى الذهكَرِ رُطُوبَاتٌ مِنَ الْفَرْجِ، وَأَيْضًا، فَإِنه الهرحِمَ لَا يَـتَمَكهنُ من الاشتمال على الماء واجتماعه فيه، وانضامه عَلَيْهِ لِتَخْلِيقِ الْوَلَدِ، وَأَيْضًا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'فَإِنه الْمَرْأَةَ مَفْعُولٌ بَِها طَبْـعًا وَشَرْعًا، وَإِذَا كَانَتْ فَاعِلَةً خَالَفَتْ مُقْتَضَى الطهبْعِ وَالشهرْعِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَكَانَ أَهْلُ الْكِتَابِ إِهنَما تََُْونَ النِّسَاءَ عَلَى جُنُوبِِهنِّ عَلَى حَرْفٍ، وَيَـقُولُونَ: هُوَ أَيْسَرُ لِلْمَرْأَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَكَانَتْ قُـرَيْشٌ وَالَْأنْصَارُ تَشْرَحُ النّساء على أقفائهن، فعابت اليهود عليهما ذَلِكَ ، فَأَنْـزَلَ ا هللَُّ عَهز وَجَله:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'نِساؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَ هنَ شِئْـتُمْ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'وَفِي «الصهحِيحَيِْن» عَنْ جابر، قَالَ: كَانَتِ الْيَـهُودُ تَـقُولُ: إِذَا أَتَى الهرجُلُ امْرَأَتَهُ مِنْ دُبُرِهَا فى قلبها، كَانَ الْوَلَدُ أَحْ وَلَ، فَأَنْـزَلَ ا هللَُّ عَهز وَجَله: نِساؤُكُمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, '(7) البقرة- .791', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَ هنَ شِئْـتُمْ. وَفِي لَفْظٍ لمسلم: «إِنْ شَاءَ مُبََِّيَةً، وَإِنْ شَاءَ غَيْـرَ مُبََِّيَةٍ، غَيْـرَ أَنه ذَلِكَ فِي صِمَامٍ وَاحِدٍ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَالْمُجَبِّيَةُ: الْمُنْكَبهةُ عَلَى وَجْ هِهَا، وَالصِّمَامُ الواحد: الفرج، وهو موضع الحرث والولد.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَأَمها الدُّبُـرُ: فَـلَمْ يُـبَحْ قَطُّ عَلَى لِسَانِ نَبٍِّ مِنَ الَْأنْبِيَاءِ، وَمَنْ نَسَبَ إِلَى بَـعْضِ السهلَفِ إِبَاحَةَ وَطْ ءِ الهزوْجَةِ فِي دُبُرِهَا، فَـقَدْ غَلِطَ عَلَيْهِ، وَفِي «سُنَنِ أبي داود» عَنْ أَبِي هُرَيْـرَةَ قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَلْعُونٌ مَنْ أَتَى الْمَرْأَةَ فِي دُبُرِهَا» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَفِي لَفْظٍ لأحدْ وَابْنِ مَاجَهْ: «لَا يَـنْظُرُ ا هللَُّ إِلَى رَجُلٍ جَامَعَ امْرَأَتَهُ فِي دُبُرِهَا» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'وَفِي لَفْظٍ لِلتِّْرمِذِيِّ وأحدْ: «مَنْ أَتَى حَائِضًا أَوِ امْرَأَةً فِي دُبُرِهَا أَوْ كَاهِنًا، فَصَدهقَهُ، فَـقَدْ كَفَرَ بَِما أُنْزِلَ عَلَى مُمَُهدٍ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَفِي لَفْظٍ للبيهقي: «مَنْ أَتَى شَيْـئًا مِنَ الرِّجَالِ وَالنِّسَاءِ فِي الَْأدْبَارِ فَـقَدْ كَفَرَ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'وَفِي «مُصَنهفِ وَكِيعٍ» : حَدهثَنِِ زمعة بن صالح، عَنِ ابن طاووس، عَنْ أَبِيهِ، عَنْ عَمْرِو بْنِ دِينَارٍ، عَنْ عبد الله بن يزيد، قَالَ: قَالَ عُمَرَ بْنِ الَْخطهابِ رَضِيَ ا هللَُّ عَنْهُ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إن الله لَا يَسْتَحْيِي مِنَ الَْحقِّ، لَا تَتَُْوا النِّسَاءَ فِي أَعْجَازِهِنه » . وَقَالَ مَ هرةً: «فِي أَدْبَارِهِنه» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَفِي الترمذي: عَنْ علي بن طلق، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وسلم: «لا تَتَُْوا النِّسَاءَ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'أَعْجَازِهِنه، فَإِنه ا هللََّ لَا يستحي مِنَ الَْحقِّ» »4« . وَفِي «الْكَامِلِ» لِابْنِ عَدِيٍّ : مِنْ حَدِيثِهِ عَنِ المحاملي، عَنْ سعيد بن يحيى الأموي، قال: حدّثنا محمد', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, '(7) أخرجه البخاري في التفسير، ومسلم. والآية التي في الحديث: الآية/ /223 من سورة البقرة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, '(2) أخرجه أحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, '(3) أخرجه الترمذي وابن ماجة وأحدْ وأبو داود والدارمي. (4) أخرجه الترمذي والدارمي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'ابن حزْة، عَنْ زيد بن رفيع، عَنْ أَبِي عُبَـيْدَةَ، عَنْ عَبْدِ ا هلِلَّ بْنِ مَسْعُودٍ يَـرْفَـعُهُ: «لَا تَتَُْوا النِّسَاءَ فِي أَعْجَازِهِنه» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'وَرُوِّينَا فِي حَدِيثِ الحسن بن علي الجوهري، عَنْ أبي ذر مَرْفُوعًا: «مَنْ أَتَى الرِّجَالَ أَوِ النِّسَاءَ فِي أَدْبَارِهِنه،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'فَـقَدْ كَفَرَ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'وَرَوَى إِسَْماعِيلُ بْنُ عَيهاشٍ ، عَنْ سُهَيْلِ بْنِ أَبِي صَالِحٍ، عَنْ مُمَُهدِ بْنِ الْمُنْكَدِرِ، عَنْ جابر يَـرْفَـعُهُ: «اسْتَحْ يُوا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'مِنَ ا هلِلَّ، فَإِنه ا هللََّ لَا يَسْتَحْيِي مِنَ الَْحقِّ، لَا تَتَُْوا النِّسَاءَ فِي حُشُوشِهِنه» . وَرَوَاهُ الدهارَقُطْنُِِّ مِنْ هَذِهِ الطهرِيقِ، وَلَفْظُهُ: «إِنه ا هللََّ لَا يَسْتَحْيِي مِنَ الَْحقِّ، لَا يَِحلُّ مَأْتَاكَ النِّسَاءَ فِي حُشُوشِهِنه» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'وَقَالَ البغوي: حَدهثَـنَا هُدْبَةُ، حَدهثَـنَا هاُم، قَالَ: سُئِلَ قتادة عَنِ الهذِي تََِْي امْرَأَتَهُ فِي دُبُرِهَا؟ فَـقَالَ: حَدهثَنِِ عَمْرُو بن شعيب، عن أبيه، عن جده، أن رسول الله هللا ىلص قال: «تِلْكَ اللُّوطِيهةُ الصُّغْرَى» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'وَقَالَ أحدْ فِي «مُسْنَدِهِ» : حَدهثَـنَا عبد الرحنْ، قَالَ: حَدهثَـنَا هاُم، أَخْبَـرَنَا عَنْ قتادة، عَنْ عَمْرِو بْنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، فَذَكَرَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'وَفِي «الْمُسْنَدِ» أَيْضًا: عَنِ ابْنِ عَبهاسٍ ، أُنْزِلَتْ هَذِهِ الْآيَةُ: نِساؤُكُمْ حَرْثٌ لَكُمْ فِي أُنَاسٍ مِنَ الَْأنْصَارِ، أَتَـوْا رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فَسَأَلُوهُ، فَـقَالَ: «ائْتِهَا عَلَى كُلِّ حَالٍ إِذَا كَانَ فِي الْفَرْجِ» »', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'وَفِي «الْمُسْنَدِ» أَيْضًا: عَنِ ابْنِ عَبهاسٍ ، قَالَ: جَاءَ عُمَرُ بْنُ الَْخطهابِ إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 48, 'فَـقَالَ «يَا رَسُولَ ا هلِلَّ، هَلَكْتُ ، فَـقَالَ: «وَمَا الهذِي أَهْلَكَكَ ؟» قَالَ: حَ هولْتُ رَحْلِي الْبَارِحَةَ، قَالَ: فَـلَمْ يَـرُده', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 49, 'عَلَيْهِ شَيْـئًا، فَأَوْحَى ا هللَُّ إِلَى رَسُولِهِ «نِساؤُكُمْ حَرْثٌ لَكُمْ، فَأْتُوا حَرْثَكُمْ أَ هنَ شِئْـتُمْ أقبل وأدبر، واتّق الحيضة والدّبر» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 50, '(7) أخرجه الدارقطنِ. (2) أخرجه أحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 51, '(3) أخرجه أحدْ والترمذي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 52, 'وَفِي الترمذي: عَنِ ابْنِ عَبهاسٍ مَرْفُوعًا: «لَا يَـنْظُرُ ا هللَُّ إِلَى رَجُلٍ أَتَى رَجُلًا أَوِ امْرَأَةً فِي الدُّبُرِ» »7« . وَرُوِّينَا مِنْ حَدِيثِ أبي علي الحسن بن الحسين بن دوما، عَنِ الْبَـرَاءِ بْنِ عَازِبٍ يَـرْفَـعُهُ: «كَفَرَ بِا هلِلَّ، الْعَظِيمِ عشرة من هذه الأمة: القا، وَالسهاحِرُ، وَالدهيُّوثُ ، وَنَاكِحُ الْمَرْأَةِ فِي دُبُرِهَا، وَمَانِعُ الهزكَاةِ، وَمَنْ وَجَدَ سَعَةً فَمَاتَ ، وَلََْ يَُحجه، وَشَارِبُ الَْخمْرِ، وَالسهاعِي فِي الْفِتَُِ، وَبَائِعُ السِّ لَاحِ مِنْ أَهْلِ الَْحرْبِ، وَمَنْ نَكَحَ ذَاتَ مَرَُْمٍ مِنْهُ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 53, 'وَقَالَ عَبْدُ ا هلِلَّ بْنُ وَهْبٍ: حَدهثَـنَا عبد الله بن لهيعة عن شرح بن هاعان، عَنْ عُقْبَةَ بْنِ عَامِرٍ، أَنه رسول الله', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 54, 'هللا ىلص قال: «مَلْعُونٌ مَنْ تََِْي النِّسَاءَ فِي مَاَُشِّهِنه. يَـعْنِِ: أَدْبَارَهُنه» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 55, 'وَفِي «مُسْنَدِ الَْحارِثِ بْنِ أَبِي أُسَامَةَ» ، مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ وَابْنِ عَبهاسٍ ، قَالَا «خَطَبَـنَا رَسُولُ ا هلِلَّ صَلهى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 56, 'ا هللَُّ عَلَيْهِ وَسَلهمَ قَـبْلَ وَفَاتِهِ، وَهِيَ آخِرُ خُطْبَةٍ خَطَبَـهَا بِالْمَدِينَةِ حتى لحق بالله عز وجل، وظنا فيها، وقال: «من نكح المرأة فِي دُبُرِهَا، أَوْ رَجُلًا أَوْ صَبِيًّا، حُشِرَ يَـوْمَ الْقِيَامَةِ، وَرِيُحهُ أَنْـتَُُ مِنَ الِْجيفَةِ يَـتَأَذهى بِهِ النهاسُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 57, 'حَ هتى يَدْخُلَ النهارَ، وَأَحْبَطَ ا هللَُّ أَجْ رَهُ، وَلَا يَـقْبَلُ مِنْهُ صَرْفًا وَلَا عَدْلًا، وَيُدْخَلُ فِي تَابُوتٍ مِنْ نَارٍ، وَيُشَدُّ عَلَيْهِ مسامير من نار» ، وقال أَبُو هُرَيْـرَةَ: هَذَا لِمَنْ لََْ يَـتُبْ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 58, 'وَذكََرَ أَبُو نُـعَيْمٍ الَْأصْبَـهَانُِّي، مِنْ حَدِيثِ خُزَيَْمةَ بْنِ ثبَت يرفعه، «إنّ الله لا يستحي مِنَ الَْحقِّ، لَا تَتَُْوا النِّسَاءَ فِي أَعْجَازِهِنه» »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 59, 'وَقَالَ الشهافِعِيُّ «أَخْ بَـرَنِي عَمِّي محمد بن علي بن شافع، قال: أخبنَي عبد الله ابن علي بن السائب، عَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 60, 'عمرو بن أحيحة بن الجلاح، عن خزيمة ابن ثبَت، أن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 61, '(7) أخرجه الترمذي وصححه ابن حبان. (2) رواه ابن عساكر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 62, '(3) أخرجه ابن عدي في الكامل. (4) ذكره في حلية الأولياء.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 63, 'رَجُلًا سَأَلَ النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَنْ إِتْـيَانِ النِّسَاءِ فِي أَدْبَارِهِنه، فَـقَالَ: «حَلَالٌ» ، فَـلَمها وَهلى، دَعَاهُ فَـقَالَ: «كَيْفَ قُـلْتَ ، فِي أَيِّ الُْخرْبَـتَـيِْن، أَوْ فِي أَيِّ الَْخرْزَتَـيِْن، أَوْ فِي أَيِّ الَْخصْفَتَـيِْن أَمِنْ دُبُرِهَا فِي قُـبُلِهَا؟ فَـنَـعَمْ. أَمْ مِنْ دُبُرِهَا فِي دُبُرِهَا، فَلَا، إِنه ا هللََّ لَا يَسْتَحْيِي مِنَ الَْحقِّ، لَا تَتَُْوا النِّسَاءَ فِي أَدْبَارِهِنه» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 64, 'قَالَ الهربِيعُ: فَقِيلَ لِلشهافِعِيِّ: فَمَا تَـقُولُ؟ فَـقَالَ: عَمِّي ثِقَةٌ، وعبد الله بن علي ثِقَةٌ، وَقَدْ أَثْـنَى عَلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 65, 'الَْأنْصَارِيِّ خَيْـرًا، يَـعْنِِ عمرو بن الجلاح، وخزيمة مِمهنْ لَا يُشَكُّ فِي ثِقَتِهِ، فَـلَسْتُ أُرَخِّصُ فيه، بل أنهى عنه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 66, 'قلت: ومن ها هنا نَشَأَ الْغَلَطُ عَلَى مَنْ نُقِلَ عَنْهُ الِْإبَاحَةُ مِنَ السهلَفِ وَالَْأئِمهةِ، فَإِنهـهُمْ أَبَاحُوا أَنْ يَكُونَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 67, 'الدُّبُـرُ طَرِيقًا إِلَى الْوَطْ ءِ فِي الْفَرْجِ، فَـيَطَأُ مِنَ الدُّبُرِ لَا فِي الدُّبُرِ، فَاشْتَـبَهَ عَلَى السهامِعِ «مِنْ » بِ «فِي» وَلََْ يَظُنه بَـيْـنَـهُمَا فَـرْقًا، فَـهَذَا الهذِي أَبَاحَهُ السهلَفُ وَالَْأئِمهةُ، فَـغَلِطَ عَلَيْهِمُ الْغَالِطُ أَقْـبَحَ الْغَلَطِ وَأَفْحَشَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 68, 'وَقَدْ قَالَ تعالى: فَأْتُوهُنه مِنْ حَيْثُ أَمَرَكُمُ ا هللَُّ قَالَ ماَهد: سَأَلْتُ ابْنَ عَبهاسٍ عَنْ قَـوْلِهِ تعالى: فَأْتُوهُنه مِنْ حَيْثُ أَمَرَكُمُ ا هللَُّ، فَـقَالَ: تَتَِْيهَا مِنْ حَيْثُ أُمِرْتَ أَنْ تَـعْتَزِلََها يَـعْنِِ فِي الَْحيْضِ . وَقَالَ علي بن أبي طلحة عَنْهُ، يَـقُولُ: فِي الْفَرْجِ، وَلَا تَـعْدُهُ إِلَى غَيِْرهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 69, 'وَقَدْ دَلهتِ الْآيَةُ عَلَى تَرَِْيِم الْوَطْ ءِ فِي دُبُرِهَا مِنْ وَجْهَيِْن: أَحَدُهُاَُ: أَنههُ أَبَاحَ إِتْـيَانَـهَا فِي الَْحرْثِ، وَهُوَ مَوْضِعُ الْوَلَدِ لَا فِي الُْحشِّ الهذِي هُوَ مَوْضِعُ الَْأذَى، وَمَوْضِعُ الَْحرْثِ هُوَ الْمُرَادُ مِنْ قَـوْلِهِ: )مِنْ حيث أمركم الله(', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 70, 'قال: فَأْتُوا حَرْثَكُمْ أَ هنَ شِئْـتُمْ وإتيانها في قلبها مِنْ دُبُرِهَا مُسْتَـفَادٌ مِنَ الْآيَةِ أَيْضًا لَِأنههُ قَالَ: أَ هنَ شِئْـتُمْ، أَيْ : مِنْ أَيْنَ شِئْـتُمْ مِنْ أَمَامٍ أَوْ مِنْ خَلْفٍ. قَالَ ابْنُ عباس: فأتوا حرثكم، يَـعْنِِ: الْفَرْجَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 71, 'وَإِذَا كَانَ ا هللَُّ حَ هرمَ الْوَطْ ءَ فِي الْفَرْجِ لَِأجْلِ الَْأذَى الْعَارِضِ ، فَمَا الظهنُّ بِالُْحشِّ الهذِي هُوَ مَلَُُّ الَْأذَى الهلازِمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 72, 'مَعَ زِيَادَةِ الْمَفْسَدَةِ بِالتهـعَرُّضِ لِانْقِطَاعِ النهسْلِ وَالذهرِيعَةِ الْقَرِيبَةِ جِدًّا مِنْ أَدْبَارِ النِّسَاءِ إِلَى أَدْبَارِ الصِّ بْـيَانِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 73, '(7) أخرجه ابن حبان.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 74, 'وَأَيْضًا: فَلِلْمَرْأَةِ حَقٌّ عَلَى الهزوْجِ فِي الْوَطْ ءِ، وَوَطْؤُهَا فِي دُبُرِهَا يُـفَوِّتُ حَقههَا، وَلَا يَـقْضِي وَطَرَهَا، وَلَا يَُحصِّلُ مَقْصُودَهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 75, 'وَأَيْضًا «فَإِنه الدُّبُـرَ لََْ يَـتَـهَيهأْ لَِهذَا الْعَمَلِ، وَلََْ يُْخلَقْ لَهُ، وإنما الذي هيىء لَهُ الْفَرْجُ، فَالْعَادِلُونَ عَنْهُ إِلَى الدُّبُرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 76, 'خَارِجُونَ عَنْ حِكْمَةِ ا هلِلَّ وَشَرْعِهِ جَِيَعًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 77, 'وَأَيْضًا: فَإِنه ذَلِكَ مُضِرٌّ بِالرُّجُلِ، وَلَِهذَا يَـنْـهَى عَنْهُ عُقَلَاءُ الَْأطِهباءِ مِنَ الْفَلَاسِفَةِ وَغَيِْرهِمْ، لَِأنه لِلْفَرْجِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 78, 'خَاصِّ يهةً فِي اجْتِذَابِ الْمَاءِ الْمُحْ تَـقَنِ وَرَاحَةِ الهرجُلِ مِنْهُ، وَالْوَطْ ءُ فِي الدُّبُرِ لَا يُعِيُن عَلَى اجْتِذَابِ جَِيَعِ الْمَاءِ، وَلَا يُْخرِجُ كُله الْمُحْتَـقَنِ لِمُخَالَفَتِهِ لِلْمَِْرِ الطهبِيعِيِّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 79, 'وَأَيْضًا: يَضُرُّ مِنْ وَجْهٍ آخَرَ، وَهُوَ إِحْ وَاجُهُ إِلَى حَرَكَاتٍ مُتْعِبَةٍ جِدًّا لِمُخَالَفَتِهِ لِلطهبِيعَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 80, 'وَأَيْضًا: فَإِنههُ مَلَُُّ الْقَذَرِ وَالنهجْوِ، فَـيَسْتَـقْبِلُهُ الهرجُلُ بِوَجْ هِهِ، وَيُلَابِسُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 81, 'وَأَيْضًا «فَإِنههُ يَضُرُّ بِالْمَرْأَةِ جِدًّا، لَِأنههُ وَارِدٌ غَرِيبٌ بَعِيدٌ عَنِ الطِّبَاعِ ، مُنَافِرٌ لََها غَايَةَ الْمُنَافَـرَةِ. وَأَيْضًا: فَإِنههُ يُْحدِثُ الْهمَه وَالْغَمه، وَالنُّـفْرَةَ عَنِ الْفَاعِلِ وَالْمَفْعُولِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 82, 'وَأَيْضًا: فَإِنههُ يُسَوِّدُ الْوَجْ هَ، وَيُظْلِمُ الصهدْرَ، وَيَطْمِسُ نُورَ الْقَلْبِ، وَيَكْسُو الْوَجْ هَ وَحْشَةً تَصِيُر عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 83, 'كَالسِّ يمَاءِ يَـعْرِفُـهَا مَنْ لَهُ أَدْنََ فِرَاسَةٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 84, 'وَأَيْضًا: فَإِنههُ يُوجِبُ النُّـفْرَةَ وَالتهـبَاغُضَ الشهدِيدَ، وَالتهـقَاطُعَ بَـيَْن الْفَاعِلِ وَالْمَفْعُولِ، وَلَا بُده.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 85, 'وَأَيْضًا فَإِنههُ يُـفْسِدُ حَالَ الْفَاعِلِ وَالْمَفْعُولِ فَسَادًا لَا يَكَادُ يُـرْجَى بَـعْدَهُ صَلَاحٌ، إِهلا أَنْ يَشَاءَ ا هللَُّ بِالتهـوْبَةِ النهصُوحِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 86, 'وَأَيْضًا: فَإِنههُ يَذْهَبُ بِالْمَحَاسِنِ مِنْـهُمَا، وَيَكْسُوهُاَُ ضِدههَا، كَمَا يَذْهَبُ بِالْمَوَدهةِ بَـيْـنَـهُمَا، وَيُـبْدِلُهمَُا بَِها تَـبَاغُضًا وَتَلَاعُنًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 87, 'وَأَيْضًا: فَإِنههُ مِنْ أَكْ بََِ أَسْبَابِ زَوَالِ النِّعَمِ، وَحُلُولِ النِّقَمِ، فَإِنههُ يُوجِبُ اللهعْنَةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 88, 'وَالْمَقْتَ مِنَ ا هلِلَّ، وَإِعْرَاضَهُ عَنْ فَاعِلِهِ، وَعَدَمَ نَظَرِهِ إِلَيْهِ، فَأَيه خَيٍْر يَـرْجُوهُ بَـعْدَ هَذَا، وَأَيه شَرٍّ مَََْنُهُ، وَكَيْفَ حَيَاةُ عَبْدٍ قَدْ حَلهتْ عَلَيْهِ لَعْنَةُ ا هلِلَّ وَمَقْتُهُ، وَأَعْرَضَ عَنْهُ بِوَجْ هِهِ، وَلََْ يَـنْظُرْ إِلَيْهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 89, 'وَأَيْضًا: فَإِنههُ يَذْهَبُ بِالَْحيَاءِ جُلََْةً، وَالَْحيَاءُ هُوَ حَيَاةُ الْقُلُوبِ فَإِذَا فَـقَدَهَا الْقَلْبُ ، اسْتَحْسَنَ الْقَبِيحَ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 90, 'وَاسْتَـقْبَحَ الَْحسَنَ، وَحِينَئِذٍ فَـقَدِ اسْتَحْكَمَ فَسَادُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 91, 'وَأَيْضًا: فَإِنههُ يُِحيلُ الطِّبَاعَ عَمها ركَهبَـهَا ا هللَُّ، وَيُْخرِجُ الِْإنْسَانَ عَنْ طَبْعِهِ إِلَى طَبْعٍ لََْ يُـرَكِّبِ ا هللَُّ عَلَيْهِ شَيْـئًا مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 92, 'حِينَئِذٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 93, 'الَْحيَـوَانِ، بَلْ هُوَ طَبْعٌ مَنْكُوسٌ ، وَإِذَا نُكِسَ الطهبْعُ انْـتَكَسَ الْقَلْبُ ، وَالْعَمَلُ، وَالْهدَُى، فَـيَسْتَطِيبُ الَْخبِيثَ مِنَ الَْأعْمَالِ وَالْهيَْـئَاتِ وَيَـفْسُدُ حَالُهُ وَعَمَلُهُ وَكَلَامُهُ بِغَيِْر اخْ تِيَارِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 94, 'وَأَيْضًا: فَإِنههُ يُورِثُ مِنَ الْوَقَاحَةِ وَالُْجرْأَةِ مَا لَا يُورِثُهُ سِوَاهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 95, 'وَأَيْضًا: فَإِنههُ يُورِثُ مِنَ الْمَهَانَةِ وَالسِّ فَالِ وَالَْحقَارَةِ مَا لَا يُورِثُهُ غَيْـرُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 96, 'وَأَيْضًا: فَإِنههُ يَكْسُو الْعَبْدَ مِنْ حُلهةِ الْمَقْتِ وَالْبَـغْضَاءِ، وَازْدِرَاءِ النهاسِ لَهُ، وَاحْ تِقَارِهِمْ إِهياهُ، وَاسْتِصْغَارِهِمْ لَهُ مَا هُوَ مُشَاهَدٌ بِالِْحسِّ فَصَلَاةُ ا هلِلَّ وَسَلَامُهُ عَلَى مَنْ سَعَادَةُ الدُّنْـيَا وَالْآخِرَةِ فِي هَدْيِهِ وَاتِّبَاعِ مَا جَاءَ بِهِ، وَهَلَاكُ الدُّنْـيَا وَالْآخِرَةِ فِي مَُخالَفَةِ هديه وما جاء به.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَالِْجمَاعُ الضهارُّ: نَـوْعَانِ: ضَارٌّ شَرْعًا، وَضَارٌّ طَبْـعًا. فَالضهارُّ شَرْعًا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الْمُحَ هرمُ، وَهُوَ مَرَاتِبُ بَـعْضُهَا أَشَدُّ مِنْ بَـعْضٍ . وَالتهحْرِيُم الْعَارِضُ مِنْهُ أَخَفُّ مِنَ الهلازِمِ، كَتَحْرِيِم الِْإحْرَامِ، وَالصِّيَامِ، وَالِاعْتِكَافِ، وَتَرَِْيِم الْمُظَاهَرِ مِنْـهَا قَـبْلَ التهكْفِيِر، وَتَرَِْيِم وَطْ ءِ الَْحائِضِ وَنَوِْْ ذَلِكَ ، وَلَِهذَا لَا حَده فِي هَذَا الِْجمَاعِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَأَمها الهلازِمُ: فَـنَـوْعَانِ. نَـوْعٌ لَا سَبِيلَ إِلَى حِلِّهِ الْبَـتهةَ، كَذَوَاتِ الْمَحَارِمِ، فَـهَذَا مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'أَضَرِّ الِْجمَاعِ ، وَهُوَ يُوجِبُ الْقَتْلَ حَدًّا عِنْدَ طَائِفَةٍ مِنَ الْعُلَمَاءِ، كَأَحْدََْ بْنِ حَنْـبَلٍ رَحِهَُْ ا هللَُّ وَغَيِْرهِ، وَفِيهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'حَدِيثٌ مَرْفُوعٌ ثَبَِتٌ ]7[ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَالثهانِي: مَا يُْمكِنُ أَنْ يَكُونَ حَلَالًا، كَالَْأجْ نَبِيهةِ، فَإِنْ كَانَتْ ذَاتَ زَوْجٍ، فَفِي وَطْئِهَا حَقهانِ. حَقٌّ هِلِلَّ، وَحَقٌّ لِلهزوْجِ. فَإِنْ كَانَتْ مُكْ رَهَةً، فَفِيهِ ثَلَاثَةُ حُقُوقٍ، وَإِنْ كَانَ لََها أَهْلٌ وَأَقَارِبُ يَـلْحَقُهُمُ الْعَارُ بِذَلِكَ صَارَ فِيهِ أَرْبَـعَةُ حُقُوقٍ، فَإِنْ كَانَتْ ذَاتَ مَرَُْمٍ مِنْهُ، صَارَ فِيهِ خَْمسَةُ حُقُوقٍ. فَمَضَ هرةُ هَذَا النهـوْعِ بَِحسَبِ دَرَجَاتِهِ فِي التهحْرِيِم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَأَمها الضهارُّ طَبْـعًا، فَـنَـوْعَانِ أَيْضًا: نَـوْعٌ ضَارٌّ بِكَيْفِيهتِهِ كَمَا تَـقَدهمَ، وَنَـوْعٌ ضَارٌّ بِكَمِّيهتِهِ كَالِْإكْ ثَارِ مِنْهُ، فَإِنههُ يُسْقِطُ الْقُهوةَ، وَيَضُرُّ بِالْعَصَبِ، وَيُْحدِثُ الهرعْشَةَ، وَالْفَالِجَ، وَالتهشَنُّجَ، وَيُضْعِفُ الْبَصَرَ وسائر القوى، ويطفىء الَْحرَارَةَ الْغَرِيزِيهةَ، وَيُـوَسِّعُ الْمَجَارِيَ، وَيَْجعَلُهَا مُسْتَعِدهةً لِلْفَضَلَاتِ الْمُؤْذِيَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَأَنْـفَعُ أَوْقَاتِهِ، مَا كَانَ بَـعْدَ انِْهضَامِ الْغِذَاءِ فِي الْمَعِدَةِ وَفِي زَمَانٍ مُعْتَدِلٍ لَا عَلَى جُوعٍ ، فَإِنههُ يُضْعِفُ الَْحاره الْغَرِيزِيه، وَلَا عَلَى شِبَعٍ، فَإِنههُ يُوجِبُ أَمْرَاضًا شَدِيدَةً، وَلَا عَلَى تَـعَبٍ، وَلَا إِثْـرَ حَهْامٍ، وَلَا اسْتِفْرَاغٍ وَلَا انْفِعَالٍ نَـفْسَانٍِّي كَالْغَمِّ وَالْهمَِّ وَالُْحزْنِ وَشِدهةِ الْفَرَحِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَأَجْ وَدُ أَوْقَاتِهِ بَـعْدَ هَزِيعٍ مِنَ اللهيْلِ إِذَا صَادَفَ انِْهضَامَ الطهعَامِ، ُ مه يَـغْتَسِلُ أَوْ يَـتَـوَضهأُ، وَيَـنَامُ عَلَيْهِ، وَيَـنَامُ عَقِبَهُ، فَـتَـرَاجَعُ إِلَيْهِ قُـوَاهُ، وَلْيَحْذَرِ الَْحرَكَةَ وَالرِّيَاضَةَ عَقِبَهُ، فَإِنهـهَا مُضِ هرةٌ جدا.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي عِلَاجِ الْعِشْقِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'هَذَا مَرَضٌ مِنْ أَمْرَاضِ الْقَلْبِ، مَُخالِفٌ لِسَائِرِ الَْأمْرَاضِ فِي ذَاتِهِ وَأَسْبَابِهِ وَعِلَاجِهِ، وَإِذَا تَكََهنَ وَاسْتَحْكَمَ عَهز عَلَى الَْأطِبهاءِ دواؤه، وأعيى الْعَلِيلَ دَاؤُهُ، وَإِهنَما حَكَاهُ ا هللَُّ سُبْحَانَهُ فِي كِتَابِهِ عَنْ طَائِفَتَـيِْن مِنَ النهاسِ : مِنَ النِّسَاءِ، وَعُشهاقِ الصِّ بْـيَانِ الْمُرْدَانِ، فَحَكَاهُ عَنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'امْرَأَةِ الْعَزِيزِ فِي شَأْنِ يُوسُفَ ، وَحَكَاهُ عَنْ قَـوْمِ لُوطٍ، فَـقَالَ تَـعَالَى إِخْ بَارًا عَنْـهُمْ لَمها جَاءَتِ الْمَلَائِكَةُ لُوطًا: وَجاءَ أَهْلُ الْمَدِينَةِ يَسْتَـبْشِرُونَ قالَ إِنه هؤُلاءِ ضَيْفِي فَلا تَـفْضَحُونِ وَاتهـقُوا ا هللََّ وَلا تُْخزُونِ قالُوا أَوَلََْ نَـنْـهَكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'عَنِ الْعالَمِيَن، قالَ هؤُلاءِ بَناتِي إِنْ كُنْـتُمْ فاعِلِيَن لَعَمْرُكَ إِنهـهُمْ لَفِي سَكْ رَتِِهمْ يَـعْمَهُونَ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَأَمها مَا زَعَمَهُ بَـعْضُ مَنْ لََْ يُـقَدِّرْ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ حَقه قَدْرِهِ أَنههُ ابْـتُلِيَ بِهِ فِي شَأْنِ زينب بنت جحش، وَأَنههُ رَآهَا فَـقَالَ «سُبْحَانَ مُقَلِّبِ الْقُلُوبِ» . وَأَخَذَتْ بِقَلْبِهِ، وَجَعَلَ يَـقُولُ لِزَيْدِ بْنِ حَارِثَةَ: أَمْسِكْهَا حَ هتى أَنْـزَلَ ا هللَُّ عَلَيْهِ: وَإِذْ تَـقُولُ لِلهذِي أَنْـعَمَ ا هللَُّ عَلَيْهِ وَأَنْـعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتهقِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'ا هللََّ وَتُْخفِي فِي نَـفْسِكَ ، مَا ا هللَُّ مُبْدِيهِ وَتَْخشَى النهاسَ وَا هللَُّ أَحَقُّ أَنْ تَْخشاهُ »2« ، فَظَنه هَذَا الهزاعِمُ أَنه ذَلِكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'فِي شَأْنِ الْعِشْقِ، وَصَنهفَ بَـعْضُهُمْ كِتَابًا فِي الْعِشْقِ، وَذكََرَ فِيهِ عِشْقَ الَْأنْبِيَاءِ، وَذكََرَ هَذِهِ الْوَاقِعَةَ، وَهَذَا مِنْ جَهْلِ هَذَا الْقَائِلِ بِالْقُرْآنِ وَبِالرُّسُلِ، وَتَمَِْيلِهِ كَلَامَ ا هلِلَّ مَا لَا يَْحتَمِلُهُ، وَنِسْبَتِهِ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَسَلهمَ إِلَى مَا بَـهرأَهُ ا هللَُّ مِنْهُ، فَإِنه زينب بنت جحش كَانَتْ تَتََْ زَيْدِ بْنِ حَارِثَةَ، وَكَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'عَلَيْهِ وَسَلهمَ قَدْ تَـبَـهناهُ، وَكَانَ يُدْعَى زيد بن محمد، وَكَانَتْ زينب فِيهَا شََممٌ وَتَـرَفُّعٌ عَلَيْهِ، فَشَاوَرَ رَسُولَ ا هلِلَّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي طَلَاقِهَا، فَـقَالَ لَهُ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وسلم: «أمسك عليك زوجك واتّق الله» وَأَخْفَى فِي نَـفْسِهِ أَنْ يَـتَـزَهوجَهَا إِنْ طَلهقَهَا زيد، وَكَانَ يَْخشَى مِنْ قَالَةِ النهاسِ أَنههُ تَـزَهوجَ امْرَأَةَ ابْنِهِ، لَِأنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'زيدا كَانَ يُدْعَى ابْـنَهُ، فَـهَذَا هُوَ الهذِي أَخْفَاهُ فِي نَـفْسِهِ، وَهَذِهِ هِيَ الَْخشْيَةُ مِنَ النهاسِ الهتِي وَقَـعَتْ لَهُ، وَلَِهذَا ذكََرَ سُبْحَانَهُ هَذِهِ الْآيَةَ يُـعَدِّدُ فِيهَا نِعَمَهُ عَلَيْهِ لَا يُـعَاتِبُهُ فِيهَا، وَأَعْلَمَهُ أَنههُ لَا يَـنْـبَغِي لَهُ أَنْ يَْخشَى النهاسَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'فِيمَا أَحَله ا هللَُّ لَهُ، وَأَنه ا هللََّ أَحَقُّ أَنْ يَْخشَاهُ، فَلَا يَـتَحَ هرجُ مَا أَحَلههُ لَهُ لَِأجْلِ قَـوْلِ النهاسِ ، ُ مه أَخْ بَـرَهُ أَنههُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'سُبْحَانَهُ زَهوجَهُ إِهياهَا بَـعْدَ قَضَاءِ زيد وَطَرَهُ مِنْـهَا لِتَـقْتَدِيَ أُمهتُهُ بِهِ فِي ذَلِكَ ، وَيَـتَـزَهوجَ الهرجُلُ بِامْرَأَةِ ابْنِهِ مِنَ التهـبَـنِِّ، لَا امْرَأَةِ ابْنِهِ لصلبه »3« ولهذا قال في آية', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, '(7) الحجر- -19 .11', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, '(2) الأحزاب- .31', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, '(3) لا صحة لهذا الحديث.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'التحريم: وَحَلائِلُ أَبْنائِكُمُ اهلذِينَ مِنْ أَصْلابِكُمْ »7« . وَقَالَ فِي هَذِهِ السُّورَةِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'مَا كانَ مُمَُهدٌ أَبا أَحَدٍ مِنْ رِجالِكُمْ »2« وَقَالَ فِي أَهولِهاَ: وَما جَعَلَ أَدْعِياءكَُمْ أَبْناءكَُمْ ذلِكُمْ قَـوْلُكُمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'بَِأفْواهِكُمْ »3« . فتأمّل هذا الذي عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَدَفْعَ طَعْنِ الطهاعِنِيَن عَنْهُ، وَبِا هلِلَّ التهـوْفِيقُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'نَـعَمْ كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يُِحبُّ نِسَاءَهُ، وَكَانَ أَحَبهـهُنُّ إِلَيْهِ عائشة رَضِيَ ا هللَُّ عَنْـهَا، وَلََْ تَكُنْ تَـبْـلُغُ مَبَُهـتُهُ لََها وَلَا لَِأحَدٍ سِوَى رَبِّهِ نَِهايَةَ الُْحبِّ ، بَلْ صَحه أَنههُ قَالَ: «لَوْ كُنْتُ مُتهخِذًا مِنْ أَهْلِ الَْأرْضِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'خليلا لأغذت أَبَا بَكْرٍ خَلِيلًا» »4« . وَفِي لَفْظٍ: «وَإِنه صَاحِبَكُمْ خليل الرّحنْ» »5« .', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَعِشْقُ الصُّوَرِ إِهنَما تُـبْـتَـلَى بِهِ الْقُلُوبُ الْفَارِغَةُ مِنْ مَبَُهةِ ا هلِلَّ تَـعَالَى، الْمُعْرِضَةُ عَنْهُ، الْمُتَـعَوِّضَةُ بِغَيِْرهِ عَنْهُ، فَإِذَا امْتَلََِ الْقَلْبُ مِنْ مَبَُهةِ ا هلِلَّ وَالشهوْقِ إِلَى لِقَائِهِ، دَفَعَ ذَلِكَ عَنْهُ مَرَضَ عِشْقِ الصُّوَرِ، وَلَِهذَا قَالَ تَـعَالَى فِي حَقِّ يُوسُفَ : كَذلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشاءَ إِنههُ مِنْ عِبادِنَا الْمُخْلَصِيَن [يُوسُفَ : ]24 ، فَدَ هل عَلَى أَنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الِْإخْلَاصَ سَبَبٌ لِدَفْعِ الْعِشْقِ وَمَا يَـتَـرَتهبُ عَلَيْهِ مِنَ السُّوءِ وَالْفَحْشَاءِ الهتِي هِيَ ثَرَََتُهُ وَنَتِيجَتُهُ، فَصَرْفُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'الْمُسَبهبِ صَرْفٌ لِسَبَبِهِ، وَلَِهذَا قَالَ بَـعْضُ السهلَفِ: الْعِشْقُ حَرَكَةُ قَـلْبٍ فَارغٍِ ، يَـعْنِِ فَارِغًا مِمها سِوَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'مَعْشُوقِهِ. قَالَ تَـعَالَى: وَأَصْبَحَ فُؤادُ أُمِّ مُوسى فارِغاً إِنْ كادَتْ لَتُـبْدِي بِهِ أَيْ : فَارِغًا مِنْ كُلِّ شَيْ ءٍ إِهلا مِنْ مُوسَى لِفَرْطِ مَبَُهتِهَا لَهُ، وَتَـعَلُّقِ قَـلْبِهَا بِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, '(7) النساء- .23 (2) الأحزاب- .41 (3) الأحزاب- .4', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(4) أخرجه البخاري في فضائل أصحاب النب صلّى الله عليه وسلم، ورواه مسلم في فضائل الصحابة. (5) أخرجه مسلم في فضائل الصحابة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَالْعِشْقُ مُرَكهبٌ مِنْ أَمْرَيْنِ: اسْتِحْسَانٍ لِلْمَعْشُوقِ، وَطَمَعٍ فِي الْوُصُولِ إِلَيْهِ، فَمَتَى انْـتَـفَى أَحَدُهُاَُ انْـتَـفَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'الْعِشْقُ، وَقَدْ أَعْيَتْ عِ هلةُ الْعِشْقِ عَلَى كَثِيٍر مِنَ الْعُقَلَاءِ وَتَكَلهمَ فِيهَا بَـعْضُهُمْ بِكَلَامٍ يُـرْغَبُ عَنْ ذِكْرِهِ إِلَى الصهوَابِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'فَـنَـقُولُ: قَدِ اسْتَـقَهرتْ حِكْمَةُ ا هلِلَّ- عَهز وَجَله- فِي خَلْقِهِ وَأَمْرِهِ عَلَى وُقُوعِ التهـنَاسُبِ وَالتهآلُفِ بَـيَْن الَْأشْبَاهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَانِْذَْابِ الشهيْ ءِ إِلَى مُوَافِقِهِ وَمُاََنِسِهِ بِالطهبْعِ، وَهُرُوبِهِ مِنْ مَُخالِفِهِ، وَنُـفْرَتِهِ عَنْهُ بِالطهبْعِ، فَسِرُّ التهمَازجُِ وَالِاتِّصَالِ فِي الْعَالََِ الْعُلْوِيِّ وَالسُّفْلِيِّ، إِهنَما هُوَ التهـنَاسُبُ وَالتهشَاكُلُ، وَالتهـوَافُقُ، وَسِرُّ التهـبَايُنِ وَالِانْفِصَالِ، إِهنَما هُوَ بِعَدَمِ التهشَاكُلِ وَالتهـنَاسُبِ، وَعَلَى ذَلِكَ قَامَ الَْخلْقُ وَالَْأمْرُ، فَالْمِثْلُ إِلَى مِثْلِهِ مَائِلٌ، وَإِلَيْهِ صَائِرٌ، وَالضِّدُّ عَنْ ضِدِّهِ هَارِبٌ ، وَعَنْهُ نَافِرٌ، وَقَدْ قَالَ تَـعَالَى «هُوَ الهذِي خَلَقَكُمْ مِنْ نَـفْسٍ واحِدَةٍ وَجَعَلَ مِنْها زَوْجَها لِيَسْكُنَ إِلَيْها »7« فَجَعَلَ سُبْحَانَهُ عِلهةَ سُكُونِ الهرجُلِ إِلَى امْرَأَتِهِ كَوْنَـهَا مِنْ جِنْسِهِ وَجَوْهَرِهِ، فَعِلهةُ السُّكُونِ الْمَذْكُورِ- وَهُوَ الُْحبُّ- كَوْنُـهَا مِنْهُ، فَدَ هل عَلَى أَنه الْعِلهةَ لَيْسَتْ بُِحسْنِ الصُّورَةِ، وَلَا الْمُوَافَـقَةِ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'الْقَصْدِ وَالِْإرَادَةِ، وَلَا فِي الُْخلُقِ وَالَْهدْيِ ، وَإِنْ كَانَتْ هَذِهِ أَيْضًا مِنْ أَسْبَابِ السُّكُونِ وَالْمَحَبهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَقَدْ ثَـبَتَ فِي «الصهحِيحِ» عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «الَْأرْوَاحُ جُنُودٌ مُنََهدَةٌ، فَمَا تَـعَارَفَ مِنْـهَا ائْـتَـلَفَ ، وَمَا تَـنَاكَرَ مِنْـهَا اخْتَـلَفَ » »2« وَفِي «مُسْنَدِ الِْإمَامِ أَحْدََْ» وَغَيِْرهِ فِي سَبَبِ هَذَا الَْحدِيثِ: أَنه امْرَأَةً بَِمكهةَ كَانَتْ تُضْحِكُ النهاسَ ، فَجَاءَتْ إِلَى الْمَدِينَةِ، فَـنَـزَلَتْ عَلَى امْرَأَةٍ تُضْحِكُ النهاسَ ، فَـقَالَ النهبُِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «الَْأرْوَاحُ جُنُودٌ مُهَنَدَةٌ» الَْحدِيثَ »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَقَدِ اسْتَـقَهرتْ شَرِيعَتُهُ سُبْحَانَهُ أَنه حُكْمَ الشهيْ ءِ حُكْمُ مِثْلِهِ، فَلَا تُـفَهرقُ شَرِيعَتُهُ بَـيَْن مُتَمَاثِلَيِْن أَبَدًا وَلَا تَمََْعُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'بَـيَْن مُتَضَادهيْنِ، وَمَنْ ظَنه خِلَافَ ذَلِكَ ، فَإِمها لِقِلهةِ عِلْمِهِ بِالشهرِيعَةِ، وَإِمها لِتَـقْصِ يِرهِ فِي مَعْرِفَةِ التهمَاثُلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَالِاخْتِلَافِ، وَإِمها لِنِسْبَتِهِ إِلَى شَرِيعَتِهِ مَا لََْ يُـنَـزِّلْ بِهِ سُلْطَانًا، بَلْ يَكُونُ مِنْ آرَاءِ الرِّجَالِ، فَبِحِكْمَتِهِ وَعَدْلِهِ ظهر خلقه وشرعه،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, '(7) الأعراف- .799', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, '(2) أخرجه البخاري في الأنبياء، ومسلم في البَ والصلة. (3) أخرجه أحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَبِالْعَدْلِ وَالْمِيزَانِ قَامَ الَْخلْقُ وَالشهرْعُ، وَهُوَ التهسْوِيَةُ بَـيَْن الْمُتَمَاثِلَيِْن، وَالتهـفْرِيقُ بَـيَْن الْمُخْ تَلِفَيِْن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'وَهَذَا كَمَا أَنههُ ثَبَِتٌ فِي الدُّنْـيَا، فَـهُوَ كَذَلِكَ يَـوْمَ الْقِيَامَةِ قَالَ تَـعَالَى: احْشُرُوا الهذِينَ ظَلَمُوا وَأَزْواجَهُمْ وَما كانُوا يَـعْبُدُونَ مِنْ دُونِ ا هلِلَّ فَاهْدُوهُمْ إِلى صِ راطِ الَْجحِيمِ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'قَالَ عُمَرُ بْنُ الَْخطهابِ رَضِيَ ا هللَُّ عَنْهُ وَبَـعْدَهُ الِْإمَامُ أَحْدَُْ رَحِهَُْ ا هللَُّ: أَزْوَاجُهُمْ أَشْبَاهُهُمْ ونظراؤهم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وقال تعالى: وَإِذَا النُّـفُوسُ زُوِّجَتْ »2« : قَـرَنَ كُله صَاحِبِ عَمَلٍ بِشَكْ لِهِ وَنَظِيِرهِ، فَـقَرَنَ بَـيَْن الْمُتَحَابهـيِْن فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'ا هلِلَّ فِي الَْجنهةِ، وَقَـرَنَ بين لَ تاَبين فِي طَاعَةِ الشهيْطَانِ فِي الَْجحِيمِ، فَالْمَرْءُ مَعَ مَنْ أَحَبه شَاءَ أَوْ أَبََ، وَفِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, '«مُسْتَدْرَكِ الَْحاكِمِ» وَغَيِْرهِ عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «لَا يُِحبُّ الْمَرْءُ قَـوْمًا إِهلا حُشِرَ معهم »3« . وَالْمَحَبهةُ أَنْـوَاعٌ مُتَـعَدِّدَةٌ فَأَفْضَلُهَا وَأَجَلُّهَا: الْمَحَبهةُ فِي ا هلِلَّ وَهِلِلَّ وَهِيَ تَسْتَـلْزِمُ مَبَُهةَ مَا أَحَبه ا هللَُّ، وَتَسْتَـلْزِمُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'مَبَُهةَ ا هلِلَّ وَرَسُولِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَمِنْـهَا مَبَُهةُ الِاتِّفَاقِ فِي طَرِيقَةٍ، أَوْ دِينٍ، أَوْ مَذْهَبٍ، أَوْ نِلَْْةٍ أَوْ قَـرَابَةٍ، أَوْ صِنَاعَةٍ أَوْ مراد ما.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'ومنها مّبُبة لِنَـيْلِ غَرَضٍ مِنَ الْمَحْ بُوبِ إِمها مِنْ جَاهِهِ أَوْ مِنْ مَالِهِ أَوْ مِنْ تَـعْلِيمِهِ وَإِرْشَادِهِ، أَوْ قَضَاءِ وَطَرٍ مِنْهُ، وَهَذِهِ هِيَ الْمَحَبهةُ الْعَرَضِ يهةُ الهتِي تَـزُولُ بِزَوَالِ مُوجِبِهَا، فَإِنه مَنْ وَدهكَ لَِأمْرٍ، وَهلى عَنْكَ عِنْدَ انْقِضَائِهِ. وَأَمها مَبَُهةُ الْمُشَاكَلَةِ وَالْمُنَاسَبَةِ الهتِي بَـيَْن الْمُحِبِّ وَالْمَحْ بُوبِ. فمحبة لازمة لا تزول', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, '(7) الصافات- .22 (2) التكوير- .1', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, '(3) أخرجه أحدْ والنسائي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'إِهلا لِعَارِضٍ يُزِيلُهَا، وَمَبَُهةُ الْعِشْقِ مِنْ هَذَا النهـوْعِ ، فَإِنهـهَا اسْتِحْسَانٌ رُوحَانٌِّي، وَامْتِزَاجٌ نَـفْسَانٌِّي، وَلَا يَـعْرِضُ فِي شَيْ ءٍ مِنْ أَنْـوَاعِ الْمَحَبهةِ مِنَ الْوَسْوَاسِ وَالنُّحُولِ، وَشَغْلِ الْبَالِ، وَالتهـلَفِ مَا يَـعْرِضُ من العشق.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'فَإِنْ قِيلَ: فَإِذَا كَانَ سَبَبُ الْعِشْقِ مَا ذكََرْتُْم مِنَ الِاتِّصَالِ وَالتهـنَاسُبِ الرُّوحَانِِّي، فَمَا بَالُهُ لَا يَكُونُ دَائِمًا مِنَ الطهرَفَـيِْن، بَلْ تَِدَُهُ كَثِيًرا مِنْ طَرَفِ الْعَاشِقِ وَحْدَهُ، فَـلَوْ كَانَ سَبَـبُهُ الِاتِّصَالَ النهـفْسِيه وَالِامْتِزَاجَ الرُّوحَانِيه، لَكَانَتِ الْمَحَبهةُ مُشْتَـرَكَةً بَـيْـنَـهُمَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'فَالَْجوَابُ : أَنه السهبَبَ قَدْ يَـتَخَلهفُ عَنْهُ مُسَبِّبُهُ لِفَوَاتِ شَرْطٍ، أَوْ لِوُجُودِ مَانِعٍ، وتخلّف المحبة من الجانب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'الآخر لابد أَنْ يَكُونَ لَِأحَدِ ثَلَاثَةِ أَسْبَابٍ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'الَْأهولُ: عِلهةٌ فِي الْمَحَبهةِ، وَأَنهـهَا مَبَُهةٌ عَرَضِ يهةٌ لَا ذَاتِيهةٌ، وَلَا يَِجبُ الِاشْ تَِراكُ فِي الْمَحَبهةِ الْعَرَضِ يهةِ، بَلْ قَدْ يَـلْزَمُهَا نُـفْرَةٌ مِنَ الْمَحْ بُوبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'الثهانِي: مَانِعٌ يقوم بالمحب يمنع مَبُُْوبِهِ لَهُ، إِمها فِي خُلُقِهِ، أَوْ فِي خَلْقِهِ أَوْ هَدْيِهِ أَوْ فِعْلِهِ، أَوْ هَيْـئَتِهِ أَوْ غَيِْر ذَلِكَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'الثهالِثُ : مَانِعٌ يَـقُومُ بِالْمَحْ بُوبِ يَْمنَعُ مُشَاركََتَهُ لِلْمُحِبِّ فِي مَبَُهتِهِ، وَلَوْلَا ذَلِكَ الْمَانِعُ، لَقَامَ بِهِ مِنَ الْمَحَبهةِ لِمُحِبِّهِ مِثْلُ مَا قَامَ بِالْآخَرِ، فَإِذَا انْـتَـفَتْ هَذِهِ الْمَوَانِعُ، وَكَانَتِ الْمَحَبهةُ ذَاتِيهةً، فَلَا يَكُونُ قَطُّ إِهلا مِنَ الَْجانِبَـيِْن، وَلَوْلَا مَانِعُ الْكِبَِْ وَالَْحسَدِ، وَالرِّيَاسَةِ وَالْمُعَادَاةِ فِي الْكُ هفارِ، لَكَانَتِ الرُّسُلُ أَحَبه إِلَيْهِمْ مِنْ أَنْـفُسِهِمْ وَأَهْلِيهِمْ وَأَمْوَالِِهمْ، وَلَمها زَالَ هَذَا الْمَانِعُ مِنْ قُـلُوبِ أَتْـبَاعِهِمْ، كَانَتْ مَبَُهـتُـهُمْ لَهمُْ فوق مبُة الأنفس والأهل والمال.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَالْمَقْصُودُ: أَنه الْعِشْقَ لَمها كَانَ مَرَضًا مِنَ الَْأمْرَاضِ ، كَانَ قَابِلًا لِلْعِلَاجِ، وَلَهُ أَنْـوَاعٌ مِنَ الْعِلَاجِ، فَإِنْ كَانَ مِمها لِلْعَاشِقِ سَبِيلٌ إِلَى وَصْلِ مَبُُْوبِهِ شَرْعًا وَقَدَرًا، فَـهُوَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'عِلَاجُهُ، كَمَا ثَـبَتَ فِي «الصهحِيحَيِْن» . مِنْ حَدِيثِ ابْنِ مَسْعُودٍ رَضِيَ ا هللَُّ عَنْهُ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «يَا مَعْشَرَ الشهبَابِ مَنِ اسْتَطَاعَ مِنْكُمُ الْبَاءَةَ فَـلْيَـتَـزَهوجْ، وَمَنْ لََْ يَسْتَطِعْ فَـعَلَيْهِ بِالصهوْمِ، فَإِنههُ لَهُ وِجَاءٌ» . فَدَ هل الْمُحِبه عَلَى عِلَاجَيِْن:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'أَصْلِيٌّ، وَبَدَلٌِِّ. وَأَمَرَهُ بِالَْأصْلِيِّ، وَهُوَ الْعِلَاجُ الهذِي وُضِعَ لَِهذَا الدهاءِ، فَلَا يَـنْـبَغِي الْعُدُولُ عَنْهُ إِلَى غَيِْرهِ مَا وَجَدَ إِلَيْهِ سَبِيلًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَرَوَى ابْنُ مَاجَهْ فِي «سُنَنِهِ» عَنِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْـهُمَا، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «لََْ نَـرَ لِلْمُتَحَابهـيِْن مِثْلَ النِّكَاحِ» . وَهَذَا هُوَ الْمَعْنَى الهذِي أَشَارَ إِلَيْهِ سُبْحَانَهُ عَقِيبَ إِحْلَالِ النِّسَاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'حَرَائِرِهِنه وَإِمَائِهِنه عِنْدَ الَْحاجَةِ بِقَوْلِهِ: يُرِيدُ ا هللَُّ أَنْ يَُخفِّفَ عَنْكُمْ وَخُلِقَ الِْإنْسانُ ضَعِيفاً [النِّسَاءِ: ]29 .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'فَذِكْ رُ تَْخفِيفِهِ فِي هَذَا الْمَوْضِ عِ، وَإِخْ بَارِهِ عَنْ ضَعْفِ الِْإنْسَانِ يَدُلُّ عَلَى ضَعْفِهِ عَنِ احْتِمَالِ هَذِهِ الشههْوَةِ، وَأَنههُ- سُبْحَانَهُ- خَ هففَ عَنْهُ أَمْرَهَا بَِما أَبَاحَهُ لَهُ مِنْ أَطَايِبِ النِّسَاءِ مثنى وثلاث ورباع، وأباح له ما شا مِمها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'مَلَكَتْ يَِمينُهُ، ُ مه أَبَاحَ لَهُ أَنْ يَـتَـزَهوجَ بِالِْإمَاءِ إِنِ احْ تَاجَ إِلَى ذَلِكَ عِلَاجًا لَِهذِهِ الشههْوَةِ، وَتَْخفِيفًا عَنْ هَذَا الَْخلْقِ الضهعِيفِ، ورحةْ به.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَإِنْ كَانَ لَا سَبِيلَ لِلْعَاشِقِ إِلَى وِصَالِ مَعْشُوقِهِ قَدَرًا أَوْ شَرْعًا، أَوْ هُوَ مُْمتَنِعٌ عَلْيِهِ مِنَ الِْجهَتَـيِْن، وَهُوَ الدهاءُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الْعُضَالُ، فَمِنْ عِلَاجِهِ إِشْعَارُ نَـفْسِهِ الْيَأْسَ مِنْهُ، فَإِنه النهـفْسَ مَتَى يَئِسَتْ مِنَ الشهيْ ءِ، اسْ تَـرَاحَتْ مِنْهُ، وَلََْ تَـلْتَفِتْ إِلَيْهِ، فَإِنْ لََْ يَـزَلْ مَرَضُ الْعِشْقِ مَعَ الْيَأْسِ ، فَـقَدِ انْرََْفَ الطهبْعُ انِْرَْافًا شَدِيدًا، فَـيَـنْـتَقِلُ إِلَى عِلَاجٍ آخَرَ، وَهُوَ عِلَاجُ عَقْلِهِ بَِأنْ يُـعْلَمَ بَِأنه تَـعَلُّقَ الْقَلْبِ بَِما لَا مَطْمَعَ فِي حُصُولِهِ نَـوْعٌ مِنَ الُْجنُونِ، وَصَاحِبُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'بَِمنْزِلَةِ مَنْ يَـعْشَقُ الشهمْسَ ، وَرُوحُهُ مُتَـعَلِّقَةٌ بِالصُّعُودِ إِلَيْـهَا وَالدهوَرَانِ مَعَهَا فِي فَـلَكِهَا، وَهَذَا مَعْدُودٌ عِنْدَ جَِيَعِ الْعُقَلَاءِ فِي زُمْرَةِ الْمَجَانِيِن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَإِنْ كَانَ الْوِصَالُ مُتَـعَذِّرًا شَرْعًا لَا قَدَرًا، فَعِلَاجُهُ بَِأنْ يُـنْزِلَهُ مَنْزِلَةَ الْمُتَـعَذِّرِ قَدَرًا، إِذْ مَا لََْ ذَََْنْ فِيهِ ا هللَُّ، فَعِلَاجُ الْعَبْدِ وَنَاَْتُهُ مَوْقُوفٌ عَلَى اجْ تِنَابِهِ، فَـلْيُشْعِرْ نَـفْسَهُ أَنههُ مَعْدُومٌ مُْمتَنِعٌ لَا سَبِيلَ لَهُ إِلَيْهِ، وَأَنههُ بَِمنْزِلَةِ سَائِرِ الْمُحَالَاتِ، فَإِنْ لََْ تُِبَْهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'النهـفْسُ الَْأمهارَةُ، فَـلْيَـتْـرُكْ هُ لَِأحَدِ أَمْرَيْنِ: إِمها خَشْيَةً، وَإِمها فَـوَاتَ مَبُُْوبٍ هُوَ أَحَبُّ إِلَيْهِ، وَأَنْـفَعُ لَهُ، وَخَيْـرٌ لَهُ مِنْهُ، وَأَدْوَمُ لَذهةً وَسُرُورًا، فَإِنه الْعَاقِلَ مَتَى وَازَنَ بَـيَْن نَـيْلِ مَبُُْوبٍ سَرِيعِ الهزوَالِ بِفَوَاتِ مَبُُْوبٍ أَعْظَمَ مِنْهُ، وَأَدْوَمَ، وَأَنْـفَعَ، وَأَلَذه أَوْ بِالْعَكْسِ ، ظَهَرَ لَهُ التهـفَاوُتُ ، فَلَا تَبِعْ لَذهةَ الَْأبَدِ الهتِي لَا خَطَرَ لََها بِلَذهةِ سَاعَةٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'تَـنْـقَلِبُ آلَامًا، وَحَقِيقَتُـهَا أَنهـهَا أَحْلَامُ نَائِمٍ، أَوْ خَيَالٌ لَا ثَـبَاتَ لَهُ، فَـتَذْهَبُ اللهذهةُ، وَتَـبْـقَى التهبِعَةُ، وَتَـزُولُ الشههْوَةُ، وَتَـبْـقَى الشِّ قْوَةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الثهانِي: حُصُولُ مَكْ رُوهٍ أَشَقُّ عَلْيِهِ مِنْ فَـوَاتِ هَذَا الْمَحْ بُوبِ، بَلْ يَْجتَمِعُ لَهُ الَْأمْرَانِ، أَعْنِِ: فَـوَاتَ مَا هُوَ أَحَبُّ إِلَيْهِ مِنْ هَذَا الْمَحْ بُوبِ، وَحُصُولَ مَا هُوَ أَكْ رَهُ إِلَيْهِ مِنْ فَـوَاتِ هَذَا الْمَحْبُوبِ، فَإِذَا تَـيَـقهنَ أَنه فِي إِعْطَاءِ النهـفْسِ حَظههَا مِنْ هَذَا الْمَحْ بُوبِ هَذَيْنِ الَْأمْرَيْنِ، هَانَ عَلَيْهِ تَـرْكُهُ، وَرَأَى أَنه صَبْـرَهُ عَلَى فَـوْتِهِ أَسْهَلُ مِنْ صَبِْهَِ عَلَيْهِمَا بِكَثِيٍر، فَـعَقْلُهُ وَدِينُهُ، وَمُرُوءَتُهُ وَإِنْسَانِيهـتُهُ، تَمَُْرُهُ بِاحْتِمَالِ الضهرَرِ الْيَسِيِر الهذِي يَـنْـقَلِبُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'سَرِيعًا لَذهةً وَسُرُورًا وَفَـرَحًا لِدَفْعِ هَذَيْنِ الضهرَرَيْنِ الْعَظِيمَيِْن. وَجَهْلُهُ وَهَوَاهُ، وَظُلْمُهُ وَطَيْشُهُ، وَخِهفتُهُ مََُْرُهُ بِِإيثَارِ هَذَا الْمَحْ بُوبِ الْعَاجِلِ بَِما فِيهِ جَالِبًا عَلَيْهِ مَا جَلَبَ ، وَالْمَعْصُومُ مَنْ عَصَمَهُ ا هللَُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'فَإِنْ لََْ تَـقْبَلْ نَـفْسُهُ هَذَا الدهوَاءَ، وَلََْ تُطَاوِعْهُ لَِهذِهِ الْمُعَالََجةِ، فَـلْيَـنْظُرْ مَا تَلَِْبُ عَلَيْهِ هَذِهِ الشههْوَةُ مِنْ مَفَاسِدِ عَاجِلَتِهِ، وَمَا تَنََْـعُهُ مِنْ مَصَالِِحهَا، فَإِنهـهَا أَجْلَبُ شَيْءٍ لِمَفَاسِدِ الدُّنْـيَا، وَأَعْظَمُ شَيْ ءٍ تَـعْطِيلًا لِمَصَالِِحهَا، فَإِنهـهَا تَوَُلُ بَـيَْن الْعَبْدِ وَبَـيَْن رُشْدِهِ الهذِي هُوَ مِلَاكُ أَمْرِهِ، وَقِوَامُ مَصَالِِحهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'فَإِنْ لََْ تَـقْبَلْ نَـفْسُهُ هَذَا الدهوَاءَ، فَـلْيَـتَذَكهرْ قَـبَائِحَ الْمَحْ بُوبِ، وَمَا يَدْعُوهُ إِلَى النُّـفْرَةِ عَنْهُ، فَإِنههُ إِنْ طَلَبَـهَا وَتَمََهلَهَا، وَجَدَهَا أَضْعَافَ مَاَُسِنِهِ الهتِي تدعوا إِلَى حُبِّهِ، وَلْيَسْأَلْ جِيَرانَهُ عَمها خَفِيَ عَلَيْهِ منها، فإن المحاسن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'كما هي داعية الحب والإرادة، فالمساوىء دَاعِيَةُ الْبُـغْضِ وَالنُّـفْرَةِ، فَـلْيُـوَازِنْ بَـيَْن الدهاعِيَـيِْن، وَلْيُحِبه أسبقهما وأقربهما منه بَابًا، وَلَا يَكُنْ مِمهنْ غَهرهُ لَوْنُ جَاََلٍ عَلَى جِسْمٍ أَبْـرَصَ مَذَُْومٍ وَلْيُجَاوِزْ بَصَرُهُ حُسْنَ الصُّورَةِ إِلَى قُـبْحِ الْفِعْلِ، وَلْيَـعْبُـرْ مِنْ حُسْنِ الْمَنْظَرِ وَالِْجسْمِ إِلَى قُـبْحِ الْمَخْبََِ وَالْقَلْبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'فَإِنْ عَجَزَتْ عَنْهُ هَذِهِ الَْأدْوِيَةُ كُلُّهَا لََْ يَـبْقَ له إلا صدق الملجأ إِلَى مَنْ يُِجيبُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'الْمُضْطَهر إِذَا دَعَاهُ، وَلْيَطْرَحْ نَـفْسَهُ بَـيَْن يَدَيْهِ عَلَى بَابِهِ، مُسْتَغِيثًا بِهِ، مُتَضَرِّعًا، مُتَذَلِّلًا، مُسْتَكِينًا، فَمَتَى وُفِّقَ لِذَلِكَ ، فَـقَدْ قَـرَعَ بَابَ التهـوْفِيقِ، فَـلْيَعِفه وَلْيَكْتُمْ، وَلَا يُشَبِّبْ بِذِكْرِ الْمَحْبُوبِ، وَلَا يَـفْضَحْهُ بَـيَْن النهاسِ وَيُـعَرِّضْهُ لِلْذََِى، فَإِنههُ يَكُونُ ظالما معتديا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَلَا يَـغْتَـهر بِالَْحدِيثِ الْمَوْضُوعِ عَلَى رَسُولِ ا هلِلَّ هللا ىلص الذي رَوَاهُ سُوَيْدُ بْنُ سَعِيدٍ، عَنْ عَلِيِّ بْنِ مُسْهِرٍ، عَنْ أبي يحيى القتات، عَنْ ماَهد، عَنِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْـهُمَا، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَرَوَاهُ عَنْ أَبِي مُسْهِرٍ أَيْضًا، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عائشة، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَرَوَاهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'الزُّبَـيْـرُ بْنُ بَكهارٍ، عَنْ عَبْدِ الْمَلِكِ بْنِ عَبْدِ الْعَزِيزِ بْنِ الْمَاجِشُونِ، عَنْ عَبْدِ الْعَزِيزِ بْنِ أَبِي حَازِمٍ، عَنْ ابْنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'أَبِي نَيِْحٍ، عَنْ ماَهد، عَنِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْـهُمَا، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «مَنْ عَشِقَ، فَـعَفه ، فَمَاتَ فَـهُوَ شَهِيدٌ» وَفِي رِوَايَةٍ: «مَنْ عَشِقَ وَكَتَمَ وَعَفه وَصَبَـرَ، غَفَرَ ا هللَُّ لَهُ، وَأَدْخَلَهُ الَْجنهةَ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'فَإِنه هَذَا الَْحدِيثَ لَا يَصِحُّ عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَلَا يَُجوزُ أَنْ يَكُونَ مِنْ كَلَامِهِ، فَإِنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'شَرْطٌ فِي حُصُولَِها،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'الشههَادَةَ دَرَجَةٌ عَالِيَةٌ عِنْدَ ا هلِلَّ، مَقْرُونَةٌ بِدَرَجَةِ الصِّدِّيقِيهةِ، وَلََها أَعْمَالٌ وَأَحْ وَالٌ، هِيَ وَهِيَ نَـوْعَانِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'عَامهةٌ وَخَاصهةٌ، فَالَْخاصهةُ: الشههَادَةُ فِي سَبِيلِ ا هلِلَّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَالْعَامهةُ خَْمسٌ مَذْكُورَةٌ فِي «الصهحِيحِ» »2« لَيْسَ الْعِشْقُ وَاحِدًا مِنْـهَا. وَكَيْفَ يَكُونُ الْعِشْقُ الهذِي هُوَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'شِرْكٌ فِي الْمَحَبهةِ، وَفَـرَاغُ الْقَلْبِ عَنِ ا هلِلَّ، وَتَلَِْيكُ الْقَلْبِ وَالرُّوحِ، وَالُْحبُّ لِغَيِْرهِ تُـنَالُ بِهِ دَرَجَةُ الشههَادَةِ، هَذَا مِنَ الْمُحَالِ، فَإِنه إِفْسَادَ عِشْقِ الصُّوَرِ لِلْقَلْبِ فَـوْقَ كُلِّ إِفْسَادٍ، بَلْ هُوَ خَْمرُ الرُّوحِ الهذِي يُسْكِرُهَا، وَيَصُدُّهَا عَنْ ذِكْرِ ا هلِلَّ وَحُبِّهِ، وَالتهـلَذُّذِ بُِمنَاجَاتِهِ، وَالُْأنْسِ بِهِ، وَيُوجِبُ عُبُودِيهةَ الْقَلْبِ لِغَيِْرهِ، فَإِنه قَـلْبَ الْعَاشِقِ مُتَـعَبِّدٌ لِمَعْشُوقِهِ، بَلِ الْعِشْقُ لُبُّ الْعُبُودِيهةِ، فَإِنهـهَا كَمَالُ الذُّلِّ، وَالُْحبِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, '(7) أخرجه الخطيب البغدادي في تاريخه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, '(2) والعامة خمس مذكورة في الصحيح: في البخاري: «الشهداء خمسة: المطعون والفرق وصاحب الهدم، والشهيد في سبيل الله.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'وَالُْخضُوعِ وَالتهـعْظِيمِ، فَكَيْفَ يَكُونُ تَـعَبُّدُ الْقَلْبِ لِغَيِْر ا هلِلَّ مِمها تُـنَالُ بِهِ دَرَجَةُ أَفَاضِلِ الْمُوَحِّدِينَ وَسَادَاتِِهمْ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَخَوَاصِّ الَْأوْلِيَاءِ، فَـلَوْ كَانَ إِسْنَادُ هَذَا الَْحدِيثِ كَالشهمْسِ ، كَانَ غَلَطًا وَوَ هًْاُ، وَلَا يُْحفَظُ عَنْ رَسُولِ ا هلِلَّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'صَلهى ا هللَُّ عَلَيْهِ وَسَ هلمَ لَفْظُ الْعِشْقِ فِي حَدِيثٍ صَحِيحٍ الْبَـتهةَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'ُ مه إِنه الْعِشْقَ مِنْهُ حَلَالٌ، وَمِنْهُ حَرَامٌ، فَكَيْفَ  يُظَنُّ بِالنهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ يَْحكُمُ عَلَى كُلِّ عَاشِقٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'يَكْتُمُ وَيَعِفُّ بَِأنههُ شَهِيدٌ، فَـتَـرَى مَنْ يَـعْشَقُ امْرَأَةَ غَيِْرهِ، أَوْ يَـعْشَقُ الْمُرْدَانَ وَالْبَـغَايَا، يَـنَالُ بِعِشْقِهِ دَرَجَةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'الشُّهَدَاءِ، وَهَلْ هَذَا إِهلا خِلَافُ الْمَعْلُومِ مِنْ دِينِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَ هلمَ بِالضهرُورَةِ؟ كَيْفَ وَالْعِشْقُ مَرَضٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'مِنَ الَْأمْرَاضِ الهتِي جَعَلَ ا هللَُّ سُبْحَانَهُ لََها الَْأدْوِيَةَ شَرْعًا وَقَدَرًا، وَالهتدَاوِي مِنْهُ إِمها وَاجِبٌ إِنْ كَانَ عِشْقًا حَرَامًا، وَإِمها مُسْتَحَبٌّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَأَنْتَ إِذَا تَمََهلْتَ الَْأمْرَاضَ وَالْآفَاتِ الهتِي حُكْمِ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لَِأصْحَابَِها بِالشههَادَةِ، وَجَدْتَـهَا مِنَ الَْأمْرَاضِ الهتِي لَا عِلَاجَ لها، كالمطعون، والمبطون، والمجنون، والحريق، وَالْغَرِيقِ، وَمَوْتِ الْمَرْأَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'يَـقْتُـلُهَا وَلَدُهَا فِي بَطْنِهَا، فَإِنه هَذِهِ بَلَايَا مِنَ ا هلِلَّ لَا صُنْعَ لِلْعَبْدِ فِيهَا، وَلَا عِلَاجَ لََها، وَلَيْسَتْ أَسْبَابُـهَا مُهَُرمَةً، وَلَا يَـتَـرَتهبُ عَلَيْـهَا مِنْ فَسَادِ الْقَلْبِ وَتَـعَبُّدِهِ لِغَيِْر ا هلِلَّ مَا يَـتَـرَتهبُ عَلَى الْعِشْقِ، فَإِنْ لََْ يَكْفِ هَذَا فِي إِبْطَالِ نِسْبَةِ هَذَا الَْحدِيثِ إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَـقَلِّدْ أَئِمهةَ الَْحدِيثِ الْعَالِمِيَن بِهِ وَبِعِلَلِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'فَإِنههُ لَا يُْحفَظُ عَنْ إِمَامٍ وَاحِدٍ مِنْـهُمْ قَطُّ أَنههُ شَهِدَ لَهُ بِصِحهةٍ، بَلْ وَلَا بُِحسْنٍ، كَيْفَ وَقَدْ أَنْكَرُوا عَلَى سويد', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'هَذَا الَْحدِيثَ ، وَرَمَوْهُ لَِأجْلِهِ بِالْعَظَائِمِ، وَاسْتَحَله بَـعْضُهُمْ غَزْوَهُ لَِأجْ لِهِ. قَالَ أَبُو أَحْدََْ بْنُ عَدِيٍّ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, '«كَامِلِهِ» : هَذَا الَْحدِيثُ أَحَدُ مَا أُنْكِرَ عَلَى سويد، وَكَذَلِكَ قَالَ البيهقي: إِنههُ مِمها أُنْكِرَ عَلَيْهِ، وَكَذَلِكَ قَالَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'ابْنُ طَاهِرٍ فِي «الذهخِيَرةِ» وَذكََرَهُ الحاكم فِي «تَارِيخِ نَـيْسَابُورَ» وَقَالَ: أَنَا أَتَـعَجهبُ مِنْ هَذَا الَْحدِيثِ، فَإِنههُ لََْ يَُحدهثْ بِهِ عَنْ غَيِْر سويد، وَهُوَ ثِقَةٌ، وذكره أبو الفرج ابن الَْجوْزِيُّ فِي كِتَابِ «الْمَوْضُوعَاتِ» ، وَكَانَ أبو بكر الأزرق يَـرْفَـعُهُ أَهولًا عَنْ سويد، فَـعُوتِبَ فِيهِ، فَأَسْقَطَ النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَكَانَ لَا يَُجاوِزُ بِهِ ابْنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'عَبهاسٍ رَضِيَ ا هللَُّ عَنْـهُمَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'وَمِنَ الْمَصَائِبِ الهتِي لَا تُتََْمَلُ جَعْلُ هَذَا الَْحدِيثِ مِنْ حَدِيثِ هِشَامِ بْنِ عُرْوَةَ عَنْ أَبِيهِ، عَنْ عائشة رَضِيَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'ا هللَُّ عَنْـهَا، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ. وَمَنْ لَهُ أَدْنََ إِلْمَامٍ بِالَْحدِيثِ وَعِلَلِهِ، لَا يَْحتَمِلُ هَذَا الْبَـتهةَ، وَلَا يَْحتَمِلُ أَنْ يَكُونَ مِنْ حَدِيثِ الماجشون عَنِ ابن أبي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'حازم، عَنِ ابْنِ أَبِي نَيِْحٍ، عَنْ ماَهد، عَنِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْـهُمَا مَرْفُوعًا، وَفِي صِحهتِهِ مَوْقُوفًا عَلَى ابْنِ عَبهاسٍ نَظَرٌ، وَقَدْ رَمَى النهاسُ سُوَيْدَ بْنَ سَعِيدٍ رَاوِيَ هَذَا الَْحدِيثِ بِالْعَظَائِمِ، وَأَنْكَرَهُ عَلَيْهِ يَْحيَى بْنُ مَعِيٍن وَقَالَ: هُوَ سَاقِطٌ كَذهابٌ ، لَوْ كَانَ لِِ فَـرَسٌ وَرُمْحٌ كُنْتُ أَغْزُوهُ، وَقَالَ الِْإمَامُ أَحْدَُْ: مَتْـرُوكُ الَْحدِيثِ، وَقَالَ النهسَائِيُّ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'لَيْسَ بِثِقَةٍ، وَقَالَ الْبُخَارِيُّ: كَانَ قَدْ عَمِيَ فَـيُـلَقهنُ مَا لَيْسَ مِنْ حَدِيثِهِ، وَقَالَ ابْنُ حِبهانَ: تََِْي المعضلات عَنِ الثِّقَاتِ يَِجبُ مُاََنَـبَةُ مَا رَوَى. انْـتَـهَى. وَأَحْسَنُ مَا قِيلَ فِيهِ قَـوْلُ أَبِي حَاتٍِم الهرازِيِّ : إِنههُ صَدُوقٌ كَثِيُر التهدْلِيسِ ، ُ مه قَـوْلُ الدهارَقُطْنِِِّ: هُوَ ثِقَةٌ غَيْـرَ أَنههُ لَمها كَبََِ كان ربما قرىء عَلَيْهِ حَدِيثٌ فِيهِ بَـعْضُ النهكَارَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'فَـيُجِيزُهُ انْـتَـهَى. وَعِيبَ عَلَى مسلم إِخْرَاجُ حَدِيثِهِ، وَهَذِهِ حَالُهُ، وَلَكِنْ مسلم رَوَى مِنْ حَدِيثِهِ مَا تَابَـعَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'عَلَيْهِ غَيْـرُهُ، وَلََْ يَـنْـفَرِدْ بِهِ، وَلََْ يَكُنْ مُنْكَرًا وَلَا شَاذًّا خِِلَِافِ هَذَا الَْحدِيثِ، وَا هللَُّ أعلم.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي حِفْظِ الصِّحهةِ بِالطِّيبِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'لَمها كَانَتِ الهرائِحَةُ الطهيِّبَةُ غِذَاءَ الرُّوحِ، وَالرُّوحُ مَطِيهةُ الْقُوَى، وَالْقُوَى تَـزْدَادُ بِالطِّيبِ، وَهُوَ يَـنْـفَعُ الدِّمَاغَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَالْقَلْبَ ، وَسَائِرَ الَْأعْضَاءِ الْبَاطِنِيهةِ، وَيُـفَرِّحُ الْقَلْبَ ، وَيَسُرُّ النهـفْسَ وَيَـبْسُطُ الرُّوحَ، وَهُوَ أَصْدَقُ شَيْ ءٍ لِلرُّوحِ، وَأَشَدُّهُ مُلَاءَمَةً لََها، وَبَـيْـنَهُ وَبَـيَْن الرُّوحِ الطهيِّبَةِ نِسْبَةٌ قَرِيبَةٌ. كَانَ أَحَدَ الْمَحْ بُوبِيَن مِنَ الدُّنْـيَا إِلَى أَطْيَبِ الطهيِّبِيَن صَلَوَاتُ ا هلِلَّ عَلَيْهِ وَسَلَامُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَفِي «صَحِيحِ الْبُخَارِيِّ » أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ لَا يَـرُدُّ الطِّيبَ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَفِي «صَحِيحِ مسلم» عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَنْ عُرِضَ عَلَيْهِ رَيَْحانٌ، فَلَا يَـرُدههُ فَإِنههُ طَيِّبُ الرِّيحِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'خَفِيفُ الْمَحْمَلِ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَفِي «سُنَنِ أبي داود» وَالنهسَائِيِّ، عَنْ أَبِي هُرَيْـرَةَ رَضِيَ ا هللَُّ عَنْهُ، عَنِ النهبِِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '(7) أخرجه البخاري في اللباس. (2) أخرجه مسلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَنْ عُرِضَ عَلَيْهِ طِيبٌ ، فَلَا يَـرُدههُ فَإِنههُ خَفِيفُ الْمَحْمَلِ طَيِّبُ الهرائِحَةِ »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, '«وَفِي مُسْنَدِ البزار» عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «إِنه ا هللََّ طَيِّبٌ يُِحبُّ الطِّيبَ ، نَظِيفٌ يُِحبُّ النهظَافَةَ، كَرِيٌم يُِحبُّ الْكَرَمَ، جَوَادٌ يُِحبُّ الُْجودَ، فَـنَظِّفُوا أَفْـنَاءكَُمْ وَسَاحَاتِكُمْ، وَلَا تَشَبهـهُوا بِالْيَـهُودِ يَْجمَعُونَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'الُْأكُبه فِي دُورِهِمْ» »2« . الُْأكُبُّ: الزُّبَالَةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَذكََرَ ابْنُ أَبِي شَيْـبَةَ، أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ لَهُ سُكهةٌ يَـتَطَيهبُ مِنْـهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَصَحه عَنْهُ أَنههُ قَالَ: «إِنه هِلِلَّ حَقًّا عَلَى كُلِّ مُسْلِمٍ أَنْ يَـغْتَسِلَ فِي كُلِّ سَبْـعَةِ أَهيامٍ، وَإِنْ كَانَ لَهُ طِيبٌ أَنْ يََمسه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'مِنْهُ» »3« . وَفِي الطِّيبِ مِنَ الَْخاصِّ يهةِ، أَنه الْمَلَائِكَةَ تُِبَُّهُ، وَالشهيَاطِيَن تَـنْفِرُ عَنْهُ، وَأَحَبُّ شَيْ ءٍ إِلَى الشهيَاطِيِن الهرائِحَةُ الْمُنْتِنَةُ الْكَرِيهَةُ، فَالَْأرْوَاحُ الطهيِّبَةُ تُِبَُّ الهرائِحَةَ الطهيِّبَةَ، وَالَْأرْوَاحُ الَْخبِيثَةُ تُِبَُّ الهرائِحَةَ الَْخبِيثَةَ، وَكُلُّ رُوحٍ تَيَِلُ إِلَى مَا يُـنَاسِبُـهَا، فَالَْخبِيثَاتُ لِلْخَبِيثِيَن، وَالَْخبِيثُونَ لِلْخَبِيثَاتِ، وَالطهيِّبَاتُ لِلطهيِّبِيَن،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَالطهيِّبُونَ لِلطهيِّبَاتِ، وَهَذَا وَإِنْ كَانَ فِي النِّسَاءِ وَالرِّجَالِ، فَإِنههُ يَـتَـنَاوَلُ الَْأعْمَالَ وَالَْأقْـوَالَ، وَالْمَطَاعِمَ وَالْمَشَارِبَ ، وَالْمَلَابِسَ وَالهروَائِحَ، إِمها بِعُمُومِ لَفْظِهِ، أو بعموم معناه.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي حِفْظِ صِحهةِ الْعَيِْن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'رَوَى أبو داود فِي «سُنَنِهِ» عَنْ عبد الرحنْ بن النعمان بن معبد بن هوذة الأنصاري، عَنْ أَبِيهِ، عَنْ جَدِّهِ رَضِيَ ا هللَُّ عَنْهُ، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَمَرَ بِالِْإثْدَِِ الْمُرَهوحِ عِنْدَ النهـوْمِ وَقَالَ: «لِيَـتهقِهِ الصهائِمُ» »4« . قَالَ أبو عبيد: المروّح: المطيب بالمسك.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '(7) أخرجه أبو داود في الزجل، والنسائي في الزينة. (2) أخرجه الترمذي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(3) أخرجه البخاري. (4) أخرجه أبو داود.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» وَغَيِْرهِ عَنِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْـهُمَا قَالَ: كَانَتْ لِلنهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مُكْحُلَةٌ يَكْتَحِلُ مِنْـهَا ثَلَاثًَ فِي كُلِّ عَيٍْن »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَفِي الترمذي: عَنِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْـهُمَا، قَالَ: كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إذا اكتحل يجعل في اليمنى ثلاثَ، يبتدىء بَِها، وَيَْختِمُ بَِها، وَفِي الْيُسْرَى ثِنْـتَـيِْن »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَقَدْ رَوَى أبو داود عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَنِ اكْ تَحَلَ فَـلْيُوتِرْ» »3« . فَـهَلِ الْوِتْـرُ بِالنِّسْبَةِ إِلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'الْعَيْـنَـيِْن كِلْتَـيْهِمَا، فَـيَكُونُ فِي هَذِهِ ثَلَاثٌ ، وَفِي هَذِهِ ثِنْـتَانِ، وَالْيُمْنَى أَوْلَى بِالِابْتِدَاءِ وَالتهـفْضِيلِ، أَوْ هُوَ بِالنِّسْبَةِ إِلَى كُلِّ عَيٍْن، فَـيَكُونُ فِي هَذِهِ ثَلَاثٌ ، وَفِي هَذِهِ ثَلَاثٌ ، وَهُاَُ قَـوْلَانِ فِي مَذْهَبِ أحدْ وَغَيِْرهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَفِي الْكُحْلِ حِفْظٌ لِصِحهةِ الْعَيِْن، وَتَـقْوِيَةٌ لِلنُّورِ الْبَاصِرِ، وَجَلَاءٌ لََها، وَتَـلْطِيفٌ لِلْمَادهةِ الهردِيئَةِ، وَاسْتِخْ رَاجٌ لََها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'مَعَ الزِّينَةِ فِي بَـعْضِ أَنْـوَاعِهِ، وَلَهُ عِنْدَ النهـوْمِ مَزِيدُ فَضْلٍ لِاشْتِمَالَِها عَلَى الْكُحْلِ، وَسُكُونَِها عَقِيبَهُ عَنِ الَْحرَكَةِ الْمُضِ هرةِ بَِها، وَخِدْمَةِ الطهبِيعَةِ لََها، وَلِلِْثْْدَِِ مِنْ ذَلِكَ خَاصِّ يهةٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» عَنْ سالَ عَنْ أَبِيهِ يَـرْفَـعُهُ: «عَلَيْكُمْ بِالِْإثْدَِِ، فَإِنههُ يَْجلُو الْبَصَرَ، وَيُـنْبِتُ الشهعْرَ» » .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَفِي كِتَابِ أبي نعيم: «فَإِنههُ مَنْـبَـتَةٌ لِلشهعْرِ، مَذْهَبَةٌ لِلْقَذَى، مَصْفَاةٌ لِلْبَصَرِ» »5« . وَفِي «سُنَنِ ابْنِ مَاجَهْ» أَيْضًا: عَنِ ابْنِ عَبهاسٍ - رَضِيَ ا هللَُّ عَنْـهُمَا- يَـرْفَـعُهُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '«خَيْـرُ أَكْحَالِكُمُ الِْإثْدَُِ، يَْجلُو الْبَصَرَ، وَيُـنْبِتُ الشعر» »1« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, '(7) أخرجه ابن ماجة والترمذي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, '(2) أخرجه أبو الشيخ في أخلاق النب صلّى الله عليه وسلم. (3) أخرجه أبو داود في الطهارة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, '(4) أخرجه ابن ماجة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, '(5) أخرجه أبو نعيم في الحلية والطباَني في الكبير.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, '(1) أخرجه ابن ماجة وأحدْ وأبو داود والبيهقي وابن حبان.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي ذِكْرِ شَيْ ءٍ مِنَ الَْأدْوِيَةِ وَالَْأغْذِيَةِ الْمُفْرَدَةِ الهتِي جَاءَتْ عَلَى لِسَانِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مُرَتهـبَةً عَلَى حُرُوفِ الْمُعْجَمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'حَرْفُ الَْهمْزَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'إِثْدٌَِ: هُوَ حَجَرُ الْكُحْلِ الَْأسْوَدِ، يُـؤْتَى بِهِ مِنْ أَصْبَـهَانَ، وَهُوَ أَفْضَلُهُ، وَيُـؤْتَى بِهِ مِنْ جِهَةِ الْمَغْرِبِ أَيْضًا، وَأَجْ وَدُهُ السهرِيعُ التهـفْتِيتِ الهذِي لِفُتَاتِهِ بَصِيصٌ ، وَدَاخِلُهُ أَمْلَسُ لَيْسَ فِيهِ شَيْ ءٌ مِنَ الَْأوْسَاخِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَمِزَاجُهُ بَارِدٌ يَابِسٌ يَـنْـفَعُ الْعَيَْن وَيُـقَوِّيهَا، وَيَشُدُّ أَعْصَابَـهَا، وَيَْحفَظُ صِحهتَـهَا، وَيُذْهِبُ اللهحْمَ الهزائِدَ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'الْقُرُوحِ وَيُدْمِلُهَا، وَيُـنَـقِّي أَوْسَاخَهَا، وَيَْجلُوهَا، وَيُذْهِبُ الصُّدَاعَ إِذَا اكْ تَحَلَ بِهِ مَعَ الْعَسَلِ الْمَائِيِّ الهرقِيقِ، وَإِذَا دُقه وَخُلِطَ بِبَـعْضِ الشُّحُومِ الطهرِيهةِ، وَلُطِّخَ عَلَى حَرْقِ النهارِ، لََْ تَـعْرِضْ فِيهِ خَشْكَرِيشَةٌ، وَنَـفَعَ مِنَ التهـنَـفُّطِ الَْحادِثِ بِسَبَبِهِ، وَهُوَ أَجْ وَدُ أَكْحَالِ الْعَيِْن لَا سِيهمَا لِلْمَشَايِخِ، وَالهذِينَ قَدْ ضَعُفَتْ أَبْصَارُهُمْ إِذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'جُعِلَ معه شيء من المسك.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'أترج: ثَـبَتَ فِي «الصهحِيحِ» : عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «مَثَلُ الْمُؤْمِنِ الهذِي يقرأ القرآن كمثل الآترجّة، طمها طَيِّبٌ ، وَرِيُحهَا طَيِّبٌ » »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'فِي الُْأتْـرُجِّ مَنَافِعُ كَثِيَرةٌ، وَهُوَ مُرَكهبٌ مِنْ أَرْبَـعَةِ أَشْيَاءَ: قِشْرٌ، وَلَْحمٌ، وَحَضٌْْ ، وَبَـزْرٌ، وَلِكُلِّ وَاحِدٍ مِنْـهَا مِزَاجٌ يَُخصُّهُ، فَقِشْرُهُ حَارٌّ يَابِسٌ، وَلَْحمُهُ حَارٌّ رَطْبٌ ، وَحَضُْْهُ بارد يابس، وبزره حار يابس.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(7) أخرجه البخاري في فضائل القرآن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَمِنْ مَنَافِعِ قِشْرِهِ: أَنههُ إِذَا جُعِلَ فِي الثِّيَابِ مَنَعَ السُّوسَ ، وَرَائِحَتُهُ تُصْلِحُ فَسَادَ الَْهوَاءِ وَالْوَبَاءِ، وَيُطَيِّبُ النهكْهَةَ إِذَا أَمْسَكَهُ فِي الْفَمِ، وَيَُحلِّلُ الرِّيَاحَ، وَإِذَا جُعِلَ فِي الطهعَامِ كَالَْأبَازِيرِ، أَعَانَ عَلَى الَْهضْمِ. قَالَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'صَاحِبُ «الْقَانُونِ» : وَعُصَارَةُ قِشْرِهِ تَـنْـفَعُ مِنْ نَـهْشِ الَْأفَاعِي شُرْبًا، وَقِشْرُهُ ضِمَادًا، وَحُرَاقَةُ قِشْرِهِ طِلَاءٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'جَيِّدٌ لِلْبَـرَصِ . انْـتَـهَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَأَمها لَْحمُهُ: فَمُلَطِّفٌ لَِحرَارَةِ الْمَعِدَةِ، نَافِعٌ لَِأصْحَابِ الْمِ هرةِ الصهفْرَاءِ، قَامِعٌ لِلْبُخَارَاتِ الَْحارهةِ. وَقَالَ الغافقي: أَكْلُ لَْحمِهِ يَـنْـفَعُ الْبَـوَاسِيَر. انْـتَـهَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَأَمها حَضُْْهُ: فَـقَابِضٌ كَاسِرٌ لِلصهفْرَاءِ، وَمُسَكِّنٌ لِلْخَفَقَانِ الَْحارِّ، نَافِعٌ مِنَ الْيَـرَقَانِ شُرْبًا وَاكْ تِحَالًا، قَاطِعٌ لِلْقَيْ ءِ الصهفْرَاوِيِّ ، مُشَهٍّ لِلطهعَامِ، عَاقِلٌ لِلطهبِيعَةِ، نَافِعٌ مِنَ الِْإسْهَالِ الصهفْرَاوِيِّ ، وَعُصَارَةُ حَضِْْهِ يُسَكِّنُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'غِلْمَةَ النِّسَاءِ، وَيَـنْـفَعُ طِلَاءً مِنَ الْكَلَفِ، وَيَذْهَبُ بِالْقَوْبَاءِ، وَيُسْتَدَلُّ عَلَى ذَلِكَ مِنْ فِعْلِهِ فِي الِْحبَِْ إِذَا وَقَعَ فِي الثِّيَابِ قَـلَعَهُ، وَلَهُ قُـهوةٌ تُـلَطِّفُ ، وَتَـقْطَعُ، وتبدَ، وتطفىء حَرَارَةَ الْكَبِدِ، وَتُـقَوِّي الْمَعِدَةَ، وَتَنََْعُ حِدهةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'الْمِ هرةِ الصهفْرَاءِ، وَتُزِيلُ الْغَمه الْعَارِضَ مِنْـهَا، وَتُسَكِّنُ الْعَطَشَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَأَمها بَـزْرُهُ: فَـلَهُ قُـهوةٌ مُلَُِّلَةٌ مُفََِّفَةٌ. وَقَالَ ابن ماسويه: خَاصِّ يهةُ حَبِّهِ النهـفْعُ مِنَ السُّمُومِ الْقَاتِلَةِ إِذَا شُرِبَ مِنْهُ وَزْنُ مِثْـقَالٍ مُقَشهرًا بَِماءٍ فَاتِرٍ، وَطِلَاءٍ مَطْبُوخٍ. وَإِنْ دُقه وَوُضِعَ عَلَى مَوْضِ عِ اللهسْعَةِ، نَـفَعَ، وَهُوَ مُلَيٌِّن لِلطهبِيعَةِ، مُطَيِّبٌ لِلنهكْهَةِ، وَأَكْ ثَـرُ هَذَا الْفِعْلِ مَوْجُودٌ فِي قِشْرِهِ، وَقَالَ غَيْـرُهُ: خَاصِّ يهةُ حَبِّهِ النهـفْعُ مِنْ لَسَعَاتِ الْعَقَارِبِ إِذَا شُرِبَ مِنْهُ وَزْنُ مِثْـقَالَيِْن مُقَشهرًا بَِماءٍ فَاتِرٍ، وَكَذَلِكَ إِذَا دُقه وَوُضِعَ عَلَى مَوْضِ عِ اللهدْغَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَقَالَ غَيْـرُهُ: حَبُّهُ يَصْلُحُ لِلسُّمُومِ كُلِّهَا، وَهُوَ نَافِعٌ مِنْ لَدْغِ الَْهوَامِّ كُلِّهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَذكُِرَ أَنه بَـعْضَ الَْأكَاسِرَةِ غَضِبَ عَلَى قَـوْمٍ مِنَ الَْأطِبهاءِ، فَأَمَرَ بَِحبْسِهِمْ، وَخَيهـرَهُمْ أُدْمًا لَا يَزِيدُ لَهمُْ عَلَيْهِ، فَاخْ تَارُوا الُْأتْـرُجه، فَقِيلَ لَهمُْ: لََِ اخْتَـرْتُوَُهُ عَلَى غَيِْرهِ؟ فَـقَالُوا: لَِأنههُ فِي الْعَاجِلِ رَيَْحانٌ، وَمَنْظَرُهُ مُفْرِحٌ، وَقِشْرُهُ طَيِّبُ الهرائِحَةِ، وَلَْحمُهُ فَاكِهَةٌ، وَحَضُْْهُ أُدْمٌ، وَحَبُّهُ تِرْيَاقٌ ، وفيه دهن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَحَقِيقٌ بِشَيْ ءٍ هَذِهِ مَنَافِعُهُ أَنْ يُشَبههَ بِهِ خُلَاصَةُ الْوُجُودِ، وَهُوَ الْمُؤْمِنُ الهذِي يَـقْرَأُ الْقُرْآنَ، وَكَانَ بَـعْضُ السهلَفِ يُِحبُّ النهظَرَ إِلَيْهِ لِمَا في منظره من التفريح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'أرزّ: فِيهِ حَدِيثَانِ بَاطِلَانِ مَوْضُوعَانِ عَلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، أَحَدُهُاَُ: أَنههُ «لَوْ كَانَ رَجُلًا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'لَكَانَ حَلِيمًا» الثهانِي: «كُلُّ شَيْ ءٍ أَخْ رَجَتْهُ الَْأرْضُ فَفِيهِ دَاءٌ وَشِفَاءٌ إِهلا الَْأرُزه، فَإِنههُ شِفَاءٌ لَا دَاءَ فِيهِ» ذكََرْنَاهُاَُ تَـنْبِيهًا وَتَذَِْيرًا مِنْ نِسْبَتِهِمَا إِلَيْهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'وَبَـعْدُ فَـهُوَ حَارٌّ يَابِسٌ ، وَهُوَ أَغْذَى الُْحبُوبِ بَـعْدَ الِْحنْطَةِ، وَأَحْدَُْهَا خَلْطًا، يَشُدُّ الْبَطْنَ شَدًّا يَسِيًرا، وَيُـقَوِّي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'الْمَعِدَةَ، وَيُدَبِّغُهَا، وَيَْمكُثُ فِيهَا. وَأَطِبهاءُ الِْهنْدِ تَـزْعُمُ، أَنههُ أَحْدَُْ الَْأغْذِيَةِ وَأَنْـفَعُهَا إِذَا طُبِخَ بَِألْبَانِ الْبَـقَرِ، وَلَهُ تَثَِْيٌر فِي خِصْبِ الْبَدَنِ، وَزِيَادَةِ الْمَنِِِّ، وَكَثْـرَةِ التهـغْذِيَةِ، وَتَصْفِيَةِ اللون.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'أرز: بِفَتْحِ الَْهمْزَةِ وَسُكُونِ الهراءِ: وَهُوَ الصهنَـوْبَـرُ، ذكََرَهُ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي قَـوْلِهِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, '«مَثَلُ الْمُؤْمِنِ مَثَلُ الَْخامَةِ مِنَ الهزرْعِ ، تُـفَيِّئُـهَا الرِّيَاحُ، تُقِيمُهَا مَ هرةً، وَتُيَِلُهَا أُخْ رَى، وَمَثَلُ الْمُنَافِقِ مَثَلُ الَْأرْزَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'لَا تَـزَالُ قَائِمَةً عَلَى أَصْلِهَا حَ هتى يَكُونَ انِْعَْافُـهَا مَ هرةً وَاحِدَةً» »7« ، وَحَبُّهُ حَارٌّ رَطْبٌ ، وَفِيهِ إِنْضَاجٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'وَتَـلْيِيٌن، وَتَلَِْيلٌ، وَلَذْعٌ يَذْهَبُ بِنَـقْعِهِ فِي الْمَاءِ، وَهُوَ عَسِرُ الَْهضْمِ، وَفِيهِ تَـغْذِيَةٌ كَثِيَرةٌ، وَهُوَ جَيِّدٌ لِلسُّعَالِ، وَلِتَـنْقِيَةِ رُطُوبَاتِ الرِّئَةِ، وَيَزِيدُ فِي الْمَنِِِّ، وَيُولِدُ مَغَصًا، وَتِرْيَاقُهُ حب الرمان المز.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'إذخر: ثَـبَتَ فِي «الصهحِيحِ» عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ فِي مَكهةَ: «لَا يُْختَـلَى خَلَاهَا» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'فَـقَالَ لَهُ العباس رَضِيَ ا هللَُّ عَنْهُ: إِهلا الِْإذْخِرَ يَا رَسُولَ ا هلِلَّ، فَإِنههُ لِقَيْنِهِمْ وَلِبُـيُوتِِهمْ، فَـقَالَ: «إِهلا الِْإذْخِرَ»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, '. »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'وَالِْإذْخِرُ حَارٌّ فِي الثهانِيَةِ، يَابِسٌ فِي الُْأولَى، لَطِيفٌ مُفَتِّحٌ لِلسُّدَدِ، وَأَفْـوَاهِ الْعُرُوقِ، يُدِرُّ الْبَـوْلَ وَالطهمْثَ ، وَيُـفَتِّتُ الَْحصَى، وَيَُحلِّلُ الَْأوْرَامَ الصُّلْبَةَ فِي الْمَعِدَةِ وَالْكَبِدِ وَالْكُلْيَـتَـيِْن شُرْبًا وَضِمَادًا، وَأَصْلُهُ يُـقَوِّي عَمُودَ الَْأسْنَانِ وَالْمَعِدَةَ، ويسكن الغثيان، ويقل البطن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, '(7) أخرجه البخاري في المرضى. ومسلم في صفات المنافقين. (2) أخرجه البخاري ومسلم في الحج.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'حَرْفُ الْبَاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'بِطِّيخٌ: رَوَى أبو داود وَالتِّْرمِذِيُّ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، أَنههُ كَانَ كََُْلُ الْبِطِّيخَ بِالرُّطَبِ، يَـقُولُ: «نَكْسِرُ حَ هر هَذَا بِبَـرْدِ هَذَا، وَبَـرْدَ هَذَا بَِحرِّ هَذَا» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'وَفِي الْبِطِّيخِ عِدهةُ أَحَادِيثَ لَا يَصِحُّ مِنْـهَا شَيْ ءٌ غَيْـرُ هَذَا الَْحدِيثِ الْوَاحِدِ، وَالْمُرَادُ بِهِ الَْأخْضَرُ، وَهُوَ بَارِدٌ رَطْبٌ ، وَفِيهِ جَلَاءٌ، وَهُوَ أَسْرَعُ انِْدَْارًا عَنِ الْمَعِدَةِ مِنَ الْقِثهاءِ وَالِْخيَارِ، وَهُوَ سَرِيعُ الِاسْتِحَالَةِ إِلَى أَيِّ خَلْطٍ كَانَ صَادَفَهُ فِي الْمَعِدَةِ، وَإِذَا كَانَ آكِلُهُ مَرُُْورًا انْـتَـفَعَ بِهِ جِدًّا، وَإِنْ كَانَ مَبْـرُودًا دُفِعَ ضَرَرُهُ بِيَسِيٍر مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'الهزنْبَِْيلِ وَنَوِْْهِ، وَيَـنْـبَغِي أَكْلُهُ قَـبْلَ الطهعَامِ، وَيُـتْـبَعُ بِهِ، وَإِهلا غَثهى وَقَـيهأَ. وَقَالَ بَـعْضُ الَْأطِبهاءِ: إِنههُ قَـبْلَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'الطهعَامِ يَـغْسِلُ البطن غسلا، ويذهب بالداء أصلا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'بلح: رَوَى النهسَائِيُّ وَابْنُ مَاجَهْ فِي «سُنَنِهِمَا» : مِنْ حَدِيثِ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عائشة رَضِيَ ا هللَُّ عَنْـهَا قَالَتْ : قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «كُلُوا الْبَـلَحَ بِالتهمْرِ، فَإِنه الشهيْطَانَ إِذَا نَظَرَ إِلَى ابْنِ آدَمَ كََُْلُ الْبَـلَحَ بِالتهمْرِ يَـقُولُ: بَقِيَ ابْنُ آدَمَ حَ هتى أَكَلَ الَْحدِيثَ بِالْعَتِيقِ» »2« . وَفِي رِوَايَةٍ: «كُلُوا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'الْبَـلَحَ بِالتهمْرِ، فَإِنه الشهيْطَانَ يَْحزَنُ إِذَا رَأَى ابْنَ آدَمَ كََُْلُهُ يَـقُولُ: عَاشَ ابْنُ مادم حَ هتى أَكَلَ الَْجدِيدَ بِالَْخلَقِ» ، رَوَاهُ البزار فِي «مُسْنَدِهِ» وَهَذَا لَفْظُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'قُـلْتُ : الْبَاءُ فِي الَْحدِيثِ بَِمعْنَى: مَعَ، أَيْ : كُلُوا هَذَا مَعَ هَذَا قَالَ بَـعْضُ أَطِبهاءِ الِْإسْلَامِ: إِهنَما أَمَرَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بَِأكْلِ الْبَـلَحِ بِالتهمْرِ، وَلََْ مََُْرْ بَِأكْلِ الْبُسْرِ مَعَ التهمْرِ، لَِأنه الْبَـلَحَ بَارِدٌ يَابِسٌ ، وَالتهمْرَ حَارٌّ رَطْبٌ ، فَفِي كُلٍّ مِنْـهُمَا إِصْلَاحٌ لِلْخَْرِ، وَلَيْسَ كَذَلِكَ الْبُسْرُ مَعَ التهمْرِ، فَإِنه كُله وَاحِدٍ مِنْـهُمَا حَارٌّ، وَإِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'كَانَتْ حَرَارَةُ التهمْرِ أَكْ ثَـرَ، وَلَا يَـنْـبَغِي مِنْ جِهَةِ الطِّبِّ الَْجمْعُ بَـيَْن حَارهيْنِ أَوْ بَارِدَيْنِ، كَمَا تَـقَدهمَ. وَفِي هَذَا الَْحدِيثِ: التهـنْبِيهُ عَلَى صِحهةِ أَصْلِ صِنَاعَةِ الطِّبِّ ، وَمُرَاعَاةِ التهدْبِيِر الذي يصلح في', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, '(7) أخرجه أبو داود في الأطعمة. (2) أخرجه ابن ماجة في الأطعمة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'دَفْعِ كَيْفِيهاتِ الَْأغْذِيَةِ وَالَْأدْوِيَةِ بَـعْضِهَا بِبَـعْضٍ ، وَمُرَاعَاةِ الْقَانُونِ الطِّبِِّّ الهذِي تُفََْظُ بِهِ الصِّحهةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'وَفِي الْبَـلَحِ بُـرُودَةٌ وَيُـبُوسَةٌ، وَهُوَ يَـنْـفَعُ الْفَمَ وَاللِّثَةَ وَالْمَعِدَةَ، وَهُوَ رَدِيءٌ لِلصهدْرِ وَالرِّئَةِ بِالُْخشُونَةِ الهتِي فِيهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'بَطِيءٌ فِي الْمَعِدَةِ يَسِيُر التهـغْذِيَةِ، وَهُوَ لِلنهخْلَةِ كَالِْحصْرِمِ لِشَجَرَةِ الْعِنَبِ، وَهُاَُ جَِيَعًا يُـوَلِّدَانِ رِيَاحًا، وَقَـرَاقِرَ، وَنَـفْخًا، وَلَا سِيهمَا إِذَا شُرِبَ عَلَيْهِمَا الْمَاءُ، وَدَفْعُ مَضَ هرتِِهمَا بِالتهمْرِ، أَوْ بِالْعَسَلِ والزّبد.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'بسر: ثَـبَتَ فِي «الصهحِيحِ» : أَنه أَبَا الْهيَْـثَمِ بْنَ التهـيِّهَانِ، لَمها ضَافَهُ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وأبو بكر', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 48, 'وعمر رَضِيَ ا هللَُّ عَنْـهُمَا، جَاءَهُمْ بِعَذْقٍ- وَهُوَ مِنَ النهخْلَةِ كَالْعُنْـقُودِ مِنَ الْعِنَبِ- فَـقَالَ لَهُ: «هَهلا انْـتَـقَيْتَ لَنَا مِنْ رطبه» فقال: «أحببت أن تنقوا مِنْ بُسْرِهِ وَرُطَبِهِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 49, 'الْبُسْرُ: حَارٌّ يَابِسٌ ، وَيُـبْسُهُ أَكْثَـرُ مِنْ حَرِّهِ، يُـنَشِّ فُ الرُّطُوبَةَ، وَيَدْبَغُ الْمَعِدَةَ، وَيَْحبِسُ الْبَطْنَ، وَيَـنْـفَعُ اللِّثَةَ وَالْفَمَ، وَأَنْـفَعُهُ مَا كَانَ هَشًّا وَحُلْوًا، وَكَثْـرَةُ أَكْ لِهِ وَأَكْلِ الْبَـلَحِ يحدث السّدد في الأحشاء.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 50, 'بيض: ذكََرَ البيهقي فِي «شُعَبِ الِْإيَمانِ» أَثَـرًا مَرْفُوعًا: أَنه نَبِيًّا مِنَ الَْأنْبِيَاءِ شَكَى إِلَى ا هلِلَّ سبحانه الضعف،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 51, 'فأمره بأكل البيض. فَأَمَرَهُ بَِأكْلِ الْبَـيْضِ . وَفِي ثُـبُوتِهِ نَظَرٌ، وَيُْختَارُ مِنَ الْبَـيْضِ الَْحدِيثُ عَلَى الْعَتِيقِ، وَبَـيْضُ الدهجَاجِ عَلَى سَائِرِ بَـيْضِ الطهيِْر، وَهُوَ مُعْتَدِلٌ يَِميلُ إِلَى الْبُـرُودَةِ قَلِيلًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 52, 'قَالَ صَاحِبُ «الْقَانُونِ» : وَمُهُُُّ »2« : حَارٌّ رَطْبٌ ، يُـوَلِّدُ دَمًا صَحِيحًا مَمُُْودًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 53, 'وَيُـغَذِّي غذاآ يَسِيًرا، وَيُسْرعُِ الِانِْدَْارَ مِنَ الْمَعِدَةِ إِذَا كَانَ رَخْ وًا. وَقَالَ غَيْـرُهُ: مُحُّ الْبَـيْضِ : مُسَكِّنٌ لِلْلَََِِ، مَُملِّسٌ لِلْحَلْقِ وَقَصَبَةِ الرِّئَةِ، نَافِعٌ لِلْحَلْقِ وَالسُّعَالِ وَقُـرُوحِ الرِّئَةِ وَالْكُلَى وَالْمَثَانَةِ، مُذْهِبٌ لِلْخُشُونَةِ، لَا سيما إذا أخذ بدهن اللوز والحلو،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 54, '(7) أخرجه الترمذي في الزهد، وأخرجه مسلم في صحيحه. (2) المح: صفرة البيض.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 55, 'وَمُنْضِجٌ لِمَا فِي الصهدْرِ، مُلَيٌِّن لَهُ، مُسَهِّلٌ لُِخشُونَةِ الَْحلْقِ، وَبَـيَاضُهُ إِذَا قُطِرَ فِي الْعَيِْن الْوَارِمَةِ وَرَمًا حَارًّا، بَـهردَهُ، وَسَكهنَ الْوَجَعَ، وَإِذَا لُطِّخَ بِهِ حَرْقُ النهارِ أَوْ مَا يَـعْرِضُ لَهُ، لََْ يَدَعْهُ يَـتَـنَـهفطُ، وَإِذَا لُطِّخَ بِهِ الوجع، منع الاحتراق العارض من الشمس، وإذا خُلِطَ بِالْكُنْدُرِ، وَلُطِّخَ عَلَى الَْجبْـهَةِ، نَـفَعَ مِنَ النهـزْلَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 56, 'وَذكََرَهُ صَاحِبُ «الْقَانُونِ» فِي الَْأدْوِيَةِ الْقَلْبِيهةِ، ُ مه قَالَ: وَهُوَ- وَإِنْ لََْ يَكُنْ مِنَ الَْأدْوِيَةِ الْمُطْلَقَةِ- فَإِنههُ مِمها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 57, 'لَهُ مَدْخَلٌ فِي تَـقْوِيَةِ الْقَلْبِ جِدًّا أَعْنِِ الصُّفْرَةَ، وَهِيَ تَمََْعُ ثَلَاثَةَ مَعَانٍ: سُرْعَةُ الِاسْتِحَالَةِ إِلَى الدهمِ، وَقِلهةُ الْفَضْلَةِ، وَكَوْنُ الدهمِ الْمُتَـوَلِّدِ مِنْهُ مُاََنِسًا لِلدهمِ الهذِي يَـغْذُو الْقَلْبَ خَفِيفًا مُنْدَفِعًا إِلَيْهِ بِسُرْعَةٍ، وَلِذَلِكَ هُوَ أَوْفَقُ مَا يُـتَلَافَى بِهِ عَادِيَةُ الأمراض المحللة لجوهر الروح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 58, 'بصل: رَوَى أبو داود فِي «سُنَنِهِ» : عَنْ عائشة رَضِيَ ا هللَُّ عَنْـهَا، أَنهـهَا سُئِلَتْ عَنِ الْبَصَلِ، فَـقَالَتْ : إِنه آخِرَ طَعَامٍ أَكَلَهُ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ فِيهِ بَصَلٌ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 59, 'وَثَـبَتَ عَنْهُ فِي «الصهحِيحَيِْن» أَنههُ مَنَعَ آكِلَهُ مِنْ دُخُولِ الْمَسْجِدِ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 60, 'وَالْبَصَلُ: حَارٌّ فِي الثهالِثَةِ، وَفِيهِ رُطُوبَةٌ فَضْلِيهةٌ يَـنْـفَعُ مِنْ تَـغَيُِّر الْمِيَاهِ، وَيَدْفَعُ رِيحَ السُّمُومِ، وَيُـفَتِّقُ الشههْوَةَ، وَيُـقَوِّي الْمَعِدَةَ، وَيُـهَيِّجُ الْبَاهَ، وَيَزِيدُ فِي الْمَنِِِّ، وَيَُحسِّ نُ اللهوْنَ، ويقطع البلغم، ويجلوا الْمَعِدَ ةَ، وَبَـزْرُهُ يُذْهِبُ الْبَـهَقَ، وَيُدَلهكُ بِهِ حَوْلَ دَاءِ الثهـعْلَبِ ، فَـيَـنْـفَعُ جِدًّا، وَهُوَ بِالْمِلْحِ يَـقْلَعُ الثهآلِيلَ، وَإِذَا شَمههُ مَنْ شَرِبَ دَوَاءً مُسَهِّلًا مَنَـعَهُ مِنَ الْقَيْ ءِ وَالْغَثَـيَانِ ، وَأَذْهَبَ رَائِحَةَ ذَلِكَ الدهوَاءِ، وَإِذَا اسْتَـعَطَ بَِمائِهِ، نَـقهى الهرأْسَ ، وَيُـقْطَرُ فِي الُْأذُنِ لِثِقَلِ السهمْعِ وَالطهنِيِن وَالْقَيْحِ، وَالْمَاءِ الَْحادِثِ فِي الُْأذُنَـيِْن، وَيَـنْـفَعُ مِنَ الْمَاءِ النهازِلِ فِي الْعَيْـنَـيِْن اكْ تِحَالًا يُكْتَحَلُ بِبَـزْرِهِ مَعَ الْعَسَلِ لِبَـيَاضِ الْعَيِْن، وَالْمَطْبُوخُ مِنْهُ كَثِيُر الْغِذَاءِ يَـنْـفَعُ مِنَ الْيَـرَقَانِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 61, 'وَالسُّعَالِ، وَخُشُونَةِ الصهدْرِ، وَيُدِرُّ الْبَـوْلَ، وَيُـلَيُِّن الطهبْعَ، وَيَـنْـفَعُ مِنْ عَضهةِ الْكَلْبِ غَيِْر الْكَلِبِ إِذَا نُطِلَ عَلَيْـهَا مَاؤُهُ بِِملْحٍ وَسَذَابٍ، وإذا احتمل، فتح أفواه البواسير.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 62, '(7) أخرجه أبو داود في الأطعمة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 63, '(2) أخرجه البخاري في الأطعمة، ومسلم في المساجد.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 64, 'وَأَمها ضَرَرُهُ: فَإِنههُ يُورِثُ الشهقِيقَةَ، وَيُصَدّعُِ الهرأْسَ ، وَيُـوَلِّدُ أَرْيَاحًا، وَيُظْلِمُ الْبَصَرَ، وَكَثْـرَةُ أَكْ لِهِ تُورِثُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 65, 'النِّسْيَانَ، وَيُـفْسِدُ الْعَقْلَ، وَيُـغَيُِّر رَائِحَةَ الْفَمِ وَالنهكْهَةِ، وَيُـؤْذِي الَْجلِيسَ ، وَالْمَلَائِكَةَ، وَإِمَاتَـتُهُ طَبْخًا تَذْهَبُ بَِهذِهِ الْمَضَ هراتِ مِنْهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 66, 'وَفِي السُّنَنِ: أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَمَرَ آكِلَهُ وَآكِلَ الثُّومِ أَنْ يُِميتَـهُمَا طَبْخًا »7« وَيُذْهِبُ رَائِحَتَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 67, 'مَضْغُ وَرَقِ السهذَابِ عليه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 68, 'باذناْن: فِي الَْحدِيثِ الْمَوْضُوعِ الْمُخْ تَـلَقِ عَلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «الْبَاذِنْاَْنُ لِمَا أُكِلَ لَهُ» »2« ، وَهَذَا الْكَلَامُ مِمها يُسْتَـقْبَحُ نِسْبَـتُهُ إِلَى آحَادِ الْعُقَلَاءِ، فَضْلًا عَنِ الَْأنْبِيَاءِ، وَبَـعْدُ: فَـهُوَ نَـوْعَانِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 69, 'أَبْـيَضُ وَأَسْوَدُ، وَفِيهِ خِلَافٌ ، هَلْ هُوَ بَارِدٌ أَوْ حَارٌّ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 70, 'وَالصهحِيحُ: أَنههُ حَارٌّ، وَهُوَ مُوَلِّدٌ لِلسهوْدَاءِ وَالْبَـوَاسِيِر، وَالسُّدَدِ وَالسهرَطَانِ وَالُْجذَامِ، وَيُـفْسِدُ اللهوْنَ وَيُسَوِّدُهُ، وَيَضُرُّ بِنَـتُِْ الْفَمِ، وَالَْأبْـيَضُ مِنْهُ الْمُسْتَطِيلُ عَارٍ مِنْ ذَلِكَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 71, 'حَرْفُ التهاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 72, 'تَرٌَْ: ثَـبَتَ فِي «الصهحِيحِ» عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَ هلمَ: «مَنْ تَصَهبحَ بِسَبْعِ تَرَََاتٍ» . وَفِي لَفْظٍ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 73, '«مِنْ تَرَِْ الْعَالِيَةِ لََْ يَضُهرهُ ذَلِكَ الْيَـوْمَ سُمٌّ وَلَا سِحْرٌ» »3« . وَثَـبَتَ عَنْهُ أَنههُ قَالَ: «بَـيْتٌ لَا تَرََْ فِيهِ جِيَاعٌ أَهْلُهُ» »4« وَثَـبَتَ عنه أكل التّمر بالزّبد بِالُْخبْزِ، وَأَكْ لُهُ مُفْرَدًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 74, 'وَهُوَ حَارٌّ فِي الثهانِيَةِ، وَهَلْ هُوَ رَطْبٌ فِي الُْأولَى، أَوْ يَابِسٌ فِيهَا؟ عَلَى قَـوْلَيِْن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 75, 'وَهُوَ مُقَوٍّ لِلْكَبِدِ، مُلَيٌِّن لِلطهبْعِ، يَزِيدُ فِي الْبَاهِ، وَلَا سِيهمَا مَعَ حبّ الصّنوبر، ويبىَء مِنْ خُشُونَةِ الَْحلْقِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 76, 'وَمَنْ لََْ يَـعْتَدْهُ كَأَهْلِ الْبِلَادِ الْبَارِدَةِ فَإِنههُ يُورِثُ لَهمُُ السُّدَدَ، وَيُـؤْذِي الَْأسْنَانَ، وَيُـهَيِّجُ الصُّدَاعَ، وَدَفْعُ ضَرَرِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 77, 'بِاللهوْزِ وَالِْخشْخَاشِ ، وَهُوَ مِنْ أَكْ ثَرِ الثِّمَارِ تَـغْذِيَةً لِلْبَدَنِ بَِما فِيهِ مِنَ الَْجوْهَرِ الَْحارِّ الهرطْبِ، وَأَكْ لُهُ عَلَى الريق يقتل الدود، فإنه مع', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 78, '(7) أخرجه مسلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 79, '(2) أخرجه البخاري في الطب، ومسلم في الأشربة. (3) أخرجه المسلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 80, '(4) أخرجه أبو داود والترمذي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 81, 'حَرَارَتِهِ فِيهِ قُـهوةٌ تِرْيَاقِيهةٌ، فَإِذَا أُدِيَم اسْتِعْمَالُهُ عَلَى الرِّيقِ، خَ هففَ مَادهةَ الدُّودِ، وَأَضْعَفَهُ وَقَـلهلَهُ، أَوْ قَـتَـلَهُ، وَهُوَ فَاكِهَةٌ وَغِذَاءٌ، وَدَوَاءٌ وَشَرَابٌ وحلوى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 82, 'تين: لَمها لََْ يَكُنِ التِّيُن بَِأرْضِ الِْحجَازِ وَالْمَدِينَةِ، لََْ تََِْ لَهُ ذِكْ رٌ فِي السُّنهةِ، فَإِنه أَرْضَهُ تُـنَافِي أَرْضَ النهخْلِ، وَلَكِنْ قَدْ أَقْسَمَ ا هللَُّ بِهِ فِي كِتَابِهِ، لِكَثْـرَةِ مَنَافِعِهِ وَفَـوَائِدِهِ، وَالصهحِيحُ: أَنه الْمُقْسَمَ بِهِ: هُوَ التِّيُن الْمَعْرُوفُ . وَهُوَ حَارٌّ، وَفِي رُطُوبَتِهِ وَيُـبُوسَتِهِ قَـوْلَانِ، وَأَجْ وَدُهُ: الَْأبْـيَضُ النهاضِجُ الْقِشْرِ، يَْجلُو رَمْلَ الْكُلَى وَالْمَثَانَةِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 83, 'ويؤمن من السموم، وهو أغذى من جيمع الْفَوَاكِهِ وَيَـنْـفَعُ خُشُونَةَ الَْحلْقِ وَالصهدْرِ، وَقَصَبَةِ الرِّئَةِ، وَيَـغْسِلُ الْكَبِدَ وَالطِّحَالَ، وَيُـنَـقِّي الَْخلْطَ الْبَـلْغَمِيه مِنَ الْمَعِدَةِ، وَيَـغْذُو الْبَدَنَ غِذَاءً جَيِّدًا، إِهلا أَنههُ يُـوَلِّدُ الْقَمْلَ إِذَا أُكْ ثِرَ مِنْهُ جِدًّا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 84, 'وَيَابِسُهُ يَـغْذُو وَيَـنْـفَعُ الْعَصَبَ ، وَهُوَ مَعَ الَْجوْزِ وَاللهوْزِ مَمُُْودٌ، قَالَ جالينوس: وَإِذَا أُكِلَ مَعَ الَْجوْزِ وَالسهذَابِ ]7[ قَـبْلَ أَخْذِ السُّمِّ الْقَاتِلِ، نَـفَعَ، وَحَفِظَ مِنَ الضهرَرِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 85, 'وَيُذْكَرُ عَنْ أَبِي الدهرْدَاءِ: أُهْدِيَ إِلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ طَبَقٌ مِنْ تِيٍن، فَـقَالَ: «كُلُوا» وَأَكَلَ مِنْهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 86, 'وَقَالَ: لَوْ قُـلْتُ : إِنه فَاكِهَةً نَـزَلَتْ مِنَ الَْجنهةِ قُـلْتُ : هَذِهِ، لَِأنه فَاكِهَةَ الَْجنهةِ بِلَا عَجَمٍ، فَكُلُوا مِنْـهَا فَإِنهـهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 87, 'تَـقْطَعُ الْبَـوَاسِيَر، وَتَـنْـفَعُ مِنَ النِّقْرِسِ » . وَفِي ثُـبُوتِ هَذَا نَظَرٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 88, 'وَاللهحْمُ مِنْهُ أَجْ وَدُ، وَيُـعَطِّشُ الْمَحْ رُورِينَ، وَيُسَكِّنُ الْعَطَشَ الْكَائِنَ عَنِ الْبَـلْغَمِ الْمَالِحِ، وَيَـنْـفَعُ السُّعَالَ الْمُزْمِنَ، وَيُدِرُّ الْبَـوْلَ، وَيَـفْتَحُ سُدَدَ الْكَبِدِ وَالطِّحَالِ، وَيُـوَافِقُ الْكُلَى وَالْمَثَانَةَ، وَلَِأكْ لِهِ عَلَى الرِّيقِ مَنْـفَعَةٌ عَجِيبَةٌ فِي تَـفْتِيحِ مَاََرِي الْغِذَاءِ، وَخُصُوصًا بِاللهوْزِ وَالَْجوْزِ، وَأَكْ لُهُ مَعَ الأغذية الغليظة رديء جدا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 89, 'وَخُصُوصًا بِاللهوْزِ وَالَْجوْزِ، وَأَكْ لُهُ مَعَ الَْأغْذِيَةِ الْغَلِيظَةِ رَدِيءٌ جِدًّا، وَالتُّوتُ الَْأبْـيَضُ قَرِيبٌ مِنْهُ، لَكِنههُ أقل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 90, 'تغذية وأضر بالمعدة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 91, 'مَاءِ الشعير', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 92, 'تلبينة: قَدْ تَـقَدهمَ إِنهـهَا مَاءُ الشهعِيِر الْمَطْحُونِ، وَذكََرْنَا مَنَافِعَهَا، وَأَنهـهَا أَنْـفَعُ لَِأهْلِ الِْحجَازِ مِنْ الصحيح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 93, 'حَرْفُ الثهاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 94, 'ثَـلْجٌ: ثَـبَتَ فِي «الصهحِيحِ» : عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «اللههُمه اغْسِلْنِِ مِنْ خَطَايَايَ بِالْمَاءِ وَالثهـلْجِ وَالْبَـرَدِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 95, 'وَفِي هَذَا الَْحدِيثِ مِنَ الْفِقْهِ: أَنه الدهاءَ يُدَاوَى بِضِدِّهِ، فَإِنه فِي الَْخطَايَا مِنَ الَْحرَارَةِ وَالَْحرِيقِ مَا يُضَادُّهُ الثهـلْجُ وَالْبَـرَدُ، وَالْمَاءُ الْبَارِدُ، وَلَا يُـقَالُ: إِنه الْمَاءَ الَْحاره أَبْـلَغُ فِي إِزَالَةِ الْوَسَخِ، لَِأنه فِي الْمَاءِ الْبَارِدِ مِنْ تَصْلِيبِ الِْجسْمِ وَتَـقْوِيَتِهِ مَا لَيْسَ فِي الَْحارِّ، وَالَْخطَايَا تُوجِبُ أَثَـرَيْنِ: التهدْنِيسَ وَالِْإرْخَاءَ، فَالْمَطْلُوبُ مُدَاوَاتُـهَا بَِما يُـنَظِّفُ الْقَلْبَ وَيُصَلِّبُهُ، فَذَكَرَ الْمَاءَ الْبَارِدَ وَالثهـلْجَ وَالْبَـرَدَ إِشَارَةً إِلَى هَذَيْنِ الَْأمْرَيْنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 96, 'وَبَـعْدُ فَالثهـلْجُ بَارِدٌ عَلَى الَْأصَحِّ ، وَغَلِطَ مَنْ قَالَ: حَارٌّ، وَشُبْـهَتُهُ تَـوَلُّدُ الَْحيَـوَانِ فِيهِ، وَهَذَا لَا يَدُلُّ عَلَى حَرَارَتِهِ، فَإِنههُ يَـتَـوَلهدُ فِي الْفَوَاكِهِ الْبَارِدَةِ، وَفِي الَْخلِّ، وَأَمها تَـعْطِيشُهُ، فَلِتَـهْيِيجِهِ الَْحرَارَةَ لَا لَِحرَارَتِهِ فِي نَـفْسِهِ، وَيَضُرُّ الْمَعِدَةَ وَالْعَصَبَ ، وَإِذَا كَانَ وَجَعُ الَْأسْنَانِ مِنْ حَرَارَةٍ مُفْرِطَةٍ، سكنها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 97, 'ثوم: هُوَ قَرِيبٌ مِنَ الْبَصَلِ، وَفِي الَْحدِيثِ : «مَنْ أَكَلَهُمَا فَـلْيُمِتْـهُمَا طَبْخًا» »2« . وَأُهْدِيَ إِلَيْهِ طَعَامٌ فِيهِ ثُومٌ، فَأَرْسَلَ بِهِ إِلَى أَبِي أَيُّوبَ الَْأنْصَارِيِّ ، فَـقَالَ: يَا رَسُولَ ا هلِلَّ، تَكْ رَهُهُ وَتُـرْسِلُ بِهِ إِلَهِ؟ فَـقَالَ: «إِنِّي أُنَاجِي مَنْ لَا تُـنَاجِي» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 98, 'وَبَـعْدُ فَـهُوَ حَارٌّ يَابِسٌ فِي الهرابِعَةِ، يُسَخِّ نُ تَسْخِينًا قَوِيًّا، وَيَُجفِّفُ تَفَِْيفًا بَالِغًا، نَافِعٌ لِلْمَبْـرُودِينَ، وَلِمَنْ مِزَاجُهُ بَـلْغَمِيٌّ، وَلِمَنْ أَشْرَفَ عَلَى الْوُقُوعِ فِي الْفَالِجِ، وَهُوَ مُفََِّفٌ لِلْمَنِِِّ، مُفَتِّحٌ لِلسُّدَدِ، ملُل للرياح الغليظة، هاضم للطعام، قاطع', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 99, '(7) أخرجه مسلم في المساجد.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 100, '(2) أخرجه مسلم في المساجد. وابن ماجة في إقامة الصلاة، والنسائي وأحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 101, 'لِلْعَطَشِ ، مُطْلِقٌ لِلْبَطْنِ، مُدِرٌّ لِلْبَـوْلِ، يَـقُومُ فِي لَسْعِ الَْهوَامِّ وَجَِيَعِ الَْأوْرَامِ الْبَارِدَةِ مَقَامَ التِّْريَاقِ، وَإِذَا دُقه وَعُمِلَ مِنْهُ ضِمَادٌ عَلَى نَـهْشِ الَْحيهاتِ، أَوْ عَلَى لَسْعِ الْعَقَارِبِ، نَـفَعَهَا وَجَذَبَ السُّمُومَ مِنْـهَا، وَيُسَخِّ نُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 102, 'الْبَدَنَ، وَيَزِيدُ فِي حَرَارَتِهِ، وَيَـقْطَعُ الْبَـلْغَمَ، وَيَُحلِّلُ النهـفْخَ وَيُصَفِّي الَْحلْقَ، وَيَْحفَظُ صِحهةَ أَكْ ثَرِ الَْأبْدَانِ، وَيَـنْـفَعُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 103, 'مِنْ تَـغَيُِّر الْمِيَاهِ، وَالسُّعَالِ الْمُزْمِنِ، وَيُـؤْكَلُ نِيئًا وَمَطْبُوخًا وَمَشْوِيًّا، وَيَـنْـفَعُ مِنْ وَجَعِ الصهدْرِ مِنَ الْبَـرْدِ، وَيُْخرجُِ الْعَلَقَ مِنَ الَْحلْقِ، وَإِذَا دُقه مَعَ الَْخلِّ وَالْمِلْحِ وَالْعَسَلِ، ُ مه وُضِعَ عَلَى الضِّ رْسِ الْمُتَأَكِّلِ، فَـتهـتَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 104, 'وَأَسْقَطَهُ، وَعَلَى الضِّرْسِ الْوَجِعِ، سَكهنَ وَجَعَهُ، وَإِنْ دُقه مِنْهُ مِقْدَارُ دِرْهَيَُِْن، وَأُخِذَ مَعَ مَاءِ الْعَسَلِ، أَخْ رَجَ الْبَـلْغَمَ وَالدُّودَ، وَإِذَا طُلِيَ بِالْعَسَلِ عَلَى الْبَـهَقِ، نَـفَعَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 105, 'وَمِنْ مَضَارِّهِ: أَنههُ يُصَدّعُِ، وَيَضُرُّ الدِّمَاغَ وَالْعَيْـنَـيِْن، وَيُضْعِفُ الْبَصَرَ وَالْبَاهَ، وَيُـعَطِّشُ ، وَيُـهَيِّجُ الصهفْرَاءَ، وَيَُجيِّفُ رَائِحَةَ الْفَمِ، وَيُذْهِبُ رَائِحَتَهُ أن يمضغ عليه ورق السّذاب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 106, 'ثريد: ثَـبَتَ فِي «الصهحِيحَيِْن» عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «فَضْلُ عَائِشَةَ عَلَى النِّسَاءِ كَفَضْلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 107, 'الثهرِيدِ عَلَى سَائِرِ الطهعَامِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 108, 'وَالثهرِيدُ وَإِنْ كَانَ مُرَكهبًا، فَإِنههُ مُرَكهبٌ مِنْ خُبْزٍ وَلَْحمٍ، فَالُْخبْـزُ أَفْضَلُ الَْأقْـوَاتِ، وَاللهحْمُ سَيِّدُ الِْإدَامِ، فَإِذَا اجْ تَمَعَا لََْ يَكُنْ بَـعْدَهُاَُ غَايَةٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 109, 'وَتَـنَازعََ النهاسُ أَيُّـهُمَا أَفْضَلُ؟ وَالصهوَابُ أَنه الَْحاجَةَ إِلَى الُْخبْزِ أَكْثَـرُ وَأَعَمُّ، وَاللهحْمُ أَجَلُّ وَأَفْضَلُ، وَهُوَ أَشْبَهُ بِوَِْهَرِ الْبَدَنِ مِنْ كُلِّ مَا عَدَاهُ، وَهُوَ طَعَامُ أَهْلِ الَْجنهةِ، وَقَدْ قَالَ تَـعَالَى لِمَنْ طَلَبَ الْبَـقْلَ، وَالْقِثهاءَ، وَالْفُومَ، وَالْعَدَسَ ، وَالْبَصَلَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 110, 'أَتَسْتَـبْدِلُونَ الهذِي هُوَ أَدْنَ بِالهذِي هُوَ خَيْـرٌ »2« ، وَكَثِيٌر مِنَ السهلَفِ عَلَى أَنه الْفُومَ الِْحنْطَةُ، وَعَلَى هَذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 111, 'فَالْآيَةُ نَصٌّ عَلَى أَنه اللهحْمَ خير من الحنطة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 112, '(7) أخرجه البخاري ومسلم في فضائل أصحاب النب صلّى الله عليه وسلم. (2) البقرة- .12', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 113, 'حَرْفُ الِْجيمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 114, 'جُهَارٌ: قَـلْبُ النهخْلِ، ثَـبَتَ فِي «الصهحِيحَيِْن» : عَنْ عبد الله بن عمر قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 115, 'بَـيْـنَا نَنُْْ عِنْدَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ جُلُوسٌ ، إِذْ أُتَِي بِمُِهارِ نَلَُْةٍ، فَـقَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إِنه مِنَ الشهجَرِ شَجَرَةً مِثْلَ الهرجُلِ الْمُسْلِمِ لَا يَسْقُطُ وَرَقُـهَا ... الَْحدِيثَ » »7« . وَالُْجمهارُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 116, 'بَارِدٌ يَابِسٌ فِي الُْأولَى، يَْختِمُ الْقُرُوحَ، وَيَـنْـفَعُ مِنْ نَـفْثِ الدهمِ، وَاسْتِطْلَاقِ الْبَطْنِ، وَغَلَبَةِ الْمِ هرةِ الصهفْرَاءِ، وَثَئَِرَةِ الدهمِ، وَلَيْسَ بِرَدِيءِ الْكَيْمُوسِ ، وَيَـغْذُو غِذَاءً يَسِيًرا، وَهُوَ بَطِيءُ الَْهضْمِ، وَشَجَرَتُهُ كُلُّهَا مَنَافِعُ، وَلَِهذَا مَثهـلَهَا النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بِالهرجُلِ الْمُسْلِمِ لكثرة خيره ومنافعه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 117, 'جبن: فِي «السُّنَنِ» عَنْ عبد الله بن عمر قَالَ: «أُتَِي النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بنِبة فِي تَـبُوكَ، فَدَعَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 118, 'بِسِكِّيٍن، وَسَمهى وَقَطَعَ» رَوَاهُ أبو داود »2« ، وَأَكَلَهُ الصهحَابَةُ رَضِيَ ا هللَُّ عَنْـهُمْ بِالشهامِ، وَالْعِرَاقِ، وَالهرطْبُ مِنْهُ غَيْـرُ الْمَمْلُوحِ جَيِّدٌ لِلْمَعِدَةِ، هَيُِّن السُّلُوكِ فِي الَْأعْضَاءِ، يَزِيدُ فِي اللهحْمِ، وَيُـلَيُِّن الْبَطْنَ تَـلْيِينًا مُعْتَدِلًا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 119, 'وَالْمَمْلُوحُ أَقَلُّ غِذَاءً مِنَ الهرطْبِ، وَهُوَ رَدِيءٌ لِلْمَعِدَةِ، مُؤْذٍ لِلْمَِْعَاءِ، وَالْعَتِيقُ يَـعْقِلُ الْبَطْنَ، وَكَذَا الْمَشْوِيُّ، وَيَـنْـفَعُ الْقُرُوحَ، وَيَْمنَعُ الِْإسْهَالَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 120, 'وَهُوَ بَارِدٌ رَطْبٌ ، فَإِنِ اسْتُـعْمِلَ مَشْوِيًّا، كَانَ أَصْلَحَ لِمِزَاجِهِ، فَإِنه النهارَ تُصْلِحُهُ وَتُـعَدِّلُهُ، وَتُـلَطِّفُ جَوْهَرَهُ، وَتُطَيِّبُ طَعْمَهُ وَرَائِحَتَهُ. وَالْعَتِيقُ الْمَالِحُ، حَارٌّ يَابِسٌ ، وَشَيُّهُ يُصْلِحُهُ أَيْضًا بِتَـلْطِيفِ جَوْهَرِهِ، وَكَسْرِ حِرَافَتِهِ لِمَا تَذَِْبُهُ النهارُ مِنْهُ مِنَ الَْأجْ زَاءِ الَْحارهةِ الْيَابِسَةِ الْمُنَاسِبَةِ لََها، وَالْمُمَلهحُ مِنْهُ يُـهْزِلُ، وَيُـوَلِّدُ حَصَاةَ الْكُلَى وَالْمَثَانَةِ، وَهُوَ رَدِيءٌ لِلْمَعِدَةِ، وَخَلْطُهُ بِالْمُلَطِّفَاتِ أَرْدَأُ بِسَبَبِ تنفيذها له إلى المعدة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 121, '(7) أخرجه البخاري في الأطعمة، ومسلم في صفات المنافقين. (2) أخرجه أبو داود في الأطعمة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 122, 'حرف الحاء', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 123, 'أحناء: قد تقدمت الأحاديث، وَذِكْرِ مَنَافِعِهِ، فَأَغْنَى عَنْ إِعَادَتِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 124, 'حَبهةُ السهوْدَاءِ: ثَـبَتَ فِي «الصهحِيحَيِْن» : مِنْ حَدِيثِ أبي سلمة، عَنْ أَبِي هُرَيْـرَةَ رَضِيَ ا هللَُّ عَنْهُ، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وسلم قال: «عَلَيْكُمْ بَِهذِهِ الَْحبهةِ السهوْدَاءِ، فَإِنه فِيهَا شِفَاءً مِنْ كُلِّ دَاءٍ إِهلا السهامَ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 125, 'وَالسهامُ: الْمَوْتُ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 126, 'الَْحبهةُ السهوْدَاءُ: هِيَ الشُّونِيزُ فِي لُغَةِ الْفُرْسِ ، وَهِيَ الْكَمُّونُ الَْأسْوَدُ، وَتُسَمهى الْكَمُّونَ الِْهنْدِيه، قَالَ الحربي،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 127, 'عَنِ الحسن: إِنهـهَا الَْخرْدَلُ، وَحَكَى الهروي: أَنهـهَا الَْحبهةُ الَْخضْرَاءُ ثَرَََةُ الْبُطْمِ، وَكِلَاهُاَُ وَهْمٌ، وَالصهوَابُ : أَنهـهَا الشُّونِيزُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 128, 'وَهِيَ كَثِيَرةُ الْمَنَافِعِ جِدًّا، وَقَـوْلُهُ: «شِفَاءً مِنْ كُلِّ دَاءٍ» ، مِثْلُ قَـوْلِهِ تعالى: تُدَمِّرُ كُله شَيْ ءٍ بَِأمْرِ رَبِّها »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 129, 'أي: كلّ شيء بقبل الهتدْمِيَر وَنَظَائِرَهُ، وَهِيَ نَافِعَةٌ مِنْ جَِيَعِ الَْأمْرَاضِ الْبَارِدَةِ، وَتَدْخُلُ فِي الَْأمْرَاضِ الَْحارهةِ الْيَابِسَةِ بِالْعَرَضِ ، فَـتُـوَصِّلُ قُـوَى الَْأدْوِيَةِ الْبَارِدَةِ الهرطْبَةِ إِلَيْـهَا بِسُرْعَةِ تَـنْفِيذِهَا إِذَا أُخِذَ يَسِيُرهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 130, 'وَقَدْ نَصه صَاحِبُ «الْقَانُونِ» وَغَيْـرُهُ عَلَى الهزعْفَرَانِ فِي قُـرْصِ الْكَافُورِ لِسُرْعَةِ تَـنْفِيذِهِ وَإِيصَالِهِ قُـهوتَهُ، وَلَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 131, 'نَظَائِرُ يَـعْرِفُـهَا حُذهاقُ الصِّنَاعَةِ، وَلَا تَسْتَـبْعِدْ مَنْـفَعَةَ الَْحارِّ فِي أَمْرَاضٍ حَارهةٍ بِالَْخاصِّ يهةِ، فَإِنهكَ تَِدَُ ذَلِكَ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 132, 'أَدْوِيَةٍ كَثِيَرةٍ، مِنْـهَا: الَْأنْـزَرُوتُ وَمَا يُـرَكهبُ مَعَهُ مِنْ أَدْوِيَةِ الهرمَدِ، كَالسُّكهرِ وَغَيِْرهِ مِنَ الْمُفْرَدَاتِ الَْحارهةِ، وَالهرمَدُ وَرَمٌ حَارٌّ بِاتِّفَاقِ الَْأطِبهاءِ، وَكَذَلِكَ نَـفْعُ الْكِبِْيَتِ الَْحارِّ جِدًّا مِنَ الَْجرَبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 133, 'وَالشُّونِيزُ حَارٌّ يَابِسٌ فِي الثهالِثَةِ، مُذْهِبٌ لِلنهـفْخِ، مُْخرِجٌ لَِحبِّ  الْقَرَعِ ، نَافِعٌ مِنَ الْبَـرَصِ وَحُهْى الرِّبْعِ وَالْبَـلْغَمِيهةِ مُفَتِّحٌ لِلسُّدَدِ، وَمُلَُِّلٌ لِلرِّيَاحِ، مُفََِّفٌ لِبَـلهةِ الْمَعِدَةِ وَرُطُوبَتِهَا. وَإِنْ دُقه وَعُجِنَ بِالْعَسَلِ، وَشُرِبَ بالماء الحار، أذاب الحصاة التي تكون', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 134, '(7) أخرجه البخاري في الطب، ومسلم في السلام. (2) الأحقاف- .25', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 135, 'فِي الْكُلْيَـتَـيِْن وَالْمَثَانَةِ، وَيُدِرُّ الْبَـوْلَ وَالَْحيْضَ وَاللهبََن إِذَا أُدِيَم شُرْبُهُ أَهيامًا، وَإِنْ سُخِّ نَ بِالَْخلِّ، وَطُلِيَ عَلَى الْبَطْنِ، قَـتَلَ حَبه الْقَرَعِ ، فَإِنْ عُجِنَ بَِماءِ الَْحنْظَلِ الهرطْبِ، أَوِ الْمَطْبُوخِ، كَانَ فِعْلُهُ فِي إِخْ رَاجِ الدُّودِ أَقْـوَى، وَيَْجلُو وَيَـقْطَعُ، وَيَُحلِّلُ، وَيَشْفِي مِنَ الزُّكَامِ الْبَارِدِ إِذَا دُقه وَصُيَِّر فِي خِرْقَةٍ، وَاشْتُمه دَائِمًا، أَذْهَبَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 136, 'وَدُهْنُهُ نَافِعٌ لِدَاءِ الَْحيهةِ، وَمِنَ الثهآلِيلِ وَالِْخيلَانِ ، وَإِذَا شُرِبَ مِنْهُ مِثْـقَالٌ بَِماءٍ، نَـفَعَ مِنَ الْبَـهَرِ وضيق', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 137, 'التّنفس، وَالضِّمَادُ بِهِ يَـنْـفَعُ مِنَ الصُّدَاعِ الْبَارِدِ، وَإِذَا نُقِعَ مِنْهُ سَبْعُ حَبهاتٍ عَدَدًا فِي لَبَِن امْرَأَةٍ، وَسُعِطَ بِهِ صَاحِبُ الْيَـرَقَانِ، نَـفَعَهُ نَـفْعًا بَلِيغًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 138, 'وَإِذَا طُبِخَ خِلٍَِّ، وَتُضَُْمِضَ بِهِ، نَـفَعَ مِنْ وَجَعِ الَْأسْنَانِ عَنْ بَـرْدٍ، وَإِذَا اسْتُعِطَ بِهِ مَسْحُوقًا، نَـفَعَ مِنِ ابْتِدَاءِ الْمَاءِ الْعَارِضِ فِي الْعَيِْن، وَإِنْ ضُمِّدَ بِهِ مَعَ الَْخلِّ، قَـلَعَ الْبُـثُورَ وَالَْجرَبَ الْمُتَـقَرِّحَ، وَحَلهلَ الَْأوْرَامَ الْبَـلْغَمِيهةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 139, 'الْمُزْمِنَةَ، وَالَْأوْرَامَ الصُّلْبَةَ، وَيَـنْـفَعُ مِنَ الهلقْوَةِ إِذَا تُسُعِّطَ بِدُهْنِهِ، وَإِذَا شُرِبَ مِنْهُ مِقْدَارُ نِصْفِ مِثْـقَالٍ إِلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 140, 'مِثْـقَالٍ، نَـفَعَ مِنْ لَسْعِ الرُّتَـيْلَاءِ، وَإِنْ سُحِقَ نَاعِمًا وَخُلِطَ بِدُهْنِ الَْحبهةِ الَْخضْرَاءِ، وَقُطِرَ مِنْهُ فِي الُْأذُنِ ثَلَاثَ قَطَرَاتٍ، نَـفَعَ مِنَ الْبَـرْدِ الْعَارِضِ فِيهَا وَالرِّيحِ وَالسُّدَدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 141, 'وَإِنْ قُلِيَ، ُ مه دُقه نَاعِمًا، ُ مه نُقِعَ فِي زَيْتٍ، وَقُطِرَ فِي الَْأنْفِ ثَلَاثَ قَطَرَاتٍ أَوْ أَرْبَعَ، نَـفَعَ مِنَ الزُّكَامِ الْعَارِضِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 142, 'مَعَهُ عُطَاسٌ كَثِيٌر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 143, 'وَإِذَا أُحْرِقَ وَخُلِطَ بِشَمْعٍ مُذَابٍ بِدُهْنِ السهوْسَنِ، أَوْ دُهْنِ الِْحنهاءِ، وَطُلِيَ بِهِ الْقُرُوحُ الَْخارِجَةُ مِنَ السهاقَـيِْن بَـعْدَ غَسْلِهَا بِالَْخلِّ، نَـفَعَهَا وَأَزَالَ الْقُرُوحَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 144, 'وَإِذَا سُحِقَ خِلٍَِّ، وَطُلِيَ بِهِ الْبَـرَصُ وَالْبَـهَقُ الَْأسْوَدُ، وَالَْحزَازُ الْغَلِيظُ، نَـفَعَهَا وَأَبْـرَأَهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 145, 'وَإِذَا سُحِقَ نَاعِمًا، وَاسْتَفه مِنْهُ كُله يَـوْمٍ دِرْهَيَُِْن بَِماءٍ بَارِدٍ مَنْ عَضههُ كَلْبٌ كَلِبٌ قَـبْلَ أَنْ يَـفْرُغَ مِنَ الْمَاءِ، نَـفَعَهُ نَـفْعًا بَلِيغًا، وَأَمِنَ عَلَى نَـفْسِهِ مِنَ الَْهلَاكِ. وَإِذَا اسْتُعِطَ بِدُهْنِهِ، نَـفَعَ مِنَ الْفَالِجِ وَالْكُزَازِ، وَقَطَعَ مَوَادههُاَُ، وَإِذَا دُخِّنَ بِهِ، طَرَدَ الَْهوَامه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 146, 'وَإِذَا أُذِيبَ الَْأنْـزَرُوتُ بَِماءٍ، وَلُطِخَ عَلَى دَاخِلِ الَْحلْقَةِ، ُ مه ذُره عَلَيْـهَا الشُّونِيزُ، كَانَ مِنَ الذهرُورَاتِ الَْجيِّدَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 147, 'الْعَجِيبَةِ النهـفْعِ مِنَ الْبَـوَاسِيِر، وَمَنَافِعُهُ أَضْعَافُ مَا ذكََرْنَا، وَالشهرْبَةُ مِنْهُ دِرْ هََاُنِ ، وَزَعَمَ قوم أن الإكثار منه قاتل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 148, 'حرير: قَدْ تَـقَدهمَ أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَبَاحَهُ للزبير، وَلِعَبْدِ الهرحْنَِْ بْنِ عَوْفٍ مِنْ حِكهةٍ كَانَتْ بِِهمَا، وَتَـقَدهمَ مَنَافِعُهُ وَمِزَاجُهُ، فلا حاجة إلى إعادته.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 149, 'حرف: قَالَ أَبُو حَنِيفَةَ الدِّينَـوَرِيُّ: هَذَا هُوَ الَْحبُّ الهذِي يُـتَدَاوَى بِهِ، وَهُوَ الثُّـهفاءُ الهذِي جَاءَ فِيهِ الَْخبَـرُ عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَنَـبَاتُهُ يُـقَالُ لَهُ: الُْحرْفُ ، وَتُسَمِّيهِ الْعَامهةُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 150, 'الرُّشَادُ، وَقَالَ أبو عبيد: الثُّـهفاءُ: هُوَ الُْحرْفُ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 151, 'قُـلْتُ : وَالَْحدِيثُ الهذِي أَشَارَ إِلَيْهِ، مَا رَوَاهُ أبو عبيد وَغَيْـرُهُ، مِنْ حَدِيثِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْـهُمَا، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «مَاذَا فِي الَْأمَ هريْنِ مِنَ الشِّ فَاءِ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 152, 'الصهبَُِ وَالثُّـهفاءُ» رَوَاهُ أبو داود فِي الْمَرَاسِيلِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 153, 'وَقُـهوتُهُ فِي الَْحرَارَةِ وَالْيُـبُوسَةِ فِي الدهرَجَةِ الثهالِثَةِ، وَهُوَ يُسَخِّ نُ، وَيُـلَيُِّن الْبَطْنَ، وَيُْخرجُِ الدُّودَ وَحَبه الْقَرَعِ ، وَيَُحلِّلُ أَوْرَامَ الطِّحَالِ، وَيَُحرِّكُ شهوة الجماع، ويجلو الجرب المتقرّح والقوباء.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 154, 'وإذ ضُمِّدَ بِهِ مَعَ الْعَسَلِ، حَلهلَ وَرَمَ الطِّحَالِ، وَإِذَا طُبِخَ مَعَ الِْحنهاءِ أَخْ رَجَ الْفُضُولَ الهتِي فِي الصهدْرِ، وَشُرْبُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 155, 'يَـنْـفَعُ مِنْ نَـهْشِ الَْهوَامِّ وَلَسْعِهَا، وَإِذَا دُخِّنَ بِهِ فِي مَوْضِ عٍ، طَرَدَ الهوامّ عنه، ويمسك الشعر المتساقط، وإذا لط بِسَوِيقِ الشهعِيِر وَالَْخلِّ، وَتُضُمِّدَ بِهِ، نَـفَعَ مِنْ عرق النساء، وَحَلهلَ الَْأوْرَامَ الَْحارهةَ فِي آخِرِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 156, 'وَإِذَا تُضُمِّدَ بِهِ مَعَ الْمَاءِ وَالْمِلْحِ أَنْضَجَ الدهمَامِيلَ وَيَـنْـفَعُ مِنَ الِاسْتِْرخَاءِ فِي جَِيَعِ الَْأعْضَاءِ وَيَزِيدُ فِي الْبَاهِ، وَيُشَهِّي الطهعَامَ وَيَـنْـفَعُ الهربْـوَ، وَعُسْرَ التهـنَـفُّسِ ، وغلظ الطحال، وينقي الرئة، ويرّ الطهمْثَ ، وَيَـنْـفَعُ مِنْ عِرْقِ النهسَا، وَوَجَعِ حُقِّ الْوَرِكِ مِمها يَْخرُجُ مِنَ الْفُضُولِ، إِذَا شُرِبَ أَوِ احْتُقِنَ بِهِ، وَيَْجلُو مَا فِي الصهدْرِ وَالرِّئَةِ مِنَ الْبَـلْغَمِ اللهزِجِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 157, 'وَإِنْ شُرِبَ مِنْهُ بَـعْدَ سَحْقِهِ وَزْنُ خَْمسَةِ دَرَاهِمَ بِالْمَاءِ الَْحارِّ، أَسْهَلَ الطهبِيعَةَ، وَحَلهلَ الرِّيَاحَ، وَنَـفَعَ مِنْ وَجَعِ الْقُولَنْجِ الْبَارِدِ السهبَبِ، وَإِذَا سُحِقَ وَشُرِبَ ، نَـفَعَ مِنَ الْبَـرَصِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 158, 'وَإِنْ لُطِّخَ عَلَيْهِ وَعَلَى الْبَـهَقِ الَْأبْـيَضِ بِالَْخلِّ، نَـفَعَ مِنْـهُمَا، وَيَـنْـفَعُ مِنَ الصُّدَاعِ الَْحادِثِ مِنَ الْبَـرْدِ وَالْبَـلْغَمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 159, 'وَإِنْ قُلِيَ، وَشُرِبَ ، عَقَلَ الطهبْعَ لَا سِيهمَا إِذَا لََْ يُسْحَقْ لِتَحَلُّلِ لُزُوجَتِهِ بِالْقَلْيِ، وَإِذَا غُسِلَ بَِمائِهِ الهرأْسُ ، نَـقهاهُ مِنَ الَْأوْسَاخِ وَالرُّطُوبَاتِ اللهزِجَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 160, 'قَالَ جالينوس قُـهوتُهُ مِثْلُ قُـهوةِ بَـزْرِ الَْخرْدَلِ، وَلِذَلِكَ قَدْ يُسَخهنُ بِهِ أَوْجَاعُ الْوَرِكِ الْمَعْرُوفَةُ بِالنهسَا، وَأَوْجَاعُ الهرأْسِ ، وَكُلُّ وَاحِدٍ مِنَ الْعِلَلِ الهتِي تَتََْاجُ إِلَى التهسْخِيِن، كَمَا يُسَخهنُ بزر الخردل، وقد يخلط أيما فِي أَدْوِيَةٍ يُسْقَاهَا أَصْحَابُ الهربْوِ مِنْ طَرِيقِ أَنه الَْأمْرَ فِيهِ مَعْلُومٌ أَنههُ يُـقَطِّعُ الَْأخْلَاطَ الْغَلِيظَةَ تَـقْطِيعًا قَوِيًّا، كَمَا يَـقْطَعُهَا بَـزْرُ الَْخرْدَلِ، لَِأنههُ شَبِيهٌ بِهِ فِي كُلِّ شَيْ ءٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 161, 'حُلْبَةٌ: يُذْكَرُ عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، أَنههُ عَادَ سَعْدَ بْنَ أَبِي وَقهاصٍ رَضِيَ ا هللَُّ عَنْهُ بَِمكهةَ، فَـقَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 162, 'ادْعُوا لَهُ طَبِيبًا، فَدُعِيَ الحارث بن كلدة، فَـنَظَرَ إِلَيْهِ، فَـقَالَ لَيْسَ عَلَيْهِ بَْأسٌ ، فَاهتِخذُوا لَهُ فَرِيقَةً، وَهِيَ الُْحلْبَةُ مَعَ تَرَِْ عَجْوَةٍ رَطْبٍ يُطْبَخَانِ، فَـيَحْسَاهُاَُ، ففعل ذلك، فبىَء.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 163, 'وَقُـهوةُ الُْحلْبَةِ مِنَ الَْحرَارَةِ فِي الدهرَجَةِ الثهانِيَةِ، وَمِنَ الْيُـبُوسَةِ فِي الُْأولَى، وَإِذَا طُبِخَتْ بِالْمَاءِ، لَيهـنَتِ الَْحلْقَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 164, 'وَالصهدْرَ وَالْبَطْنَ، وَتُسَكِّنُ السُّعَالَ وَالُْخشُونَةَ وَالهربْـوَ، وَعُسْرَ النهـفَسِ ، وَتَزِيدُ فِي الْبَاهِ، وَهِيَ جَيِّدَةٌ لِلرِّيحِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 165, 'وَالْبَـلْغَمِ وَالْبَـوَاسِيِر، مُدُِْرَةُ الْكَيْمُوسَاتِ الْمُرْتَبِكَةِ فِي الَْأمْعَاءِ، وَتُلََِّلُ الْبَـلْغَمَ الهلزجَِ مِنَ الصهدْرِ، وَتَـنْـفَعُ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 166, 'الدُّبَـيْلَاتِ وَأَمْرَاضِ الرِّئَةِ، وَتُسْتَـعْمَلُ لَِهذِهِ الَْأدْوَاءِ فِي الَْأحْشَاءِ مَعَ السهمْنِ وَالْفَانِيذِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 167, 'وَإِذَا شُرِبَتْ مَعَ وَزْنِ خَْمسَةِ دَرَاهِمِ فُـهوةٍ، أَدَرهتِ الَْحيْضَ ، وَإِذَا طُبِخَتْ ، وَغُسِلَ بَِها الشهعْرُ جَعهدَتْهُ، وَأَذْهَبَتِ الَْحزَازَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 168, 'وَدَقِيقُهَا إِذَا خُلِطَ بِالنهطْرُونِ وَالَْخلِّ، وَضُمِّدَ بِهِ، حَلهلَ وَرَمَ الطِّحَالِ، وَقَدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 169, 'تَلَِْسُ الْمَرْأَةُ فِي الْمَاءِ اهلذِي طُبِخَتْ فِيهِ الُْحلْبَةُ، فَـتَـنْـتَفِعُ بِهِ مِنْ وَجَعِ الهرحِمِ الْعَارِضِ مِنْ وَرَمٍ فِيهِ. وَإِذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 170, 'ضُمِّدَ بِهِ الَْأوْرَامُ الصُّلْبَةُ الْقَلِيلَةُ الَْحرَارَةِ، نَـفَعَتْـهَا وَحَلهلَتْـهَا، وَإِذَا شُرِبَ مَاؤُهَا، نَـفَعَ مِنَ الْمَغَصِ الْعَارِضِ مِنَ الرِّيَاحِ، وَأَزْلَقَ الَْأمْعَاءَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 171, 'وَإِذَا أُكِلَتْ مَطْبُوخَةً بِالتهمْرِ، أَوِ الْعَسَلِ، أَوِ التِّيِن عَلَى الرِّيقِ، حَلهلَتِ الْبَـلْغَمَ اللهزِجَ الْعَارِضَ فِي الصهدْرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 172, 'وَالْمَعِدَةِ، وَنَـفَعَتْ مِنَ السُّعَالِ الْمُتَطَاوِلِ مِنْهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 173, 'وَهِيَ نَافِعَةٌ مِنَ الَْحصْرِ، مُطْلِقَةٌ لِلْبَطْنِ، وَإِذَا وُضِ عَتْ عَلَى الظُّفْرِ الْمُتَشَنِّجِ أَصْلَحَتْهُ، وَدُهْنُـهَا يَـنْـفَعُ إِذَا خُلِطَ بِالشهمْعِ مِنَ الشُّقَاقِ الْعَارِضِ مِنَ الْبَـرْدِ، وَمَنَافِعُهَا أَضْعَافُ مَا ذكََرْنَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 174, 'وَيُذْكَرُ عَنِ الْقَاسِمِ بْنِ عَبْدِ الهرحْنَِْ، أَنههُ قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «اسْتَشْفُوا بِالُْحلْبَةِ»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 175, 'وَقَالَ بَـعْضُ الَْأطِبهاءِ: لَوْ عَلِمَ النهاسُ مَنَافِعَهَا، لَاشْتَـرَوْهَا بِوَزْنَِها ذَهَبًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 176, 'حَرْفُ الَْخاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 177, 'خُبْـزٌ: ثَـبَتَ فِي «الصهحِيحَيِْن» ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «تَكُونُ الَْأرْضُ يَـوْمَ الْقِيَامَةِ خُبْـزَةً وَاحِدَةً يَـتَكَ هفؤُهَا الَْجبهارُ بِيَدِهِ كَمَا يَكْفُؤُ أَحَدُكُمْ خُبْـزَتَهُ فِي السهفَرِ نُـزُلًا لَِأهْلِ الَْجنهةِ» »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 178, 'الطهعَامِ إِلَى رَسُولِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 179, 'وَرَوَى أبو داود فِي «سُنَنِهِ» : مِنْ حَدِيثِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْـهُمَا، قَالَ كَانَ أَحَبه ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ الثهرِيدُ مِنَ الُْخبْزِ، وَالثهرِيدُ مِنَ الَْحيْسِ ؟.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 180, 'وَرَوَى أبو داود فِي «سُنَنِهِ» أَيْضًا، مِنْ حَدِيثِ ابْنِ عُمَرَ رَضِيَ ا هللَُّ عَنْهُ، قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 181, '«وَدِدْتُ أَنه عِنْدِي خُبْـزَةً بَـيْضَاءَ مِنْ بُـهرةٍ سَْمرَاءَ مُلَبهـقَةً بسمن ولبن»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 182, 'قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 183, '،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 184, '(7) أخرجه البخاري في الرقاق. ومسلم في صفات المنافقين.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 185, 'فَـقَامَ رَجُلٌ مِنَ الْقَوْمِ فَاهتَخذَهُ، فَجَاءَ بِهِ، فَـقَالَ: «فِي أَيِّ شَيْ ءٍ كَانَ هَذَا السهمْنُ؟» فَـقَالَ: فِي عُكهةِ ضَبٍّ ، فَـقَالَ: «ارْفَـعْهُ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 186, 'وَذكََرَ البيهقي مِنْ حَدِيثِ عائشة رَضِيَ ا هللَُّ عَنْـهَا ترفعه «أكرموا الخبز، ومن كرامته ألاينتظر بِهِ الِْإدَامُ» »2« . وَالْمَوْقُوفُ أَشْبَهُ، فَلَا يَـثْـبُتُ رَفْـعُهُ، وَلَا رَفْعُ مَا قَـبْـلَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 187, 'وَأَمها حَدِيثُ النهـهْيِ عَنْ قَطْعِ الُْخبْزِ بِالسِّ كِّيِن، فَـبَاطِلٌ لَا أَصْلَ لَهُ عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَإِهنَما الْمَرْوِيُّ: النهـهْيُ عَنْ قَطْعِ اللهحْمِ بِالسِّ كِّيِن، وَلَا يَصِحُّ أَيْضًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 188, 'قَالَ مُهَنها سَأَلْتُ أحدْ عَنْ حَدِيثِ أبي معشر، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عائشة رَضِيَ ا هللَُّ عَنْـهَا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 189, 'عَنِ النهبِِّ صَ هلى ا هللَُّ عَلَيْهِ وَسَلهمَ «لَا تَـقْطَعُوا اللهحْمَ بِالسِّ كِّيِن، فَإِنه ذَلِكَ مِنْ فِعْلِ الَْأعَاجِمِ» »3« . فَـقَالَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 190, 'لَيْسَ بِصَحِيحٍ، وَلَا يُـعْرَفُ هَذَا، وَحَدِيثُ عَمْرِو بْنِ أُمَيهةَ خِلَافُ هَذَا، وَحَدِيثُ المغيرة- يَـعْنِِ بَِحدِيثِ عَمْرِو بْنِ أُمَيهةَ:- كَانَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَْحتَـزُّ مِنْ لَْحمِ الشهاةِ »4« . وَبَِحدِيثِ المغيرة أَنههُ لَمها أَضَافَهُ أَمَرَ بِنَِْبٍ فَشُوِيَ، ُ مه أَخَذَ الشهفْرَةَ، فَجَعَلَ يَُحزُّ »5« .', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ وَأَحْدَُْ أَنْـوَاعِ الُْخبْزِ أَجْ وَدُهَا اخْ تِمَارًا وَعَجْ نًا، ُ مه خُبْـزُ التهـنُّورِ أَجْ وَدُ أَصْنَافِهِ، وَبَـعْدَهُ خُبْـزُ الْفُرْنِ، ُ مه خُبْـزُ الْمَلهةِ فِي الْمَرْتَـبَةِ الثهالِثَةِ، وَأَجْ وَدُهُ مَا اتُِّخذَ مِنَ الِْحنْطَةِ الَْحدِيثَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَكْ ثَـرُ أَنْـوَاعِهِ تَـغْذِيَةً خُبْـزُ السهمِيذِ، وَهُوَ أَبْطَؤُهَا هَضْمًا لِقِلهةِ نُاَُلَتِهِ وَيَـتْـلُوهُ خُبْـزُ الحواري، م الخشكار.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '(7) أخرجه أبو داود وابن ماجة في الأطعمة. (2) حديث لا يصح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, '(3) أخرجه أبو داود.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, '(4) أخرجه البخاري في الأطعمة. ومسلم. (5) أخرجه أحدْ وأبو داود.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَأَحْدَُْ أَوْقَاتِ أَكْلِهِ فِي آخِرِ الْيَـوْمِ الهذِي خُبِزَ فِيهِ، وَاللهيُِّن مِنْهُ أَكْ ثَـرُ تَـلْيِينًا وَغِذَاءً وَتَـرْطِيبًا وَأَسْرَعُ انِْدَْارًا، وَالْيَابِسُ خِِلَِافِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَمِزَاجُ الُْخبْزِ مِنَ الْبُـرِّ حَارٌّ فِي وَسَطِ الدهرَجَةِ الثهانِيَةِ، وَقَرِيبٌ مِنَ الِاعْتِدَالِ فِي الرُّطُوبَةِ وَالْيُـبُوسَةِ، وَالْيُـبْسُ يَـغْلِبُ عَلَى مَا جَ هففَتْهُ النهارُ مِنْهُ، وَالرُّطُوبَةُ على مده.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَفِي خُبْزِ الِْحنْطَةِ خَاصِّ يهةٌ، وَهُوَ أَنههُ يُسَمِّنُ سَرِيعًا، وَخُبْـزُ الْقَطَائِفِ يُـوَلِّدُ خَلْطًا غَلِيظًا، وَالْفَتِيتُ نَـهفاخٌ بَطِيءُ الَْهضْمِ، وَالْمَعْمُولُ بِاللهبَِن مُسَدِّدٌ كَثِيُر الْغِذَاءِ، بَطِيءُ الِانِْدَْارِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَخُبْـزُ الشهعِيِر بَارِدٌ يَابِسٌ فِي الُْأولَى، وَهُوَ أَقَلُّ غِذَاءً مِنْ خُبْزِ الحنطة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'رَوَى مسلم فِي «صَحِيحِهِ» : عَنْ جَابِرِ بْنِ عَبْدِ ا هلِلَّ رَضِيَ ا هللَُّ عَنْـهُمَا، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ سَأَلَ أَهْلَهُ الِْإدَامَ، فَـقَالُوا مَا عِنْدَنَا إِهلا خَلٌّ، فَدَعَا بِهِ، وَجَعَلَ كََُْلُ وَيَـقُولُ: «نِعْمَ الِْإدَامُ الَْخلُّ، نِعْمَ الِْإدَامُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'الَْخلُّ» »7« . وَفِي «سُنَنِ ابْنِ مَاجَهْ» عَنْ أم سعد رَضِيَ ا هللَُّ عَنْـهَا عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «نِعْمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'الِْإدَامُ الَْخلُّ، اللههُمه بَارِكْ فِي الَْخلِّ، فَإِنههُ كَانَ إِدَامَ الَْأنْبِيَاءِ قَـبْلِي، وَلََْ يَـفْتَقِرْ بَـيْتٌ فِيهِ الَْخلُّ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'الَْخلُّ مُرَكهبٌ مِنَ الَْحرَارَةِ، وَالْبُـرُودَةُ أَغْلَبُ عَلَيْهِ، وَهُوَ يَابِسٌ فِي الثهالِثَةِ، قَوِيُّ التهجْفِيفِ، يَْمنَعُ مِنِ انْصِبَابِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'الْمَوَادِّ، وَيُـلَطِّفُ الطهبِيعَةَ، وَخَلُّ الَْخمْرِ يَـنْـفَعُ الْمَعِدَةَ الْمُلْتَهِبَةَ، وَيَـقْمَعُ الصهفْرَاءَ، وَيَدْفَعُ ضَرَرَ الَْأدْوِيَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'الْقَتهالَةِ، وَيَُحلِّلُ اللهبََن وَالدهمَ إِذَا جَدَََا فِي الَْجوْفِ، وَيَـنْـفَعُ الطِّحَالَ، وَيَدْبَغُ الْمَعِدَةَ، وَيَـعْقِلُ الْبَطْنَ، وَيَـقْطَعُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'الْعَطَشَ ، وَيَْمنَعُ الْوَرَمَ حَيْثُ يُرِيدُ أَنْ يَْحدُثَ ، وَيُعِيُن عَلَى الَْهضْمِ، وَيُضَادُّ الْبَـلْغَمَ، وَيُـلَطِّفُ الَْأغْذِيَةَ الْغَلِيظَةَ، وَيُرِقُّ الدهمَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَإِذَا شُرِبَ بِالْمِلْحِ، نَـفَعَ مِنْ أَكْلِ الْفِطْرِ الْقَتهالِ، وإذا احتسي، قطع العلق', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, '(7) أخرجه مسلم في الأشربة. (2) أخرجه ابن ماجة في الأطعمة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'الْمُتَـعَلِّقَ بَِأصْلِ الَْحنَكِ ، وَإِذَا تُضَُْمِضَ بِهِ مُسَخهنًا، نَـفَعَ مِنْ وَجَعِ الَْأسْنَانِ، وَقَـهوى اللِّثَةَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'وَهُوَ نَافِعٌ لِلدهاحِسِ ، إِذَا طُلِيَ بِهِ، وَالنهمْلَةِ وَالَْأوْرَامِ الَْحارهةِ، وَحَرْقِ النهارِ، وَهُوَ مُشَهٍّ لِلْكَِْلِ، مُطَيِّبٌ لِلْمَعِدَةِ، صَالِحٌ لِلشهبَابِ، وَفِي الصهيْفِ لِسُكهانِ الْبِلَادِ الحارةه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'خلال فِيهِ حَدِيثَانِ لَا يَـثْـبُـتَانِ، أَحَدُهُاَُ: يُـرْوَى مِنْ حَدِيثِ أَبِي أَيُّوبَ الَْأنْصَارِيِّ يَـرْفَـعُهُ «يَا حَبهذَا الْمُتَخَلِّلُونَ مِنَ الطهعَامِ، إِنههُ لَيْسَ شَيْءٌ أَشَده عَلَى الْمَلَكِ مِنْ بَقِيهةٍ تَـبْـقَى فِي الْفَمِ مِنَ الطهعَامِ» »', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, '. وَفِيهِ واصل بن السائب، قَالَ الْبُخَارِيُّ والرازي: مُنْكَرُ الَْحدِيثِ، وَقَالَ النهسَائِيُّ والأزدي: مَتْـرُوكُ الَْحدِيثِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'الثهانِي يُـرْوَى مِنْ حَدِيثِ ابْنِ عَبهاسٍ ، قَالَ عبد الله بن أحدْ سَأَلْتُ أَبِي عَنْ شَيْخٍ رَوَى عَنْهُ صالح الوحاظي يُـقَالُ لَهُ: محمد بن عبد الملك الأنصاري، حَدهثَـنَا عطاء، عَنِ ابْنِ عَبهاسٍ ، قَالَ نَـهَى رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وسلم أن يُـتَخَلهلَ بِاللِّيطِ وَالْآسِ ، وَقَالَ: «إِنهـهُمَا يَسْقِيَانِ عُرُوقَ الُْجذَامِ» فَـقَالَ أَبِي رَأَيْتُ مُمَُهدَ بْنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'عَبْدِ الْمَلِكِ - وَكَانَ أَعْمَى- يَضَعُ الَْحدِيثَ ، وَيَكْذِبُ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'وَبَـعْدُ فَالِْخلَالُ نَافِعٌ لِلِّثَةِ وَالَْأسْ نَانِ، حَافِظٌ لِصِحهتِهَا، نَافِعٌ مِنْ تَـغَيُِّر النهكْهَةِ، وَأَجْ وَدُهُ مَا اتُِّخذَ مِنْ عِيدَانِ الَْأخِلهةِ، وَخَشَبِ الهزيْـتُونِ وَالِْخلَافِ، وَالتهخَلُّلُ بِالْقَصَبِ وَالْآسِ وَالهريَْحانِ، وَالْبَاذَرُوجِ مُضِرٌّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'حَرْفُ الدهالِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'دُهْنٌ رَوَى الترمذي فِي كِتَابِ «الشهمَائِلِ» مِنْ حَدِيثِ أَنَسِ بْنِ مَالِكٍ رَضِيَ ا هللَُّ عَنْـهُمَا، قَالَ كَانَ رَسُولُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يُكْثِرُ دُهْنَ رَأْسِهِ، وَتَسْرِيحَ لِْحيَتِهِ، وَيُكْثِرُ الْقِنَاعَ كأنّ ثوبه ثفو زيّات »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, '(7) أخرجه أحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, '(2) أخرجه الترمذي في الشمائل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'الدهن يسد مسام البدنج وَيَْمنَعُ مَا يَـتَحَلهلُ مِنْهُ، وَإِذَا اسْتُـعْمِلَ بَـعْدَ الِاغْتِسَالِ بِالْمَاءِ الَْحارِّ، حَسهنَ الْبَدَنَ وَرَطهبَهُ، وَإِنْ دُهِنَ بِهِ الشهعْرُ حَسهنَهُ وَطَهولَهُ، وَنَـفَعَ مِنَ الَْحصْبَةِ، وَدَفَعَ أَكْ ثَـرَ الْآفَاتِ عَنْهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'وَفِي الترمذي مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ رَضِيَ ا هللَُّ عَنْهُ مرفوعا: «كلوا الزّي وَادههِنُوا بِهِ» »7« . وَسَيَأْتِي إِنْ شَاءَ ا هللَُّ تَـعَالَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَالدُّهْنُ فِي الْبِلَادِ الَْحارهةِ، كَالِْحجَازِ وَنَوِْْهِ مِنْ آكَدِ أَسْبَابِ حِفْظِ الصِّحهةِ وَإِصْلَاحِ الْبَدَنِ، وَهُوَ كَالضهرُورِيِّ لَهمُْ، وَأَمها الْبِلَادُ الْبَارِدَةُ، فَلَا يَْحتَاجُ إِلَيْهِ أَهْلُهَا، وَالِْإلَْحاحُ بِهِ فِي الهرأْسِ فِيهِ خطر بالبصره', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وَأَنْـفَعُ الَْأدْهَانِ الْبَسِيطَةِ: الهزيْتُ ، ُ مه السهمْنُ ُ مه الشيرج', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'وأما المركبة منها بَارِدٌ رَطْبٌ ، كَدُهْنِ الْبَـنَـفْسَجِ يَـنْـفَعُ مِنَ الصُّدَاعِ الَْحارِّ، وَيُـنَـوِّمُ أَصْحَابَ السههَرِ، وَيُـرَطِّبُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'الدِّمَاغَ، وَيَـنْـفَعُ مِنَ الشُّقَاقِ، وَغَلَبَةِ الْيُـبْسِ ، وَالَْجفَافِ، وَيُطْلَى بِهِ الَْجرَبُ ، وَالِْحكهةُ الْيَابِسَةُ، فَـيَـنْـفَعُهَا وَيُسَهِّلُ حَرَكَةَ الْمَفَاصِلِ، وَيَصْلُحُ لَِأصْحَابِ الَْأمْزِجَةِ الَْحارهةِ فِي زَمَنِ الصهيْفِ، وَفِيهِ حَدِيثَانِ بَاطِلَانِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'مَوْضُوعَانِ عَلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَحَدُهُاَُ: «فَضْلُ دُهْنِ الْبَـنَـفْسَجِ عَلَى سَائِرِ الَْأدْهَانِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'كَفَضْلِي عَلَى سَائِرِ النهاسِ » . وَالثهانِي: فَضْلُ دُهْنِ الْبَـنَـفْسَجِ عَلَى سَائِرِ الَْأدْهَانِ، كَفَضْلِ الِْإسْلَامِ عَلَى سَائِرِ الَْأدْيَانِ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'وَمِنْـهَا: حَارٌّ رَطْبٌ ، كَدُهْنِ الْبَانِ ، وَلَيْسَ دُهْنَ زَهْرِهِ، بَلْ دُهْنٌ يُسْتَخْ رَجُ مِنْ حَبٍّ أَبْـيَضَ أَغْبَـرَ نَوِْْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'الْفُسْتُقِ، كَثِيِر الدُّهْنِيهةِ وَالدهسَمِ، يَـنْـفَعُ مِنْ صَلَابَةِ الْعَصَبِ، وَيُـلَيِّنُهُ، وَيَـنْـفَعُ مِنَ الْبَـرَشِ وَالنهمَشِ ، والكيلف وَالْبَـهَقِ، وَيُسَهِّلُ بَـلْغَمًا غَلِيظًا، وَيُلِيُن الَْأوْتَارَ الْيَابِسَةَ، وَيُسَخِّ نُ الْعَصَبَ ، وَقَدْ رُوِيَ فِيهِ حَدِيثٌ بَاطِلٌ مُْختَـلَقٌ لَا أَصْلَ لَهُ « «ادههِنُوا بِالْبَانِ ، فَإِنههُ أَحْظَى لَكُمْ عِنْدَ نِسَائِكُمْ» . وَمِنْ مَنَافِعِهِ أَنههُ يَْجلُو الَْأسْنَانَ، وَيُكْسِبُـهَا بَـهْجَةً، وَيُـنَـقِّيهَا مِنَ الصهدَأِ، وَمَنْ مَسَحَ بِهِ وَجْ هَهُ وَأَطْرَافَهُ لََْ يُصِبْهُ حصى ولا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, '(7) أخرجه الترمذي في الأطعمة وأحدْ والدارمي وابن ماجه والحاكم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'شُقَاقٌ ، وَإِذَا دَهَنَ بِهِ حِقْوَهُ وَمَذَاكِيَرهُ وَمَا وَالَاهَا، نَـفَعَ مِنْ بَـرْدِ الْكُلْيَـتَـيِْن، وَتَـقْطِيِر الْبَـوْلِ. حَرْفُ الذهالِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'ذَرِيرَةٌ: ثَـبَتَ فِي «الصهحِيحَيِْن» : عَنْ عَائِشَةَ رَضِيَ ا هللَُّ عَنْـهَا قَالَتْ : طَيهـبْتُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بِيَدِي، بِذَرِيرَةٍ فِي حَجهةِ الْوَدَاعِ لِِحلِّهِ وَإِحْ رَامِهِ »7« تَـقَدهمَ الْكَلَامُ فِي الذهرِيرَةِ وَمَنَافِعِهَا وَمَاهِيهتِهَا، فَلَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'حَاجَةَ لِِإعَادَتِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'ذباب: تَـقَدهمَ فِي حَدِيثِ أَبِي هُرَيْـرَةَ الْمُتهـفَقِ عَلَيْهِ في أمره صلّى الله عليه وسلم يغمس الذُّبَابِ فِي الطهعَامِ إِذَا سَقَطَ فِيهِ لَِأجْلِ الشِّ فَاءِ الهذِي فِي جَنَاحِهِ، وَهُوَ كَالتِّْريَاقِ لِلسُّمِّ الهذِي فِي الَْجنَاحِ الْآخَرِ، وَذكََرْنَا مَنَافِعَ الذُّبَابِ هناك.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'ذهب رَوَى أبو داود، وَالتِّْرمِذِيُّ «أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ رَخهصَ لعرفجة بن أسعد لَمها قُطِعَ أَنْـفُهُ يَـوْمَ الْكُ هلابِ، وَاهتَخذَ أَنْـفًا مِنْ وَرِقٍ، فَأَنْـتََُ عَلَيْهِ، فَأَمَرَهُ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنْ يَـتهخِذَ أَنْـفًا مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'ذَهَبٍ» »2« . وَلَيْسَ لعرفجة عِنْدَهُمْ غَيْـرُ هَذَا الَْحدِيثِ الْوَاحِدِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 48, 'الذههَبُ : زِينَةُ الدُّنْـيَا، وَطِلهسْمُ الْوُجُودِ، وَمُفْرِحُ النُّـفُوسِ ، وَمُقَوِّي الظُّهُورِ، وَسِرُّ ا هلِلَّ فِي أَرْضِهِ، وَمِزَاجُهُ فِي سَائِرِ الْكَيْفِيهاتِ، وَفِيهِ حَرَارَةٌ لَطِيفَةٌ تَدْخُلُ فِي سَائِرِ الْمَعْجُونَاتِ اللهطِيفَةِ وَالْمُفْرِحَاتِ، وَهُوَ أَعْدَلُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 49, 'الْمَعَادِنِ عَلَى الِْإطْلَاقِ وَأَشْرَفُـهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 50, 'وَمِنْ خَوَاصههِ أَنههُ إِذَا دُفِنَ فِي الَْأرْضِ ، لََْ يَضُهرهُ التُّـرَابُ ، وَلََْ يَـنْـقُصْهُ شَيْـئًا، وَبُـرَادَتُهُ إِذَا خُلِطَتْ بِالَْأدْوِيَةِ، نَـفَعَتْ مِنْ ضَعْفِ الْقَلْبِ، وَالهرجَفَانِ الْعَارِضِ مِنَ السهوْدَاءِ، وَيَـنْـفَعُ مِنْ حَدِيثِ النهـفْسِ ، وَالُْحزْنِ، وَالْغَمِّ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 51, 'وَالْفَزَعِ ، وَالْعِشْقِ، وَيُسَمِّنُ الْبَدَنَ، وَيُـقَوِّيهِ، وَيُذْهِبُ الصهفَارَ، وَيَُحسِّ نُ اللهوْنَ، وَيَـنْـفَعُ مِنَ الُْجذَامِ، وَجَِيَعِ الَْأوْجَاعِ وَالَْأمْرَاضِ السهوْدَاوِيهةِ وَيَدْخُلُ خِاَِصِّ يهةٍ فِي أَدْوِيَةِ داء الثعلب، وداء الحية', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 52, '(7) أخرجه البخاري في اللباس، ومسلم في الحج.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 53, '(2) أخرجه أبو داود في الخاتم والترمذي وأحدْ وصححه ابن حبان.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 54, 'شُرْبًا وَطِلَاءً، وَيَْجلُو الْعَيَْن وَيُـقَوِّيهَا، وَيَـنْـفَعُ مِنْ كَثِيٍر مِنْ أَمْرَاضِهَا، وَيُـقَوِّي جَِيَعَ الَْأعْضَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 55, 'وَإِمْسَاكُهُ فِي الْفَمِ يُزِيلُ الْبَخْرَ، وَمَنْ كَانَ بِهِ مَرَضٌ يَْحتَاجُ إِلَى الْكَيِّ، وَكُوِيَ بِهِ لََْ يَـتَـنَـهفطْ مَوْضِ عُهُ، وَيَـبْـرَأُ سَرِيعًا، وَإِنِ اهتَخذَ مِنْهُ مَيْلًا وَاكْ تَحَلَ بِهِ، قَـهوى الْعَيَْن وَجَلَاهَا، وَإِذَا اتُِّخذَ مِنْهُ خَاتٌَم فَصُّهُ مِنْهُ وَأُحِْيَْ ، وَكُوِيَ بِهِ قَـوَادِمُ أَجْنِحَةِ الَْحمَامِ، أَلِفَتْ أَبْـرَاجَهَا، وَلََْ تَـنْـتَقِلْ عَنْـهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 56, 'وَلَهُ خَاصِّ يهةٌ عَجِيبَةٌ فِي تَـقْوِيَةِ النُّـفُوسِ ، لَِأجْلِهَا أُبِيحَ فِي الَْحرْبِ وَالسِّ لَاحِ مِنْهُ مَا أُبِيحَ، وَقَدْ رَوَى الترمذي مِنْ حَدِيثِ مزيدة العصري رَضِيَ ا هللَُّ عَنْهُ، قَالَ دَخَلَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـوْمَ الْفَتْحِ، وَعَلَى سَيْفِهِ ذَهَبٌ وَفِضهةٌ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 57, 'وَهُوَ مَعْشُوقُ النفوس التي متى فرحت بِهِ، سَ هلاهَا عَنْ غَيِْرهِ مِنْ مَبُُْوبَاتِ الدُّنْـيَا، قَالَ تَـعَالَى: زُيِّنَ لِلنهاسِ حُبُّ الشههَواتِ مِنَ النِّساءِ وَالْبَنِيَن وَالْقَناطِيِر. الْمُقَنْطَرَةِ مِنَ الذههَبِ وَالْفِضهةِ وَالَْخيْلِ الْمُسَ هومَةِ وَالَْأنْعامِ وَالَْحرْثِ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 58, 'وَفِي «الصهحِيحَيِْن» عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ «لَوْ كَانَ لِابْنِ آدَمَ وَادٍ مِنْ ذَهَبٍ لَابْـتَـغَى إِلَيْهِ ثَنَِيًا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 59, 'وَلَوْ كَانَ لَهُ ثَنٍَ ، لَابْـتَـغَى إِلَيْهِ ثَلَِثًا، وَلَا يَْملَُِ جَوْفَ ابْنِ آدَمَ إِهلا التُّـرَابُ ، وَيَـتُوبُ ا هللَُّ عَلَى مَنْ تَابَ » .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 60, 'هَذَا وَإِنههُ أَعْظَمُ حَائِلٍ بَـيَْن الَْخلِيقَةِ وَبَـيَْن فَـوْزِهَا الَْأكْبََِ يَـوْمَ مَعَادِهَا، وَأَعْظَمُ شَيْءٍ عُصِيَ ا هللَُّ بِهِ، وَبِهِ قُطِعَتِ الَْأرْحَامُ، وَأُرِيقَتِ الدِّمَاءُ، وَاسْتُحِلهتِ الْمَحَارِمُ، وَمُنِعَتِ الُْحقُوقُ ، وَتَظَالَََ الْعِبَادُ، وَهُوَ الْمُرَغِّبُ فِي الدُّنْـيَا وَعَاجِلِهَا، وَالْمُزَهِّدُ فِي الْآخِرَةِ وَمَا أَعَدههُ ا هللَُّ لَِأوْلِيَائِهِ فِيهَا، فَكَمْ أُمِيتَ بِهِ مِنْ حَقٍّ وَأُحْيِيَ بِهِ مِنْ بَاطِلٍ وَنُصِرَ بِهِ ظَالٌَِ، وَقُهِرَ بِهِ مَظْلُومٌ، وَمَا أَحْسَنَ مَا قَالَ فِيهِ الحريري »3« :', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 61, '(7) أخرجه الترمذي في الجهاد. (2) آل عمران- .74', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 62, '(3) أخرجه البخاري في الرقاق، ومسلم في الزكاة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 63, 'تبا له من خادع مماذق ... أصفر في وَجْ هَيِْن كَالْمُنَافِقِ يَـبْدُو بِوَصْفَيِْن لِعَيِْن الهرامِقِ ... زِينَةِ مَعْشُوقٍ وَلَوْنِ عَاشِقِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 64, 'وَحُبُّهُ عِنْدَ ذَوِي الَْحقَائِقِ ... يَدْعُو إِلَى ارْتِكَابِ سُخْطِ الَْخالِقِ لَوْلَاهُ لََْ تُـقْطَعْ يَِميُن السهارِقِ ... وَلَا بَدَتْ مَظْلِمَةٌ مِنْ فاسق', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 65, 'ولا اشمأزّ باطل مِنْ طَارِقِ ... وَلَا اشْتَكَى الْمَمْطُولُ مَطْلَ الْعَائِقِ وَلَا اسْتُعِيذَ مِنْ حَسُودٍ رَاشِقِ ... وَشَرُّ مَا فِيهِ مِنَ الَْخلَائِقِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 66, 'أَنْ لَيْسَ يُـغْنِِ عَنْكَ فِي الْمَضَايِقِ ... إِهلا إِذَا فَـهر فِرَارَ الْآبِقِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 67, 'حَرْفُ الهراءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 68, 'رُطَبٌ : قَالَ ا هللَُّ تَـعَالَى لِمَرْيََم: وَهُزِّي إِلَيْكِ بِِذِْعِ النهخْلَةِ تُساقِطْ عَلَيْكِ رُطَباً جَنِيًّا فَكُلِي وَاشْرَبِي وَقَـرِّي عَيْناً »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 69, 'وَفِي «الصهحِيحَيِْن» عَنْ عبد الله بن جعفر، قَالَ: رَأَيْتُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وسلم كَل القثّاء بالرطب »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 70, '«سُنَنِ أبي داود» عَنْ أنس قَالَ: كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يُـفْطِرُ عَلَى رُطَبَاتٍ قَـبْلَ أَنْ يُصَلِّيَ ، فَإِنْ لََْ تَكُنْ رُطَبَاتٌ فَـتَمَرَاتٍ، فَإِنْ لََْ تَكُنْ تَرَََاتٌ ، حَسَا حَسَوَاتٍ مِنْ مَاءٍ »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 71, 'طَبْعُ الرُّطَبِ طَبْعُ الْمِيَاهِ حَارٌّ رَطْبٌ ، يُـقَوِّي الْمَعِدَةَ الْبَارِدَةَ وَيُـوَافِقُهَا، وَيَزِيدُ فِي الْبَاهِ، وَيُْخصِبُ الْبَدَنَ، وَيُـوَافِقُ أَصْحَابَ الَْأمْزِجَةِ الْبَارِدَةِ وَيَـغْذُو غِذَاءً كَثِيًرا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 72, 'وَهُوَ مِنْ أَعْظَمِ الْفَاكِهَةِ مُوَافَـقَةً لَِأهْلِ الْمَدِينَةِ وَغَيِْرهَا مِنَ البلاد التي هو', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 73, '(7) مريم- .25', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 74, '(2) أخرجه البخاري في الأطعمة، ومسلم في الأشربة. (3) رواه أبو داود والترمذي وأحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 75, 'فَاكِهَتُـهُمْ فِيهَا وَأَنْـفَعُهَا لِلْبَدَنِ، وَإِنْ كَانَ مَنْ لََْ يَـعْتَدْهُ يُسْرعُِ التهـعَفُّنَ فِي جَسَدِهِ، وَيَـتَـوَلهدُ عَنْهُ دَمٌ لَيْسَ بَِمحْمُودٍ، وَيُْحدِثُ فِي إِكْ ثَارِهِ مِنْهُ صُدَاعٌ وَسَوْدَاءُ، وَيُـؤْذِي أَسْنَانَهُ، وَإِصْلَاحُهُ بِالسهكَنْجِبَـيِْن وَنَوِْْهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 76, 'وَفِي فِطْرِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مِنَ الصهوْمِ عَلَيْهِ، أَوْ عَلَى التهمْرِ، أَوِ الْمَاءِ تَدْبِيٌر لَطِيفٌ جِدًّا فَإِنه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 77, 'الصهوْمَ يَُخلِّي الْمَعِدَةَ مِنَ الْغِذَاءِ، فَلَا تَِدَُ الْكَبِدُ فِيهَا مَا تَذَِْبُهُ وَتُـرْسِلُهُ إِلَى الْقُوَى وَالَْأعْضَاءِ، وَالُْحلْوُ أَسْرَعُ شَيْ ءٍ وُصُولًا إِلَى الْكَبِدِ، وَأَحَبُّهُ إِلَيْـهَا، وَلَا سِيهمَا إِنْ كَانَ رُطَبًا فَـيَشْتَدُّ قَـبُولَُها لَهُ، فَـتَـنْـتَفِعُ بِهِ هِيَ وَالْقُوَى، فَإِنْ لََْ يَكُنْ ، فَالتهمْرُ لَِحلَاوَتِهِ وَتَـغْذِيَتِهِ فَإِنْ لََْ يكن، فحسوات الماء تطفىء لَِهيبَ الْمَعِدَةِ، وَحَرَارَةَ الصهوْمِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 78, 'فَـتَـتَـنَـبههُ بَـعْدَهُ لِلطهعَامِ، وتخَذه بشهوة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 79, 'ريحان: قَالَ تَـعَالَى: فَأَمها إِنْ كانَ مِنَ الْمُقَهربِيَن فَـرَوْحٌ وَرَيْحانٌ وَجَنهةُ نَعِيمٍ »7« وقال تعالى: وَالَْحبُّ ذُو', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 80, 'الْعَصْفِ وَالهريْحانُ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 81, 'وَفِي «صَحِيحِ مسلم» عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ:: «مَنْ عُرِضَ عَلَيْهِ رَيَْحانٌ فَلَا يرده، فإنه خفيف المحمل طيب الرائحة» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 82, 'وفي «سُنَنِ ابْنِ مَاجَهْ» : مِنْ حَدِيثِ أسامة رَضِيَ ا هللَُّ عَنْهُ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ أَلَا مُشَمِّرٌ لِلْجَنهةِ، فَإِنه الَْجنهةَ لَا خَطَرَ لََها، هِيَ وَرَبِّ الْكَعْبَةِ، نُورٌ يَـتَلَلَُِْأ، وَرَيَْحانَةٌ تَـهْتَـزُّ، وَقَصْرٌ مَشِيدٌ وَنَـهْرٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 83, 'مُطهرِدٌ وَثَرَََةٌ نَضِيجَةٌ وَزَوْجَةٌ حَسْنَاءُ جَِيَلَةٌ، وَحُلَلٌ كَثِيَرةٌ فِي مَقَامٍ أَبَدًا، فِي حِبَـرَةٍ وَنَضْرَةٍ، فِي دُورٍ عَالِيَةٍ سَلِيمَةٍ بَِهيهةٍ» قَالُوا: نَـعَمْ يَا رَسُولَ ا هلِلَّ، نَنُْْ الْمُشَمِّرُونَ لََها قَالَ: قُولُوا: إِنْ شَاءَ ا هللَُّ تَـعَالَى» ، فَـقَالَ الْقَوْمُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 84, 'إِنْ شَاءَ ا هللَُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 85, 'الهريَْحانُ كُلُّ نَـبْتٍ طَيِّبِ الرِّيحِ، فَكُلُّ أَهْلِ بَـلَدٍ يَُخصُّونَهُ بِشَيْ ءٍ مِنْ ذَلِكَ ، فَأَهْلُ الْغَرْبِ يَُخصُّونَهُ بِالْآسِ ، وَهُوَ الهذِي يَـعْرِفُهُ الْعَرَبُ مِنَ الهريَْحانِ ، وَأَهْلُ الْعِرَاقِ وَالشهامِ يخصّونه بالحبق.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 86, '(7) - الواقعة- .99 (2) الرحنْ- .72', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 87, 'فَأَمها الْآسُ فَمِزَاجُهُ بَارِدٌ فِي الُْأولَى يَابِسٌ فِي الثهانِيَةِ، وَهُوَ مَعَ ذَلِكَ مُرَكهبٌ مِنْ قُـوًى مُتَضَادهةٍ، وَالَْأكْ ثَـرُ فِيهِ الَْجوْهَرُ الَْأرْضِ يُّ الْبَارِدُ، وَفِيهِ شَيْ ءٌ حَارٌّ لَطِيفٌ ، وَهُوَ يَُجفِّفُ تَفَِْيفًا قَوِيًّا، وَأَجْ زَاؤُهُ مُتَـقَارِبَةُ الْقُهوةِ، وَهِيَ قُـهوةٌ قَابِضَةٌ حَابِسَةٌ مِنْ دَاخِلٍ وَخَارِجٍ مَعًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 88, 'وَهُوَ قَاطِعٌ لِلِْسْْهَالِ الصهفْرَاوِيِّ ، دَافِعٌ لِلْبُخَارِ الَْحارِّ الهرطْبِ إِذَا شُمه، مُفْرِحٌ لِلْقَلْبِ تَـفْرِيًحا شَدِيدًا، وَشَُّمهُ مَانِعٌ للوباء، وكذلك افتراشه في البيت.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 89, 'ويبىَء الَْأوْرَامَ الَْحادِثَةَ فِي الَْحالِبَـيِْن إِذَا وُضِعَ عَلَيْـهَا، وَإِذَا دُقه وَرَقُهُ وَهُوَ غَضٌّ وَضُرِبَ بِالَْخلِّ، وَوُضِعَ عَلَى الهرأْسِ ، قَطَعَ الرُّعَافَ ، وَإِذَا سُحِقَ وَرَقُهُ الْيَابِسُ ، وَذُره عَلَى الْقُرُوحِ ذَوَاتِ الرُّطُوبَةِ نَـفَعَهَا، وَيُـقَوِّي الَْأعْضَاءَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 90, 'الْوَاهِيَةَ إِذَا ضُمِّدَ بِهِ، وَيَـنْـفَعُ دَاءَ الدهاحِسِ ، وَإِذَا ذُره عَلَى الْبُـثُورِ وَالْقُرُوحِ الهتِي فِي الْيَدَيْنِ وَالرِّجْ لَيِْن، نَـفَعَهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 91, 'وَإِذَا دُلِّكَ بِهِ الْبَدَنُ قَطَعَ الْعَرَقَ ، وَنَشهفَ الرُّطُوبَاتِ الفضيلة، وَأَذْهَبَ نَـتَُْ الِْإبِطِ، وَإِذَا جُلِسَ فِي طَبِيخِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 92, 'نَـفَعَ مِنْ خَرَارِيجِ الْمَقْعَدَةِ وَالهرحِمِ، وَمِنِ اسْتِْرخَاءِ الْمَفَاصِلِ، وَإِذَا صُبه عَلَى كُسُورِ الْعِظَامِ الهتِي لََْ تَـلْتَحِمْ، نَـفَعَهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 93, 'وَيَْجلُو قُشُورَ الهرأْسِ وَقُـرُوحَهُ الهرطْبَةَ، وَبُـثُورَهُ، وَيُْمسِكُ الشهعْرَ الْمُتَسَاقِطَ وَيُسَوِّدُهُ، وَإِذَا دُقه وَرَقُهُ، وَصُبه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 94, 'عَلَيْهِ مَاءٌ يَسِيٌر، وَخُلِطَ بِهِ شَيْ ءٌ مِنْ زَيْتٍ أَوْ دُهْنِ الْوَرْدِ، وَضُمِّدَ بِهِ، وَافَقَ الْقُرُوحَ الهرطْبَةَ وَالنهمْلَةَ وَالُْحمْرَةَ، وَالَْأوْرَامَ الَْحادهةَ، وَالشهرَى وَالْبَـوَاسِيَر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 95, 'وَحَبُّهُ نَافِعٌ مَنْ نَـفْثِ الدهمِ الْعَارِضِ فِي الصهدْرِ وَالرِّئَةِ، دَابِغٌ لِلْمَعِدَةِ وَلَيْسَ بِضَارٍّ لِلصهدْرِ وَلَا الرِّئَةِ لَِجلَاوَتِهِ، وَخَاصِّ يهـتُهُ النهـفْعُ مِنِ اسْتِطْلَاقِ الْبَطْنِ مَعَ السُّعَالِ، وَذَلِكَ نَادِرٌ فِي الَْأدْوِيَةِ، وَهُوَ مُدِرٌّ لِلْبَـوْلِ، نَافِعٌ مَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 96, 'لَذْعِ الْمَثَانَةِ، وَعَضِّ الرُّتَـيْلَاءِ، وَلَسْعِ الْعَقَارِبِ، وَالتهخَلُّلُ بِعِرْقِهِ مُضِرٌّ، فَـلْيُحْذَرْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 97, 'وَأَمها الهريَْحانُ الْفَارِسِيُّ الهذِي يُسَمهى الَْحبَقَ، فَحَارٌّ فِي أَحَدِ الْقَوْلَيِْن، يَـنْـفَعُ شَُّمهُ مِنَ الصُّدَاعِ الَْحارِّ إِذَا رُشه عَلَيْهِ الْمَاءُ وَيُـبَـرِّدُ، وَيُـرَطِّبُ بِالْعَرَضِ ، وَبَارِدٌ فِي الْآخَرِ، وَهَلْ هُوَ رَطْبٌ أَوْ يَابِسٌ ؟ عَلَى قَـوْلَيِْن. وَالصهحِيحُ: أَنه فِيهِ مِنَ الطهبَائِعِ الأربع،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 98, 'وَيَْجلِبُ النهـوْمَ، وَبَـزْرُهُ حَابِسٌ لِلِْسْْهَالِ الصهفْرَاوِيِّ ، وَمُسَكِّنٌ لِلْمَغَصِ ، مُقَوٍّ لِلْقَلْبِ، نَافِعٌ لِلْمَِْرَاضِ السهوْدَاوِيهةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 99, 'رُمهانٌ: قال تعالى فِيهِما فاكِهَةٌ وَْنَلٌُ وَرُمهانٌ ]7[ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 100, 'وَيُذْكَرُ عَنِ ابْنِ عَبهاسٍ مَوْقُوفًا وَمَرْفُوعًا: «مَا مِنْ رُمهانٍ مِنْ رُمهانِكُمْ هَذَا إِهلا وَهُوَ مُلَقهحٌ بَِحبهةٍ مِنْ رُمهانِ الَْجنهةِ» وَالْمَوْقُوفُ أَشْبَهُ. وَذكََرَ حرب وَغَيْـرُهُ عَنْ علي أَنههُ قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 101, '«كُلُوا الرُّمهانَ بِشَحْمِهِ، فَإِنههُ دِبَاغُ الْمَعِدَةِ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 102, 'حُلْوُ الرُّمهانِ حَارٌّ رَطْبٌ ، جَيِّدٌ لِلْمَعِدَةِ، مُقَوٍّ لََها بَِما فِيهِ مِنْ قَـبْضٍ لَطِيفٍ، نَافِعٌ لِلْحَلْقِ والصدر والرئة، جيد للسعال، وماؤه ملين للبطن، يغذي الْبَدَنَ غِذَاءً فَاضِلًا يَسِيًرا، سَرِيعُ التهحَلُّلِ لِرِقهتِهِ وَلَطَافَتِهِ، وَيُـوَلِّدُ حَرَارَةً يَسِيَرةً فِي الْمَعِدَةِ وَرِيًحا، وَلِذَلِكَ يُعِيُن عَلَى الْبَاهِ، وَلَا يَصْلُحُ لِلْمَحْمُومِيَن، وَلَهُ خَاصِّ يهةٌ عَجِيبَةٌ إِذَا أُكِلَ بِالُْخبْزِ يَْمنَـعُهُ مِنَ الْفَسَادِ فِي الْمَعِدَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 103, 'وَحَامِضُهُ بَارِدٌ يَابِسٌ ، قَابِضٌ لَطِيفٌ ، يَـنْـفَعُ الْمَعِدَةَ الْمُلْتَهِبَةَ، وَيُدِرُّ الْبَـوْلَ أَكْ ثَـرَ مِنْ غَيِْرهِ مِنَ الرُّمهانِ، وَيُسَكِّنُ الصهفْرَاءَ، ويقطع الإسهال، ويمنع القيء، ويلطف الفضول.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 104, 'ويطفىء حَرَارَةَ الْكَبِدِ، وَيُـقَوِّي الَْأعْضَاءَ، نَافِعٌ مِنَ الَْخفَقَانِ الصهفْرَاوِيِّ ، وَالْآلَامِ الْعَارِضَةِ لِلْقَلْبِ، وَفَمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 105, 'الْمَعِدَةِ، وَيُـقَوِّي المعدة، ويدفع الفضول عنها، ويطفىء الْمِ هرةَ الصهفْرَاءَ وَالدهمَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 106, 'وَإِذَا اسْتُخْرِجَ مَاؤُهُ بِشَحْمِهِ، وَطُبِخَ بِيَسِيٍر مِنَ الْعَسَلِ حَ هتى يَصِيَر كَالْمَرْهَمِ، وَاكْ تُحِلَ بِهِ، قَطَعَ الصهفْرَةَ مِنَ الْعَيِْن، وَنَـقهاهَا مِنَ الرُّطُوبَاتِ الْغَلِيظَةِ، وَإِذَا لُطِّخَ عَلَى اللِّثَةِ، نَـفَعَ مِنَ الَْأكَلَةِ الْعَارِضَةِ لََها، وَإِنِ اسْتُخْرِجَ مَاؤُهُاَُ بِشَحْمِهِمَا أَطْلَقَ الْبَطْنَ وَأَحْدَرَ الرُّطُوبَاتِ الْعَفِنَةَ الْمُرِّيهةَ وَنَـفَعَ مِنْ حُهْيَاتِ الْغِبِّ الْمُتَطَاوِلَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 107, 'وَأَمها الرُّمهانُ الْمُزُّ، فَمُتَـوَسِّطٌ طَبْـعًا وَفِعْلًا بَـيَْن النهـوْعَيِْن، وَهَذَا أَمْيَلُ إِلَى لَطَافَةِ الَْحامِضِ قَلِيلًا، وَحَبُّ الرُّمهانِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 108, '»7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 109, 'مَعَ الْعَسَلِ طِلَاءٌ لِلدهاحِسِ وَالْقُرُوحِ الَْخبِيثَةِ وَأَقْمَاعُهُ لِلْجِرَاحَاتِ قَالُوا وَمَنِ ابْـتَـلَعَ ثَلَاثَةً مِنْ جُنْـبُذِ الرُّمهانِ فِي كُلِّ سَنَةٍ أَمِنَ مِنَ الهرمَدِ سَنَـتَهُ كُلههَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 110, 'حَرْفُ الهزايِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 111, 'زَيْتٌ : قَالَ تَـعَالَى: يُوقَدُ مِنْ شَجَرَةٍ مُباركََةٍ زَيْـتُونَةٍ لَا شَرْقِيهةٍ وَلا غَرْبِيهةٍ يَكادُ زَيْـتُها يُضِيءُ وَلَوْ لََْ تَسََْسْهُ نارٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 112, '. »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 113, 'وَفِي الترمذي وَابْنِ مَاجَهْ مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ رَضِيَ ا هللَُّ عَنْهُ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «كُلُوا الهزيْتَ وَادههِنُوا بِهِ، فَإِنههُ مِنْ شَجَرَةٍ مُبَاركََةٍ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 114, 'وَلِلْبَـيْـهَقِيِّ وَابْنِ مَاجَهْ أَيْضًا: عَنِ ابْنِ عُمَرَ رَضِيَ ا هللَُّ عَنْهُ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «ائْـتَدِمُوا بِالهزيْتِ، وَادههِنُوا بِهِ، فَإِنههُ مِنْ شَجَرَةٍ مُبَاركََةٍ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 115, 'الهزيْتُ حَارٌّ رَطْبٌ فِي الُْأولَى، وَغَلِطَ مَنْ قَالَ: يَابِسٌ ، وَالهزيْتُ بَِحسَبِ زَيْـتُونِهِ، فَالْمُعْتَصَرُ مِنَ النهضِيجِ أَعْدَلُهُ وَأَجْ وَدُهُ، وَمِنَ الْفَجِّ فِيهِ بُـرُودَةٌ وَيُـبُوسَةٌ، وَمِنَ الهزيْـتُونِ الَْأحْرَِْ مُتَـوَسِّطٌ بَـيَْن الهزيْـتَـيِْن، وَمِنَ الَْأسْوَدِ يُسَخِّ نُ وَيُـرَطِّبُ بِاعْتِدَالٍ، وَيَـنْـفَعُ مِنَ السُّمُومِ، وَيُطْلِقُ الْبَطْنَ، وَيُْخرِجُ الدُّودَ، وَالْعَتِيقُ مِنْهُ أَشَدُّ تَسْخِينًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 116, 'وَتَلَِْيلًا، وَمَا اسْتُخْرِجَ مِنْهُ بِالْمَاءِ، فَـهُوَ أَقَلُّ حَرَارَةً، وَأَلْطَفُ وَأَبْـلَغُ فِي النهـفْعِ، وَجَِيَعُ أَصْنَافِهِ مُلَيِّنَةٌ للبشرة، وتبطىء الشيب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 117, 'وماء الزيتون المالح يمنع من تنقّط حَرْقِ النهارِ، وَيَشُدُّ اللِّثَةَ، وَوَرَقُهُ يَـنْـفَعُ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 118, '(7) النحل- .9', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 119, '(2) أخرجه مالك وأحدْ والنسائي وابن ماجه والترمذي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 120, 'الُْحمْرَةِ، وَالنهمْلَةِ، وَالْقُرُوحِ الْوَسِخَةِ، وَالشِّ رَى، وَيَْمنَعُ الْعَرَقَ ، ومنافعه أضعاف ما ذكرنا. زبد: رَوَى أبو داود فِي «سُنَنِهِ» ، عَنِ ابْـنَِْ بسر السُّلَمِيهـيِْن رَضِيَ ا هللَُّ عَنْـهُمَا قَالَا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 121, 'دَخَلَ عَلَيْـنَا رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَـقَدهمْنَا لَهُ زُبْدًا وَتَرًَْا، وَكَانَ يُِحبُّ الزُّبْدَ وَالتهمْرَ »7« . الزُّبْدُ حَارٌّ رَطْبٌ ، فِيهِ مَنَافِعُ كَثِيَرةٌ، منها الإنضاج والتحليل، ويبىَء الَْأوْرَامَ الهتِي تَكُونُ إِلَى جَانِبِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 122, 'الُْأذُنَـيِْن وَالَْحالِبَـيِْن، وَأَوْرَامَ الْفَمِ، وَسَائِرَ الَْأوْرَامِ الهتِي تَـعْرِضُ فِي أَبْدَانِ النِّسَاءِ وَالصِّ بْـيَانِ إِذَا اسْتُـعْمِلَ وَحْدَهُ، وَإِذَا لعق منه، نفع من نَـفْثِ الدهمِ الهذِي يَكُونُ مِنَ الرِّئَةِ، وَأَنْضَجَ الَْأوْرَامَ الْعَارِضَةَ فِيهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 123, 'وَهُوَ مُلَيٌِّن لِلطهبِيعَةِ وَالْعَصَبِ وَالَْأوْرَامِ الصُّلْبَةِ الْعَارِضَةِ مِنَ الْمِ هرةِ السهوْدَاءِ وَالْبَـلْغَمِ، نَافِعٌ مِنَ الْيُـبْسِ الْعَارِضِ فِي الْبَدَنِ، وَإِذَا طُلِيَ بِهِ عَلَى مَنَابِتِ أَسْنَانِ الطِّفْلِ، كَانَ مُعِينًا عَلَى نَـبَاتَِها وَطُلُوعِهَا، وَهُوَ نَافِعٌ مِنَ السُّعَالِ الْعَارِضِ مِنَ الْبَـرْدِ وَالْيُـبْسِ ، وَيُذْهِبُ الْقُوَبَاءَ وَالُْخشُونَةَ الهتِي فِي الْبَدَنِ، وَيُـلَيُِّن الطهبِيعَةَ، وَلَكِنههُ يُضْعِفُ شَهْوَةَ الطهعَامِ، وَيُذْهِبُ بِوَخَامَتِهِ الُْحلْوُ، كَالْعَسَلِ وَالتهمْرِ، وَفِي جَعَِْهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بَـيَْن التهمْرِ وَبَـيْـنَهُ مِنَ الِْحكْمَةِ إِصْلَاحُ كُلٍّ منهما بالآخر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 124, 'زبيب: رُوِيَ فِيهِ حَدِيثَانِ لَا يَصِحهانِ. أَحَدُهُاَُ: «نِعْمَ الطهعَامُ الهزبِيبُ يُطَيِّبُ النهكْهَةَ، وَيُذِيبُ الْبَـلْغَمَ» . وَالثهانِي: نِعْمَ الطهعَامُ الهزبِيبُ يُذْهِبُ النهصَبَ ، وَيَشُدُّ الْعَصَبَ ، ويطفىء الْغَضَبَ ، وَيُصَفِّي اللهوْنَ، وَيُطَيِّبُ النهكْهَةَ» . وَهَذَا أَيْضًا لَا يَصِحُّ فِيهِ شَيْ ءٌ عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 125, 'وبعد: فأجود الزبيب ما كبَ جسَه، وَسَِمنَ شَحْمُهُ وَلَْحمُهُ، وَرَقه قِشْرُهُ، وَنُزعَِ عَجَمُهُ، وَصَغُرَ حَبُّهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 126, 'وَجِرْمُ الهزبِيبِ حَارٌّ رَطْبٌ فِي الُْأولَى، وَحَبُّهُ بَارِدٌ يَابِسٌ ، وَهُوَ كَالْعِنَبِ الْمُتهخَذِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 127, '(7) أخرجه أبو داود وابن ماجه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 128, 'مِنْهُ: الُْحلْوُ مِنْهُ حَارٌّ، وَالَْحامِضُ قَابِضٌ بَارِدٌ، وَالَْأبْـيَضُ أَشَدُّ قَـبْضًا مِنْ غَيِْرهِ، وَإِذَا أُكِلَ لَْحمُهُ، وَافَقَ قَصَبَةَ الرِّئَةِ، وَنَـفَعَ مِنَ السُّعَالِ، وَوَجَعِ الْكُلَى، وَالْمَثَانَةِ، وَيُـقَوِّي الْمَعِدَةَ، وَيُـلَيُِّن الْبَطْنَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 129, 'وَالُْحلْوُ اللهحْمِ أَكْ ثَـرُ غِذَاءً مِنَ الْعِنَبِ، وَأَقَلُّ غِذَاءً مِنَ التِّيِن الْيَابِسِ ، وَلَهُ قُـهوةٌ مُنْضِجَةٌ هَاضِمَةٌ قَابِضَةٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 130, 'مُلَُِّلَةٌ بِاعْتِدَالٍ، وَهُوَ بِالُْجمْلَةِ يُـقَوِّي الْمَعِدَةَ وَالْكَبِدَ وَالطِّحَالَ، نَافِعٌ مِنْ وَجَعِ الَْحلْقِ وَالصهدْرِ وَالرِّئَةِ وَالْكُلَى وَالْمَثَانَةِ، وَأَعْدَلُهُ أَنْ يُـؤْكَلَ بِغَيِْر عَجَمِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 131, 'وَهُوَ يُـغَذِّي غِذَاءً صَالًِحا، وَلَا يُسَدِّدُ كَمَا يَـفْعَلُ التهمْرُ، وَإِذَا أُكِلَ مِنْهُ بِعَجَمِهِ كَانَ أَكْ ثَـرَ نَـفْعًا لِلْمَعِدَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 132, 'وَالْكَبِدِ وَالطِّحَالِ، وَإِذَا لُصِقَ لَْحمُهُ عَلَى الَْأظَافِيِر الْمُتَحَرّكَِةِ أَسْرَعَ قَـلْعَهَا، وَالُْحلْوُ مِنْهُ وَمَا لَا عَجَمَ لَهُ نَافِعٌ لَِأصْحَابِ الرُّطُوبَاتِ وَالْبَـلْغَمِ، وَهُوَ يَُخصِّبُ الْكَبِدَ، وَيَـنْـفَعُهَا خِاَِصِّ يهتِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 133, 'وَفِيهِ نَـفْعٌ لِلْحِفْظِ: قَالَ الزُّهْرِيُّ: مَنْ أَحَبه أَنْ يَْحفَظَ الَْحدِيثَ ، فَـلْيَأْكُلِ الهزبِيبَ . وَكَانَ المنصور يَذْكُرُ عَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 134, 'جَدِّهِ عَبْدِ ا هلِلَّ بْنِ عَبهاسٍ : عَجَمُهُ دَاءٌ، وَلَْحمُهُ دَوَاءٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 135, 'زَنْبَِْيلٌ: قَالَ تَـعَالَى: وَيُسْقَوْنَ فِيها كَأْساً كانَ مِزاجُها زَنْبَِْيلًا ]7[ وذكر أبو نعيم في كتاب «الطب النبوي» مِنْ حَدِيثِ أَبِي سَعِيدٍ الُْخدْرِيِّ رَضِيَ ا هللَُّ عَنْهُ قَالَ: أَهْدَى مَلِكُ الرُّومِ إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ جَ هرةَ زَنْبَِْيلٍ، فَأَطْعَمَ كُله إِنْسَانٍ قِطْعَةً، وَأَطْعَمَنِِ قِطْعَةً.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 136, 'الهزنْبَِْيلُ حَارٌّ فِي الهثانِيَةِ، رَطْبٌ فِي الُْأولَى، مُسْخِنٌ مُعِيٌن عَلَى هَضْمِ الطهعَامِ، مُلَيٌِّن لِلْبَطْنِ تَـلْيِينًا مُعْتَدِلًا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 137, 'نَافِعٌ مِنْ سُدَدِ الْكَبِدِ الْعَارِضَةِ عَنِ الْبَـرْدِ وَالرُّطُوبَةِ، وَمِنْ ظُلْمَةِ الْبَصَرِ الَْحادِثَةِ عَنِ الرُّطُوبَةِ أَكْلًا وَاكْتِحَالًا، مُعِيٌن عَلَى الِْجمَاعِ ، وَهُوَ مُلَُِّلٌ لِلرِّيَاحِ الْغَلِيظَةِ الَْحادِثَةِ فِي الَْأمْعَاءِ وَالْمَعِدَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 138, 'وبالجملة فهو صالح لحكبد وَالْمَعِدَةِ الْبَارِدَتَِي الْمِزَاجِ، وَإِذَا أُخِذَ مِنْهُ مَعَ السُّكهرِ وَزْنُ دِرْهَيَُِْن بِالْمَاءِ الَْحارِّ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 139, 'أَسْهَلَ فُضُولًا لزجة لعابية، ويقع الْمَعْجُونَاتِ الهتِي تُلََِّلُ الْبَـلْغَمَ وَتُذِيبُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 140, 'وَالْمِزِّيُّ مِنْهُ حَارٌّ يَابِسٌ يُـهَيِّجُ الِْجمَاعَ، وَيَزِيدُ فِي الْمَنِِِّ، وَيُسَخِّ نُ الْمَعِدَةَ وَالْكَبِدَ، وَيُعِيُن عَلَى الِاسْتِمْرَاءِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 141, 'وَيُـنَشِّ فُ الْبَـلْغَمَ الْغَالِبَ عَلَى الْبَدَنِ ، وَيَزِيدُ فِي الِْحفْظِ، وَيُـوَافِقُ بَـرْدَ الْكَبِدِ وَالْمَعِدَةِ، وَيُزِيلُ بِلهتَـهَا الَْحادِثَةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 142, 'عَنْ أَكْلِ الْفَاكِهَةِ، وَيُطَيِّبُ النهكْهَةَ، وَيُدْفَعُ بِهِ ضَرَرُ الَْأطْعِمَةِ الْغَلِيظَةِ الْبَارِدَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 143, 'حَرْفُ السِّ يِن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 144, 'سَنَا: قَدْ تَـقَدهمَ، وَتَـقَدهمَ سَنُّوتٌ أَيْضًا، وَفِيهِ سَبْـعَةُ أَقْـوَالٍ: أَحَدُهَا: أَنههُ الْعَسَلُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 145, 'الثهانِي: أنه رب عكة السمن يخرج خططا سوداء عَلَى السهمْنِ. الثهالِثُ : أَنههُ حَبُّ يُشْبِهُ الْكَمُّونَ، وَلَيْسَ بِكَمُّونٍ. الهرابِعُ: الْكَمُّونُ، الْكَرْمَانُِّي. الَْخامِسُ : أَنههُ الشِّ بَتُّ، السهادِسُ : أَنههُ التهمْرُ. السهابِعُ: أَنههُ الهرازَيَانْجُ. سفرجل: رَوَى ابْنُ مَاجَهْ فِي «سُنَنِهِ» : مِنْ حَدِيثِ إسماعيل بن محمد الطلحي، عَنْ نقيب بن حاجب، عَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 146, 'أبي سعيد، عَنْ عبد الملك الزبيري، عَنْ طَلْحَةَ بْنِ عُبَـيْدِ ا هلِلَّ رَضِيَ لله عَنْهُ قَالَ: دَخَلْتُ عَلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَبِيَدِهِ سَفَرْجَلَةٌ، فَـقَالَ: «دُونَكَهَا يَا طلحة، فَإِنهـهَا تُِمَُّ الْفُؤَادَ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 147, 'وَرَوَاهُ النهسَائِيُّ مِنْ طَرِيقٍ آخَرَ، وَقَالَ: «أَتَـيْتُ النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَهُوَ فِي جَاََعَةٍ مِنْ أَصْحَابِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 148, 'وَبِيَدِهِ سَفَرْجَلَةٌ يُـقَلِّبُـهَا، فَـلَمها جَلَسْتُ إِلَيْهِ، دَحَا بها إلِّ م قال: «دونكها أباذر، فَإِنهـهَا تَشُدُّ الْقَلْبَ ، وَتُطَيِّبُ النهـفْسَ ، وَتُذْهِبُ بِطَخَاءِ الصهدْرِ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 149, 'وَقَدْ رُوِيَ فِي السهفَرْجَلِ أَحَادِيثُ أُخَرُ، هَذَا أَمْثَـلُهَا، وَلَا تَصِحُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 150, 'وَالسهفَرْجَلُ بَارِدٌ يَابِسٌ ، وَيَْختَلِفُ  فِي ذَلِكَ  بِاخْتِلَافِ طَعْمِهِ، وَكُلُّهُ بَارِدٌ قَابِضٌ ، جَيِّدٌ لِلْمَعِدَ ةِ، وَالُْحلْوُ مِنْهُ أَقَلُّ بُـرُودَةً وَيُـبْسًا، وَأَمْيَلُ إِلَى الِاعْتِدَالِ، وَالَْحامِضُ أَشَدُّ قَـبْضًا وَيُـبْسًا وَبُـرُودَةً، وَكُلُّهُ يُسَكِّنُ الْعَطَشَ وَالْقَيْ ءَ، وَيُدِرُّ البول، ويعقل الطبع،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 151, '(7) أخرجه ابن ماجه في الأطعمة. قال أبو حاتم: حديث منكر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 152, 'وَيَـنْـفَعُ مِنْ قُـرْحَةِ الَْأمْعَاءِ، وَنَـفْثِ الدهمِ، وَالَْهيْضَةِ، وَيَـنْـفَعُ مِنَ الْغَثَـيَانِ، وَيَْمنَعُ مِنْ تَصَاعُدِ الَْأخِْرَِةِ إِذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 153, 'اسْتُـعْمِلَ بَـعْدَ الطهعَامِ، وَحُرَاقَةُ أَغْصَانِهِ وَوَرَقِهِ الْمَغْسُولَةُ كَالتُّوتِيَاءِ فِي فِعْلِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 154, 'وَهُوَ قَـبْلَ الطهعَامِ يَـقْبِضُ ، وَبَـعْدَهُ يُـلَيُِّن الطهبْعَ، وَيُسْرعُِ بِانِْدَْارِ الثُّـفْلِ، والإكثار منه مضر بالعصب، مولد للقولنج، ويطفىء الْمِ هرةَ الصهفْرَاءَ الْمُتَـوَلِّدَةَ فِي الْمَعِدَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 155, 'وَإِنْ شُوِيَ كَانَ أَقَله لُِخشُونَتِهِ، وَأَخَفه ، وَإِذَا قُـوِّرَ وَسَطُهُ، وَنُزعَِ حَبُّهُ، وَجُعِلَ فِيهِ الْعَسَلُ، وَطُيَِّن جِرْمُهُ بِالْعَجِيِن، وَأُودِعَ الهرمَادَ الَْحاره، نَـفَعَ نَـفْعًا حَسَنًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 156, 'وَأَجْ وَدُ مَا أُكِلَ مَشْوِيًّا أَوْ مَطْبُوخًا بِالْعَسَلِ، وَحَبُّهُ يَـنْـفَعُ مِنْ خُشُونَةِ الَْحلْقِ، وَقَصَبَةِ الرِّئَةِ، وَكَثِيٍر مِنَ الَْأمْرَاضِ ، وَدُهْنُهُ يَْمنَعُ الْعَرَقَ ، وَيُـقَوِّي الْمَعِدَةَ، وَالْمُرَهبَ مِنْهُ يُـقَوِّي الْمَعِدَةَ وَالْكَبِدَ، وَيَشُدُّ الْقَلْبَ ، وَيُطَيِّبُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 157, 'ِ         ِ                         ِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 158, 'ِ       ِ        ِ     ِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 159, 'النهـفَسَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 160, 'وَمَعْنَى تُِمَُّ الْفُؤَادَ: تُرِيُحهُ. وَقيلَ: تُـفَتّحُهُ وَتُـوَسّعُهُ، منْ جُاََمِ الْمَاء، وَهُوَ اتّسَاعُهُ وَكَثْـرَتُهُ، وَالطهخَاءُ للْقَلْبِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 161, 'مِثْلُ الْغَيْمِ عَلَى السهمَاءِ. قَالَ أبو عبيد: الطهخَاءُ ثِقَلٌ وَغَشْيٌ، تَـقُولُ: مَا فِي السهمَاءِ طَخَاءٌ، أَيْ : سَحَابٌ وظلمة..', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 162, 'سواك: فِي «الصهحِيحَيِْن» عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «لَوْلَا أَنْ أَشُقه عَلَى أُمهتِي لََأمَرْتُـهُمْ بِالسِّ وَاكِ عِنْدَ كُلِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 163, 'صَلَاةٍ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 164, 'وَفِيهِمَا: أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ إِذَا قَامَ مِنَ اللهيْلِ يَشُوصُ فَاهُ بِالسِّ وَاكِ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 165, 'وَفِي «صَحِيحِ الْبُخَارِيِّ » تَـعْلِيقًا عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «السِّ وَاكُ مَطْهَرَةٌ للفم مرضاة للرب» . »3«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 166, '(7) أخرجه البخاري في الجمعة، ومسلم في الطهارة. (2) أخرجه البخاري ومسلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 167, '(3) أخرجه البخاري تعليقا في الصوم وأحدْ والنسائي والدارمي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 168, '»2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 169, 'وَفِي «صَحِيحِ مسلم» : أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ إِذَا دَخَلَ بَـيْـتَهُ، بَدَأَ بِالسِّ وَاكِ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 170, 'وَالَْأحَادِيثُ فِيهِ كَثِيَرةٌ، وَصَحه عَنْهُ مِنْ حَدِيثٍ أَنههُ اسْتَاكَ عِنْدَ مَوْتِهِ بِسِوَاكِ عَبْدِ الهرحْنَِْ بْنِ أَبِي بَكْرٍ ، وَصَحه عَنْهُ أَنههُ قَالَ: «أكثر تعليكم فِي السِّ وَاكِ» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 171, 'وَأَصْلَحُ مَا اتُِّخذَ السِّ وَاكُ مِنْ خَشَبِ الَْأرَاكِ وَنَوِْْهِ، وَلَا يَـنْـبَغِي أَنْ يُـؤْخَذَ مِنْ شَجَرَةٍ مَهَُْولَةٍ، فَـرُهبَما كَانَتْ سًُّما، وَيَـنْـبَغِي الْقَصْدُ فِي اسْتِعْمَالِهِ، فَإِنْ بَالَغَ فِيهِ، فَـرُهبَما أَذْهَبَ طَلَاوَةَ الَْأسْنَانِ وَصِ قَالَتَـهَا، وَهَيهأَهَا لِقَبُولِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 172, 'الَْأخِْرَِةِ الْمُتَصَاعِدَةِ مِنَ الْمَعِدَةِ وَالَْأوْسَاخِ، وَمَتَى اسْتُـعْمِلَ بِاعْتِدَالٍ، جَلَا الَْأسْنَانَ، وَقَـهوى الْعَمُودَ، وَأَطْلَقَ اللِّسَانَ، وَمَنَعَ الَْحفَرَ، وَطَيهبَ النهكْهَةَ، وَنَـقهى الدِّمَاغَ، وَشَ ههى الطهعَامَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 173, 'وَأَجْ وَدُ مَا اسْتُـعْمِلَ مَبْـلُولًا بَِماءِ الْوَرْدِ، وَمِنْ أَنْـفَعِهِ أُصُولُ الَْجوْزِ. قَالَ صَاحِبُ «التهـيْسِيِر» : زَعَمُوا أَنههُ إِذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 174, 'اسْتَاكَ بِهِ الْمُسْتَاكُ كُله خَامِسٍ مِنَ الَْأهيامِ، نَـقهى الهرأْسَ ، وَصَ هفى الَْحوَاسه ، وَأَحَده الذِّهْنَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 175, 'وَفِي السِّ وَاكِ عِدهةُ مَنَافِعَ: يُطَيِّبُ الْفَمَ، وَيَشُدُّ اللِّثَةَ، وَيَـقْطَعُ الْبَـلْغَمَ، وَيَْجلُو الْبَصَرَ، وَيَذْهَبُ بِالَْحفَرِ، وَيُصِحُّ الْمَعِدَةَ، وَيُصَفِّي الصهوْتَ ، وَيُعِيُن عَلَى هَضْمِ الطهعَامِ، وَيُسَهِّلُ مَاََرِيَ الْكَلَامِ، وَيُـنَشِّ طُ لِلْقِرَاءَةِ، وَالذِّكْرِ وَالصهلَاةِ، وَيَطْرُدُ النهـوْمَ، وَيُـرْضِ ي الهربه ، وَيُـعْجِبُ الْمَلَائِكَةَ، وَيُكْثِرُ الَْحسَنَاتِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 176, 'وَيُسْتَحَبُّ كُله وَقْتٍ، وَيَـتَأَكهدُ عِنْدَ الصهلَاةِ وَالْوُضُوءِ، وَالِانْتِبَاهِ مِنَ النهـوْمِ، وَتَـغْيِيِر رَائِحَةِ الْفَمِ، وَيُسْتَحَبُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 177, 'لِلْمُفْطِرِ وَالصهائِمِ فِي كُلِّ وَقْتٍ لِعُمُومِ الَْأحَادِيثِ فِيهِ، وَلَِحاجَةِ الصهائِمِ إِلَيْهِ، وَلَِأنههُ مَرْضَاةٌ لِلهربِّ ، وَمَرْضَاتُهُ مَطْلُوبَةٌ فِي الصهوْمِ أَشَدُّ مِنْ طَلَبِهَا فِي الْفِطْرِ، وَلَِأنههُ مَطْهَرَةٌ للفم، والطهور للصائم من أفضل أعماله.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 178, '(7) أخرجه مسلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 179, '(2) أخرجه البخاري.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 180, '(3) أخرجه البخاري في الجمعة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 181, 'وَفِي «السُّنَنِ» : عَنْ عَامِرِ بْنِ رَبِيعَةَ رَضِيَ ا هللَُّ عَنْهُ، قَالَ: رَأَيْتُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مَا لَا أُحْصِي يَسْتَاكُ، وَهُوَ صَائِمٌ »7« وَقَالَ الْبُخَارِيُّ: قَالَ ابْنُ عُمَرَ: يَسْتَاكُ أَهولَ النهـهَارِ وَآخِرَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 182, 'وَأَجْعَََ النهاسُ عَلَى أن الصائم يتمضمض وجوبا واستحبابا، والمضمضمة أَبْـلَغُ مِنَ السِّ وَاكِ، وَلَيْسَ هِلِلَّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 183, 'غَرَضٌ فِي التهـقَرُّبِ إِلَيْهِ بِالهرائِحَةِ الْكَرِيهَةِ، وَلَا هِيَ مِنْ جِنْسِ مَا شُرعَِ التهـعَبُّدُ بِهِ، وَإِهنَما ذكُِرَ طِيبُ الُْخلُوفِ عِنْدَ ا هلِلَّ يَـوْمَ الْقِيَامَةِ حَثًّا منه على الصوم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 184, 'لاحثا عَلَى إِبْـقَاءِ الهرائِحَةِ، بَلِ الصهائِمُ أَحْوَجُ إِلَى السِّ وَاكِ مِنَ الْمُفْطِرِ. وَأَيْضًا فَإِنه رِضْوَانَ ا هلِلَّ أَكْبَـرُ مَنِ اسْتِطَابَتِهِ لُِخلُوفِ فَمِ الصهائِمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 185, 'وَأَيْضًا فَإِنه مَبَُهـتَهُ لِلسِّ وَاكِ أَعْظَمُ مِنْ مَبَُهتِهِ لِبَـقَاءِ خُلُوفِ فَمِ الصهائِمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 186, 'وَأَيْضًا فَإِنه السِّ وَاكَ لَا يَْمنَعُ طِيبَ الُْخلُوفِ الهذِي يُزِيلُهُ السِّ وَاكُ عِنْدَ ا هلِلَّ يَـوْمَ الْقِيَامَةِ، بَلْ تََِْي الصهائِمُ يَـوْمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 187, 'الْقِيَامَةِ، وَخُلُوفُ فَمِهِ أَطْيَبُ مِنَ الْمِسْكِ عَلَامَةً عَلَى صِ يَامِهِ، وَلَوْ أَزَالَهُ بِالسِّ وَاكِ، كَمَا أَنه الَْجرِيحَ تََِْي يَـوْمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 188, 'الْقِيَامَةِ، وَلَوْنُ دَمِ جُرْحِهِ لَوْنُ الدهمِ، وَرِيُحهُ رِيحُ الْمِسْكِ ، وَهُوَ مَأْمُورٌ بِِإزَالَتِهِ فِي الدُّنْـيَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 189, 'وَأَيْضًا فَإِنه الُْخلُوفَ لَا يَـزُولُ بِالسِّ وَاكِ، فَإِنه سَبَـبَهُ قَائِمٌ، وَهُوَ خُلُوُّ الْمَعِدَةِ عَنِ الطهعَامِ، وَإِهنَما يَـزُولُ أَثَـرُهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 190, 'وَهُوَ الْمُنْـعَقِدُ عَلَى الَْأسْنَانِ وَاللِّثَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 191, 'وَأَيْضًا فَإِنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَلهمَ أُمهتَهُ مَا يُسْتَحَبُّ لَهمُْ فِي الصِّيَامِ، وَمَا يُكْ رَهُ لَهمُْ، وَلََْ يَْجعَلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 192, 'السِّ وَاكَ مِنَ الْقِسْمِ الْمَكْرُوهِ، وَهُوَ يَـعْلَمُ أَنهـهُمْ يَـفْعَلُونَهُ، وَقَدْ حَضههُمْ عَلَيْهِ بَِأبْـلَغِ أَلْفَاظِ الْعُمُومِ وَالشُّمُولِ، وَهُمْ يُشَاهِدُونَهُ يَسْتَاكُ وَهُوَ صَائِمٌ مِرَارًا كَثِيَرةً تَـفُوتُ الِْإحْصَاءَ، وَيَـعْلَمُ أَنهـهُمْ يَـقْتَدُونَ بِهِ، وَلََْ يَـقُلْ لَهمُْ يَـوْمًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 193, 'مِنَ الدههْرِ: لَا تَسْتَاكُوا بَـعْدَ الهزوَالِ، وَتَخَِْيُر الْبَـيَانِ عَنْ وَقْتِ الَْحاجَةِ مُْمتَنِعٌ، وَا هللَُّ أَعْلَمُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 194, 'سَْمنٌ: روى محمد جَرِيرٍ الطهبَِيَُّ بِِإسْنَادِهِ، مِنْ حَدِيثِ صهيب يَـرْفَـعُهُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 195, '(7) أخرجه أبو داود في الصوم، وأحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 196, '«عليكم بألبان البقر، فإنّه شِفَاءٌ، وَسَْمنُـهَا دَوَاءٌ، وَلُُحومُهَا دَاءٌ» رَوَاهُ عَنْ أَحْدََْ بْنِ الَْحسَنِ التِّْرمِذِيِّ ، حَدهثَـنَا محمد بن موسى النسائي، حَدهثَـنَا دفاع بن دغفل السدوسي، عَنْ عبد الحميد بن صيفي بن صهيب، عَنْ أَبِيهِ عَنْ جَدِّهِ، وَلَا يَـثْـبُتُ مَا فِي هَذَا الِْإسْنَادِ »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 197, 'وَالسهمْنُ حَارٌّ رَطْبٌ فِي الُْأولَى، وَفِيهِ جَلَاءٌ يَسِيٌر، وَلَطَافَةٌ وَتَـفْشِيَةُ الَْأوْرَامِ الَْحادِثَةِ مِنَ الَْأبْدَانِ النهاعِمَةِ، وَهُوَ أَقْـوَى مِنَ الزبد في الإنضلاج وَالتهـلْيِيِن، وَذكََرَ جَالِينُوسُ : أَنههُ أَبْـرَأَ بِهِ الَْأوْرَامَ الَْحادِثَةَ فِي الُْأذُنِ، وَفِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 198, 'الَْأرْنَـبَةِ، وَإِذَا دُلِّكَ بِهِ مَوْضِعُ الَْأسْنَانِ، نَـبَـتَتْ سَرِيعًا، وَإِذَا خُلِطَ مَعَ عَسَلٍ وَلَوْزٍ مُرٍّ، جَلَا مَا فِي الصدور وَالرِّئَةِ، وَالْكَيْمُوسَاتِ الْغَلِيظَةَ اللهزِجَةَ، إِهلا أَنههُ ضَارٌّ بِالْمَعِدَةِ، سِيهمَا إِذَا كَانَ مِزَاجُ صَاحِبِهَا بَـلْغَمِيًّا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 199, 'وَأَمها سَْمنُ الْبَـقَرِ وَالْمَعِزِ، فَإِنههُ إِذَا شُرِبَ مَعَ الْعَسَلِ نَـفَعَ مِنْ شُرْبِ السُّمِّ الْقَاتِلِ، وَمِنْ لَدْغِ الَْحيهاتِ وَالْعَقَارِبِ، وَفِي كِتَابِ ابْنِ السُّنِِِّّ: عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ ا هللَُّ عَنْهُ قَالَ: لََْ يَسْتَشْفِ النهاسُ بِشَيْ ءٍ أفضل من السمن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 200, 'سمك: رَوَى الِْإمَامُ أَحْدَُْ بْنُ حَنْـبَلٍ، وَابْنُ مَاجَهْ في «سننه» : من حديث عبد الله بن عُمَرَ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «أُحِلهتْ لَنَا مَيْـتَـتَانِ وَدَمَانِ: السهمَكُ وَالَْجرَادُ، وَالْكَبِدُ وَالطِّحَالُ» »2« . أَصْنَافُ السهمَكِ كَثِيَرةٌ، وَأَجْ وَدُهُ مَا لَذه طَعْمُهُ، وَطَابَ رِيُحهُ، وَتَـوَسهطَ مِقْدَارُهُ، وَكَانَ رَقِيقَ الْقِشْرِ، وَلََْ يَكُنْ صُلْبَ اللهحْمِ وَلَا يَابِسَهُ، وَكَانَ فِي مَاءٍ عَذْبٍ جَارٍ عَلَى الَْحصْبَاءِ، وَيَـغْتَذِي بِالنهـبَاتِ لَا الَْأقْذَارِ، وَأَصْلَحُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 201, 'أَمَاكِنِهِ مَا كَانَ فِي نَـهْرٍ جَيِّدِ الْمَاءِ، وَكَانَ وََِْي إِلَى الَْأمَاكِنِ الصهخْرِيهةِ، ُ مه الهرمْلِيهةِ، وَالْمِيَاهِ الَْجارِيَةِ الْعَذْبَةِ الهتِي لَا قَذَرَ فِيهَا، وَلَا حَأَْْةَ، الْكَثِيَرةِ الِاضْطِرَابِ وَالتهمَوُّجِ، الْمَكْشُوفَةِ لِلشهمْسِ والرياح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 202, '(7) وأخرجه الحاكم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 203, '(2) أخرجه أحدْ وابن ماجه والدارقطنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 204, 'وَالسهمَكُ الْبَحْرِيُّ فَاضِلٌ، مَمُُْودٌ، لَطِيفٌ ، وَالطهرِيُّ مِنْهُ بَارِدٌ رَطْبٌ ، عَسِرُ الِانِْهضَامِ، يُـوَلِّدُ بَـلْغَمًا كَثِيًرا، إِهلا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 205, 'الْبَحْرِيه وَمَا جَرَى مَرََْاهُ، فَإِنههُ يُـوَلِّدُ خَلْطًا مَمُُْودًا، وَهُوَ يَُخصِّبُ الْبَدَنَ، وَيَزِيدُ فِي الْمَنِِِّ، وَيُصْلِحُ الَْأمْزِجَةَ الَْحارهةَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 206, 'وَأَمها الْمَالِحُ، فَأَجْ وَدُهُ مَا كَانَ قَرِيبَ الْعَهْدِ بِالتهمَلُّحِ، وَهُوَ حَارٌّ يَابِسٌ ، وَكُلهمَا تَـقَادَمَ عَهْدُهُ ازْدَادَ حَرُّهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 207, 'وَيُـبْسُهُ، وَالسِّ لهوْرُ مِنْهُ كَثِيُر اللُّزُوجَةِ، وَيُسَمهى الِْجرِّيه، وَالْيَـهُودُ لَا تَكَُْلُهُ. وَإِذَا أُكِلَ طَرِيًّا، كَانَ مُلَيِّنًا لِلْبَطْنِ، وَإِذَا مُلِّحَ وَعُتِّقَ وَأُكِلَ، صَهفى قَصَبَةَ الرِّئَةِ، وَجَ هودَ الصهوْتَ ، وَإِذَا دُقه وَوُضِعَ مِنْ خَارِجٍ، أَخْ رَجَ السهلَى وَالْفُضُولَ مِنْ عُمْقِ الْبَدَنِ مِنْ طَرِيقِ أَنه لَهُ قُـهوةً جَاذِبَةً.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 208, 'وَمَاءُ مِلْحِ الِْجرِّيِّ الْمَالِحِ إِذَا جَلَسَ فِيهِ مَنْ كَانَتْ بِهِ قُـرْحَةُ الَْأمْعَاءِ فِي ابْتِدَاءِ الْعِلهةِ، وَافَـقَهُ بِذَِْبِهِ الْمَوَاده', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 209, 'إِلَى ظَاهِرِ الْبَدَنِ ، وَإِذَا احْتُقِنَ بِهِ، أَبْـرَأَ مِنْ عِرْقِ النهسَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 210, 'وَأَجْ وَدُ مَا فِي السهمَكِ مَا قَـرُبَ مِنْ مُؤَخِّرِهَا، وَالطهرِيُّ السهمِيُن مِنْهُ يَُخصِّبُ الْبَدَنَ لَْحمُهُ وَوَدَكُهُ. وَفِي «الصهحِيحَيِْن» : مِنْ حَدِيثِ جَابِرِ بْنِ عَبْدِ ا هلِلَّ رَضِيَ ا هللَُّ عَنْهُ قَالَ: بَـعَثَـنَا النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي ثَلَاثِاَِئَةِ رَاكِبٍ، وَأَمِيُرنَا أَبُو عُبَـيْدَةَ بْنُ الَْجهراحِ، فَأَتَـيْـنَا السهاحِلَ، فَأَصَابَـنَا جُوعٌ شَدِيدٌ، حَ هتى أَكَلْنَا الَْخبَطَ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 211, 'فَأَلْقَى لَنَا الْبَحْرُ حُوتًا يُـقَالُ لََها: عَنْـبَـرُ، فَأَكَلْنَا مِنْهُ نِصْفَ شَهْرٍ، وَائْـتَدَمْنَا بِوَدكَِهِ حَ هتى ثَبََتْ أَجْسَامُنَا، فَأَخَذَ أبو عبيدة ضِلْعًا مِنْ أَضْلَاعِهِ، وَحَلََْ رَجُلًا عَلَى بَعِيِرهِ، وَنَصَبَهُ، فَمَ هر تَتََْهُ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 212, 'سلق: رَوَى الترمذي وأبو داود، عَنْ أم المنذر، قَالَتْ : دَخَلَ عَلَيه رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَمَعَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 213, 'علي رَضِيَ ا هللَُّ عَنْهُ، وَلَنَا دَوَالٍ مُعَلهقَةٌ، قَالَتْ : فَجَعَلَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كََُْلُ وعلي مَعَهُ كََُْلُ، فَـقَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «مَهْ يَا علي فَإِنهكَ نَاقِهٌ» ، قَالَتْ :', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 214, 'فَجَعَلْتُ لَهمُْ سِلْقًا وَشَعِيًرا، فَـقَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «يَا علي فَأَصِبْ مِنْ هَذَا، فَإِنههُ أَوْفَقُ لَكَ »', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 215, '. قَالَ الترمذي: حَدِيثٌ حسن غريب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 216, '(7) أخرجه البخاري ومسلم في الصيد والذبائح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 217, 'السِّ لْقُ حَارٌّ يَابِسٌ فِي الُْأولَى، وَقِيلَ: رَطْبٌ فِيهَا، وَقِيلَ: مُرَكهبٌ مِنْـهُمَا، وَفِيهِ بُـرُودَةٌ مُلَطِّفَةٌ، وَتَلَِْيلٌ. وَتَـفْتِيحٌ، وَفِي الَْأسْوَدِ مِنْهُ قَـبْضٌ وَنَـفْعٌ مِنْ دَاءِ الثهـعْلَبِ، وَالْكَلَفِ ، وَالَْحهزازِ، وَالثهآلِيلِ إِذَا طُلِيَ بَِمائِهِ، وَيَـقْتُلُ الْقُمهلَ، وَيُطْلَى بِهِ الْقُوَبَاءُ مَعَ الْعَسَلِ، وَيُـفَتِّحُ سُدَدَ الْكَبِدِ وَالطِّحَالِ، وَأَسْوَدُهُ يَـعْقِلُ الْبَطْنَ، وَلَا سِيهمَا مَعَ الْعَدَسِ ، وَهُاَُ رَدِيئَانِ، وَالَْأبْـيَضُ : يُـلَيُِّن مَعَ الْعَدَسِ ، وَيُْحقَنُ بَِمائِهِ للسْهال، وينفع من القولنج مَعَ الْمَرِيِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 218, 'وَالتهـوَابِلِ، وَهُوَ قَلِيلُ الْغِذَاءِ، رَدِيءُ الْكَيْمُوسِ ، يَْحرِقُ الدهمَ، وَيُصْلِحُهُ الَْخلُّ وَالَْخرْدَلُ، وَالِْإكْ ثَارُ مِنْهُ يُـوَلِّدُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 219, 'الْقَبْضَ وَالنهـفْخَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 220, 'حَرْفُ الشِّ يِن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 221, 'شُونِيزٌ: هُوَ الَْحبهةُ السهوْدَاءُ، وَقَدْ تَـقَدهمَ فِي حَرْفِ الحاء.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 222, 'شبمَ: رَوَى الترمذي، وَابْنُ مَاجَهْ فِي «سُنَنِهِمَا» : مِنْ حَدِيثِ أسماء بنت عميس، قَالَتْ : قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «بَِماذَا كُنْتِ تَسْتَمْشِيَن؟» قَالَتْ :', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 223, 'بِالشُّبْـرُمِ. قَالَ: «حَارٌّ جَارٌّ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 224, 'الشُّبْـرُمُ شَجَرٌ صَغِيٌر وَكَبِيٌر، كَقَامَةِ الهرجُلِ وَأَرْجَحُ، لَهُ قضبان حرْ ملمعة ببياض، وفي رؤوس قُضْبَانِهِ جُهَةٌ مِنْ وَرَقٍ، وَلَهُ نَـوْرٌ صِغَارٌ أَصْفَرُ إِلَى الْبَـيَاضِ ، يَسْقُطُ وَيَْخلُفُهُ مَرَاوِدُ صِغَارٌ فِيهَا حَبٌّ صَغِيٌر مِثْلُ الْبُطْمِ، فِي قَدْرِهِ، أَحْرَُْ اللهوْنِ، وَلَهاَ عُرُوقٌ عَلَيْـهَا قُشُورٌ حُرٌْْ، وَالْمُسْتَـعْمَلُ مِنْهُ قِشْرُ عُرُوقِهِ، وَلَبَُن قُضْبَانِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 225, 'وَهُوَ حَارٌّ يَابِسٌ فِي الدهرَجَةِ الهرابِعَةِ، وَيُسَهِّلُ السهوْدَاءَ، وَالْكَيْمُوسَاتِ الْغَلِيظَةَ، وَالْمَاءَ الَْأصْفَرَ، وَالْبَـلْغَمَ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 226, 'مُكْرِبٌ ، مُغَثٍّ ، وَالِْإكْ ثَارُ مِنْهُ يَـقْتُلُ، وَيَـنْـبَغِي إِذَا اسْتُـعْمِلَ أَنْ يُـنْـقَعَ فِي اللهبَِن الَْحلِيبِ يَـوْمًا وَلَيْـلَةً، وَيُـغَيهـرَ عليه اللهبَُن فِي الْيَـوْمِ مَ هرتَـيِْن أَوْ ثَلَاثًَ، وَيُْخرَجَ، وَيَُجهففَ فِي الظِّلِّ، وَيُْخلَطَ مَعَهُ الْوُرُودُ وَالْكَثِيَراءُ، وَيُشْرَبَ بَِماءِ الْعَسَلِ، أَوْ عَصِيِر الْعِنَبِ، وَالشهرْبَةُ مِنْهُ مَا بَـيَْن أَرْبَعِ دَوَانِقَ إِلَى دَانِقَيِْن على حسب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 227, '(7) أخرجه الترمذي في الطب، وابن ماجة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 228, 'الْقُهوةِ، قَالَ حنين: أَمها لَبَُن الشُّبْـرُمِ، فَلَا خَيْـرَ فِيهِ، وَلَا أَرَى شُرْبَهُ الْبَـتهةَ، فَـقَدْ قَـتَلَ بِهِ أَطِبهاءُ الطُّرُقَاتِ كَثِيًرا مِنَ النهاسِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 229, 'شعير: رَوَى ابْنُ مَاجَهْ: مِنْ حَدِيثِ عائشة، قَالَتْ : كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إِذَا أَخَذَ أَحَدًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 230, 'مِنْ أَهْلِهِ الْوَعْكُ ، أَمَرَ بِالِْحسَاءِ مِنَ الشهعِيِر، فَصُنِعَ، ُ مه أَمَرَهُمْ فَحَسَوْا مِنْهُ، ُ مه يَـقُولُ: «إِنههُ لَيَـرْتُو فُـؤَادَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 231, 'الَْحزِينِ ويسرو فؤاد السّقيم كما تسرو إِحْدَاكُنه الْوَسَخَ بِالْمَاءِ عَنْ وَجْ هِهَا» »7« . وَمَعْنَى يَـرْتُوهُ: يَشُدُّهُ وَيُـقَوِّيهِ وَيَسْرُو: يَكْشِفُ ، وَيُزِيلُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 232, 'وَقَدْ تَـقَدهمَ أَنه هَذَا هُوَ مَاءُ الشهعِيِر الْمَغْلِيِّ، وَهُوَ أَكْ ثَـرُ غِذَاءً مِنْ سَوِيقِهِ، وَهُوَ نَافِعٌ لِلسُّعَالِ، وَخُشُونَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 233, 'الَْحلْقِ، صَالِحٌ لِقَمْعِ حِدهةِ الْفُضُولِ، مُدِرٌّ لِلْبَـوْلِ، جَلَاءٌ لِمَا فِي الْمَعِدَةِ، قَاطِعٌ لِلْعَطَشِ ، مطفىء لِلْحَرَارَةِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 234, 'وَفِيهِ قُـهوةٌ يَْجلُو بَِها وَيُـلَطِّفُ وَيَُحلِّلُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 235, 'وَصِ فَتُهُ: أَنْ يُـؤْخَذَ مِنَ الشهعِيِر الَْجيِّدِ الْمَرْضُوضِ مِقْدَارٌ، وَمِنَ الْمَاءِ الصهافِي الْعَذْبِ خَْمسَةُ أَمْثَالِهِ، وَيُـلْقَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 236, 'فِي قِدْرٍ نَظِيفٍ، وَيُطْبَخَ بِنَارٍ مُعْتَدِلَةٍ إِلَى أَنْ يَـبْـقَى مِنْهُ خُُمسَاهُ، وَيُصَ هفى، وَيُسْتَـعْمَلَ منه مقدار الحاجة ملُّا. شواء: قَالَ ا هللَُّ تَـعَالَى فِي ضِ يَافَةِ خَلِيلِهِ إِبْـرَاهِيمَ عَلَيْهِ السهلَامُ لَِأضْيَافِهِ: فَما لَبِثَ أَنْ جاءَ بِعِجْلٍ حَنِيذٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 237, '»2« وَالَْحنِيذُ: الْمَشْوِيُّ عَلَى الهرضْفِ، وَهِيَ الِْحجَارَةُ الْمُحْمَاةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 238, 'وَفِي الترمذي: عَنْ أم سلمة رَضِيَ ا هللَُّ عَنْـهَا، أَنهـهَا قَـهربَتْ إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ جَنْـبًا مَشْوِيًّا، فَأَكَلَ مِنْهُ ُ مه قَامَ إِلَى الصهلَاةِ وَلََْ يَـتَـوَضهأْ. قَالَ الترمذي: حديث صحيح »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 239, '(7) أخرجه ابن ماجة والترمذي في الطب، وأحدْ. (2) سورة هود: .19', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 240, '(3) أخرجه الترمذي في الأطعمة، وأحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 241, 'وَفِيهِ أَيْضًا: عَنْ عبد الله بن الحارث قَالَ: أَكَلْنَا مَعَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ شِوَاءً فِي الْمَسْجِدِ »7« . وَفِيهِ أَيْضًا: عَنِ الْمُغِيَرةِ بْنِ شُعْبَةَ قَالَ: ضِفْتُ مَعَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ ذات لَيْـلَةٍ، فَأَمَرَ بِنَِْبٍ، فَشُوِيَ، ُ مه أَخَذَ الشهفْرَةَ، فَجَعَلَ يَُحزُّ لِِ بَِها مِنْهُ، قَالَ: فَجَاءَ بلال يُـؤَذِّنُ لِلصهلَاةِ، فَأَلْقَى الشهفْرَةَ فَـقَالَ: «مَا لَهُ تَرِبَتْ يَدَاهُ» » .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 242, 'أَنْـفَعُ الشِّ وَاءِ شِوَاءُ الضهأْنِ الَْحوْلِِِّ، ُ مه الْعِجْلِ اللهطِيفِ السهمِيِن، وَهُوَ حَارٌّ رَطْبٌ إِلَى الْيُـبُوسَةِ، كَثِيُر التهـوْلِيدِ لِلسهوْدَاءِ، وَهُوَ مِنْ أَغْذِيَةِ الَْأقْوِيَاءِ وَالَْأصِحهاءِ وَالْمُرْتَاضِيَن، وَالْمَطْبُوخُ أَنْـفَعُ وَأَخَفُّ عَلَى الْمَعِدَةِ، وَأَرْطَبُ مِنْهُ، وَمِنَ الْمُطَجهنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 243, 'وَأَرْدَؤُهُ الْمَشْوِيُّ فِي الشهمْسِ ، وَالْمَشْوِيُّ عَلَى الَْجمْرِ خَيْـرٌ مِنَ الْمَشْوِيِّ بِاللههَبِ، وَهُوَ الَْحنِيذُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 244, 'شَحْمٌ: ثَـبَتَ فِي «الْمُسْنَدِ» : عَنْ أنس، أَنه يَـهُودِيًّا أَضَافَ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَـقَدهمَ لَهُ خُبْـزَ شَعِيٍر وَإِهَالَةً سَنِخَةً »3« ، وَالِْإهَالَةُ: الشهحْمُ الْمُذَابُ ، وَالَْألْيَةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 245, 'وَالسهنِخَةُ: الْمُتَـغَيَِّرةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 246, 'وَثَـبَتَ فِي «الصهحِيحِ» : عَنْ عَبْدِ ا هلِلَّ بْنِ مُغَهفلٍ، قَالَ: قَالَ: دُلَِِّ جِرَابٌ مِنْ شَحْمٍ يَـوْمَ خَيْـبَـرَ، فَالْتَـزَمْتُهُ وَقُـلْتُ : وَا هلِلَّ لَا أُعْطِي أَحَدًا مِنْهُ شَيْـئًا، فَالْتَـفَتُّ، فَإِذَا رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَضْحَكُ ، وَلََْ يَـقُلْ شَيْـئًا »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 247, 'أَجْ وَدُ الشهحْمِ مَا كَانَ مِنْ حَيَـوَانٍ مُكْتَمِلٍ، وَهُوَ حَارٌّ رَطْبٌ ، وَهُوَ أَقَلُّ رُطُوبَةً مِنَ السهمْنِ، وَلَِهذَا لَوْ أُذِيبَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 248, 'الشهحْمُ وَالسهمْنُ كَانَ الشهحْمُ أَسْرَعَ جُوَُدًا، وَهُوَ يَـنْـفَعُ مِنْ خُشُونَةِ الَْحلْقِ، ويرخي ويعفن، ويدفع ضرره بالليمون المملوح،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 249, '(7) أخرجه أحدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 250, '(2) أخرجه أحدْ وأبو داود.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 251, '(3) أخرجه أحدْ، وأخرجه البخاري والترمذي. (4) أخرجه البخاري ومسلم في الجهاد.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 252, 'وَالهزنْبَِْيلِ، وَشَحْمُ الْمَعِزِ أَقْـبَضُ الشُّحُومِ، وَشَحْمُ التُّـيُوسِ أَشَدُّ تَلَِْيلًا، وَيَـنْـفَعُ مِنْ قُـرُوحِ الَْأمْعَاءِ، وَشَحْمُ الْعَنْزِ أَقْـوَى فِي ذَلِكَ ، وَيُْحتَـقَنُ بِهِ لِلسهحَجِ والزّحير.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 253, 'حَرْفُ الصهادِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 254, 'صَلَاةٌ: قَالَ ا هللَُّ تَـعَالَى: وَاسْتَعِينُوا بِالصهبَِْ وَالصهلاةِ وَإِهنها لَكَبِيَرةٌ إِهلا عَلَى الْخاشِعِيَن »7« ، وقال: يا أَيُّـهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 255, 'اهلذِينَ آمَنُوا اسْتَعِينُوا بِالصهبَِْ وَالصهلاةِ إِنه ا هللََّ مَعَ الصهابِرِينَ »2« . وَقَالَ تَـعَالَى: وَأْمُرْ أَهْلَكَ بِالصهلاةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 256, 'وَاصْطَبَِْ عَلَيْها لا نَسْئَـلُكَ رِزْقاً نَنُْْ نَـرْزُقُكَ وَالْعاقِبَةُ لِلتهـقْوى »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 257, 'وَفِي «السُّنَنِ» : كَانَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، إِذَا حَزَبَهُ أَمْرٌ، فَزعَِ إِلَى الصهلَاةِ »4« . وَقَدْ تَـقَدهمَ ذِكْرُ الِاسْتِشْفَاءِ بِالصهلَاةِ مِنْ عَامهةِ الَْأوْجَاعِ قَـبْلَ اسْتِحْكَامِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 258, 'وَالصهلَاةُ مَلََْبَةٌ لِلرِّزْقِ، حَافِظَةٌ لِلصِّحهةِ، دَافِعَةٌ لِلْذََِى، مَطْرَدَةٌ لِلْدَِْوَاءِ، مُقَوِّيَةٌ لِلْقَلْبِ، مُبَـيِّضَةٌ لِلْوَجْ هِ، مُفْرِحَةٌ لِلنهـفْسِ ، مُذْهِبَةٌ لِلْكَسَلِ، مُنَشِّ طَةٌ لِلْجَوَارِحِ، مُِمدهةٌ لِلْقُوَى، شَارِحَةٌ لِلصهدْرِ، مُغَذِّيَةٌ لِلرُّوحِ، مُنَـوِّرَةٌ لِلْقَلْبِ، حَافِظَةٌ لِلنِّعْمَةِ، دَافِعَةٌ لِلنِّقْمَةِ، جَالِبَةٌ لِلْبَـرَكَةِ، مُبْعِدَةٌ مِنَ الشهيْطَانِ مُقَرِّبَةٌ مِنَ الهرحْنَِْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 259, 'وَبِالُْجمْلَةِ: فَـلَهَا تَثَِْيٌر عَجِيبٌ فِي حِفْظِ صِحهةِ الْبَدَنِ وَالْقَلْبِ، وَقُـوَاهُاَُ، وَدَفْعِ الْمَوَادِّ الهردِيئَةِ عَنْـهُمَا، وَمَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 260, 'ابْـتُلِيَ رَجُلَانِ بِعَاهَةٍ أَوْ دَاءٍ أَوْ مِنَُْةٍ أَوْ بَلِيهةٍ إِهلا كَانَ حَظُّ الْمُصَلِّي مِنْـهُمَا أَقَله، وَعَاقِبَـتُهُ أَسْلَمَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 261, 'وَلِلصهلَاةِ تَثَِْيٌر عَجِيبٌ فِي دَفْعِ شُرُورِ الدُّنْـيَا، وَلَا سِيهمَا إِذَا أُعْطِيَتْ حَقههَا مِنَ التهكْمِيلِ ظَاهِرًا وَبَاطِنًا، فَمَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 262, 'اسْتُدْفِعَتْ شُرُورُ الدُّنْـيَا وَالْآخِرَةِ، وَلَا اسْتُجْلِبَتْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 263, '(7) البقرة- .45 (2) البقرة- .753 (3) طه- .732 (4) حديث صحيح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 264, 'مَصَالُِحهُمَا بِِمثْلِ الصهلَاةِ، وَسِرُّ ذَلِكَ أَنه الصهلَاةَ صِلَةٌ بِا هلِلَّ عَهز وَجَله، وَعَلَى قَدْرِ صِلَةِ الْعَبْدِ بِرَبِّهِ عَهز وَجَله', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 265, 'تُـفْتَحُ عَلَيْهِ مِنَ الَْخيْـرَاتِ أَبْـوَابُـهَا، وَتُـقْطَعُ عَنْهُ مِنَ الشُّرُورِ أَسْبَابُـهَا، وَتُفِيضُ عَلَيْهِ مَوَادُّ التهـوْفِيقِ مِنْ رَبِّهِ عَهز', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 266, 'وَجَله، وَالْعَافِيَةُ وَالصِّحهةُ، وَالْغَنِيمَةُ وَالْغِنَى، وَالهراحَةُ وَالنهعِيمُ، وَالَْأفْـرَاحُ وَالْمَسَ هراتُ ، كُلُّهَا مُضَُْرَةٌ لَدَيْهِ، وَمُسَارِعَةٌ إِلَيْهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 267, 'صبَ: «الصهبْـرُ نِصْفُ الِْإيَمانِ» »7« ، فَإِنههُ مَاهِيهةٌ مُرَكهبَةٌ مِنْ صَبٍَْ وَشُكْرٍ، كَمَا قَالَ بَـعْضُ السهلَفِ : الِْإيَمانُ نِصْفَانِ: نِصْفٌ صَبْـرٌ، وَنِصْفٌ شُكْرٌ، قَالَ تَـعَالَى:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 268, 'إِنه فِي ذلِكَ لَآياتٍ لِكُلِّ صَهبارٍ شَكُورٍ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 269, 'وَالصهبْـرُ مِنَ الِْإيَمانِ بَِمنْزِلَةِ الهرأْسِ مِنَ الَْجسَدِ، وَهُوَ ثَلَاثَةُ أَنْـوَاعٍ : صَبْـرٌ عَلَى فَـرَائِضِ ا هلِلَّ فَلَا يُضَيِّعُهَا، وَصَبْـرٌ عَنْ مَاَُرِمِهِ، فَلَا يَـرْتَكِبُـهَا وَصَبْـرٌ عَلَى أَقْضِيَتِهِ وَأَقْدَارِهِ، فَلَا يَـتَسَخهطُهَا، وَمَنِ اسْتَكْمَلَ هَذِهِ الْمَرَاتِبَ الثهلَاثَ ، اسْتَكْمَلَ الصهبْـرَ، وَلَذهةَ الدُّنْـيَا وَالْآخِرَةِ وَنَعِيمَهَا، وَالْفَوْزُ وَالظهفَرُ فِيهِمَا، لَا يَصِلُ إِلَيْهِ أَحَدٌ إِهلا عَلَى جِسْرِ الصهبَِْ، كَمَا لَا يَصِلُ أَحَدٌ إِلَى الَْجنهةِ إِهلا عَلَى الصِّرَاطِ، قَالَ عُمَرُ بْنُ الَْخطهابِ رَضِيَ ا هللَُّ عَنْهُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 270, 'خَيْـرُ عَيْشٍ أَدْركَْ نَاهُ بِالصهبَِْ، وَإِذَا تَمََهلْتَ مَرَاتِبَ الْكَمَالِ الْمُكْتَسَبِ فِي الْعَالََِ، رَأَيْـتَـهَا كُلههَا مَنُوطَةً بِالصهبَِْ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 271, 'وَإِذَا تَمََهلْتَ النُّـقْصَانَ الهذِي يُذَمُّ صَاحِبُهُ عَلَيْهِ، وَيَدْخُلُ تَتََْ قُدْرَتِهِ، رَأَيْـتَهُ كُلههُ مِنْ عَدَمِ الصهبَِْ، فَالشهجَاعَةُ وَالْعِهفةُ، وَالُْجودُ وَالِْإيثَارُ كُلُّهُ صَبْـرُ سَاعَةٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 272, 'فَالصهبْـرُ طِلهسْمٌ عَلَى كَنْزِ الْعُلَى ... مَنْ حَله ذَا الطِّلهسْمَ فَازَ بِكَنْزِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 273, 'وَأَكْ ثَـرُ أَسْقَامِ الْبَدَنِ وَالْقَلْبِ، إِهنَما تَـنْشَأُ عَنْ عَدَمِ الصهبَِْ، فَمَا حُفِظَتْ صِحهةُ الْقُلُوبِ وَالَْأبْدَانِ وَالَْأرْوَاحِ بِِمثْلِ الصهبَِْ، فَـهُوَ الْفَارُوقُ الَْأكْبَـرُ، وَالتِّْريَاقُ الَْأعْظَمُ، وَلَوْ لََْ يَكُنْ فِيهِ إِهلا مَعِيهةُ ا هلِلَّ مَعَ أَهْلِهِ، فَإِنه ا هللََّ مَعَ الصابرين ومبُته لهم، فإن الله', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 274, '(7) أخرجه أبو نعيم في الحلية، والخطيب في تاريخه، والبيهقي في شعب الإيمان. (2) ابراهيم- .51', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 275, 'يحب الصابرين، ونصره لأهله، فإن النصرع الصهبَِْ، وَإِنههُ خَيْـرٌ لَِأهْلِهِ، وَلَئِنْ صَبَـرْتُْم لَهوَُ خَيْـرٌ لِلصهابِرِينَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 276, '»2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 277, '»7« . وإنه سبب الفلاح: يا أَيُّـهَا الهذِينَ آمَنُوا اصْبِوَُا وَصابِرُوا وَرابِطُوا وَاتهـقُوا ا هللََّ لَعَلهكُمْ تُـفْلِحُونَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 278, '.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 279, 'صبَ: رَوَى أبو داود فِي كِتَابِ «الْمَرَاسِيلِ» مِنْ حَدِيثِ قيس بن رافع القيسي، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ: «مَاذَا فِي الَْأمَ هريْنِ مِنَ الشِّ فَاءِ؟ الصهبَُِ وَالثُّـهفاءُ» »3« . وَفِي «السُّنَنِ» لأبي داود: مِنْ حَدِيثِ أم سلمة، قَالَتْ : دَخَلَ عَلَيه رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ حِيَن تُـوُفَِّي أبو سلمة، وَقَدْ جَعَلْتُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 280, 'عَلَيه صَبِاًَ، فَـقَالَ: «مَاذَا يَا أم سلمة؟» فَـقُلْتُ : إِهنَما هُوَ صَبٌَِ يَا رَسُولَ ا هلِلَّ، لَيْسَ فِيهِ طِيبٌ ، قَالَ: «إِنههُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 281, 'يَشُبُّ الْوَجْ هَ، فَلَا تَْعََلِيهِ إِهلا بِاللهيْلِ» وَنَـهَى عَنْهُ بِالهنـهَارِ »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 282, 'الصهبَُِ كَثِيُر الْمَنَافِعِ، لَا سِيهمَا الِْهنْدِيُّ مِنْهُ، يُـنَـقِّي الْفُضُولَ الصهفْرَاوِيهةَ الهتِي فِي الدِّمَاغِ وَأَعْصَابِ الْبَصَرِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 283, 'وَإِذَا طُلِيَ عَلَى الَْجبْـهَةِ وَالصُّدْغِ بِدُهْنِ الْوَرْدِ، نَـفَعَ مِنَ الصُّدَاعِ ، وَيَـنْـفَعُ مِنْ قُـرُوحِ الَْأنْفِ وَالْفَمِ، وَيُسَهِّلُ السهوْدَاءَ وَالْمَالِيخُولْيَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 284, 'وَالصهبَُِ الْفَارِسِيُّ يُذَكِّي الْعَقْلَ، وَيُِمدُّ الْفُؤَادَ، وَيُـنَـقِّي الْفُضُولَ الصهفْرَاوِيهةَ وَالْبَـلْغَمِيههَ مِنَ الْمَعِدَةِ إِذَا شُرِبَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 285, 'مِنْهُ مِلْعَقَتَانِ بَِماءٍ، وَيَـرُدُّ الشههْوَةَ الْبَاطِلَةَ وَالْفَاسِدَةَ، وَإِذَا شُرِبَ فِي الْبَـرْدِ، خِيفَ أَنْ يُسْهِلَ دَمًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 286, 'صوم: الصهوْمُ جُنهةٌ مِنْ أَدْوَاءِ الرُّوحِ وَالْقَلْبِ وَالْبَدَنِ، مَنَافِعُهُ تَـفُوتُ الِْإحْصَاءَ، وَلَهُ تَثَِْيٌر عَجِيبٌ فِي حِفْظِ الصِّحهةِ، وَإِذَابَةِ الْفَضَلَاتِ، وَحَبْسِ النهـفْسِ عَنْ تَـنَاوُلِ مُؤْذِيَاتَِها، وَلَا سِيهمَا إِذَا كَانَ بِاعْتِدَالٍ وَقَصْدٍ فِي أَفْضَلِ أَوْقَاتِهِ شَرْعًا، وَحَاجَةُ الْبَدَنِ إليه طبعا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 287, '(7) النحل- .721 (2) آل عمران- .211', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 288, '(3) رواه أبو داود في المراسيل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 289, '(4) أخرجه أبو داود والنسائي في الطلاق.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 290, 'ُ مه إِنه فِيهِ مِنْ إِرَاحَةِ الْقُوَى وَالَْأعْضَاءِ مَا يَْحفَظُ عَلَيْـهَا قُـوَاهَا، وَفِيهِ خَاصِّ يهةٌ تَـقْتَضِي إِيثَارَهُ، وَهِيَ تَـفْرِيُحهُ لِلْقَلْبِ عَاجِلًا وَآجِلًا، وَهُوَ أَنْـفَعُ شَيْ ءٍ لَِأصْحَابِ الَْأمْزِجَةِ الْبَارِدَةِ وَالهرطْبَةِ، وَلَهُ تَثَِْيٌر عَظِيمٌ فِي حِفْظِ صِحهتِهِمْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 291, 'وَهُوَ يَدْخُلُ في الأدوية الروحانية والطبيعية، وإذا رعى الصهائِمُ فِيهِ مَا يَـنْـبَغِي مُرَاعَاتُهُ طَبْـعًا وَشَرْعًا، عَظُمَ انْتِفَاعُ قَـلْبِهِ وَبَدَنِهِ بِهِ، وَحَبَسَ عَنْهُ الْمَوَاده الْغَرِيبَةَ الْفَاسِدَةَ الهتِي هُوَ مُسْتَعِدٌّ لََها، وَأَزَالَ الْمَوَاده الهردِيئَةَ الَْحاصِلَةَ بَِحسَبِ كَمَالِهِ وَنُـقْصَانِهِ، وَيَْحفَظُ الصهائِمَ مِمها يَـنْـبَغِي أَنْ يَـتَحَ هفظَ مِنْهُ، وَيُعِينُهُ عَلَى قِيَامِهِ بَِمقْصُودِ الصهوْمِ وَسِرِّهِ وَعِلهتِهِ الْغَائِيهةِ، فَإِنه الْقَصْدَ مِنْهُ أَمْرٌ آخَرُ وَرَاءَ تَـرْكِ الطهعَامِ وَالشهرَابِ، وَبِاعْتِبَارِ ذَلِكَ الَْأمْرِ اخْ تَصه مِنْ بَـيِْن الَْأعْمَالِ بَِأنههُ هِلِلَّ سُبْحَانَهُ، وَلَمها كَانَ وِقَايَةً وَجُنهةً بَـيَْن الْعَبْدِ وَبَـيَْن مَا يُـؤْذِي قَـلْبَهُ وَبَدَنَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 292, 'عَاجِلًا وَآجِلًا، قَالَ ا هللَُّ تعالى: يا أَيُّـهَا الهذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيامُ كَما كُتِبَ عَلَى الهذِينَ مِنْ قَـبْلِكُمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 293, 'لَعَلهكُمْ تَـتهـقُونَ [البقرة: ]793 ، فَأَحَدُ مَقْصُودَيِ الصِّيَامِ الُْجنهةُ وَالْوِقَايَةُ، وَهِيَ حِيَْْةٌ عَظِيمَةُ النهـفْعِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 294, 'وَالْمَقْصُودُ الْآخَرُ: اجْ تِمَاعُ الْقَلْبِ وَالَْهمِّ عَلَى ا هلِلَّ تَـعَالَى، وَتَـوْفِيُر قُـوَى النهـفْسِ عَلَى مبُته وَطَاعَتِهِ، وَقَدْ تَـقَدهمَ الْكَلَامُ فِي بَـعْضِ أَسْرَارِ الصهوْمِ عِنْدَ ذِكْرِ هَدْيِهِ صَلهى ا هللَُّ عَلَيْهِ وسلم فيه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 295, 'حَرْفُ الضهادِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 296, 'ضَبٌّ: ثَـبَتَ فِي «الصهحِيحَيِْن» : مِنْ حَدِيثُ ابْنِ عَبهاسٍ ، إِنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ سُئِلَ عَنْهُ لَمها قُدِّمَ إِلَيْهِ، وَامْتَـنَعَ مِنْ أَكْ لِهِ: أَحَرَامٌ هُوَ؟ فَـقَالَ: «لَا وَلَكِنْ لََْ يَكُنْ بَِأرْضِ قَـوْمِي، فَأَجِدُنِي أَعَافُهُ. وَأُكِلَ بَـيَْن يَدَيْهِ وَعَلَى مَائِدَتِهِ وَهُوَ يَـنْظُرُ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 297, 'وَفِي الصهحِيحَيِْن» : مِنْ حَدِيثِ ابْنِ عُمَرَ رَضِيَ ا هللَُّ عَنْـهُمَا، عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «لَا أُحِلُّهُ وَلَا أُحَرِّمُهُ» ]7[ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 298, 'وَهُوَ حَارٌّ يَابِسٌ ، يُـقَوِّي شَهْوَةَ الِْجمَاعِ ، وَإِذَا دُقه ، وَوُضِعَ عَلَى مَوْضِ عِ الشهوْكَةِ اجْ تَذَبَـهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 299, 'ضِ فْدَعٌ: قَالَ الِْإمَامُ أَحْدَُْ: الضِّ فْدَعُ لَا يَِحلُّ فِي الدهوَاءِ، نَـهَى رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ عَنْ قَـتْلِهَا، يُرِيدُ الَْحدِيثَ الهذِي رَوَاهُ فِي «مُسْنَدِهِ» مِنْ حَدِيثِ عثمان بن عبد الرحنْ رَضِيَ ا هللَُّ عَنْهُ، أَنه طَبِيبًا ذكََرَ ضِفْدَعًا فِي دَوَاءٍ عِنْدَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَـنَـهَاهُ عَنْ قَـتْلِهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 300, 'قَالَ صَاحِبُ الْقَانُونِ: مَنْ أَكَلَ مِنْ دَمِ الضِّ فْدَعِ أَوْ جِرْمِهِ، وَرِمَ بَدَنُهُ، وَكَمَدَ لَوْنُهُ، وَقَذَفَ الْمَ ِ هنِ حَ هتى يَُموتَ ، وَلِذَلِكَ تَـرَكَ الَْأطِبهاءُ اسْتِعْمَالَهُ خَوْفًا مِنْ ضَرَرِهِ، وَهِيَ نَـوْعَانِ: مَائِيهةٌ وَتُـرَابِيهةٌ، والترابية يقتل أكلها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 301, 'حَرْفُ الطهاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 302, 'طِيبٌ : ثَـبَتَ عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «حُبِّبَ إِلَهِ مِنْ دُنْـيَاكُمْ: النِّسَاءُ وَالطِّيبُ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 303, 'وَجُعِلَتْ قُـهرةُ عَيْنِِ فِي الصهلَاةِ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 304, 'وَكَانَ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يُكْثِرُ التهطَيُّبَ ، وَتَشْتَدُّ عَلَيْهِ الهرائِحَةُ الْكَرِيهَةُ، وَتَشُقُّ عَلَيْهِ، وَالطِّيبُ غِذَاءُ الرُّوحِ الهتِي هِيَ مَطِيهةُ الْقُوَى تَـتَضَاعَفُ وَتَزِيدُ بِالطِّيبِ، كَمَا تَزِيدُ بِالْغِذَاءِ وَالشهرَابِ، وَالدهعَةِ وَالسُّرُورِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 305, 'وَمُعَاشَرَةِ الَْأحِبهةِ، وَحُدُوثِ الُْأمُورِ الْمَحْ بُوبَةِ، وَغَيْـبَةِ مَنْ تَسُرُّ غَيْـبَـتُهُ، وَيَـثْـقُلُ عَلَى الرُّوحِ مُشَاهَدَتُهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 306, 'كَالثُّـقَلَاءِ وَالْبُـغَضَاءِ، فَإِنه مُعَاشَرَتَـهُمْ تُوهِنُ الْقُوَى، وَتَلَِْبُ  الَْهمه وَالْغَمه، وَهِيَ لِلرُّوحِ بَِمنْزِلَةِ الُْحمهى لِلْبَدَنِ، وَبَِمنْزِلَةِ الهرائِحَةِ الْكَرِيهَةِ، وَلَِهذَا كَانَ مِمها حَبهبَ ا هللَُّ سُبْحَانَهُ الصهحَابَةَ بِنَـهْيِهِمْ عَنِ التهخَلُّقِ بَِهذَا الُْخلُقِ فِي مُعَاشَرَةِ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لِتَأَذِّيهِ بِذَلِكَ ، فَـقَالَ إِذا دُعِيتُمْ فَادْخُلُوا، فَإِذا طَعِمْتُمْ فَانْـتَشِرُوا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 307, 'وَلا مُسْتَأْنِسِيَن لَِحدِيثٍ إِنه ذلِكُمْ كانَ يُـؤْذِي النهبِه فَـيَسْتَحْيِي مِنْكُمْ وَا هللَُّ لَا يَسْتَحْيِي مِنَ الَْحقِّ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 308, '(7) الأحزاب- .53', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 309, 'وَالْمَقْصُودُ أَنه الطِّيبَ كَانَ مِنْ أَحَبِّ  الَْأشْيَاءِ إلى رسول الله هللا ىلص، وَلَهُ تَثَِْيٌر فِي حِفْظِ الصِّحهةِ، وَدَفْعِ كَثِيٍر مِنَ الْآلَامِ، وَأَسْبَابَِها بِسَبَبِ قُـهوةِ الطهبِيعَةِ بِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 310, 'طين: وَرَدَ فِي أَحَادِيثَ مَوْضُوعَةٍ لَا يَصِحُّ مِنْـهَا شَيْ ءٌ مِثْلِ حَدِيثِ «مَنْ أَكَلَ الطِّيَن، فَـقَدْ أَعَانَ عَلَى قَـتْلِ نَـفْسِهِ» وَمِثْلِ حَدِيثِ: «يَا حُيَْْـرَاءُ لَا تَكَُْلِي الطِّيَن فَإِنههُ يَـعْصِمُ الْبَطْنَ، وَيُصَفِّرُ اللهوْنَ، وَيُذْهِبُ بَـهَاءَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 311, 'الْوَجْهِ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 312, 'وَكُلُّ حَدِيثٍ فِي الطِّيِن فَإِنههُ لَا يَصِحُّ وَلَا أَصْلَ لَهُ عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، إِهلا أَنههُ رَدِيءٌ مُؤْذٍ، يَسُدُّ مَاََرِيَ الْعُرُوقِ، وَهُوَ بَارِدٌ يَابِسٌ ، قَوِيُّ التهجْفِيفِ، وَيَْمنَعُ اسْتِطْلَاقَ الْبَطْنِ، وَيُوجِبُ نَـفْثَ الدهمِ وَقُـرُوحَ الْفَمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 313, 'طلح: قال تعالى: وَطَلْحٍ مَنْضُودٍ »7« ، قَالَ أَكْثَـرُ الْمُفَسِّ رِينَ: هُوَ الْمَوْزُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 314, 'وَالْمَنْضُودُ: هُوَ الهذِي قَدْ نُضِّدَ بَـعْضُهُ عَلَى بَـعْضٍ ، كَالْمُشْطِ. وَقِيلَ: الطهلْحُ: الشهجَرُ ذُو الشهوْكِ، نُضِّدَ مَكَانَ كُلِّ شَوْكَةٍ ثَرَََةٌ، فَـثَمَرُهُ قَدْ نُضِّدَ بَـعْضُهُ إِلَى بَـعْضٍ ، فَـهُوَ مِثْلُ الْمَوْزِ، وَهَذَا الْقَوْلُ أَصَحُّ، وَيَكُونُ مِنْ ذِكْرِ الْمَوْزِ مِنَ السهلَفِ أَرَادَ التهمْثِيلَ لَا التهخْصِيصَ وَا هللَُّ أَعْلَمُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 315, 'وَهُوَ حَارٌّ رَطْبٌ ، أَجْ وَدُهُ النهضِيجُ الُْحلْوُ، يَـنْـفَعُ مِنْ خُشُونَةِ الصهدْرِ وَالرِّئَةِ وَالسُّعَالِ، وَقُـرُوحِ الْكُلْيَـتَـيِْن،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 316, 'وَالْمَثَانَةِ، وَيُدِرُّ الْبَـوْلَ، وَيَزِيدُ فِي الْمَنِِِّ، وَيَُحرِّكُ الشههْوَةَ لِلْجِمَاعِ ، وَيُـلَيُِّن الْبَطْنَ، وَيُـؤْكَلُ قَـبْلَ الطهعَامِ، وَيَضُرُّ الْمَعِدَةَ، وَيَزِيدُ فِي الصهفْرَاءِ وَالْبَـلْغَمِ، وَدَفْعُ ضَرَرِهِ بالسكر أو العسل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 317, '»2« . وقال تعالى: وَنَلٍُْ طَلْعُها هَضِيمٌ »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 318, 'طلع: قَالَ تَـعَالَى: وَالنهخْلَ باسِقاتٍ لَها طَلْعٌ نَضِيدٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 319, '(7) الواقعة- 29.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 320, '.71 -ق (2)', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 321, '(3) الشعراء- .749', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 322, 'طَلْعُ النهخْلِ: مَا يَـبْدُو مِنْ ثَرَََتِهِ فِي أَهولِ ظُهُورِهِ، وَقِشْرُهُ يُسَمهى الْكُفُ هرى، وَالنهضِيدُ: الْمَنْضُودُ الهذِي قَدْ نُضِّدَ بَـعْضُهُ عَلَى بَـعْضٍ ، وَإِهنَما يُـقَالُ لَهُ: نَضِيدٌ مَا دَامَ فِي كُفُ هراهُ، فَإِذَا انْـفَتَحَ فَـلَيْسَ بِنَضِيدٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 323, 'وَأَمها الَْهضِيمُ: فَـهُوَ الْمُنْضَمُّ بَـعْضُهُ إِلَى بَـعْضٍ ، فَـهُوَ كَالنهضِيدِ أَيْضًا، وذلك يكون قبل تشقّق لكفري عَنْهُ. وَالطهلْعُ نَـوْعَانِ : ذكََرٌ وَأُنْـثَى، وَالتهـلْقِيحُ هُوَ أَنْ يُـؤْخَذَ مِنَ الذهكَرِ، وَهُوَ مِثْلُ دَقِيقِ الِْحنْطَةِ، فَـيُجْعَلَ فِي الُْأنْـثَى، وَهُوَ التهأْبِيُر، فَـيَكُونُ ذَلِكَ بَِمنْزِلَةِ اللِّقَاحِ بَـيَْن الذهكَرِ وَالُْأنْـثَى، وَقَدْ رَوَى مسلم فِي «صَحِيحِهِ» :', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 324, 'عَنْ طَلْحَةَ بْنِ عُبَـيْدِ ا هلِلَّ رَضِيَ ا هللَُّ عَنْهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 325, 'قَالَ: مَرَرْتُ مَعَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي نَلٍُْ، فَـرَأَى قَـوْمًا يُـلَقِّحُونَ، فَـقَالَ: «مَا يَصْنَعُ هَؤُلَاءِ؟» قَالُوا: خََُْذُونَ مِنَ الذهكَرِ فَـيَجْ عَلُونَهُ فِي الُْأنْـثَى، قَالَ: «مَا أَظُنُّ ذَلِكَ يُـغْنِِ شَيْـئًا» ، فَـبَـلَغَهُمْ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 326, 'فَـتَـرَكُوهُ، فَـلَمْ يَصْلُحْ ، فَـقَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إِهنَما هُوَ ظَنٌّ، فَإِنْ كَانَ يُـغْنِِ شَيْـئًا، فَاصْنَـعُوهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 327, 'فَإِهنَما أَنَا بشر مثلكم، وإنّ الظنّ يخطىء وَيُصِيبُ ، وَلَكِنْ مَا قُـلْتُ لَكُمْ عَنِ ا هلِلَّ عَهز وَجَله. فَـلَنْ أَكْذِبَ عَلَى ا هلِلَّ» »7« انْـتَـهَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 328, 'طَلْعُ النهخْلِ يَـنْـفَعُ مِنَ الْبَاهِ، وَيَزِيدُ فِي الْمُبَاضَعَةِ، وَدَقِيقُ طَلْعِهِ إِذَا تَمََهلَتْ بِهِ الْمَرْأَةُ قَـبْلَ الِْجمَاعِ أَعَانَ عَلَى الَْحبَلِ إِعَانَةً بَالِغَةً، وَهُوَ فِي الْبُـرُودَةِ وَالْيُـبُوسَةِ فِي الدهرَجَةِ الثهانِيَةِ، يُـقَوِّي الْمَعِدَةَ وَيَُجفِّفُهَا، وَيُسَكِّنُ ثَئَِرَةَ الدهمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 329, 'مَعَ غِلْظَةٍ وَبُطْءِ هَضْمٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 330, 'وَلَا يَْحتَمِلُهُ إِهلا أَصْحَابُ الَْأمْزِجَةِ الَْحارهةِ، وَمَنْ أَكْ ثَـرَ مِنْهُ فَإِنههُ يَـنْـبَغِي أَنْ خََُْذَ عَلَيْهِ شَيْـئًا مِنَ الُْجوَارِشَاتِ الَْحارهةِ، وَهُوَ يُـعْقِلُ الطهبْعَ، وَيُـقَوِّي الَْأحْشَاءَ، وَالُْجمهارُ يَْجرِي مَرََْاهُ، وَكَذَلِكَ الْبَـلَحُ، وَالْبُسْرُ، وَالِْإكْ ثَارُ مِنْهُ يَضُرُّ بِالْمَعِدَةِ وَالصهدْرِ، وَرُهبَما أَوْرَثَ الْقُولَنْجَ، وَإِصْلَاحُهُ بِالسهمْنِ، أو بما تقدم ذكره.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 331, '(7) أخرجه مسلم في الفضائل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 332, 'حَرْفُ الْعَيِْن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 333, 'عِنَبٌ : فِي «الْغَيْلَانِيهاتِ» مِنْ حَدِيثِ حبيب بن يسار، عَنِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 334, 'ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كََُْلُ الْعِنَبَ خَرْطًا. قَالَ أَبُو جَعْفَرٍ الْعُقَيْلِيُّ: لَا أَصْلَ لَِهذَا الَْحدِيثِ ، قُـلْتُ : وَفِيهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 335, 'داود بن عبد الجبار أبو سليم الكوفي، قَالَ يَْحيَى بْنُ مَعِيٍن: كَانَ يَكْذِبُ . وَيَذْكُرُ عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ كَانَ يُِحبُّ الْعِنَبَ وَالْبِطِّيخَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 336, 'وَقَدْ ذكََرَ ا هللَُّ سُبْحَانَهُ الْعِنَبَ فِي سِتهةِ مَوَاضِعَ مِنْ كِتَابِهِ فِي جُلََْةِ نِعَمِهِ الهتِي أَنْـعَمَ بَِها عَلَى عِبَادِهِ فِي هَذِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 337, 'الدهارِ وَفِي الَْجنهةِ، وَهُوَ مِنْ أَفْضَلِ الْفَوَاكِهِ وَأَكْ ثَرِهَا مَنَافِعَ، وَهُوَ يُـؤْكَلُ رَطْبًا وَيَابِسًا، وَأَخْضَرَ وَيَانِعًا، وَهُوَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 338, 'فَاكِهَةٌ مَعَ الْفَوَاكِهِ، وَقُوتٌ مَعَ الَْأقْـوَاتِ، وَأُدْمٌ مَعَ الِْإدَامِ، وَدَوَاءٌ مَعَ الَْأدْوِيَةِ، وَشَرَابٌ مَعَ الَْأشْرِبَةِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 339, 'وَطَبْـعُهُ طَبْعُ الَْحبهاتِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 340, 'الَْحرَارَةُ وَالرُّطُوبَةُ، وَجَيِّدُهُ الْكُبهارُ الْمَائِيُّ، وَالَْأبْـيَضُ أَحْدَُْ مِنَ الَْأسْوَدِ إِذَا تَسَاوَيَا فِي الَْحلَاوَةِ، وَالْمَتْـرُوكُ بَـعْدَ قَطْفِهِ يَـوْمَيِْن أَوْ ثَلَاثَةً أَحْدَُْ مِنَ الْمَقْطُوفِ فِي يَـوْمِهِ، فَإِنههُ مُنْفِخٌ مُطْلِقٌ لِلْبَطْنِ، وَالْمُعَلهقُ حَ هتى يَضْمُرَ قِشْرُهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 341, 'جَيِّدٌ لِلْغِذَاءِ، مُقَوٍّ لِلْبَدَنِ، وَغِذَاؤُهُ كَغِذَاءِ التِّيِن وَالهزبِيبِ، وَإِذَا أُلْقِيَ عَجَمُ الْعِنَبِ كَانَ أَكْثَـرَ تَـلْيِينًا لِلطهبِيعَةِ، وَالِْإكْ ثَارُ مِنْهُ مُصَدّعٌِ لِلهرأْسِ ، وَدَفْعُ مَضَ هرتِهِ بِالرُّمهانِ الْمُزِّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 342, 'وَمَنْـفَعَةُ الْعِنَبِ يُسَهِّلُ الطهبْعَ، وَيُسَمِّنُ، وَيَـغْذُو جَيِّدُهُ غِذَاءً حَسَنًا، وَهُوَ أَحَدُ الْفَوَاكِهِ الثهلَاثِ الهتِي هِيَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 343, 'مُلُوكُ الفواكه، هو والرّطب والتين.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 344, 'عسل: قَدْ تَـقَدهمَ ذِكْرُ مَنَافِعِهِ. قَالَ ابْنُ جُرَيْجٍ: قَالَ الزُّهْرِيُّ: عَلَيْكَ بِالْعَسَلِ فَإِنههُ جَيِّدٌ لِلْحِفْظِ، وَأَجْ وَدُهُ أَصْفَاهُ وَأَبْـيَضُهُ، وَأَلْيَـنُهُ حِدهةً، وَأَصْدَقُهُ حَلَاوَةً، وَمَا يُـؤْخَذُ مِنَ الِْجبَالِ وَالشهجَرِ لَهُ فَضْلٌ عَلَى مَا يُـؤْخَذُ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 345, 'الَْخلَايَا، وَهُوَ بَِحسَبِ مرعى نلْه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 346, 'عجوة: فِي «الصهحِيحَيِْن» : مِنْ حَدِيثِ سَعْدِ بْنِ أَبِي وَقهاصٍ رَضِيَ ا هللَُّ عَنْهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 347, 'عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «مَنْ تَصَبهحَ بِسَبْعِ تَرَََاتٍ عَجْوَةً، لََْ يضره ذلك اليوم سم ولا سحر» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 348, 'وفي «سُنَنِ النهسَائِيِّ» وَابْنِ مَاجَهْ: مِنْ حَدِيثِ جابر، وأبي سعيد رَضِيَ ا هللَُّ عَنْـهُمَا، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «الْعَجْوَةُ مِنَ الَْجنهةِ، وَهِيَ شِفَاءٌ مِنَ السُّمِّ، وَالْكَمْأَةُ مِنَ الْمَنِّ، وَمَاؤُهَا شِفَاءٌ لِلْعَيِْن» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 349, 'وَقَدْ قِيلَ: إِنه هَذَا فِي عَجْوَةِ الْمَدِينَةِ، وَهِيَ أَحَدُ أَصْنَافِ التهمْرِ بَِها، وَمِنْ أَنْـفَعِ تَرَِْ الِْحجَازِ عَلَى الِْإطْلَاقِ، وَهُوَ صِنْفٌ كَرِيٌم، مُلَذهذٌ، مَتِيٌن لِلْجِسْمِ وَالْقُهوةِ، مِنْ أَلْيَِن التهمْرِ وَأَطْيَبِهِ وَأَلَذِّهِ، وَقَدْ تَـقَدهمَ ذِكْرُ التهمْرِ وَطَبْعِهِ وَمَنَافِعِهِ فِي حَرْفِ التهاءِ، وَالْكَلَامُ عَلَى دَفْعِ الْعَجْوَةِ لِلسُّمِّ وَالسِّ حْرِ، فَلَا حاجة لإعادته.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 350, 'عنبَ تَـقَدهمَ فِي «الصهحِيحَيِْن» مِنْ حَدِيثِ جابر، فِي قِصهةِ أبي عبيدة، وَأَكْلِهِمْ مِنَ الْعَنْـبََِ شَهْرًا، وَأَنهـهُمْ تَـزَهودُوا مِنْ لَْحمِهِ وَشَائِقَ إِلَى الْمَدِينَةِ، وَأَرْسَلُوا مِنْهُ إِلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَهُوَ أَحَدُ مَا يَدُلُّ عَلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 351, 'أَنه إباحة ما في البحر لا يختص بالمسك، وَعَلَى أَنه مَيْـتَـتَهُ حَلَالٌ، وَاعْتُِرضَ عَلَى ذَلِكَ بَِأنه الْبَحْرَ أَلْقَاهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 352, 'حَيًّا، ُ مه جَزَرَ عَنْهُ الْمَاءُ، فَمَاتَ ، وَهَذَا حَلَالٌ، فَإِنه مَوْتَهُ بِسَبَبِ مُفَارَقَتِهِ لِلْمَاءِ، وَهَذَا لَا يَصِحُّ، فَإِنهـهُمْ إِهنَما وَجَدُوهُ مَيِّتًا بِالسهاحِلِ، وَلََْ يُشَاهِدُوهُ قَدْ خَرَجَ عَنْهُ حَيًّا، ُ مه جَزَرَ عَنْهُ الْمَاءُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 353, 'وَأَيْضًا: فَـلَوْ كَانَ حَيًّا لَمَا أَلْقَاهُ الْبَحْرُ إِلَى سَاحِلِهِ، فَإِنههُ مِنَ الْمَعْلُومِ أَنه الْبَحْرَ إِهنَما يَـقْذِفُ إِلَى سَاحِلِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 354, 'الْمَيِّتَ مِنْ حَيَـوَانَاتِهِ لَا الَْحيه مِنْـهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 355, 'وَأَيْضًا: فَـلَوْ قُدِّرَ احْتِمَالُ مَا ذكََرُوهُ لََْ يَُجزْ أَنْ يَكُونَ شَرْطًا فِي الِْإبَاحَةِ، فَإِنههُ لَا يُـبَاحُ الشهيْ ءُ مَعَ الشهكِّ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 356, 'سَبَبِ إِبَاحَتِهِ، وَلَِهذَا مَنَعَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مِنْ أَكْلِ الصهيْدِ إِذَا وَجَدَهُ الصهائِدُ غَرِيقًا فِي الْمَاءِ لِلشهكِّ فِي سَبَبِ مَوْتِهِ، هَلْ هُوَ الْآلَةُ أَمِ الْمَاءُ؟.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 357, 'وَأَمها الْعَنْـبَـرُ الهذِي هُوَ أَحَدُ أَنْـوَاعِ الطِّيبِ، فهو من أفخر انواعه بعد المسك،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 358, '(7) أخرجه الترمذي في الطب، وأحدْ وابن ماجه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 359, 'وَأَخْطَأَ مَنْ قَدهمَهُ عَلَى الْمِسْكِ ، وَجَعَلَهُ سَيِّدَ أَنْـوَاعِ الطِّيبِ، وَقَدْ ثَـبَتَ عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 360, 'قَالَ فِي الْمِسْكِ : «هُوَ أَطْيَبُ الطِّيبِ» »7« ، وَسَيَأْتِي إِنْ شَاءَ ا هللَُّ تَـعَالَى ذِكْرُ الَْخصَائِصِ وَالْمَنَافِعِ الهتِي خُصه بَِها الْمِسْكُ ، حَ هتى إِنههُ طِيبُ الَْجنهةِ، وَالْكُثْـبَانُ الهتِي هِيَ مَقَاعِدُ الصِّدِّيقِيَن هُنَاكَ مِنْ مِسْكٍ لَا مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 361, 'عَنْـبٍََ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 362, 'وَالهذِي غَهر هَذَا الْقَائِلَ أَنههُ لَا يَدْخُلُهُ التهـغَيُّـرُ عَلَى طُولِ الهزمَانِ، فَـهُوَ كَالذههَبِ، وَهَذَا يَدُلُّ عَلَى أَنههُ أَفْضَلُ مِنَ الْمِسْكِ ، فَإِنههُ بَِهذِهِ الَْخاصِّ يهةِ الْوَاحِدَةِ لَا يُـقَاوِمُ مَا فِي الْمِسْكِ مِنَ الَْخوَاصِّ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 363, 'وَبَـعْدُ فَضُرُوبُهُ كَثِيَرةٌ، وَأَلْوَانُهُ مُْختَلِفَةٌ، فَمِنْهُ الَْأبْـيَضُ وَالَْأشْهَبُ ، وَالَْأحْرَُْ، وَالَْأصْفَرُ، وَالَْأخْضَرُ وَالَْأزْرَقُ، وَالَْأسْوَدُ، وَذُو الَْألْوَانِ. وَأَجْ وَدُهُ: الَْأشْهَبُ ، ُ مه الَْأزْرَقُ ، ُ مه الَْأصْفَرُ، وَأَرْدَؤُهُ: الَْأسْوَدُ. وَقَدِ اخْ تَـلَفَ النهاسُ فِي عُنْصُرِهِ، فَـقَالَتْ طَائِفَةٌ: هُوَ نَـبَاتٌ يَـنْـبُتُ فِي قَـعْرِ الْبَحْرِ، فَـيَـبْـتَلِعُهُ بَـعْضُ دَوَابِّهِ، فَإِذَا ثَلََِتْ مِنْهُ قَذَفَـتْهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 364, 'رَجِيعًا، فَـيَـقْذِفُهُ الْبَحْرُ إِلَى سَاحِلِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 365, 'وَقِيلَ طَلٌّ يَـنْزِلُ مِنَ السهمَاءِ فِي جَزَائِرِ الْبَحْرِ، فَـتُـلْقِيهِ الَْأمْوَاجُ إِلَى السهاحِلِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 366, 'وَقِيلَ: رَوْثُ دَابهةٍ بَْحرِيهةٍ تُشْبِهُ الْبَـقَرَةَ. وَقِيلَ: بَلْ هُوَ جُفَاءٌ مِنْ جُفَاءِ الْبَحْرِ، أَيْ : زَبَدٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 367, 'وَقَالَ صَاحِبُ «الْقَانُونِ» : هُوَ فِيمَا يُظَنُّ يَـنْـبُعُ مِنْ عَيٍْن فِي الْبَحْرِ، وَالهذِي يُـقَالُ: إِنههُ زَبَدُ الْبَحْرِ، أَوْ رَوْثُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 368, 'دَابهةٍ بَعِيدٌ انْـتَـهَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 369, 'وَمِزَاجُهُ حَارٌّ يَابِسٌ ، مُقَوٍّ لِلْقَلْبِ، وَالدِّمَاغِ ، وَالَْحوَاسِّ ، وَأَعْضَاءِ الْبَدَنِ، نَافِعٌ مِنَ الْفَالِجِ وَاللهقْوَةِ، وَالَْأمْرَاضِ الْبَـلْغَمِيهةِ، وَأَوْجَاعِ الْمَعِدَةِ الْبَارِدَةِ، وَالرِّيَاحِ الْغَلِيظَةِ، وَمِنَ السُّدَدِ إِذَا شُرِبَ ، أَوْ طُلِيَ بِهِ مِنْ خَارِجٍ، وَإِذَا تُـبُخِّ رَ بِهِ، نفع من الزّكام والصداع، والشقيقة الباردة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 370, '(7) أخرجه مسلم والترمذي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 371, 'عود: الْعُودُ الِْهنْدِيُّ نَـوْعَانِ ، أَحَدُهُاَُ: يُسْتَـعْمَلُ فِي الَْأدْوِيَةِ وَهُوَ الْكُسْتُ ، وَيُـقَالُ لَهُ: الْقُسْطُ، وَسَيَأْتِي فِي حَرْفِ الْقَافِ. الثهانِي: يُسْتَـعْمَلُ فِي الطِّيبِ، وَيُـقَالُ لَهُ: الَْألُهوةُ. وَقَدْ رَوَى مسلم فِي «صَحِيحِهِ» : عَنِ ابْنِ عُمَرَ رَضِيَ ا هللَُّ عَنْـهُمَا، أَنههُ كَانَ يَسْتَجْمِرُ بِالَْألُهوةِ غَيْـرَ مُطَهراةٍ، وَبِكَافُورٍ يُطْرَحُ مَعَهَا، وَيَـقُولُ: هَكَذَا كَانَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 372, 'يَسْتَجْمِرُ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ »7« ، وَثَـبَتَ عَنْهُ فِي صِفَةِ نَعِيمِ أَهْلِ الَْجنهةِ «مَاََمِرُهُمُ الَْألُهوةُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 373, '»2« وَالْمَجَامِرُ: جَعَُْ مِمََْرٍ وَهُوَ مَا يُـتَجَمهرُ بِهِ مِنْ عُودٍ وَغَيِْرهِ، وَهُوَ أَنْـوَاعٌ. أَجْوَدُهَا: الِْهنْدِيُّ، ُ مه الصِّينُِِّ، ُ مه الْقَمَارِيُّ، ُ مه الْمَنْدَلُِِّ، وَأَجْ وَدُهُ: الَْأسْوَدُ وَالَْأزْرَقُ الصُّلْبُ الهرزِينُ الدهسِمُ، وَأَقَـلُّهُ جَوْدَةً: مَا خَفه وَطَفَا عَلَى الْمَاءِ، وَيُـقَالُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 374, 'إِنههُ شَجَرٌ يُـقْطَعُ وَيُدْفَنُ فِي الَْأرْضِ سَنَةً، فَـتَأْكُلُ الَْأرْضُ مِنْهُ مَا لَا يَـنْـفَعُ، وَيَـبْـقَى عُودُ الطِّيبِ، لا تعمل فيه الأرض شيئا، ويتعفن مِنْهُ قِشْرُهُ وَمَا لَا طِيبَ فِيهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 375, 'وَهُوَ حَارٌّ يَابِسٌ فِي الثهالِثَةِ، يَـفْتَحُ السُّدَدَ، وَيَكْسِرُ الرِّيَاحَ، وَيَذْهَبُ بِفَضْلِ الرُّطُوبَةِ، وَيُـقَوِّي الَْأحْشَاءَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 376, 'وَالْقَلْبَ وَيُـفْرِحُهُ، وَيَـنْـفَعُ الدِّمَاغَ، وَيُـقَوِّي الَْحوَاسه ، وَيَْحبِسُ الْبَطْنَ، وَيَـنْـفَعُ مِنْ سَلَسِ الْبَـوْلِ الَْحادِثِ عَنْ بَـرْدِ الْمَثَانَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 377, 'قَالَ ابن سمجون: الْعُودُ ضُرُوبٌ كَثِيَرةٌ يَْجمَعُهَا اسْمُ الَْألُهوةِ، وَيُسْتَـعْمَلُ مِنْ دَاخِلٍ وَخَارِجٍ، وَيُـتَجَمهرُ بِهِ مُفْرَدًا وَمَعَ غَيِْرهِ، وَفِي الَْخلْطِ لِلْكَافُورِ بِهِ عِنْدَ التهجْ مِيِر مَعْنًى طِبٌِّّ، وَهُوَ إِصْلَاحُ كُلٍّ مِنْـهُمَا بِالْآخَرِ، وَفِي التهجَمُّرِ مُرَاعَاةُ جَوْهَرِ الَْهوَاءِ وَإِصْلَاحُهُ، فَإِنههُ أَحَدُ الَْأشْيَاءِ السِّ تهةِ الضهرُورِيهةِ الهتِي فِي صَلَاحِهَا صَلَاحُ الَْأبْدَانِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 378, 'عَدَسٌ : قَدْ وَرَدَ فِيهِ أَحَادِيثُ كُلُّهَا بَاطِلَةٌ عَلَى رسول الله هللا ىلص، لَ يَـقُلْ شَيْـئًا مِنْـهَا، كَحَدِيثِ: «إِنههُ قُدِّسَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 379, 'عَلَى لِسَانِ سَبْعِيَن نَبِيًّا» وَحَدِيثِ «إِنههُ يُرِقُّ الْقَلْبَ ، وَيُـغْزِرُ الدهمْعَةَ، وَإِنههُ مَأْكُولُ الصهالِِحيَن» ، وَأَرْفَعُ شَيْءٍ جَاءَ فِيهِ، وَأَصَحُّهُ أَنههُ شَهْوَةُ الْيَـهُودِ الهتِي قَدهمُوهَا عَلَى الْمَنِّ وَالسهلْوَى، وَهُوَ قَرِينُ الثُّومِ وَالْبَصَلِ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 380, 'الذِّكْرِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 381, 'وَطَبْـعُهُ طَبْعُ الْمُؤَنهثِ، بَارِدٌ يابس، وفيه قوتان متضادتان. إحداهاُ: يعقل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 382, '(7) أخرجه مسلم في الألفاظ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 383, '(2) أخرجه البخاري في الأنبياء، ومسلم في الجنة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 384, 'الطهبِيعَةَ. وَالُْأخْ رَى: يُطْلِقُهَا، وَقِشْرُهُ حَارٌّ يَابِسٌ فِي الثهالِثَةِ، حِرِّيفٌ مُطْلِقٌ لِلْبَطْنِ، وَتِرْيَاقُهُ فِي قِشْرِهِ، وَلَِهذَا كَانَ صِ حَاحُهُ أَنْـفَعَ مِنْ مَطْحُونِهِ، وَأَخَفه عَلَى الْمَعِدَةِ، وَأَقَله ضَرَرًا، فَإِنه لُبههُ بَطِيءُ الَْهضْمِ لِبُـرُودَتِهِ وَيُـبُوسَتِهِ، وَهُوَ مُوَلِّدٌ لِلسهوْدَاءِ، وَيَضُرُّ بِالْمَالِيخُولْيَا ضَرَرًا بَـيِّنًا، وَيَضُرُّ بِالَْأعْصَابِ وَالْبَصَرِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 385, 'وَهُوَ غَلِيظُ الدهمِ، وَيَـنْـبَغِي أَنْ يَـتَجَنهـبَهُ أَصْحَابُ السهوْدَاءِ، وَإِكْثَارُهُمْ مِنْهُ يُـوَلِّدُ لَهمُْ أَدْوَاءً رَدِيئَةً، كَالْوَسْوَاسِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 386, 'وَالُْجذَامِ، وَحُهْى الرِّبْعِ، وَيُـقَلِّلُ ضَرَرَهُ السِّ لْقُ وَالِْإسْفَانَاخُ، وَإِكْ ثَارُ الدُّهْنِ. وَأَرْدَأَ مَا أُكِلَ بِالنهمْكَسُودِ وَلْيُـتَجَنهبْ خَلْطُ الَْحلَاوَةِ بِهِ، فَإِنههُ يُورِثُ سُدَدًا كَبِدِيهةً، وَإِدْمَانُهُ يُظْلِمُ الْبَصَرَ لِشِدهةِ تَفَِْيفِهِ، وَيُـعْسِرُ الْبَـوْلَ، وَيُوجِبُ الَْأوْرَامَ الْبَارِدَةَ، وَالرِّيَاحَ الْغَلِيظَةَ، وَأَجْ وَدُهُ الَْأبْـيَضُ السهمِيُن، السهرِيعُ النُّضْجِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 387, 'وَأَمها مَا يَظُنُّهُ الُْج ههالُ أَنههُ كَانَ سَِماطَ الَْخلِيلِ الهذِي يُـقَدِّمُهُ لَِأضْيَافِهِ، فَكَذِبٌ مُفْتَـرًى، وَإِهنَما حَكَى ا هللَُّ عَنْهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 388, 'الضِّيَافَةَ بِالشِّ وَاءِ، وَهُوَ الْعِجْلُ الَْحنِيذُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 389, 'وَذكََرَ البيهقي، عَنْ إسحاق قَالَ: سُئِلَ ابْنُ الْمُبَارَكِ عَنِ الَْحدِيثِ الهذِي جَاءَ فِي الْعَدَسِ ، أَنههُ قُدِّسَ عَلَى لِسَانِ سَبْعِيَن نَبِيًّا، فَـقَالَ: وَلَا عَلَى لِسَانِ نَبٍِّ وَاحِدٍ، وَإِنههُ لِمُؤْذٍ مُنْفِخٌ، مَنْ حَدهثَكُمْ بِهِ؟ قَالُوا: سَلْمُ بْنُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 390, 'سَالٍَِ، فَـقَالَ: عَمهنْ ؟ قَالُوا: عَنْكَ . قَالَ: وَعَنِِّ أَيْضًا!!؟.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 391, 'حَرْفُ الْغَيِْن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 392, 'غَيْثٌ : مَذْكُورٌ فِي الْقُرْآنِ فِي عِدهةِ مَوَاضِعَ، وَهُوَ لَذِيذُ الِاسْمِ عَلَى السهمْعِ، وَالْمُسَمهى عَلَى الرُّوحِ وَالْبَدَنِ ، تَـبْـتَهِجُ الَْأسَْماعُ بِذِكْرِهِ وَالْقُلُوبُ بِوُرُودِهِ، وَمَاؤُهُ أَفْضَلُ الْمِيَاهِ، وَأَلْطَفُهَا وَأَنْـفَعُهَا وَأَعْظَمُهَا بَـرَكَةً، وَلَا سِيهمَا إِذَا كَانَ مِنْ سَحَابٍ رَاعِدٍ، وَاجْتَمَعَ فِي مُسْتَـنْـقَعَاتِ الِْجبَالِ، وَهُوَ أَرْطَبُ مِنْ سَائِرِ الْمِيَاهِ، لَِأنههُ لََْ تَطُلْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 393, 'مُدهتُهُ عَلَى الَْأرْضِ ، فَـيَكْتَسِبُ مِنْ يُـبُوسَتِهَا، وَلََْ يَُخالِطْهُ جَوْهَرٌ يَابِسٌ ، وَلِذَلِكَ يَـتَـغَيهـرُ وَيَـتَـعَهفنُ سَرِيعًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 394, 'لِلَطَافَتِهِ وَسُرْعَةِ انْفِعَالِهِ وَهَلِ الْغَيْثُ الهربِيعِيُّ أَلْطَفُ مِنَ الشِّ تْوِيِّ أَوْ بِالْعَكْسِ ؟ فِيهِ قَـوْلَانِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 395, 'قَالَ مَنْ رَجهحَ الْغَيْثَ الشِّ تْوِيه: حَرَارَةُ الشهمْسِ تَكُونُ حِينَئِذٍ أَقَله، فَلَا تَتََْذِبُ مِنْ مَاءِ الْبَحْرِ إِهلا أَلْطَفَهُ، وَالَْجوُّ صَافٍ وَهُوَ خَالٍ مِنَ الَْأخِْرَِةِ الدُّخَانِيهةِ، وَالْغُبَارِ الْمُخَالِطِ لِلْمَاءِ، وَكُلُّ هَذَا يُوجِبُ لُطْفَهُ وَصَفَاءَهُ، وَخُلُهوهُ مِنْ مَُخالِطٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 396, 'قَالَ مَنْ رَجهحَ الهربِيعِيه : الَْحرَارَةُ تُوجِبُ تَلََُّلَ الَْأخِْرَِةِ الْغَلِيظَةِ، وَتُوجِبُ رِقهةَ الَْهوَاءِ وَلَطَافَـتَهُ، فَـيَخِفُّ بِذَلِكَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 397, 'الْمَاءُ، وَتَقِلُّ أَجْزَاؤُهُ الَْأرْضِيهةُ، وَتُصَادِفُ وَقْتَ حَيَاةِ النهـبَاتِ وَالَْأشْجَارِ وَطِيبَ الَْهوَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 398, 'وَذكََرَ الشهافِعِيُّ رَحِهَُْ ا هللَُّ عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ ا هللَُّ عَنْـهُمَا، قَالَ: كُنها مَعَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 399, 'وَسَلهمَ، فَأَصَابَـنَا مَطَرٌ، فَحَسَرَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ ثَـوْبَهُ، وَقَالَ: «إِنههُ حَدِيثُ عَهْدٍ بِرَبِّهِ» »7« ، وَقَدْ تَـقَدهمَ فِي هَدْيِهِ فِي الِاسْتِسْقَاءِ ذِكْ رُ اسْتِمْطَارِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَتَـبَـرُّكِهِ بَِماءِ الْغَيْثِ عِنْدَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 400, 'أول ميَئه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 401, 'حَرْفُ الْفَاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 402, 'فَاتِةََُ الْكِتَابِ: وَأُمُّ الْقُرْآنِ ، وَالسهبْعُ الْمَثَانِي، وَالشِّ فَاءُ التهامُّ، وَالدهوَاءُ النهافِعُ، وَالرُّقْـيَةُ التهامهةُ، وَمِفْتَاحُ الْغِنَى وَالْفَلَاحِ، وَحَافِظَةُ الْقُهوةِ، وَدَافِعَةُ الَْهمِّ وَالْغَمِّ وَالَْخوْفِ وَالَْحزَنِ لِمَنْ عَرَفَ مِقْدَارَهَا وَأَعْطَاهَا حَقههَا، وَأَحْسَنَ تَـنْزِيلَهَا عَلَى دَائِهِ، وَعَرَفَ وَجْ هَ الِاسْتِشْفَاءِ وَالتهدَاوِي بَِها، وَالسِّ هر الهذِي لَِأجْلِهِ كَانَتْ كَذَلِكَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 403, 'وَلَمها وَقَعَ بَـعْضُ الصهحَابَةِ عَلَى ذَلِكَ ، رَقَى بَِها اللهدِيغَ، فَـبَـرَأَ لِوَقْتِهِ، فَـقَالَ لَهُ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «وَمَا أَدْرَاكَ أَنهـهَا رُقْـيَةٌ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 404, 'وَمَنْ سَاعَدَهُ التهـوْفِيقُ، وَأُعِيَن بِنُورِ الْبَصِيَرةِ حَ هتى وَقَفَ عَلَى أَسْرَارِ هَذِهِ السُّورَةِ، وَمَا اشْتَمَلَتْ عَلَيْهِ مِنَ التهـوْحِيدِ، وَمَعْرِفَةِ، الذهاتِ وَالَْأسَْماءِ وَالصِّفَاتِ وَالَْأفْـعَالِ، وَإِثْـبَاتِ الشهرْعِ وَالْقَدَرِ وَالْمَعَادِ، وترَيد توحيد الربوبية والإلهية، وكمال', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 405, '(7) أخرجه مسلم في صلاة الاستسقاء.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 406, 'التوكيل وَالتهـفْوِيضِ إِلَى مَنْ لَهُ الَْأمْرُ كُلُّهُ، وَلَهُ الَْحمْدُ كُلُّهُ، وَبِيَدِهِ الَْخيْـرُ كُلُّهُ، وَإِلَيْهِ يُـرْجَعُ الَْأمْرُ كُلُّهُ، وَالِافْتِقَارُ إِلَيْهِ فِي طَلَبِ الِْهدَايَةِ الهتِي هِيَ أَصْلُ سَعَادَةِ الدهارَيْنِ، وَعَلِمَ ارْتِبَاطَ مَعَانِيهَا بِلَِْبِ مَصَالِِحهِمَا، وَدَفْعِ مَفَاسِدِهِاَُ، وَأَنه الْعَاقِبَةَ الْمُطْلَقَةَ التهامهةَ، وَالنِّعْمَةَ الْكَامِلَةَ مَنُوطَةٌ بَِها، مَوْقُوفَةٌ عَلَى التهحَقُّقِ بَِها، أَغْنَـتْهُ عَنْ كَثِيٍر مِنَ الَْأدْوِيَةِ وَالرُّقَى. وَاسْتَـفْتَحَ بَِها مِنَ الَْخيِْر أَبْـوَابَهُ، وَدَفَعَ بَِها مِنَ الشهرِّ أَسْبَابَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 407, 'وَهَذَا أَمْرٌ يَْحتَاجُ اسْتِحْدَاثَ فِطْرَةٍ أُخْ رَى، وَعَقْلٍ آخَرَ، وَإِيَمانٍ آخَرَ، وَتَا هلِلَّ لَا تَِدَُ مَقَالَةً فَاسِدَةً، وَلَا بِدْعَةً', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 408, 'بَاطِلَةً إِهلا وَفَا تَِةَُ الْكِتَابِ مُتَضَمِّنَةٌ لِرَدِّهَا وَإِبْطَالَِها بَِأقْـرَبِ الطُّرُقِ، وَأَصَحِّ هَا وَأَوْضَحِهَا، وَلَا تَِدَُ بَابًا مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 409, 'أَبْـوَابِ الْمَعَارِفِ الِْإلَِهيهةِ، وَأَعْمَالِ الْقُلُوبِ وَأَدْوِيَتِهَا مِنْ عِلَلِهَا وَأَسْقَامِهَا إِهلا وَفِي فَاتِةََِ الْكِتَابِ مِفْتَاحُهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 410, 'وَمَوْضِعُ الدِّلَالَةِ عَلَيْهِ، وَلَا مَنْزِلًا مِنْ مَنَازِلِ السهائِرِينَ إِلَى رَبِّ الْعَالَمِيَن إِهلا وَبِدَايَـتُهُ وَنَِهايَـتُهُ فِيهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 411, 'وَلَعَمْرُ ا هلِلَّ إِنه شَأْنَـهَا لََأعْظَمُ مِنْ ذَلِكَ ، وَهِيَ فَـوْقَ ذَلِكَ . وَمَا تَقََهقَ عَبْدٌ بَِها، وَاعْتَصَمَ بَِها، وَعَقَلَ عَمهنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 412, 'تَكَلهمَ بَِها، وَأَنْـزَلَهاَ شِفَاءً تَامًّا، وَعِصْمَةً بَالِغَةً، وَنُورًا مُبِينًا، وَفَهِمَهَا وَفَهِمَ لَوَازِمَهَا كَمَا يَـنْـبَغِي لا يقع فِي بِدْعَةٍ وَلَا شِرْكٍ، وَلَا أَصَابَهُ مَرَضٌ مِنْ أَمْرَاضِ الْقُلُوبِ إِهلا لِمَامًا، غَيْـرَ مُسْتَقِرٍّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 413, 'هَذَا، وَإِنهـهَا الْمِفْتَاحُ الَْأعْظَمُ لِكُنُوزِ الَْأرْضِ ، كَمَا أَنهـهَا الْمِفْتَاحُ لِكُنُوزِ الَْجنهةِ، وَلَكِنْ لَيْسَ كُلُّ وَاحِدٍ يُْحسِنُ الْفَتْحَ بَِهذَا الْمِفْتَاحِ، وَلَوْ أَنه طُهلابَ الْكُنُوزِ وَقَـفُوا عَلَى سِرِّ هَذِهِ السُّورَةِ، وَتَقََهقُوا بَِمعَانِيهَا، وَركَهبُوا لَِهذَا الْمِفْتَاحِ أَسْنَانًا، وَأَحْسَنُوا الْفَتْحَ بِهِ، لَوَصَلُوا إِلَى تَـنَاوُلِ الْكُنُوزِ مِنْ غَيِْر مُعَاوِقٍ، وَلَا مَُمانِعٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 414, 'وَلََْ نَـقُلْ هَذَا ماَزفة ولا استعارة، بل حقيقة، ولكن الله تَـعَالَى حِكْمَةٌ بَالِغَةٌ فِي إِخْفَاءِ هَذَا السِّ رِّ عَنْ نُـفُوسِ أَكْ ثَرِ الْعَالَمِيَن، كَمَا لَهُ حِكْمَةٌ بَالِغَةٌ فِي إِخْفَاءِ كُنُوزِ الَْأرْضِ عَنْـهُمْ. وَالْكُنُوزُ الْمَحْجُوبَةُ قَدِ اسْتُخْدِمَ عَلَيْـهَا أَرْوَاحٌ خَبِيثَةٌ شَيْطَانِيهةٌ تَوَُلُ بَـيَْن الِْإنْسِ وَبَـيْـنَـهَا، وَلَا تَـقْهَرُهَا إِهلا أَرْوَاحٌ عُلْوِيهةٌ شَرِيفَةٌ غَالِبَةٌ لََها بَِحالَِها الِْإيَمانِِّي، مَعَهَا مِنْهُ أَسْلِحَةٌ لَا تَـقُومُ لََها الشهيَاطِيُن، وَأَكْثَـرُ نُـفُوسِ النهاسِ لَيْسَتْ بَِهذِهِ الْمَثَابَةِ، فَلَا يُـقَاوِمُ تِلْكَ الَْأرْوَاحَ وَلَا يَـقْهَرُهَا، وَلَا يَـنَالُ مِنْ سَلَبِهَا شَيْـئًا، فَإِنه مَنْ قَـتَلَ قَتِيلًا فله سلبه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 415, 'فاغية: هِيَ نَـوْرُ الِْحنهاءِ، وَهِيَ مِنْ أَطْيَبِ الهريَاحِيِن، رَوَى البيهقي فِي كِتَابِهِ «شُعَبِ الِْإيَمانِ» مِنْ حَدِيثِ عَبْدِ ا هلِلَّ بْنِ بُـرَيْدَةَ، عَنْ أَبِيهِ رَضِيَ ا هللَُّ عَنْهُ يَـرْفَـعُهُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 416, '«سَيِّدُ الهريَاحِيِن فِي الدُّنْـيَا وَالْآخِرَةِ الْفَاغِيَةُ» »7« وَرَوَى فِيهِ أَيْضًا، عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ ا هللَُّ عَنْهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 417, 'قَالَ: «كَانَ أَحَبه الهريَاحِيِن إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ الْفَاغِيَةُ» . وَا هللَُّ أَعْلَمُ بَِحالِ هَذَيْنِ الَْحدِيثَـيِْن، فَلَا نَشْهَدُ عَلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بَِما لَا نَـعْلَمُ صِحهتَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 418, 'وَهِيَ مُعْتَدِلَةٌ فِي الَْحرِّ وَالْيُـبْسِ ، فِيهَا بَـعْضُ الْقَبْضِ ، وَإِذَا وُضِ عَتْ بَـيَْن طَيِّ ثِيَابِ الصُّوفِ حَفِظَتْـهَا مِنَ السُّوسِ ، وَتَدْخُلُ فِي مَرَاهِمِ الْفَالِجِ وَالتهمَدُّدِ، وَدُهْنُـهَا يَُحلِّلُ الَْأعْضَاءَ، وَيُـلَيُِّن الْعَصَبَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 419, 'فضة: ثَـبَتَ أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ خَاتَهَُُ مِنْ فِضهةٍ، وَفَصُّهُ مِنْهُ »2« ، وَكَانَتْ قَبِيعَةُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 420, 'سَيْفِهِ فِضهةً »3« وَلََْ يَصِحه عَنْهُ فِي الْمَنْعِ مِنْ لِبَاسِ الْفِضهةِ وَالتهحَلِّي بَِها شَيْ ءٌ الْبَـتهةَ، كَمَا صَحه عَنْهُ الْمَنْعُ مِنَ الشُّرْبِ فِي آنِيَتِهَا، وَبَابُ الْآنِيَةِ أَضْيَقُ مِنْ بَابِ اللِّبَاسِ ، وَالتهحَلِّي، وَلَِهذَا يُـبَاحُ لِلنِّسَاءِ لِبَاسًا وَحِلْيَةً مَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 421, 'يَْحرُمُ عَلَيْهِنه اسْتِعْمَالُهُ آنِيَةً، فَلَا يَـلْزَمُ مِنْ تَرَِْيِم الْآنِيَةِ تَرَِْيُم اللِّبَاسِ وَالِْحلْيَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 422, 'وَفِي «السُّنَنِ» عَنْهُ: «وَأَمها الْفِضهةُ فَالْعَبُوا بَِها لَعِبًا» »4« فَالْمَنْعُ يَْحتَاجُ إِلَى دَلِيلٍ يُـبَـيِّنُهُ، إِمها نَصٍّ أَوْ إِجْاََعٍ ، فَإِنْ ثَـبَتَ أَحَدُهُاَُ، وَإِهلا فَفِي الْقَلْبِ مِنْ تَرَِْيِم ذَلِكَ عَلَى الرِّجَالِ شَيْ ءٌ، وَالنهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 423, 'أَمْسَكَ بيده ذهبا، وبالأحرى حَرِيرًا، وَقَالَ: «هَذَانِ حَرَامٌ عَلَى ذكُُورِ أُمهتِي، حِلٌّ لِِإنَاثِهِمْ» »5« . وَالْفِضهةُ سِرٌّ مِنْ أَسْرَارِ ا هلِلَّ فِي الَْأرْضِ ، وَطَلْسَمُ الَْحاجَاتِ، وَإِحْسَانُ أَهْلِ الدُّنْـيَا بَـيْـنَـهُمْ، وَصَاحِبُـهَا مَرْمُوقٌ بِالْعُيُونِ بَـيْـنَـهُمْ، مُعَظهمٌ فِي النفوس، مصدّر في', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 424, '(7) وأخرجه أبو نعيم في الطب، والطباَني في الأوسط. (2) أخرجه البخاري والترمذي في الشمائل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 425, '(3) أخرجه الترمذي في الشمائل، وأبو داود والنسائي. (4) أخرجه أحدْ وأبو داود في الخاتم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 426, '(5) حديث صحيح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 427, 'الْمَجَالِسِ ، لَا تُـغْلَقُ دُونَهُ الَْأبْـوَابُ ، وَلَا تُلََُّ مُاََلَسَتُهُ، وَلَا مُعَاشَرَتُهُ، وَلَا يُسْتَـثْـقَلُ مَكَانُهُ، تُشِيُر الَْأصَابِعُ إِلَيْهِ، وَتَـعْقِدُ الْعُيُونُ نِطَاقَـهَا عَلَيْهِ، إِنْ قَالَ، سُِمعَ قَـوْلُهُ، وَإِنْ شَفَعَ، قُبِلَتْ شَفَاعَتُهُ، وَإِنْ شَهِدَ، زكُِّيَتْ شَهَادَتُهُ، وَإِنْ خَطَبَ فَكُفْ ءٌ لَا يُـعَابُ ، وَإِنْ كَانَ ذَا شَيْـبَةٍ بَـيْضَاءَ، فَهِيَ أَجْلََُ عَلَيْهِ مِنْ حِلْيَةِ الشهبَابِ. وَهِيَ مِنَ الَْأدْوِيَةِ الْمُفْرِحَةِ النهافِعَةِ مِنَ الَْهمِّ وَالْغَمِّ وَالَْحزَنِ، وَضَعْفِ الْقَلْبِ وَخَفَقَانِهِ، وَتَدْخُلُ فِي الْمَعَاجِيِن الْكِبَارِ، وَتَتََْذِبُ خِاَِصِّ يهتِهَا مَا يَـتَـوَلهدُ فِي الْقَلْبِ مِنَ الَْأخْلَاطِ الْفَاسِدَةِ، خُصُوصًا إِذَا أُضِيفَتْ إِلَى العسل المصفى، والزغفران.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 428, 'وَمِزَاجُهَا إِلَى الْيُـبُوسَةِ وَالْبُـرُودَةِ، وَيَـتَـوَلهدُ عَنْـهَا مِنَ الَْحرَارَةِ وَالرُّطُوبَةِ مَا يَـتَـوَلهدُ، وَالِْجنَانُ الهتِي أَعَدههَا ا هللَُّ عَهز', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 429, 'وَجَله لَِأوْلِيَائِهِ يَـوْمَ يَـلْقَوْنَهُ أَرْبَعٌ: جَنهـتَانِ مِنْ ذَهَبٍ، وَجَنهـتَانِ مِنْ فِضهةٍ، آنِيَـتُـهُمَا وَحِلْيَـتُـهُمَا وَمَا فِيهِمَا. وَقَدْ ثَـبَتَ عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي «الصهحِيحُ» مِنْ حَدِيثِ أُمِّ سَلَمَةَ أَنههُ قَالَ: «الهذِي يَشْرَبُ فِي آنِيَةِ الذههَبِ وَالْفِضهةِ إِهنَما يَُجرْجِرُ فِي بَطْنِهِ نَارَ جَهَنهمَ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 430, 'وَصَحه عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «لَا تَشْرَبُوا فِي آنِيَةِ الذههَبِ وَالْفِضهةِ، وَلَا تَكَُْلُوا فِي صِحَافِهِمَا، فَإِنهـهَا لَهمُْ فِي الدُّنْـيَا وَلَكُمْ فِي الْآخِرَةِ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 431, 'فَقِيلَ: عِلهةُ التهحْرِيِم تَضْيِيقُ النُّـقُودِ، فَإِنهـهَا إِذَا اتُِّخذَتْ أَوَانَِي فَاتَتِ الِْحكْمَةُ الهتِي وُضِ عَتْ لَِأجْ لِهَا مِنْ قِيَامِ مَصَالِحِ بَنِِ آدَمَ، وَقِيلَ: الْعِلهةُ الْفَخْرُ وَالُْخيَلَاءُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 432, 'وَقِيلَ: الْعِلهةُ كَسْرُ قُـلُوبِ الْفُقَرَاءِ وَالْمَسَاكِيِن إِذَا رَأَوْهَا وَعَايَـنُوهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 433, 'وَهَذِهِ الْعِلَلُ فِيهَا مَا فِيهَا، فَإِنه التهـعْلِيلَ بِتَضْيِيقِ النُّـقُودِ يَْمنَعُ مِنَ التهحَلِّي بَِها وَجَعْلِهَا سَبَائِكَ وَنَوَْْهَا مِمها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 434, 'لَيْسَ بِنِِيَةٍ وَلَا نَـقْدٍ، وَالْفَخْرُ وَالُْخيَلَاءُ حَرَامٌ بَِأيِّ شَيْءٍ كَانَ، وَكَسْرُ قُـلُوبِ الْمَسَاكِيِن لَا ضَابِطَ لَهُ، فَإِنه قُـلُوبَـهُمْ تَـنْكَسِرُ بِالدُّورِ الْوَاسِعَةِ، وَالَْحدَائِقِ الْمُعْجِبَةِ، وَالْمَرَاكِبِ الْفَارِهَةِ، وَالْمَلَابِسِ الْفَاخِرَةِ، وَالَْأطْعِمَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 435, 'اللهذِيذَةِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 436, '(7) أخرجه البخاري في الأشربة، ومسلم في اللباس والزينة. (2) أخرجه البخاري في الأطعمة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 437, 'وَغَيِْر ذَلِكَ مِنَ الْمُبَاحَاتِ، وَكُلُّ هَذِهِ عِلَلٌ مُنْـتَقِضَةٌ، إِذْ تُوجَدُ الْعِلهةُ، وَيَـتَخَلهفُ مَعْلُولَُها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 438, 'فَالصهوَابُ أَنه الْعِلهةَ- وَا هللَُّ أَعْلَمُ- مَا يُكْسِبُ  اسْتِعْمَالَُها الْقَلْبَ  مِنَ الْهيَْـئَةِ، وَالَْحالَةِ الْمُنَافِيَةِ لِلْعُبُودِيهةِ مُنَافَاةً ظَاهِرَةً، وَلَِهذَا عَلهلَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بَِأنهـهَا لِلْكُ هفارِ فِي الدُّنْـيَا، إِذْ لَيْسَ لَهمُْ نَصِيبٌ مِنَ الْعُبُودِيهةِ الهتِي يَـنَالُونَ بَِها فِي الْآخِرَةِ نَعِيمَهَا، فَلَا يَصْلُحُ اسْتِعْمَالَُها لِعَبِيدِ ا هلِلَّ فِي الدُّنْـيَا، وَإِهنَما يَسْتَـعْمِلُهَا مَنْ خَرَجَ عَنْ عُبُودِيهتِهِ، وَرَضِيَ بِالدُّنْـيَا وَعَاجِلِهَا مِنَ الْآخِرَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 439, 'حَرْفُ الْقَافِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 440, 'قُـرْآنٌ: قَالَ ا هللَُّ تَـعَالَى: وَنُـنَـزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفاءٌ وَرَ حَْةٌْ لِلْمُؤْمِنِيَن »7« وَالصهحِيحُ: أَنه «مِنْ » هَاهُنَا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 441, 'لِبَـيَانِ الِْجنْسِ لَا للتبعيض، وقال تعالى: يا أَيُّـهَا النهاسُ قَدْ جاءَتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ وَشِفاءٌ لِما فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 442, 'الصُّدُورِ »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 443, 'فَالْقُرْآنُ هُوَ الشِّ فَاءُ التهامُّ مِنْ جَِيَعِ الَْأدْوَاءِ الْقَلْبِيهةِ وَالْبَدَنِيهةِ، وَأَدْوَاءِ الدُّنْـيَا وَالْآخِرَةِ، وَمَا كُلُّ أَحَدٍ يُـؤَههلُ وَلَا يُـوَفهقُ لِلِاسْتِشْفَاءِ بِهِ، وَإِذَا أَحْسَنَ الْعَلِيلُ التهدَاوِيَ بِهِ، وَوَضَعَهُ عَلَى دَائِهِ بِصِدْقٍ وَإِيَمانٍ، وَقَـبُولٍ تَامٍّ، وَاعْتِقَادٍ جَازِمٍ، وَاسْتِيفَاءِ شُرُوطِهِ، لََْ يُـقَاوِمْهُ الدهاءُ أَبَدًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 444, 'وَكَيْفَ تُـقَاوِمُ كَلَامَ رَبِّ الَْأرْضِ وَالسهمَاءِ الهذِي لَوْ نَـزَلَ عَلَى الِْجبَالِ، لَصَدهعَهَا، أَوْ عَلَى الَْأرْضِ ، لَقَطهعَهَا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 445, 'فَمَا مِنْ مَرَضٍ مِنْ أَمْرَاضِ الْقُلُوبِ وَالَْأبْدَانِ إِهلا وَفِي الْقُرْآنِ سَبِيلُ الدِّلَالَةِ عَلَى دَوَائِهِ وَسَبَبِهِ، وَالَْحمِيهةِ مِنْهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 446, 'لِمَنْ رَزَقَهُ ا هللَُّ فَـهْمًا فِي كِتَابِهِ، وَقَدْ تَـقَدهمَ فِي أَهولِ الْكَلَامِ عَلَى الطِّبِّ بَـيَانُ إِرْشَادِ الْقُرْآنِ الْعَظِيمِ إِلَى أُصُولِهِ وَمَاََمِعِهِ الهتِي هِيَ حِفْظُ الصِّحهةِ وَالِْحمْيَةُ، وَاسْتِفْرَاغُ الْمُؤْذِي، وَالِاسْتِدْلَالُ بِذَلِكَ عَلَى سَائِرِ أَفْـرَادِ هذه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 447, 'الأنواع.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 448, '(7) الإسراء- .92 (2) يونس- .51', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 449, 'وَأَمها الَْأدْوِيَةُ الْقَلْبِيهةُ، فَإِنههُ يَذْكُرُهَا مُفَصهلَةً، وَيَذْكُرُ أَسْبَابَ أَدْوَائِهَا وَعِلَاجَهَا. قَالَ: أَوَلََْ يَكْفِهِمْ أَهنا أَنْـزَلْنا عَلَيْكَ الْكِتابَ يُـتْلى عَلَيْهِمْ»', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 450, 'فَمَنْ لََْ يَشْفِهِ الْقُرْآنُ، فَلَا شَفَاهُ ا هللَُّ، وَمَنْ لََْ يَكْفِهِ، فَلَا كَفَاهُ ا هللَُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 451, 'قِثهاءٌ: فِي «السُّنَنِ» : مِنْ حَدِيثِ عبد الله بن جعفر رَضِيَ ا هللَُّ عَنْهُ، أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ كََُْلُ الْقِثهاءَ بِالرُّطَبِ، وَرَوَاهُ الترمذي وَغَيْـرُهُ »2« :', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 452, 'الْقِثهاءُ بَارِدٌ رَطْبٌ في الدرجة الثانية، مطفىء لَِحرَارَةِ الْمَعِدَةِ الْمُلْتَهِبَةِ، بَطِيءُ الْفَسَادِ فِيهَا، نَافِعٌ مِنْ وَجَ عِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 453, 'الْمَثَانَةِ، وَرَائِحَتُهُ تَـنْـفَعُ مِنَ الْغَشْيِ ، وَبَـزْرُهُ يُدِرُّ الْبَـوْلَ، وَوَرَقُهُ إِذَا اتُِّخذَ ضِمَادًا، نَـفَعَ مِنْ عَضهةِ الْكَلْبِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 454, 'وَهُوَ بَطِيءُ الِانِْدَْارِ عَنِ الْمَعِدَةِ، وَبَـرْدُهُ مُضِرٌّ بِبَـعْضِهَا، فَـيَـنْـبَغِي أَنْ يُسْتَـعْمَلَ مَعَهُ مَا يُصْلِحُهُ وَيَكْسِرُ بُـرُودَتَهُ وَرُطُوبَـتَهُ، كَمَا فَـعَلَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إِذْ أَكَلَهُ بِالرُّطَبِ، فَإِذَا أُكِلَ بِتَمْرٍ أَوْ زَبِيبٍ أَوْ عَسَلٍ عَدَلَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 455, 'قُسْطٌ وَكُسْتٌ : بَِمعْنًى؟؟؟ وَاحِدٍ. وَفِي «الصهحِيحَيِْن» : مِنْ حَدِيثِ أنس رَضِيَ ا هللَُّ عَنْهُ، عَنِ النهبِِّ صَلهى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 456, 'ا هللَُّ عَلَيْهِ وَسَلهمَ «خَيْـرُ مَا تَدَاوَيْـتُمْ بِهِ الِْحجَامَةُ وَالْقُسْطُ الْبَحْرِيُّ» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 457, 'وَفِي «الْمُسْنَدِ» : مِنْ حَدِيثِ أم قيس، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «عَلَيْكُمْ بَِهذَا الْعُودِ الِْهنْدِيِّ ، فَإِنه فِيهِ سَبْـعَةَ أَشْفِيَةٍ مِنْـهَا ذَاتُ الَْجنْبِ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 458, 'الْقُسْطُ: نَـوْعَانِ. أَحَدُهُاَُ: الَْأبْـيَضُ الهذِي يُـقَالُ لَهُ: الْبَحْرِيُّ. وَالْآخَرُ: الِْهنْدِيُّ، وَهُوَ أَشَدُّهُاَُ حَرًّا، وَالَْأبْـيَضُ أَلْيَـنُـهُمَا، وَمَنَافِعُهُمَا كَثِيَرةٌ جِدًّا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 459, 'وَ هَُاُ حَارهانِ يَابِسَانِ فِي الهثالِثَةِ، يُـنَشِّ فَانِ الْبَـلْغَمَ، قَاطِعَانِ لِلزُّكَامِ، وَإِذَا شُرِبَا، نَـفَعَا مِنْ ضَعْفِ الْكَبِدِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 460, 'وَالْمَعِدَةِ وَمِنْ بَـرْدِهِاَُ، وَمِنْ حُهْى الدهوْرِ وَالرِّبْعِ، وَقَطَعَا وَجَعَ الَْجنْبِ، وَنَـفَعَا مِنَ السُّمُومِ، وَإِذَا طُلِيَ بِهِ الْوَجْ هُ مَعْجُونًا بِالْمَاءِ وَالْعَسَلِ، قَـلَعَ الْكَلَفَ . وَقَالَ جالينوس: يَـنْـفَعُ مِنَ الكزاز، ووجع الجنبين، ويقتل حب القرع.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 461, '(7) العنكبوت- .57', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 462, '(2) أخرجه أبو داود والترمذي وابن ماجة في الأطعمة والبخاري في الأطعمة، ومسلم في الأشربة. (3) أخرجه أحدْ والبخاري في الطب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 463, 'وقد خفي على جاهل الَْأطِبهاءِ نَـفْعُهُ مِنْ وَجَعِ ذَاتِ الَْجنْبِ، فَأَنْكَرُوهُ، وَلَوْ ظَفِرَ هَذَا الَْجاهِلُ بَِهذَا النهـقْلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 464, 'عَنْ جالينوس لنزله مَنْزِلَةَ الهنصِّ ، كَيْفَ وَقَدْ نَصه كَثِيٌر مِنَ الَْأطِهباءِ الْمُتَـقَدِّمِيَن عَلَى أَنه الْقُسْطَ يَصْلُحُ لِلنهـوْعِ الْبَـلْغَمِيِّ مِنْ ذَاتِ الَْجنْبِ، ذكََرَهُ الخطابي عَنْ مُمَُهدِ بْنِ الَْجهْمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 465, 'وَقَدْ تَـقَدهمَ أَنه طِبه الَْأطِبهاءِ بِالنِّسْبَةِ إِلَى طِبِّ الَْأنْبِيَاءِ أَقَلُّ مِنْ نِسْبَةِ طِبِّ الطُّرُقِيهةِ وَالْعَجَائِزِ إِلَى طِبِّ الَْأطِبهاءِ، وَأَنه بَـيَْن مَا يُـلْقَى بِالْوَحْيِ ، وَبَـيَْن مَا يُـلْقَى بِالتهجْرِبَةِ، وَالْقِيَاسِ مِنَ الْفَرْقِ أَعْظَمُ مِمها بَـيَْن الْقَدَمِ وَالْفَرْقِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 466, 'وَلَوْ أَنه هَؤُلَاءِ الُْج ههالَ وَجَدُوا دَوَاءً مَنْصُوصًا عَنْ بَـعْضِ الْيَـهُودِ وَالنهصَارَى وَالْمُشْركِِيَن مِنَ الَْأطِبهاءِ، لَتَـلَقهوْهُ بِالْقَبُولِ وَالتهسْلِيمِ، وَلََْ يَـتَـوَقهـفُوا عَلَى تَرَِْبَتِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 467, 'نَـعَمْ نَنُْْ لَا نُـنْكِرُ أَنه لِلْعَادَةِ تَثَِْيًرا فِي الِانْتِفَاعِ بِالدهوَاءِ وَعَدَمِهِ، فَمَنِ اعْتَادَ دَوَاءً وَغِذَاءً، كَانَ أَنْـفَعَ لَهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 468, 'وَأَوْفَقَ مِمهنْ لََْ يَـعْتَدْهُ، بَلْ رُهبَما لََْ يَـنْـتَفِعْ بِهِ مَنْ لََْ يَـعْتَدْهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 469, 'وَكَلَامُ فُضَلَاءِ الَْأطِبهاءِ وَإِنْ كَانَ مُطْلَقًا، فَـهُوَ بَِحسَبِ الَْأمْزِجَةِ وَالَْأزْمِنَةِ، وَالَْأمَاكِنِ وَالْعَوَائِدِ، وَإِذَا كَانَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 470, 'التهـقْيِيدُ بِذَلِكَ لَا يَـقْدَحُ فِي كَلَامِهِمْ وَمَعَارِفِهِمْ، فَكَيْفَ يَـقْدَحُ فِي كَلَامِ الصهادِقِ الْمَصْدُوقِ، وَلَكِنه نُـفُوسَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 471, 'الْبَشَرِ مُرَكهبَةٌ عَلَى الَْجهْلِ وَالظُّلْمِ، إِهلا مَنْ أَيهدَهُ ا هللَُّ بِرُوحِ الِْإيَمانِ ، وَنَـهورَ بَصِيَرتَهُ بِنُورِ الْهدَُى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 472, 'قصب السّكر: جَاءَ فِي بَـعْضِ أَلْفَاظِ السُّهنةِ الصهحِيحَةِ فِي الَْحوْضِ «مَاؤُهُ، أَحْلَى مِنَ السُّكهرِ» »7« ، وَلَا أَعْرِفُ السُّكهرَ فِي الَْحدِيثِ إِهلا فِي هَذَا الْمَوْضِ عِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 473, 'وَالسُّكهرُ حَادِثٌ لََْ يَـتَكَلهمْ فِيهِ مُتَـقَدِّمُو الَْأطِبهاءِ، وَلَا كَانُوا يَـعْرِفُونَهُ، وَلَا يَصِفُونَهُ فِي الَْأشْرِبَةِ، وَإِهنَما يَـعْرِفُونَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 474, 'الْعَسَلَ، وَيُدْخِلُونَهُ فِي الَْأدْوِيَةِ، وَقَصَبُ السكر حار رطب ينفع من السّعال، ويجلوا الرُّطُوبَةَ وَالْمَثَانَةَ، وَقَصَبَةَ الرِّئَةِ، وَهُوَ أَشَدُّ تَـلْيِينًا من', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 475, '(7) في مسلم والترمذي بلفظ: «أحلى من العسل» بدلا من «أحلى من السكر» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 476, 'السُّكهرِ، وَفِيهِ مَعُونَةٌ عَلَى الْقَيْ ءِ، وَيُدِرُّ الْبَـوْلَ، وَيَزِيدُ فِي الْبَاهِ. قَالَ عَهفانُ بْنُ مُسْلِمٍ الصههفارُ: مَنْ مَصه قَصَبَ السُّكهرِ بَـعْدَ طَعَامِهِ، لََْ يَـزَلْ يَـوْمَهُ أَجْعَََ فِي سُرُورٍ، انْـتَـهَى. وَهُوَ يَـنْـفَعُ مِنْ خُشُونَةِ الصهدْرِ وَالَْحلْقِ إِذَا شُوِيَ، وَيُـوَلِّدُ رِيَاحًا دَفْـعُهَا بَِأنْ يُـقَشهرَ، وَيُـغْسَلَ بَِماءٍ حَارٍّ. وَالسُّكهرُ حَارٌّ رَطْبٌ عَلَى الَْأصَحِّ ، وَقِيلَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 477, 'بَارِدٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 478, 'وَأَجْ وَدُهُ: الَْأبْـيَضُ الشه هفافُ الطهبَـرْزَدُ، وَعَتِيقُهُ أَلْطَفُ مِنْ جَدِيدِهِ، وَإِذَا طُبِخَ وَنُزِعَتْ رَغْوَتُهُ، سَكهنَ الْعَطَشَ وَالسُّعَالَ، وَهُوَ يَضُرُّ الْمَعِدَةَ الهتِي تَـتَـوَلهدُ فِيهَا الصهفْرَاءُ لِاسْتِحَالَتِهِ إِلَيْـهَا، وَدَفْعُ ضَرَرِهِ بَِماءِ اللهيْمُونِ أَوِ النهارَنْجِ، أَوِ الرُّمهانِ اللُّهفانِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 479, 'وَبَـعْضُ النهاسِ يُـفَضِّلُهُ عَلَى الْعَسَلِ لِقِلهةِ حَرَارَتِهِ وَلِينِهِ، وَهَذَا تَاََمُلٌ مِنْهُ عَلَى الْعَسَلِ، فَإِنه مَنَافِعَ الْعَسَلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 480, 'أَضْعَافُ مَنَافِعِ السُّكهرِ، وَقَدْ جَعَلَهُ ا هللَُّ شِفَاءً وَدَوَاءً، وَإِدَامًا وَحَلَاوَةً، وَأَيْنَ نَـفْعُ السُّكهرِ مِنْ مَنَافِعِ الْعَسَلِ: مِنْ تَـقْوِيَةِ الْمَعِدَةِ، وَتَـلْيِيِن الطهبْعِ، وَإِحْدَادِ الْبَصَرِ، وَجَلَاءِ ظُلْمَتِهِ، وَدَفْعِ الخوانيق بالغرغرة به، وإبرائه من', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 481, 'الفالَ اللّقوة، وَمِنْ جَِيَعِ الْعِلَلِ الْبَارِدَةِ الهتِي تَدَُْثُ فِي جَِيَعِ الْبَدَنِ مِنَ الرُّطُوبَاتِ، فَـيَجْذِبُـهَا مِنْ قَـعْرِ الْبَدَنِ، وَمِنْ جَِيَعِ الْبَدَنِ، وَحِفْظِ صِحهتِهِ وَتَسْمِينِهِ وتسخينه، والزيادة في الباه، والتحليل الجلاء، وَفَـتْحِ أَفْـوَاهِ الْعُرُوقِ، وَتَـنْقِيَةِ الْمِعَى، وَإِحْدَارِ الدُّودِ، وَمَنْعِ التهخَمِ وَغَيِْرهِ مِنَ الْعَفَنِ، وَالُْأدْمِ النهافِعِ، وَمُوَافَـقَةِ مَنْ غَلَبَ عَلَيْهِ الْبَـلْغَمُ وَالْمَشَايِخُ وَأَهْلُ الَْأمْزِجَةِ الْبَارِدَةِ. وَبِالُْجمْلَةِ: فَلَا شَيْ ءَ أَنْـفَعُ مِنْهُ لِلْبَدَنِ، وَفِي الْعِلَاجِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 482, 'مِثْلُ هَذِهِ الْمَنَافِعِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 483, 'وَعَجْزِ الَْأدْوِيَةِ، وَحِفْظِ قُـوَاهَا، وَتَـقْوِيَةِ الْمَعِدَةِ إِلَى أَضْعَافِ هَذِهِ الْمَنَافِعِ، فَأَيْنَ لِلسُّكهرِ وَالَْخصَائِصِ أَوْ قَرِيبٍ منها؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 484, 'حَرْفُ الْكَافِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 485, 'كِتَابٌ لِلْحُمهى: قَالَ المروزي: بَـلَغَ أبا عبد الله أَنِّي حُِمْْتُ ، فَكَتَبَ لِِ مِنَ الُْحمهى رُقْـعَةً فِيهَا: بِسْمِ ا هلِلَّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 486, 'الهرحْنَِْ الهرحِيمِ، بِسْمِ ا هلِلَّ، وَبِا هلِلَّ، مُمَُهدٌ رَسُولُ ا هلِلَّ، قُـلْنَا: يَا نَارُ كُونِي بَـرْدًا وَسَلَامًا عَلَى إبراهيم، وأرادوا به كيدا، فجعلناهم الأخسرين، اللههُمه رَبه جَبْـرَائِيلَ، وَمِيكَائِيلَ، وَإِسْرَافِيلَ، اشْفِ صَاحِبَ هَذَا الْكِتَابِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 487, 'بَِحوْلِكَ وَقُـهوتِكَ وَجَبَـرُوتِكَ ، إِلَهَ الَْحقِّ آمين.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 488, 'قَالَ المروزي: وَقَـرَأَ عَلَى أبي عبد الله- وَأَنَا أَسَْمعُ- أبو المنذر عمرو بن ممَع، حَدهثَـنَا يونس بن حبان،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 489, 'قَالَ: سَأَلْتُ أبا جعفر محمد بن علي أَنْ أُعَلِّقَ التهـعْوِيذَ، فَـقَالَ: إِنْ كَانَ مِنْ كِتَابِ ا هلِلَّ أَوْ كَلَامٍ عَنْ نَبِِّ ا هلِلَّ فَـعَلِّقْهُ وَاسْتَشْفِ بِهِ مَا اسْتَطَعْتَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 490, 'قُـلْتُ : أَكْتُبُ هَذِهِ مِنْ حُهْى الرّبع: بسم ا هلِلَّ، وَبِا هلِلَّ، وَمُمَُهدٌ رَسُولُ ا هلِلَّ إِلَى آخِرِهِ؟ قَالَ: أَيْ نَـعَمْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 491, 'وَذكََرَ أحدْ عَنْ عائشة رَضِيَ ا هللَُّ عَنْـهَا وَغَيِْرهَا، أَنهـهُمْ سَ ههلُوا فِي ذَلِكَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 492, 'قَالَ حرب: وَلََْ يُشَدِّدْ فِيهِ أَحْدَُْ بْنُ حَنْـبَلٍ. قَالَ أحدْ: وَكَانَ ابْنُ مَسْعُودٍ يَكْ رَهُهُ كَرَاهَةً شَدِيدَةً جِدًّا. وَقَالَ أحدْ وَقَدْ سُئِلَ عَنِ التهمَائِمِ تُـعَلهقُ بَـعْدَ نُـزُولِ الْبَلَاءِ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 493, 'قال: أرجو ألايكون بِهِ بَْأسٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 494, 'قَالَ الخلال: وَحَدهثَـنَا عبد الله بن أحدْ، رَأَيْتُ أَبِي يَكْتُبُ التهـعْوِيذَ لِلهذِي يُـفْزَعُ، وَلِلْحُمهى بعد وقوع البلاء. كتاب لعسر الولادة: قَالَ الخلال: حَدهثَنِِ عبد الله بن أحدْ، قَالَ: رَأَيْتُ أَبِي يَكْتُبُ لِلْمَرْأَةِ إِذَا عَسُرَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 495, 'عَلَيْـهَا وِلَادَتُـهَا فِي جَامٍ أَبْـيَضَ ، أَوْ شَيْ ءٍ نَظِيفٍ ، يَكْتُبُ حَدِيثَ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْهُ: لَا إِلَهَ إِهلا ا هللَُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 496, 'الَْحلِيمُ الْكَرِيُم، سُبْحَانَ ا هلِلَّ رَبِّ الْعَرْشِ الْعَظِيمِ، الَْحمْدُ هِلِلَّ رَبِّ الْعَالَمِيَن: كَأَنهـهُمْ يَـوْمَ يَـرَوْنَ مَا يُوعَدُونَ لََْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 497, 'يَـلْبَـثُوا إِهلا ساعَةً مِنْ نَهارٍ بَلاغٌ »7« ، كَأَنهـهُمْ يَـوْمَ يَـرَوْنَها لََْ يَـلْبَـثُوا إِهلا عَشِيهةً أَوْ ضُحاها »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 498, 'قَالَ الخلال: أَنْـبَأَنَا أبو بكر المروزي، أَنه أبا عبد الله جَاءَهُ رَجُلٌ فَـقَالَ: يَا أبا عبد الله! تَكْتُبُ لِامْرَأَةٍ قَدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 499, 'عَسُرَ عَلَيْـهَا وَلَدُهَا مُنْذُ يَـوْمَيِْن؟ فَـقَالَ: قُلْ لَهُ: يَِجيءُ بِاَِمٍ وَاسِعٍ، وَزَعْفَرَانٍ، وَرَأَيْـتُهُ يَكْتُبُ لِغَيِْر وَاحِدٍ. وَيَذْكُرُ عَنْ عكرمة، عَنِ ابْنِ عَبهاسٍ قَالَ: مَ هر عِيسَى صَلهى ا هللَُّ عَلَى نَبِيِّنَا وَعَلَيْهِ وَسَلهمَ عَلَى بَـقَرَةٍ قَدِ اعْتَـرَضَ وَلَدُهَا في بطنها،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 500, '(7) الأحقاف- .35 (2) النازعات. .41', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 501, 'فَـقَالَتْ : يَا كَلِمَةَ ا هلِلَّ! ادعُْ ا هللََّ لِِ أَنْ يَُخلِّصَنِِ مِمها أَنَا فِيهِ، فَـقَالَ: يَا خَالِقَ النهـفْسِ مِنَ النهـفْسِ ، وَيَا مَُخلِّصَ النهـفْسِ مِنَ النهـفْسِ ، وَيَا مُْخرِجَ النهـفْسِ مِنَ النهـفْسِ ، خَلِّصْهَا. قَالَ: فَـرَمَتْ بِوَلَدِهَا، فَإِذَا هِيَ قَائِمَةٌ تَشُمُّهُ. قَالَ: فَإِذَا عَسُرَ عَلَى الْمَرْأَةِ وَلَدُهَا، فَاكْ تُـبْهُ لََها. وَكُلُّ مَا تَـقَدهمَ مِنَ الرُّقَى، فَإِنه كِتَابَـتَهُ نَافِعَةٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 502, 'وَرَخهصَ جَاََعَةٌ مِنَ السهلَفِ فِي كِتَابَةِ بَـعْضِ الْقُرْآنِ وَشُرْبِهِ، وَجَعْلِ ذَلِكَ مِنَ الشِّ فَاءِ الهذِي جَعَلَ ا هللَُّ فِيهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 503, 'كِتَابٌ آخَرُ لِذَلِكَ : يُكْتَبُ فِي إِنَاءٍ نَظِيفٍ: إِذَا السهماءُ انْشَقهتْ وَأَذِنَتْ لِرَبِّها وَحُقهتْ ، وَإِذَا الَْأرْضُ مُدهتْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 504, 'وَأَلْقَتْ ما فِيها وَتََخهلتْ »7« ، وَتَشْرَبُ مِنْهُ الَْحامِلُ، وَيُـرَشُّ عَلَى بَطْنِهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 505, 'كِتَابٌ للرّعاف: كَانَ شَيْخُ الِْإسْلَامِ ابْنُ تَـيْمِيهةَ رَحِهَُْ ا هللَُّ يكتب على جبهته: وَقِيلَ يا أَرْضُ ابْـلَعِي ماءَكِ، وَيا سَماءُ أَقْلِعِي وَغِيضَ الْماءُ وَقُضِيَ الَْأمْرُ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 506, 'وَسَِمعْتُهُ يَـقُولُ: كَتَـبْـتُـهَا لِغَيِْر وَاحِدٍ فَـبَـرَأَ، فَـقَالَ: وَلَا يَُجوزُ كِتَابَـتُـهَا بِدَمِ الهراعِفِ، كَمَا يَـفْعَلُهُ الُْج ههالُ، فَإِنه الدهمَ نَِسٌْ ، فَلَا يَُجوزُ أَنْ يُكْتَبَ بِهِ كَلَامُ ا هلِلَّ تَـعَالَى.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 507, 'كِتَابٌ آخَرُ لَهُ: خَرَجَ مُوسَى عَلَيْهِ السهلَامُ بِرِدَاءٍ، فَـوَجَدَ شُعَيْـبًا، فَشَدههُ بِرِدَائِهِ يَْمحُوا ا هللَُّ مَا يَشاءُ وَيُـثْبِتُ وَعِنْدَهُ أُمُّ الْكِتابِ »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 508, 'كِتَابٌ آخَرُ لِلْحَ هزازِ: يُكْتَبُ عَلَيْهِ: فَأَصابَها إِعْصارٌ فِيهِ نارٌ، فَاحْ تَـرَقَتْ »4« بَِحوْلِ ا هلِلَّ وَقُـهوتِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 509, 'كِتَابٌ آخَرُ لَهُ: عِنْدَ اصفرار الشمس يكتب عليه: يا أَيُّـهَا الهذِينَ آمَنُوا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 510, '(7) الانشقاق- -7 .4 (2) هود- .44', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 511, '(3) الرعد- .39 (4) البقرة- .221', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 512, 'اتهـقُوا ا هللََّ وَآمِنُوا بِرَسُولِهِ يُـؤْتِكُمْ كِفْلَيِْن مِنْ رَحْتَِْهِ وَيَْجعَلْ لَكُمْ نُوراً تَشَُْونَ بِهِ، وَيَـغْفِرْ لَكُمْ وَا هللَُّ غَفُورٌ رَحِيمٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 513, '. »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 514, 'كتاب آخر للحمى المثلاثة: يُكْتَبُ عَلَى ثَلَاثِ وَرَقَاتٍ لِطَافٍ: بِسْمِ ا هلِلَّ فَـهرتْ ، بِسْمِ ا هلِلَّ مَ هرتْ ، بِسْمِ ا هلِلَّ قَـلهتْ ، وَخََُْذُ كُله يَـوْمٍ وَرَقَةً، وَيَْجعَلُهَا فِي فَمِهِ، وَيَـبْـتَلِعُهَا بَِماءٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 515, 'كِتَابٌ آخَرُ لِعِرْقِ النهسَا: بِسْمِ ا هلِلَّ الهرحْنَِْ الهرحِيمِ، اللههُمه رَبه كُلِّ شَيْ ءٍ، وَمَلِيكَ كُلِّ شَيْ ءٍ، وَخَالِقَ كُلِّ شَيْ ءٍ، أَنْتَ خَلَقْتَنِِ، وَأَنْتَ خَلَقْتَ النهسَا، فَلَا تُسَلِّطْهُ عَلَيه بَِأذًى، وَلَا تُسَلِّطْنِِ عَلَيْهِ بِقَطْعٍ، وَاشْفِنِِ شِفَاءً لَا يُـغَادِرُ سَقَمًا، لَا شَافَِي إِهلا أَنْتَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 516, 'كتاب للعرق الضارب: رَوَى الترمذي فِي «جَامِعِهِ» : مِنْ حَدِيثِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْـهُمَا، أَنه رَسُولَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 517, 'ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ كَانَ يُـعَلِّمُهُمْ مِنَ الُْحمهى، وَمِنَ الَْأوْجَاعِ كُلِّهَا أَنْ يَـقُولُوا: «بِسْمِ ا هلِلَّ الْكَبِيِر، أَعُوذُ بِا هلِلَّ الْعَظِيمِ مِنْ شَرِّ كُلِّ عِرْقٍ نَـعهارٍ، وَمِنْ شَرِّ حَرِّ النهارِ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 518, 'كتاب لوجع الضرس: يُكْتَبُ عَلَى الَْخدِّ الهذِي يَلِي الْوَجَعَ: بِسْمِ ا هلِلَّ الهرحْنَِْ الهرحِيمِ: قُلْ هُوَ الهذِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 519, 'أَنْشَأَكُمْ وَجَعَلَ لَكُمُ السهمْعَ وَالَْأبْصارَ وَالَْأفْئِدَةَ قَلِيلًا مَا تَشْكُرُونَ »3« ، وَإِنْ شَاءَ كَتَبَ : وَلَهُ مَا سَكَنَ فِي اللهيْلِ وَالنههارِ وَهُوَ السهمِيعُ الْعَلِيمُ »4« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 520, 'كتاب للخراج: يكتب عليه: وَيَسْئَـلُونَكَ عَنِ الِْجبالِ فَـقُلْ يَـنْسِفُها رَبِّي نَسْفاً فَـيَذَرُها قَاعًا صَفْصَفاً لَا تَرى فِيها عِوَجاً وَلا أَمْتاً »5« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 521, '(7) الحديد- .29', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 522, '(2) أخرجه الترمذي في الطب. (3) النحل- .29', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 523, '(4) الانعام- .73 (5) طه- .715', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 524, 'كمأة: ثَـبَتَ عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «الْكَمْأَةُ مِنَ الْمَنِّ وَمَاؤُهَا شِفَاءٌ لِلْعَيِْن» ، أَخْ رَجَاهُ فِي «الصهحِيحَيِْن» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 525, 'قَالَ ابْنُ الَْأعْرَابِِّي: جَعٌَْ، وَاحِدُهُ كَمْءٌ، وَهَذَا خِلَافُ قِيَاسِ الْعَرَبِيهةِ، فَإِنه مَا بَـيْـنَهُ وَبَـيَْن وَاحِدِهِ التهاءُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 526, 'فَالْوَاحِدُ منه بالتاء، وَإِذَا حُذِفَتْ كَانَ لِلْجَمْعِ. وَهَلْ هُوَ جَعٌَْ، أَوِ اسْمُ جَعٍَْ؟ عَلَى قَـوْلَيِْن مَشْهُورَيْنِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 527, 'هِيَ عَلَى الْقِيَاسِ : الْكَمْأَةُ لِلْوَاحِدِ، وَالْكَمْءُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 528, 'قَالُوا: وَلََْ يَْخرُجْ عَنْ هَذَا إِهلا حَرْفَانِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 529, 'كَمْأَةٌ وَكَمْءٌ، وَجَبْأَةٌ وَجَبْ ءٌ، وَقَالَ غَيْـرُ ابْنِ الَْأعْرَابِِّي: بَلْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 530, 'لِلْكَثِيِر، وَقَالَ غَيْـرُهُاَُ: الْكَمْأَةُ تَكُونُ وَاحِدًا وَجَعًَْا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 531, 'وَاحْ تَجه أَصْحَابُ الْقَوْلِ الَْأهولِ بَِأنهـهُمْ قَدْ جَعََُوا كَمْئًا عَلَى أَكْمُؤٍ، قَالَ الشهاعِرُ: وَلَقَدْ جَنَـيْـتُكَ أَكْمُؤًا وَعَسَاقِلًا ... وَلَقَدْ نَـهَيْـتُكَ عَنْ بَـنَاتِ الَْأوْبَرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 532, 'وهذا يدل على أن «كمء» مُفْرَدٌ، «وَكَمْأَةً» جَعٌَْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 533, 'وَالْكَمْأَةُ تَكُونُ فِي الَْأرْضِ مِنْ غَيِْر أَنْ تُـزْرعََ، وَسُِّميَتْ كَمْأَةً لِاسْتِتَارِهَا، وَمِنْهُ كَمَأَ الشههَادَةَ: إِذَا سَتَـرَهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 534, 'وَأَخْفَاهَا، وَالْكَمْأَةُ مَْخفِيهةٌ تَتََْ الَْأرْضِ لَا وَرَقَ لََها، وَلَا سَاقَ ، وَمَادهتُـهَا مِنْ جَوْهَرٍ أَرْضِيٍّ خُاَِرِيٍّ مُتَُْقِنٍ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 535, 'الَْأرْضِ نَوَْْ سَطْحِهَا يَْحتَقِنُ بِبَـرْدِ الشِّ تَاءِ، وَتُـنَمِّيهِ أَمْطَارُ الرِّبِيعِ، فَـيَـتَـوَلهدُ وَيَـنْدَفِعُ نَوَْْ سَطْحِ الأرض', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 536, 'متجسدا، ولذلك يقال لها: جدرت الَْأرْضِ ، تَشْبِيهًا بِالُْجدَرِيِّ فِي صُورَتِهِ وَمَادهتِهِ، لَِأنه مَادهتَهُ رُطُوبَةٌ دَمَوِيهةٌ، فَـتَـنْدَفِعُ عِنْدَ سِنِّ التهـرَعْرُعِ فِي الْغَالِبِ، وَفِي ابْتِدَاءِ اسْتِيلَاءِ الَْحرَارَةِ، وَنََماءِ الْقُهوةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 537, 'وَهِيَ مِمها يُوجَدُ فِي الهربِيعِ، وَيُـؤْكَلُ نِيئًا وَمَطْبُوخًا، وَتُسَمِّيهَا الْعَرَبُ : نَـبَاتَ الهرعْدِ لَِأنهـهَا تَكْ ثُـرُ بِكَثْـرَتِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 538, 'وَتَـنْـفَطِرُ عَنْـهَا الَْأرْضُ ، وَهِيَ مِنْ أَطْعِمَةِ أَهْلِ الْبَـوَادِي، وَتَكْ ثُـرُ بَِأرْضِ الْعَرَبِ، وَأَجْ وَدُهَا مَا كَانَتْ أَرْضُهَا رَمْلِيهةً قَلِيلَةَ الْمَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 539, 'وَهِيَ أَصْنَافٌ : مِنْـهَا صِنْفٌ قَـتهالٌ يَضْرِبُ لَوْنُهُ إِلَى الحمرة يحدث الاختناق.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 540, '(7) أخرجه البخاري في الطب، ومسلم في الأشربة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 541, 'وَهِيَ بَارِدَةٌ رَطْبَةٌ فِي الدهرَجَةِ الثهالِثَةِ، رَدِيئَةٌ لِلْمَعِدَةِ، بَطِيئَةُ الْهضَْمِ، وَإِذَا أُدْمِنَتْ ، أَوْرَثَتِ الْقُولَنْجَ وَالسهكْ تَةَ وَالْفَالِجَ، وَوَجَعَ الْمَعِدَةِ، وَعُسْرَ الْبَـوْلِ، وَالهرطْبَةُ أَقَلُّ ضَرَرًا مِنَ الْيَابِسَةِ، وَمَنْ أَكَلَهَا فَـلْيَدْفِنْـهَا فِي الطِّيِن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 542, 'الهرطْبِ، وَيَسْلُقْهَا بِالْمَاءِ وَالْمِلْحِ وَالصهعْتَِر، وَكََُْلْهَا بِالهزيْتِ وَالتهـوَابِلِ الَْحارهةِ، لَِأنه جَوْهَرَهَا أَرْضِ يٌّ غَلِيظٌ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 543, 'وَغِذَاؤُهَا رَدِيءٌ، لَكِنْ فِيهَا جَوْهَرٌ مَائِيٌّ لَطِيفٌ يَدُلُّ عَلَى خِهفتِهَا، وَالِاكْ تِحَالُ بَِها نَافِعٌ مِنْ ظُلْمَةِ الْبَصَرِ وَالهرمَدِ الَْحارِّ، وَقَدِ اعْتَـرَفَ فُضَلَاءُ الَْأطِبهاءِ بَِأنه مَاءَهَا يَْجلُو الْعَيَْن، وَمِمهنْ ذكََرَهُ الْمَسِيحِيُّ، وَصَاحِبُ الْقَانُونِ وَغَيْـرُهُاَُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 544, 'وَقَـوْلُهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «الْكَمْأَةُ مِنَ الْمَنِّ» ، فِيهِ قَـوْلَانِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 545, 'أَحَدُهُاَُ: أَنه الْمَنه الهذِي أُنْزِلَ عَلَى بَنِِ إِسْرَائِيلَ لََْ يَكُنْ هَذَا الُْحلْوَ فَـقَطْ ، بَلْ أَشْيَاءَ كَثِيَرةً مَنه ا هللَُّ عَلَيْهِمْ بَِها مِنَ النهـبَاتِ الهذِي يُوجَدُ عَفْوًا مِنْ غَيِْر صَنْـعَةٍ وَلَا عِلَاجٍ وَلَا حَرْثٍ، فَإِنه الْمَنه مَصْدَرٌ بَِمعْنَى الْمَفْعُولِ، أَيْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 546, '«مَْمنُونٌ» بِهِ، فَكُلُّ مَا رَزَقَهُ ا هللَُّ الْعَبْدَ عَفْوًا بِغَيِْر كَسْبٍ منه ولا علاج، مَنٌّ مَْضٌُ ، وَإِنْ كَانَتْ  سَائِرُ نِعَمِهِ مَنًّا منه على عبده، فخصّ منها مالا كَسْبَ لَهُ فِيهِ، وَلَا صُنْعَ بِاسْمِ الْمَنِّ، فَإِنههُ مَنٌّ بِلَا وَاسِطَةِ الْعَبْدِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 547, 'وَجَعَلَ سُبْحَانَهُ قُـهوتَـهُمْ بِالتِّيهِ الْكَمْأَةَ، وَهِيَ تَـقُومُ مَقَامَ الُْخبْزِ، وَجَعَلَ أُدْمَهُمُ السهلْوَى، وَهُوَ يَـقُومُ مَقَامَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 548, 'اللهحْمِ، وَجَعَلَ حَلْوَاهُمُ الطهله الهذِي يَـنْزِلُ عَلَى الَْأشْجَارِ يَـقُومُ لَهمُْ مَقَامَ الَْحلْوَى، فَكَمُلَ عَيْشُهُمْ. وَتَمََهلْ قَـوْلَهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «الْكَمْأَةُ مِنَ الْمَنِّ الهذِي أَنْـزَلَهُ ا هللَُّ عَلَى بَنِِ إِسْرَائِيلَ» فَجَعَلَهَا مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 549, 'جُلََْتِهِ، وَفَـرْدًا مِنْ أَفْـرَادِهِ، وَالتهـرَنْبَِْيُن الهذِي يَسْقُطُ عَلَى الَْأشْجَارِ نَـوْعٌ مِنَ الْمَنِّ، ُ مه غَلَبَ اسْتِعْمَالُ الْمَنِّ عَلَيْهِ عُرْفًا حَادِثًَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 550, 'وَالْقَوْلُ الثهانِي: أَنههُ شَبههَ الْكَمْأَةَ بِالْمَنِّ الْمُنَـهزلِ مِنَ السهمَاءِ، لَِأنههُ يُْجمَعُ مِنْ غَيِْر تَـعَبٍ وَلَا كُلْفَةٍ وَلَا زَرْعِ بِزْرٍ وَلَا سَقْيٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 551, 'فَإِنْ قُـلْتَ : فَإِنْ كَانَ هَذَا شَأْنَ الْكَمْأَةِ، فَمَا بَالُ هَذَا الضهرَرِ فِيهَا، وَمِنْ أَيْنَ أَتَاهَا ذَلِكَ ؟ فَاعْلَمْ أَنه ا هللََّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 552, 'سُبْحَانَهُ أَتْـقَنَ كُله شَيْ ءٍ صَنَـعَهُ، وَأَحْسَنَ كُله شَيْ ءٍ خَلَقَهُ، فَـهُوَ عِنْدَ مَبْدَأِ خَلْقِهِ بَرِيءٌ مِنَ الْآفَاتِ والعلل، تامّ المنفعة لما هيىء وَخُلِقَ لَهُ، وَإِهنَما', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 553, 'تَـعْرِضُ لَهُ الْآفَاتُ بَـعْدَ ذَلِكَ بُِأمُورٍ أُخَرَ مِنْ مُاََوَرَةٍ، أَوِ امْتِزَاجٍ وَاخْتِلَاطٍ، أَوْ أَسْبَابٍ أُخَرَ تَـقْتَضِي فَسَادَهُ، فَـلَوْ تُرِكَ عَلَى خِلْقَتِهِ الَْأصْلِيهةِ مِنْ غَيِْر تَـعَلُّقِ أَسْبَابِ الْفَسَادِ بِهِ، لََْ يَـفْسُدْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 554, 'وَمَنْ لَهُ مَعْرِفَةٌ بَِأحْ وَالِ الْعَالََِ وَمَبْدَئِهِ يَـعْرِفُ أَنه جَِيَعَ الْفَسَادِ فِي جَوِّهِ وَنَـبَاتِهِ وَحَيَـوَانِهِ، وَأَحْ وَالِ أَهْلِهِ حَادِثٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 555, 'بَـعْدَ خَلْقِهِ بَِأسْبَابٍ اقْـتَضَتْ حُدُوثَهُ، وَلََْ تَـزَلْ أَعْمَالُ بَنِِ آدَمَ وَمَُخالَفَتُـهُمْ لِلرُّسُلِ تُدَِْثُ لَهمُْ مِنَ الْفَسَادِ الْعَامِّ وَالَْخاصِّ مَا يَْجلِبُ عَلَيْهِمْ مِنَ الْآلَامِ، وَالَْأمْرَاضِ ، وَالَْأسْقَامِ، وَالطهوَاعِيِن، وَالْقُحُوطِ، وَالُْجدُوبِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 556, 'وَسَلْبِ بَـرَكَاتِ الَْأرْضِ ، وَثِاََرِهَا، وَنَـبَاتَِها، وَسَلْبِ مَنَافِعِهَا، أَوْ نُـقْصَانَِها أُمُورًا مُتَـتَابِعَةً يَـتْـلُو بَـعْضُهَا بَـعْضًا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 557, 'فَإِنْ لََْ يَـهتسِعْ عِلْمُكَ لَِهذَا فَاكْ تَفِ بِقَوْلِهِ تَـعَالَى: ظَهَرَ الْفَسادُ فِي الْبَـرِّ وَالْبَحْرِ بِما كَسَبَتْ أَيْدِي الهناسِ »7«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 558, '، وَنَـزِّلْ هَذِهِ الْآيَةَ عَلَى أَحْوَالِ الْعَالََِ، وَطَابِقْ بَـيَْن الْوَاقِعِ وَبَـيْـنَـهَا، وَأَنْتَ تَـرَى كَيْفَ تَدَُْثُ الْآفَاتُ وَالْعِلَلُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 559, 'كُله وَقْتٍ فِي الثِّمَارِ وَالهزرْعِ وَالَْحيَـوَانِ، وَكَيْفَ يَْحدُثُ مِنْ تِلْكَ الْآفَاتِ آفَاتٌ أُخَرُ مُتَلَازِمَةٌ، بَـعْضُهَا آخِذٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 560, 'بِرِقَابِ بَـعْضٍ ، وَكُلهمَا أَحْدَثَ النهاسُ ظُلْمًا وَفُجُورًا، أَحْدَثَ لَهمُْ رَبُّـهُمْ تَـبَارَكَ وَتَـعَالَى مِنَ الْآفَاتِ وَالْعِلَلِ فِي أَغْذِيَتِهِمْ وَفَـوَاكِهِهِمْ، وَأَهْوِيَتِهِمْ وَمِيَاهِهِمْ، وَأَبْدَانِِهمْ وَخَلْقِهِمْ، وَصُوَرِهِمْ وَأَشْكَالِِهمْ وَأَخْلَاقِهِمْ مِنَ النهـقْصِ وَالْآفَاتِ، مَا هُوَ مُوجَبُ أَعْمَالِِهمْ وَظُلْمِهِمْ وَفُجُورِهِمْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 561, 'وَلَقَدْ كَانَتِ الُْحبُوبُ مِنَ الِْحنْطَةِ وَغَيِْرهَا أَكْ بَـرَ مِمها هِيَ الْيَـوْمَ، كَمَا كَانَتِ الْبَـرَكَةُ فِيهَا أَعْظَمَ. وَقَدْ رَوَى الِْإمَامُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 562, 'أَحْدَُْ بِِإسْنَادِهِ: أَنههُ وَجَدَ فِي خَزَائِنِ بَـعْضِ بَنِِ أُمَيهةَ صُهرةً فِيهَا حِنْطَةٌ أَمْثَالُ نَـوَى التهمْرِ مَكْ تُوبٌ عَلَيْـهَا: هَذَا كَانَ يَـنْـبُتُ أَهيامَ الْعَدْلِ. وَهَذِهِ الْقِصهةُ، ذكََرَهَا فِي «مُسْنَدِهِ» عَلَى أَثَرِ حَدِيثٍ رَوَاهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 563, 'وَأَكْ ثَـرُ هَذِهِ الَْأمْرَاضِ وَالْآفَاتِ الْعَامهةِ بَقِيهةُ عَذَابٍ عُذِّبَتْ بِهِ الُْأمَمُ السهالِفَةُ، ُ مه بَقِيَتْ مِنْـهَا بَقِيهةٌ مُرْصَدَةٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 564, 'لِمَنْ بَقِيَتْ عَلَيْهِ بَقِيهةٌ مِنْ أَعْمَالِِهمْ، حَكَمًا قِسْطًا، وَقَضَاءً عَدْلًا، وَقَدْ أَشَارَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ إِلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 565, 'هَذَا بِقَوْلِهِ فِي الطهاعُونِ: «إِنههُ بَقِيهةُ رِجْزٍ أَوْ عَذَابٍ أُرْسِلَ عَلَى بَنِِ إسرائيل» . (7) الروم- .47', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 566, 'وَكَذَلِكَ سَلهطَ ا هللَُّ سُبْحَانَهُ وَتَـعَالَى الرِّيحَ عَلَى قَـوْمٍ سَبْعَ لَيَالٍ وَثَاََنِيَةَ أَهيامٍ، ُ مه أَبْـقَى فِي الْعَالََِ مِنْـهَا بَقِيهةً فِي تِلْكَ الَْأهيامِ، وَفِي نَظِيِرهَا عِظَةٌ وَعِبْـرَةٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 567, 'وَقَدْ جَعَلَ ا هللَُّ سُبْحَانَهُ أَعْمَالَ الْبَـرِّ وَالْفَاجِرِ مُقْتَضِيَاتٍ لِآثَرَِهَا فِي هذا العالَ اقتضاء لابد مِنْهُ، فَجَعَلَ مَنْعَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 568, 'الِْإحْسَانِ وَالهزكَاةِ وَالصهدَقَةِ سَبَـبًا لِمَنْعِ الْغَيْثِ مِنَ السهمَاءِ، وَالْقَحْطِ وَالَْجدْبِ، وَجَعَلَ ظُلْمَ الْمَسَاكِيِن،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 569, 'وَالْبَخْسَ فِي الْمَكَايِيلِ وَالْمَوَازِينِ، وَتَـعَدِّي الْقَوِيِّ عَلَى الضهعِيفِ سَبَـبًا لَِجوْرِ الْمُلُوكِ وَالْوُلَاةِ الهذِينَ لَا يَـرْحَوُْنَ إِنِ اسْتُـرْحِوُْا، وَلَا يَـعْطِفُونَ إِنِ اسْتُـعْطِفُوا، وَهُمْ فِي الَْحقِيقَةِ أَعْمَالُ الهرعَايَا ظهرت في صورولاتهم،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 570, 'فَإِنه ا هللََّ سُبْحَانَهُ بِِحكْمَتِهِ وَعَدْلِهِ يُظْهِرُ لِلنهاسِ أَعْمَالَهمُْ فِي قَـوَالِبَ وَصُوَرٍ تُـنَاسِبُـهَا، فَـتَارَةً بِقَحْطٍ وَجَدْبٍ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 571, 'وَتَارَةً بِعَدُوٍّ، وَتَارَةً بِوُلَاةٍ جَائِرِينَ، وَتَارَةً بَِأمْرَاضٍ عَامهةٍ، وَتَارَةً بُِهمُومٍ وَآلَامٍ وَغُمُومٍ تُضَِْ رُهَا نُـفُوسُهُمْ لَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 572, 'يَـنْـفَكُّونَ عَنْـهَا، وَتَارَةً بَِمنْعِ بَـرَكَاتِ السهمَاءِ وَالَْأرْضِ عَنْـهُمْ، وَتَارَةً بِتَسْلِيطِ الشهيَاطِيِن عَلَيْهِمْ توزهم إِلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 573, 'أَسْبَابِ الْعَذَابِ أَزًّا، لِتَحِقه عَلَيْهِمُ الْكَلِمَةُ، وَلِيَصِيَر كُلٌّ مِنْـهُمْ إِلَى مَا خُلِقَ لَهُ، وَالْعَاقِلُ يُسَيُِّر بَصِيَرتَهُ بَـيَْن أَقْطَارِ الْعَالََِ، فَـيُشَاهِدُهُ، وَيَـنْظُرُ مَوَاقِعَ عَدْلِ ا هلِلَّ وَحِكْمَتِهِ، وَحِينَئِذٍ يَـتَـبَـهيُن لَهُ أَنه الرُّسُلَ وَأَتْـبَاعَهُمْ خَاصهةً عَلَى سَبِيلِ النهجَاةِ، وَسَائِرُ الَْخلْقِ عَلَى سَبِيلِ الَْهلَاكِ سَائِرُونَ، وَإِلَى دَارِ الْبَـوَارِ صَائِرُونَ، وَالُّلَُّ بَالِغٌ أَمْرَهُ، لَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 574, 'مُعَقِّبَ لُِحكْمِهِ، وَلَا رَاده لَِأمْرِهِ، وَبِا هلِلَّ التهـوْفِيقُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 575, 'وَقَـوْلُهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي الْكَمْأَةِ «وَمَاؤُهَا شِفَاءٌ لِلْعَيِْن» فِيهِ ثَلَاثَةُ أَقْـوَالٍ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 576, 'أَحَدُهَا: أَنه مَاءَهَا يُْخلَطُ فِي الَْأدْوِيَةِ الهتِي يُـعَالََُ بَِها الْعَيُْن، لَا أَنههُ يُسْتَـعْمَلُ وَحْدَهُ، ذكََرَهُ أَبُو عُبَـيْدٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 577, 'الثهانِي: أَنههُ يُسْتَـعْمَلُ بَْحتًا بَـعْدَ شَيِّهَا، وَاسْتِقْطَارِ مَائِهَا، لَِأنه النهارَ تُـلَطِّفُهُ وَتُـنْضِجُهُ، وَتُذِيبُ فَضَلَاتِهِ وَرُطُوبَـتَهُ الْمُؤْذِيَةَ، وَتُـبْقِي الْمَنَافِعَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 578, 'الثهالِثُ : أَنه الْمُرَادَ بَِمائِهَا الْمَاءُ الهذِي يَْحدُثُ بِهِ مِنَ الْمَطَرِ، وَهُوَ أَهولُ قَطْرٍ يَـنْزِلُ إِلَى الَْأرْضِ ، فَـتَكُونُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 579, 'الِْإضَافَةُ إِضَافَةَ اقْتَِرانٍ، لَا إِضَافَةَ جُزْءٍ، ذكََرَهُ ابْنُ الَْجوْزِيِّ ، وَهُوَ أَبْـعَدُ الوجوه وأضعفها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 580, 'وقيل: إن استعمال مَاؤُهَا لِتَـبِْيَدِ مَا فِي الْعَيِْن، فَمَاؤُهَا مُهََردًا شِفَاءٌ، وَإِنْ كَانَ لِغَيِْر ذَلِكَ ، فَمُرَكهبٌ مَعَ غَيِْرهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 581, 'وَقَالَ الغافقي: مَاءُ الْكَمْأَةِ أَصْلَحُ الَْأدْوِيَةِ لِلْعَيِْن إِذَا عُجِنَ بِهِ الِْإثْدَُِ وَاكْ تُحِلَ بِهِ، وَيُـقَوِّي أَجْ فَانَـهَا، وَيَزِيدُ الرُّوحَ الْبَاصِ رَةَ قُـهوةً وَحِدهةً، ويدفع عنها نزول النوازل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 582, 'كباث: فِي «الصهحِيحَيِْن» : مِنْ حَدِيثِ جَابِرِ بْنِ عَبْدِ ا هلِلَّ رَضِيَ ا هللَُّ عَنْهُ، قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 583, 'كُنها مَعَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ نَنِِْْ الْكَبَاثَ ، فَـقَالَ: «عَلَيْكُمْ بِالَْأسْوَدِ مِنْهُ، فَإِنههُ أَطْيَـبُهُ» »7« . الْكَبَاثُ ، بِفَتْحِ الْكَافِ، وَالْبَاءِ الْمُوَحهدَةِ الْمُخَ هففَةِ، وَالثهاءِ المثلاثة- ثَرََُ الَْأرَاكِ، وَهُوَ بَِأرْضِ الِْحجَازِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 584, 'وَطَبْـعُهُ حَارٌّ يَابِسٌ ، وَمَنَافِعُهُ كَمَنَافِعِ الَْأرَاكِ: يُـقَوِّي الْمَعِدَةَ، وَيُِجيدُ الْهضَْمَ، وَيَْجلُو الْبَـلْغَمَ، وَيَـنْـفَعُ مِنْ أَوْجَاعِ الظههْرِ، وَكَثِيٍر مِنَ الَْأدْوَاءِ. قَالَ ابن جلجل: إِذَا شُرِبَ طَحِينُهُ، أَدَره الْبَـوْلَ، وَنَـقهى الْمَثَانَةَ، وَقَالَ ابن رضوان: يُـقَوِّي الْمَعِدَةَ، وَيُْمسِكُ الطهبِيعَةَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 585, 'كَتَمٌ: رَوَى الْبُخَارِيُّ فِي «صَحِيحِهِ» : عَنْ عُثْمَانَ بْنِ عَبْدِ ا هلِلَّ بْنِ مَوْهَبٍ، قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 586, 'دَخَلْنَا عَلَى أم سلمة رَضِيَ ا هللَُّ عَنْـهَا، فَأَخْ رَجَتْ إِلَيْـنَا شَعْرًا مِنْ شَعْرِ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَإِذَا هُوَ مَْخضُوبٌ بِالِْحنهاءِ وَالْكَتَمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 587, 'وَفِي «السُّنَنِ الَْأرْبَـعَةِ» : عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «إِنه أَحْسَنَ مَا غَيهـرْتُْم بِهِ الشهيْبَ الِْحنهاءُ وَالْكَتَمُ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 588, 'وَفِي «الصهحِيحَيِْن» : عَنْ أنس رَضِيَ ا هللَُّ عَنْهُ، أَنه أبا بكر هللا يضر اختصب بالحناء والكتم »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 589, '(7) أخرجه البخاري في الأطعمة، ومسلم في الأشربة. (2) أخرجه البخاري في اللباس.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 590, '(3) أخرجه البخاري في فضائل أصحاب النب صلّى الله عليه وسلم، ومسلم في الفضائل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 591, 'وَفِي سُنَنِ أبي داود: عَنِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْـهُمَا، قَالَ: مَ هر عَلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ رَجُلٌ قَدْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 592, 'خَضَبَ بِالِْحنهاءِ فَـقَالَ: «مَا أَحْسَنَ هَذَا؟» فَمَ هر آخَرُ قَدْ خَضَبَ بِالِْحنهاءِ وَالْكَتَمِ، فَـقَالَ: «هَذَا أَحْسَنُ مِنْ هَذَا» فَمَ هر آخَرُ قَدْ خَضَبَ بِالصُّفْرَةِ، فَـقَالَ: «هَذَا أَحْسَنُ مِنْ هَذَا كُلِّهِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 593, 'قَالَ الغافقي: الكتم نبت بِالسُّهُولِ، وَرَقُهُ قَرِيبٌ مِنْ وَرَقِ الهزيْـتُونِ، يَـعْلُو فَـوْقَ الْقَامَةِ، وَلَهُ ثَرٌََ قَدْرَ حَبِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 594, 'الْفُلْفُلِ، فِي دَاخِلِهِ نَـوًى، إِذَا رُضِخَ اسْوَده؛ وَإِذَا اسْتُخْرِجَتْ عُصَارَةُ وَرَقِهِ، وَشُرِبَ مِنْـهَا قَدْرُ أُوقِيهةٍ، قَـيهأَ قَـيْـئًا شَدِيدًا، وَيَـنْـفَعُ عَنْ عَضهةِ الْكَلْبِ. وَأَصْلُهُ إِذَا طُبِخَ بِالْمَاءِ كَانَ مِنْهُ مِدَادٌ يُكْتَبُ بِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 595, 'وَقَالَ الكندي: بَـزْرُ الْكَتَمِ إِذَا اكْتُحِلَ بِهِ، حَلهلَ الْمَاءَ النهازِلَ فِي الْعَيِْن وَأَبْـرَأَهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 596, 'وَقَدْ ظَنه بَـعْضُ النهاسِ أَنه الْكَتَمَ هُوَ الْوَسَْمةُ، وَهِيَ وَرَقُ النِّيلِ، وَهَذَا وَهْمٌ، فَإِنه الْوَسَْمةَ غَيْـرُ الْكَتَمِ. قَالَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 597, 'صَاحِبُ «الصِّحَاحِ» : الْكَتَمُ بِالتهحْرِيكِ : نَـبْتٌ يُْخلَطُ بِالْوَسَْمةِ يُْختَضَبُ بِهِ. قِيلَ: وَالْوَسَْمةُ نَـبَاتٌ لَهُ وَرَقٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 598, 'طَوِيلٌ يَضْرِبُ لَوْنُهُ إِلَى الزُّرْقَةِ أَكْ بَـرُ مِنْ وَرَقِ الِْخلَافِ، يُشْبِهُ وَرَقَ اللُّوبِيَا، وَأَكْ بَـرُ مِنْهُ، يُـؤْتَى بِهِ مِنَ الِْحجَازِ وَالْيَمَنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 599, 'فَإِنْ قِيلَ: قَدْ ثَـبَتَ فِي «الصهحِيحِ» عَنْ أنس رَضِيَ ا هللَُّ عَنْهُ، أَنههُ قَالَ: لََْ يَْختَضِبِ النهبِه صَلهى ا هللَُّ عَلَيْهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 600, 'وَسَلهمَ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 601, 'قِيلَ: قَدِ أَجَابَ أَحْدَُْ بْنُ حَنْـبَلٍ عَنْ هَذَا وَقَالَ: قَدْ شَهِدَ بِهِ غَيْـرُ أنس رَضِيَ ا هللَُّ عَنْهُ عَلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ خَضَبَ ، وَلَيْسَ مَنْ شَهِدَ بَِمنْزِلَةِ مَنْ لََْ يَشْهَدْ، فأحدْ أَثْـبَتَ خِضَابَ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَمَعَهُ جَاََعَةٌ مِنَ الْمُحَدِّثِيَن، ومالك أَنْكَرَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 602, 'فَإِنْ قِيلَ: فَـقَدْ ثَـبَتَ فِي «صَحِيحِ مسلم» النهـهْيُ عَنِ الِْخضَابِ بِالسهوَادِ فِي شَأْنِ أبي قحافة لَمها أُتَِي بِهِ وَرَأْسُهُ وَلِْحيَـتُهُ كَالثهـغَامَةِ بَـيَاضًا، فقال: «غيّروا هذا الشّيب وجنّبوه السّواد» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 603, '(7) أخرجه أبو داود وابن ماجة. (2) أخرجه البخاري ومسلم. (3) أخرجه مسلم في اللباس.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 604, 'وَالْكَتَمُ يُسَوِّدُ الشهعْرَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 605, 'فَالَْجوَابُ مِنْ وَجْ هَيِْن، أَحَدُهُاَُ: أَنه النهـهْيَ عَنِ التهسْوِيدِ الْبَحْتِ، فَأَمها إِذَا أُضِيفَ إِلَى الِْحنهاءِ شَيْ ءٌ آخَرُ، كَالْكَتَمِ وَنَوِْْهِ، فَلَا بَْأسَ بِهِ، فَإِنه الْكَتَمَ وَالِْحنهاءَ يَْجعَلُ الشهعْرَ بَـيَْن الَْأحْرَِْ وَالَْأسْوَدِ خِِلَِافِ الْوَسَْمةِ، فَإِنهـهَا تَعََْلُهُ أَسْوَدَ فَاحِاًْ، وَهَذَا أَصَحُّ الَْجوَابَـيِْن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 606, 'الَْجوَابُ الثهانِي: أَنه الِْخضَابَ بِالسهوَادِ الْمَنْهِيِّ عَنْهُ خِضَابُ التهدْلِيسِ ، كَخِضَابِ شَعْرِ الَْجارِيَةِ، وَالْمَرْأَةِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 607, 'الْكَبِيَرةِ تَـغُرُّ الهزوْجَ، وَالسهيِّدَ بِذَلِكَ ، وَخِضَابِ الشهيْخِ يَـغُرُّ الْمَرْأَةَ بِذَلِكَ ، فَإِنههُ مِنَ الْغِشِّ وَالِْخدَاعِ ، فَأَمها إِذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 608, 'لََْ يَـتَضَمهنْ تَدْلِيسًا وَلَا خِدَاعًا، فَـقَدْ صَحه عَنِ الحسن والحسين رَضِيَ ا هللَُّ عَنْـهُمَا أَنهـهُمَا كَانَا يَْخضِ بَانِ بِالسهوَادِ، ذكََرَ ذَلِكَ ابْنُ جَرِيرٍ عَنْـهُمَا فِي كِتَابِ «تَـهْذِيبِ الْآثَرَِ» ، وَذكََرَهُ عَنْ عُثْمَانَ بْنِ عَهفانَ، وَعَبْدِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 609, 'ا هلِلَّ بْنِ جَعْفَرٍ، وَسَعْدِ بْنِ أَبِي وَقهاصٍ ، وَعُقْبَةَ بْنِ عَامِرٍ، وَالْمُغِيَرةِ بْنِ شُعْبَةَ، وَجَرِيرِ بْنِ عَبْدِ ا هلِلَّ، وعمرو ابن الْعَاصِ ، وَحَكَاهُ عَنْ جَاََعَةٍ مِنَ التهابِعِيَن، مِنْـهُمْ: عَمْرُو بْنُ عُثْمَانَ، وَعَلِيُّ بْنُ عَبْدِ ا هلِلَّ بْنِ عَبهاسٍ ، وَأَبُو سَلَمَةَ بْنُ عَبْدِ الهرحْنَِْ، وعبد الرحنْ بن الأسود، وموسى ابن طَلْحَةَ، وَالزُّهْرِيُّ، وأيوب، وإسماعيل بن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 610, 'معدي كرب. وَحَكَاهُ ابْنُ الَْجوْزِيِّ عَنْ مُاَُرِبِ بْنِ دِثَرٍَ، ويزيد، وَابْنِ جُرَيْجٍ، وأبي يوسف، وأبي إسحاق،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 611, 'وَابْنِ أَبِي لَيْـلَى، وَزِيَادِ بْنِ عِلَاقَةَ، وغيلان بن جامع، وَنَافِعِ بْنِ جُبَـيٍْر، وعمرو بن علي المقدمي، والقاسم بن سلام.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 612, 'كرم: شَجَرَةُ الْعِنَبِ، وَهِيَ الَْحبَـلَةُ، وَيُكْ رَهُ تَسْمِيَـتُـهَا كَرْمًا، لِمَا رَوَى مسلم فِي «صَحِيحِهِ» عَنِ النهبِِّ صَلهى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 613, 'ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «لَا يَـقُولَنه أَحَدُكُمْ لِلْعِنَبِ الْكَرْمَ. الْكَرْمُ: الهرجُلُ الْمُسْلِمُ» . وَفِي رِوَايَةٍ: «إِهنَما', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 614, 'الْكَرْمُ قَـلْبُ الْمُؤْمِنِ» »7« وَفِي أُخْ رَى: «لَا تَـقُولُوا: الْكَرْمُ، وَقُولُوا: الْعِنَبُ وَالَْحبَـلَةُ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 615, '(7) أخرجه مسلم. (2) أخرجه مسلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 616, 'وَفِي هَذَا مَعْنَـيَانِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 617, 'أَحَدُهُاَُ: أَنه الْعَرَبَ كَانَتْ تُسَمِّي شَجَرَةَ الْعِنَبِ الْكَرْمَ، لِكَثْـرَةِ مَنَافِعِهَا وَخَيِْرهَا، فَكَرِهَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ تَسْمِيَـتَـهَا بِاسْمٍ يُـهَيِّجُ النُّـفُوسَ عَلَى مَبَُهتِهَا وَمَبَُهةِ مَا يُـتهخَذُ مِنْـهَا مِنَ الْمُسْكِرِ، وَهُوَ أُمُّ الَْخبَائِثِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 618, 'فَكَرِهَ أَنْ يُسَمهى أَصْلُهُ بَِأحْسَنِ الَْأسَْماءِ وَأَجْعََِهَا لِلْخَيِْر.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 619, 'وَالثهانِي: أَنههُ مِنْ بَابِ قَـوْلِهِ: «لَيْسَ الشهدِيدُ بِالصُّرْعَةِ» »7« . «وَلَيْسَ الْمِسْكِيُن بِالطههوافِ» »2« . أَيْ : أَنهكُمْ تُسَمُّونَ شَجَرَةَ الْعِنَبِ كَرْمًا لِكَثْـرَةِ مَنَافِعِهِ، وَقَـلْبُ الْمُؤْمِنِ أَوِ الهرجُلِ الْمُسْلِمِ أَوْلَى بَِهذَا الِاسْمِ مِنْهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 620, 'فَإِنه الْمُؤْمِنَ خَيْـرٌ كُلُّهُ وَنَـفْعٌ، فَـهُوَ مِنْ بَابِ التهـنْبِيهِ وَالتهـعْرِيفِ لِمَا فِي قَـلْبِ الْمُؤْمِنِ مِنَ الَْخيِْر، وَالُْجودِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 621, 'وَالِْإيَمانِ، وَالنُّورِ، وَالْهدَُى، وَالتهـقْوَى، وَالصِّفَاتِ الهتِي يَسْتَحِقُّ بَِها هَذَا الِاسْمَ أَكْ ثَـرَ مِنِ اسْتِحْقَاقِ الَْحبَـلَةِ لَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 622, 'وَبَـعْدُ: فَـقُهوةُ الَْحبَـلَةِ بَارِدَةٌ يَابِسَةٌ، وَوَرَقُـهَا وَعَلَائِقُهَا وَعُرْمُوشُهَا مُبَـرِّدٌ فِي آخِرِ الدهرَجَةِ الُْأولَى، وَإِذَا دُقهتْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 623, 'وَضُمِّدَ بَِها مِنَ الصُّدَاعِ سَكهنَـتْهُ، وَمِنَ الَْأوْرَامِ الَْحارهةِ وَالْتِهَابِ الْمَعِدَةِ. وَعُصَارَةُ قُضْبَانِهِ إِذَا شُرِبَتْ سَكهنَتِ الْقَيْ ءَ، وَعَقَلَتِ الْبَطْنَ، وَكَذَلِكَ إِذَا مُضِغَتْ قُـلُوبُـهَا الهرطْبَةُ. وَعُصَارَةُ وَرَقِهَا، تَـنْـفَعُ مِنْ قُـرُوحِ الَْأمْعَاءِ، وَنَـفْثِ الدهمِ وَقَـيْئِهِ، وَوَجَعِ الْمَعِدَةِ، وَدَمْعُ شَجَرِهِ الهذِي يُْحمَلُ عَلَى الْقَضْبَانِ ، كَالصهمْغِ إِذَا شُرِبَ أَخْ رَجَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 624, 'الَْحصَاةَ، وَإِذَا لُطِّخَ بِهِ، أَبْـرَأَ الْقُوَبَ وَالَْجرَبَ الْمُتَـقَهرحَ وَغَيْـرَهُ، وَيَـنْـبَغِي غَسْلُ الْعُضْوِ قَـبْلَ اسْتِعْمَالَِها بِالْمَاءِ وَالنهطْرُونِ، وَإِذَا تُسَُِّ حَ بَِها مَعَ الهزيْتِ حَلَقَ الشهعْرَ، وَرَمَادُ قُضْبَانِهِ إِذَا تُضُمِّدَ بِهِ مَعَ الَْخلِّ وَدُهْنِ الْوَرْدِ وَالسهذَابِ، نَـفَعَ مِنَ الْوَرَمِ الْعَارِضِ فِي الطِّحَالِ، وَقُـهوةُ دُهْنِ زَهْرَةِ الْكَرْمِ قَابِضَةٌ شَبِيهَةٌ بِقُهوةِ دُهْنِ الْوَرْدِ، وَمَنَافِعُهَا كَثِيَرةٌ قَرِيبَةٌ مِنْ مَنَافِعَ النهخْلَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 625, 'كَرَفْسٌ : رُوِيَ فِي حَدِيثٍ لَا يَصِحُّ عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «مَنْ أَكَلَهُ ُ مه نَامَ عَلَيْهِ، نَامَ وَنَكْهَتُهُ طَيِّبَةٌ، وَيَـنَامُ آمِنًا مِنْ وَجَعِ الَْأضْرَاسِ وَالَْأسْنَانِ» ، وَهَذَا بَاطِلٌ عَلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَلَكِنه الْبُسْتَانِيه مِنْهُ يُطَيِّبُ النهكْهَةَ جِدًّا، وَإِذَا عُلِّقَ أَصْلُهُ فِي الهرقَـبَةِ نَـفَعَ من وجع الأسنان.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 626, '(7) أخرجه البخاري في الأدب، ومسلم في البَ. (2) أخرجه مسلم في الزكاة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 627, 'وَهُوَ حَارٌّ يَابِسٌ ، وَقِيلَ: رَطْبٌ مُفَتِّحٌ لِسُدَادِ الْكَبِدِ وَالطِّحَالِ، وَوَرَقُهُ رَطْبًا يَـنْـفَعُ الْمَعِدَةَ وَالْكَبِدَ الْبَارِدَةَ، وَيُدِرُّ الْبَـوْلَ وَالطهمْثَ ، وَيُـفَتِّتُ الَْحصَاةَ، وَحَبُّهُ أَقْـوَى فِي ذَلِكَ ، وَيُـهَيِّجُ الْبَاهَ، وَيَـنْـفَعُ مِنَ الْبَخَرِ. قَالَ الرازي: وَيَـنْـبَغِي أَنْ يُْجتَـنَبَ أَكْ لُهُ إذا خيف من لدغ العقارب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 628, 'كراث: فِيهِ حَدِيثٌ لَا يَصِحُّ عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، بَلْ هُوَ بَاطِلٌ مَوْضُوعٌ: «مَنْ أَكَلَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 629, 'الْكُ هراثَ ُ مه نَامَ عَلَيْهِ نَامَ آمِنًا مِنْ رِيحِ الْبَـوَاسِيِر وَاعْتَـزَلَهُ الْمَلَكُ لِنَـتَُِ نَكْهَتِهِ حَ هتى يُصْبِحَ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 630, 'وَهُوَ نَـوْعَانِ: نَـبَطِيٌّ وَشَامِيٌّ، فَالنهـبَطِيُّ: الْبَـقْلُ الهذِي يُوضَعُ عَلَى الْمَائِدَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 631, 'والشّامي: الذي له رؤوس، وَهُوَ حَارٌّ يَابِسٌ مُصَدّعٌِ، وَإِذَا طُبِخَ وَأُكِلَ، أَوْ شُرِبَ مَاؤُهُ، نَـفَعَ مِنَ الْبَـوَاسِيِر الْبَارِدَةِ. وَإِنْ سُحِقَ بِزْرُهُ، وَعُجِنَ بِقَطِرَانٍ، وَخُِرَِّتْ بِهِ الَْأضْرَاسُ الهتِي فِيهَا الدُّودُ نَـثَـرَهَا وَأَخْ رَجَهَا، وَيُسَكِّنُ الْوَجَعَ الْعَارِضَ فِيهَا، وَإِذَا دُخِّنَتِ الْمَقْعَدَةُ بِبِزْرِهِ خَ هفتِ الْبَـوَاسِيُر، هَذَا كُلُّهُ فِي الْكُ هراثِ النهـبَطِيِّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 632, 'وَفِيهِ مَعَ ذَلِكَ فَسَادُ الَْأسْنَانِ وَاللهثَةِ، وَيُصَدّعُِ، وَيُرِي أَحْلَامًا رَدِيئَةً، وَيُظْلِمُ الْبَصَرَ، وَيُـنْتُُِ النهكْهَةَ، وَفِيهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 633, 'إِدْرَارٌ لِلْبَـوْلِ وَالطهمْثِ، وَتَرَِْيكٌ لِلْبَاهِ، وَهُوَ بطيء الهضم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 634, 'حَرْفُ الهلامِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 635, 'لَْحمٌ: قَالَ ا هللَُّ تَـعَالَى: وَأَمْدَدْناهُمْ بِفاكِهَةٍ وَلَْحمٍ مِمها يَشْتَـهُونَ »7« وقال:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 636, 'وَلَْحمِ طَيٍْر مِمها يَشْتَـهُونَ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 637, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» مِنْ حَدِيثِ أَبِي الدهرْدَاءِ، عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «سيّد', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 638, '(7) الطور- .22 (2) الواقعة- .27', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 639, 'طَعَامِ أَهْلِ الدُّنْـيَا، وَأَهْلِ الَْجنهةِ اللهحْمُ» »7« وَمِنْ حَدِيثِ بريدة يَـرْفَـعُهُ: «خَيْـرُ الِْإدَامِ فِي الدُّنْـيَا وَالْآخِرَةِ اللهحْمُ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 640, 'وَفِي «الصهحِيحِ» عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «فَضْلُ عائشة عَلَى النِّسَاءِ كَفَضْلِ الثهرِيدِ عَلَى سَائِرِ الطهعَامِ» »3« . وَالثهرِيدُ: الُْخبْـزُ وَاللهحْمُ، قَالَ الشهاعِرُ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 641, 'إِذَا مَا الُْخبْـزُ تَدَِْمُهُ بِلَحْمٍ ... فَذَاكَ أَمَانَةَ ا هلِلَّ الثهرِيدُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 642, '»7« وَقَالَ الزُّهْرِيُّ: أَكْلُ اللهحْمِ يَزِيدُ سَبْعِيَن قُـهوةً. وَقَالَ مُمَُهدُ بْنُ وَاسِعٍ: اللهحْمُ يَزِيدُ فِي الْبَصَرِ، وَيُـرْوَى عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ ا هللَُّ عنه: «كُلُوا اللهحْمَ» فَإِنههُ يُصَفِّي اللهوْنَ وَيُْخمِصُ الْبَطْنَ، وَيَُحسِّ نُ الُْخلُقَ» وَقَالَ نافع: كَانَ ابْنُ عُمَرَ إِذَا كَانَ رَمَضَانُ لََْ يَـفُتْهُ اللهحْمُ، وَإِذَا سَافَـرَ لََْ يَـفُتْهُ اللهحْمُ. وَيُذْكَرُ عَنْ علي مَنْ تَـرَكَهُ أَرْبَعِيَن لَيْـلَةً سَاءَ خُلُقُهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 643, 'وَأَمها حَدِيثُ عائشة رَضِيَ ا هللَُّ عَنْـهَا، الهذِي رَوَاهُ أبو داود مَرْفُوعًا: «لَا تَـقْطَعُوا اللهحْمَ بِالسِّ كِّيِن، فَإِنههُ مِنْ صَنِيعِ الَْأعَاجِمِ، وَانْـهَسُوهُ، فَإِنههُ أَهْنَأُ وَأَمْرَأُ» »', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 644, '. فَـرَدههُ الِْإمَامُ أَحْدَُْ بَِما صَحه عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مِنْ قَطْعِهِ بِالسِّ كِّيِن فِي حَدِيثَـيِْن، وَقَدْ تَـقَدهمَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 645, 'وَاللهحْمُ أَجْنَاسٌ يَْختَلِفُ  بِاخْتِلَافِ أُصُولِهِ وَطَبَائِعِهِ، فَـنَذْكُرُ حُكْمَ كُلِّ جِنْسٍ  وَطَبْـعَهُ وَمَنْـفَعَتَهُ وَمَضَ هرتَهُ. لَْحمُ الضهأْنِ : حَارٌّ فِي الثهانِيَةِ، رَطْبٌ فِي الُْأولَى، جَيِّدُهُ الَْحوْلُِِّ، يُـوَلِّدُ الدهمَ الْمَحْمُودَ الْقَوِيه لِمَنْ جَادَ هَضْمُهُ، يَصْلُحُ لَِأصْحَابِ الَْأمْزِجَةِ الْبَارِدَةِ وَالْمُعْتَدِلَةِ، وَلَِأهْلِ الرِّيَاضَاتِ التهامهةِ فِي الْمَوَاضِعِ وَالْفُصُولِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 646, 'الْبَارِدَةِ، نَافِعٌ لَِأصْحَابِ الْمِ هرةِ السهوْدَاءِ، يُـقَوِّي الذِّهْنَ وَالِْحفْظَ. وَلَْحمُ الَْهرِمِ وَالْعَجِيفِ رديء، وكذلك لحم', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 647, 'النّعاج، وأجوده: لحم', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 648, '(7) أخرجه ابن ماجة في الأطعمة. (2) أخرجه البيهقي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 649, '(3) أخرجه البخاري ومسلم. (4) أخرجه أبو داود في الأطعمة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 650, 'الذهكَرِ الَْأسْوَدِ مِنْهُ، فَإِنههُ أَخَفُّ وَأَلَذُّ وَأَنْـفَعُ، وَالَْخصِيُّ أَنْـفَعُ وَأَجْ وَدُ، وَالَْأحْرَُْ مِنَ الَْحيَـوَانِ السهمِيُن أَخَفُّ وَأَجْ وَدُ غِذَاءً، وَالَْجذَعُ مِنَ الْمَعْزِ أَقَلُّ تَـغْذِيَةً، وَيَطْفُو فِي الْمَعِدَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 651, 'وَأَفْضَلُ اللهحْمِ عَائِذُهُ بِالْعَظْمِ، وَالَْأيَْمنُ أَخَفُّ وَأَجْ وَدُ مِنَ الَْأيْسَرِ، وَالْمُقَدهمُ أَفْضَلُ مِنَ الْمُؤَخهرِ، وَكَانَ أَحَبه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 652, 'الشهاةِ إِلَى رَسُولِ ا هلِلَّ صَ هلى ا هللَُّ عَلَيْهِ وَسَ هلمَ مُقَدهمُهَا، وَكُلُّ مَا عَلَا مِنْهُ سِوَى الهرأْسِ كَانَ أَخَفه وَأَجْ وَدَ مِمها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 653, 'سَفَلَ، وَأَعْطَى الْفَرَزْدَقُ رَجُلًا يَشْتَِري لَهُ لَْحمًا وَقَالَ لَهُ: خُذِ الْمُقَدهمَ، وَإِهياكَ وَالهرأْسَ وَالْبَطْنَ، فَإِنه الدهاءَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 654, 'فِيهِمَا. وَلَْحمُ الْعُنُقِ جَيِّدٌ لَذِيذٌ، سَرِيعُ الْهضَْمِ خَفِيفٌ ، وَلَْحمُ الذِّرَاعِ أَخَفُّ اللهحْمِ وَأَلَذُّهُ وَأَلْطَفُهُ وَأَبْـعَدُهُ مِنَ الَْأذَى، وَأَسْرَعُهُ انِْهضَامًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 655, 'وَفِي «الصهحِيحَيِْن» : أَنههُ كَانَ يُـعْجِبُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَ هلمَ »7« : وَلَْحمُ الظههْرِ كَثِيُر الْغِذَاءِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 656, 'يُـوَلِّدُ دَمًا مَمُُْودًا. وَفِي «سُنَنِ ابْنِ مَاجَهْ» مَرْفُوعًا: «أَطْيَبُ اللهحْمِ لحم الظّهر» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 657, 'لحم المعز: قَلِيلُ الَْحرَارَةِ، يَابِسٌ ، وَخَلْطُهُ الْمُتَـوَلِّدُ مِنْهُ لَيْسَ بِفَاضِلٍ وَلَيْسَ بِيَِِّدِ الَْهضْمِ، وَلَا مَمُُْودِ الْغِذَاءِ. وَلَْحمُ التهـيْسِ رَدِيءٌ مُطْلَقًا، شَدِيدُ الْيُـبْسِ ، عَسِرُ الِانِْهضَامِ، مُوَلِّدٌ لِلْخَلْطِ السهوْدَاوِيِّ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 658, 'قَالَ الَْجاحِظُ: قَالَ لِِ فَاضِلٌ مِنَ الَْأطِبهاءِ: يَا أبا عثمان! إِهياكَ وَلَْحمَ الْمَعْزِ، فَإِنههُ يُورِثُ الْغَمه، وَيَُحرِّكُ السهوْدَاءَ، وَيُورِثُ النِّسْيَانَ، وَيُـفْسِدُ الدهمَ، وَهُوَ وَا هلِلَّ يَْخبِلُ الَْأوْلَادَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 659, 'وَقَالَ بَـعْضُ الَْأطِبهاءِ: إِهنَما الْمَذْمُومُ مِنْهُ الْمُسِنُّ، وَلَا سِيهمَا لِلْمُسِنِّيَن، وَلَا رَدَاءَةَ لِمَنِ اعْتَادَهُ. وجالينوس', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 660, 'جَعَلَ الَْحوْلِهِ مِنْهُ مِنَ الَْأغْذِيَةِ الْمُعْتَدِلَةِ الْمُعَدِّلَةِ لِلْكَيْمُوسِ الْمَحْمُودِ، وَإِنَاثُهُ أَنْـفَعُ من ذكوره.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 661, '(7) أخرجه البخاري في الأنبياء، ومسلم في الايمان. (2) أخرجه ابن ماجة في الأطعمة، وأحدْ والحاكم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 662, 'وَقَدْ رَوَى الهنسَائِيُّ فِي «سُنَنِهِ» : عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «أَحْسِنُوا إِلَى الْمَاعِزِ وَأَمِيطُوا عَنْـهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 663, 'الَْأذَى فَإِنهـهَا مِنْ دَوَابِّ الَْجنهةِ» . وَفِي ثُـبُوتِ هَذَا الَْحدِيثِ نَظَرٌ. وَحُكْمُ الَْأطِبهاءِ عَلَيْهِ بِالْمَضَ هرةِ حُكْمٌ جُزْئِيٌّ لَيْسَ بِكُلِّيٍّ عَامٍّ، وَهُوَ بَِحسَبِ الْمَعِدَةِ الضهعِيفَةِ، وَالَْأمْزِجَةِ الضهعِيفَةِ الهتِي لََْ تَـعْتَدْهُ، وَاعْتَادَتِ الْمَأْكُولَاتِ اللهطِيفَةَ، وَهَؤُلَاءِ أَهْلُ الهرفَاهِيَةِ مِنْ أَهْلِ الْمُدُنِ، وَهُمُ الْقَلِيلُونَ مِنَ الناس.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 664, 'لَْحمُ الَْجدْيِ : قَرِيبٌ إِلَى الِاعْتِدَالِ، خَاصهةً مَا دَامَ رَضِيعًا، وَلََْ يَكُنْ قَرِيبَ الْعَهْدِ بِالْوِلَادَةِ، وَهُوَ أَسْرَعُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 665, 'هَضْمًا لِمَا فِيهِ مِنْ قُـهوةِ اللهبَِن، مُلَيٌِّن لِلطهبْعِ، مُوَافِقٌ لَِأكْ ثَرِ النهاسِ فِي أَكْثَرِ الَْأحْ وَالِ، وَهُوَ أَلْطَفُ مِنْ لَْحمِ الَْجمَلِ، وَالدهمُ الْمُتَـوَلِّدُ عَنْهُ مُعْتَدِلٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 666, 'لَْحمُ الْبَـقَرِ: بَارِدٌ يَابِسٌ ، عَسِرُ الِانِْهضَامِ، بَطِيءُ الِانِْدَْارِ، يُـوَلِّدُ دَمًا سَوْدَاوِيًّا، لَا يَصْلُحُ إِهلا لَِأهْلِ الْكَدِّ وَالتهـعَبِ الشهدِيدِ، وَيُورِثُ  إِدْمَانُهُ الَْأمْرَاضَ  السهوْدَاوِيهةَ، كَالْبَـهَقِ وَالَْجرَبِ، وَالْقُوبَاءِ وَالُْجذَامِ، وَدَاءِ الْفِيلِ، وَالسهرَطَانِ، وَالْوَسْوَاسِ ، وَحُهْى الرِّبْعِ، وَكَثِيٍر مِنَ الَْأوْرَامِ، وَهَذَا لِمَنْ لََْ يَـعْتَدْهُ، أَوْ لََْ يَدْفَعْ ضَرَرَهُ بِالْفُلْفُلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 667, 'وَالثهـوْمِ والدار صينِ، وَالهزنْبَِْيلِ وَنَوِْْهِ، وَذكََرُهُ أَقَلُّ بُـرُودَةً، وَأُنْـثَاهُ أَقَلُّ يُـبْسًا. وَلَْحمُ الْعِجْلِ وَلَا سِيهمَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 668, 'السهمِيُن مِنْ أَعْدَلِ الَْأغْذِيَةِ وَأَطْيَبِهَا وَأَلَذِّهَا وَأَحْدَِْهَا، وَهُوَ حَارٌّ رَطْبٌ ، وَإِذَا انْـهَضَمَ غَذهى غِذَاءً قَوِيًّا. لَْحمُ الفرس: ثَـبَتَ فِي «الصهحِيحِ» عَنْ أسماء رَضِيَ ا هللَُّ عَنْـهَا قَالَتْ : نَرَْْنَا فَـرَسًا فَأَكَلْنَاهُ عَلَى عَهْدِ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وسلم »7« . وَثَـبَتَ عَنْهُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ أَذِنَ فِي لُُحومِ الَْخيْلِ، وَنَـهَى عَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 669, 'لُُحومِ الُْحمُرِ أَخْ رَجَاهُ فِي «الصهحِيحَيِْن» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 670, 'وَلَا يَـثْـبُتُ عَنْهُ حَدِيثُ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ - رَضِيَ ا هللَُّ عَنْهُ- أَنههُ نَـهَى عَنْهُ. قَالَهُ أبو داود وَغَيْـرُهُ من أهل الحديث» »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 671, '(7) أخرجه البخاري في الأطعمة، ومسلم في الصيد. (2) أخرجه البخاري مسلم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 672, '(3) أخرجه أبو داود في الأطعمة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 673, 'وَاقْتَِرانُهُ بِالْبِغَالِ وَالَْحمِيِر فِي الْقُرْآنِ لَا يَدُلُّ عَلَى أَنه حُكْمَ لَْحمِهِ حُكْمُ لُُحومِهَا بِوَجْهٍ مِنَ الْوُجُوهِ، كَمَا لَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 674, 'يَدُلُّ عَلَى أَنه حُكْمَهَا فِي السههْمِ فِي الْغَنِيمَةِ حُكْمُ الْفَرَسِ ، وَا هللَُّ سُبْحَانَهُ يَـقْرِنُ فِي الذِّكْرِ بَـيَْن الْمُتَمَاثِلَاتِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 675, 'تَارَةً، وَبَـيَْن الْمُخْتَلِفَاتِ، وَبَـيَْن الْمُتَضَادهاتِ، وَلَيْسَ فِي قوله: لِتَـرْكَبُوها »7« ، مَا يَْمنَعُ مِنْ أَكْ لِهَا، كَمَا لَيْسَ فِيهِ مَا يَْمنَعُ مِنْ غَيِْر الرُّكُوبِ مِنْ وُجُوهِ الِانْتِفَاعِ ، وَإِهنَما نَصه عَلَى أَجَلِّ مَنَافِعِهَا، وَهُوَ الرُّكُوبُ ، وَالَْحدِيثَانِ فِي حِلِّهَا صَحِيحَانِ لَا مُعَارِضَ لَهمَُا، وَبَـعْدُ: فَـلَحْمُهَا حَارٌّ يَابِسٌ ، غَلِيظٌ سَوْدَاوِيٌّ مُضِرٌّ لَا يَصْلُحُ لِلْبَِْدَانِ اللهطِيفَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 676, 'لَْحمُ الَْجمَلِ: فَـرْقُ مَا بَـيَْن الهرافِضَةِ وَأَهْلِ السُّنهةِ، كَمَا أَنههُ أَحَدُ الْفُرُوقِ بَـيَْن الْيَـهُودِ وَأَهْلِ الِْإسْلَامِ. فَالْيَـهُودُ وَالهرافِضَةُ تَذُمُّهُ وَلَا تَكَُْلُهُ،؛ وَقَدْ عُلِمَ بِالِاضْطِرَارِ مِنْ دِينِ الِْإسْلَامِ حِلُّهُ، وَطَالَمَا أَكَلَهُ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ وَأَصْحَابِهِ حضرا وسفرا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 677, 'ولحم الفصيل مه مِنْ أَلَذِّ اللُّحُومِ وَأَطْيَبِهَا وَأَقْـوَاهَا غِذَاءً، وَهُوَ لِمَنِ اعْتَادَهُ بَِمنْزِلَةِ لَْحمِ الضهأْنِ لَا يَضُرُّهُمُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 678, 'الْبَـتهةَ، وَلَا يُـوَلِّدُ لَهمُْ دَاءً، وَإِهنَما ذَمههُ بَـعْضُ الَْأطِبهاءِ بِالنِّسْبَةِ إِلَى أَهْلِ الهرفَاهِيَةِ مِنْ أَهْلِ الَْحضَرِ الهذِينَ لََْ يَـعْتَادُوهُ، فَإِنه فِيهِ حَرَارَةً وَيُـبْسًا، وَتَـوْلِيدًا لِلسهوْدَاءِ، وَهُوَ عَسِرُ الِانِْهضَامِ، وَفِيهِ قُـهوةٌ غَيْـرُ مَمُُْودَةٍ، لَِأجْ لِهَا أَمَرَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بِالْوُضُوءِ مِنْ أَكْ لِهِ فِي حَدِيثَـيِْن صَحِيحَيِْن »2« لَا مُعَارِضَ لَهمَُا، وَلَا يَصِحُّ تَوَِْيلُهُمَا بِغَسْلِ الْيَدِ، لَِأنههُ خِلَافُ الْمَعْهُودِ مِنَ الْوُضُوءِ فِي كَلَامِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، لِتَـفْرِيقِهِ بَـيْـنَهُ وَبَـيَْن لَْحمِ الْغَنَمِ، فَخَيهـرَ بَـيَْن الْوُضُوءِ وَتَـرْكِهِ مِنْـهَا، وَحَتهمَ الْوُضُوءَ مِنْ لُُحومِ الِْإبِلِ. وَلَوْ حُِلَْ الْوُضُوءُ عَلَى غَسْلِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 679, 'الْيَدِ فَـقَطْ ، لَُحمِلَ عَلَى ذَلِكَ فِي قَـوْلِهِ: «مَنْ مَسه فَـرْجَهُ فَـلْيَـتَـوَضهأْ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 680, 'وَأَيْضًا: فَإِنه آكِلَهَا قَدْ لَا يُـبَاشِرُ أَكْ لَهَا بِيَدِهِ بَِأنْ يُوضَعَ في فمه، فإن كان وضؤوه غَسْلَ يَدِهِ، فَـهُوَ عَبَثٌ ، وَحَلٌْْ لِكَلَامِ الشهارعِِ عَلَى غَيِْر مَعْهُودِهِ وَعُرْفِهِ، وَلَا يَصِحُّ مُعَارَضَتُهُ بَِحدِيثِ: «كَانَ آخِرُ الَْأمْرَيْنِ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 681, 'رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ تَـرْكَ الْوُضُوءِ مِمها مست النار» لعدة أوجه:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 682, '(7) النحل- .9', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 683, '(2) أخرجه مالك وأحدْ والنسائي وابن ماجة والترمذي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 684, 'أحدها: أن هذا عام، والأ؟؟؟ بالوضوء هذا؟؟؟ خَاصٌّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 685, 'الثهانِي: أَنه الِْجهَةَ مُْختَلِفَةٌ، فَالَْأمْرُ بِالْوُضُوءِ مِنْـهَا بِِهَِةِ كَوْنَِها لَْحمَ إِبِلٍ سَوَاءٌ كَانَ نِيئًا، أَوْ مَطْبُوخًا، أَوْ قَدِيدًا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 686, 'وَلَا تَثَِْيَر لِلنهارِ فِي الْوُضُوءِ. وَأَمها تَـرْكُ الْوُضُوءِ مِمها مَسهتِ النهارُ، فَفِيهِ بَـيَانُ أَنه مَسه النهارِ لَيْسَ بِسَبَبٍ لِلْوُضُوءِ، فَأَيْنَ أَحَدُهُاَُ مِنَ الْآخَرِ؟ هَذَا فِيهِ إِثْـبَاتُ سَبَبِ الْوُضُوءِ، وَهُوَ كَوْنُهُ لَْحمَ إِبِلٍ، وَهَذَا فِيهِ نَـفْيٌ لِسَبَبِ الْوُضُوءِ، وَهُوَ كَوْنُهُ مَْمسُوسَ النهارِ، فَلَا تَـعَارُضَ بَـيْـنَـهُمَا بِوَجْهٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 687, 'الثهالِثُ : أَنه هَذَا لَيْسَ فِيهِ حِكَايَةُ لَفْظٍ عَامٍّ عَنْ صَاحِبِ الشهرْعِ ، وَإِهنَما هُوَ إِخْ بَارٌ عَنْ وَاقِعَةِ فِعْلٍ فِي أَمْرَيْنِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 688, 'أَحَدُهُاَُ: مُتَـقَدِّمٌ عَلَى الْآخَرِ، كَمَا جَاءَ ذَلِكَ مُبَـيهـنًا فِي نَـفْسِ الَْحدِيثِ ، أَنهـهُمْ قَـهربُوا إِلَى النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لَْحمًا، فَأَكَلَ، ُ مه حَضَرَتِ الصهلَاةُ، فَـتَـوَضهأَ فَصَلهى، ُ مه قَـهربُوا إِلَيْهِ فَأَكَلَ، ُ مه صَلهى، وَلََْ يَـتَـوَضهأْ، فَكَانَ آخِرُ الَْأمْرَيْنِ مِنْهُ تَـرْكَ الْوُضُوءِ مِمها مَسهتِ النهارُ، هَكَذَا جَاءَ الَْحدِيثُ ، فَاخْ تَصَرَهُ الهراوِي لِمَكَانِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 689, 'الِاسْتِدْلَالِ، فَأَيْنَ فِي هَذَا مَا يَصْلُحُ لِنَسْخِ الَْأمْرِ بِالْوُضُوءِ مِنْهُ، حَ هتى لَوْ كَانَ لَفْظًا عَامًّا مُتَأَخِّرًا مُقَاوِمًا، لََْ يَصْلُحْ لِلنهسْخِ، وَوَجَبَ تَـقْدِيُم الَْخاصِّ عَلَيْهِ، وَهَذَا فِي غَايَةِ الظُّهُورِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 690, 'لَْحمُ الضهبِّ : تَـقَدهمَ الَْحدِيثُ فِي حِلِّهِ، وَلَْحمُهُ حَارٌّ يَابِسٌ ، يُـقَوِّي شَهْوَةَ الِْجمَاعِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 691, 'لَْحمُ الْغَزَالِ: الْغَزَالُ أَصْلَحُ الصهيْدِ وَأَحْدَُْهُ لَْحمًا، وَهُوَ حَارٌّ يَابِسٌ ، وَقِيلَ: مُعْتَدِلٌ جِدًّا، نَافِعٌ لِلْبَِْدَانِ الْمُعْتَدِلَةِ الصهحِيحَةِ، وَجَيِّدُهُ الِْخشْفُ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 692, 'لَْحمُ الظهبِْ: حَارٌّ يَابِسٌ فِي الَْأوْلَى، مُفََِّفٌ لِلْبَدَنِ، صَالِحٌ لِلْبَِْدَانِ الهرطْبَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 693, 'قَالَ صَاحِبُ «الْقَانُونِ» : وَأَفْضَلُ لُُحومِ الْوَحْشِ لَْحمُ الظهبِْ مع ميله إلى السوداوية.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 694, 'لحم الأرانب: ثَـبَتَ فِي «الصهحِيحَيِْن» : عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: أَنْـفَجْ نَا أَرْنَـبًا فَسَعَوْا فِي طَلَبِهَا، فَأَخَذُوهَا، فَـبَـعَثَ أبو طلحة بِوَركِِهَا إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فَـقَبِلَهُ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 695, 'لَْحمُ الَْأرْنَبِ: مُعْتَدِلٌ إِلَى الَْحرَارَةِ وَالْيُـبُوسَةِ، وَأَطْيَـبُـهَا وَركُِهَا، وَأَحْدَُْهُ أكل', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 696, '(7) أخرجه البخاري ومسلم في الصيد.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 697, 'لَْحمِهَا مَشْوِيًّا، وَهُوَ يَـعْقِلُ الْبَطْنَ، وَيُدِرُّ الْبَـوْلَ، ويفتّت الحصى، وأكل رؤوسها ينفع من الرعشة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 698, 'لحم حاْر الوحش: ثَـبَتَ فِي «الصهحِيحَيِْن» : مِنْ حَدِيثِ أبي قتادة رَضِيَ ا هللَُّ عَنْهُ، أَنهـهُمْ كَانُوا مَعَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فِي بَـعْضِ عُمَرِهِ، وَأَنههُ صَادَ حِاَْرَ وَحْشٍ ، فَأَمَرَهُمُ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ بَِأكْ لِهِ وَكَانُوا مُرُِْمِيَن، وَلََْ يَكُنْ أَبُو قَـتَادَةَ مُرُِْمًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 699, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» : عَنْ جَابِرٍ قَالَ: أَكَلْنَا زَمَنَ خيبَ الخيل وحرْ الوحش »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 700, 'لَْحمُهُ حَارٌّ يَابِسٌ ، كَثِيُر التهـغْذِيَةِ، مُوَلِّدٌ دَمًا غَلِيظًا سَوْدَاوِيًّا، إِهلا أَنه شَحْمَهُ نَافِعٌ مَعَ دُهْنِ الْقُسْطِ لِوَجَعِ الظههْرِ وَالرِّيحِ الْغَلِيظَةِ الْمُرْخِيَةِ لِلْكُلَى، وَشَحْمُهُ جَيِّدٌ لِلْكَلَفِ طِلَاءً، وَبِالُْجمْلَةِ فَـلُحُومُ الْوُحُوشِ كُلُّهَا تُـوَلِّدُ دَمًا غَلِيظًا سَوْدَاوِيًّا، وَأَحْدَُْهُ الغزال، وبعده الأرنب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 701, 'لُُحومُ الَْأجِنهةِ: غَيْـرُ مَمُُْودَةٍ لِاحْتِقَانِ الدهمِ فِيهَا، وَلَيْسَتْ بَِحرَامٍ، لِقَوْلِهِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 702, '«ذكََاةُ الَْجنِيِن ذكََاةُ أُمِّهِ» ! »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 703, 'وَمَنَعَ أَهْلُ الْعِرَاقِ مِنْ أَكْ لِهِ إِهلا أَنْ يُدْركَِهُ حَيًّا فَـيُذَكِّيَهُ، وَأَهولُوا الَْحدِيثَ عَلَى أَنه الْمُرَادَ بِهِ أَنه ذكََاتَهُ كَذَكَاةِ أُمِّهِ. قَالُوا: فَـهُوَ حُجهةٌ عَلَى التهحْرِيِم، وَهَذَا فَاسِدٌ، فَإِنه أَهولَ الَْحدِيثِ أَنهـهُمْ سَأَلُوا رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ فَـقَالُوا: يَا رَسُولَ ا هلِلَّ! نَذْبَحُ الشهاةَ، فَـنَجِدُ فِي بَطْنِهَا جَنِينًا أَفَـنَأْكُلُهُ؟ فَـقَالَ: «كُلُوهُ إِنْ شِئْـتُمْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 704, 'فَإِنه ذكََاتَهُ ذكََاةُ أُمِّهِ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 705, 'وَأَيْضًا: فَالْقِيَاسُ يَـقْتَضِي حِلههُ، فَإِنههُ مَا دَامَ حَلًْْا فَـهُوَ جُزْءٌ مِنْ أَجْ زَاءِ الُْأمِّ، فَذَكَاتُـهَا ذكََاةٌ لَِجمِيعِ أَجْزَائِهَا، وَهَذَا هُوَ الهذِي أَشَارَ إِلَيْهِ صَاحِبُ الشهرْعِ بِقَوْلِهِ: «ذكََاتُهُ ذكََاةُ أُمِّهِ» ، كَمَا تَكُونُ ذكََاتُـهَا ذكََاةَ سَائِرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 706, 'أَجْ زَائِهَا، فَـلَوْ لََْ تَتَِْ عَنْهُ السُّنهةُ الصهرِيَحةُ بَِأكْ لِهِ، لَكَانَ الْقِيَاسُ الصهحِيحُ يقتضي حله.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 707, '(7) أخرجه ابن ماجه في الذبائح.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 708, '(2) أخرجه أبو داود وأحدْ وابن ماجه والترمذي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 709, 'لحم القديد: فِي «السُّنَنِ» : مِنْ حَدِيثِ ثَـوْبَانَ رَضِيَ ا هللَُّ عَنْهُ قَالَ: ذَبَْحتُ لِرَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ شَاةً وَنَنُْْ مُسَافِرُونَ، فَـقَالَ: «أَصْلِحْ لَْحمَهَا» فَـلَمْ أَزَلْ أُطْعِمُهُ مِنْهُ إِلَى الْمَدِينَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 710, 'الْقَدِيدُ: أَنْـفَعُ مِنَ النهمْكَسُودِ، وَيُـقَوِّي الَْأبْدَانَ، وَيُْحدِثُ حَكهةً، وَدَفْعُ ضَرَرِهِ بِالَْأبَازِيرِ الْبَارِدَةِ الهرطْبَةِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 711, 'وَيُصْلِحُ الَْأمْزِجَةَ الَْحارهةَ وَالنهمْكَسُودُ: حَارٌّ يَابِسٌ مُفََِّفٌ ، جَيِّدُهُ مِنَ السهمِيِن الهرطْبِ، يَضُرُّ بِالْقُولَنْجِ، وَدَفْعُ مَضَ هرتِهِ طَبْخُهُ بِاللهبَِن وَالدُّهْنِ، وَيَصْلُحُ لِلْمِزَاجِ الَْحارِّ الهرطْبِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ فِي لُُحومِ الطهيِْر قَالَ ا هللَُّ تَـعَالَى: وَلَْحمِ طَيٍْر مِمها يَشْتَـهُونَ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَفِي «مُسْنَدِ البزار» وَغَيِْرهِ مَرْفُوعًا «إِنهكَ لَتَـنْظُرُ إِلَى الطهيِْر فِي الَْجنهةِ، فَـتَشْتَهِيهِ، فَـيَخِرُّ مَشْوِيًّا بَـيَْن يَدَيْكَ »', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, '. »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَمِنْهُ حَلَالٌ، وَمِنْهُ حَرَامٌ. فَالَْحرَامُ: ذُو الْمِخْلَبِ، كَالصهقْرِ وَالْبَازِيِّ وَالشهاهِيِن، وَمَا كََُْلُ الِْجيَفَ كَالنهسْرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَالهرخَمِ وَاللهقْلَقِ وَالْعَقْعَقِ وَالْغُرَابِ الَْأبْـقَعِ وَالَْأسْوَدِ الْكَبِيِر، وَمَا نُِهيَ عَنْ قَـتْلِهِ كَالْهدُْهُدِ وَالصُّرَدِ، وَمَا أُمِرَ بِقَتْلِهِ كَالِْحدَأَةِ وَالْغُرَابِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَالَْحلَالُ أَصْنَافٌ كَثِيَرةٌ، فَمِنْهُ الدهجَاجُ، فَفِي «الصهحِيحَيِْن» : مِنْ حَدِيثِ أبي موسى، أَنه النهبِه صَلهى ا هللَُّ عليه وسلم أكل لحم الدّجاج »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, '(7) الواقعة- .27', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, '(2) أخرجه أبو داود ومسلم في الأضاحي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, '(3) أخرجه البخاري في الذبائح، ومسلم في الايمان.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَهُوَ حَارٌّ رَطْبٌ فِي الَْأوْلَى، خَفِيفٌ عَلَى الْمَعِدَةِ، سَرِيعُ الَْهضْمِ، جَيِّدُ الَْخلْطِ، يَزِيدُ فِي الدِّمَاغِ وَالْمَنِِِّ، وَيُصَفِّي الصهوْتَ ، وَيَُحسِّ نُ اللهوْنَ، وَيُـقَوِّي الْعَقْلَ، وَيُـوَلِّدُ دَمًا جَيِّدًا، وَهُوَ مَائِلٌ إِلَى الرُّطُوبَةِ، وَيُـقَالُ: إِنه مُدَاوَمَةَ أَكْ لِهِ تُورِثُ النِّقْرِسَ ، وَلَا يَـثْـبُتُ ذَلِكَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَلَْحمُ الدِّيكِ أَسْخَنُ مِزَاجًا، وَأَقَلُّ رُطُوبَةً، وَالْعَتِيقُ مِنْهُ دَوَاءٌ يَـنْـفَعُ الْقُولَنْجَ وَالهربْـوَ وَالرِّيَاحَ الْغَلِيظَةَ إِذَا طُبِخَ بَِماءِ الْقُرْطُمِ وَالشهبْثِ، وَخَصِ يُّـهَا مَمُُْودُ الْغِذَاءِ، سَرِيعُ الِانِْهضَامِ، وَالْفَرَارِيجُ سَرِيعَةُ الَْهضْمِ، مُلَيِّنَةٌ لِلطهبْعِ، وَالدهمُ الْمُتَـوَلِّدُ مِنْـهَا دَمٌ لَطِيفٌ جَيِّدٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'لَْحمُ الدُّرهاجِ: حَارٌّ يَابِسٌ فِي الثهانِيَةِ، خَفِيفٌ لَطِيفٌ ، سَرِيعُ الِانِْهضَامِ، مُوَلِّدٌ لِلدهمِ الْمُعْتَدِلِ، وَالِْإكْثَارُ مِنْهُ يُِحدُّ الْبَصَرَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'لَْحمُ الَْحجَلِ: يُـوَلِّدُ الدهمَ الَْجيِّدَ، سَرِيعُ الِانِْهضَامِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'لَْحمُ الإومّ: حار يابس، رديء الغذاء إذا اعتيد، ولس بِكَثِيِر الْفُضُولِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'لَْحمُ الْبَطِّ : حَارٌّ رَطْبٌ ، كَثِيُر الْفُضُولِ، عَسِرُ الِانِْهضَامِ، غَيْـرُ مُوَافِقٍ لِلْمَعِدَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'لَْحمُ الُْحبَارَى: فِي «السُّنَنِ» . مِنْ حَدِيثِ بريه بن عمر بن سفينة، عَنْ أَبِيهِ، عَنْ جَدِّهِ رَضِيَ ا هللَُّ عَنْهُ قَالَ: أَكَلْتُ مَعَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لَْحمَ حُبَارَى »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَهُوَ حَارٌّ يَابِسٌ ، عَسِرُ الِانِْهضَامِ، نَافِعٌ لَِأصْحَابِ الرِّيَاضَةِ وَالتهـعَبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'لَْحمُ الْكُرْكِيِّ: يَابِسٌ خَفِيفٌ ، وَفِي حَرِّهِ وَبَـرْدِهِ خِلَافٌ ، يُـوَلِّدُ دَمًا سَوْدَاوِيًّا، وَيَصْلُحُ لَِأصْحَابِ الْكَدِّ وَالتهـعَبِ، وَيَـنْـبَغِي أَنْ يُـتْـرَكَ بَـعْدَ ذبحه يوما أو يومين، م يؤكل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, '(7) أخرجه أبو داود والترمذي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'لَْحمُ الْعَصَافِيِر وَالْقَنَابِرِ: رَوَى النهسَائِيُّ فِي «سُنَنِهِ» : مِنْ حَدِيثِ عبد الله بن عمر رَضِيَ ا هللَُّ عَنْهُ، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَالَ: «مَا مِنْ إِنْسَانٍ يَـقْتُلُ عُصْفُورًا فَمَا فَـوْقَهُ بِغَيِْر حَقِّهِ إِهلا سَأَلَهُ ا هللَُّ عَهز وَجَله عَنْـهَا. قِيلَ: يَا رَسُولَ ا هلِلَّ! وَمَا حَقُّهُ؟ قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, '«تَذْبَُحهُ فَـتَأْكُلُهُ، وَلَا تَـقْطَعُ رَأْسَهُ وَتَـرْمِي بِهِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَفِي «سُنَنِهِ» أَيْضًا: عَنْ عمرو بن الشريد، عَنْ أَبِيهِ قَالَ: سَِمعْتُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـقُولُ: «مَنْ قَـتَلَ عُصْفُورًا عَبَـثًا، عَجه إِلَى ا هلِلَّ يَـقُولُ: يَا رَبِّ إِنه فُلَانًا قَـتَـلَنِِ عَبَـثًا، وَلََْ يَـقْتُـلْنِِ لِمَنْـفَعَةٍ» »2« . وَلَْحمُهُ حَارٌّ يَابِسٌ ، عَاقِلٌ لِلطهبِيعَةِ، يَزِيدُ فِي الْبَاهِ، وَمَرَقُهُ يُـلَيُِّن الطهبْعَ، وَيَـنْـفَعُ الْمَفَاصِلَ، وَإِذَا أُكِلَتْ أَدْمِغَتُـهَا بِالهزنْبَِْيلِ وَالْبَصَلِ، هَيهجَتْ شَهْوَةَ الِْجمَاعِ ، وَخَلْطُهَا غَيْـرُ مَمُُْودٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'لَْحمُ الَْحمَامِ: حَارٌّ رَطْبٌ ، وَحْشِيُّهُ أَقَلُّ رُطُوبَةً، وَفِرَاخُهُ أَرْطَبُ خَاصِّ يهةً، وَمَا رُبَِّي فِي الدُّورِ وَنَاهِضُهُ أَخَفُّ لَْحمًا، وَأَحْدَُْ غِذَاءً، وَلَْحمُ ذكُُورِهَا شِفَاءٌ مِنَ الِاسْتِْرخَاءِ وَالَْخدَرِ وَالسهكْ تَةِ وَالهرعْشَةِ، وَكَذَلِكَ شَمُّ رَائِحَةِ أَنْـفَاسِهَا، وَأَكْلُ فِرَاخِهَا مُعِيٌن عَلَى النِّسَاءِ، وَهُوَ جَيِّدٌ لِلْكُلَى، يَزِيدُ فِي الدهمِ، وَقَدْ رُوِيَ فِيهَا حَدِيثٌ بَاطِلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'لَا أَصْلَ لَهُ عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: إن رجلا شكى إِلَيْهِ الْوَحْدَةَ، فَـقَالَ: «اهتِخذْ زَوْجًا مِنَ الَْحمَامِ» »3« . وَأَجْ وَدُ مِنْ هَذَا الَْحدِيثُ أَنههُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ رَأَى رَجُلًا يَـتْـبَعُ حَاَْمَةً، فَـقَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, '«شَيْطَانٌ يَـتْـبَعُ شَيْطَانَةً» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'وَكَانَ عُثْمَانُ بْنُ عَهفانَ رَضِيَ ا هللَُّ عَنْهُ فِي خُطْبَتِهِ مََُْرُ بِقَتْلِ الكلاب وذبح الحمام.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, '(7) أخرجه النسائي في الصيد، وأحدْ الدارمي. (2) أخرجه أحدْ والنسائي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, '(3) أخرجه أبو داود في الأدب، وابن ماجه، وأحدْ، والبخاري في الأدب المفرد.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'لَْحمُ الْقَطَا: يَابِسٌ ، يُـوَلِّدُ السهوْدَاءَ، وَيَْحبِسُ الطهبْعَ، وَهُوَ مِنْ شَرِّ الْغِذَاءِ، إِهلا أَنههُ يَـنْـفَعُ مِنَ الِاسْتِسْقَاءِ. لَْحمُ السُّمَانََ: حَارٌّ يَابِسٌ ، يَـنْـفَعُ الْمَفَاصِلَ، وَيَضُرُّ بِالْكَبِدِ الَْحارِّ، وَدَفْعُ مَضَ هرتِهِ بِالَْخلِّ وَالْكُسْفَرَةِ، وَيَـنْـبَغِي أَنْ يُْجتَـنَبَ مِنْ لُُحومِ الطهيِْر مَا كَانَ فِي الْآجَامِ وَالْمَوَاضِعِ الْعَفِنَةِ، وَلُُحومُ الطهيِْر كُلُّهَا أَسْرَعُ انِْهضَامًا مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'الْمَوَاشِي، وَأَسْرَعُهَا انِْهضَامًا، أَقَـلُّهَا غِذَاءً، وَهِيَ الرِّقَابُ  وَالَْأجْنِحَةُ، وَأَدْمِغَتُـهَا أَحْدَُْ مِنْ أَدْمِغَةِ الْمَوَاشِي. الَْجرَادُ: فِي «الصهحِيحَيِْن» : عَنْ عَبْدِ ا هلِلَّ بْنِ أَبِي أَوْفَى قَالَ: غَزَوْنَا مَعَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'سَبْعَ غَزَوَاتٍ نَْأكُلُ الَْجرَادَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'وَفِي «الْمُسْنَدِ» عَنْهُ: «أُحِلهتْ لَنَا مَيْـتَـتَانِ وَدَمَانِ: الُْحوتُ وَالَْجرَادُ، والكبد والطحال» . يروى مرفوعا وموقوفا عى ابْنِ عُمَرَ رَضِيَ ا هللَُّ عَنْهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَهُوَ حَارٌّ يَابِسٌ ، قَلِيلُ الْغِذَاءِ وَإِدَامَةُ أَكْ لِهِ تُورِثُ الْهزَُالَ، وَإِذَا تُـبُخِّ رَ بِهِ نَـفَعَ مِنْ تَـقْطِيِر الْبَـوْلِ وَعُسْرِهِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وَخُصُوصًا لِلنِّسَاءِ، وَيُـتَـبَخهرُ بِهِ لِلْبَـوَاسِيِر، وَسَِمانُهُ يُشْوَى وَيُـؤْكَلُ لِلَسْعِ الْعَقْرَبِ، وَهُوَ ضَارٌّ لَِأصْحَابِ الصهرْعِ ، رَدِيءُ الَْخلْطِ، وَفِي إِبَاحَةِ مَيْـتَتِهِ بِلَا سَبَبٍ قَـوْلَانِ، فَالُْجمْهُورُ عَلَى حِلِّهِ، وَحَ هرمَهُ مَالِكٌ ، وَلَا خِلَافَ فِي إِبَاحَةِ مَيْـتَتِهِ إِذَا مَاتَ بسبب، كالكبس والتحريق ونوْه.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل وينبغي ألايداوم عَلَى أَكْلِ اللهحْمِ، فَإِنههُ يُورِثُ الَْأمْرَاضَ الدهمَوِيهةَ وَالِامتِلَائِيهةَ، وَالُْحمهيَاتِ الَْحادهةَ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَقَالَ عُمَرُ بْنُ الَْخطهابِ رَضِيَ ا هللَُّ عَنْهُ: إِهياكُمْ وَاللهحْمَ، فَإِنه لَهُ ضَرَاوَةً كَضَرَاوَةِ الَْخمْرِ، ذكََرَهُ مالك فِي «الْمُوَطهأِ» عَنْهُ. وَقَالَ أبقراط: لَا تَعََْلُوا أَجْ وَافَكُمْ مَقْبَـرَةً للحيوان.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'اللبن: قَالَ ا هللَُّ تَـعَالَى: وَإِنه لَكُمْ فِي الَْأنْعامِ لَعِبْـرَةً نُسْقِيكُمْ مِمها فِي بُطُونِهِ مِنْ بَـيِْن فَـرْثٍ وَدَمٍ لَبَناً خالِصاً سائِغاً لِلشهارِبِيَن »7« . وَقَالَ فِي الَْجنهةِ: فِيها أَنْهارٌ مِنْ ماءٍ غَيِْر آسِنٍ وَأَنْهارٌ مِنْ لَبٍَن لََْ يَـتَـغَيهـرْ طَعْمُهُ »2« . وَفِي «السُّنَنِ» مَرْفُوعًا: «مَنْ أَطْعَمَهُ ا هللَُّ طَعَامًا فَـلْيَـقُلْ: «اللههُمه بَارِكْ لَنَا فِيهِ، وَزِدْنَا مِنْهُ، فإنّي لا أعلم ما يجزيء مِنَ الطهعَامِ وَالشهرَابِ إِهلا اللهبََن» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'اللهبَُن: وَإِنْ كَانَ بَسِيطًا فِي الِْحسِّ ، إِهلا أَنههُ مُرَكهبٌ فِي أَصْلِ الِْخلْقَةِ تَـرْكِيبًا طَبِيعِيًّا مِنْ جَوَاهِرَ ثَلَاثَةٍ: الُْجبْنِيهةُ، وَالسهمْنِيهةُ، وَالْمَائِيهةُ، فَالُْجبْنِيهةُ: بَارِدَةٌ رَطْبَةٌ، مُغَذِّيَةٌ لِلْبَدَنِ، وَالسهمْنِيهةُ: مُعْتَدِلَةُ الَْحرَارَةِ وَالرُّطُوبَةِ مُلَائِمَةٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'لِلْبَدَنِ الِْإنْسَانِِّي الصهحِيحِ، كَثِيَرةُ الْمَنَافِعِ، وَالْمَائِيهةُ: حَارهةٌ رَطْبَةٌ، مُطْلِقَةٌ لِلطهبِيعَةِ، مُرَطِّبَةٌ لِلْبَدَنِ، وَاللهبَُن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'عَلَى الِْإطْلَاقِ أَبْـرَدُ وَأَرْطَبُ مِنَ الْمُعْتَدِلِ. وَقِيلَ: قُـهوتُهُ عِنْدَ حَلْبِهِ الَْحرَارَةُ وَالرُّطُوبَةُ. وَقِيلَ: مُعْتَدِلٌ فِي الَْحرَارَةِ وَالْبُـرُودَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَأَجْ وَدُ مَا يَكُونُ اللهبَُن حِيَن يُْحلَبُ ، ُ مه لَا يَـزَالُ تَـنْـقُصُ جَوْدَتُهُ عَلَى ممر السهاعَاتِ، فَـيَكُونُ حِيَن يُْحلَبُ أَقَله بُـرُودَةً، وَأَكْثَـرَ رُطُوبَةً، وَالَْحامِضُ بِالْعَكْسِ ، وَيُْختَارُ اللهبَُن بَـعْدَ الْوِلَادَةِ بَِأرْبَعِيَن يَـوْمًا، وَأَجْ وَدُهُ مَا اشْتَده بَـيَاضُهُ، وَطَابَ رِيُحهُ، وَلَذه طَعْمُهُ، وَكَانَ فِيهِ حَلَاوَةٌ يَسِيَرةٌ، وَدُسُومَةٌ مُعْتَدِلَةٌ، وَاعْتَدَلَ قِوَامُهُ فِي الرِّقهةِ وَالْغِلَظِ، وَحُلِبَ مِنْ حَيَـوَانٍ فَتٍِّي صَحِيحٍ، مُعْتَدِلِ اللهحْمِ، مَمُُْودِ الْمَرْعَى وَالْمَشْرَبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَهُوَ مَمُُْودٌ يُـوَلِّدُ دَمًا جَيِّدًا، وَيُـرَطِّبُ الْبَدَنَ الْيَابِسَ ، وَيَـغْذُو غِذَاءً حَسَنًا، وَيَـنْـفَعُ مِنَ الْوَسْوَاسِ وَالْغَمِّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَالَْأمْرَاضِ السهوْدَاوِيهةِ، وَإِذَا شُرِبَ مَعَ الْعَسَلِ نَـقهى الْقُرُوحَ الْبَاطِنَةَ مِنَ الَْأخْلَاطِ الْعَفِنَةِ، وَشُرْبُهُ مَعَ السُّكهرِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'يَُحسِّ نُ اللهوْنَ جِدًّا، وَالَْحلِيبُ يَـتَدَارَكُ ضَرَرَ الِْجمَاعِ ، وَيُـوَافِقُ الصهدْرَ والرئة، جيد لأصحاب السبل، رَدِيءٌ لِلهرأْسِ وَالْمَعِدَةِ، وَالْكَبِدِ وَالطِّحَالِ، وَالِْإكْ ثَارُ مِنْهُ مُضِرٌّ بِالَْأسْنَانِ وَاللِّثَةِ، وَلِذَلِكَ يَـنْـبَغِي أَنْ يُـتَمَضْمَضَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'بَـعْدَهُ بِالْمَاءِ، وَفِي «الصهحِيحَيِْن» : أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ شَرِبَ لَبَـنًا، ُ مه دَعَا بماء فتمضمض', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وقال: «إنّ له دسما» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, '(7) النحل- .11 (2) محمد- .75', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَهُوَ رَدِيءٌ لِلْمَحْمُومِيَن، وَأَصْحَابِ الصُّدَاعِ ، مُؤْذٍ لِلدِّمَاغِ ، وَالهرأْسِ الضهعِيفِ، وَالْمُدَاوَمَةُ عَلَيْهِ تُدَِْثُ ظُلْمَةَ الْبَصَرِ وَالْغِشَاءَ، وَوَجَعَ الْمَفَاصِلِ، وَسُدهةَ الْكَبِدِ، وَالنهـفْخَ فِي الْمَعِدَةِ وَالَْأحْشَاءِ وَإِصْلَاحُهُ بِالْعَسَلِ وَالهزنْبَِْيلِ الْمُرَهبَ وَنَوِْْهِ، وَهَذَا كُلُّهُ لِمَنْ لََْ يَـعْتَدْهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'لبن الضأن: أَغْلَظُ الَْألْبَانِ وَأَرْطَبُـهَا، وَفِيهِ مِنَ الدُّسُومَةِ وَالزُّهُومَةِ مَا لَيْسَ فِي لَبَِن الْمَاعِزِ وَالْبَـقَرِ، يُـوَلِّدُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'فُضُولًا بَـلْغَمِ يًّا، وَيُْحدِثُ فِي الِْجلْدِ بَـيَاضًا إِذَا أُدْمِنَ اسْتِعْمَالُهُ، وَلِذَلِكَ يَـنْـبَغِي أَنْ يُشَابَ هَذَا اللهبَُن بِالْمَاءِ لِيَكُونَ مَا نَالَ الْبَدَنَ مِنْهُ أَقَله، وَتَسْكِينُهُ لِلْعَطَشِ أَسْرَعَ، وَتَـبِْيَدُهُ أَكْ ثَـرَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'لَبَُن الْمَعْزِ: لَطِيفٌ مُعْتَدِلٌ، مُطْلِقٌ لِلْبَطْنِ، مُرَطِّبٌ لِلْبَدَنِ الْيَابِسِ ، نَافِعٌ مِنْ قُـرُوحِ الَْحلْقِ، وَالسُّعَالِ الْيَابِسِ ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَنَـفْثِ الدهمِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَاللهبَُن الْمُطْلَقُ أَنْـفَعُ الْمَشْرُوبَاتِ لِلْبَدَنِ الِْإنْسَانِِّي لِمَا اجْتَمَعَ فِيهِ مِنَ التهـغْذِيَةِ وَالدهمَوِيهةِ، وَلِاعْتِيَادِهِ حَالَ الطُّفُولِيهةِ، وَمُوَافَـقَتِهِ لِلْفِطْرَةِ الَْأصْلِيهةِ، وَفِي «الصهحِيحَيِْن» : أَنه رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أُتَِي لَيْـلَةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'أُسْرِيَ بِهِ بِقَدَحٍ مِنْ خَْمرٍ، وَقَدَحٍ مِنْ لَبٍَن، فَـنَظَرَ إِلَيْهِمَا، ُ مه أَخَذَ اللهبََن، فَـقَالَ جِبِْيَلُ: الَْحمْدُ هِلِلَّ الهذِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'هَدَاكَ لِلْفِطْرَةِ، لَوْ أَخَذْتَ الَْخمْرَ، غَوَتْ أُمهتُكَ » . وَالَْحامِضُ مِنْهُ بَطِيءُ الِاسْتِمْرَاءِ، خَامُ الِْخلْطِ، وَالْمَعِدَةُ الحارة تهضمه وتنتفع به.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'لَبَُن الْبَـقَرِ: يَـغْذُو الْبَدَنَ، وَيَُخصِّبُهُ، وَيُطْلِقُ الْبَطْنَ بِاعْتِدَالٍ، وَهُوَ مِنْ أَعْدَلِ الَْألْبَانِ وَأَفْضَلِهَا بَـيَْن لبن الضأن، ولبن المعز في الرقة واللظ وَالدهسَمِ، وَفِي السُّنَنِ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'مِنْ حَدِيثِ عَبْدِ ا هلِلَّ بْنِ مَسْعُودٍ يَـرْفَـعُهُ: عَلَيْكُمْ بَِألْبَانِ الْبَـقَرِ، فَإِنهـهَا تَـرُمُّ مِنْ كُلِّ الشهجَرِ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'لَبَُن الِْإبِلِ: تَـقَدهمَ ذِكْرُهُ فِي أَهولِ الْفَصْلِ، وَذِكْرُ مَنَافِعِهِ، فَلَا حاجة لإعادته. (7) ليس في السنن، بل هو في المستدرك.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'لبان: هُوَ الْكُنْدُرُ: قَدْ وَرَدَ فِيهِ عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «خَِرُِّوا بُـيُوتَكُمْ بِاللُّبَانِ وَالصهعْتَِر» : وَلَا يَصِحُّ عَنْهُ، وَلَكِنْ يُـرْوَى عَنْ علي أَنههُ قَالَ لِرَجُلٍ شَكَا إِلَيْهِ النِّسْيَانَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'عَلَيْكَ بِاللُّبَانِ، فَإِنههُ يُشَجِّ عُ الْقَلْبَ ، وَيَذْهَبُ بِالنِّسْيَانِ. وَيُذْكَرُ عَنِ ابْنِ عَبهاسٍ رَضِيَ ا هللَُّ عَنْـهُمَا أَنه شُرْبَهُ مَعَ السُّكهرِ عَلَى الرِّيقِ جَيِّدٌ لِلْبَـوْلِ وَالنِّسْيَانِ. وَيُذْكَرُ عَنْ أنس رَضِيَ ا هللَُّ عَنْهُ، أَنههُ شَكَا إِلَيْهِ رَجُلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'النِّسْيَانَ، فَـقَالَ: عَلَيْكَ بِالْكُنْدُرِ وَانْـقَعْهُ مِنَ اللهيْلِ، فَإِذَا أَصْبَحْتَ ، فَخُذْ مِنْهُ شَرْبَةً عَلَى الرِّيقِ، فَإِنههُ جَيِّدٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'لِلنِّسْيَانِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَلَِهذَا سَبَبٌ طَبِيعِيٌّ ظَاهِرٌ، فَإِنه النِّسْيَانَ إِذَا كَانَ لِسُوءِ مِزَاجٍ بَارِدٍ رَطْبٍ يَـغْلِبُ عَلَى الدِّمَاغِ ، فَلَا يَْحفَظُ مَا يَـنْطَبِعُ فِيهِ، نَـفَعَ مِنْهُ اللُّبَانُ، وَأَمها إِذَا كَانَ النِّسْيَانُ لِغَلَبَةِ شَيْ ءٍ عَارِضٍ ، أَمْكَنَ زَوَالُهُ سَرِيعًا بِالْمُرَطِّبَاتِ. وَالْفَرْقُ بَـيْـنَـهُمَا أَنه الْيُـبُوسِيه يَـتْـبَـعُهُ سَهَرٌ، وَحِفْظُ الُْأمُورِ الْمَاضِيَةِ دُونَ الَْحالِيهةِ، وَالرُّطُوبُِّي بِالْعَكْسِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'وَقَدْ يُْحدِثُ النِّسْيَانَ أَشْيَاءَ بِالَْخاصِّ يهةِ، كَحِجَامَةِ نُـقْرَةِ الْقَفَا، وَإِدْمَانِ أَكْلِ الْكُسْفَرَةِ الهرطْبَةِ، وَالتُّـهفاحِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'الَْحامِضِ ، وَكَثْـرَةِ الَْهمِّ وَالْغَمِّ، وَالنهظَرِ فِي الْمَاءِ الْوَاقِفِ ، وَالْبَـوْلِ فِيهِ، وَالنهظَرِ إِلَى الْمَصْ لُوبِ، وَالِْإكْ ثَارِ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'قِرَاءَةِ أَلْوَاحِ الْقُبُورِ، وَالْمَشْيِ بَـيَْن جَلَََيِْن مَقْطُورَيْنِ، وَإِلْقَاءِ الْقَمْلِ فِي الِْحيَاضِ وَأَكْلِ سُؤْرِ الْفَأْرِ، وَأَكْ ثُـرُ هَذَا مَعْرُوفٌ بِالتهجْرِبَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَالْمَقْصُودُ: أَنه اللُّبَانَ مُسَخِّ نٌ فِي الدهرَجَةِ الثهانِيَةِ، وَمُفََِّفٌ فِي الُْأولَى، وَفِيهِ قَـبْضٌ يَسِيٌر، وَهُوَ كَثِيُر الْمَنَافِعِ، قَلِيلُ الْمَضَارِّ، فَمِنْ مَنَافِعِهِ: أَنْ يَـنْـفَعَ مِنْ قَذْفِ الدهمِ وَنَـزْفِهِ، وَوَجَعِ الْمَعِدَةِ، وَاسْتِطْلَاقِ الْبَطْنِ، وَيَـهْضِمُ الطهعَامَ، وَيَطْرُدُ الرِّيَاحَ، وَيَْجلُو قُـرُوحَ الْعَيِْن، وَيُـنْبِتُ اللهحْمَ فِي سَائِرِ الْقُرُوحِ، وَيُـقَوِّي الْمَعِدَةَ الضهعِيفَةَ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وَيُسَخِّ نُـهَا، وَيَُجفِّفُ الْبَـلْغَمَ، وَيُـنَشِّ فُ رُطُوبَاتِ الصهدْرِ، وَيَْجلُو ظُلْمَةَ الْبَصَرِ، وَيَْمنَعُ الْقُرُوحَ الَْخبِيثَةَ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 35, 'الِانْتِشَارِ، وَإِذَا مُضِغَ وَحْدَهُ، أَوْ مَعَ الصهعْتَِر الْفَارِسِيِّ جَلَبَ الْبَـلْغَمَ، وَنَـفَعَ مِنِ اعْتِقَالِ اللِّسَانِ، وَيَزِيدُ فِي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 36, 'الذِّهْنِ وَيُذَكِّيهِ، وَإِنْ خُِرَِّ بِهِ مَاءٌ، نَـفَعَ مِنَ الْوَبَاءِ، وَطَيهبَ رَائِحَةَ الَْهوَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 37, 'حَرْفُ الْمِيمِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 38, 'مَاءٌ: مَادهةُ الَْحيَاةِ، وَسَيِّدُ الشهرَابِ، وَأَحَدُ أَرْكَانِ الْعَالََِ، بَلْ ركُْنُهُ الَْأصْلِيُّ، فَإِنه السهمَاوَاتِ خُلِقَتْ مِنْ خُاَِرِهِ، وَالَْأرْضَ مِنْ زَبَدِهِ، وَقَدْ جَعَلَ ا هللَُّ مِنْهُ كُله شَيْ ءٍ حَيٍّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 39, 'وَقَدِ اخْتُلِفَ فِيهِ: هَلْ يَـغْذُو، أَوْ يُـنْفِذُ الْغِذَاءَ فَـقَطْ ؟ عَلَى قَـوْلَيِْن، وَقَدْ تَـقَدهمَا، وَذكََرْنَا الْقَوْلَ الهراجِحَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 40, 'وَدَلِيلَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 41, 'وَهُوَ بَارِدٌ رَطْبٌ ، يَـقْمَعُ الَْحرَارَةَ، وَيَْحفَظُ عَلَى الْبَدَنِ رُطُوبَاتِهِ، وَيَـرُدُّ عَلَيْهِ بَدَلَ مَا تَلََهلَ مِنْهُ، وَيُـرَقِّقُ الْغِذَاءَ وَيُـنْفِذُهُ فِي الْعُرُوقِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 42, 'وَتُـعْتَـبَـرُ جَوْدَةُ الْمَاءِ مِنْ عَشَرَةِ طُرُقٍ: أَحَدُهَا: مِنْ لَوْنِهِ بَِأنْ يَكُونَ صَافِيًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 43, 'الثهانِي: مِنْ رَائِحَتِهِ بَِأنْ لَا تَكُونَ لَهُ رَائِحَةٌ الْبَـتهةَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 44, 'الثهالِثُ : مِنْ طَعْمِهِ بَِأنْ يَكُونَ عَذْبَ الطهعْمِ حُلْوَهُ، كَمَاءِ النِّيلِ وَالْفُرَاتِ. الهرابِعُ: مِنْ وَزْنِهِ بَِأنْ يَكُونَ خَفِيفًا رَقِيقَ الْقِوَامِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 45, 'الَْخامِسُ : مِنْ مَرََْاهُ، بَِأنْ يَكُونَ طَيِّبَ الْمَجْ رَى والمسلك.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 46, 'السادس: مَنْـبَعِهِ بَِأنْ يَكُونَ بَعِيدَ الْمَنْـبَعِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 47, 'السهابِعُ: مِنْ بُـرُوزِهِ لِلشهمْسِ وَالرِّيحِ،! بَِأنْ لَا يَكُونَ مُْختَفِيًا تَتََْ الَْأرْضِ ، فَلَا تَـتَمَكهنُ الشهمْسُ وَالرِّيحُ مِنْ قُصَارَتِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 48, 'الثهامِنُ: مِنْ حَرَكَتِهِ بَِأنْ يَكُونَ سَرِيعَ الَْجرْيِ وَالَْحرَكَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 49, 'التهاسِعُ: مِنْ كَثْـرَتِهِ بَِأنْ يَكُونَ لَهُ كَثْـرَةٌ يَدْفَعُ الْفَضَلَاتِ الْمُخَالِطَةَ لَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 50, 'الْعَاشِرُ: مِنْ مَصَبِّهِ بَِأنْ يَكُونَ آخِذًا مِنَ الشهمَالِ إِلَى الَْجنُوبِ، أَوْ مِنَ الْمَغْرِبِ إِلَى الْمَشْرِقِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 51, 'وَإِذَا اعْتَـبَـرْتَ هَذِهِ الَْأوْصَافَ . لََْ تَِدَْهَا بِكَمَالَِها إِهلا فِي الَْأنْـهَارِ الَْأرْبَـعَةِ: النِّيلِ، وَالْفُرَاتِ، وَسَيْحُونَ، وَجَيْحُونَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 52, 'وَفِي «الصهحِيحَيِْن» : مِنْ حَدِيثِ أَبِي هُرَيْـرَةَ رَضِيَ ا هللَُّ عَنْهُ قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «سَيْحَانُ، وَجَيْحَانُ، وَالنِّيلُ، وَالْفُرَاتُ ، كُلٌّ مِنْ أَنْـهَارِ الَْجنهةِ» »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 53, 'وَتُـعْتَـبَـرُ خِهفةُ الْمَاءِ مِنْ ثَلَاثَةِ أَوْجُهٍ، أَحَدُهَا: سُرْعَةُ قَـبُولِهِ لِلْحَرِّ وَالْبَـرْدِ. قَالَ أبقراط: الْمَاءُ الهذِي يَسْخُنُ سَرِيعًا، وَيَـبْـرُدُ سَرِيعًا أَخَفُّ الْمِيَاهِ. الثهانِي: بِالْمِيزَانِ، الثهالِثُ : أَنْ تُـبَله قُطْنَـتَانِ مُتَسَاوِيَـتَا الْوَزْنِ بَِماءَيْنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 54, 'مُْختَلِفَيِْن، ُ مه يَُجهففَا بَالِغًا، ُ مه تُوزَنَا، فَأَيهـتُـهُمَا كَانَتْ أَخَفه ، فَمَاؤُهَا كَذَلِكَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 55, 'وَالْمَاءُ وَإِنْ كَانَ فِي الَْأصْلِ بَارِدًا رَطْبًا، فَإِنه قُـهوتَهُ تَـنْـتَقِلُ وَتَـتَـغَيهـرُ لَِأسْبَابٍ عَارِضَةٍ تُوجِبُ انْتِقَالََها، فَإِنه الْمَاءَ الْمَكْشُوفَ لِلشِّ مَالِ الْمَسْتُورَ عَنِ الِْجهَاتِ الُْأخَرِ يَكُونُ بَارِدًا، وَفِيهِ يُـبْسٌ مُكْتَسَبٌ مِنْ رِيحِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 56, 'الشهمَالِ، وَكَذَلِكَ الُْحكْمُ عَلَى سَائِرِ الِْجهَاتِ الُْأخَرِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 57, 'وَالْمَاءُ الهذِي يَـنْـبُعُ مِنَ الْمَعَادِنِ يَكُونُ عَلَى طَبِيعَةِ ذَلِكَ الْمَعْدِنِ، وَيُـؤَثِّرُ فِي الْبَدَنِ تَثَِْيَرهُ، وَالْمَاءُ الْعَذْبُ نَافِعٌ لِلْمَرْضَى وَالَْأصِحهاءِ، وَالْبَارِدُ مِنْهُ أَنْـفَعُ وَأَلَذُّ، وَلَا يَـنْـبَغِي شُرْبُهُ عَلَى الرِّيقِ، وَلَا عَقِيبَ الِْجمَاعِ ، وَلَا الِانْتِبَاهِ مِنَ النهـوْمِ، وَلَا عَقِيبَ الَْحمهامِ، وَلَا عَقِيبَ أَكْلِ الْفَاكِهَةِ، وَقَدْ تَـقَدهمَ. وَأَمها عَلَى الطهعَامِ، فَلَا بَْأسَ بِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 58, 'إِذَا اضْطُهر إِلَيْهِ، بَلْ يَـتَـعَهيُن وَلَا يُكْثِرُ مِنْهُ، بَلْ يَـتَمَصهصُهُ مَصًّا، فَإِنههُ لَا يَضُرُّهُ الْبَـتهةَ، بَلْ يُـقَوِّي الْمَعِدَةَ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 59, 'وَيُـنْهِضُ الشههْوَةَ، وَيُزِيلُ الْعَطَشَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 60, 'وَالْمَاءُ الْفَاتِرُ يَـنْـفُخُ وَيَـفْعَلُ ضِده مَا ذكََرْنَاهُ، وَبَائِتُهُ أَجْ وَدُ مِنْ طَرِيِّهِ وَقَدْ تَـقَدهمَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 61, 'وَالْبَارِدُ يَـنْـفَعُ مِنْ دَاخِلٍ أَكْثَـرَ مِنْ نَـفْعِهِ مِنْ خَارِجٍ، وَالَْحارُّ بِالْعَكْسِ ، وَيَـنْـفَعُ الْبَارِدُ مِنْ عُفُونَةِ الدهمِ، وَصُعُودِ الَْأخِْرَِةِ إِلَى الهرأْسِ ، وَيَدْفَعُ الْعُفُونَاتِ، وَيُـوَافِقُ الَْأمْزِجَةَ وَالَْأسْنَانَ وَالَْأزْمَانَ وَالَْأمَاكِنَ الَْحارهةَ، وَيَضُرُّ عَلَى كُلِّ حَالَةٍ تَتََْاجُ إِلَى نُضْجٍ وتلَيل،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 62, '(7) أخرجه مسلم في الجنة وصفة نعيمها، وليس في البخاري.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 63, 'كَالزُّكَامِ وَالَْأوْرَامِ، وَالشهدِيدُ الْبُـرُودَةِ مِنْهُ يُـؤْذِي الَْأسْنَانَ، وَالِْإدْمَانُ عَلَيْهِ يُْحدِثُ انْفِجَارَ الدهمِ وَالنهـزَلَاتِ، وَأَوْجَاعَ الصهدْرِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 64, 'وَالْبَارِدُ وَالَْحارُّ بِِإفْـرَاطٍ ضَارهانِ لِلْعَصَبِ وَلَِأكْ ثَرِ الَْأعْضَاءِ، لَِأنه أَحَدَهُاَُ مُلَُِّلٌ، وَالْآخَرُ مُكَثِّفٌ ، وَالْمَاءُ الَْحارُّ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 65, 'يُسَكِّنُ لَذْعَ الَْأخْلَاطِ الَْحادهةِ، وَيَُحلِّلُ وَيُـنْضِجُ، وَيُْخرجُِ الْفُضُولَ، وَيُـرَطِّبُ وَيُسَخِّ نُ، وَيُـفْسِدُ الَْهضْمَ شُرْبُهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 66, 'ويطفوا الطعام إِلَى أَعْلَى الْمَعِدَةِ وَيُـرْخِيهَا، وَلَا يُسْرعُِ فِي تسكين العطش، ويذبل البدن، ويؤذي إِلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 67, 'أَمْرَاضٍ رَدِيئَةٍ وَيَضُرُّ فِي أَكْثَرِ الَْأمْرَاضِ عَلَى أَنههُ صَالِحٌ لِلشُّيُوخِ، وَأَصْحَابِ الصهرْعِ ، وَالصُّدَاعِ الْبَارِدِ وَالهرمَدِ. وَأَنْـفَعُ مَا اسْتُـعْمِلَ مِنْ خَارِجٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 68, 'ولا ظيصحّ فِي الْمَاءِ الْمُسَخهنِ بِالشهمْسِ حَدِيثٌ وَلَا أَثَـرٌ، وَلَا كَرِهَهُ أَحَدٌ مِنْ قُدَمَاءِ الَْأطِبهاءِ، وَلَا عَابُوهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 69, 'وَالشهدِيدُ السُّخُونَةِ يُذِيبُ شَحْمَ الْكُلَى، وَقَدْ تَـقَدهمَ الْكَلَامُ عَلَى مَاءِ الَْأمْطَارِ فِي حَرْفِ الْعَيِْن.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 70, 'مَاءٌ الثهـلْجِ وَالْبَـرَدِ: ثَـبَتَ فِي «الصهحِيحَيِْن» : عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ كان يدعو في الاستفتاح وغيره: «الّهمّ اغْسِلْنِِ مِنْ خَطَايَايَ بَِماءِ الثهـلْجِ وَالْبَـرَدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 71, 'الثهـلْجُ لَهُ فِي نَـفْسِهِ كَيْفِيهةٌ حَادهةٌ دُخهانِيهةٌ، فَمَاؤُهُ كَذَلِكَ ، وَقَدْ تَـقَدهمَ وَجْ هُ الِْحكْمَةِ فِي طَلَبِ الْغَسْلِ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 72, 'الَْخطَايَا بَِمائِهِ لِمَا يَْحتَاجُ إِلَيْهِ الْقَلْبُ مِنَ التهـبِْيَدِ وَالتهصْلِيبِ وَالتهـقْوِيَةِ، وَيُسْتَـفَادُ مِنْ هَذَا أَصْلُ طِبِّ الَْأبْدَانِ وَالْقُلُوبِ، وَمُعَالََجةِ أَدْوَائِهَا بِضِدِّهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 73, 'وَمَاءُ الْبَـرَدِ أَلْطَفُ وَأَلَذُّ مِنْ مَاءِ الثهـلْجِ، وَأَمها مَاءُ الَْجمْدِ وَهُوَ الَْجلِيدُ، فَبِحَسَبِ أَصْلِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 74, 'وَالثهـلْجُ يَكْتَسِبُ كَيْفِيهةَ الِْجبَالِ وَالَْأرْضِ الهتِي يَسْقُطُ عَلَيْـهَا فِي الَْجوْدَةِ وَالهردَاءَةِ، وَيَـنْـبَغِي تَنََُّبُ شُرْبِ الْمَاءِ الْمَثْـلُوجِ عَقِيبَ الَْحمهامِ وَالِْجمَاعِ ، وَالرِّيَاضَةِ وَالطهعَامِ الَْحارِّ، وَلَِأصْحَابِ السُّعَالِ وَوَجَعِ الصهدْرِ، وَضَعْفِ الْكَبِدِ، وَأَصْحَابِ الَْأمْزِجَةِ الْبَارِدَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 75, 'ماء الآبار والقنِ: مِيَاهُ الْآبَارِ قَلِيلَةُ اللهطَافَةِ، وَمَاءُ الْقُنِِِّ الْمَدْفُونَةِ تتَ الأرض', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 76, 'ثَقِيلٌ، لَِأنه أَحَدَهُاَُ مُتَُْقِنٌ لَا يَْخلُو عَنْ تَـعَفُّنٍ، وَالْآخَرَ مَجُُْوبٌ عَنِ الَْهوَاءِ، وَيَـنْـبَغِي أَهلا يُشْرَبَ عَلَى الْفَوْرِ حَ هتى يُصْمَدَ لِلْهَوَاءِ وَتَتََِْي عَلَيْهِ لَيْـلَةٌ، وَأَرْدَؤُهُ مَا كَانَتْ مَاََرِيهِ مِنْ رَصَاصٍ ، أَوْ كَانَتْ بِئْـرُهُ مُعَطهلَةً، وَلَا سِيهمَا إِذَا كَانَتْ تُـرْبَـتُـهَا رَدِيئَةً، فَـهَذَا الْمَاءُ وَبِيءٌ وخيم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 77, 'ماء زمزم: سَيِّدُ الْمِيَاهِ وَأَشْرَفُـهَا وَأَجَلُّهَا قَدْرًا، وَأَحَبُّـهَا إِلَى النفوس وأغلاها تنَا وَأَنْـفَسُهَا عِنْدَ النهاسِ ، وَهُوَ هَزْمَةُ جِبِْيَلَ وَسُقْيَا ا هلِلَّ إِسَْماعِيلَ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 78, 'وَثَـبَتَ فِي «الصهحِيحِ» : عَنْ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، أَنههُ قَالَ لأبي ذر وَقَدْ أَقَامَ بَـيَْن الْكَعْبَةِ وَأَسْتَارِهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 79, 'أَرْبَعِيَن مَا بَـيَْن يَـوْمٍ وَلَيْـلَةٍ، لَيْسَ لَهُ طَعَامٌ غَيْـرَهُ؛ فَـقَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إِنهـهَا طَعَامُ طُعْمٍ »2«', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 80, '.. وَزَادَ غَيْـرُ مسلم بِِإسْنَادِهِ: وَشِفَاءُ سُقْمٍ »3« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 81, 'وَفِي «سُنَنِ ابْنِ مَاجَهْ» . مِنْ حَدِيثِ جَابِرِ بْنِ عَبْدِ ا هلِلَّ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 82, '«مَاءُ زَمْزَمَ لِمَا شُرِبَ لَهُ» »4« . وَقَدْ ضَعهفَ هَذَا الَْحدِيثَ طَائِفَةٌ بعبد الله بن المؤمل رَاوِيهِ عَنْ مُمَُهدِ بْنِ الْمُنْكَدِرِ وَقَدْ رُوِّينَا عَنْ عَبْدِ ا هلِلَّ بْنِ الْمُبَارَكِ أَنههُ لَمها حَجه، أَتَى زَمْزَمَ فَـقَالَ: اللههُمه إِنه ابن أبي الموالِ حَدهثَـنَا عَنْ مُمَُهدِ بْنِ الْمُنْكَدِرِ، عَنْ جابر رَضِيَ ا هللَُّ عَنْهُ، عَنْ نَبِيِّكَ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «مَاءُ زَمْزَمَ لِمَا شُرِبَ لَهُ» ، وَإِنِّي أَشْرَبَهُ لِظَمَأِ يَـوْمِ الْقِيَامَةِ، وابن أبي الموالِ ثِقَةٌ، فَالَْحدِيثُ إِذًا حَسَنٌ وَقَدْ صَحهحَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 83, 'بَـعْضُهُمْ، وَجَعَلَهُ بَـعْضُهُمْ مَوْضُوعًا، وَكِلَا الْقَوْلَيِْن فِيهِ مُاََزَفَةٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 84, 'وَقَدْ جَ هربْتُ أَنَا وَغَيِْري مِنَ الِاسْتِشْفَاءِ بَِماءِ زَمْزَمَ أُمُورًا عَجِيبَةً، وَاسْتَشْفَيْتُ بِهِ مِنْ عِدهةِ أَمْرَاضٍ ، فَـبَـرَأْتُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 85, 'بِِإذْنِ ا هلِلَّ، وَشَاهَدْتُ مَنْ يَـتَـغَذهى بِهِ الَْأهيامَ ذَوَاتِ الْعَدَدِ قَرِيبًا مِنْ نِصْفِ الشههْرِ، أَوْ أَكْثَـرَ، وَلَا يَِجدُ جُوعًا،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 86, 'وَيَطُوفُ مَعَ النهاسِ كَأَحَدِهِمْ، وَأَخْبَـرَنِي أَنههُ رُهبَما بَقِيَ عَلَيْهِ أَرْبَعِيَن يَـوْمًا، وَكَانَ لَهُ قُـهوةً يَُجامِعُ بَِها أَهْلَهُ، وَيَصُومُ ويطوف مرارا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 87, '(7) أخرجه الدارقطنِ، والحاكم.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 88, '(2) أخرجه مسلم في فضائل الصحابة. (3) أخرجه البزار والبيهقي والطيالسي. (4) أخرجه ابن ماجة وأحدْ والبيهقي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 89, 'ماء النيل: أَحَدُ أَنْـهَارِ الَْجنهةِ أَصْلُهُ مِنْ وَرَاءِ جِبَالِ الْقَمَرِ فِي أَقْصَى بِلَادِ الَْحبَشَةِ مِنْ أَمْطَارٍ تَتََْمِعُ هُنَاكَ، وَسُيُولٍ يَُمدُّ بَـعْضُهَا بَـعْضًا، فَـيَسُوقُهُ ا هللَُّ تَـعَالَى إِلَى الَْأرْضِ الُْجرُزِ الهتِي لَا نَـبَاتَ لَهاَ، فَـيُخْ رِجُ بِهِ زَرْعًا، تَكَُْلُ مِنْهُ الَْأنْـعَامُ وَالَْأنَامُ، وَلَمها كَانَتِ الَْأرْضُ الهتِي يَسُوقُهُ إِلَيْـهَا إِبْلِيزًا صُلْبَةً، إِنْ أُمْطِرَتْ مَطَرَ الْعَادَةِ، لََْ تُـرْوَ، وَلََْ تَـتَـهَيهأْ لِلنهـبَاتِ، وَإِنْ أُمْطِرَتْ فَـوْقَ الْعَادَةِ، ضَ هرتِ الْمَسَاكِنَ وَالسهاكِنَ، وَعَطهلَتِ الْمَعَايِشَ وَالْمَصَالِحَ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 90, 'فَأَمْطَرَ الْبِلَادَ الْبَعِيدَةَ، ُ مه سَاقَ تِلْكَ الَْأمْطَارَ إِلَى هَذِهِ الَْأرْضِ فِي نَـهْرٍ عَظِيمٍ، وَجَعَلَ سُبْحَانَهُ زِيَادَتَهُ فِي أَوْقَاتٍ مَعْلُومَةٍ عَلَى قَدْرِ رَيِّ الْبِلَادِ وَكِفَايَتِهَا، فَإِذَا أَرْوَى الْبِلَادَ وَعَمههَا، أَذِنَ سُبْحَانَهُ بِتَـنَاقُصِهِ وَهُبُوطِهِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 91, 'لِتَتِمه الْمَصْلَحَةُ بِالتهمَكُّنِ مِنَ الهزرْعِ ، وَاجْتَمَعَ فِي هَذَا الْمَاءِ الُْأمُورُ الْعَشْرَةُ الهتِي تَـقَدهمَ ذِكْ رُهَا، وَكَانَ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 92, 'أَلْطَفِ الْمِيَاهِ وَأَخَفِّهَا وَأَعْذَبَِها وَأَحْلَاهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 93, 'مَاءُ الْبَحْرِ: ثَـبَتَ عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ فِي الْبَحْرِ: «هُوَ الطههُورُ مَاؤُهُ الِْحلُّ مَيْـتَـتُهُ» . وَقَدْ جَعَلَهُ ا هللَُّ سُبْحَانَهُ مِلْحًا أُجَاجًا مُرًّا زُعَاقًا لِتَمَامِ مَصَالِحِ مَنْ هُوَ عَلَى وَجْهِ الَْأرْضِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 94, 'مِنَ الْآدَمِيِّيَن وَالْبَـهَائِمِ، فَإِنههُ دَائِمٌ رَاكِدٌ كَثِيُر الَْحيَـوَانِ، وَهُوَ يَُموتُ فِيهِ كَثِيًرا وَلَا يُـقْبَـرُ، فَـلَوْ كَانَ حُلْوًا لََأنْـتََُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 95, 'مِنْ إِقَامَتِهِ وَمَوْتِ حَيَـوَانَاتِهِ فِيهِ وَأَجَافَ ، وَكَانَ الَْهوَاءُ الْمُحِيطُ بِالْعَالََِ يَكْتَسِبُ مِنْهُ ذَلِكَ ، وَيَـنْـتُُُ وَيُِجيفُ ، فَـيَـفْسُدُ الْعَالََُ، فَاقْـتَضَتْ حِكْمَةُ الهربِّ سُبْحَانَهُ وَتَـعَالَى أَنْ جَعَلَهُ كَالْمَ هلاحَةِ الهتِي لَوْ أُلْقِيَ فيه حيف الْعَالَِِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 96, 'كُلُّهَا وَأَنْـتَانُهُ وَأَمْوَاتُهُ لََْ تُـغَيِّْرهُ شَيْـئًا، وَلَا يَـتَـغَيهـرُ عَلَى مُكْ ثِهِ مِنْ حِيِن خُلِقَ وَإِلَى أَنْ يَطْوِيَ ا هللَُّ الْعَالَََ، فَـهَذَا هُوَ السهبَبُ الْغَائِيُّ الْمُوجِبُ لِمُلُوحَتِهِ. وَأَمها الْفَاعِلِيُّ، فَكَوْنُ أرضه سبخة الحة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 97, 'وَبَـعْدُ فَالِاغْتِسَالُ بِهِ نَافِعٌ مِنْ آفَاتٍ عَدِيدَةٍ فِي ظَاهِرِ الِْجلْدِ، وَشُرْبُهُ مُضِرٌّ بِدَاخِلِهِ وَخَارِجِهِ، فَإِنههُ يُطْلِقُ الْبَطْنَ، وَيُـهْزِلُ، وَيُْحدِثُ حَكهةً وَجَرَبًا، وَنَـفْخًا وَعَطَشًا، وَمَنِ اضْطُهر إِلَى شُرْبِهِ فَـلَهُ طُرُقٌ مِنَ الْعِلَاجِ يَدْفَعُ بَِها مَضَ هرتَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 98, 'مِنْـهَا: أَنْ يُْجعَلَ فِي قِدْرٍ، وَيُْجعَلَ فَـوْقَ الْقِدْرِ قَصَبَاتٌ وَعَلَيْـهَا صُوفٌ جَدِيدٌ مَنْـفُوشٌ ، وَيُوقَدَ تَتََْ القدر حتى يرتفع خاِرها إلى الصوفج فَإِذَا كَثُـرَ عَصَرَهُ، وَلَا يَـزَالُ يَـفْعَلُ ذَلِكَ حَ هتى يَْجتَمِعَ لَهُ مَا يُرِيدُ، فَـيَحْصُلُ فِي الصُّوفِ مِنَ الْبُخَارِ مَا عَذُبَ وَيَـبْـقَى فِي القدر الزّعاق.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 99, 'وَمِنْـهَا: أَنْ يُْحفَرَ عَلَى شَاطِئِهِ حُفْرَةٌ وَاسِعَةٌ يُـرَشهحُ مَاؤُهُ، إِلَيْـهَا، ُ مه إِلَى جَانِبِهَا قَرِيبًا مِنْـهَا أُخْ رَى تُـرَشِّحُ هِيَ إِلَيْـهَا، ُ مه ثَلَِثَةٌ إِلَى أَنْ يَـعْذُبَ الْمَاءُ. وَإِذَا أَلَْجأَتْهُ الضهرُورَةُ إِلَى شُرْبِ الْمَاءِ الْكَدِرِ فَعِلَاجُهُ أَنْ يُـلْقِيَ فِيهِ نَـوَى الْمِشْمِشِ ، أَوْ قِطْعَةً مِنْ خَشَبِ السهاجِ، أَوْ جَرًَْا مُلْتَهِبًا يُطْفَأُ فِيهِ، أَوْ طِينًا أَرْمَنِيًّا، أَوْ سَوِيقَ حِنْطَةٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 100, 'فَإِنه كُدْرَتَهُ ترسب إلى أسفل.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 101, 'مسك: ثَـبَتَ فِي صَحِيحِ مسلم، عَنْ أَبِي سَعِيدٍ الُْخدْرِيِّ رَضِيَ ا هللَُّ عَنْهُ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ أَنههُ قَالَ: «أَطْيَبُ الطِّيبِ الْمِسْكُ » »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 102, 'وَفِي «الصهحِيحَيِْن» : عَنْ عائشة رَضِيَ ا هللَُّ عَنْـهَا: كُنْتُ أُطَيِّبُ النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ قَـبْلَ أَنْ يُْحرِمَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 103, 'وَيَـوْمَ النهحْرِ قَـبْلَ أَنْ يَطُوفَ بِالْبَـيْتِ بِطِيبٍ فِيهِ مِسْكٌ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 104, 'الْمِسْكُ : مَلِكُ أَنْـوَاعِ الطِّيبِ، وَأَشْرَفُـهَا وَأَطْيَـبُـهَا، وَهُوَ الهذِي تُضْرَبُ بِهِ الَْأمْثَالُ، وَيُشَبههُ بِهِ غَيْـرُهُ، وَلَا يُشَبههُ بِغَيِْرهِ، وَهُوَ كُثْـبَانُ الَْجنهةِ، وَهُوَ حَارٌّ يَابِسٌ فِي الثهانِيَةِ، يَسُرُّ النهـفْسَ وَيُـقَوِّيهَا، وَيُـقَوِّي الأعضاء الباطنة جيَعها شربا وشّما وَيُـقَوِّي الَْأعْضَاءَ الْبَاطِنَةَ جَِيَعَهَا شُرْبًا وَشَمها وَالظهاهِرَةَ إِذَا وُضِعَ عَلَيْـهَا. نَافِعٌ لِلْمَشَايِخِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 105, 'وَالْمَبْـرُودِينَ، لَا سِيهمَا زَمَنَ  الشِّ تَاءِ جَيِّدٌ لِلْغَشْ يِ  وَالَْخفَقَانِ، وَضَعْفِ القوة بإنعاشه للحرارة الغريزية، ويجلو بيام العين، وينشف رطوبتها، وظيفشّ الرِّيَاحَ مِنْـهَا وَمِنْ جَِيَعِ الَْأعْضَاءِ، وَيُـبْطِلُ عَمَلَ السمومج وينفع من نهش الأفاعي، ومنافعه كثيرة جداج وهو من أقوى المفرّحات.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 106, 'مرزنوْش: وَرَدَ فِيهِ حَدِيثٌ لَا نَـعْلَمُ صِحهتَهُ: «عَلَيْكُمْ بِالْمَرْزَنْوُْشِ ، فَإِنههُ جَيِّدٌ لِلْخُشَامِ» »3« وَالُْخشَامُ: الزُّكَامُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 107, 'وَهُوَ حَارٌّ فِي الثهالِثَةِ يَابِسٌ فِي الثهانِيَةِ، يَـنْـفَعُ شَُّمهُ مِنَ الصُّدَاعِ الْبَارِدِ وَالْكَائِنِ عَنِ الْبَـلْغَمِ، وَالسهوْدَاءِ وَالزُّكَامِ، وَالرِّيَاحِ الْغَلِيظَةِ، وَيَـفْتَحُ السُّدَدَ الَْحادِثَةَ في الرأس', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 108, '(7) أخرجه مسلم في الألفاظ. (2) أخرجه البخاري في الحج.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 109, '(3) ذكره السيوطي في الجامع الصغير، ونسبه لابن السنِ وأبي نعيم في الطب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 110, 'وَالْمَنْخِرَيْنِ، وَيَُحلِّلُ أَكْ ثَـرَ الَْأوْرَامِ الْبَارِدَةِ، فَـيَـنْـفَعُ مِنْ أَكْ ثَرِ الَْأوْرَامِ وَالَْأوْجَاعِ الْبَارِدَةِ الهرطْبَةِ، وَإِذَا احْتُمِلَ، أَدَره الطهمْثَ ، وَأَعَانَ عَلَى الَْحبَلِ، وَإِذَا دُقه وَرَقُهُ الْيَابِسُ ، وَكُمِدَ بِهِ، أَذْهَبَ آثَرََ الدهمِ الْعَارِضِ تَتََْ الْعَيِْن، وَإِذَا ضُمِّدَ بِهِ مَعَ الَْخلِّ، نَـفَعَ لَسْعَةَ الْعَقْرَبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 111, 'وَدُهْنُهُ نَافِعٌ لِوَجَعِ الظههْرِ وَالرُّكْ بَـتَـيِْن، وَيُذْهِبُ بِالِْإعْيَاءِ، وَمَنْ أَدْمَنَ شَمههُ لََْ يَـنْزِلْ فِي عَيْـنَـيْهِ الْمَاءُ، وَإِذَا اسْتُعِطَ بَِمائِهِ مَعَ دُهْنِ اللهوْزِ الْمُرِّ، فَـتَحَ سُدَدَ الْمَنْخِرَيْنِ، وَنَـفَعَ مِنَ الرِّيحِ الْعَارِضَةِ فِيهَا وَفِي الرأس.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 112, 'ملح: رَوَى ابْنُ مَاجَهْ فِي «سُنَنِهِ» : مِنْ حَدِيثِ أَنَسٍ يَـرْفَـعُهُ: «سَيِّدُ إِدَامِكُمُ الْمِلْحُ» »7« وَسَيِّدُ الشهيْ ءِ: هُوَ الهذِي يُصْلِحُهُ، وَيَـقُومُ عَلَيْهِ، وَغَالِبُ الِْإدَامِ إِهنَما يَصْلُحُ بِالْمِلْحِ، وَفِي «مُسْنَدِ البزار» مَرْفُوعًا: سيوشك أن تكونوا في الناس مثل ال الْمِلْحِ فِي الطهعَامِ، «وَلَا يَصْلُحُ الطهعَامُ إِهلا بِالْمِلْحِ» »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 113, 'وَذكََرَ البغوي فِي «تَـفْسِيِرهِ» : عَنْ عبد الله بن عمر رَضِيَ ا هللَُّ عَنْـهُمَا مَرْفُوعًا:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 114, '«إِنه ا هللََّ أَنْـزَلَ أَرْبَعَ بَـرَكَاتٍ مِنَ السهمَاءِ إِلَى الَْأرْضِ : الَْحدِيدَ، وَالنهارَ، وَالْمَاءَ، وَالْمِلْحَ» .. وَالْمَوْقُوفُ أَشْبَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 115, 'الْمِلْحُ يُصْلِحُ أَجْسَامَ النهاسِ وَأَطْعِمَتَـهُمْ، وَيُصْلِحُ كُله شَيْ ءٍ يَُخالِطُهُ حَ هتى الذههَبَ وَالْفِضهةَ، وَذَلِكَ أَنه فِيهِ قُـهوةً تَزِيدُ الذههَبَ صُفْرَةً، وَالْفِضهةَ بَـيَاضًا، وَفِيهِ جِلَاءٌ وَتَلَِْيلٌ، وَإِذْهَابٌ لِلرُّطُوبَاتِ الْغَلِيظَةِ، وَتَـنْشِيفٌ لََها،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 116, 'وَتَـقْوِيَةٌ لِلْبَِْدَانِ، وَمَنْعٌ مِنْ عُفُونَتِهَا وَفَسَادِهَا وَنَـفْعٌ مِنَ الَْجرَبِ الْمُتَـقَرِّحِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 117, 'وَإِذَا اكْ تُحِلَ بِهِ، قَـلَعَ اللهحْمَ الهزائِدَ مِنَ الْعَيِْن، وَمَقََُ الظهفَرَةَ وَالَْأنْدَرَانُِّي أَبْـلَغُ فِي ذَلِكَ ، وَيَْمنَعُ الْقُرُوحَ الَْخبِيثَةَ مِنَ الِانْتِشَارِ، وَيُْحدِرُ الْبِاََزَ، وَإِذَا دُلِكَ به بطون', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 118, '(7) أخرجه ابن ماجة في الأطعمة. (2) رواه البزار والطباَني.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 119, 'أَصْحَابِ الِاسْتِسْقَاءِ نَـفَعَهُمْ، وَيُـنَـقِّي الَْأسْنَانَ، وَيَدْفَعُ عَنْـهَا الْعُفُونَةَ، وَيَشُدُّ اللهثَةَ وَيُـقَوِّيهَا، وَمَنَافِعُهُ كَثِيَرةٌ جِدًّا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 120, 'حَرْفُ النُّونِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 121, 'نَلٌُْ: مَذْكُورٌ فِي الْقُرْآنِ فِي غَيِْر مَوْضِ عٍ، وَفِي «الصهحِيحَيِْن» : عَنِ ابْنِ عُمَرَ رَضِيَ ا هللَُّ عَنْـهُمَا، قَالَ: بَـيْـنَا نَنُْْ عِنْدَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، إذ أُتَِي بِمُِهارِ نَلَُْةٍ، فَـقَالَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «إِنه مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 122, 'الشهجَرِ شَجَرَةً مَثَـلُهَا مَثَلُ الهرجُلِ الْمُسْلِمِ لَا يَسْقُطُ وَرَقُـهَا، أَخْ بِوَُنِي مَا هِيَ؟ فَـوَقَعَ النهاسُ فِي شَجَرِ ِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 123, 'الْبَـوَادِي، فَـوَقَعَ فِي نَـفْسِي أَنهـهَا النهخْلَةُ، فَأَرَدْتُ أَنْ أَقُولَ: هِيَ النهخْلَةُ، ُ مه نَظَرْتُ فَإِذَا أَنَا أَصْغُرُ الْقَوْم سِنًّا فَسَكَتُّ، فَـقَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «هِيَ النهخْلَةُ» ، فَذَكَرْتُ ذَلِكَ لعمر، فَـقَالَ: لََأنْ تَكُونَ قُـلْتَـهَا أَحَبُّ إِلَهِ مِنْ كَذَا وَكَذَا »7« ..', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 124, 'فَفِي هَذَا الَْحدِيثِ إِلْقَاءُ الْعَالَِِ الْمَسَائِلَ عَلَى أَصْحَابِهِ، وَتَرَِْينُـهُمْ، وَاخْ تِبَارُ مَا عِنْدَهُمْ. وَفِيهِ ضَرْبُ الَْأمْثَالِ وَالتهشْبِيهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 125, 'وَفِيهِ مَا كَانَ عَلَيْهِ الصهحَابَةُ مِنَ الَْحيَاءِ مِنْ أَكَابِرِهِمْ وَإِجْلَالِِهمْ وَإِمْسَاكِهِمْ عَنِ الْكَلَامِ بَـيَْن أَيْدِيهِمْ. وَفِيهِ فَـرَحُ الهرجُلِ بِِإصَابَةِ وَلَدِهِ، وَتَـوْفِيقِهِ لِلصهوَابِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 126, 'وَفِيهِ أَنههُ لَا يُكْ رَهُ لِلْوَلَدِ أَنْ يُِجيبَ بَِما يَـعْرِفُ بَِحضْرَةِ أَبِيهِ، وَإِنْ لََْ يَـعْرِفْهُ الَْأبُ ، وَلَيْسَ فِي ذَلِكَ إِسَاءَةُ أَدَبٍ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 127, 'عَلَيْهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 128, 'وَفِيهِ مَا تَضَمهنَهُ تَشْبِيهُ الْمُسْلِمِ بِالنهخْلَةِ مِنْ كَثْـرَةِ خَيِْرهَا وَدَوَامِ ظِلِّهَا، وَطِيبِ ثَرََِهَا، وَوُجُودِهِ على الدوام.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 129, '(7) أخرجه البخاري في الأطعمة، ومسلم في صفات المنافقين.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 130, 'وَثَرََُهَا يُـؤْكَلُ رَطْبًا وَيَابِسًا، وَبَـلَحًا وَيَانِعًا، وَهُوَ غِذَاءٌ وَدَوَاءٌ وَقُوتٌ وَحَلْوَى، وَشَرَابٌ وَفَاكِهَةٌ، وَجُذُوعُهَا لِلْبِنَاءِ وَالْآلَاتِ وَالَْأوَانِي، وَيُـتهخَذُ مِنْ خُوصِ هَا الُْحصُرُ وَالْمَكَاتِلُ وَالَْأوَانِي وَالْمَرَاوحُِ، وَغَيْـرُ ذَلِكَ ، وَمِنْ لِيفِهَا الِْحبَالُ وَالَْحشَايَا وَغَيْـرُهَا، ُ مه آخِرُ شَيْ ءٍ نَـوَاهَا عَلَفٌ لِلِْبِْلِ، وَيَدْخُلُ فِي الَْأدْوِيَةِ وَالَْأكْحَالِ، ُ مه جَاََلُ ثَرَََتَِها', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 131, 'وَنَـبَاتَِها وَحُسْنُ هَيْـئَتِهَا، وَبَـهْجَةُ مَنْظَرِهَا، وَحُسْنُ نَضْدِ ثَرََِهَا، وَصَنْـعَتِهِ وَبَـهْجَتُهُ، وَمَسَ هرةُ النُّـفُوسِ عِنْدَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 132, 'رُؤْيَتِهِ، فَـرُؤْيَـتُـهَا مُذَكِّرَةٌ لِفَاطِرِهَا وَخَالِقِهَا، وَبَدِيعِ صَنْـعَتِهِ، وَكَمَالِ قُدْرَتِهِ، وَتَاََمِ حِكْمَتِهِ، وَلَا شَيْ ءَ أَشْبَهُ بَِها مِنَ الهرجُلِ الْمُؤْمِنِ، إِذْ هُوَ خَيْـرٌ كُلُّهُ، وَنَـفْعٌ ظَاهِرٌ وَبَاطِنٌ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 133, 'وَهِيَ الشهجَرَةُ الهتِي حَنه جِذْعُهَا إِلَى رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لَمها فَارَقَهُ شَوْقًا إِلَى قُـرْبِهِ، وَسََماعِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 134, 'كَلَامِهِ، وَهِيَ الهتِي نَـزَلَتْ تَتََْـهَا مريم لَمها وَلَدَتْ عِيسَى عَلَيْهِ السهلَامُ، وَقَدْ وَرَدَ فِي حَدِيثٍ فِي إِسْنَادِهِ نَظَرٌ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 135, 'أَكْرِمُوا عمّاتكم النهخْلَةَ، فَإِنهـهَا خُلِقَتْ مِنَ الطِّيِن الهذِي خُلِقَ مِنْهُ آدَمُ». » .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 136, 'وَقَدِ اخْ تَـلَفَ النهاسُ فِي تَـفْضِيلِهَا عَلَى الَْحبَـلَةِ أَوْ بِالْعَكْسِ عَلَى قَـوْلَيِْن، وَقَدْ قَـرَنَ ا هللَُّ بَـيْـنَـهُمَا فِي كِتَابِهِ فِي غَيِْر مَوْضِ عٍ، وَمَا أَقْـرَبَ أَحَدِهِاَُ مِنْ صَاحِبِهِ، وَإِنْ كَانَ كُلُّ وَاحِدٍ مِنْـهُمَا فِي مَلَُِّ سُلْطَانِهِ وَمَنْـبَتِهِ، وَالَْأرْضِ الهتِي تُـوَافِقُهُ أَفْضَلَ وَأَنْـفَعَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 137, 'نَـرْجِسُ : فِيهِ حَدِيثٌ لَا يَصِحُّ: «عَلَيْكُمْ بِشَمِّ النهـرْجِسِ فَإِنه فِي الْقَلْبِ حَبهةَ الُْجنُونِ وَالُْجذَامِ وَالْبَـرَصِ ، لَا يَـقْطَعُهَا إِهلا شَمُّ النهـرْجِسِ » »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 138, 'وَهُوَ حَارٌّ يَابِسٌ فِي الثهانِيَةِ، وَأَصْلُهُ يُدْمِلُ الْقُرُوحَ الْغَائِرَةَ إِلَى الْعَصَبِ، وَلَهُ قُـهوةُ غُسَالَةٍ جَالِيَةٌ جَابِذَةٌ، وَإِذَا طُبِخَ وَشُرِبَ مَاؤُهُ، أَوْ أُكِلَ مَسْلُوقًا، هَيهجَ الْقَيْ ءَ، وَجَذَبَ الرُّطُوبَةَ مِنْ قَـعْرِ الْمَعِدَةِ، وَإِذَا طُبِخَ مَعَ الْكِرْسِنهةِ وَالْعَسَلِ، نَـقهى أَوْسَاخَ القروح، وفجر الدّبيلات العسرة النضج.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 139, '(7) حديث موضوع.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 140, '(2) أخرجه ابن ماجه في الأدب.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 141, 'وَزَهْرُهُ مُعْتَدِلُ الَْحرَارَةِ، لَطِيفٌ يَـنْـفَعُ الزُّكَامَ الْبَارِدَ، وَفِيهِ تَلَِْيلٌ قَوِيٌّ، وَيَـفْتَحُ سُدَدَ الدِّمَاغِ وَالْمَنْخِرَيْنِ، وينفع من الصّداع الرطب والسّوداوي، ويصدع الرؤوس الَْحارهةَ، وَالْمُحَ هرقُ مِنْهُ إِذَا شُقه بَصَلُهُ صَلِيبًا، وَغُرِسَ ، صَارَ مُضَاعَفًا، وَمَنْ أَدْمَنَ شَمههُ فِي الشِّ تَاءِ أَمِنَ مِنَ الْبِْسََامِ فِي الصهيْفِ، وَيَـنْـفَعُ مِنْ أَوْجَاعِ الهرأْسِ الْكَائِنَةِ مِنَ الْبَـلْغَمِ وَالْمِ هرةِ السهوْدَاءِ، وَفِيهِ مِنَ الْعِطْرِيهةِ مَا يُـقَوِّي الْقَلْبَ وَالدِّمَاغَ، وَيَـنْـفَعُ مِنْ كَثِيٍر مِنْ أَمْرَاضِهَا. وَقَالَ صَاحِبُ التهـيْسِيِر: شَُّمهُ يُذْهِبُ بِصَرْعِ الصِّ بْـيَانِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 142, 'نُورَةٌ: رَوَى ابْنُ مَاجَهْ: مِنْ حَدِيثِ أم سلمة رَضِيَ ا هللَُّ عَنْـهَا، أَنه النهبِه صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، كَانَ إِذَا اطهلَى بَدَأَ بِعَوْرَتِهِ، فَطَلَاهَا بِالنُّورَةِ، وَسَائِرَ جَسَدِهِ أَهْلُهُ، وَقَدْ وَرَدَ فِيهَا عِدهةُ أَحَادِيثَ هَذَا أَمْثَـلُهَا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 143, 'قِيلَ: إِنه أَهولَ مَنْ دَخَلَ الَْحمهامَ، وَصُنِعَتْ لَهُ النُّورَةُ، سليمان ابن داود، وأصلها: كلس جزآن، وَزِرْنِيخٌ جُزْءٌ، يُْخلَطَانِ بِالْمَاءِ، وَيُـتْـرَكَانِ فِي الشهمْسِ أَوِ الَْحمهامِ بِقَدْرِ مَا تَـنْضَجُ، وَتَشْتَدُّ زُرْقَـتُهُ، ُ مه يُطْلَى بِهِ، وَيَْجلِسُ سَاعَةً رَيْـثَمَا يَـعْمَلُ، وَلَا يَُمسُّ بَِماءٍ، ُ مه يُـغْسَلُ، وَيُطْلَى مَكَانُـهَا بالحناء لإذهاب ناريتها.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 144, 'نبق: فكر أبو نعيم فِي كِتَابِهِ «الطِّبِّ النهـبَوِيِّ » : مَرْفُوعًا: «إِنه آدَمَ لَمها أُهْبِطَ إِلَى الَْأرْضِ كَانَ أَهولَ شَيْ ءٍ أَكَلَ مِنْ ثِاََرِهَا النهـبْقُ» . وَقَدْ ذكََرَ النهبُِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ النهـبْقَ فِي الَْحدِيثِ الْمُتهـفَقِ عَلَى صِحهتِهِ: أَنههُ رَأَى سدة الْمُنْـتَـهَى لَيْـلَةَ أُسْرِيَ بِهِ، وَإِذَا نَـبْـقُهَا مِثْلَ قِلَالِ هَجَرَ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 145, 'وَالنهـبْقُ ثَرََُ شَجَرِ السِّ دْرِ يُـعْقِلُ الطهبِيعَةَ، وَيَـنْـفَعُ مِنَ الِْإسْهَالِ، وَيَدْبُغُ الْمَعِدَةَ، وَيُسَكِّنُ الصهفْرَاءَ، وَيَـغْذُو الْبَدَنَ، وَيُشَهِّي الطهعَامَ، وَيُـوَلِّدُ بَـلْغَمًا، وَيَـنْـفَعُ الذهرَبَ ، الصهفْرَاوِيه، وَهُوَ بَطِيءُ الَْهضْمِ، وَسَوِيقُهُ يُـقَوِّي', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 146, 'الَْحشَا، وَهُوَ يُصْلِحُ الَْأمْزِجَةَ الصهفْرَاوِيهةَ، وَتُدْفَعُ مَضَ هرتُهُ بِالشههْدِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 147, 'وَاخْتُلِفَ فِيهِ، هَلْ هُوَ رَطْبٌ أَوْ يَابِسٌ ؟ عَلَى قَـوْلَيِْن. وَالصهحِيحُ: أَنه رَطْبُهُ بارد رطب، ويابسه بارد يابس.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 148, '(7) أخرجه البخاري في بدء الخلق.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 149, 'حَرْفُ الَْهاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 150, 'هِنْدَبَا: وَرَدَ فِيهَا ثَلَاثَةُ أَحَادِيثَ لَا تَصِحُّ عَنْ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: وَلَا يَـثْـبُتُ مِثْـلُهَا، بَلْ هِيَ مَوْضُوعَةٌ أَحَدُهَا: «كُلُوا الِْهنْدَبَاءَ وَلَا تَـنْـفُضُوهُ فَإِنههُ لَيْسَ يَـوْمٌ مِنَ الَْأهيامِ إِهلا وَقَطَرَاتٌ مِنَ الَْجنهةِ تَـقْطُرُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 151, 'عَلَيْهِ» الثهانِي: مَنْ أَكَلَ الِْهنْدَبَاءَ، ُ مه نَامَ عَلَيْـهَا لََْ يَُحله فِيهِ سُمٌّ وَلَا سِحْرٌ» . الثهالِثُ : «مَا مِنْ وَرَقَةٍ مِنْ وَرَقِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 152, 'الِْهنْدَبَاءِ إِهلا وَعَلَيْـهَا قَطْرَةٌ مِنَ الَْجنهةِ» ]7[ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 153, 'وَبَـعْدُ فَهِيَ مُسْتَحِيلَةُ الْمِزَاجِ، مُنْـقَلِبَةٌ بِانْقِلَابِ فُصُولِ السهنَةِ، فَهِيَ فِي الشِّ تَاءِ بَارِدَةٌ رَطْبَةٌ، وَفِي الصهيْفِ حَارهةٌ يَابِسَةٌ وَفِي الهربِيعِ وَالَْخرِيفِ مُعْتَدِلَةٌ، وفي غالب أَحْ وَالَُها تَيَِلُ إِلَى الْبُـرُودَةِ وَالْيُـبْسِ ، وَهِيَ قَابِضَةٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 154, 'مُبَـهردَةٌ، جَيِّدَةٌ لِلْمَعِدَةِ، وَإِذَا طُبِخَتْ وَأُكِلَتْ خِلٍَِّ، عَقَلَتِ الْبَطْنَ وَخَاصهةً الْبَـرِّيُّ مِنْـهَا، فَهِيَ أَجْ وَدُ لِلْمَعِدَةِ، وَأَشَدُّ قَـبْضًا، وَتَـنْـفَعُ مِنْ ضَعْفِهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 155, 'وَإِذَا تُضُمِّدَ بَِها، سَلَبَتِ الِالْتِهَابَ الْعَارِضَ فِي الْمَعِدَةِ، وَتَـنْـفَعُ مِنَ النِّقْرِسِ ، وَمِنْ أَوْرَامِ الْعَيِْن الَْحارهةِ، وَإِذَا تُضُمِّدَ بِوَرَقِهَا وَأُصُولَِها، نَـفَعَتْ مِنْ لَسْعِ الْعَقْرَبِ، وَهِيَ تُـقَوِّي الْمَعِدَةَ، وَتَـفْتَحُ السُّدَدَ الْعَارِضَةَ في الكيد، وَتَـنْـفَعُ مِنْ أَوْجَاعِهَا حَارُّهَا وَبَارِدُهَا، وَتَـفْتَحُ سُدَدَ الطِّحَالِ وَالْعُرُوقِ وَالَْأحْشَاءِ، وَتُـنَـقِّي مَاََرِيَ الْكُلَى. وَأَنْـفَعُهَا لِلْكَبِدِ أَمَرُّهَا، وَمَاؤُهَا الْمُعْتَصَرُ يَـنْـفَعُ مِنَ الْيَـرَقَانِ السُّدَدِيِّ ، وَلَا سِيهمَا إِذَا خُلِطَ بِهِ مَاءُ الرازيانج', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 156, 'الرئب، وَإِذَا دُقه وَرَقُـهَا، وَوُضِعَ عَلَى الَْأوْرَامِ الَْحارهةِ برّدها وحلّلها، ويجلو ما في المعدة، ويطفىء حَرَارَةَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 157, 'الدهمِ وَالصهفْرَاءَ، وَأَصْلَحُ مَا أُكِلَتْ غَيْـرَ مَغْسُولَةٍ وَلَا مَنْـفُوضَةٍ، لَِأنهـهَا مَتَى غُسِلَتْ أَوْ نُفِضَتْ ، فَارَقَـتْـهَا قُـهوتُـهَا، وَفِيهَا مَعَ ذَلِكَ قُـهوةٌ تِرْيَاقِيهةٌ تَـنْـفَعُ مِنْ جَِيَعِ السُّمُومِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 158, 'وَإِذَا اكْ تُحِلَ بَِمائِهَا، نَـفَعَ مِنَ الْعَشَا، وَيَدْخُلُ وَرَقُـهَا فِي التِّْريَاقِ، وَيَـنْـفَعُ مِنْ لَدْغِ الْعَقْرَبِ، وَيُـقَاوِمُ أَكْثَـرَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 159, 'السُّمُومِ، وَإِذَا اعْتُصِرَ مَاؤُهَا، وَصُبه عَلَيْهِ الهزيْتُ ، خَلهصَ مِنَ الَْأدْوِيَةِ الْقَتهالَةِ، وَإِذَا اعْتُصِرَ أَصْلُهَا، وشرب', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 160, 'مَاؤُهُ، نَـفَعَ مِنْ لَسْعِ الَْأفَاعِي، وَلَسْعِ الْعَقْرَبِ، وَلَسْعِ الزُّنْـبُورِ، وَلَبَُن أَصْلِهَا يَْجلُو بَـيَاضَ الْعَيِْن. حَرْفُ الْوَاوِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 161, 'وَرْسٌ : ذكََرَ الترمذي فِي «جَامِعِهِ» : مِنْ حَدِيثِ زَيْدِ بْنِ أَرْقَمَ، عَنِ النهبِِّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، أَنههُ كَانَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 162, 'يَـنْـعَتُ الهزيْتَ وَالْوَرْسَ مِنْ ذَاتِ الَْجنْبِ، قَالَ قَـتَادَةُ: يُـلَدُّ بِهِ، وَيُـلَدُّ مِنَ الَْجانِبِ الهذِي يَشْتَكِيهِ »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 163, 'وَرَوَى ابْنُ مَاجَهْ فِي «سُنَنِهِ» مِنْ حَدِيثِ زَيْدِ بْنِ أَرْقَمَ أَيْضًا، قَالَ: نَـعَتَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ مِنْ ذَاتِ الَْجنْبِ وَرْسًا وَقُسْطًا وَزَيْـتًا يُـلَدُّ بِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 164, 'وَصَحه عَنْ أم سلمة رَضِيَ ا هللَُّ عَنْـهَا قَالَتْ : كَانَتِ النُّـفَسَاءُ تَـقْعُدُ بَـعْدَ نِفَاسِهَا أَرْبَعِيَن يَـوْمًا، وَكَانَتْ إِحْدَانَا تَطْلِي الْوَرْسَ عَلَى وَجْ هِهَا مِنَ الْكَلَفِ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 165, 'قَالَ أبو حنيفة اللغوي: الْوَرْسُ يُـزْرعَُ زَرْعًا، وَلَيْسَ بِبَـرِّيٍّ ، وَلَسْتُ أَعْرِفُهُ بِغَيِْر أَرْضِ الْعَرَبِ، وَلَا مِنْ أَرْضِ الْعَرَبِ بِغَيِْر بِلَادِ الْيَمَنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 166, 'وَقُـهوتُهُ فِي الَْحرَارَةِ وَالْيُـبُوسَةِ فِي أَهولِ الدهرَجَةِ الثهانِيَةِ، وَأَجْ وَدُهُ الَْأحْرَُْ اللهيُِّن فِي الْيَدِ، الْقَلِيلُ النُّخَالَةِ، يَـنْـفَعُ مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 167, 'الْكَلَفِ، وَالَْحكهةِ، وَالْبُـثُورِ، الْكَائِنَةِ فِي سَطْحِ الْبَدَنِ إِذَا طُلِيَ بِهِ، وَلَهُ قُـهوةٌ قَابِضَةٌ صَابِغَةٌ، وَإِذَا شُرِبَ نَـفَعَ مِنَ الْوَضَحِ، وَمِقْدَارُ الشهرْبَةِ مِنْهُ وَزْنُ دِرْهَمٍ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 168, 'وَهُوَ فِي مِزَاجِهِ وَمَنَافِعِهِ قَرِيبٌ مِنْ مَنَافِعِ الْقُسْطِ الْبَحْرِيِّ ، وَإِذَا لُطِّخَ بِهِ عَلَى الْبَـهَقِ وَالَْحكهةِ وَالْبُـثُورِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 169, 'وَالسهفْعَةِ نَـفَعَ مِنْـهَا، وَالثهـوْبُ الْمَصْبُوغُ بالورس يقوي على الباه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 170, '(7) أخرجه الترمذي في الطب، وابن ماجة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 171, '(2) أخرجه أحدْ في المسند، وأبو داود والترمذي والدارقطنِ، والحاكم والبيهقي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 172, 'وسمة: هِيَ وَرَقُ النِّيلِ، وَهِيَ تُسَوِّدُ الشهعْرَ، وَقَدْ تَـقَدهمَ قَرِيبًا ذِكْ رُ الِْخلَافِ فِي جَوَازِ الصهبْغِ بالسواد ومن فعله.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 173, 'حَرْفُ الْيَاءِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 174, 'يَـقْطِيٌن: وَهُوَ الدُّهباءُ وَالْقَرْعُ، وَإِنْ كَانَ الْيَـقْطِيُن أَعَمه، فَإِنههُ فِي اللُّغَةِ: كُلُّ شَجَرٍ لَا تَـقُومُ عَلَى سَاقُ ، كَالْبِطِّيخِ، وَالْقِثهاءِ وَالِْخيَارِ، قَالَ ا هللَُّ تَـعَالَى: وَأَنْـبَـتْنا عَلَيْهِ شَجَرَةً مِنْ يَـقْطِيٍن »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 175, 'فَإِنْ قِيلَ: مَا لَا يَـقُومُ عَلَى سَاقٍ يُسَمهى نَمًْْا لَا شَجَرًا، وَالشهجَرُ: مَا لَهُ سَاقٌ ، قَالَهُ أَهْلُ اللُّغَةِ: فَكَيْفَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 176, 'قَالَ: شَجَرَةً مِنْ يَـقْطِيٍن »7« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 177, 'فَالَْجوَابُ : أَنه الشهجَرَ إِذَا أُطْلِقَ، كَانَ مَا لَهُ سَاقٌ يَـقُومُ عَلَيْهِ، وَإِذَا قُـيِّدَ بِشَيْ ءٍ تَـقَيهدَ بِهِ، فَالْفَرْقُ بَـيَْن الْمُطْلَقِ وَالْمُقَيهدِ فِي الَْأسَْماءِ بَابٌ مُهِمٌّ عَظِيمُ النهـفْعِ فِي الْفَهْمِ، وَمَرَاتِبِ اللُّغَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 178, 'وَالْيَـقْطِيُن الْمَذْكُورُ فِي الْقُرْآنِ: هُوَ نَـبَاتُ الدُّهباءِ، وَثَرََُهُ يُسَمهى الدُّهباءَ وَالْقَرْعَ، وَشَجَرَةَ الْيَـقْطِيِن. وَقَدْ ثَـبَتَ فِي «الصهحِيحَيِْن» : مِنْ حَدِيثِ أَنَسِ بْنِ مَالِكٍ ، أَنه خَيهاطًا دَعَا رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ لِطَعَامٍ صَنَـعَهُ، قَالَ أنس رَضِيَ ا هللَُّ عَنْهُ: فَذَهَبْتُ مَعَ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَـقَهربَ إِلَيْهِ خُبْـزًا مِنْ شَعِيٍر، وَمَرَقًا فِيهِ دُ هباءٌ وَقَدِيدٌ، قَالَ أنس: فَـرَأَيْتُ رَسُولَ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ يَـتَـتَـبهعُ الدُّهباءَ مِنْ حَوَالَِِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 179, 'الصهحْفَةِ، فَـلَمْ أَزَلْ أُحِبُّ الدُّهباءَ مِنْ ذَلِكَ الْيَـوْمِ »2« .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 180, 'وَقَالَ أبو طالوت دَخَلْتُ عَلَى أَنَسِ بْنِ مَالِكٍ رَضِيَ ا هللَُّ عَنْهُ، وَهُوَ كََُْلُ الْقَرْعَ، وَيَـقُولُ: يَا لَكِ مِنْ شَجَرَةٍ مَا أَحَبهكِ إِلَهِ لُِحبِّ رَسُولِ ا هلِلَّ صَلهى ا هللَُّ عليه وسلم إيّاك.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 181, '(7) الصافات- .741', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 182, '(2) أخرجه البخاري في الأطعمة، ومسلم في الأشربة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 183, 'وَفِي «الْغَيْلَانِيهاتِ» : مِنْ حَدِيثِ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عائشة رَضِيَ ا هللَُّ عَنْـهَا قَالَتْ : قَالَ لِ رسول الله صلى الله عَلَيْهِ وَسَلهمَ: «يَا عائشة إِذَا طَبَخْتُمْ قِدْرًا، فَأَكْثِرُوا فِيهَا مِنَ الدُّهباءِ، فَإِنهـهَا تَشُدُّ قَـلْبَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 184, 'الَْحزِينِ» .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 185, 'الْيَـقْطِيُن: بَارِدٌ رَطْبٌ ، يَـغْذُو غِذَاءً يَسِيًرا، وَهُوَ سَرِيعُ الِانِْدَْارِ، وَإِنْ لََْ يَـفْسُدْ قَـبْلَ الَْهضْمِ تَـوَلهدَ مِنْهُ خَلْطٌ مَمُُْودٌ، وَمِنْ خَاصِّ يهتِهِ أَنههُ يَـتَـوَلهدُ مِنْهُ خَلْطٌ مَمُُْودٌ مُاََنِسٌ لِمَا يَصْحَبُهُ، فَإِنْ أُكِلَ بِالَْخرْدَلِ، تَـوَلهدَ مِنْهُ خِلْطٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 186, 'حِرِّيفٌ ، وَبِالْمِلْحِ خِلْطٌ مَالِحٌ، وَمَعَ الْقَابِضِ قَابِضٌ ، وَإِنْ طُبِخَ بِالسهفَرْجَلِ غَذَا الْبَدَنَ غِذَاءً جَيِّدًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 187, 'وَهُوَ لَطِيفٌ مَائِيٌّ يَـغْذُو غِذَاءً رَطْبًا بَـلْغَمِيًّا، وَيَـنْـفَعُ الْمَحْ رُورِينَ، وَلَا يُلَائِمُ الْمَبْـرُودِينَ، وَمَنِ الْغَالِبُ عَلَيْهِمُ الْبَـلْغَمُ، وَمَاؤُهُ يَـقْطَعُ الْعَطَشَ ، وَيُذْهِبُ الصُّدَاعَ الَْحاره إِذَا شُرِبَ أَوْ غُسِلَ بِهِ الهرأْسُ ، وَهُوَ مُلَيٌِّن لِلْبَطْنِ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 188, 'كَيْفَ اسْتُـعْمِلَ، وَلَا يَـتَدَاوَى الْمَحْ رُورُونَ بِِمثْلِهِ، وَلَا أَعْجَلَ مِنْهُ نَـفْعًا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 189, 'وَمِنْ مَنَافِعِهِ: أَنههُ إِذَا لُطِّخَ بِعَجِيٍن، وَشُوِيَ فِي الْفُرْنِ أَوِ التهـنُّورِ، وَاسْتُخْرِجَ مَاؤُهُ وَشُرِبَ بِبَـعْضِ الَْأشْرِبَةِ اللهطِيفَةِ سَكهنَ حَرَارَةَ الُْحمهى الْمُلْتَهِبَةَ، وَقَطَعَ الْعَطَشَ ، وَغَذهى غِذَاءً حَسَنًا، وَإِذَا شُرِبَ بِتَـرَنْبَِْيَن وَسَفَرْجَلٍ مُرَبًَّ أَسْهَلَ صَفْرَاءَ مَضَُْةً.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 190, 'وَإِذَا طُبِخَ الْقَرْعُ، وَشُرِبَ مَاؤُهُ بِشَيْ ءٍ مِنْ عَسَلٍ، وَشَيْ ءٍ مِنْ نَطْرُونٍ، أَحْدَرَ بَـلْغَمًا وَمِهرةً مَعًا، وَإِذَا دُقه', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 191, 'وَعُمِلَ مِنْهُ ضِمَادٌ عَلَى الْيَافُوخِ، نَـفَعَ مِنَ الَْأوْرَامِ الَْحارهةِ فِي الدِّمَاغِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 192, 'وَإِذَا عُصِ رَتْ جُرَادَتُهُ، وَخُلِطَ مَاؤُهَا بِدُهْنِ الْوَرْدِ، وَقُطِرَ مِنْـهَا فِي الُْأذُنِ، نَـفَعَتْ مِنَ الَْأوْرَامِ الَْحارهةِ، وَجُرَادَتُهُ نَافِعَةٌ مِنْ أَوْرَامِ الْعَيِْن الَْحارهةِ، وَمِنَ النِّقْرِسِ  الَْحارِّ، وَهُوَ شَدِيدُ النهـفْعِ لَِأصْحَابِ الَْأمْزِجَةِ الَْحارهةِ وَالْمَحْمُومِيَن، وَمَتَى صَادَفَ فِي الْمَعِدَةِ خَلْطًا رَدِيئًا، اسْتَحَالَ إِلَى طَبِيعَتِهِ، وَفَسَدَ، وَوَلهدَ فِي الْبَدَنِ خَلْطًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 193, 'رَدِيئًا، وَدَفْعُ مَضَ هرتِهِ بِالَْخلِّ وَالْمُرِّيِّ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 194, 'رَسُولَ ا هلِلَّ صَلهى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 195, 'وَبِالُْجمْلَةِ فَـهُوَ مِنْ أَلْطَفِ الَْأغْذِيَةِ، وَأَسْرَعِهَا انْفِعَالًا، وَيُذْكَرُ عَنْ أنس رَضِيَ ا هللَُّ عَنْهُ أَنه الله عليه وسلم كان يكثر من أكله.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل [في المحاذير]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَقَدْ رَأَيْتُ أَنه أَخْتِمَ الْكَلَامَ فِي هَذَا الْبَابِ بِفَصْلٍ مُْختَصَرٍ عَظِيمِ النهـفْعِ فِي الْمَحَاذِرِ، وَالْوَصَايَا الْكُلُّيهةِ النهافِعَةِ لِتَتِمه مَنْـفَعَةُ الْكِتَابِ، وَرَأَيْتُ لابن ماسويه فَصْلًا فِي كِتَابِ «الْمَحَاذِيرِ» نَـقَلْتُهُ بِلَفْظِهِ، قَالَ: مَنْ أَكَلَ الْبَصَلَ أَرْبَعِيَن يَـوْمًا وَكَلِفَ ، فَلَا يَـلُومَنه إِهلا نَـفْسَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَمَنِ افْـتَصَدَ، فَأَكَلَ مَالًِحا فَأَصَابَهُ بَـهَقٌ أَوْ جَرَبٌ ، فَلَا يَـلُومَنه إِهلا نَـفْسَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَمَنْ جَعَََ فِي مَعِدَتِهِ الْبَـيْضَ وَالسهمَكَ ، فَأَصَابَهُ فَالِجٌ أَوْ لَقْوَةٌ، فَلَا يَـلُومَنه إِهلا نَـفْسَهُ. وَمَنْ دَخَلَ الَْحمهامَ وَهُوَ ممتلىء، فَأَصَابَهُ فَالِجٌ، فَلَا يَـلُومَنه إِهلا نَـفْسَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَمَنْ جَعَََ فِي مَعِدَتِهِ اللهبََن وَالسهمَكَ ، فَأَصَابَهُ جُذَامٌ، أَوْ بَـرَصٌ أَوْ نِقْرِسٌ ، فَلَا يَـلُومَنه إِهلا نَـفْسَهُ. وَمَنْ جَعَََ فِي مَعِدَتِهِ اللهبََن وَالنهبِيذَ، فَأَصَابَهُ بَـرَصٌ أَوْ نِقْرِسٌ ، فَلَا يَـلُومَنه إِهلا نفسه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'ومن احتلم، فلم يغتسل حتى وطىء أَهْلَهُ، فَـوَلَدَتْ مَنَُْونًا أَوْ مَُخبهلًا، فَلَا يَـلُومَنه إِهلا نَـفْسَهُ. وَمَنْ أَكَلَ بَـيْضًا مَسْلُوقًا بَارِدًا، وَامْتَلََِ مِنْهُ، فَأَصَابَهُ رَبْـوٌ، فَلَا يَـلُومَنه إِهلا نَـفْسَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَمَنْ جَامَعَ، فَـلَمْ يَصْبَِْ حَ هتى يَـفْرُغَ، فَأَصَابَهُ حَصَاةٌ، فَلَا يَـلُومَنه إِهلا نَـفْسَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَمَنْ نَظَرَ فِي الْمِرْآةِ لَيْلًا، فَأَصَابَهُ لَقْوَةٌ، أَوْ أَصَابَهُ دَاءٌ، فَلَا يَـلُومَنه إِهلا نَـفْسَهُ. فصل [في الحذر من أكل البيض والسمك معا]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وقال ابن يختيشوع: احْذَرْ أَنْ تَمََْعَ الْبَـيْضَ وَالسهمَكَ ، فَإِنهـهُمَا يُورِثَنَِ الْقُولَنْجَ، وَالْبَـوَاسِيَر، وَوَجَعَ الَْأضْرَاسِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَإِدَامَةُ أَكْلِ الْبَـيْضِ يُـوَلِّدُ الْكَلَفَ فِي الْوَجْهِ وَأَكْلُ الْمُلُوحَةِ وَالسهمَكِ الْمَالِحِ وَالِافْتِصَادُ بَـعْدَ الَْحمهامِ يُـوَلِّدُ الْبَـهَقَ وَالَْجرَبَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'إِدَامَةُ أَكْلِكُلَى الْغَنَمِ يَـعْقِرُ الْمَثَانَةَ. الِاغْتِسَالُ بِالْمَاءِ الْبَارِدِ بَـعْدَ أَكْلِ السهمَكِ الطهرِيِّ يُـوَلِّدُ الْفَالِجَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَطْ ءُ الْمَرْأَةِ الَْحائِضِ يُـوَلِّدُ الُْجذَامَ، الِْجمَاعُ مِنْ غَيِْر أَنْ يُـهْرِيقَ الْمَاءَ عَقِيبَهُ يُـوَلِّدُ الَْحصَاةَ، طُولُ الْمُكْثِ فِي الْمَخْ رَجِ يُـوَلِّدُ الدهاءَ الدهوِيه.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'قَالَ أبقراط: الِْإقْلَالُ مِنَ الضهارِّ خَيْـرٌ مِنَ الِْإكْ ثَارِ مِنَ النهافِعِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَقَالَ: اسْتَدِيُموا الصِّحهةَ بِتَـرْكِ التهكَاسُلِ عَنِ التهـعَبِ، وَبِتَـرْكِ الِامْتِلَاءِ مِنَ الطهعَامِ وَالشهرَابِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'وَقَالَ بَـعْضُ الُْحكَمَاءِ: مَنْ أَرَادَ الصِّحهةَ، فَـلْيُجَوِّدِ الْغِذَاءَ، وَلْيَأْكُلْ عَلَى نَـقَاءٍ، وَلْيَشْرَبْ عَلَى ظَمَأٍ، وَلْيُـقْلِلْ مِنْ شُرْبِ الْمَاءِ، وَيَـتَمَدهدْ بَـعْدَ الْغَدَاءِ، وَيَـتَمَشه بَـعْدَ الْعِشَاءِ، وَلَا يَـنَمْ حَ هتى يَـعْرِضَ نَـفْسَهُ عَلَى الَْخلَاءِ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَلْيَحْذَرْ دُخُولَ الَْحمهامِ عَقِيبَ الِامْتِلَاءِ، وَمَ هرةً فِي الصهيْفِ خَيْـرٌ مِنْ عَشْرٍ فِي الشِّ تَاءِ، وَأَكْلُ الْقَدِيدِ الْيَابِسِ بِاللهيْلِ مُعِيٌن عَلَى الْفَنَاءِ، وَمُاََمَعَةُ الْعَجَائِزِ تُـهْرِمُ أَعْمَارَ الَْأحْ يَاءِ، وَتُسْقِمُ أَبْدَانَ الَْأصِحهاءِ، وَيُـرْوَى هَذَا عَنْ علي رَضِيَ ا هللَُّ عَنْهُ، وَلَا يَصِحُّ عَنْهُ، وَإِهنَما بَـعْضُهُ مِنْ كَلَامِ الحارث بن كلدة طَبِيبِ الْعَرَبِ، وَكَلَامِ غَيِْرهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَقَالَ الحارث: مَنْ سَ هرهُ الْبَـقَاءُ- وَلَا بَـقَاءَ- فليباكر الغداء، وليعجل العشاء، وليخفف الرّداء، وليقل غَشَيَانَ النِّسَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'وَقَالَ الحارث: أَرْبَـعَةُ أَشْيَاءَ تَـهْدِمُ الْبَدَنَ: الِْجمَاعُ عَلَى الْبِطْنَةِ، وَدُخُولُ الَْحمهامِ عَلَى الِامْتِلَاءِ، وَأَكْلُ الْقَدِيدِ، وَجِاََعُ الْعَجُوزِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَلَمها احْتُضِرَ الحارث اجْتَمَعَ إِلَيْهِ النهاسُ ، فَـقَالُوا: مُرْنَا بَِأمْرٍ نَـنْـتَهِي إِلَيْهِ مِنْ بَـعْدِكَ، فَـقَالَ: لَا تَـتَـزَهوجُوا مِنَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'النِّسَاءِ إِهلا شَابهةً، وَلَا تَكَُْلُوا مِنَ الْفَاكِهَةِ إِهلا فِي أَوَانِ نُضْجِهَا، وَلَا يَـتَـعَالََجنه أَحَدُكُمْ مَا احْتَمَلَ بَدَنُهُ الدهاءَ، وَعَلَيْكُمْ بِتَـنْظِيفِ الْمَعِدَةِ فِي كُلِّ شَهْرٍ، فَإِنهـهَا مُذِيبَةٌ لِلْبَـلْغَمِ، مهلكة للمرة، منبتة للحم، وإذا تغذّى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, 'أَحَدُكُمْ، فَـلْيَـنَمْ عَلَى إِثْرِ غَدَائِهِ سَاعَةً، وَإِذَا تَـعَشهى فَـلْيَمْشِ أَرْبَعِيَن خُطْوَةً.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'وَقَالَ بَـعْضُ الْمُلُوكِ لِطَبِيبِهِ: لَعَلهكَ لَا تَـبْـقَى لِِ، فَصِفْ لِِ صِفَةً آخُذُهَا عَنْكُ ، فَـقَالَ: لَا تَـنْكِحْ إِهلا شَابهةً، وَلَا تَكَُْلْ مِنَ اللهحْمِ إِهلا فَتِيًّا، وَلَا تَشْرَبِ الدهوَاءَ إِهلا مِنْ عِلهةٍ، وَلَا تَكَُْلِ الْفَاكِهَةَ إِهلا فِي نُضْجِهَا، وَأَجِدْ مَضْغَ الطهعَامِ. وَإِذَا أَكَلْتَ نَـهَارًا فَلَا بَْأسَ أَنْ تَـنَامَ، وَإِذَا أَكَلْتَ لَيْلًا فَلَا تَـنَمْ حَ هتى تَشَِْيَ وَلَوْ خَْمسِيَن خُطْوَةً، وَلَا تَكَُْلَنه حَ هتى تَوَُعَ، وَلَا تَـتَكَارَهَنه عَلَى الِْجمَاعِ ، وَلَا تَبَِْسِ الْبَـوْلَ، وَخُذْ مِنَ الَْحمهامِ قَـبْلَ أَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'خََُْذَ مِنْكَ ، وَلَا تَكَُْلَنه طَعَامًا، وَفِي مَعِدَتِكَ طَعَامٌ، وَإِهياكَ أَنْ تَكَُْلَ مَا تَـعْجِزُ أَسْنَانُكَ عَنْ مصنفه، فَـتَـعْجِزَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 24, 'مَعِدَتُكَ عَنْ هَضْمِهِ، وَعَلَيْكَ فِي كُلِّ أُسْبُوعٍ بِقَيْـئَةٍ تُـنَـقِّي جِسْمَكَ ، وَنِعْمَ الْكَنْـزُ الدهمُ فِي جَسَدِكَ، فَلَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 25, 'مِنَ الَْأطْبَاقِ مَا لَا تَصِلُ الَْأدْوِيَةُ إِلَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 26, 'تُْخرِجْ هُ إِهلا عِنْدَ الَْحاجَةِ إِلَيْهِ، وَعَلَيْكَ بِدُخُولِ الَْحمهامِ، فَإِنههُ يُْخرجُِ إِخْ رَاجِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 27, 'وَقَالَ الشهافِعِيُّ:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 28, 'أَرْبَـعَةٌ تُـقَوِّي الْبَدَنَ: أَكْلُ اللهحْمِ، وَشَمُّ الطِّيبِ، وَكَثْـرَةُ الْغُسْلِ مِنْ غَيِْر جِاََعٍ ، وَلُبْسُ الْكَتهانِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 29, 'وَأَرْبَـعَةٌ تُوهِنُ الْبَدَنَ: كَثْـرَةُ الِْجمَاعِ ، وَكَثْـرَةُ الْهمَِّ، وَكَثْـرَةُ شُرْبِ الْمَاءِ عَلَى الرِّيقِ، وَكَثْـرَةُ أَكْلِ الَْحامِضِ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 30, 'وَأَرْبَـعَةٌ تُـقَوِّي الْبَصَرَ: الُْجلُوسُ حِيَالَ الْكَعْبَةِ، وَالْكُحْلُ عند النوم، والنظر الى الحقزة، وَتَـنْظِيفُ الْمَجْلِسِ . وَأَرْبَـعَةٌ تُوهِنُ الْبَصَرَ: النهظَرُ إِلَى الْقَذَرِ، وَإِلَى الْمَصْلُوبِ، وَإِلَى فَـرْجِ الْمَرْأَةِ، وَالْقُعُودُ مُسْتَدْبِرَ الْقِبْـلَةِ. وَأَرْبَـعَةٌ تَزِيدُ فِي الِْجمَاعِ : أَكْلُ الْعَصَافِيِر، وَالِْإطْرِيفِلِ، وَالْفُسْتُقِ، وَالَْخرُّوبِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 31, 'وَأَرْبَـعَةٌ تَزِيدُ فِي الْعَقْلِ: تَـرْكُ الْفُضُولِ مِنَ الْكَلَامِ، وَالسِّ وَاكُ، وَمُاََلَسَةُ الصهالِِحيَن، وَمُاََلَسَةُ الْعُلَمَاءِ ]7[ . وَقَالَ أفلاطون: خَْمسٌ يُذِبْنَ الْبَدَنَ وَرُهبَما قَـتَـلْنَ قِصَرُ ذَاتِ الْيَدِ، وَفِرَاقُ الَْأحِبهةِ، وَتَرََُّعُ الْمَغَايِظِ، وَرَدِّ النُّصْحِ، وَضَحِكُ ذَوِي الَْجهْلِ بِالْعُقَلَاءِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 32, 'وَقَالَ طَبِيبُ الْمَأْمُونِ: عَلَيْكَ خِِصَِالٍ من حفظها، فهو جدير ألايعتل إِهلا عِلهةَ الْمَوْتِ: لَا تَكَُْلْ طَعَامًا وَفِي مَعِدَتِكَ طَعَامٌ، وَإِهياكَ أَنْ تَكَُْلَ طَعَامًا يُـتْعِبُ أَضْرَاسَكَ فِي مَضْغِهِ، فَـتَـعْجِزَ مَعِدَتُكَ عَنْ هَضْمِهِ، وإياك وكثرة الجماع، فإنه يطفى نُورَ الَْحيَاةِ، وَإِهياكَ وَمُاََمَعَةَ الْعَجُوزِ، فَإِنههُ يُورِثُ مَوْتَ الْفَجْأَةِ، وَإِهياكَ وَالْفَصْدَ إِهلا عِنْدَ الَْحاجَةِ إِلَيْهِ، وَعَلَيْكَ بِالْقَيْ ءِ فِي الصهيْفِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 33, 'وَمِنْ جَوَامِعِ كَلِمَاتِ أبقراط قَـوْلُهُ: كُلُّ كَثِيٍر فَـهُوَ مُعَادٍ للطبيعة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 34, 'وقيل لجالينوس: مالك لَا تَرََْضُ ؟ فَـقَالَ: لَِأنِّي لََْ أَجْعََْ بَـيَْن طَعَامَيِْن رَدِيئَـيِْن، وَلََْ أُدْخِلْ طَعَامًا عَلَى طَعَامٍ، وَلََْ أَحْبِسْ فِي الْمَعِدَةِ طَعَامًا تَذََهيْتُ بِهِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل [في ما يمرض الجسم]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَأَرْبَـعَةُ أَشْيَاءَ تُرَِْضُ الِْجسْمَ: الْكَلَامُ الْكَثِيُر، وَالنهـوْمُ الْكَثِيُر، وَالَْأكْلُ الْكَثِيُر، وَالِْجمَاعُ الْكَثِيُر. فَالْكَلَامُ الْكَثِير يُـقَلِّلُ مُخه الدِّمَاغِ وَيُضْعِفُهُ، وَيُـعَجِّ لُ الشهيْبَ .', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَالنهـوْمُ الْكَثِيُر يُصَفِّرُ الْوَجْ هَ، وَيُـعْمِي الْقَلْبَ ، وَيُـهَيِّجُ الْعَيَْن، وَيُكْسِلُ عَنِ الْعَمَلِ، وَيُـوَلِّدُ الرُّطُوبَاتِ فِي الْبَدَنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَالَْأكْلُ الْكَثِيُر يُـفْسِدُ فَمَ الْمَعِدَةِ، وَيُضْعِفُ الِْجسْمَ، وَيُـوَلِّدُ الرِّيَاحَ الْغَلِيظَةَ، وَالَْأدْوَاءَ الْعَسِرَةَ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَالِْجمَاعُ الْكَثِيُر: يَـهُدُّ الْبَدَنَ، وَيُضْعِفُ الْقُوَى، وَيَُجفِّفُ  رُطُوبَاتِ الْبَدَنِ، وَيُـرْخِي الْعَصَبَ ، وَيُورِثُ السهدَدَ، وَيَـعُمُّ ضَرَرُهُ جَِيَعَ الْبَدَنِ، وَيَُخصُّ الدِّمَاغَ لِكَثْـرَةِ مَا يَـتَحَلهلُ بِهِ مِنَ الرُّوحِ النهـفْسَانِِّي، وَإِضْعَافُهُ أَكْ ثَـرُ مِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'إِضْعَافِ جَِيَعِ الْمُسْتَـفْرِغَاتِ، وَيَسْتَـفْرغُِ مِنْ جَوْهَرِ الرُّوحِ شَيْـئًا كَثِيًرا.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَأَنْـفَعَ مَا يَكُونُ إِذَا صَادَفَ شَهْوَةً صَادِقَةً مِنْ صُورَةٍ جَِيَلَةٍ حَدِيثَةِ السِّ نِّ حَلَالًا مَعَ سِنِّ الشُّبُوبِيهةِ، وَحَرَارَةِ الْمِزَاجِ وَرُطُوبَتِهِ، وَبُـعْدِ الْعَهْدِ بِهِ وَخَلَاءِ الْقَلْبِ مِنَ الشهوَاغِلِ النهـفْسَانِيهةِ، وَلََْ يُـفَرِّطْ فِيهِ، وَلََْ يُـقَارِنْهُ مَا يَـنْـبَغِي تَـرْكُهُ مَعَهُ مِنِ امْتِلَاءٍ مُفْرِطٍ، أَوْ خَوَاءٍ، أَوِ اسْتِفْرَاغٍ ، أَوْ رِيَاضَةٍ تَامهةٍ، أَوْ حَرٍّ مُفْرِطٍ، أَوْ بَـرْدٍ مُفْرِطٍ، فَإِذَا رَاعَى فِيهِ هَذِهِ الُْأمُورَ الْعَشْرَةَ، انْـتَـفَعَ بِهِ جِدًّا، وَأَيُّـهَا فَـقَدَ فَـقَدْ حَصَلَ لَهُ مِنَ الضهرَرِ بَِحسَبِهِ، وَإِنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'فُقِدَتْ كُلُّهَا أَوْ أَكْ ثَـرُهَا، فَـهُوَ الَْهلَاكُ المعجلّ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فصل [في الحمية المفرطة]', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'وَالِْحمْيَةُ الْمُفْرِطَةُ فِي الصِّحهةِ. كَالتهخْلِيطِ فِي الْمَرَضِ ، وَالِْحمْيَةُ الْمُعْتَدِلَةُ نَافِعَةٌ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَقَالَ جالينوس لَِأصْحَابِهِ: اجْ تَنِبُوا ثَلَاثًَ، وَعَلَيْكُمْ بَِأرْبَعٍ، وَلَا حَاجَةَ بِكُمْ إِلَى طَبِيبٍ: اجْ تَنِبُوا الْغُبَارَ، والدخان، والنّتُ، وعليكم بِالدهسَمِ، وَالطِّيبِ، وَالَْحلْوَى، وَالَْحمهامِ، وَلَا تَكَُْلُوا فَـوْقَ شِبَعِكُمْ، وَلَا تَـتَخَلهلُوا بِالْبَاذَرُوجِ، وَالهريَْحانِ، وَلَا تَكَُْلُوا الَْجوْزَ عِنْدَ الْمَسَاءِ، وَلَا يَـنَمْ مَنْ بِهِ زكُْمَةٌ عَلَى قَـفَاهُ، وَلَا كََُْلْ مَنْ بِهِ غَمٌّ حَامِضًا، وَلَا يُسْرعِِ الْمَشْيَ مَنِ افْـتَصَدَ، فَإِنههُ مَُخاطَرَةُ الْمَوْتِ، وَلَا يَـتَـقَيهأْ مَنْ تُـؤْلِمُهُ عَيْـنُهُ، وَلَا تَكَُْلُوا فِي الصهيْفِ لَْحمًا كَثِيًرا، وَلَا يَـنَمْ صَاحِبُ الُْحمهى الْبَارِدَةِ فِي الشهمْسِ ، وَلَا تَـقْرَبُوا الْبَاذِنْاَْنَ الْعَتِيقَ الْمُبَـهزرَ، وَمَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'شَرِبَ كُله يَـوْمٍ فِي الشِّ تَاءِ قَدَحًا مِنْ مَاءٍ حَارٍّ، أَمِنَ مِنَ الَْأعْلَالِ، وَمَنْ دَلَكَ جِسْمَهُ فِي الَْحمهامِ بِقُشُورِ الرُّمهانِ أَمِنَ مِنَ الَْجرَبِ وَالَْحكهةِ، وَمَنْ أَكَلَ خَْمسَ سَوْسَنَاتٍ مَعَ قَلِيلِ مَصْطَكًى رُومِيٍّ، وَعُودٍ خَامٍ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَمِسْكٍ ، بَقِيَ طُولَ عُمُرِهِ لَا تَضْعُفَ مَعِدَتُهُ وَلَا تَـفْسُدُ، وَمَنْ أَكَلَ بِزْرَ الْبِطِّيخِ مَعَ السُّكهرِ، نَظهفَ الَْحصَى مِنْ مَعِدَتِهِ، وَزَالَتْ عَنْهُ حُرْقَةُ الْبَـوْلِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ [في ما يهدم البدن]:', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'أَرْبَـعَةٌ تَـهْدِمُ الْبَدَنَ: الَْهمُّ، وَالُْحزْنُ، وَالُْجوعُ، وَالسههَرُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'وَأَرْبَـعَةٌ تُـفْرِحُ: النهظَرُ إِلَى الُْخضْرَةِ، وَإِلَى الْمَاءِ الَْجارِي، وَالْمَحْ بُوبِ، وَالثِّمَارِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَأَرْبَـعَةٌ تُظْلِمُ الْبَصَرَ: الْمَشْيُ حَافِيًا، وَالتهصَبُّحُ وَالتهمَسِّ ي بِوَجْهِ الْبَغِيضِ وَالثهقِيلِ، وَالْعَدُوِّ، وَكَثْـرَةُ الْبُكَاءِ، وَكَثْـرَةُ النهظَرِ فِي الَْخطِّ الدهقِيقِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'وَأَرْبَـعَةٌ تُـقَوِّي الِْجسْمَ: لُبْسُ الثهـوْبِ النهاعِمِ، وَدُخُولُ الحمام المعتدل، وأكل الطعام الحلو الدسم، وَشَمُّ الهروَائِحِ الطهيِّبَةِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَأَرْبَـعَةٌ تُـيَـبِّسُ الْوَجْ هَ، وَتُذْهِبُ مَاءَهُ وَبَـهْجَتَهُ وَطَلَاوَتَهُ: الْكَذِبُ ، وَالْوَقَاحَةُ، وَكَثْـرَةُ السُّؤَالِ عَنْ غَيِْر عِلْمٍ، وَكَثْـرَةُ الْفُجُورِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'وَأَرْبَـعَةٌ تَزِيدُ فِي مَاءِ الْوَجْهِ وَبَـهْجَتِهِ: الْمُرُوءَةُ، وَالْوَفَاءُ، وَالْكَرَمُ، وَالتهـقْوَى. وَأَرْبَـعَةٌ تَلَِْبُ الْبَـغْضَاءَ وَالْمَقْتَ : الْكِبْـرُ، وَالَْحسَدُ، والكذب، والنميمة.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَأَرْبَـعَةٌ تَلَِْبُ الرِّزْقَ : قِيَامُ اللهيْلِ، وَكَثْـرَةُ الِاسْتِغْفَارِ بِالَْأسْحَارِ، وَتَـعَاهُدُ الصهدَقَةِ، وَالذِّكْ رُ أَهولَ النهـهَارِ وَآخِرَهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَأَرْبَـعَةٌ تَنََْعُ الرِّزْقَ : نَـوْمُ الصُّبْحَةِ، وَقِلهةُ الصهلَاةِ، وَالْكَسَلُ، وَالِْخيَانَةُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'وَأَرْبَـعَةٌ تَضُرُّ بِالْفَهْمِ وَالذِّهْنِ: إِدْمَانُ أَكْلِ الَْحامِضِ وَالْفَوَاكِهِ، وَالنهـوْمُ عَلَى الْقَفَا، وَالْهمَُّ، وَالْغَمُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَأَرْبَـعَةٌ تَزِيدُ فِي الْفَهْمِ: فَـرَاغُ الْقَلْبِ، وَقِلهةُ التهمَلِّي مِنَ الطهعَامِ وَالشهرَابِ، وَحُسْنُ تَدْبِيِر الْغِذَاءِ بِالَْأشْيَاءِ الُْحلْوَةِ وَالدهسَِمةِ، وَإِخْرَاجُ الْفَضَلَاتِ الْمُثْقِلَةِ لِلْبَدَنِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'وَمِمها يَضُرُّ بِالْعَقْلِ: إِدْمَانُ أَكْلِ الْبَصَلِ، وَالْبَاقِهلا، وَالهزيْـتُونِ، وَالْبَاذِنْاَْنِ، وَكَثْـرَةُ الِْجمَاعِ ، وَالْوَحْدَةُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'وَالَْأفْكَارُ، وَالسُّكْرُ، وَكَثْـرَةُ الضهحِكِ ، وَالْغَمُّ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'قَالَ بَـعْضُ أَهْلِ النهظَرِ: قُطِعْتُ فِي ثَلَاثِ مَاََلِسَ ، فَـلَمْ أَجِدْ لِذَلِكَ عِلهةً إِهلا أَنِّي أَكْ ثَـرْتُ مِنْ أَكْلِ الْبَاذِنْاَْنِ فِي أَحَدِ تِلْكَ الَْأهيامِ، وَمِنَ الهزيْـتُونِ فِي الْآخَرِ، وَمِنَ الْبَاقِهلا فِي الثهالِثِ.', 'unverified');
  INSERT INTO kb_sections (id, source_id, title, sequence_num)
  INSERT INTO kb_chunks (id, source_id, section_id, sequence_num, raw_arabic_text, status) VALUES
  (gen_random_uuid(), v_source_id, v_section_id, 1, 'فَصْلٌ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 2, 'قد أتينا على جلَة مِنْ أَجْزَاءِ الطِّبِّ الْعِلْمِيِّ وَالْعَمَلِيِّ، لَعَله النهاظِرَ لَا يَظْفَرُ بِكَثِيٍر مِنْـهَا إِهلا فِي هَذَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 3, 'الكتاب، وأريناك قرب ما بينهما وَبَـيَْن الشهرِيعَةِ، وَأَنه الطِّبه النهـبَوِيه نِسْبَةُ طِبِّ الطهبَائِعِيِّيَن إِلَيْهِ أَقَلُّ مِنْ نِسْبَةِ طِبِّ الْعَجَائِزِ إِلَى طِبِّهِمْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 4, 'وَالَْأمْرُ فَـوْقَ مَا ذكََرْنَاهُ، وَأَعْظَمُ مِمها وَصَفْنَاهُ بِكَثِيٍر، وَلَكِنْ فِيمَا ذكََرْنَاهُ تَـنْبِيهٌ بِالْيَسِيِر عَلَى مَا وَرَاءَهُ، وَمَنْ لََْ يَـرْزُقْهُ ا هللَُّ بَصِيَرةً عَلَى التهـفْصِيلِ، فَـلْيَـعْلَمْ مَا بَـيَْن الْقُهوةِ الْمُؤَيهدَةِ بِالْوَحْيِ مِنْ عِنْدِ ا هلِلَّ، وَالْعُلُومِ الهتِي رَزَقَـهَا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 5, 'ا هللَُّ الَْأنْبِيَاءَ، وَالْعُقُولِ وَالْبَصَائِرِ الهتِي مَنَحَهُمُ ا هللَُّ إِهياهَا، وَبَـيَْن مَا عِنْدَ غَيِْرهِمْ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 6, 'وَلَعَله قَائِلًا يَـقُولُ: مَا لَِهدْيِ الهرسُولِ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، وَمَا لَِهذَا الْبَابِ، وَذِكْرِ قُـوَى الَْأدْوِيَةِ، وَقَـوَانِيِن', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 7, 'الْعِلَاجِ، وَتَدْبِيِر أَمْرِ الصِّحهةِ؟', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 8, 'وَهَذَا مِنْ تَـقْصِيِر هَذَا الْقَائِلِ فِي فَـهْمِ مَا جَاءَ بِهِ الهرسُولُ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ، فَإِنه هَذَا وَأَضْعَافَهُ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 9, 'وَأَضْعَافَ أَضْعَافِهِ مِنْ فَـهْمِ بَـعْضِ مَا جَاءَ بِهِ، وَإِرْشَادِهِ إِلَيْهِ، وَدِلَالَتِهِ عَلَيْهِ، وَحُسْنِ الْفَهْمِ عَنِ ا هلِلَّ وَرَسُولِهِ مَنٌّ يَُمنُّ ا هللَُّ بِهِ عَلَى مَنْ يَشَاءُ من عباده.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 10, 'فَـقَدْ أَوْجَدْنَاكَ أُصُولَ الطِّبِّ الثهلَاثَةِ فِي الْقُرْآنِ، وَكَيْفَ تُـنْكِرُ أَنْ تَكُونَ شَرِيعَةُ الْمَبْـعُوثِ بِصَلَاحِ الدُّنْـيَا وَالْآخِرَةِ مُشْتَمِلَةً عَلَى صَلَاحِ الَْأبْدَانِ، كَاشْتِمَالَِها عَلَى صَلَاحِ الْقُلُوبِ، وَأَنهـهَا مُرْشِدَةٌ إِلَى حِفْظِ صِ حهتِهَا، وَدَفْعِ آفَاتَِها بِطُرُقٍ كُلِّيهةٍ قَدْ وُكِلَ تَـفْصِيلُهَا إِلَى الْعَقْلِ الصهحِيحِ، وَالْفِطْرَةِ السهلِيمَةِ بِطَرِيقِ الْقِيَاسِ وَالتهـنْبِيهِ وَالِْإيَماءِ، كَمَا هُوَ فِي كَثِيٍر مِنْ مَسَائِلِ فُـرُوعِ الْفِقْهِ، وَلَا تَكُنْ مِمهنْ إِذَا جَهِلَ شَيْـئًا عَادَاهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 11, 'وَلَوْ رُزِقَ الْعَبْدُ تَضَلُّعًا مِنْ كِتَابِ ا هلِلَّ وَسُنهةِ رَسُولِهِ، وَفَـهْمًا تَامًّا فِي النُّصُوصِ وَلَوَازِمِهَا، لَاسْتَـغْنَى بِذَلِكَ عَنْ كُلِّ كَلَامٍ سِوَاهُ، وَلَاسْتَـنْـبَطَ جَِيَعَ الْعُلُومِ الصهحِيحَةِ مِنْهُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 12, 'فَمَدَارُ الْعُلُومِ كُلِّهَا عَلَى مَعْرِفَةِ ا هلِلَّ وَأَمْرِهِ وَخَلْقِهِ، وَذَلِكَ مُسَلهمٌ إِلَى الرُّسُلِ صَلَوَاتُ ا هلِلَّ عَلَيْهِمْ وَسَلَامُهُ،', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 13, 'فَـهُمْ أَعْلَمُ الَْخلْقِ بِا هلِلَّ وَأَمْرِهِ وَخَلْقِهِ وَحِكْمَتِهِ فِي خَلْقِهِ وَأَمْرِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 14, 'وَطِبُّ أَتْـبَاعِهِمْ: أَصَحُّ وَأَنْـفَعُ مِنْ طِبِّ غَيِْرهِمْ. وَطِبُّ أَتْـبَاعِ خَاتَهَِِمْ وَسَيِّدِهِمْ وَإِمَامِهِمْ مُمَُهدِ بْنِ عَبْدِ ا هلِلَّ صَلَوَاتُ ا هلِلَّ وَسَلَامُهُ عَلَيْهِ وَعَلَيْهِمْ: أَكْمَلُ الطِّبِّ وَأَصَحُّهُ وَأَنْـفَعُهُ، وَلَا يَـعْرِفُ هَذَا إِهلا مَنْ عَرَفَ طِبه النهاسِ سِوَاهُمْ وَطِبهـهُمْ، ُ مه وَازَنَ بَـيْـنَـهُمَا، فَحِينَئِذٍ يَظْهَرُ لَهُ التهـفَاوُتُ ، وَهُمْ أَصَحُّ الُْأمَمِ عُقُولًا وَفِطَرًا، وَأَعْظَمُهُمْ عِلْمًا، وَأَقْـرَبُـهُمْ فِي كُلِّ شَيْ ءٍ إِلَى الَْحقِّ لَِأنهـهُمْ خِيَرةُ ا هلِلَّ مِنَ الُْأمَمِ، كَمَا أَنه؟؟؟ رَسُولَهمُْ خِيَرتُهُ مِنَ الرُّسُلِ. وَالْعِلْمُ الهذِي وَهَبَـهُمْ إِهياهُ، وَالِْحلْمُ وَالِْحكْمَةُ أَمْرٌ لَا يُدَانِيهِمْ فِيهِ غَيْـرُهُمْ، وَقَدْ رَوَى الِْإمَامُ أَحْدَُْ فِي «مُسْنَدِهِ» : مِنْ حَدِيثِ بَـهْزِ بْنِ حَكِيمٍ، عَنْ أَبِيهِ، عَنْ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 15, 'جَدِّهِ رَضِيَ ا هللَُّ عَنْهُ، قَالَ: قَالَ رَسُولُ ا هلِلَّ صَلهى ا هللَُّ عَلَيْهِ وَسَلهمَ: «أَنْـتُمْ تُوفُونَ سَبْعِيَن أُمهةً أَنْـتُمْ خَيْـرُهَا وَأَكْ رَمُهَا عَلَى ا هلِلَّ» »7« فَظَهَرَ أَثَـرُ كَرَامَتِهَا عَلَى ا هلِلَّ سُبْحَانَهُ فِي عُلُومِهِمْ وَعُقُولِِهمْ، وَأَحْلَامِهِمْ وَفِطَرِهِمْ، وَهُمُ الهذِينَ عُرِضَتْ عَلَيْهِمْ عُلُومُ الُْأمَمِ قَـبْـلَهُمْ وَعُقُولُهمُْ، وَأَعْمَالُهمُْ وَدَرَجَاتُـهُمْ، فَازْدَادُوا بِذَلِكَ عِلْمًا', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 16, 'وَحِلْمًا وَعُقُولًا إِلَى مَا أَفَاضَ ا هللَُّ سُبْحَانَهُ وَتَـعَالَى عَلَيْهِمْ مِنْ عِلْمِهِ وَحِلْمِهِ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 17, 'وَلِذَلِكَ كَانَتِ الطهبِيعَةُ الدهمَوِيهةُ لَهمُْ، وَالصهفْرَاوِيهةُ لِلْيَـهُودِ، وَالْبَـلْغَمِيهةُ لِلنهصَارَى، وَلِذَلِكَ غَلَبَ عَلَى النهصَارَى', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 18, 'الْبَلَادَةُ، وَقِلهةُ الْفَهْمِ وَالْفِطْنَةِ، وَغَلَبَ عَلَى الْيَـهُودِ الحزن والهمّ وَالصهغَارُ، وَغَلَبَ عَلَى الْمُسْلِمِيَن الْعَقْلُ وَالشهجَاعَةُ وَالْفَهْمُ وَالنهجْدَةُ، وَالْفَرَحُ وَالسُّرُورُ.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 19, 'وَهَذِهِ أَسْرَارٌ وَحَقَائِقُ إِهنَما يَـعْرِفُ مِقْدَارَهَا مَنْ حَسُنَ فَـهْمُهُ، وَلَطُفَ ذِهْنُهُ، وَغَزُرَ عِلْمُهُ، وَعَرَفَ مَا عِنْدَ', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 20, 'النهاسِ وَبِا هلِلَّ التوفيق.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 21, '(7) أخرجه أحدْ والترمذي.', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 22, 'الفهرس', 'unverified'),
  (gen_random_uuid(), v_source_id, v_section_id, 23, 'الموضوع الصفحة المقدمة 5', 'unverified');
